#!/usr/bin/env python3
from __future__ import annotations
import argparse
import json
from pathlib import Path


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("repo_map")
    ap.add_argument("--changed", action="append", required=True)
    a = ap.parse_args()
    m = json.loads(Path(a.repo_map).read_text())
    changed = set(a.changed)
    impacted = set(changed)
    reasons = []
    mods = {Path(x).stem for x in changed}
    for imp in m.get("python_imports", []):
        if any(
            mod == imp.get("module", "").split(".")[0] or mod in imp.get("module", "")
            for mod in mods
        ):
            impacted.add(imp["file"])
            reasons.append(
                {
                    "file": imp["file"],
                    "reason": "imports changed module",
                    "evidence": imp,
                }
            )
    tests = [
        f["path"]
        for f in m.get("files", [])
        if "test" in f["path"].lower()
        and any(Path(c).stem in f["path"] for c in changed)
    ]
    print(
        json.dumps(
            {
                "changed": sorted(changed),
                "impacted": sorted(impacted),
                "candidate_tests": tests,
                "reasons": reasons,
                "unknowns": [
                    "Runtime reflection and external consumers are not statically resolved."
                ],
            },
            indent=2,
        )
    )


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
from __future__ import annotations
import argparse
import json
import os
from pathlib import Path


def load(p):
    if not p:
        return {}
    if p.endswith(".json"):
        return json.loads(Path(p).read_text())
    d = {}
    for line in Path(p).read_text().splitlines():
        if "=" in line and not line.lstrip().startswith("#"):
            k, v = line.split("=", 1)
            d[k.strip()] = v.strip()
    return d


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("key")
    ap.add_argument("--default")
    ap.add_argument("--config", action="append", default=[])
    ap.add_argument("--cli")
    a = ap.parse_args()
    chain = []
    val = a.default
    chain.append({"source": "default", "value": val})
    for f in a.config:
        d = load(f)
        if a.key in d:
            val = d[a.key]
            chain.append({"source": f, "value": val})
    if a.key in os.environ:
        val = os.environ[a.key]
        chain.append({"source": "environment", "value": val})
    if a.cli is not None:
        val = a.cli
        chain.append({"source": "cli", "value": val})
    print(
        json.dumps({"key": a.key, "resolved": val, "precedence_chain": chain}, indent=2)
    )


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
from __future__ import annotations
import argparse
import json
import subprocess
from pathlib import Path


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--diff")
    ap.add_argument("--allowed", action="append", default=[])
    ap.add_argument("--max-lines", type=int, default=500)
    a = ap.parse_args()
    diff = (
        Path(a.diff).read_text()
        if a.diff
        else subprocess.check_output(
            ["git", "diff", "--no-ext-diff"], text=True, timeout=30
        )
    )
    files = []
    changed = 0
    for line in diff.splitlines():
        if line.startswith("+++ b/"):
            files.append(line[6:])
        elif (line.startswith("+") or line.startswith("-")) and not line.startswith(
            ("+++", "---")
        ):
            changed += 1
    denied = [
        f for f in files if a.allowed and not any(Path(f).match(p) for p in a.allowed)
    ]
    ok = not denied and changed <= a.max_lines
    print(
        json.dumps(
            {
                "allowed": ok,
                "files": files,
                "denied_files": denied,
                "changed_lines": changed,
                "max_lines": a.max_lines,
            },
            indent=2,
        )
    )
    raise SystemExit(0 if ok else 4)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
from __future__ import annotations
import argparse
import ast
import hashlib
import json
from collections import Counter
from pathlib import Path

SKIP = {".git", "node_modules", ".venv", "venv", "dist", "build", "__pycache__"}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("root")
    ap.add_argument("--out")
    a = ap.parse_args()
    root = Path(a.root).resolve()
    files = []
    langs = Counter()
    symbols = []
    imports = []
    for p in sorted(root.rglob("*")):
        if not p.is_file() or any(x in SKIP for x in p.parts):
            continue
        rel = str(p.relative_to(root))
        ext = p.suffix.lower() or "[none]"
        langs[ext] += 1
        rec = {
            "path": rel,
            "bytes": p.stat().st_size,
            "sha256": hashlib.sha256(p.read_bytes()).hexdigest(),
        }
        files.append(rec)
        if p.suffix == ".py":
            try:
                t = ast.parse(p.read_text(encoding="utf-8"))
                for n in ast.walk(t):
                    if isinstance(
                        n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)
                    ):
                        symbols.append(
                            {
                                "file": rel,
                                "name": n.name,
                                "kind": type(n).__name__,
                                "line": n.lineno,
                            }
                        )
                    elif isinstance(n, (ast.Import, ast.ImportFrom)):
                        imports.append(
                            {
                                "file": rel,
                                "module": getattr(n, "module", None)
                                or ",".join(x.name for x in n.names),
                                "line": n.lineno,
                            }
                        )
            except Exception as e:
                rec["parse_error"] = str(e)
    out = {
        "root": str(root),
        "file_count": len(files),
        "languages": dict(langs),
        "files": files,
        "python_symbols": symbols,
        "python_imports": imports,
        "limitations": [
            "Dynamic dispatch and non-Python symbol extraction require language adapters."
        ],
    }
    s = json.dumps(out, indent=2, sort_keys=True) + "\n"
    Path(a.out).write_text(s) if a.out else print(s, end="")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
from __future__ import annotations
import argparse
import json
from pathlib import Path


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("events")
    ap.add_argument("--correlation", required=True)
    a = ap.parse_args()
    rows = []
    for line in Path(a.events).read_text().splitlines():
        try:
            e = json.loads(line)
            if a.correlation in json.dumps(e, sort_keys=True):
                rows.append(e)
        except (json.JSONDecodeError, TypeError):
            continue
    rows.sort(key=lambda x: str(x.get("timestamp", "")))
    print(
        json.dumps(
            {
                "correlation": a.correlation,
                "events": rows,
                "gaps": [] if rows else ["No matching events."],
            },
            indent=2,
        )
    )


if __name__ == "__main__":
    main()

