def timsort(items: list[Item]) -> list[Item]:
    return sorted(items, key=lambda item: (item[0], item[1]))


def merge_sort(items: list[Item]) -> list[Item]:
    width = 1
    source = list(items)
    target = source.copy()
    while width < len(source):
        for start in range(0, len(source), width * 2):
            left, mid, right = (
                start,
                min(start + width, len(source)),
                min(start + width * 2, len(source)),
            )
            i, j, out = left, mid, left
            while i < mid and j < right:
                if (source[i][0], source[i][1]) <= (source[j][0], source[j][1]):
                    target[out] = source[i]
                    i += 1
                else:
                    target[out] = source[j]
                    j += 1
                out += 1
            while i < mid:
                target[out] = source[i]
                i += 1
                out += 1
            while j < right:
                target[out] = source[j]
                j += 1
                out += 1
        source, target = target, source
        width *= 2
    return source


def heap_sort(items: list[Item]) -> list[Item]:
    heap = [((item[0], item[1]), item) for item in items]
    heapq.heapify(heap)
    return [heapq.heappop(heap)[1] for _ in range(len(heap))]


def quick_3way(items: list[Item]) -> list[Item]:
    values = list(items)
    stack = [(0, len(values) - 1)]
    while stack:
        low, high = stack.pop()
        if low >= high:
            continue
        pivot = (values[(low + high) // 2][0], values[(low + high) // 2][1])
        left, index, right = low, low, high
        while index <= right:
            key = (values[index][0], values[index][1])
            if key < pivot:
                values[left], values[index] = values[index], values[left]
                left += 1
                index += 1
            elif key > pivot:
                values[index], values[right] = values[right], values[index]
                right -= 1
            else:
                index += 1
        stack.extend([(low, left - 1), (right + 1, high)])
    return values


def counting_sort(items: list[Item]) -> list[Item]:
    keys = [item[0] for item in items]
    low, high = min(keys), max(keys)
    buckets: list[list[Item]] = [[] for _ in range(high - low + 1)]
    for item in items:
        buckets[item[0] - low].append(item)
    return [item for bucket in buckets for item in bucket]


def radix_sort(items: list[Item]) -> list[Item]:
    low = min(item[0] for item in items)
    shifted = [(item[0] - low, item) for item in items]
    place = 1
    maximum = max(key for key, _ in shifted)
    while maximum // place:
        buckets: list[list[tuple[int, Item]]] = [[] for _ in range(256)]
        for pair in shifted:
            buckets[(pair[0] // place) % 256].append(pair)
        shifted = [pair for bucket in buckets for pair in bucket]
        place *= 256
    return [item for _, item in shifted]


def bucket_sort(items: list[Item]) -> list[Item]:
    low, high = (
        min(float(item[0]) for item in items),
        max(float(item[0]) for item in items),
    )
    if low == high:
        return list(items)
    count = max(2, min(4096, int(math.sqrt(len(items))) or 2))
    buckets: list[list[Item]] = [[] for _ in range(count)]
    for item in items:
        index = min(count - 1, int((float(item[0]) - low) / (high - low) * count))
        buckets[index].append(item)
    return [
        item
        for bucket in buckets
        for item in sorted(bucket, key=lambda row: (row[0], row[1]))
    ]

def timsort(items: list[Item]) -> list[Item]:
    return sorted(items, key=lambda item: (item[0], item[1]))


def merge_sort(items: list[Item]) -> list[Item]:
    width = 1
    source = list(items)
    target = source.copy()
    while width < len(source):
        for start in range(0, len(source), width * 2):
            left, mid, right = (
                start,
                min(start + width, len(source)),
                min(start + width * 2, len(source)),
            )
            i, j, out = left, mid, left
            while i < mid and j < right:
                if (source[i][0], source[i][1]) <= (source[j][0], source[j][1]):
                    target[out] = source[i]
                    i += 1
                else:
                    target[out] = source[j]
                    j += 1
                out += 1
            while i < mid:
                target[out] = source[i]
                i += 1
                out += 1
            while j < right:
                target[out] = source[j]
                j += 1
                out += 1
        source, target = target, source
        width *= 2
    return source


def heap_sort(items: list[Item]) -> list[Item]:
    heap = [((item[0], item[1]), item) for item in items]
    heapq.heapify(heap)
    return [heapq.heappop(heap)[1] for _ in range(len(heap))]


def quick_3way(items: list[Item]) -> list[Item]:
    values = list(items)
    stack = [(0, len(values) - 1)]
    while stack:
        low, high = stack.pop()
        if low >= high:
            continue
        pivot = (values[(low + high) // 2][0], values[(low + high) // 2][1])
        left, index, right = low, low, high
        while index <= right:
            key = (values[index][0], values[index][1])
            if key < pivot:
                values[left], values[index] = values[index], values[left]
                left += 1
                index += 1
            elif key > pivot:
                values[index], values[right] = values[right], values[index]
                right -= 1
            else:
                index += 1
        stack.extend([(low, left - 1), (right + 1, high)])
    return values


