    while maximum // place:
        buckets: list[list[tuple[int, Item]]] = [[] for _ in range(256)]
        for pair in shifted:
            buckets[(pair[0] // place) % 256].append(pair)
        shifted = [pair for bucket in buckets for pair in bucket]
        place *= 256
    return [item for _, item in shifted]


