def _json_array_records(path: Path, chunk_size: int = 1024 * 1024) -> Iterator[Any]:
    decoder = json.JSONDecoder()
    with path.open("r", encoding="utf-8") as handle:
        buffer = ""
        started = False
        finished = False
        while not finished:
            chunk = handle.read(chunk_size)
            eof = chunk == ""
            buffer += chunk
            position = 0
            while True:
                while position < len(buffer) and buffer[position].isspace():
                    position += 1
                if not started:
                    if position >= len(buffer):
                        break
                    if buffer[position] != "[":
                        raise ValueError(
                            "JSON input must be a top-level array; use JSONL for streams"
                        )
                    started = True
                    position += 1
                    continue
                while position < len(buffer) and (
                    buffer[position].isspace() or buffer[position] == ","
                ):
                    position += 1
                if position < len(buffer) and buffer[position] == "]":
                    finished = True
                    position += 1
                    break
                if position >= len(buffer):
                    break
                try:
                    value, end = decoder.raw_decode(buffer, position)
                except json.JSONDecodeError:
                    if eof:
                        raise ValueError("invalid or incomplete JSON array")
                    break
                yield value
                position = end
            buffer = buffer[position:]
            if eof:
                if not finished and buffer.strip():
                    raise ValueError("invalid or incomplete JSON array")
                break
        if not started or not finished:
            raise ValueError("JSON array terminator was not found")


def iter_records(path: Path, input_format: str) -> Iterator[Any]:
    kind = (
        input_format
        if input_format != "auto"
        else {
            ".json": "json",
            ".jsonl": "jsonl",
            ".ndjson": "jsonl",
            ".csv": "csv",
        }.get(path.suffix.lower(), "lines")
    )
    if kind == "json":
        yield from _json_array_records(path)
    elif kind == "jsonl":
        with path.open("r", encoding="utf-8") as handle:
            for line_number, line in enumerate(handle, 1):
                if line.strip():
                    try:
                        yield json.loads(line)
                    except json.JSONDecodeError as error:
                        raise ValueError(
                            f"invalid JSON on line {line_number}: {error.msg}"
                        ) from error
    elif kind == "csv":
        with path.open("r", encoding="utf-8", newline="") as handle:
            yield from csv.DictReader(handle)
    elif kind == "lines":
        with path.open("r", encoding="utf-8") as handle:
            for line in handle:
                yield line.rstrip("\r\n")
    else:
        raise ValueError(f"unsupported input format: {kind}")

