def benchmark(
    name: str,
    algorithm: Algorithm,
    items: list[Item],
    reference: list[Item],
    repeats: int,
) -> dict[str, Any]:
    timings: list[int] = []
    correct = stable = True
    error: str | None = None
    for _ in range(repeats):
        started = time.perf_counter_ns()
        try:
            output = algorithm(list(items))
            elapsed = time.perf_counter_ns() - started
            run_correct, run_stable, run_error = validate_output(output, reference)
            correct = correct and run_correct
            stable = stable and run_stable

