def schema(name: str, fields: list[str]) -> dict:
    properties = {}
    for field in fields:
        if field in {
            "components",
            "models",
            "datasets",
            "evidence",
            "evidence_ids",
            "alternatives",
            "tags",
            "timeline",
            "steps",
        }:
            properties[field] = {
                "type": "array",
                "items": {"type": ["string", "object"]},
            }
        elif field in {
            "input",
            "oracle",
            "observed",
            "environment",
            "provenance",
            "checkpoint",
            "verification",
        }:
            properties[field] = {"type": "object"}
        elif field in {"recoverable"}:
            properties[field] = {"type": "boolean"}
        else:
            properties[field] = {"type": "string", "minLength": 1}
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": f"urn:engineering-loop-bootstrap:contract:{name}",
        "title": name.replace("-", " ").title(),
        "type": "object",
        "required": fields,
        "properties": properties,
        "additionalProperties": False,
    }

def disposition_for(relative: Path, suite: str) -> tuple[str, str]:
    text = relative.as_posix()
    name = relative.name
    if suite == "complete":
        if "/skills/" in f"/{text}" and name == "skill.json":
            return "merge_authoritative_contract", "domain capability-contract registry"
        if "/skills/" in f"/{text}" and name == "GUIDE.md":
            return "merge_authoritative_guidance", "domain lazy skill reference"
        if "/orchestrations/" in f"/{text}" or name == "orchestrations.json":
            return (
                "merge_authoritative_orchestration",
                "canonical declared-suite workflow registry",
            )
        if "/scripts/" in f"/{text}" and name in UNSAFE_SCRIPT_RULES:
            return (
                "reject_unsafe_body_use_safe_replacement",
                "existing fail-closed runtime owner",
            )
        if "/scripts/" in f"/{text}" and name.endswith(".py"):
            return "admit_namespaced_tool", "owning domain skill scripts"
        if "/schemas/" in f"/{text}":
            return (
                "merge_authoritative_schema",
                "declared-suite schema contract registry",
            )
        if "/templates/" in f"/{text}":
            return "merge_authoritative_template", "templates/declared_suite"
        if name in {"formulas.json", "knowledge.json"} or "/knowledge/" in f"/{text}":
            return (
                "merge_operational_knowledge",
                "declared-suite formula/knowledge registries",
            )
        if (
            "/tests/" in f"/{text}"
            or "/evidence/" in f"/{text}"
            or "/certification/" in f"/{text}"
        ):
            return "retain_validation_evidence", "REL-008 evidence ledger"
        return (
            "retain_provenance_or_package_metadata",
            "REL-008 source disposition ledger",
        )
    if suite == "scheduler":
        if "__pycache__" in text or name.endswith((".pyc", ".pyo")):
            return (
                "quarantine_generated_transient_after_intake_close",
                "parent temp quarantine",
            )
        if "/.agents/skills/" in f"/{text}" or "/.px/skills/" in f"/{text}":
            return (
                "consolidate_lazy_capability_contract",
                "orchestrate-capability-scheduling",
