        if "/orchestrations/" in f"/{text}":
            return (
                "compose_with_existing_orchestration",
                "orchestration/workflows/capability-scheduling.yaml",
            )
        if "/src/scheduler/" in f"/{text}" and name == "engine.py":
            return (
                "admit_and_harden_observe_only_runtime",
                "runtime/capability_scheduler.py",
            )
        if "/scripts/" in f"/{text}" and name.endswith(".py"):
            return (
                "retain_validation_or_cli_reference",
                "runtime/capability_scheduler.py and REL-008 evidence",
            )
        if "/schemas/" in f"/{text}":
            return "admit_namespaced_schema", "contracts/scheduling"
        if "/policies/" in f"/{text}":
            return "compose_policy", "registry/scheduling_policies.json"
        if (
            "/tests/" in f"/{text}"
            or "/evidence/" in f"/{text}"
            or "/certification/" in f"/{text}"
        ):
            return "retain_and_port_validation", "REL-008 tests and evidence"
        return (
            "retain_provenance_or_package_metadata",
            "REL-008 source disposition ledger",
        )
    if (
        "/.agents/skills/" in f"/{text}"
        or "/.px/skills/" in f"/{text}"
        or "/skills/" in f"/{text}"
        or name == "skills.json"
    ):
        return (
            "consolidate_lazy_capability_contract",
            "metacognitive capability registry and canonical owners",
        )
    if "/orchestration/" in f"/{text}" or name == "orchestrations.json":
        return (
            "compose_with_existing_orchestration",
            "metacognitive workflow projection",
        )
    if "/runtime/" in f"/{text}" and name.endswith(".py"):
        return (
            "admit_namespaced_runtime",
            "engineering_bootstrap.metacognitive_evolution",
        )
    if "/scripts/" in f"/{text}" and name == "release_hygiene.py":
        return "merge_no_copy", "quarantine-only cleanup and release audit"
    if "/scripts/" in f"/{text}" and name.endswith(".py"):
