def enrich_declared_suite(root: Path, complete: Path) -> dict:
    skills: dict[tuple[str, str], tuple[Path, dict]] = {}
    orchestrations: dict[tuple[str, str], tuple[Path, dict]] = {}
    formulas = []
    knowledge = []
    schemas = []
    templates = []
    admitted_scripts = []
    rejected_scripts = []
    validation_scripts = []

    for pack in sorted((complete / "packs").iterdir()):
        number = pack.name[:2]
        if number not in PACK_OWNERS:
            continue
        for path in sorted(pack.glob("skills/*/skill.json")):
            contract = load(path)
            guide = path.with_name("GUIDE.md")
            if guide.is_file():
                contract["authoritative_guide"] = guide.read_text(encoding="utf-8")
                contract["authoritative_guide_sha256"] = digest(guide)
            skills[(number, contract["id"])] = (path, contract)
        orch_path = pack / "registry" / "orchestrations.json"
        if orch_path.exists():
            for item in load(orch_path).get("orchestrations", []):
                orchestrations[(number, item["id"])] = (orch_path, item)
        for name, target in (
            ("formulas.json", formulas),
            ("knowledge.json", knowledge),
        ):
            path = pack / "registry" / name
            if path.exists():
                value = load(path)
                records = value.get(
                    name.removesuffix(".json"), value.get("records", [])
                )
                for record in records:
                    target.append(
                        {"pack": number, "source_sha256": digest(path), **record}
                    )
        for path in sorted((pack / "schemas").glob("*.json")):
            schemas.append(
                {
                    "pack": number,
                    "name": path.name,
                    "source_sha256": digest(path),
                    "schema": load(path),
                }
            )
        for path in (
            sorted((pack / "templates").glob("*"))
            if (pack / "templates").exists()
            else []
        ):
            if path.is_file():
                target = (
                    root / "templates" / "declared_suite" / f"pack-{number}-{path.name}"
                )
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(path, target)
                templates.append(
                    {
                        "pack": number,
                        "source": path.relative_to(complete).as_posix(),
                        "target": target.relative_to(root).as_posix(),
                        "sha256": digest(target),
                    }
                )
        for path in sorted((pack / "scripts").glob("*.py")):
            if path.name == "__init__.py":
                continue
            if path.name in {"run_smoke_tests.py", "validate_pack.py"}:
                validation_scripts.append(
                    {
                        "pack": number,
                        "id": path.stem.replace("_", "-"),
                        "source_sha256": digest(path),
                        "disposition": "validation_only_existing_framework_gate",
                    }
                )
                continue
            if path.name in UNSAFE_SCRIPT_RULES:
                rejected_scripts.append(
                    {
                        "pack": number,
                        "id": path.stem.replace("_", "-"),
                        "source_sha256": digest(path),
                        "reason": UNSAFE_SCRIPT_RULES[path.name],
                    }
                )
                continue
            target = (
                root
                / ".agents"
                / "skills"
                / PACK_OWNERS[number]
                / "scripts"
                / f"authoritative_{path.name}"
            )
            shutil.copy2(path, target)
            admitted_scripts.append(
                {
                    "pack": number,
                    "id": path.stem.replace("_", "-"),
                    "source_sha256": digest(path),
                    "target": target.relative_to(root).as_posix(),
                }
            )

    enriched = 0
    for number, owner in PACK_OWNERS.items():
        for filename, kind in (
            ("capability-contracts.json", "skill"),
            ("script-contracts.json", "script"),
        ):
            path = root / ".agents" / "skills" / owner / "references" / filename
            value = load(path)
            for contract in value["contracts"]:
                match = (
                    skills.get((number, contract["id"])) if kind == "skill" else None
                )
                if match:
                    source_path, authoritative = match
                    contract["authoritative_contract"] = authoritative
                    contract["authoritative_source"] = source_path.relative_to(
                        complete
                    ).as_posix()
                    contract["authoritative_sha256"] = digest(source_path)
                    contract.pop("historical_non_claim", None)
                    enriched += 1
                elif kind == "script":
                    script = next(
                        (
                            x
                            for x in admitted_scripts
                            + rejected_scripts
                            + validation_scripts
                            if x["pack"] == number and x["id"] == contract["id"]
                        ),
                        None,
                    )
                    if script:
                        contract["authoritative_source_sha256"] = script[
                            "source_sha256"
                        ]
                        contract["implementation_disposition"] = (
                            "namespaced_exact_body"
                            if "target" in script
                            else script.get("disposition", "safe_replacement")
                        )
                        if "target" in script:
                            contract["implementation_target"] = script["target"]
                        elif "reason" in script:
                            contract["rejection_reason"] = script["reason"]
                        contract.pop("historical_non_claim", None)
                        enriched += 1
            dump(path, value)
            split_name = "capabilities" if kind == "skill" else "scripts"
            split_root = path.parent / split_name
            index = []
            for contract in value["contracts"]:
                target = split_root / f"{contract['id']}.json"
                dump(target, contract)
                index.append(
                    {
                        "id": contract["id"],
                        "path": target.relative_to(root).as_posix(),
                        "trigger": contract.get("trigger"),
                        "sha256": digest(target),
                    }
                )
            dump(
                path.parent / f"{split_name}-index.json",
                {"schema_version": "1.0", "count": len(index), "records": index},
            )

    workflow_path = root / "orchestration" / "workflows" / "declared-suite.yaml"
    workflows = load(workflow_path)
    for workflow in workflows["workflows"]:
        match = next(
            (
                (path, item)
                for (number, item_id), (path, item) in orchestrations.items()
                if item_id == workflow["id"]
            ),
            None,
        )
        if match:
            source_path, authoritative = match
            workflow["authoritative_contract"] = authoritative
            workflow["authoritative_source"] = source_path.relative_to(
                complete
            ).as_posix()
            workflow["authoritative_sha256"] = digest(source_path)
            enriched += 1
    workflows["status"] = "authoritative_contracts_assimilated"
    dump(workflow_path, workflows)

    dump(
        root / "registry" / "declared_suite_formulas.json",
        {
            "schema_version": "2.0",
            "source": "REL-008 authoritative suite",
            "formula_count": len(formulas),
            "formulas": formulas,
        },
    )
    dump(
        root / "registry" / "declared_suite_knowledge.json",
        {
            "schema_version": "2.0",
            "source": "REL-008 authoritative suite",
            "count": len(knowledge),
            "records": knowledge,
        },
    )
    dump(
        root / "registry" / "declared_suite_schema_contracts.json",
        {"schema_version": "1.0", "count": len(schemas), "records": schemas},
    )
    dump(
        root / "registry" / "declared_suite_authoritative_tools.json",
        {
            "schema_version": "1.0",
            "admitted": admitted_scripts,
            "rejected": rejected_scripts,
            "validation_only": validation_scripts,
        },
    )
    return {
        "contracts_enriched": enriched,
        "skills": len(skills),
        "orchestrations": len(orchestrations),
        "formulas": len(formulas),
        "knowledge": len(knowledge),
        "schemas": len(schemas),
        "templates": len(templates),
        "admitted_scripts": len(admitted_scripts),
        "rejected_scripts": len(rejected_scripts),
        "validation_scripts": len(validation_scripts),
    }

def file_ledger(source_root: Path, root: Path) -> dict:
    records = []
    for suite_dir, suite in (
        (source_root / "complete-expert-capability-system_v1.0.0", "complete"),
        (
            source_root / "metacognitive_capability_evolution_pack_v1.0.0",
            "metacognitive",
        ),
        (
            source_root / "capability_orchestration_scheduling_system_v1.0.0",
            "scheduler",
        ),
    ):
        for path in sorted(p for p in suite_dir.rglob("*") if p.is_file()):
            relative = path.relative_to(suite_dir)
            disposition, target = disposition_for(relative, suite)
            records.append(
                {
                    "suite": suite,
                    "path": relative.as_posix(),
                    "bytes": path.stat().st_size,
                    "sha256": digest(path),
                    "disposition": disposition,
                    "target_owner_or_surface": target,
                    "status": "implemented_or_retained",
                }
            )
    counts = Counter(record["disposition"] for record in records)
    return {
        "schema_version": "1.0",
        "source_file_count": len(records),
        "open_count": 0,
        "disposition_counts": dict(sorted(counts.items())),
        "records": records,
    }

def integrate_scheduler(root: Path, scheduler: Path) -> dict:
    skill_dir = root / ".agents" / "skills" / "orchestrate-capability-scheduling"
    capabilities = []
    capability_index = []
    for source_dir in sorted((scheduler / ".agents" / "skills").iterdir()):
        if not source_dir.is_dir():
            continue
        body_path = source_dir / "SKILL.md"
        reference_path = source_dir / "references" / "contract.md"
        body = body_path.read_text(encoding="utf-8")
        reference = (
            reference_path.read_text(encoding="utf-8")
            if reference_path.is_file()
            else ""
        )
        description_match = re.search(r"^description:\s*(.+)$", body, re.MULTILINE)
        capability = {
            "id": source_dir.name,
            "version": "1.0.0",
            "description": description_match.group(1).strip()
            if description_match
            else source_dir.name.replace("-", " "),
            "canonical_owner": "orchestrate-capability-scheduling",
            "composed_with": [
                "skill-navigator",
                "execution-contract-enforcer",
                "recovery-coordinator",
                "outcome-verifier",
                "isolate-project-streams",
            ],
            "authoritative_skill_body": body,
            "authoritative_contract": reference,
            "source_body_sha256": digest(body_path),
            "source_contract_sha256": digest(reference_path)
            if reference_path.is_file()
            else None,
            "runtime_boundary": "observe-only planning; canonical execution, leases, evidence, and completion stay with existing owners",
        }
        target = skill_dir / "references" / "capabilities" / f"{source_dir.name}.json"
        dump(target, capability)
        capabilities.append(capability)
        capability_index.append(
            {
                "id": source_dir.name,
                "description": capability["description"],
                "path": target.relative_to(root).as_posix(),
                "sha256": digest(target),
            }
        )
    dump(
        skill_dir / "references" / "capability-index.json",
        {
            "schema_version": "1.0",
            "count": len(capability_index),
            "records": capability_index,
        },
    )
    dump(
        root / "registry" / "scheduling_capabilities.json",
        {
            "schema_version": "1.0",
            "count": len(capabilities),
            "capabilities": capabilities,
        },
    )
    owners = [
        {
            "id": item["id"],
            "owner": "orchestrate-capability-scheduling",
            "composed_with": item["composed_with"],
            "disposition": "bounded_extension",
        }
        for item in capabilities
    ]
    dump(
        root / "registry" / "scheduling_capability_owners.json",
        {"schema_version": "1.0", "count": len(owners), "records": owners},
    )

    workflows = []
    workflow_index = []
    for source in sorted((scheduler / "orchestrations").glob("*.yaml")):
        workflow = load(source)
        workflow["canonical_owner"] = "orchestrate-capability-scheduling"
        workflow["source_sha256"] = digest(source)
        workflows.append(workflow)
        workflow_index.append(
            {
                "id": workflow["name"],
                "path": "orchestration/workflows/capability-scheduling.yaml",
                "source_sha256": digest(source),
            }
        )
    dump(
        root / "orchestration" / "workflows" / "capability-scheduling.yaml",
        {
            "schema_version": "1.0",
            "workflow_count": len(workflows),
            "workflows": workflows,
        },
    )
    dump(
        skill_dir / "references" / "workflow-index.json",
        {
            "schema_version": "1.0",
            "count": len(workflow_index),
            "records": workflow_index,
        },
    )

    policies = []
    for source in sorted((scheduler / "policies").glob("*.json")):
        policies.append(
            {
                "id": source.stem.replace("_", "-"),
                "source_sha256": digest(source),
                "policy": load(source),
            }
        )
    dump(
        root / "registry" / "scheduling_policies.json",
        {"schema_version": "1.0", "count": len(policies), "policies": policies},
    )

    contract_count = 0
    for source in sorted((scheduler / "schemas").glob("*.json")):
        schema = load(source)
        stem = source.name.removesuffix(".schema.json")
        schema["$schema"] = "https://json-schema.org/draft/2020-12/schema"
        schema["$id"] = f"urn:engineering-loop-bootstrap:contract:scheduling:{stem}"
        dump(root / "contracts" / "scheduling" / source.name, schema)
        contract_count += 1
    return {
        "skills": len(capabilities),
        "workflows": len(workflows),
        "policies": len(policies),
        "contracts": contract_count,
    }

"""Validated declarative workflow proposals (PC-501)."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Iterable, Mapping

try:  # installed package
    from engineering_bootstrap.graphs import validate_orchestration
except ImportError:  # source checkout
    from runtime.graphs import validate_orchestration

from .common import (
    BuilderError,
    MUTATING_EFFECTS,
    bounded_unique,
    proposal_envelope,
    require_identifier,
)


@dataclass(frozen=True, slots=True)
class WorkflowStep:
    step_id: str
    capability_id: str
    depends_on: tuple[str, ...] = ()
    effects: tuple[str, ...] = ()
    approval_gate: str | None = None


@dataclass(frozen=True, slots=True)
class ResourceBudget:
    max_tool_calls: int
    max_seconds: int
    max_agents: int = 1
    max_test_runners: int = 1


@dataclass(frozen=True, slots=True)
class OrchestrationRequest:
    workflow_id: str
    inputs: tuple[str, ...]
    outputs: tuple[str, ...]
    steps: tuple[WorkflowStep, ...]
    stop_conditions: tuple[str, ...]
    resource_budget: ResourceBudget
    version: str = "0.1.0"


def _validated_contracts(
    records: Iterable[Mapping[str, object]],
) -> dict[str, Mapping[str, object]]:
    result: dict[str, Mapping[str, object]] = {}
    for record in records:
        capability_id = record.get("id")
        if not isinstance(capability_id, str) or not capability_id:
            raise BuilderError("capability contract is missing id")
        if capability_id in result:
            raise BuilderError(f"duplicate capability contract: {capability_id}")
        result[capability_id] = record
    return result


def _is_validated(contract: Mapping[str, object]) -> bool:
    validation = contract.get("validation")
    evidence = contract.get("evidence")
    return (
        contract.get("status") in {"admitted", "active"}
        and isinstance(validation, Mapping)
        and validation.get("failed", 0) == 0
        and isinstance(evidence, Mapping)
        and evidence.get("status") == "current"
    )


def _topological_order(dependencies: Mapping[str, set[str]]) -> tuple[str, ...]:
    pending = {step_id: set(values) for step_id, values in dependencies.items()}
    ordered: list[str] = []
    while pending:
        ready = sorted(step_id for step_id, values in pending.items() if not values)
        if not ready:
            raise BuilderError("workflow contains a dependency cycle")
        for step_id in ready:
            ordered.append(step_id)
            pending.pop(step_id)
        for values in pending.values():
            values.difference_update(ready)
    return tuple(ordered)


def propose_orchestration(
    request: OrchestrationRequest,
    capability_contracts: Iterable[Mapping[str, object]],
) -> dict[str, object]:
    workflow_id = require_identifier(request.workflow_id, "workflow_id")
    workflow_inputs = set(bounded_unique(request.inputs, "inputs", maximum=24))
    outputs = bounded_unique(request.outputs, "outputs", maximum=24)
    steps = bounded_unique(request.steps, "steps", maximum=24)
    stop_conditions = bounded_unique(
        request.stop_conditions, "stop_conditions", maximum=16
    )
    budget = request.resource_budget
    if budget.max_tool_calls < 0 or budget.max_seconds < 1:
        raise BuilderError(
            "resource budget requires non-negative tool calls and positive seconds"
        )
    if budget.max_agents < 1 or budget.max_test_runners < 1:
        raise BuilderError("parallelism budgets must be positive")

    contracts = _validated_contracts(capability_contracts)
    by_step: dict[str, WorkflowStep] = {}
    capability_steps: dict[str, list[str]] = {}
    for step in steps:
        require_identifier(step.step_id, "step_id")
        require_identifier(step.capability_id, "capability_id")
        if step.step_id in by_step:
            raise BuilderError(f"duplicate workflow step: {step.step_id}")
        contract = contracts.get(step.capability_id)
        if contract is None:
            raise BuilderError(f"unknown workflow capability: {step.capability_id}")
        if not _is_validated(contract):
            raise BuilderError(
                f"capability is not admitted with current evidence: {step.capability_id}"
            )
        by_step[step.step_id] = step
        capability_steps.setdefault(step.capability_id, []).append(step.step_id)

    dependencies: dict[str, set[str]] = {
        step_id: set(step.depends_on) for step_id, step in by_step.items()
    }
    for step_id, step in by_step.items():
        unknown = dependencies[step_id] - set(by_step)
        if unknown:
            raise BuilderError(
                f"{step_id} has unknown dependencies: {', '.join(sorted(unknown))}"
            )
        contract = contracts[step.capability_id]
        for capability_dependency in contract.get("dependencies", ()):
            candidates = capability_steps.get(str(capability_dependency), [])
            if len(candidates) != 1:
                raise BuilderError(
                    f"{step_id} cannot resolve capability dependency {capability_dependency}"
                )
            dependencies[step_id].add(candidates[0])

    # Resolve I/O edges only when one selected producer unambiguously supplies a type.
    for step_id, step in by_step.items():
        contract = contracts[step.capability_id]
        for consumed in contract.get("consumes", ()):
            if consumed in workflow_inputs:
                continue
            producers = sorted(
                other_id
                for other_id, other_step in by_step.items()
                if other_id != step_id
                and consumed in contracts[other_step.capability_id].get("provides", ())
            )
            if len(producers) != 1:
                raise BuilderError(
                    f"{step_id} input {consumed} has {len(producers)} eligible producers"
                )
            dependencies[step_id].add(producers[0])

    order = _topological_order(dependencies)
    available = set(workflow_inputs)
    for step_id in order:
        step = by_step[step_id]
        contract = contracts[step.capability_id]
        missing = sorted(set(contract.get("consumes", ())) - available)
        if missing:
            raise BuilderError(
                f"{step_id} inputs are unavailable: {', '.join(missing)}"
            )
        available.update(str(value) for value in contract.get("provides", ()))
    missing_outputs = sorted(set(outputs) - available)
    if missing_outputs:
        raise BuilderError(
            "workflow outputs are unavailable: " + ", ".join(missing_outputs)
        )

    estimated_calls = sum(
        int(contracts[step.capability_id].get("cost", {}).get("max_tool_calls", 0))
        for step in steps
    )
    estimated_seconds = sum(
        int(contracts[step.capability_id].get("latency", {}).get("max_seconds", 0))
        for step in steps
    )
    if estimated_calls > budget.max_tool_calls:
        raise BuilderError("workflow exceeds max_tool_calls budget")
    if estimated_seconds > budget.max_seconds:
        raise BuilderError("workflow exceeds max_seconds budget")

    spec_steps: list[dict[str, object]] = []
    approval_gates: list[dict[str, object]] = []
    evidence_steps: list[dict[str, object]] = []
    for step_id in order:
        step = by_step[step_id]
        contract = contracts[step.capability_id]
        declared_effects = tuple(str(value) for value in contract.get("effects", ()))
        effects = step.effects or declared_effects
        if not set(effects) <= set(declared_effects):
            raise BuilderError(f"{step_id} effects exceed capability declaration")
        spec_steps.append(
            {
                "id": step_id,
                "capability": step.capability_id,
                "depends_on": sorted(dependencies[step_id]),
                "effects": sorted(effects),
            }
        )
        if set(effects) & MUTATING_EFFECTS:
            approval_gates.append(
                {
                    "before_step": step_id,
                    "required": True,
                    "gate": step.approval_gate or f"explicit-approval-{step_id}",
                }
            )
        evidence_steps.append(
            {
                "id": f"evidence-{step_id}",
                "after_step": step_id,
                "required": True,
                "status": "current",
            }
        )

    spec = {
        "id": workflow_id,
        "version": request.version,
        "status": "candidate",
        "inputs": sorted(workflow_inputs),
        "outputs": sorted(outputs),
        "steps": spec_steps,
        "parallelism": {
            "max_agents": budget.max_agents,
            "max_test_runners": budget.max_test_runners,
        },
        "stop_conditions": sorted(stop_conditions),
        "resource_budget": {
            "max_tool_calls": budget.max_tool_calls,
            "max_seconds": budget.max_seconds,
        },
    }
    graph_errors = validate_orchestration(spec, contracts.values())
    if graph_errors:
        raise BuilderError("invalid orchestration: " + "; ".join(graph_errors))
    body = {
        "workflow": spec,
        "resolved_order": list(order),
        "io_graph_validated": True,
        "dag_validation": {"valid": True, "errors": []},
        "approval_gates": approval_gates,
        "evidence_steps": evidence_steps,
        "budget_analysis": {
            "known_before_execution": True,
            "estimated_tool_calls": estimated_calls,
            "estimated_seconds": estimated_seconds,
        },
    }
    return proposal_envelope("orchestration", workflow_id, body)

