def _run(*arguments: str) -> dict:
    command = [sys.executable, "-m", "runtime.cli", "--root", str(ROOT), *arguments]
    result = subprocess.run(
        command, cwd=ROOT, text=True, capture_output=True, timeout=60
    )
    if result.returncode:
        raise RuntimeError(
            f"command failed ({result.returncode}): {' '.join(command)}\n{result.stdout}\n{result.stderr}"
        )
    return json.loads(result.stdout)


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Run the bounded PACIFY-X quickstart demonstration."
    )
    parser.add_argument(
        "--output",
        type=Path,
        required=True,
        help="New directory that will retain the demo project and evidence",
    )
    args = parser.parse_args()
    output = args.output.resolve()
    if output.exists():
        raise SystemExit("--output must name a path that does not exist")
    evidence = output / "evidence"
    project = output / "project"
    evidence.mkdir(parents=True)

    steps: dict[str, object] = {}
    # The quickstart demonstrates an operable pre-validation lifecycle. Full
    # validation is intentionally reserved for the post-profile closure phase.
    steps["framework_validation"] = _run("processing-order", "status")
    steps["initialization_preview"] = _run(
        "commission", "--mode", "new", "--project", str(project)
    )
    steps["initialization"] = _run(
        "commission", "--mode", "new", "--project", str(project), "--apply"
    )
    task = "validate a bounded project with retained evidence"
    steps["classification"] = _run("classify", "--task", task)
    selection = _run("working-set", "--goal", task)
    steps["selection"] = selection
    selected = str(selection["capability_ids"][0])
    hydration = _run("hydrate", "--skill", selected)
    steps["hydration"] = {
        "valid": hydration["valid"],
        "selected": selected,
        "active_ids": hydration["active_ids"],
        "bytes_loaded": hydration["bytes_loaded"],
        "release": hydration["release"],
    }
    steps["bounded_dry_run"] = _run(
        "commission", "--mode", "new", "--project", str(output / "dry-run-project")
    )
    steps["verification"] = _run("project-check", "--project", str(project))

    valid = all(
        bool(value.get("valid", True))
        for value in steps.values()
        if isinstance(value, dict)
    )

valid = all(
    bool(value.get("valid", True))
    for value in steps.values()
    if isinstance(value, dict)
)
receipt = {
    "schema_version": "1.0",
    "valid": valid,
    "project": "project",
    "changed_paths": ["project/", "evidence/demo-receipt.json"],
    "effects": [
        "create explicitly requested demo output",
        "no network",
        "no deletion",
    ],
    "steps": steps,
}
canonical = json.dumps(receipt, sort_keys=True, separators=(",", ":")).encode()
receipt["receipt_sha256"] = hashlib.sha256(canonical).hexdigest()
path = evidence / "demo-receipt.json"
path.write_text(
    json.dumps(receipt, indent=2, sort_keys=True) + "\n",
    encoding="utf-8",
    newline="\n",
)
print(
    json.dumps(
        {
            "valid": valid,
            "evidence": str(path),
            "receipt_sha256": receipt["receipt_sha256"],
        },
        indent=2,
    )
)
return 0 if valid else 1

[CmdletBinding()]
param(
  [string]$VsixPath = ''
)

$ErrorActionPreference = 'Stop'
$package = Get-Content -Raw -LiteralPath (Join-Path $PSScriptRoot 'package.json') | ConvertFrom-Json
$expectedName = "$($package.name)-$($package.version).vsix"
if (-not $VsixPath) { $VsixPath = Join-Path $PSScriptRoot "dist\$expectedName" }
$resolvedVsix = (Resolve-Path -LiteralPath $VsixPath).Path

$hashManifest = Join-Path $PSScriptRoot 'SHA256SUMS.txt'
$line = Get-Content -LiteralPath $hashManifest | Where-Object { $_ -match [regex]::Escape($expectedName) } | Select-Object -First 1
if (-not $line) { throw "SHA256SUMS.txt does not certify $expectedName." }
$expectedSha256 = ($line -split '\s+')[0].ToLowerInvariant()
$actualSha256 = (Get-FileHash -LiteralPath $resolvedVsix -Algorithm SHA256).Hash.ToLowerInvariant()
if ($actualSha256 -ne $expectedSha256) {
  throw "VSIX integrity check failed. Expected $expectedSha256, received $actualSha256."
}

$code = Get-Command code -ErrorAction Stop
$extensionId = "$($package.publisher).$($package.name)"
$installedBefore = & $code.Source --list-extensions --show-versions
if ($installedBefore -contains "$extensionId@$($package.version)") {
  throw "Refusing same-version replacement of $extensionId@$($package.version). Every changed VSIX payload requires a new package version."
}
& $code.Source --install-extension $resolvedVsix --force
if ($LASTEXITCODE -ne 0) { throw "VS Code rejected the VSIX with exit code $LASTEXITCODE." }

$installed = & $code.Source --list-extensions --show-versions | Where-Object { $_ -eq "$extensionId@$($package.version)" }
if (-not $installed) { throw "VS Code did not report $extensionId@$($package.version) after installation." }
Write-Host "Pacify-X $($package.version) installed and verified on disk. Run 'Developer: Reload Window' before opening the Pacify-X Control Plane."

'use strict';

(() => {
  const root = globalThis;
  if (root.PXDashboard) return;

  const modules = new Map();
  const api = {
    version: '1.0.0',
    define(name, value) {
      if (!name || typeof name !== 'string') throw new TypeError('Dashboard module name must be a non-empty string.');
      if (modules.has(name)) throw new Error(`Dashboard module already defined: ${name}`);
      modules.set(name, Object.freeze(value));
      return modules.get(name);
    },
    require(name) {
      if (!modules.has(name)) throw new Error(`Dashboard module is not available: ${name}`);
      return modules.get(name);
    },
    has(name) { return modules.has(name); },
    list() { return Object.freeze([...modules.keys()]); }
  };

  Object.defineProperty(root, 'PXDashboard', {
    value: Object.freeze(api), configurable: false, enumerable: false, writable: false
  });
})();

'use strict';

(() => {
  const dashboard = globalThis.PXDashboard;
  if (!dashboard) throw new Error('PXDashboard foundation must load before state.');

  const text = (value, fallback = '', maximum = 240) => {
    const candidate = typeof value === 'string' ? value.trim() : '';
    return candidate && candidate.length <= maximum ? candidate : fallback;
  };
  const oneOf = (value, allowed, fallback) => allowed.includes(value) ? value : fallback;
  const integer = (value, minimum, maximum, fallback) => {
    const candidate = Number(value);
    return Number.isSafeInteger(candidate) ? Math.max(minimum, Math.min(maximum, candidate)) : fallback;
  };
  const boundedArray = (value, limit, maximumBytes) => {
    if (!Array.isArray(value)) return [];
    try {
      const encoded = JSON.stringify(value.slice(0, limit));
      if (new TextEncoder().encode(encoded).byteLength > maximumBytes) return [];
      const parsed = JSON.parse(encoded);
      return Array.isArray(parsed) ? parsed : [];
    } catch { return []; }
  };
  const GRAPH_SAVED_VIEW_KEYS = Object.freeze(['community', 'depth', 'direction', 'kind', 'layout', 'mode', 'name', 'query', 'relation', 'status', 'target', 'view']);
  const graphSavedViews = value => {
    if (!Array.isArray(value)) return [];
    const result = [];
    for (const candidate of value.slice(0, 12)) {
      if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) continue;
      if (Object.keys(candidate).sort().join('\0') !== GRAPH_SAVED_VIEW_KEYS.join('\0')) continue;
      const name = text(candidate.name, '', 80);
      if (!name || candidate.name !== name) continue;
      const normalized = {
        name,
        view: oneOf(candidate.view, ['capabilities', 'repository'], 'capabilities'),
        mode: oneOf(candidate.mode, ['full', 'overview', 'neighborhood', 'path', 'impact', 'dependencies', 'dependents', 'hubs', 'orphans', 'provenance'], 'full'),
        target: text(candidate.target, '', 500),
        query: text(candidate.query, '', 500),
        relation: text(candidate.relation, '', 160),
        direction: oneOf(candidate.direction, ['both', 'outgoing', 'incoming'], 'both'),
        depth: integer(candidate.depth, 1, 6, 1),
        layout: oneOf(candidate.layout, ['community', 'orbit', 'flow'], 'community'),
        kind: text(candidate.kind, '', 120),
        status: text(candidate.status, '', 120),
        community: text(candidate.community, '', 160)
      };
      if (GRAPH_SAVED_VIEW_KEYS.some(key => candidate[key] !== normalized[key])) continue;
      result.push(normalized);
    }
    return boundedArray(result, 12, 262144);
  };
  const containsForbiddenDraftKey = value => {
    if (!value || typeof value !== 'object') return false;
    if (Array.isArray(value)) return value.some(containsForbiddenDraftKey);
    return Object.entries(value).some(([key, item]) =>
      /^(?:token|proof|requestId|request_id|approvalIdentity|approval_identity|credentialValue|credential_value|secret)$/i.test(key)
      || containsForbiddenDraftKey(item)
    );
  };
  const SHA256_PATTERN = /^[a-f0-9]{64}$/;
  const STUDIO_IDENTITY_PATTERN = /^[a-z0-9][a-z0-9._:-]{0,199}$/;
  const STUDIO_VERSION_PATTERN = /^(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)(?:-[0-9a-z.-]+)?(?:\+[0-9a-z.-]+)?$/;
  const SOURCE_BINDING_KEYS = Object.freeze([
    'identity', 'source_content_sha256', 'source_revision_sha256',
    'source_scope', 'source_version'
  ]);
  const sourceBinding = (value, kind, draft) => {
    if (value === null || value === undefined) return null;
    if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined;
    if (Object.keys(value).sort().join('\0') !== [...SOURCE_BINDING_KEYS].sort().join('\0')) return undefined;
    const identityKey = kind === 'agent' ? 'agent_id' : kind === 'workflow' ? 'workflow_id' : 'skill_id';
    const identity = typeof value.identity === 'string' ? value.identity.trim().toLowerCase() : '';
    const sourceVersion = typeof value.source_version === 'string' ? value.source_version.trim().toLowerCase() : '';
    const draftIdentity = typeof draft?.[identityKey] === 'string' ? draft[identityKey].trim().toLowerCase() : '';
    const draftVersion = typeof draft?.version === 'string' ? draft.version.trim().toLowerCase() : '';
    if (value.identity !== identity || value.source_version !== sourceVersion) return undefined;
    if (!STUDIO_IDENTITY_PATTERN.test(identity) || !STUDIO_VERSION_PATTERN.test(sourceVersion) || !STUDIO_VERSION_PATTERN.test(draftVersion)) return undefined;
    if (draftIdentity !== identity || draft?.[identityKey] !== draftIdentity || draft?.version !== draftVersion) return undefined;
    if (!['studio-physical', 'external-authenticated'].includes(value.source_scope)) return undefined;
    if (value.source_scope === 'external-authenticated' && kind !== 'skill') return undefined;
    if (!SHA256_PATTERN.test(value.source_revision_sha256) || !SHA256_PATTERN.test(value.source_content_sha256)) return undefined;
    return {
      source_scope: value.source_scope,
      identity,
      source_version: sourceVersion,
      source_revision_sha256: value.source_revision_sha256,
      source_content_sha256: value.source_content_sha256
    };
  };
