    const graphObservation = graph?.observation;
    const projectsComplete = completeOwnedProbe(projects)
      && projectsObservation?.completed === true
      && projectsObservation?.webview_restarted === true
      && projectsObservation?.exact_reconstruction === true;
    const graphComplete = completeOwnedProbe(graph)
      && graphObservation?.completed === true
      && graphObservation?.invalid_rejected === true
      && graphObservation?.saved_view_created === true
      && graphObservation?.saved_view_applied === true
      && graphObservation?.saved_view_deleted === true
      && graphObservation?.webview_restarted === true
      && graphObservation?.exact_reconstruction === true
      && graphObservation?.restored === true;
    if (!projectsComplete || !graphComplete) {
      incomplete('focused-knowledge-graph-incomplete', 'The focused Knowledge Graph journey did not complete its prerequisite project-map reconstruction and exact saved-view restart, apply, deletion, and restoration contract.', {
        projects: {
          complete: projectsComplete,
          eligible_control_count: Number(projects?.control_probe?.eligible_control_count || 0),
          record_count: Array.isArray(projects?.control_probe?.records) ? projects.control_probe.records.length : 0,
          errors: projectsObservation?.errors || []
        },
        knowledge_graph: {
          complete: graphComplete,
          eligible_control_count: Number(graph?.control_probe?.eligible_control_count || 0),
          record_count: Array.isArray(graph?.control_probe?.records) ? graph.control_probe.records.length : 0,
          errors: graphObservation?.errors || []
        }
      });
    }
  } else if (focused === 'surface-capture') {
    const expectedSurfaces = ['dashboard', 'projects', 'agents', 'agent-studio', 'workflow-studio', 'skill-studio', 'knowledgeGraph', 'skillsTools', 'workflows', 'plugins', 'memory', 'activity', 'diagnostics', 'assurance', 'studio-lifecycle', 'settings', 'knowledgeCore', 'runtimeCore'];
    const results = Array.isArray(value.results) ? value.results : [];
    const bySurface = new Map(results.map(result => [String(result?.surface || ''), result]));
    const incompleteSurfaces = expectedSurfaces.filter(surface => {
      const result = bySurface.get(surface);
      return result?.navigation_active !== true
        || result?.captures?.surface_id !== surface
        || result?.captures?.first_fold?.screenshot?.status !== 'captured'
        || result?.captures?.deep_panel?.screenshot?.status !== 'captured';
    });
    const unexpectedSurfaces = [...bySurface.keys()].filter(surface => !expectedSurfaces.includes(surface));
    if (results.length !== expectedSurfaces.length || incompleteSurfaces.length || unexpectedSurfaces.length) {
      incomplete('focused-surface-capture-incomplete', 'The focused surface-capture journey did not stably navigate and capture exact first-fold and deep-panel evidence for every registered installed surface.', {
        expected_count: expectedSurfaces.length,
        result_count: results.length,
        incomplete_surfaces: incompleteSurfaces,
        unexpected_surfaces: unexpectedSurfaces
      });
    }
  } else if (focused === 'native-dialog-boundary') {
    const cleanup = value.cleanup_recycle_profile;
    const cleanupRecords = Array.isArray(cleanup?.control_probe?.records) ? cleanup.control_probe.records : [];
    const cleanupEligible = Number(cleanup?.control_probe?.eligible_control_count || 0);
    const cleanupComplete = cleanupEligible > 0 && cleanupRecords.length === cleanupEligible
      && cleanupRecords.every(record => record?.rendered === true && record?.attempted === true && !(record?.errors || []).length
        && (record?.control_id === 'pxui.runtime-core.action.cleanupPermanent'
          ? record?.authority_skipped === true
            && record?.interaction_chain?.failure_handling?.state === 'present'
            && record?.interaction_chain?.recovery_rollback?.state === 'present'
          : requiredStages.every(stage => ['present', 'not_applicable'].includes(record?.interaction_chain?.[stage]?.state))))
      && cleanup?.observation?.completed === true
      && cleanup?.observation?.webview_restarted === true
      && cleanup?.observation?.invalid_selection_rejected === true
      && cleanup?.observation?.select_all_round_trip === true
      && cleanup?.observation?.permanent_refused_without_authorization === true
      && cleanup?.observation?.permanent_completed === false
      && cleanup?.observation?.reclaimed_absent_after_restart === true
      && !(cleanup?.observation?.errors || []).length;
    const profiles = [
      ['enterprise', value.enterprise_profile, completeOwnedProbe(value.enterprise_profile)],
      ['projects', value.projects_profile, completeOwnedProbe(value.projects_profile)],
      ['knowledge-graph', value.knowledge_graph_profile, completeOwnedProbe(value.knowledge_graph_profile)],
      ['cleanup', cleanup, cleanupComplete],
      ['plugin-mutation', value.plugin_mutation_profile, completeOwnedProbe(value.plugin_mutation_profile)]
    ];
    const incompleteProfiles = profiles.filter(([, , complete]) => !complete).map(([name, profile]) => ({
      name,
      eligible_control_count: Number(profile?.control_probe?.eligible_control_count || 0),
      record_count: Array.isArray(profile?.control_probe?.records) ? profile.control_probe.records.length : 0,
      errors: profile?.observation?.errors || []
    }));
    if (incompleteProfiles.length) {
      incomplete('focused-native-dialog-boundary-incomplete', 'The focused native-dialog journey did not complete Enterprise, Projects, Knowledge Graph, Cleanup, and Plugin mutation through exact typed postconditions and recovery.', { incomplete_profiles: incompleteProfiles });
    }
  } else if (focused === 'plugin-lifecycle') {
    const profile = value.plugin_mutation_profile;
    const observation = profile?.observation;
    if (!completeOwnedProbe(profile)
      || observation?.completed !== true
      || observation?.exact_reconstruction !== true
      || observation?.cleanup_restored !== true
      || observation?.uninstall_rollback_reconciled !== true
      || observation?.update_rollback_reconciled !== true) {
      incomplete('focused-plugin-lifecycle-incomplete', 'The focused Plugin lifecycle did not complete its exact install, update, uninstall, rollback, reconstruction, and absent-state restoration contract.', {
        eligible_control_count: Number(profile?.control_probe?.eligible_control_count || 0),
        record_count: Array.isArray(profile?.control_probe?.records) ? profile.control_probe.records.length : 0,
