  dashboard: 'dashboard', projects: 'projects', agents: 'agents', 'agent-studio': 'agent-studio',
  'workflow-studio': 'workflow-studio', 'skill-studio': 'skill-studio', 'knowledge-graph': 'knowledgeGraph',
