  const ignored = new Set(['the', 'and', 'for', 'with', 'from', 'into', 'state', 'surface', 'control']);
  return [...new Set(normalize(value).split(' ').filter(token => (token.length > 2 || token === 'id') && !ignored.has(token)))];
}
