      || !chain || Object.keys(chain).length !== STAGES.length) return false;
    return STAGES.every(stage => Object.hasOwn(chain, stage)
      && ((control.stage_policy[stage] === 'not_applicable_with_evidence') === (chain[stage]?.state === 'not_applicable')));
  });
}

