  childProcess.spawnSync(git, ['init', '--quiet'], { cwd: config.workspace, encoding: 'utf8' });
  childProcess.spawnSync(git, ['config', 'user.email', 'px-installed@example.invalid'], { cwd: config.workspace, encoding: 'utf8' });
