      target.dispatchEvent(new inner.KeyboardEvent('keydown', { key: 'ArrowRight', bubbles: true, cancelable: true }));
      target.dispatchEvent(new inner.KeyboardEvent('keydown', { key: 'ArrowLeft', bubbles: true, cancelable: true }));
