    await settleInstalledSurfaceControl(frameHost, { surface: 'knowledgeGraph', selector: '[data-action="graphView"][data-view="repository"]', stableSamplesRequired: 2 }, Math.min(timeoutMs, 30_000));
    observation.rendered = true;
