function ownedCleanupCandidate(inventory, root, fixture) {
  if (!root || !fixture) return null;
  const resolvedRoot = path.resolve(root);
  const resolvedFixture = path.resolve(fixture);
  if (!resolvedFixture.startsWith(`${resolvedRoot}${path.sep}`)) return null;
  const expectedRelative = path.relative(resolvedRoot, resolvedFixture).split(path.sep).join('/');
  return (inventory?.candidates || []).find(candidate => candidate?.relativePath === expectedRelative
    && candidate?.name === '__pycache__'
    && candidate?.classification === 'safe-to-delete'
    && candidate?.retentionRequired === false
    && typeof candidate?.id === 'string' && candidate.id.length > 0) || null;
}

'use strict';

const fs = require('fs');
const path = require('path');
const {
  CONFORMANCE_VIOLATION_IDS,
  coordinationConformanceReport
} = require('../src/stateInvariants');

function clone(value) {
  return JSON.parse(JSON.stringify(value));
}

function mutate(state, mutation) {
  let target = state;
  const parts = mutation.path;
  for (const part of parts.slice(0, -1)) target = target[part];
  const leaf = parts.at(-1);
  if (mutation.op === 'set') target[leaf] = clone(mutation.value);
  else if (mutation.op === 'append') target[leaf].push(clone(mutation.value));
  else throw new Error(`unsupported conformance mutation: ${mutation.op}`);
}

function runVectors(corpus) {
  if (corpus.schema_version !== 'px.coordination-state-conformance-vectors/1.0') {
    throw new Error('coordination conformance vector schema is invalid');
  }
  if (JSON.stringify(corpus.evaluation_order) !== JSON.stringify(CONFORMANCE_VIOLATION_IDS)) {
    throw new Error('coordination conformance evaluation order drifted');
  }
  return corpus.vectors.map(vector => {
    const state = clone(corpus.base_state);
    for (const mutation of vector.mutations) mutate(state, mutation);
    return {
      id: vector.id,
      ...coordinationConformanceReport(state, { nowUtc: corpus.now_utc })
    };
  });
}

if (require.main === module) {
  const corpusPath = process.argv[2];
  if (!corpusPath) throw new Error('vector corpus path is required');
  const corpus = JSON.parse(fs.readFileSync(path.resolve(corpusPath), 'utf8'));
  process.stdout.write(`${JSON.stringify({ results: runVectors(corpus) })}\n`);
}

module.exports = { runVectors };

'use strict';

const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
const { requiredBrowserLanes } = require('../tests/browser-lane');

const root = path.resolve(__dirname, '..');
const testsRoot = path.join(root, 'tests');
const isolated = Object.freeze({
  'ui-e2e': Object.freeze(['dashboard-e2e.test.js', 'sidebar-e2e.test.js']),
  performance: Object.freeze(['runtime-efficiency-load.test.js'])
});

function testFiles() {
  return fs.readdirSync(testsRoot).filter(name => name.endsWith('.test.js')).sort();
}

function profile(name) {
  const all = testFiles();
  const isolatedNames = new Set(Object.values(isolated).flat());
  if (name === 'unit') return { name, concurrency: 4, files: all.filter(file => !isolatedNames.has(file)) };
  if (Object.hasOwn(isolated, name)) return { name, concurrency: 1, files: isolated[name].filter(file => all.includes(file)) };
  throw new Error(`unknown-test-profile:${name}`);
}

function run(name) {
  const selected = profile(name);
  if (!selected.files.length) throw new Error(`empty-test-profile:${name}`);
  const args = ['--test', `--test-concurrency=${selected.concurrency}`, ...selected.files.map(file => path.join('tests', file))];
  const lanes = name === 'ui-e2e' ? requiredBrowserLanes() : [null];
  const results = [];
  for (const lane of lanes) {
    const result = spawnSync(process.execPath, args, {
      cwd: root, stdio: 'inherit', windowsHide: true,
      env: { ...process.env, ...(lane ? { PX_UI_BROWSER: lane } : {}) }
    });
    if (result.error) throw result.error;
    results.push({ lane, exit_code: Number.isInteger(result.status) ? result.status : 1 });
  }
  if (name === 'ui-e2e') {
    const evidenceRoot = path.join(root, 'evidence');
    fs.mkdirSync(evidenceRoot, { recursive: true });
    fs.writeFileSync(path.join(evidenceRoot, 'browser-matrix.json'), `${JSON.stringify({
      schema_version: 'px.ui-browser-matrix/1.0', generated_utc: new Date().toISOString(),
      platform: process.platform, lanes: results, passed: results.every(item => item.exit_code === 0)
    }, null, 2)}\n`, 'utf8');
  }
  return results.every(item => item.exit_code === 0) ? 0 : 1;
}

if (require.main === module) process.exitCode = run(process.argv[2] || 'unit');

module.exports = { profile, run, testFiles };

