function createLatestDiscoveryCoordinator() {
  let pending = null;
  let generation = 0;

  function run(start, options = {}) {
    if (typeof start !== 'function') throw new TypeError('latest-discovery-start-required');
    if (!pending || options.requireFresh === true) {
      generation += 1;
      let candidate;
      try { candidate = Promise.resolve(start(generation)); }
      catch (error) { candidate = Promise.reject(error); }
      pending = candidate;
      const clearIfOwner = () => { if (pending === candidate) pending = null; };
      candidate.then(clearIfOwner, clearIfOwner);
    }
    return pending;
  }

  return { run };
}

module.exports = { createLatestDiscoveryCoordinator };

'use strict';

const crypto = require('crypto');
const { SDK_VERSION, buildOperationEvent } = require('./instrumentationSdk');

function sha(value) {
  return crypto.createHash('sha256').update(typeof value === 'string' ? value : JSON.stringify(value)).digest('hex');
}

function cleanId(value, fallback) {
  const result = String(value ?? '').trim().toLowerCase().replace(/[^a-z0-9._-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 160);
  return result || fallback;
}

function actorAttestation(input = {}, context = {}, processId = process.pid) {
  const required = ['actor_id', 'session_id', 'harness', 'accountable_owner'];
  const missing = required.filter(field => typeof input[field] !== 'string' || !input[field].trim());
  const coreIdentityPresent = ['actor_id', 'session_id', 'harness'].every(field => typeof input[field] === 'string' && input[field].trim());
  const contextualSession = context?.source?.session_id;
  return {
    actor: {
      actorId: cleanId(input.actor_id, 'mcp-client'),
      sessionId: cleanId(input.session_id || contextualSession, `mcp-server-${processId}`),
      harness: String(input.harness || context?.source?.surface || 'MCP client').slice(0, 120),
      accountableOwner: String(input.accountable_owner || 'unattested-owner').slice(0, 160)
    },
    actorKind: coreIdentityPresent ? 'agent' : 'unknown',
    identityAttestation: coreIdentityPresent ? 'self_asserted' : 'unattested',
    unattestedFields: missing
  };
}

function createMcpActivityIntegration(options) {
  const state = {
    schema_version: 'px.mcp-instrumentation-health/1.0', registered_tools: [], calls: 0,
    emitted_events: 0, dropped_events: 0, last_drop_type: null,
    identity: { authenticated_host_capability_calls: 0, self_asserted_calls: 0, unattested_calls: 0 }
  };
  const now = options.now || (() => new Date().toISOString());
  const uuid = options.uuid || (() => crypto.randomUUID());

  function health() {
    return {
      ...state,
      registered_tools: [...state.registered_tools],
      status: state.dropped_events ? 'degraded' : 'healthy',
      authority_granted: false,
      canonical_bus_connected: false,
      coverage_tier: 'C',
      limitations: ['Events are canonical-contract attestations retained in the project activity ledger; direct canonical-bus publication remains an O11 reconciliation dependency.']
    };
  }

  function canonicalEvent(name, definition, input, lifecycle, result, correlationId, attestation, startedAt, durationMs) {
    const readOnly = Boolean(definition.annotations?.readOnlyHint);
    const reportedCorrelation = typeof input?.correlation_id === 'string' && input.correlation_id ? cleanId(input.correlation_id, null) : null;
    return buildOperationEvent({
      sdk_version: SDK_VERSION,
      event_id: `mcp-${uuid()}-${lifecycle}`,
      correlation_id: correlationId,
      parent_correlation_id: reportedCorrelation,
      actor: {
        actor_id: attestation.actor.actorId,
        actor_kind: attestation.actorKind,
        session_id: attestation.actor.sessionId,
        harness: attestation.actor.harness,
        accountable_owner: attestation.actor.accountableOwner
      },
      work: {
        project_id: cleanId(options.projectId?.() || 'unresolved-project', 'unresolved-project'),
        task_id: input?.task_id ? cleanId(input.task_id, null) : null,
        claim_id: input?.claim_id ? cleanId(input.claim_id, null) : null,
        orchestration_id: input?.orchestration_id ? cleanId(input.orchestration_id, null) : null
      },
      source: { route_id: 'mcp.tool', component: 'src/mcpActivityIntegration.js', host_id: null, coverage_tier: 'C' },
      operation: { name, lifecycle, result },
      effects: {
        declared: readOnly ? ['read'] : ['write'],
        observed: readOnly ? ['read'] : ['write'],
        scope_refs: [`tool:${cleanId(name, 'unknown')}`]
      },
      provider: null,
      time: { observed_at: now(), started_at: startedAt, duration_ms: durationMs, freshness: 'live' },
      integrity: { input_sha256: null, output_sha256: null, previous_event_sha256: null },
      capture: { classification: 'metadata_only', payload_included: false }
    });
  }

  function emit(name, definition, input, lifecycle, result, correlationId, attestation, startedAt, durationMs) {
    if (options.policy().captureMcpCalls === false) return { recorded: false, reason: 'mcp-capture-disabled' };
    const event = canonicalEvent(name, definition, input, lifecycle, result, correlationId, attestation, startedAt, durationMs);
    const legacyStatus = { started: 'started', completed: 'succeeded', failed: 'failed' }[lifecycle] || 'observed';
    try {
      const recorded = options.recordActivity(
        options.workspaceRoot(),
        attestation.actor,
        {
          category: 'mcp', operation: name, status: legacyStatus, source: 'pacify-x-mcp',
          effect: definition.annotations?.readOnlyHint ? 'workspace-read' : 'workspace-write',
          correlationId, parentCorrelationId: event.parent_correlation_id,
          taskId: input?.task_id, claimId: input?.claim_id, durationMs,
          metadata: {
            tool: name,
            declared_read_only: Boolean(definition.annotations?.readOnlyHint),
            argument_keys: Object.keys(input || {}).sort(),
            identity_attestation: attestation.identityAttestation,
            unattested_fields: attestation.unattestedFields,
            reported_correlation_id: event.parent_correlation_id,
            canonical_schema_version: event.schema_version,
            canonical_sdk_version: SDK_VERSION,
            canonical_event_sha256: sha(event),
            server_version: String(options.serverVersion || 'unknown').slice(0, 80),
            payload_retained: false
          }
        },
        options.policy()
      );
      if (recorded?.recorded === false) throw new Error(`activity-${recorded.reason || 'not-recorded'}`);
      state.emitted_events += 1;
      return recorded;
    } catch (error) {
      state.dropped_events += 1;
      state.last_drop_type = error?.constructor?.name || 'Error';
      options.onDrop?.({ type: state.last_drop_type, tool: name, lifecycle });
      return { recorded: false, reason: 'instrumentation-drop', failure_type: state.last_drop_type };
    }
  }

  function wrapTool(name, definition, handler) {
    if (!name || typeof handler !== 'function') throw new Error('MCP tool identity and handler are required');
    if (state.registered_tools.includes(name)) throw new Error(`duplicate MCP tool instrumentation: ${name}`);
    state.registered_tools.push(name);
    return async input => {
      const context = options.contextEnvelope?.() || {};
      let effectiveInput = input;
      let attestation = actorAttestation(input, context, options.processId);
      if (!definition.annotations?.readOnlyHint && typeof options.authorize === 'function') {
        const decision = await options.authorize(name, input);
        if (!decision?.authorized) return decision?.result;
        effectiveInput = decision.input;
        attestation = decision.attestation;
      }
      state.calls += 1;
      state.identity[`${attestation.identityAttestation}_calls`] += 1;
      const correlationId = `mcp-${uuid()}`;
      const startedMs = Date.now();
      const startedAt = now();
      emit(name, definition, effectiveInput, 'started', 'pending', correlationId, attestation, startedAt, 0);
      try {
        const value = await handler(effectiveInput);
        emit(name, definition, effectiveInput, 'completed', 'success', correlationId, attestation, startedAt, Date.now() - startedMs);
        return value;
      } catch (error) {
        emit(name, definition, effectiveInput, 'failed', 'failure', correlationId, attestation, startedAt, Date.now() - startedMs);
        throw error;
      }
    };
  }

  return { wrapTool, health, actorAttestation: (input, context) => actorAttestation(input, context, options.processId) };
}

module.exports = { actorAttestation, createMcpActivityIntegration };

'use strict';

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const { canonicalJson, keyId, signClaim } = require('./studioApprovalHost');

const AUTHORITY_SCHEMA = 'px.mcp-launch-authority/1.0';
const MAX_LIFETIME_MS = 24 * 60 * 60 * 1000;
const MUTATING_TOOL_NAMES = Object.freeze([
  'pacify_enterprise_readiness',
  'pacify_enterprise_pack_set',
  'pacify_enterprise_target_configure',
  'pacify_activity_emit',
  'pacify_parallel_plan_create',
  'pacify_task_claim',
  'pacify_claim_renew',
  'pacify_task_progress',
  'pacify_task_reconcile',
  'pacify_task_release',
  'pacify_memory_capture',
  'pacify_team_pack_stage'
]);

function sha(value) {
  return crypto.createHash('sha256').update(String(value), 'utf8').digest('hex');
}

function physicalProjectIdentity(projectRoot) {
  if (!projectRoot) throw new Error('MCP project authority root is unavailable.');
  const resolved = fs.realpathSync.native(path.resolve(projectRoot));
  const stat = fs.statSync(resolved);
  if (!stat.isDirectory()) throw new Error('MCP project authority root is not a directory.');
  return sha(process.platform === 'win32' ? resolved.toLowerCase() : resolved);
}

function encodeClaim(claim) {
  return Buffer.from(canonicalJson(claim), 'utf8').toString('base64url');
}

function decodeClaim(value) {
  const raw = Buffer.from(String(value || ''), 'base64url');
  if (!raw.length || raw.length > 16 * 1024) throw new Error('MCP authority claim is invalid.');
  const claim = JSON.parse(raw.toString('utf8'));
  if (!claim || Array.isArray(claim) || typeof claim !== 'object') throw new Error('MCP authority claim is invalid.');
  return claim;
}

function createLaunchAuthority({ projectRoot, sessionId, keyMaterial, now = Date.now, lifetimeMs = 12 * 60 * 60 * 1000 }) {
  const issuedMs = Number(now());
  const boundedLifetime = Math.min(Math.max(Number(lifetimeMs) || 0, 60_000), MAX_LIFETIME_MS);
  const token = crypto.randomBytes(32).toString('base64url');
  const claim = {
    schema_version: AUTHORITY_SCHEMA,
    key_id: keyMaterial.keyId,
    project_sha256: physicalProjectIdentity(projectRoot),
    session_id: String(sessionId || ''),
    actor_id: 'vscode-mcp-host',
    harness: 'VS Code MCP',
    accountable_owner: 'local-user',
    allowed_operations: [...MUTATING_TOOL_NAMES],
    token_sha256: sha(token),
    issued_at: new Date(issuedMs).toISOString(),
    expires_at: new Date(issuedMs + boundedLifetime).toISOString()
  };
  if (!claim.session_id) throw new Error('MCP host session identity is unavailable.');
  return { claim: encodeClaim(claim), signature: signClaim(keyMaterial, claim), token };
}

function verifiedLaunchAuthority({ projectRoot, claim: encodedClaim, signature, token, publicKeyJwk, trustedKeyId, now = Date.now }) {
  const claim = decodeClaim(encodedClaim);
  const issuedMs = Date.parse(claim.issued_at);
  const expiresMs = Date.parse(claim.expires_at);
  const allowed = Array.isArray(claim.allowed_operations) ? claim.allowed_operations : [];
  const structurallyValid = claim.schema_version === AUTHORITY_SCHEMA &&
    /^[0-9a-f]{64}$/.test(String(claim.key_id || '')) && claim.key_id === trustedKeyId &&
    publicKeyJwk?.kty === 'RSA' && keyId(publicKeyJwk) === trustedKeyId &&
    claim.project_sha256 === physicalProjectIdentity(projectRoot) &&
    typeof claim.session_id === 'string' && claim.session_id.length > 0 && claim.session_id.length <= 200 &&
    claim.token_sha256 === sha(token) &&
    Number.isFinite(issuedMs) && Number.isFinite(expiresMs) && expiresMs > issuedMs &&
    expiresMs - issuedMs <= MAX_LIFETIME_MS && Number(now()) >= issuedMs - 30_000 && Number(now()) < expiresMs &&
    allowed.length === MUTATING_TOOL_NAMES.length &&
    MUTATING_TOOL_NAMES.every(name => allowed.includes(name));
  if (!structurallyValid) throw new Error('MCP host authority is unavailable or expired.');
  const verified = crypto.verify('sha256', Buffer.from(canonicalJson(claim), 'utf8'), {
    key: publicKeyJwk,
    format: 'jwk',
    padding: crypto.constants.RSA_PKCS1_PADDING
  }, Buffer.from(String(signature || ''), 'base64url'));
  if (!verified) throw new Error('MCP host authority signature is invalid.');
  return claim;
}

function deniedResult() {
  const value = { available: false, authorized: false, reason: 'A current authenticated Pacify-X host capability is required for this write.' };
  return { isError: true, content: [{ type: 'text', text: JSON.stringify(value) }], structuredContent: value };
}

function createMcpMutationAuthority(options) {
  let claim;
  let failure;
  try { claim = verifiedLaunchAuthority(options); } catch (error) { failure = error; }
  return {
    authorize(operation, input = {}) {
      if (failure || Number(options.now?.() ?? Date.now()) >= Date.parse(claim?.expires_at) ||
        !claim?.allowed_operations.includes(operation)) return { authorized: false, result: deniedResult() };
      const sanitizedInput = {
        ...input,
        actor_id: claim.actor_id,
        session_id: claim.session_id,
        harness: claim.harness,
        accountable_owner: claim.accountable_owner
      };
      return {
        authorized: true,
        input: sanitizedInput,
        attestation: {
          actor: {
            actorId: claim.actor_id,
            sessionId: claim.session_id,
            harness: claim.harness,
            accountableOwner: claim.accountable_owner
          },
          actorKind: 'host',
          identityAttestation: 'authenticated_host_capability',
          unattestedFields: []
        }
      };
    }
  };
}

module.exports = {
  AUTHORITY_SCHEMA, MUTATING_TOOL_NAMES, createLaunchAuthority, createMcpMutationAuthority,
  physicalProjectIdentity, verifiedLaunchAuthority
};

'use strict';

const DEFAULT_FRESHNESS_MS = 24 * 60 * 60 * 1000;

function observeMcpRuntime(registration, activity, serverVersion, options = {}) {
  const base = { ...(registration || {}) };
  if (base.registered !== true) return { ...base, runtime_verified: false };
  if (activity?.integrity?.valid !== true) return {
    ...base, status: 'registered_unverified', runtime_verified: false,
    detail: 'Definition provider registered; the project activity ledger is unavailable or invalid.'
  };
  const nowMs = Number(options.nowMs ?? Date.now());
  const freshnessMs = Number(options.freshnessMs ?? DEFAULT_FRESHNESS_MS);
  const version = String(serverVersion || '');
  const event = (activity.events || []).find(item => {
    const observedMs = Date.parse(item?.timestamp || '');
    return item?.category === 'mcp'
      && item?.source === 'pacify-x-mcp'
      && item?.status === 'succeeded'
      && item?.metadata?.server_version === version
      && Number.isFinite(observedMs)
      && nowMs >= observedMs
      && nowMs - observedMs <= freshnessMs;
  });
  if (!event) return {
    ...base, status: 'registered_unverified', runtime_verified: false,
    detail: 'Definition provider registered; no fresh successful invocation from this exact bundled server version is retained.'
  };
  return {
    ...base,
    status: 'runtime_verified',
    runtime_verified: true,
    detail: `Successful ${event.operation} invocation retained in the integrity-valid project activity ledger.`,
    verified_at: event.timestamp,
    verified_operation: event.operation,
    evidence_event_id: event.event_id
  };
}

module.exports = { DEFAULT_FRESHNESS_MS, observeMcpRuntime };

'use strict';

function admittedBaseUrl(value) {
  try {
    const url = new URL(String(value || ''));
    if (url.protocol !== 'http:' || !['127.0.0.1', 'localhost', '::1', '[::1]'].includes(url.hostname)) return null;
    return url.toString().replace(/\/$/, '');
  } catch {
    return null;
  }
}

function messageText(message) {
  return (message.content || []).map(part => typeof part?.value === 'string' ? part.value : '').filter(Boolean).join('\n');
}

function ollamaMessages(vscode, messages) {
  return messages.map(message => ({
    role: message.role === vscode.LanguageModelChatMessageRole.Assistant ? 'assistant' : 'user',
    content: messageText(message)
  })).filter(message => message.content);
}

class OllamaStreamError extends Error {
  constructor(code, message) {
    super(message);
    this.name = 'OllamaStreamError';
    this.code = code;
  }
}

const STREAM_DEFAULTS = Object.freeze({
  idleTimeoutMs: 30000,
  totalTimeoutMs: 300000,
  maxLineBytes: 1024 * 1024,
  maxStreamBytes: 16 * 1024 * 1024
});

function streamFault(code, message) { return new OllamaStreamError(code, message); }

function parseStreamEvent(line) {
  let event;
  try { event = JSON.parse(line); } catch { throw streamFault('OLLAMA_STREAM_MALFORMED', 'Ollama returned a malformed streaming event.'); }
  if (!event || Array.isArray(event) || typeof event !== 'object') throw streamFault('OLLAMA_STREAM_MALFORMED', 'Ollama returned an invalid streaming event.');
  if (event.error) throw streamFault('OLLAMA_REMOTE_ERROR', 'Ollama reported a model execution error.');
  return event;
}

class OllamaChatProvider {
  constructor(vscode, getBaseUrl, streamLimits = {}) {
    this.vscode = vscode;
    this.getBaseUrl = getBaseUrl;
    this.emitter = new vscode.EventEmitter();
    this.onDidChangeLanguageModelChatInformation = this.emitter.event;
    this.streamLimits = { ...STREAM_DEFAULTS, ...streamLimits };
  }

  refresh() { this.emitter.fire(); }
  dispose() { this.emitter.dispose(); }

  async provideLanguageModelChatInformation(_options, token) {
    const baseUrl = admittedBaseUrl(this.getBaseUrl());
    if (!baseUrl || token.isCancellationRequested) return [];
    try {
      const response = await fetch(`${baseUrl}/api/tags`, { signal: AbortSignal.timeout(3000) });
      if (!response.ok) return [];
      const payload = await response.json();
      return (payload.models || []).map(item => ({
        id: item.name,
        name: item.name,
        family: item.details?.family || item.model || item.name.split(':')[0],
        version: item.digest || item.modified_at || item.name,
        tooltip: `Local Ollama model at ${baseUrl}`,
        detail: 'Pacify-X local provider',
        maxInputTokens: 32768,
        maxOutputTokens: 8192,
        capabilities: { toolCalling: false, imageInput: false }
      }));
    } catch {
      return [];
    }
  }

  async provideLanguageModelChatResponse(model, messages, options, progress, token) {
    const baseUrl = admittedBaseUrl(this.getBaseUrl());
    if (!baseUrl) throw new Error('Pacify-X refused the Ollama URL because it is not a loopback HTTP endpoint.');
    const controller = new AbortController();
    let cancelled = Boolean(token.isCancellationRequested); let totalExpired = false;
    const cancellation = token.onCancellationRequested(() => { cancelled = true; controller.abort(); });
    const started = Date.now();
    const totalTimer = setTimeout(() => { totalExpired = true; controller.abort(); }, this.streamLimits.totalTimeoutMs);
    try {
      if (cancelled) throw streamFault('OLLAMA_CANCELLED', 'Ollama generation was cancelled.');
      const response = await fetch(`${baseUrl}/api/chat`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({
          model: model.id,
          messages: ollamaMessages(this.vscode, messages),
          stream: true,
          options: {
            num_predict: Math.min(Number(options?.modelOptions?.maxOutputTokens || model.maxOutputTokens || 8192), 8192),
            temperature: Math.max(0, Math.min(2, Number(options?.modelOptions?.temperature ?? 0)))
          }
        }),
        signal: controller.signal
      });
      if (!response.ok) throw streamFault('OLLAMA_HTTP_ERROR', `Ollama returned HTTP ${response.status}.`);
      if (!response.body) throw streamFault('OLLAMA_STREAM_MISSING', 'Ollama returned no response stream.');
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffered = ''; let totalBytes = 0; let completed = false;
      const consume = line => {
        if (!line.trim()) return;
        if (Buffer.byteLength(line, 'utf8') > this.streamLimits.maxLineBytes) throw streamFault('OLLAMA_STREAM_LIMIT', 'Ollama exceeded the streaming event size limit.');
        const event = parseStreamEvent(line);
        if (event.message?.content) progress.report(new this.vscode.LanguageModelTextPart(event.message.content));
        if (event.done === true) completed = true;
      };
      while (true) {
        if (Date.now() - started >= this.streamLimits.totalTimeoutMs) throw streamFault('OLLAMA_TOTAL_TIMEOUT', 'Ollama exceeded the total generation deadline.');
        let idleTimer;
        const idleFailure = new Promise((_, reject) => { idleTimer = setTimeout(() => { reject(streamFault('OLLAMA_IDLE_TIMEOUT', 'Ollama stopped producing stream data.')); controller.abort(); }, this.streamLimits.idleTimeoutMs); });
        let chunk;
        try { chunk = await Promise.race([reader.read(), idleFailure]); } finally { clearTimeout(idleTimer); }
        const { done, value } = chunk;
        if (done) break;
        totalBytes += value?.byteLength || 0;
        if (totalBytes > this.streamLimits.maxStreamBytes) { controller.abort(); throw streamFault('OLLAMA_STREAM_LIMIT', 'Ollama exceeded the total stream size limit.'); }
        buffered += decoder.decode(value, { stream: true });
        if (Buffer.byteLength(buffered, 'utf8') > this.streamLimits.maxLineBytes) { controller.abort(); throw streamFault('OLLAMA_STREAM_LIMIT', 'Ollama exceeded the streaming event size limit.'); }
        const lines = buffered.split(/\r?\n/); buffered = lines.pop() || '';
        for (const line of lines) consume(line);
        if (completed) { try { await reader.cancel(); } catch {} break; }
      }
      buffered += decoder.decode();
      if (buffered.trim()) consume(buffered);
      if (!completed) throw streamFault('OLLAMA_STREAM_TRUNCATED', 'Ollama closed the stream before a completion event.');
    } catch (error) {
      if (error instanceof OllamaStreamError) throw error;
      if (cancelled) throw streamFault('OLLAMA_CANCELLED', 'Ollama generation was cancelled.');
      if (totalExpired || Date.now() - started >= this.streamLimits.totalTimeoutMs) throw streamFault('OLLAMA_TOTAL_TIMEOUT', 'Ollama exceeded the total generation deadline.');
      throw streamFault('OLLAMA_STREAM_DISCONNECTED', 'The local Ollama stream disconnected unexpectedly.');
    } finally {
      clearTimeout(totalTimer);
      cancellation.dispose();
    }
  }

  async provideTokenCount(_model, value) {
    const text = typeof value === 'string' ? value : messageText(value);
    return Math.max(1, Math.ceil(text.length / 4));
  }
}

