"""Minimum sufficient proof planning from dependency and test ownership facts."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path
from typing import Iterable, Mapping

from .dependency_invalidation import compute_invalidation_cone


SCHEMA_VERSION = "px.affected-proof-plan/1.0"


def _digest(value: object) -> str:
    return hashlib.sha256(
        json.dumps(value, sort_keys=True, separators=(",", ":"), default=str).encode()
    ).hexdigest()


def _load(path: Path) -> dict[str, object]:
    return json.loads(path.read_text(encoding="utf-8"))


def build_affected_proof_plan(
    root: Path,
    changed_cards: Iterable[str],
    *,
    card_directory: str = ".engineering-bootstrap/punch-cards/cohesion-closure-20260904",
    projection_invalidation: Mapping[str, object] | None = None,
) -> dict[str, object]:
    resolved = root.resolve()
    directory = resolved / card_directory
    dag = _load(directory / "dag.json")
    nodes = {
        str(row["card_id"]): row
        for row in dag.get("nodes", ())
        if isinstance(row, Mapping)
    }
    seeds = tuple(sorted(set(map(str, changed_cards))))
    unknown = sorted(set(seeds) - set(nodes))
    if not seeds or unknown:
        raise ValueError(f"changed cards must be known and non-empty: {unknown}")
    graph = {
        "nodes": [
            {"node_id": card_id, "kind": "source", "revision": "recorded"}
            for card_id in sorted(nodes)
        ],
        "edges": [
            {"dependency": dependency, "consumer": card_id}
            for card_id, row in nodes.items()
            for dependency in row.get("dependencies", ())
        ],
    }
    cone = compute_invalidation_cone(
        graph,
        {card_id: "changed" for card_id in seeds},
        authority={"node_kinds": [{"kind": "source", "rebuild_gate": "affected_proof"}]},
    )
    affected_cards = tuple(item["node_id"] for item in cone["stale_nodes"])
    cards = {card_id: _load(directory / str(nodes[card_id]["path"])) for card_id in affected_cards}
    focused_tests: set[str] = set()
    focused_vectors: set[str] = set()
    affected_tests: set[str] = set()
    negative_cases: dict[str, tuple[str, ...]] = {}
    sections: set[str] = set()
    for card_id, card in cards.items():
        for item in card.get("focused_tests", ()):
            value = str(item)
            (focused_tests if value.endswith(".py") else focused_vectors).add(value)
        affected_tests.update(
            str(item) for item in card.get("affected_tests", ()) if str(item).endswith(".py")
        )
        negative_cases[card_id] = tuple(map(str, card.get("negative_cases", ())))
        sections.update(map(str, card.get("affected_sections", ())))
    index = _load(resolved / "registry/test_group_index.json")
    owners: dict[str, str] = {}
    for group in index.get("groups", ()):
        if not isinstance(group, Mapping):
            continue
        for member in group.get("members", ()):
            path = str(member)
            prior = owners.get(path)
            if prior and prior != group.get("group"):
                raise ValueError(f"test has multiple group owners: {path}")
            owners[path] = str(group.get("group"))
    all_tests = tuple(sorted(focused_tests | affected_tests))
    unowned = tuple(path for path in all_tests if path not in owners)
    if unowned:
        raise ValueError(f"unowned test mapping: {list(unowned)}")
    groups = tuple(sorted({owners[path] for path in all_tests}))
    stale_projections = tuple(
        sorted(
            str(row.get("output"))
            for row in (projection_invalidation or {}).get("stale", ())
            if isinstance(row, Mapping)
        )
    )
    payload = {
        "schema_version": SCHEMA_VERSION,
        "changed_cards": seeds,
        "direct_consumers": tuple(cone["direct_consumers"]),
        "transitive_consumers": tuple(cone["transitive_consumers"]),
        "affected_cards": affected_cards,
        "focused_tests": tuple(sorted(focused_tests)),
        "focused_vectors": tuple(sorted(focused_vectors)),
        "negative_cases": {key: negative_cases[key] for key in sorted(negative_cases)},
        "affected_tests": tuple(sorted(affected_tests - focused_tests)),
        "test_groups": groups,
        "sections": tuple(sorted(sections)),
        "stale_projections": stale_projections,
        "stale_evidence": tuple(
            [*(f"group:{name}" for name in groups), *(f"section:{name}" for name in sorted(sections))]
        ),
        "broad_profile_allowed_during_repair": False,
        "completion_requires_downstream_green": bool(
            cone["direct_consumers"] or cone["transitive_consumers"]
        ),
    }
    return {**payload, "plan_sha256": _digest(payload)}


def validate_proof_completion(
    plan: Mapping[str, object], completion: Mapping[str, object]
) -> dict[str, object]:
    errors: list[str] = []
    if completion.get("broad_profile_run"):
        errors.append("broad_profile_selected_during_repair")
    checks = (
        ("focused_tests", "passed_focused_tests"),
        ("affected_tests", "passed_affected_tests"),
        ("test_groups", "passed_test_groups"),
        ("sections", "passed_sections"),
        ("stale_projections", "rebuilt_projections"),
    )
    for required_key, actual_key in checks:
        missing = sorted(
            set(map(str, plan.get(required_key, ())))
            - set(map(str, completion.get(actual_key, ())))
        )
        errors.extend(f"missing_{actual_key}:{item}" for item in missing)
    negative_cards = {
        card_id
        for card_id, cases in plan.get("negative_cases", {}).items()
        if cases
    }
    missing_negative = sorted(
        negative_cards - set(map(str, completion.get("passed_negative_cards", ())))
    )
    errors.extend(f"missing_negative_proof:{item}" for item in missing_negative)
    if plan.get("completion_requires_downstream_green"):
        required = set(map(str, plan.get("direct_consumers", ()))) | set(
            map(str, plan.get("transitive_consumers", ()))
        )
        green = set(map(str, completion.get("downstream_green_cards", ())))
        errors.extend(f"downstream_not_green:{item}" for item in sorted(required - green))
    return {
        "schema_version": "px.affected-proof-completion/1.0",
        "valid": not errors,
        "errors": tuple(errors),
        "plan_sha256": plan.get("plan_sha256"),
    }

def build_affected_proof_plan(
    root: Path,
    changed_cards: Iterable[str],
    *,
    card_directory: str = ".engineering-bootstrap/punch-cards/cohesion-closure-20260904",
    projection_invalidation: Mapping[str, object] | None = None,
) -> dict[str, object]:
    resolved = root.resolve()
    directory = resolved / card_directory
    dag = _load(directory / "dag.json")
    nodes = {
        str(row["card_id"]): row
        for row in dag.get("nodes", ())
        if isinstance(row, Mapping)
    }
    seeds = tuple(sorted(set(map(str, changed_cards))))
    unknown = sorted(set(seeds) - set(nodes))
    if not seeds or unknown:
        raise ValueError(f"changed cards must be known and non-empty: {unknown}")
    graph = {
        "nodes": [
            {"node_id": card_id, "kind": "source", "revision": "recorded"}
            for card_id in sorted(nodes)
        ],
        "edges": [
            {"dependency": dependency, "consumer": card_id}
            for card_id, row in nodes.items()
            for dependency in row.get("dependencies", ())
        ],
    }
    cone = compute_invalidation_cone(
        graph,
        {card_id: "changed" for card_id in seeds},
        authority={"node_kinds": [{"kind": "source", "rebuild_gate": "affected_proof"}]},
    )
    affected_cards = tuple(item["node_id"] for item in cone["stale_nodes"])
    cards = {card_id: _load(directory / str(nodes[card_id]["path"])) for card_id in affected_cards}
    focused_tests: set[str] = set()
    focused_vectors: set[str] = set()
    affected_tests: set[str] = set()
    negative_cases: dict[str, tuple[str, ...]] = {}
    sections: set[str] = set()
    for card_id, card in cards.items():
        for item in card.get("focused_tests", ()):
            value = str(item)
            (focused_tests if value.endswith(".py") else focused_vectors).add(value)
        affected_tests.update(
            str(item) for item in card.get("affected_tests", ()) if str(item).endswith(".py")
        )
        negative_cases[card_id] = tuple(map(str, card.get("negative_cases", ())))
        sections.update(map(str, card.get("affected_sections", ())))
    index = _load(resolved / "registry/test_group_index.json")
    owners: dict[str, str] = {}
    for group in index.get("groups", ()):
        if not isinstance(group, Mapping):
            continue
        for member in group.get("members", ()):
            path = str(member)
            prior = owners.get(path)
            if prior and prior != group.get("group"):
                raise ValueError(f"test has multiple group owners: {path}")
            owners[path] = str(group.get("group"))
    all_tests = tuple(sorted(focused_tests | affected_tests))
    unowned = tuple(path for path in all_tests if path not in owners)
    if unowned:
        raise ValueError(f"unowned test mapping: {list(unowned)}")
    groups = tuple(sorted({owners[path] for path in all_tests}))
    stale_projections = tuple(
        sorted(
            str(row.get("output"))
            for row in (projection_invalidation or {}).get("stale", ())
            if isinstance(row, Mapping)
        )
    )
    payload = {
        "schema_version": SCHEMA_VERSION,
        "changed_cards": seeds,
        "direct_consumers": tuple(cone["direct_consumers"]),
        "transitive_consumers": tuple(cone["transitive_consumers"]),
        "affected_cards": affected_cards,
        "focused_tests": tuple(sorted(focused_tests)),
        "focused_vectors": tuple(sorted(focused_vectors)),
        "negative_cases": {key: negative_cases[key] for key in sorted(negative_cases)},
        "affected_tests": tuple(sorted(affected_tests - focused_tests)),
        "test_groups": groups,
        "sections": tuple(sorted(sections)),
        "stale_projections": stale_projections,
        "stale_evidence": tuple(
            [*(f"group:{name}" for name in groups), *(f"section:{name}" for name in sorted(sections))]
        ),
        "broad_profile_allowed_during_repair": False,
        "completion_requires_downstream_green": bool(
            cone["direct_consumers"] or cone["transitive_consumers"]
        ),
    }
    return {**payload, "plan_sha256": _digest(payload)}

def validate_proof_completion(
    plan: Mapping[str, object], completion: Mapping[str, object]
) -> dict[str, object]:
    errors: list[str] = []
    if completion.get("broad_profile_run"):
        errors.append("broad_profile_selected_during_repair")
    checks = (
        ("focused_tests", "passed_focused_tests"),
        ("affected_tests", "passed_affected_tests"),
        ("test_groups", "passed_test_groups"),
        ("sections", "passed_sections"),
        ("stale_projections", "rebuilt_projections"),
    )
    for required_key, actual_key in checks:
        missing = sorted(
            set(map(str, plan.get(required_key, ())))
            - set(map(str, completion.get(actual_key, ())))
        )
        errors.extend(f"missing_{actual_key}:{item}" for item in missing)
    negative_cards = {
        card_id
        for card_id, cases in plan.get("negative_cases", {}).items()
        if cases
    }
    missing_negative = sorted(
        negative_cards - set(map(str, completion.get("passed_negative_cards", ())))
    )
    errors.extend(f"missing_negative_proof:{item}" for item in missing_negative)
    if plan.get("completion_requires_downstream_green"):
        required = set(map(str, plan.get("direct_consumers", ()))) | set(
            map(str, plan.get("transitive_consumers", ()))
        )
        green = set(map(str, completion.get("downstream_green_cards", ())))
        errors.extend(f"downstream_not_green:{item}" for item in sorted(required - green))
    return {
        "schema_version": "px.affected-proof-completion/1.0",
        "valid": not errors,
        "errors": tuple(errors),
        "plan_sha256": plan.get("plan_sha256"),
    }

"""Authority-preserving adapter from Agency selection to Studio run control."""

from __future__ import annotations

from dataclasses import dataclass
import hashlib
import json
from typing import Mapping


def _digest(value: object) -> str:
    return hashlib.sha256(
        json.dumps(value, sort_keys=True, separators=(",", ":"), default=str).encode()
    ).hexdigest()


@dataclass(frozen=True, slots=True)
class StudioAgentRequest:
    schema_version: str
    specialist_id: str
    specialist_revision: str
    allowed_capabilities: tuple[str, ...]
    agency_route_receipt_sha256: str
    task_plan_id: str
    task_plan_sha256: str
    authority: tuple[str, ...]
    budgets: Mapping[str, int]
    studio_executor: str
    agency_executes_directly: bool
    request_sha256: str


def validate_agency_selection(
    selection: Mapping[str, object], registry: Mapping[str, object]
) -> dict[str, object]:
    errors: list[str] = []
    agents = {
        str(item.get("agent_id")): item
        for item in registry.get("agents", ())
        if isinstance(item, Mapping)
    }
    primary = str(selection.get("primary_agent", ""))
    if not selection.get("valid"):
        errors.append("agency_selection_invalid")
    if selection.get("authority_granted") is not False:
        errors.append("agency_selection_must_not_grant_authority")
    if primary not in agents:
        errors.append("unknown_specialist")
    if not str(selection.get("route_receipt_sha256", "")):
        errors.append("agency_route_receipt_missing")
    if primary and not any(
        isinstance(item, Mapping) and item.get("agent_id") == primary
        for item in selection.get("score_evidence", ())
    ):
        errors.append("selected_specialist_missing_score_evidence")
    return {"valid": not errors, "errors": tuple(errors), "agent": agents.get(primary)}


def compile_studio_agent_request(
    selection: Mapping[str, object],
    registry: Mapping[str, object],
    task_plan: object,
    *,
    requested_authority: tuple[str, ...],
    available_authority: tuple[str, ...],
    budgets: Mapping[str, int],
    budget_ceilings: Mapping[str, int],
) -> StudioAgentRequest:
    validation = validate_agency_selection(selection, registry)
    if not validation["valid"]:
        raise ValueError("invalid Agency selection: " + ",".join(validation["errors"]))
    agent = validation["agent"]
    assert isinstance(agent, Mapping)
    authority = tuple(sorted(set(map(str, requested_authority))))
    if not authority or not set(authority) <= set(map(str, available_authority)):
        raise PermissionError("Agency-to-Studio translation widens authority")
    normalized_budgets = {str(key): int(value) for key, value in sorted(budgets.items())}
    if not normalized_budgets or any(
        value < 1 or value > int(budget_ceilings.get(key, 0))
        for key, value in normalized_budgets.items()
    ):
        raise PermissionError("Agency-to-Studio translation widens or omits budget")
    plan = task_plan.as_dict() if hasattr(task_plan, "as_dict") else dict(task_plan)
    plan_id = str(plan.get("plan_id", ""))
    plan_sha = str(plan.get("plan_sha256", ""))
    if not plan_id or len(plan_sha) != 64:
        raise ValueError("exact task plan binding is required")
    revision_payload = {
        "agent_id": agent.get("agent_id"),
        "body_sha256": agent.get("body_sha256"),
        "manifest_sha256": agent.get("manifest_sha256"),
    }
    if any(len(str(revision_payload[key] or "")) != 64 for key in ("body_sha256", "manifest_sha256")):
        raise ValueError("specialist revision is unpinned")
    specialist_revision = _digest(revision_payload)
    base = {
        "schema_version": "px.agency-studio-agent-request/1.0",
        "specialist_id": str(agent["agent_id"]),
        "specialist_revision": specialist_revision,
        "allowed_capabilities": tuple(
            sorted(set(map(str, agent.get("capabilities", ()))))
        ),
        "agency_route_receipt_sha256": str(selection["route_receipt_sha256"]),
        "task_plan_id": plan_id,
        "task_plan_sha256": plan_sha,
        "authority": authority,
        "budgets": normalized_budgets,
        "studio_executor": "runtime.studio_run_control.DurableRunControl.create",
        "agency_executes_directly": False,
    }
    return StudioAgentRequest(**base, request_sha256=_digest(base))


def submit_studio_agent_request(controller: object, request: StudioAgentRequest):
    """Submit only through Studio's existing durable run-control owner."""
    create = getattr(controller, "create", None)
    if not callable(create):
        raise TypeError("Studio DurableRunControl owner is required")
    return create(
        kind="agent",
        subject_id=request.specialist_id,
        version=f"agency-{request.specialist_revision[:12]}",
        owner="agency-studio-adapter",
        revision_sha256=request.specialist_revision,
        request_sha256=request.request_sha256,
        checkpoint={
            "phase": "queued_from_agency",
            "task_plan_id": request.task_plan_id,
            "task_plan_sha256": request.task_plan_sha256,
            "authority": list(request.authority),
            "budgets": dict(request.budgets),
        },
    )

