def validate_architecture_invariants(root: Path) -> dict[str, object]:
    """Evaluate the complete current-tree invariant set without mutating it."""
    root = root.resolve(strict=True)
    from .authority_topology import validate_authority_topology
    from .capability_maturity import load_maturity_policy, validate_maturity_policy
    from .dependency_invalidation import validate_dependency_authority
    from .evidence_claims import evidence_type_compatible, load_evidence_type_policy
    from .primitive_authority import validate_primitive_authority
    from .primitive_lint import validate_primitive_exceptions
    from .projection_dependencies import revision_for_path

    def load(relative: str):
        try:
            return json.loads((root / relative).read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return None

    semantic = load("registry/semantic_capability_index.json")
    profiles = semantic.get("records", ()) if isinstance(semantic, Mapping) else ()
    semantic_ok = bool(profiles) and all(
        isinstance(item, Mapping)
        and isinstance(item.get("semantic_profile"), Mapping)
        and bool(item["semantic_profile"].get("positive_intents"))
        for item in profiles
    )
    projection = load("registry/projection_dependencies.json")
    try:
        projection_ok = isinstance(projection, Mapping) and all(
            isinstance(item, Mapping)
            and bool(item.get("output_revision"))
            and revision_for_path(root, str(item.get("output")))
            == item.get("output_revision")
            and all(
                isinstance(dependency, Mapping)
                and revision_for_path(root, str(dependency.get("path")))
                == dependency.get("revision")
                for dependency in item.get("dependencies", ())
            )
            for item in projection.get("projections", ())
        )
    except (OSError, ValueError):
        projection_ok = False
    primitive = load("registry/primitive_authority.json")
    primitive_report = validate_primitive_authority(root)
    primitive_ok = primitive_report["valid"]
    duplicate_ok = (
        isinstance(primitive, Mapping)
        and validate_primitive_exceptions(primitive)["valid"]
    )
    try:
        load_evidence_type_policy(root)
        evidence_ok = (
            evidence_type_compatible(root, "runtime_effect", "feature.runtime_effect")
            and not evidence_type_compatible(root, "ui_interaction", "feature.runtime_effect")
        )
    except (OSError, ValueError, json.JSONDecodeError):
        evidence_ok = False
    conformance_ok = all(
        (root / path).is_file()
        for path in (
            "tests/coordination_conformance/coordination_state_conformance_vectors.json",
            "tests/coordination_conformance/provider_execution_policy_vectors.json",
        )
    )
    dependency = load("registry/dependency_authority.json")
    dependency_ok = (
        isinstance(dependency, Mapping)
        and validate_dependency_authority(root, dependency)["valid"]
    )
    release = load(".engineering-bootstrap/processing-order/release-identity.json")
    release_ok = not (
        isinstance(release, Mapping)
        and release.get("state") in {"active", "certified"}
        and isinstance(release.get("identity"), Mapping)
        and not release["identity"].get("source_product_digest")
    )
    invalidation_ok = isinstance(projection, Mapping) and all(
        isinstance(item, Mapping)
        and item.get("invalidation_rule") == "any_dependency_revision_change"
        and item.get("rebuild_gate") in {"rebuild_before_use", "block_until_rebuilt"}
        for item in projection.get("projections", ())
    )
    try:
        maturity = load_maturity_policy(root)
        maturity_ok = validate_maturity_policy(maturity)["valid"] and all(
            item.get("required_evidence_type")
            and item.get("required_authority_class") in {"installed_host", "external_authority"}
            for item in maturity.get("levels", ())
            if item.get("level") in {"L5", "L6"}
        )
    except (OSError, ValueError, json.JSONDecodeError):
        maturity_ok = False
    topology_ok = validate_authority_topology(root)["valid"]
    checks = {
        INVARIANT_IDS[0]: semantic_ok,
        INVARIANT_IDS[1]: projection_ok,
        INVARIANT_IDS[2]: primitive_ok,
        INVARIANT_IDS[3]: duplicate_ok,
        INVARIANT_IDS[4]: evidence_ok,
        INVARIANT_IDS[5]: conformance_ok,
        INVARIANT_IDS[6]: dependency_ok,
        INVARIANT_IDS[7]: all(
            (root / path).is_file()
            for path in (
                "contracts/task_execution_plan.schema.json",
                "contracts/model_attachment.schema.json",
            )
        ),
        INVARIANT_IDS[8]: release_ok,
        INVARIANT_IDS[9]: evidence_ok,
        INVARIANT_IDS[10]: invalidation_ok,
        INVARIANT_IDS[11]: maturity_ok,
        INVARIANT_IDS[12]: topology_ok,
    }
    return architecture_invariant_report(checks)

"""Build the closed-world registry/workflow ownership and reachability inventory."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path

from .repository_scope import is_external_environment_relative


def _sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _load(path: Path) -> dict:
    return json.loads(path.read_text(encoding="utf-8"))


def build_artifact_reachability(root: Path) -> dict:
    root = root.resolve()
    binding_doc = _load(root / "registry/workflow_execution_bindings.json")
    bindings = {item["path"]: item for item in binding_doc["bindings"]}
    records = []
    recorded_paths: set[str] = set()

    def record(value: dict) -> None:
        path = str(value["path"])
        if is_external_environment_relative(path):
            return
        if path in recorded_paths:
            raise ValueError(f"duplicate artifact reachability record: {path}")
        recorded_paths.add(path)
        records.append(value)

    registry_owners = {
        "artifact_reachability.json": "runtime/artifact_reachability.py",
        "contract_ownership.json": "runtime/contracts.py",
        "corrective_release_ledger.json": "runtime/corrective_release.py",
        "declared_suite_authoritative_tools.json": "runtime/exact_tool_certification.py",
        "effect_surface_ownership.json": "runtime/effect_surface.py",
        "full_repair_ledger.json": "runtime/full_repair.py",
        "integrations.json": "runtime/integration_registry.py",
        "project_stream_handlers.json": "runtime/project_stream_orchestrator.py",
        "project_stream_orchestrations.json": "runtime/project_stream_orchestrator.py",
        "python_surface_ownership.json": "runtime/python_surface_certification.py",
        "registry_envelope_inventory.json": "runtime/registry_envelope.py",
        "semantic_capability_index.json": "runtime/semantic_index.py",
        "skill_catalog.toml": "runtime/registry.py",
        "skill_orchestrations.json": "runtime/skill_navigator.py",
        "test_profiles.json": "runtime/test_profiles.py",
        "workflow_execution_bindings.json": "runtime/structural_integrity.py",
    }
    for path in sorted(
        (root / "registry").rglob("*"), key=lambda item: item.as_posix().casefold()
    ):
        if (
            not path.is_file()
            or path.name == "artifact_reachability.json"
            # This operational index hashes artifact_reachability as a test
            # input. Including it here would create an unsatisfiable digest
            # cycle. Its topology and content are governed independently by
            # runtime.test_profiles and registry-envelope validation.
            or path.name == "test_group_index.json"
            # This live projection hashes the test receipts whose input hashes
            # include artifact_reachability. Indexing it here would create a
            # second unsatisfiable digest cycle. The evidence index remains
            # governed by its own builder and registry-envelope invariants.
            or path.name == "current_evidence_index.json"
            # Completion status is likewise a live projection over current
            # section/group receipts. Hashing it into the static artifact graph
            # would make advancing a receipt invalidate the graph it summarizes.
            or path.name == "completion_status.json"
            # World state binds the final product digest while remaining a
            # mutable, bounded startup projection. Hashing it into the static
            # reachability graph would feed its source revision back into that
            # digest and create an unsatisfiable cycle.
            or path.name == "px_world_state.json"
            # The operational gap ledger head and snapshot are live projections
            # advanced by every mandatory work admission. Hashing either into
            # the static graph would make the admission for a verification run
            # invalidate that graph immediately before the run starts.
            or path.name
            in {
                "operational_gap_ledger.head.json",
                "operational_gap_ledger.snapshot.json",
            }
            # The exact engine manifest hashes artifact_reachability. Including
            # the manifest here would create a two-document digest cycle.
            or path.name == "engine_identity.json"
            or path.suffix.casefold() not in {".json", ".toml", ".yaml", ".yml"}
        ):
            continue
        relative = path.relative_to(root).as_posix()
        owner = registry_owners.get(path.name, "runtime/structural_integrity.py")
        record(
            {
                "path": relative,
                "sha256": _sha(path),
                "kind": "registry",
                "owner": owner,
                "reachability": "release_validated",
            }
        )
    project_stream = _load(root / "registry/project_stream_handlers.json")
    project_bindings = {
        item["orchestration_id"]: item for item in project_stream["workflows"]
    }
    for path in sorted(
        (root / "orchestration/workflows").rglob("*.yaml"),
        key=lambda item: item.as_posix().casefold(),
    ):
        relative = path.relative_to(root).as_posix()
        if "project_stream" in path.parts:
            binding = project_bindings.get(path.stem)
            if binding is None:
                entrypoint, mode = "", "unbound"
            else:
                dotted = str(binding["handler"])
                module, attribute = dotted.rsplit(".", 1)
                entrypoint, mode = f"{module}:{attribute}", str(binding["status"])
        else:
            binding = bindings.get(relative, {})
            entrypoint, mode = (
                str(binding.get("entrypoint", "")),
                str(binding.get("mode", "unbound")),
            )
        record(
            {
                "path": relative,
                "sha256": _sha(path),
                "kind": "orchestration",
                "owner": "runtime/structural_integrity.py",
                "reachability": mode,
                "entrypoint": entrypoint,
            }
        )

    provider_root = root / "providers" / "agency_agents"
    if provider_root.is_dir():
        for path in sorted(
            provider_root.rglob("*"), key=lambda item: item.as_posix().casefold()
        ):
            if not path.is_file():
                continue
            relative = path.relative_to(root).as_posix()
            if "/agents/" in f"/{relative}":
                reachability = "lazy_selected_agent_body"
            elif "/manifests/" in f"/{relative}":
                reachability = "lazy_selected_agent_manifest"
            else:
                reachability = "provider_license"
            record(
                {
                    "path": relative,
                    "sha256": _sha(path),
                    "kind": "provider_asset",
                    "owner": "runtime/agent_provider.py",
                    "reachability": reachability,
                }
            )

    # YAML is executable configuration or a user-facing template. Every YAML
    # file therefore needs an explicit owner even when it is not an orchestration.
    yaml_paths = {*root.rglob("*.yaml"), *root.rglob("*.yml")}
    for path in sorted(yaml_paths, key=lambda item: item.as_posix().casefold()):
        relative = path.relative_to(root).as_posix()
        if relative in recorded_paths:
            continue
        if relative.startswith(".px/skills/") and relative.endswith(
            "/agents/openai.yaml"
        ):
            skill_id = relative.split("/")[2]
            owner = f".px/skills/{skill_id}/SKILL.md"
            reachability = "lazy_skill_interface"
        elif (
            relative
            == "bootstrap/commissioning/reference/questionnaire_answers.template.yaml"
        ):
            owner = "bootstrap/commissioning/reference/README_START_HERE.md"
            reachability = "documented_commissioning_template"
        elif relative.startswith("templates/project_stream/"):
            owner = "runtime/project_control_plane.py"
            reachability = "runtime_validated_template"
        else:
            owner = "runtime/structural_integrity.py"
            reachability = "unclassified_yaml"
        record(
            {
                "path": relative,
                "sha256": _sha(path),
                "kind": "yaml",
                "owner": owner,
                "reachability": reachability,
            }
        )
    return {"schema_version": "1.0", "record_count": len(records), "records": records}

"""Deterministic controls for evidence-first commissioning, containment, and assurance."""

from __future__ import annotations

from dataclasses import asdict, dataclass
import hashlib
import json
from pathlib import PurePosixPath
from typing import Mapping, Sequence


@dataclass(frozen=True, slots=True)
class AssuranceResult:
    control_id: str
    decision: str
    reasons: tuple[str, ...]
    outputs: Mapping[str, object]

    def as_dict(self) -> dict[str, object]:
        return asdict(self)


ASSURANCE_CONTROLS = (
    "audit-ai-runtime-assurance",
    "certify-skeptical-engineering",
    "commission-evidence-first-project",
    "discover-environment-safely",
    "propose-change-intelligence",
    "quarantine-external-tools",
    "supervise-contained-execution",
)

MUTATING_EFFECTS = {
    "write_workspace",
    "write_global",
    "install_project",
    "install_global",
    "network",
    "service_start",
    "migration",
    "remote_git",
    "mcp_connect",
    "auth_change",
    "destructive",
    "load_test",
    "chaos_test",
    "red_team",
}
APPROVED_CREDENTIAL_STORES = {
    "git-credential-manager",
    "windows-credential-manager",
    "keychain",
    "secret-service",
    "encrypted-secret-store",
    "ephemeral-environment-injection",
}


def _stable(value: object) -> str:
    return hashlib.sha256(
        json.dumps(value, sort_keys=True, separators=(",", ":"), default=str).encode()
    ).hexdigest()


def _strings(values: object) -> tuple[str, ...]:
    return tuple(sorted({str(value) for value in values or ()}))


def discover_environment(payload: Mapping[str, object]) -> AssuranceResult:
    observed = {
        str(key): dict(value)
        for key, value in dict(payload.get("observed_tools", {})).items()
    }
    required = set(map(str, payload.get("required_tools", ())))
    missing = tuple(
        sorted(name for name in required if not observed.get(name, {}).get("available"))
    )
    proposals = [dict(item) for item in payload.get("proposed_changes", ())]
    approval_required = tuple(
        sorted(
            str(item.get("id", "unnamed"))
            for item in proposals
            if str(item.get("effect")) in MUTATING_EFFECTS
        )
    )
    credential_store = str(payload.get("credential_store", ""))
    credential_warning = None
    if credential_store and credential_store not in APPROVED_CREDENTIAL_STORES:
        credential_warning = "credential_store_not_approved"
    todo_records = tuple(
        sorted(str(item) for item in payload.get("todo_stub_findings", ()))
    )
    decision = "approval_required" if approval_required else "report_only"
    reasons = tuple(
        name
        for name, active in (
            ("required_tools_missing", bool(missing)),
            ("mutating_setup_requires_approval", bool(approval_required)),
            ("credential_store_not_approved", credential_warning is not None),
        )
        if active
    )
    return AssuranceResult(
        "discover-environment-safely",
        decision,
        reasons,
        {
            "observed_tools": tuple(
                sorted(
                    (
                        name,
                        bool(item.get("available")),
                        str(item.get("version", "unknown")),
                    )
                    for name, item in observed.items()
                )
            ),
            "missing_required_tools": missing,
            "approval_required_for": approval_required,
            "todo_stub_findings": todo_records,
            "credential_guidance": "use_os_or_ephemeral_secret_store"
            if credential_warning
            else "approved_or_not_requested",
            "executed_changes": False,
            "inventory_hash": _stable(observed),
        },
    )


def commission_project(payload: Mapping[str, object]) -> AssuranceResult:
    required = (
        "goal",
        "users",
        "data",
        "accessibility",
        "security",
        "integrations",
        "operations",
        "acceptance",
    )
    answers = dict(payload.get("answers", {}))
    missing = tuple(field for field in required if not answers.get(field))
    facts = [dict(item) for item in payload.get("facts", ())]
    invalid_facts = tuple(
        sorted(
            str(item.get("id", "unnamed")) for item in facts if not item.get("evidence")
        )
    )
    assumptions = [dict(item) for item in payload.get("assumptions", ())]
    unknowns = [dict(item) for item in payload.get("unknowns", ())]
    high_risk = tuple(
        sorted(
            str(item.get("id", "unnamed"))
            for item in (*assumptions, *unknowns)
            if str(item.get("risk", "low")) in {"high", "critical"}
            and not item.get("approved")
        )
    )
    reasons = tuple(
        name
        for name, active in (
            ("commissioning_sections_missing", bool(missing)),
            ("facts_without_evidence", bool(invalid_facts)),
            ("high_risk_unknowns_unresolved", bool(high_risk)),
        )
        if active
    )
    ledger = tuple(
        sorted(
            (
                str(item.get("id", "unnamed")),
                str(item.get("confidence", "unknown")),
                bool(item.get("confirmed")),
                str(item.get("risk", "low")),
            )
            for item in assumptions
        )
    )
    return AssuranceResult(
        "commission-evidence-first-project",
        "review_ready" if not reasons else "blocked",
        reasons,
        {
            "missing_sections": missing,
            "invalid_fact_ids": invalid_facts,
            "unresolved_high_risk_ids": high_risk,
            "assumption_ledger": ledger,
            "legal_compliance_claim": False,
            "implementation_authorized": not high_risk
            and not missing
            and bool(payload.get("human_acceptance")),
            "brief_hash": _stable(
                {
                    "answers": answers,
                    "facts": facts,
                    "assumptions": assumptions,
                    "unknowns": unknowns,
                }
            ),
        },
    )


def _path_within(path: str, roots: Sequence[str]) -> bool:
    candidate = PurePosixPath(path.replace("\\", "/"))
    for root in roots:
        allowed = PurePosixPath(str(root).replace("\\", "/"))
        if candidate == allowed or allowed in candidate.parents:
            return True
    return False


def supervise_action(payload: Mapping[str, object]) -> AssuranceResult:
    effects = set(map(str, payload.get("effects", ())))
    allowed_effects = set(map(str, payload.get("allowed_effects", ())))
    paths = tuple(map(str, payload.get("target_paths", ())))
    owned = tuple(map(str, payload.get("owned_paths", ())))
    budgets = dict(payload.get("budget", {}))
    limits = dict(payload.get("limits", {}))
    reasons: list[str] = []
    undeclared = tuple(sorted(effects - allowed_effects))
    if undeclared:
        reasons.append("effect_not_allowed")
    outside = (
        tuple(sorted(path for path in paths if not _path_within(path, owned)))
        if paths
        else ()
    )
    if outside:
        reasons.append("target_outside_owned_scope")
    exceeded = tuple(
        sorted(
            key
            for key, value in budgets.items()
            if key in limits and float(value) > float(limits[key])
        )
    )
    if exceeded:
        reasons.append("budget_exceeded")
    approval_needed = bool(effects & MUTATING_EFFECTS)
    if approval_needed and payload.get("approval") is not True:
        reasons.append("approval_missing")
    if payload.get("policy_override_requested"):
        reasons.append("policy_override_forbidden")
    decision = (
        "allow"
        if not reasons
        else ("escalate" if reasons == ["approval_missing"] else "block")
    )
    return AssuranceResult(
        "supervise-contained-execution",
        decision,
        tuple(reasons),
        {
            "undeclared_effects": undeclared,
            "outside_scope": outside,
            "exceeded_budgets": exceeded,
            "approval_required": approval_needed,
            "audit_record_hash": _stable(payload),
        },
    )


def quarantine_tool(payload: Mapping[str, object]) -> AssuranceResult:
    required = (
        "source",
        "sha256",
        "license",
        "permissions",
        "vulnerabilities",
        "policy_compatible",
    )
    missing = tuple(field for field in required if payload.get(field) in (None, "", ()))
    vulnerabilities = tuple(str(item) for item in payload.get("vulnerabilities", ()))
    malicious = tuple(str(item) for item in payload.get("malicious_indicators", ()))
    reasons: list[str] = []
    if missing:
        reasons.append("static_evidence_missing")
    if vulnerabilities:
        reasons.append("known_vulnerabilities")
    if malicious:
        reasons.append("malicious_indicators")
    if payload.get("policy_compatible") is not True:
        reasons.append("policy_incompatible_or_unknown")
    dynamic_requested = bool(payload.get("dynamic_analysis_requested"))
    if dynamic_requested and not (
        payload.get("sandbox_approved") is True
        and payload.get("synthetic_secrets_only") is True
        and payload.get("network_policy_declared") is True
    ):
        reasons.append("dynamic_analysis_not_contained")
    if payload.get("approval") is not True:
        reasons.append("explicit_approval_missing")
    decision = "admit" if not reasons else "quarantine"
    return AssuranceResult(
        "quarantine-external-tools",
        decision,
        tuple(reasons),
        {
            "execution": "allowed_after_admission"
            if decision == "admit"
            else "blocked",
            "integration": "allowed_after_admission"
            if decision == "admit"
            else "blocked",
            "missing_static_fields": missing,
            "vulnerability_count": len(vulnerabilities),
            "malicious_indicator_count": len(malicious),
            "dynamic_phase_separately_approved": dynamic_requested
            and "dynamic_analysis_not_contained" not in reasons,
            "intake_hash": _stable(payload),
        },
    )


LEVEL_REQUIREMENTS = {
    0: {"inventory"},
    1: {"inventory", "baseline"},
    2: {"inventory", "baseline", "functional"},
    3: {"inventory", "baseline", "functional", "security", "dependency"},
    4: {
        "inventory",
        "baseline",
        "functional",
        "security",
        "dependency",
        "user_workflows",
        "authorization",
    },
    5: {
        "inventory",
