def supervise_action(payload: Mapping[str, object]) -> AssuranceResult:
    effects = set(map(str, payload.get("effects", ())))
    allowed_effects = set(map(str, payload.get("allowed_effects", ())))
    paths = tuple(map(str, payload.get("target_paths", ())))
    owned = tuple(map(str, payload.get("owned_paths", ())))
    budgets = dict(payload.get("budget", {}))
    limits = dict(payload.get("limits", {}))
    reasons: list[str] = []
    undeclared = tuple(sorted(effects - allowed_effects))
    if undeclared:
        reasons.append("effect_not_allowed")
    outside = (
        tuple(sorted(path for path in paths if not _path_within(path, owned)))
        if paths
        else ()
    )
    if outside:
        reasons.append("target_outside_owned_scope")
    exceeded = tuple(
        sorted(
            key
            for key, value in budgets.items()
            if key in limits and float(value) > float(limits[key])
        )
    )
    if exceeded:
        reasons.append("budget_exceeded")
    approval_needed = bool(effects & MUTATING_EFFECTS)
    if approval_needed and payload.get("approval") is not True:
        reasons.append("approval_missing")
    if payload.get("policy_override_requested"):
        reasons.append("policy_override_forbidden")
    decision = (
        "allow"
        if not reasons
        else ("escalate" if reasons == ["approval_missing"] else "block")
    )
    return AssuranceResult(
        "supervise-contained-execution",
        decision,
        tuple(reasons),
        {
            "undeclared_effects": undeclared,
            "outside_scope": outside,
            "exceeded_budgets": exceeded,
            "approval_required": approval_needed,
            "audit_record_hash": _stable(payload),
        },
    )

def load_classified_json(
    root: Path,
    path: Path,
    *,
    artifact_kind: str,
    allowed_root: Path,
    quarantine_root: Path,
    validator: Callable[[Mapping[str, object]], None] | None = None,
) -> dict[str, Any]:
    """Load classified JSON; preserve corrupt authority and never invent fallback."""
    classes = load_state_classifications(root)
    record = classes.get(artifact_kind)
    if record is None:
        raise AuthoritativeStateError(f"unclassified state refused: {artifact_kind}")
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(value, dict):
            raise ValueError("state root must be an object")
        if validator is not None:
            validator(value)
    except (OSError, UnicodeError, json.JSONDecodeError, TypeError, ValueError) as error:
        if record["classification"] == "derived":
            return {
                "schema_version": "1.0",
                "status": "rebuild_required",
                "artifact_kind": artifact_kind,
                "path": path.resolve().as_posix(),
                "error_type": type(error).__name__,
                "data": None,
            }
        if not path.is_file():
            raise AuthoritativeStateError(
                f"authoritative state unavailable: {artifact_kind}"
            ) from error
        receipt = _quarantine_corrupt(
            path,
            artifact_kind=artifact_kind,
            allowed_root=allowed_root,
            quarantine_root=quarantine_root,
            parse_error=error,
        )
        raise AuthoritativeStateError(
            f"authoritative state quarantined: {artifact_kind}", receipt=receipt
        ) from error
    return {
        "schema_version": "1.0",
        "status": "valid",
        "artifact_kind": artifact_kind,
        "path": path.resolve().as_posix(),
        "data": value,
    }

def load_state_classifications(root: Path) -> dict[str, dict[str, str]]:
    """Load and strictly validate the state-artifact classification registry."""
    path = root / "registry" / "state_artifact_classes.json"
    payload = json.loads(path.read_text(encoding="utf-8"))
    if set(payload) != {"schema_version", "policy", "classes"}:
        raise ValueError("state classification registry fields are not exact")
    if payload["schema_version"] != "1.0" or not isinstance(payload["classes"], list):
        raise ValueError("state classification registry header is invalid")
    result: dict[str, dict[str, str]] = {}
    required = {"artifact_kind", "classification", "owner", "corruption_disposition"}
    for raw in payload["classes"]:
        if not isinstance(raw, dict) or set(raw) != required:
            raise ValueError("state classification record fields are not exact")
        record = {key: str(value) for key, value in raw.items()}
        kind = record["artifact_kind"]
        if not kind or kind in result:
            raise ValueError(f"duplicate or empty artifact kind: {kind}")
        expected = {
            "authoritative": "quarantine_fail_closed",
            "derived": "rebuild",
        }.get(record["classification"])
        if expected is None or record["corruption_disposition"] != expected:
            raise ValueError(f"invalid classification/disposition for {kind}")
        if not declared_file_available(root, record["owner"]):
            raise ValueError(f"missing artifact owner for {kind}: {record['owner']}")
        result[kind] = record
    return result

"""Machine-readable ownership topology for effect-producing PX operations."""

from __future__ import annotations

import ast
import json
from pathlib import Path
from typing import Any, Mapping

from .paths import resolve_repository_relative


SCHEMA_VERSION = "px.authority-topology/1.0"
REGISTRY_PATH = Path("registry/authority_topology.json")
REQUIRED_EFFECT_TYPES = frozenset(
    {
        "agent_execution",
        "filesystem_mutation",
        "ledger_append",
        "network",
        "process",
        "project_transfer",
        "provider_execution",
        "release_identity",
        "skill_promotion",
    }
)


def _load(root: Path) -> dict[str, Any]:
    value = json.loads((root / REGISTRY_PATH).read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise ValueError("authority topology must be an object")
    return value


def _python_symbols(path: Path) -> set[str]:
    tree = ast.parse(path.read_text(encoding="utf-8-sig"), filename=str(path))
    return {
        node.name
        for node in ast.walk(tree)
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef))
    }


def _owner_errors(root: Path, value: object, label: str) -> list[str]:
    if not isinstance(value, Mapping):
        return [f"{label} must be an object"]
    errors: list[str] = []
    language = value.get("language")
    relative = value.get("path")
    symbol = value.get("symbol")
    if language not in {"python", "javascript"}:
        errors.append(f"{label}.language must be python or javascript")
    path = resolve_repository_relative(root, relative)
    if path is None or not path.is_file():
        errors.append(f"{label}.path is missing or outside the repository")
        return errors
    if not isinstance(symbol, str) or not symbol:
        errors.append(f"{label}.symbol is required")
    elif language == "python":
        try:
            if symbol not in _python_symbols(path):
                errors.append(f"{label}.symbol is not defined by {relative}")
        except (OSError, SyntaxError, UnicodeError) as error:
            errors.append(f"{label}.path cannot be inspected: {error}")
    else:
        try:
            source = path.read_text(encoding="utf-8")
            if symbol not in source:
                errors.append(f"{label}.symbol is not present in {relative}")
        except (OSError, UnicodeError) as error:
            errors.append(f"{label}.path cannot be inspected: {error}")
    return errors


def validate_authority_topology(
    root: Path, payload: Mapping[str, Any] | None = None
) -> dict[str, object]:
    """Validate singular gates, rollback, receipts, and bypass visibility."""
    root = root.resolve(strict=True)
    try:
        topology = dict(payload) if payload is not None else _load(root)
    except (OSError, UnicodeError, ValueError, json.JSONDecodeError) as error:
        return {"schema_version": SCHEMA_VERSION, "valid": False, "errors": [str(error)]}
    errors: list[str] = []
    if topology.get("schema_version") != SCHEMA_VERSION:
        errors.append(f"schema_version must be {SCHEMA_VERSION}")
    effects = topology.get("effects")
    if not isinstance(effects, list):
        effects = []
        errors.append("effects must be a list")
    seen: set[str] = set()
    for index, effect in enumerate(effects):
        label = f"effects[{index}]"
        if not isinstance(effect, Mapping):
            errors.append(f"{label} must be an object")
            continue
        effect_type = effect.get("effect_type")
        if not isinstance(effect_type, str) or not effect_type:
            errors.append(f"{label}.effect_type is required")
            continue
        if effect_type in seen:
            errors.append(f"two authoritative gates declared for {effect_type}")
        seen.add(effect_type)
        errors.extend(_owner_errors(root, effect.get("authoritative_gate"), f"{effect_type}.authoritative_gate"))
        errors.extend(_owner_errors(root, effect.get("rollback_owner"), f"{effect_type}.rollback_owner"))
        errors.extend(_owner_errors(root, effect.get("bypass_detector"), f"{effect_type}.bypass_detector"))
        receipt = effect.get("receipt_contract")
        if not isinstance(receipt, str) or not receipt:
            errors.append(f"{effect_type}.receipt_contract is required")
        elif receipt.startswith("contracts/"):
            receipt_path = resolve_repository_relative(root, receipt)
            if receipt_path is None or not receipt_path.is_file():
                errors.append(f"{effect_type}.receipt_contract is missing")
        runtimes = effect.get("runtimes")
        if not isinstance(runtimes, list) or not runtimes:
            errors.append(f"{effect_type}.runtimes must be a non-empty list")
        elif len(set(map(str, runtimes))) > 1:
            vectors = effect.get("conformance_vectors")
            vector_path = resolve_repository_relative(root, vectors)
            if vector_path is None or not vector_path.is_file():
                errors.append(f"{effect_type} cross-runtime semantics lack conformance vectors")
    missing = sorted(REQUIRED_EFFECT_TYPES - seen)
    unknown = sorted(seen - REQUIRED_EFFECT_TYPES)
    if missing:
        errors.append(f"missing effect types: {missing}")
    if unknown:
        errors.append(f"unknown effect types: {unknown}")
    if topology.get("effect_count") != len(effects):
        errors.append("effect_count does not match effects")
    return {
        "schema_version": SCHEMA_VERSION,
        "valid": not errors,
        "effect_count": len(effects),
        "errors": errors,
    }


def resolve_effect_authority(root: Path, effect_type: str) -> dict[str, Any]:
    topology = _load(root.resolve(strict=True))
    report = validate_authority_topology(root, topology)
    if not report["valid"]:
        raise ValueError("authority topology is invalid: " + "; ".join(report["errors"]))
    matches = [item for item in topology["effects"] if item["effect_type"] == effect_type]
    if len(matches) != 1:
        raise KeyError(f"unknown effect type {effect_type!r}")
    return dict(matches[0])

def resolve_effect_authority(root: Path, effect_type: str) -> dict[str, Any]:
    topology = _load(root.resolve(strict=True))
    report = validate_authority_topology(root, topology)
    if not report["valid"]:
        raise ValueError("authority topology is invalid: " + "; ".join(report["errors"]))
    matches = [item for item in topology["effects"] if item["effect_type"] == effect_type]
    if len(matches) != 1:
        raise KeyError(f"unknown effect type {effect_type!r}")
    return dict(matches[0])

def cluster_coverage_frontier(
    queries: Iterable[str], *, min_chars: int = 12
) -> tuple[dict[str, Any], ...]:
    counts: Counter[str] = Counter()
    for raw in queries:
        normalized = normalize_query(raw)
        if len(normalized) < min_chars:
            continue
        counts[normalized] += 1
    return tuple(
        {
            "representative": key,
            "normalized": key,
            "query_sha256": hashlib.sha256(key.encode("utf-8")).hexdigest(),
            "demand_count": count,
            "oracle_known": False,
            "candidate_only": True,
        }
        for key, count in sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    )

def run_behavioral_probe(
    controls: Iterable[Control],
    invoke: Callable[[Any], Any],
    compare: Callable[[Any, Any], bool],
    *,
    max_latency_ms: float | None = None,
) -> ProbeResult:
    declared = tuple(controls)
    roles = {item.role for item in declared}
    reasons: list[str] = []
    if max_latency_ms is not None and max_latency_ms < 0:
        raise ValueError("maximum latency must be non-negative")
    if len({item.control_id for item in declared}) != len(declared):
        reasons.append("duplicate_control_id")
    if roles - ({"positive"} | DISCRIMINATING_ROLES):
        reasons.append("invalid_control_role")
    if "positive" not in roles:
        reasons.append("missing_positive_control")
    if not roles.intersection(DISCRIMINATING_ROLES):
        reasons.append("missing_discriminating_control")
    results: list[ControlResult] = []
    for control in declared:
        started = time.perf_counter()
        try:
            observed = invoke(control.payload)
            error_type = None
            passed = bool(compare(observed, control.oracle))
        except Exception as error:  # sanitized; evidence layer owns details
            observed = None
            error_type = type(error).__name__
            passed = False
        elapsed = (time.perf_counter() - started) * 1000
        if max_latency_ms is not None and elapsed > max_latency_ms:
            reasons.append(f"latency_exceeded:{control.control_id}")
            passed = False
        if not passed:
            reasons.append(f"control_failed:{control.control_id}")
        results.append(
            ControlResult(
                control.control_id,
                control.role,
                passed,
                elapsed,
                observed,
                error_type,
            )
        )
    distinct_oracles = {repr(item.oracle) for item in declared}
    distinct_observations = {repr(item.observed) for item in results}
    discriminating = len(distinct_oracles) < 2 or len(distinct_observations) >= 2
    if not discriminating:
        reasons.append("constant_output_not_discriminating")
    passed = bool(results) and all(item.passed for item in results) and not reasons
    return ProbeResult(
        passed,
        any(item.error_type is not None for item in results),
        discriminating,
        tuple(results),
        tuple(sorted(set(reasons))),
    )

def validate_evaluation_lineage(lineage: Mapping[str, Any]) -> tuple[bool, tuple[str, ...]]:
    reasons: list[str] = []
    case_class = str(lineage.get("case_class", ""))
    origin = str(lineage.get("origin", ""))
    authority = str(lineage.get("oracle_authority", ""))
    if origin in {"model_generated", "derived"} and authority in {
        "model_provisional",
        "unknown",
    }:
        reasons.append("generated_case_cannot_self_certify")
    if case_class in {"holdout", "external_benchmark"}:
        if lineage.get("treatment_visibility") == "visible":
            reasons.append("protected_case_visible_to_treatment")
        if lineage.get("oracle_visibility") == "visible":
            reasons.append("protected_oracle_visible_before_run")
    if not lineage.get("source_refs"):
        reasons.append("lineage_source_missing")
    return not reasons, tuple(sorted(set(reasons)))

def admit_test_only_capability(
    *, execution_mode: str, capability_scope: str
) -> tuple[bool, str]:
    if capability_scope != "test_only":
        return True, "normal_capability_scope"
    if execution_mode != "benchmark":
        return False, "test_only_capability_requires_benchmark_execution_mode"
    return True, "test_only_capability_admitted_in_benchmark_context"

def decide_benchmark_retry(
    profile: Mapping[str, Any],
    *,
    completed_attempts: int,
    failure_class: BenchmarkFailureClass | str,
    observed_profile_hash: str,
) -> RetryDecision:
    valid, _ = verify_frozen_profile(profile)
    expected_hash = str(profile.get("frozen_hash", ""))
    if not valid or observed_profile_hash != expected_hash:
        return RetryDecision(False, "treatment_changed", 0)
    if completed_attempts < 1:
        return RetryDecision(False, "completed_attempts_must_be_positive", 0)
    retry = profile["retry_policy"]
    maximum = int(retry["max_retries"])
    remaining = max(0, maximum - (completed_attempts - 1))
    normalized = BenchmarkFailureClass(_enum_value(failure_class)).value
    if normalized not in set(map(str, retry["retryable_classes"])):
        return RetryDecision(False, "failure_class_not_retryable", remaining)
    if completed_attempts > maximum:
        return RetryDecision(False, "retry_budget_exhausted", 0)
    return RetryDecision(True, "retry_admitted_under_frozen_treatment", remaining)

def evaluate_contamination(
    *,
    lane: BenchmarkLane | str,
    oracle_visibility: str,
    treatment_visibility: str,
    benchmark_informed_changes: Iterable[str] = (),
) -> ContaminationDecision:
    selected = BenchmarkLane(_enum_value(lane))
    reasons: list[str] = []
    if selected is BenchmarkLane.COLD:
        if oracle_visibility not in {"hidden", "post_run_only"}:
            reasons.append("cold_oracle_visible")
        if treatment_visibility == "visible":
            reasons.append("cold_case_visible_to_treatment")
        if tuple(benchmark_informed_changes):
            reasons.append("cold_treatment_benchmark_informed")
    return ContaminationDecision(not reasons, tuple(sorted(set(reasons))))

def freeze_execution_profile(profile: Mapping[str, Any]) -> dict[str, Any]:
    """Return a content-addressed immutable treatment declaration."""
    candidate = dict(profile)
    missing = [section for section in REQUIRED_PROFILE_SECTIONS if section not in candidate]
    if missing:
        raise ValueError("missing profile sections: " + ", ".join(missing))
    if candidate.get("schema_version") != "1.0" or not str(candidate.get("run_id", "")).strip():
        raise ValueError("schema_version 1.0 and a non-empty run_id are required")
    invalid_sections = [
        section
        for section in REQUIRED_PROFILE_SECTIONS
        if not isinstance(candidate.get(section), Mapping)
    ]
    if invalid_sections:
        raise ValueError("profile sections must be objects: " + ", ".join(invalid_sections))
    if not isinstance(candidate["pacify_x"].get("enabled"), bool):
        raise ValueError("pacify_x.enabled must be boolean")
    try:
        BenchmarkLane(_enum_value(candidate["lane"]))
        retry = candidate["retry_policy"]
        max_retries = int(retry["max_retries"])
        retryable = tuple(sorted(set(map(str, retry["retryable_classes"]))))
    except (KeyError, TypeError, ValueError) as error:
        raise ValueError("invalid lane or retry policy") from error
    if max_retries < 0:
        raise ValueError("max_retries must be non-negative")
    candidate["retry_policy"] = {
        **dict(retry),
        "max_retries": max_retries,
        "retryable_classes": list(retryable),
    }
    payload = _profile_payload(candidate)
    return {
        **payload,
        "frozen": True,
        "frozen_hash": content_hash(payload),
        "comparison_hash": content_hash(_comparison_payload(payload)),
    }

def matched_control_comparison(
    pacify_on: Mapping[str, Any], pacify_off: Mapping[str, Any]
) -> dict[str, Any]:
    on_valid, on_reasons = verify_frozen_profile(pacify_on)
    off_valid, off_reasons = verify_frozen_profile(pacify_off)
    reasons = [*(f"on:{item}" for item in on_reasons), *(f"off:{item}" for item in off_reasons)]
    if on_valid and off_valid:
        if pacify_on.get("comparison_hash") != pacify_off.get("comparison_hash"):
            reasons.append("treatment_not_matched")
        on_pacify = pacify_on.get("pacify_x", {})
        off_pacify = pacify_off.get("pacify_x", {})
        if not isinstance(on_pacify, Mapping) or on_pacify.get("enabled") is not True:
            reasons.append("on_profile_not_enabled")
        if not isinstance(off_pacify, Mapping) or off_pacify.get("enabled") is not False:
            reasons.append("off_profile_not_disabled")
    return {
        "valid": not reasons,
        "matched": not reasons,
        "comparison_hash": pacify_on.get("comparison_hash") if not reasons else None,
        "reasons": tuple(sorted(set(reasons))),
    }

def summarize_matched_results(
    treatment_runs: Iterable[Mapping[str, Any]],
    control_runs: Iterable[Mapping[str, Any]],
) -> dict[str, Any]:
    treatment = tuple(treatment_runs)
    control = tuple(control_runs)
    required = {"task_id", "passed"}
    if any(not required.issubset(item) for item in (*treatment, *control)):
        raise ValueError("every matched result requires task_id and passed")
    treatment_tasks = {str(item["task_id"]) for item in treatment}
    control_tasks = {str(item["task_id"]) for item in control}
    if treatment_tasks != control_tasks or not treatment_tasks:
        raise ValueError("matched result task denominators differ or are empty")
    for task in treatment_tasks:
        treatment_count = sum(str(item["task_id"]) == task for item in treatment)
        control_count = sum(str(item["task_id"]) == task for item in control)
        if treatment_count != control_count:
            raise ValueError(f"matched trial counts differ for task {task}")

    def frequencies(rows: tuple[Mapping[str, Any], ...]) -> dict[str, float]:
        result: dict[str, float] = {}
        for task in sorted({str(item["task_id"]) for item in rows}):
            samples = [item.get("passed") is True for item in rows if str(item["task_id"]) == task]
            result[task] = round(sum(samples) / len(samples), 6)
        return result

    on_frequency, off_frequency = frequencies(treatment), frequencies(control)
    treatment_only = sorted(
        task for task in treatment_tasks if on_frequency[task] > 0 and off_frequency[task] == 0
    )
    control_only = sorted(
        task for task in treatment_tasks if off_frequency[task] > 0 and on_frequency[task] == 0
    )
    on_rate = sum(item.get("passed") is True for item in treatment) / len(treatment)
    off_rate = sum(item.get("passed") is True for item in control) / len(control)
    metrics = {}
    for name in ("quality", "latency", "cost", "tokens", "tool_calls", "wall_time"):
        metrics[name] = {
            "treatment": _numeric_summary(
                float(item[name]) for item in treatment if name in item
            ),
            "control": _numeric_summary(
                float(item[name]) for item in control if name in item
            ),
        }
    return {
        "valid": True,
        "task_count": len(treatment_tasks),
        "treatment_pass_rate": round(on_rate, 6),
        "control_pass_rate": round(off_rate, 6),
        "absolute_pass_delta": round(on_rate - off_rate, 6),
        "relative_pass_improvement": round((on_rate - off_rate) / off_rate, 6)
        if off_rate
        else None,
        "treatment_only_passes": treatment_only,
        "control_only_passes": control_only,
        "common_passes": sorted(
            task for task in treatment_tasks if on_frequency[task] > 0 and off_frequency[task] > 0
        ),
        "common_failures": sorted(
            task for task in treatment_tasks if on_frequency[task] == 0 and off_frequency[task] == 0
        ),
        "per_task": {
            task: {"treatment": on_frequency[task], "control": off_frequency[task]}
            for task in sorted(treatment_tasks)
        },
        "metrics": metrics,
        "infrastructure_errors": {
            "treatment": sum(item.get("infrastructure_error") is True for item in treatment),
            "control": sum(item.get("infrastructure_error") is True for item in control),
        },
        "significance_claimed": False,
    }

def verify_frozen_profile(profile: Mapping[str, Any]) -> tuple[bool, tuple[str, ...]]:
    reasons: list[str] = []
    if profile.get("frozen") is not True:
        reasons.append("profile_not_frozen")
    missing = [section for section in REQUIRED_PROFILE_SECTIONS if section not in profile]
    reasons.extend(f"profile_section_missing:{item}" for item in missing)
    reasons.extend(
        f"profile_section_invalid:{section}"
        for section in REQUIRED_PROFILE_SECTIONS
        if section in profile and not isinstance(profile.get(section), Mapping)
    )
    try:
        BenchmarkLane(_enum_value(profile.get("lane", "")))
    except ValueError:
        reasons.append("lane_invalid")
    payload = _profile_payload(profile)
    if profile.get("frozen_hash") != content_hash(payload):
        reasons.append("frozen_hash_mismatch")
    if profile.get("comparison_hash") != content_hash(_comparison_payload(payload)):
        reasons.append("comparison_hash_mismatch")
    retry = profile.get("retry_policy")
    if not isinstance(retry, Mapping):
        reasons.append("retry_policy_invalid")
    else:
        try:
            if int(retry.get("max_retries", -1)) < 0:
                reasons.append("retry_budget_invalid")
        except (TypeError, ValueError):
            reasons.append("retry_budget_invalid")
        if not isinstance(retry.get("retryable_classes"), list):
            reasons.append("retryable_classes_invalid")
    if profile.get("lane") == BenchmarkLane.COLD.value:
        environment = profile.get("environment", {})
        if not isinstance(environment, Mapping):
            reasons.append("environment_invalid")
        else:
            if environment.get("memory") not in {"disabled", "ephemeral_empty"}:
                reasons.append("cold_memory_not_isolated")
            if environment.get("cache") not in {"disabled", "empty", "ephemeral_empty"}:
                reasons.append("cold_cache_not_isolated")
    return not reasons, tuple(sorted(set(reasons)))

"""Deterministic, bounded filesystem traversal for read-only controls.

The walker makes resource ceilings and symlink handling explicit.  It never
follows a link unless the caller selects ``follow_within_root``; that mode
rejects both escapes and identity cycles before yielding a path.
"""

from __future__ import annotations

from dataclasses import dataclass
import os
from pathlib import Path
from typing import Callable, Literal


SymlinkPolicy = Literal["reject", "skip", "follow_within_root"]


@dataclass(frozen=True, slots=True)
class WalkLimits:
    """Hard traversal ceilings; all values must be positive."""

    max_files: int = 10_000
    max_depth: int = 64
    max_bytes: int = 256 * 1024 * 1024

    def __post_init__(self) -> None:
        for name in ("max_files", "max_depth", "max_bytes"):
            if getattr(self, name) < 1:
                raise ValueError(f"{name} must be positive")


class FilesystemWalkError(ValueError):
    """A structured, fail-closed traversal failure."""

    def __init__(
        self,
        code: str,
        *,
        root: Path,
        path: Path | None = None,
        limit: int | None = None,
        observed: int | None = None,
    ) -> None:
        self.code = code
        self.root = root
        self.path = path
        self.limit = limit
        self.observed = observed
        details = [code]
        if path is not None:
            details.append(f"path={path.as_posix()}")
        if limit is not None:
            details.append(f"limit={limit}")
        if observed is not None:
            details.append(f"observed={observed}")
        super().__init__("; ".join(details))

    def as_dict(self) -> dict[str, object]:
        return {
            "code": self.code,
            "root": self.root.as_posix(),
            "path": self.path.as_posix() if self.path is not None else None,
            "limit": self.limit,
            "observed": self.observed,
        }


@dataclass(frozen=True, slots=True)
class WalkEntry:
    """A root-relative filesystem object accepted by :func:`bounded_walk`."""

    path: Path
    relative: str
    kind: Literal["file", "directory"]
    size: int | None


@dataclass(frozen=True, slots=True)
class WalkResult:
    root: Path
    entries: tuple[WalkEntry, ...]
    file_count: int
    total_bytes: int

    @property
    def files(self) -> tuple[WalkEntry, ...]:
        return tuple(entry for entry in self.entries if entry.kind == "file")


def _inside(path: Path, root: Path) -> bool:
    try:
        path.relative_to(root)
        return True
    except ValueError:
        return False


def _identity(path: Path) -> tuple[int, int]:
    stat = path.stat()
    return stat.st_dev, stat.st_ino


def bounded_walk(
    root: Path,
    *,
    limits: WalkLimits = WalkLimits(),
    symlink_policy: SymlinkPolicy = "reject",
    exclude: Callable[[str], bool] | None = None,
) -> WalkResult:
    """Return a deterministic root-relative tree subject to hard limits.

    ``reject`` fails when any symbolic link is encountered. ``skip`` ignores
    links. ``follow_within_root`` follows links only after containment and
    inode/device cycle checks.  Files are sorted case-insensitively with a
    case-sensitive tie-breaker so the result is stable across runs. ``exclude``
    receives a POSIX root-relative path and prunes matching entries (including
    their directory subtrees) before resource limits are considered.
    """
    if symlink_policy not in {"reject", "skip", "follow_within_root"}:
        raise ValueError("unsupported symlink policy")
    canonical_root = root.resolve(strict=True)
    if not canonical_root.is_dir():
        raise ValueError("walk root must be a directory")

    entries: list[WalkEntry] = []
    file_count = 0
    total_bytes = 0
    visited_directories = {_identity(canonical_root)}
    pending: list[tuple[Path, Path, int]] = [(canonical_root, canonical_root, 0)]

    while pending:
        logical_directory, physical_directory, depth = pending.pop()
        try:
            children = sorted(
                os.scandir(physical_directory),
                key=lambda item: (item.name.casefold(), item.name),
            )
        except OSError as error:
            raise FilesystemWalkError(
                "directory_unreadable", root=canonical_root, path=logical_directory
            ) from error
        for child in reversed(children):
            logical_path = logical_directory / child.name
            relative_path = logical_path.relative_to(canonical_root)
            relative = relative_path.as_posix()
            if exclude is not None and exclude(relative):
                continue
            child_depth = depth + 1
            if child_depth > limits.max_depth:
                raise FilesystemWalkError(
                    "max_depth_exceeded",
                    root=canonical_root,
                    path=relative_path,
                    limit=limits.max_depth,
                    observed=child_depth,
                )
            is_link = child.is_symlink()
            if is_link:
                if symlink_policy == "reject":
                    raise FilesystemWalkError(
                        "symlink_disallowed", root=canonical_root, path=relative_path
                    )
                if symlink_policy == "skip":
                    continue
                try:
                    physical_path = Path(child.path).resolve(strict=True)
                except OSError as error:
                    raise FilesystemWalkError(
                        "symlink_unresolvable", root=canonical_root, path=relative_path
                    ) from error
                if not _inside(physical_path, canonical_root):
                    raise FilesystemWalkError(
                        "symlink_escape", root=canonical_root, path=relative_path
                    )
            else:
                physical_path = Path(child.path)

            try:
                if physical_path.is_dir():
                    identity = _identity(physical_path)
                    if identity in visited_directories:
                        raise FilesystemWalkError(
                            "directory_cycle", root=canonical_root, path=relative_path
                        )
                    visited_directories.add(identity)
                    entries.append(WalkEntry(logical_path, relative, "directory", None))
                    pending.append((logical_path, physical_path, child_depth))
                elif physical_path.is_file():
                    size = physical_path.stat().st_size
                    next_file_count = file_count + 1
                    next_total_bytes = total_bytes + size
                    if next_file_count > limits.max_files:
                        raise FilesystemWalkError(
                            "max_files_exceeded",
                            root=canonical_root,
                            path=relative_path,
                            limit=limits.max_files,
                            observed=next_file_count,
                        )
                    if next_total_bytes > limits.max_bytes:
                        raise FilesystemWalkError(
                            "max_bytes_exceeded",
                            root=canonical_root,
                            path=relative_path,
                            limit=limits.max_bytes,
                            observed=next_total_bytes,
                        )
                    file_count = next_file_count
                    total_bytes = next_total_bytes
                    entries.append(WalkEntry(logical_path, relative, "file", size))
            except OSError as error:
                raise FilesystemWalkError(
                    "path_unreadable", root=canonical_root, path=relative_path
                ) from error

    entries.sort(key=lambda entry: (entry.relative.casefold(), entry.relative))
    return WalkResult(canonical_root, tuple(entries), file_count, total_bytes)

