def certify_router(
    corpus: Mapping[str, object],
    records: Mapping[str, CapabilitySummary],
    *,
    index_revision: str,
    project_revision: str | None,
) -> dict[str, object]:
    """Run a fixed adversarial routing corpus with explicit ranking metrics."""
    cases = corpus.get("cases")
    if not isinstance(cases, list) or not cases:
        raise ValueError("router certification corpus requires cases")
    outcomes = []
    numerators = {1: 0, 3: 0, 5: 0}
    denominators = {1: 0, 3: 0, 5: 0}
    must_not_failures = []
    deterministic = True
    source = tuple(records.values())
    for case in cases:
        if not isinstance(case, Mapping):
            raise ValueError("router certification case must be an object")
        case_id = str(case.get("case_id", ""))
        query = str(case.get("query", ""))
        expected = set(map(str, case.get("expected", ())))
        forbidden = set(map(str, case.get("must_not_return", ())))
        if not case_id or not query or not expected:
            raise ValueError("router certification case is incomplete")
        first = route_task(query, {"adversarial": source}, canonical_records=records)
        second = route_task(query, {"adversarial": tuple(reversed(source))}, canonical_records=records)
        first_ids = tuple(item.canonical_id for item in first.ranked if item.disposition == "selectable")
        second_ids = tuple(item.canonical_id for item in second.ranked if item.disposition == "selectable")
        deterministic = deterministic and first_ids == second_ids
        forbidden_found = tuple(sorted(forbidden & set(first_ids)))
        if forbidden_found:
            must_not_failures.append({"case_id": case_id, "found": forbidden_found})
        for k in (1, 3, 5):
            window = first_ids[:k]
            numerators[k] += len(expected & set(window))
            denominators[k] += max(1, len(window))
        outcomes.append(
            {
                "case_id": case_id,
                "ranked": first_ids[:5],
                "expected": tuple(sorted(expected)),
                "must_not_return": tuple(sorted(forbidden)),
                "forbidden_found": forbidden_found,
                "top1_correct": bool(first_ids and first_ids[0] in expected),
            }
        )
    metrics = {
        f"precision_at_{k}": round(numerators[k] / denominators[k], 6)
        for k in (1, 3, 5)
    }
    thresholds = {
        str(key): float(value)
        for key, value in dict(corpus.get("thresholds", {})).items()
    }
    threshold_pass = all(
        metrics[name] >= thresholds.get(name, 0.0) for name in metrics
    )
    corpus_sha256 = _stable(corpus)
    payload = {
        "schema_version": "px.router-certification/1.0",
        "corpus_sha256": corpus_sha256,
        "index_revision": index_revision,
        "project_revision": project_revision,
        "case_outcomes": outcomes,
        "metrics": metrics,
        "thresholds": thresholds,
        "must_not_return_pass": not must_not_failures,
        "must_not_return_failures": must_not_failures,
        "deterministic_ties": deterministic,
        "threshold_pass": threshold_pass,
    }
    return {
        **payload,
        "valid": not must_not_failures and deterministic and threshold_pass,
        "receipt_sha256": _stable(payload),
    }

def expand_graph(
    seeds: Iterable[str],
    edges: Mapping[str, Sequence[tuple[str, str]]],
    *,
    max_depth: int = 2,
    max_nodes: int = 100,
    max_edges: int = 250,
    max_milliseconds: int = 100,
) -> dict[str, tuple[str, ...]]:
    """Expand reviewed edges under explicit depth, node, edge, and time budgets."""
    if not 0 <= max_depth <= 3 or min(max_nodes, max_edges, max_milliseconds) < 1:
        raise ValueError("invalid graph-expansion budget")
    started = time.monotonic()
    paths: dict[str, tuple[str, ...]] = {seed: (seed,) for seed in sorted(set(seeds))}
    frontier = list(paths)
    examined_edges = 0
    for _depth in range(max_depth):
        next_frontier = []
        for source in frontier:
            for relation, target in sorted(
                edges.get(source, ()), key=lambda item: (item[0], item[1])
            ):
                examined_edges += 1
                if (
                    examined_edges > max_edges
                    or (time.monotonic() - started) * 1000 > max_milliseconds
                ):
                    return paths
                if target in paths:
                    continue
                if len(paths) >= max_nodes:
                    return paths
                paths[target] = (*paths[source], f"{relation}:{target}")
                next_frontier.append(target)
        frontier = next_frontier
        if not frontier:
            break
    return paths

def rank_candidates(
    envelope: TaskEnvelope,
    discovery: Mapping[str, Sequence[DiscoveryCandidate]],
    records: Mapping[str, CapabilitySummary],
    *,
    graph_paths: Mapping[str, tuple[str, ...]] | None = None,
    max_risk: str = "R4",
    project_features: Mapping[str, object] | None = None,
) -> tuple[RankedCandidate, ...]:
    """Fuse independently discovered records with explainable 0-100 scoring."""
    if max_risk not in RISK_ORDER:
        raise ValueError("max_risk must be R0 through R4")
    canonical_ids, shadow_reasons = canonicalize_records(records)
    shadow_reason_by_id = {
        shadow: (owner, reason) for shadow, owner, reason in shadow_reasons
    }
    by_id: dict[str, list[DiscoveryCandidate]] = {}
    for rows in discovery.values():
        for row in rows:
            by_id.setdefault(
                canonical_ids.get(row.candidate_id, row.candidate_id), []
            ).append(row)
    applicable_ids = set(by_id)
    ranked: list[RankedCandidate] = []
    for candidate_id, rows in sorted(by_id.items()):
        record = records.get(candidate_id)
        if record is None:
            continue
        fields = set(
            _tokens(
                " ".join(
                    (
                        record.capability_id,
                        record.purpose,
                        *record.triggers,
                        *record.aliases,
                        *record.capability_tags,
                        *record.concepts,
                        *record.synonyms,
                    )
                )
            )
        )
        exact_alias = any(
            " ".join(_tokens(value)) == " ".join(_tokens(envelope.raw_request))
            for value in record.aliases
        )
        convergence = min(1.0, len({row.source_path for row in rows}) / 4.0)
        components = {
            "intent_similarity": 10 * _overlap(envelope.intent, fields),
            "capability_match": 16 * _overlap(envelope.capabilities, fields),
            "technology_match": 8 * _overlap(envelope.technologies, fields),
            "domain_match": 7 * _overlap(envelope.domain, fields),
            "task_type_match": 7 * _overlap(envelope.verbs, fields),
            "alias_confidence": 8.0
            if exact_alias
            else 4 * _overlap(envelope.aliases, record.aliases),
            "graph_proximity": 6.0
            if graph_paths and candidate_id in graph_paths
            else 0.0,
            "independent_path_convergence": 8 * convergence,
            "historical_success": 1.5,
            "freshness": 4 * max(0.0, min(1.0, record.freshness)),
            "canonical_preference": 4.0
            if record.status in {"active", "admitted"}
            else 0.0,
            "evidence_quality": 4 * record.evidence_quality,
            "validation_coverage": 4 * record.validation_coverage,
            "contract_coverage": 4 * record.contract_coverage,
            "workflow_compatibility": 2.0 if record.relations else 0.0,
            "tool_compatibility": 2.0,
            "safety_compatibility": 2.0
            if RISK_ORDER.get(record.risk, 4) <= RISK_ORDER[max_risk]
            else 0.0,
            "output_compatibility": 1
            * _overlap(envelope.required_outputs, record.outputs),
            "lexical_support": 5 * min(1.0, max(row.confidence for row in rows)),
            "project_context_match": 6
            * _overlap(
                fields,
                tuple(project_features.get("feature_tokens", ()))
                if project_features
                else (),
            ),
        }
        request_terms = set(_tokens(envelope.raw_request))
        negative_hit = any(
            set(_tokens(item)) <= request_terms
            for item in record.negative_matches
            if _tokens(item)
        )
        avoid_hit = any(
            set(_tokens(item)) <= request_terms
            for item in record.avoid_when
            if _tokens(item)
        )
        penalties = {
            "conflict": 40.0 if set(record.conflicts_with) & applicable_ids else 0.0,
            "deprecation": 50.0
            if record.status in {"deprecated", "superseded", "quarantined"}
            else 0.0,
            "orphan": 10.0 if record.dependencies and not record.relations else 0.0,
            "weak_metadata": 8.0 if len(fields) < 4 else 0.0,
            "stale_source": 10.0 if record.freshness < 0.25 else 0.0,
            "missing_authority": 35.0
            if RISK_ORDER.get(record.risk, 4) > RISK_ORDER[max_risk]
            else 0.0,
            "missing_reviewer": 25.0
            if record.risk in {"R3", "R4"} and not record.reviewed_by
            else 0.0,
            "negative_match": 35.0 if negative_hit else 0.0,
            "avoid_condition": 35.0 if avoid_hit else 0.0,
            "unresolved_dependency": 25.0
            if any(dep not in records for dep in record.dependencies)
            else 0.0,
        }
        positive = sum(components.values())
        penalty = sum(penalties.values())
        score = round(max(0.0, min(100.0, positive - penalty)), 6)
        blocked = any(value >= 25 for value in penalties.values())
        selectable = record.status in {"active", "admitted"} and not blocked
        reasons_set = {reason for row in rows for reason in row.match_reasons}
        for row in rows:
            shadow = shadow_reason_by_id.get(row.candidate_id)
            if shadow:
                reasons_set.add(f"{shadow[1]}:{row.candidate_id}->{shadow[0]}")
        reasons = tuple(
            sorted(
                reasons_set
                | {
                    f"paths={len(rows)}",
                    f"positive={positive:.3f}",
                    f"penalties={penalty:.3f}",
                }
            )
        )
        ranked.append(
            RankedCandidate(
                candidate_id=candidate_id,
                canonical_id=candidate_id,
                kind=record.kind,
                source_paths=tuple(sorted({row.source_path for row in rows})),
                component_scores={
                    key: round(value, 6) for key, value in components.items()
                },
                penalties={key: round(value, 6) for key, value in penalties.items()},
                final_score=score,
                disposition="selectable" if selectable else "discovery_only",
                reasons=reasons,
            )
        )
    return tuple(
        sorted(ranked, key=lambda item: (-item.final_score, item.canonical_id))
    )

def route_task(
    request: str,
    sources: Mapping[str, Iterable[CapabilitySummary]],
    *,
    project: Path | None = None,
    constraints: Iterable[str] = (),
    max_risk: str = "R4",
    available_inputs: Mapping[str, object] | None = None,
    canonical_records: Mapping[str, CapabilitySummary] | None = None,
) -> RouteResult:
    """Run the normalized discovery-to-package control flow without execution."""
    envelope = normalize_task(
        request,
        constraints=constraints,
        repository_context_required=project is not None or None,
    )
    project_map: Mapping[str, object] | None = None
    if envelope.repository_context_required and project is not None:
        from .project_intelligence import project_routing_features, validate_project_map
        from .project_intelligence import _map_dir
        from .project_map_retrieval import query_project_map

        validation = validate_project_map(project, check_freshness=True)
        if not validation.get("valid"):
            raise ValueError(
                f"fresh project map required: {validation.get('errors', [])}"
            )
        project_map = query_project_map(project, request, top_k=10, relation_depth=2)
        manifest = json.loads(
            (_map_dir(project) / "project-manifest.json").read_text(encoding="utf-8")
        )
        project_map = {
            **project_map,
            "routing_features": project_routing_features(project, manifest, project_map),
        }
    materialized = {name: tuple(items) for name, items in sources.items()}
    records = dict(canonical_records or {})
    for items in materialized.values():
        for item in items:
            records.setdefault(item.capability_id, item)
    discovery = discover_independently(
        envelope,
        materialized,
        available_inputs=available_inputs,
        constraints={"max_risk": max_risk},
    )
    relations = {
        record.capability_id: tuple(("relation", target) for target in record.relations)
        for record in records.values()
    }
    seeds = [row.candidate_id for rows in discovery.values() for row in rows[:5]]
    graph_paths = expand_graph(seeds, relations)
    ranked = rank_candidates(
        envelope,
        discovery,
        records,
        graph_paths=graph_paths,
        max_risk=max_risk,
        project_features=project_map.get("routing_features") if project_map else None,
    )
    package = build_minimum_package(
        envelope,
        ranked,
        records,
        project_features=project_map.get("routing_features") if project_map else None,
    )
    receipt_payload = {
        "envelope": envelope.task_envelope_sha256,
        "discovery_sources": {
            key: [item.candidate_id for item in value]
            for key, value in discovery.items()
        },
        "ranked": [
            (item.canonical_id, item.final_score, item.disposition) for item in ranked
        ],
        "package": package.receipt_sha256,
        "project_map_revision": project_map.get("map_revision")
        if project_map
        else None,
    }
    return RouteResult(
        envelope, discovery, ranked, package, project_map, _stable(receipt_payload)
    )

class Scheduler:
    """Plans and simulates; it never invokes an executor or mutates canonical state."""

    def __init__(
        self,
        resources: Resources,
        policy: Mapping[str, Any] | None = None,
        *,
        now: datetime | None = None,
    ):
        self.total = resources
        self.available = Resources.from_mapping(resources.record())
        self.policy = dict(policy or {})
        self.now = now or datetime(2000, 1, 1, tzinfo=timezone.utc)
        self.tasks: dict[str, Task] = {}
        self.completed: set[str] = set()
        self.failed: set[str] = set()
        self.events: list[dict[str, Any]] = []
        self._counter = 0

    def add(self, task: Task) -> None:
        if task.id in self.tasks:
            raise ValueError(f"duplicate task id: {task.id}")
        if not task.id or not task.capability:
            raise ValueError("task id and capability are required")
        if not 0 <= int(task.priority) <= 1000:
            raise ValueError(f"priority outside 0..1000: {task.id}")
        self._counter += 1
        task.created_index = self._counter
        self.tasks[task.id] = task
        self.events.append({"event": "task_added", "task_id": task.id})

    def validate_dag(self) -> None:
        visiting: set[str] = set()
        visited: set[str] = set()

        def visit(task_id: str) -> None:
            if task_id in visiting:
                raise ValueError(f"dependency cycle at {task_id}")
            if task_id in visited:
                return
            visiting.add(task_id)
            for dependency in self.tasks[task_id].dependencies:
                if dependency not in self.tasks:
                    raise ValueError(f"missing dependency {dependency} for {task_id}")
                visit(dependency)
            visiting.remove(task_id)
            visited.add(task_id)

        for task_id in sorted(self.tasks):
            visit(task_id)

    def eligible(self, task: Task) -> tuple[bool, list[str]]:
        reasons: list[str] = []
        if task.state not in {"pending", "ready"}:
            reasons.append("state_not_schedulable")
        if any(dependency not in self.completed for dependency in task.dependencies):
            reasons.append("dependencies_incomplete")
        if task.approval_required and not task.approved:
            reasons.append("approval_required")
        if not self.available.fits(task.resources):
            reasons.append("resource_unavailable")
        if task.risk in {"high", "critical"} and not task.acceptance:
            reasons.append("acceptance_missing")
        if (
            task.privacy in {"restricted", "secret"}
            and task.resources.network == "external"
        ):
            reasons.append("privacy_policy_denied")
        if (
            self.policy.get("external_network") == "deny"
            and task.resources.network == "external"
        ):
            reasons.append("egress_policy_denied")
        maximum_cost = task.budget.get("maximum_cost")
        estimated_cost = task.budget.get("estimated_cost")
        if (
            maximum_cost is not None
            and estimated_cost is not None
            and float(estimated_cost) > float(maximum_cost)
        ):
            reasons.append("budget_exhausted")
        if task.attempt > 1 and not task.idempotency_key and not task.compensation:
            reasons.append("retry_requires_idempotency_or_compensation")
        return not reasons, sorted(reasons)

    def score(self, task: Task) -> tuple[float, dict[str, float]]:
        downstream = sum(
            1
            for candidate in self.tasks.values()
            if task.id in candidate.dependencies
            and candidate.state in {"pending", "ready"}
        )
        maximum_downstream = max(1, len(self.tasks) - 1)
        deadline_pressure = 0.0
        if task.deadline:
            try:
                deadline = datetime.fromisoformat(task.deadline.replace("Z", "+00:00"))
                remaining = (deadline - self.now).total_seconds()
                deadline_pressure = _clamp(
                    1.0 - remaining / max(task.estimated_seconds * 10.0, 1.0)
                )
            except ValueError:
                deadline_pressure = 0.0
        factors = {
            "priority": _clamp(task.priority / 1000.0),
            "deadline_pressure": deadline_pressure,
            "dependency_unblock": _clamp(downstream / maximum_downstream),
            "aging": _clamp(
                (self._counter - task.created_index) / max(1, self._counter)
            ),
            "success_rate": _clamp(float(task.acceptance.get("expected_success", 0.5))),
            "quality": _clamp(float(task.acceptance.get("required_quality", 0.5))),
            "cost_efficiency": _clamp(float(task.budget.get("cost_efficiency", 0.5))),
        }
        weights = dict(DEFAULT_WEIGHTS)
        weights.update(self.policy.get("weights", {}))
        total_weight = sum(max(0.0, float(value)) for value in weights.values()) or 1.0
        score = (
            sum(
                factors[name] * max(0.0, float(weights.get(name, 0.0)))
                for name in factors
            )
            / total_weight
        )
        return round(score, 8), {
            name: round(value, 8) for name, value in factors.items()
        }

    def next_task(
        self,
    ) -> tuple[Task | None, dict[str, list[str]], dict[str, Any] | None]:
        eligible: list[tuple[float, int, str, dict[str, float]]] = []
        blocked: dict[str, list[str]] = {}
        for task in self.tasks.values():
            accepted, reasons = self.eligible(task)
            if accepted:
                score, factors = self.score(task)
                eligible.append((-score, task.created_index, task.id, factors))
            elif task.state in {"pending", "ready"}:
                blocked[task.id] = reasons
        if not eligible:
            return None, blocked, None
        eligible.sort()
        negated, _, task_id, factors = eligible[0]
        return self.tasks[task_id], blocked, {"score": -negated, "factors": factors}

    def simulate(self) -> dict[str, Any]:
        self.validate_dag()
        decisions: list[dict[str, Any]] = []
        while len(self.completed | self.failed) < len(self.tasks):
            task, blocked, score = self.next_task()
            if task is None:
                decisions.append({"event": "stalled", "blocked": blocked})
                break
            self.available.consume(task.resources)
            task.state = "running"
            dispatch = {
                "event": "would_dispatch",
                "task_id": task.id,
                **(score or {}),
                "resources": task.resources.record(),
                "idempotency_key": task.idempotency_key,
            }
            decisions.append(dispatch)
            self.events.append(dispatch)
            self.available.release(task.resources)
            evidence = {
                "simulation": True,
                "acceptance_preserved": True,
                "executor_not_invoked": True,
            }
            task.state = "succeeded"
            self.completed.add(task.id)
            finish = {
                "event": "simulated_completion",
                "task_id": task.id,
                "evidence": evidence,
            }
            decisions.append(finish)
            self.events.append(finish)
        stalled = len(self.completed | self.failed) < len(self.tasks)
        return {
            "valid": not stalled,
            "observe_only": True,
            "completed": sorted(self.completed),
            "failed": sorted(self.failed),
            "events": decisions,
            "stalled": stalled,
            "decision_hash": _hash(self.events),
            "execution_authority": "none; dispatch events are plans only",
        }


def simulate_schedule(payload: Mapping[str, Any]) -> dict[str, Any]:
    workload = payload.get("workload", payload)
    tasks = workload.get("tasks") if isinstance(workload, Mapping) else None
    if not isinstance(tasks, list):
        return {"valid": False, "errors": ["workload.tasks must be a list"]}
    now_value = payload.get("now", "2000-01-01T00:00:00Z")
    try:
        now = datetime.fromisoformat(str(now_value).replace("Z", "+00:00"))
        scheduler = Scheduler(
            Resources.from_mapping(payload.get("resources", {})),
            payload.get("policy", {}),
            now=now,
        )
        for value in tasks:
            if not isinstance(value, Mapping):
                raise ValueError("every task must be an object")
            scheduler.add(Task.from_mapping(value))
        return scheduler.simulate()
    except (KeyError, TypeError, ValueError) as error:
        return {"valid": False, "observe_only": True, "errors": [str(error)]}


