class Scheduler:
    """Plans and simulates; it never invokes an executor or mutates canonical state."""

    def __init__(
        self,
        resources: Resources,
        policy: Mapping[str, Any] | None = None,
        *,
        now: datetime | None = None,
    ):
        self.total = resources
        self.available = Resources.from_mapping(resources.record())
        self.policy = dict(policy or {})
        self.now = now or datetime(2000, 1, 1, tzinfo=timezone.utc)
        self.tasks: dict[str, Task] = {}
        self.completed: set[str] = set()
        self.failed: set[str] = set()
        self.events: list[dict[str, Any]] = []
        self._counter = 0

    def add(self, task: Task) -> None:
        if task.id in self.tasks:
            raise ValueError(f"duplicate task id: {task.id}")
        if not task.id or not task.capability:
            raise ValueError("task id and capability are required")
        if not 0 <= int(task.priority) <= 1000:
            raise ValueError(f"priority outside 0..1000: {task.id}")
        self._counter += 1
        task.created_index = self._counter
        self.tasks[task.id] = task
        self.events.append({"event": "task_added", "task_id": task.id})

    def validate_dag(self) -> None:
        visiting: set[str] = set()
        visited: set[str] = set()

        def visit(task_id: str) -> None:
            if task_id in visiting:
                raise ValueError(f"dependency cycle at {task_id}")
            if task_id in visited:
                return
            visiting.add(task_id)
            for dependency in self.tasks[task_id].dependencies:
                if dependency not in self.tasks:
                    raise ValueError(f"missing dependency {dependency} for {task_id}")
                visit(dependency)
            visiting.remove(task_id)
            visited.add(task_id)

        for task_id in sorted(self.tasks):
            visit(task_id)

    def eligible(self, task: Task) -> tuple[bool, list[str]]:
        reasons: list[str] = []
        if task.state not in {"pending", "ready"}:
            reasons.append("state_not_schedulable")
        if any(dependency not in self.completed for dependency in task.dependencies):
            reasons.append("dependencies_incomplete")
        if task.approval_required and not task.approved:
            reasons.append("approval_required")
        if not self.available.fits(task.resources):
            reasons.append("resource_unavailable")
        if task.risk in {"high", "critical"} and not task.acceptance:
            reasons.append("acceptance_missing")
        if (
            task.privacy in {"restricted", "secret"}
            and task.resources.network == "external"
        ):
            reasons.append("privacy_policy_denied")
        if (
            self.policy.get("external_network") == "deny"
            and task.resources.network == "external"
        ):
            reasons.append("egress_policy_denied")
        maximum_cost = task.budget.get("maximum_cost")
        estimated_cost = task.budget.get("estimated_cost")
        if (
            maximum_cost is not None
            and estimated_cost is not None
            and float(estimated_cost) > float(maximum_cost)
        ):
            reasons.append("budget_exhausted")
        if task.attempt > 1 and not task.idempotency_key and not task.compensation:
            reasons.append("retry_requires_idempotency_or_compensation")
        return not reasons, sorted(reasons)

    def score(self, task: Task) -> tuple[float, dict[str, float]]:
        downstream = sum(
            1
            for candidate in self.tasks.values()
            if task.id in candidate.dependencies
            and candidate.state in {"pending", "ready"}
        )
        maximum_downstream = max(1, len(self.tasks) - 1)
        deadline_pressure = 0.0
        if task.deadline:
            try:
                deadline = datetime.fromisoformat(task.deadline.replace("Z", "+00:00"))
                remaining = (deadline - self.now).total_seconds()
                deadline_pressure = _clamp(
                    1.0 - remaining / max(task.estimated_seconds * 10.0, 1.0)
                )
            except ValueError:
                deadline_pressure = 0.0
        factors = {
            "priority": _clamp(task.priority / 1000.0),
            "deadline_pressure": deadline_pressure,
            "dependency_unblock": _clamp(downstream / maximum_downstream),
            "aging": _clamp(
                (self._counter - task.created_index) / max(1, self._counter)
            ),
            "success_rate": _clamp(float(task.acceptance.get("expected_success", 0.5))),
            "quality": _clamp(float(task.acceptance.get("required_quality", 0.5))),
            "cost_efficiency": _clamp(float(task.budget.get("cost_efficiency", 0.5))),
        }
        weights = dict(DEFAULT_WEIGHTS)
        weights.update(self.policy.get("weights", {}))
        total_weight = sum(max(0.0, float(value)) for value in weights.values()) or 1.0
        score = (
            sum(
                factors[name] * max(0.0, float(weights.get(name, 0.0)))
                for name in factors
            )
            / total_weight
        )
        return round(score, 8), {
            name: round(value, 8) for name, value in factors.items()
        }

    def next_task(
        self,
    ) -> tuple[Task | None, dict[str, list[str]], dict[str, Any] | None]:
        eligible: list[tuple[float, int, str, dict[str, float]]] = []
        blocked: dict[str, list[str]] = {}
        for task in self.tasks.values():
            accepted, reasons = self.eligible(task)
            if accepted:
                score, factors = self.score(task)
                eligible.append((-score, task.created_index, task.id, factors))
            elif task.state in {"pending", "ready"}:
                blocked[task.id] = reasons
        if not eligible:
            return None, blocked, None
        eligible.sort()
        negated, _, task_id, factors = eligible[0]
        return self.tasks[task_id], blocked, {"score": -negated, "factors": factors}

    def simulate(self) -> dict[str, Any]:
        self.validate_dag()
        decisions: list[dict[str, Any]] = []
        while len(self.completed | self.failed) < len(self.tasks):
            task, blocked, score = self.next_task()
            if task is None:
                decisions.append({"event": "stalled", "blocked": blocked})
                break
            self.available.consume(task.resources)
            task.state = "running"
            dispatch = {
                "event": "would_dispatch",
                "task_id": task.id,
                **(score or {}),
                "resources": task.resources.record(),
                "idempotency_key": task.idempotency_key,
            }
            decisions.append(dispatch)
            self.events.append(dispatch)
            self.available.release(task.resources)
            evidence = {
                "simulation": True,
                "acceptance_preserved": True,
                "executor_not_invoked": True,
            }
            task.state = "succeeded"
            self.completed.add(task.id)
            finish = {
                "event": "simulated_completion",
                "task_id": task.id,
                "evidence": evidence,
            }
            decisions.append(finish)
            self.events.append(finish)
        stalled = len(self.completed | self.failed) < len(self.tasks)
        return {
            "valid": not stalled,
            "observe_only": True,
            "completed": sorted(self.completed),
            "failed": sorted(self.failed),
            "events": decisions,
            "stalled": stalled,
            "decision_hash": _hash(self.events),
            "execution_authority": "none; dispatch events are plans only",
        }

def validate_capability_semantic_profile(
    profile: CapabilitySemanticProfile | Mapping[str, object],
) -> dict[str, object]:
    value = profile.as_dict() if isinstance(profile, CapabilitySemanticProfile) else dict(profile)
    errors: list[str] = []
    if value.get("schema_version") != SCHEMA_VERSION:
        errors.append(f"schema_version must be {SCHEMA_VERSION}")
    if not value.get("capability_id"):
        errors.append("capability_id is required")
    if not value.get("canonical_owner"):
        errors.append("canonical owner is required")
    positive = set(map(str, value.get("positive_intents", ())))
    negative = set(map(str, value.get("negative_intents", ())))
    if not positive:
        errors.append("at least one positive intent is required")
    overlap = sorted(positive & negative)
    if overlap:
        errors.append(f"positive and negative intents overlap: {overlap}")
    maturity = value.get("maturity")
    if maturity is not None and maturity not in MATURITY_LEVELS:
        errors.append(f"unsupported maturity claim: {maturity}")
    guards = value.get("ambiguity_guards", ())
    guarded = {
        str(item.get("term"))
        for item in guards
        if isinstance(item, Mapping) and item.get("disambiguate_by")
    }
    ambiguous = set(map(str, value.get("ambiguous_synonyms", ())))
    missing_guards = sorted(ambiguous - guarded)
    if missing_guards:
        errors.append(f"ambiguous synonyms lack guards: {missing_guards}")
    for field in (
        "positive_intents",
        "negative_intents",
        "domains",
        "mechanisms",
        "inputs",
        "outputs",
        "effects",
        "exclusions",
        "synonyms",
        "failure_modes",
        "evidence_sources",
    ):
        items = value.get(field)
        if not isinstance(items, (list, tuple)) or any(not str(item).strip() for item in items):
            errors.append(f"{field} must be a non-empty-string array")
        elif list(items) != sorted(set(map(str, items))):
            errors.append(f"{field} must be sorted and unique")
    return {
        "schema_version": SCHEMA_VERSION,
        "valid": not errors,
        "capability_id": value.get("capability_id"),
        "errors": errors,
    }

def _tool_result(
    identifier: str,
    executable: Path | None,
    requirement: str | None,
    *,
    cwd: Path,
    arguments: Sequence[str] = ("--version",),
    timeout_seconds: float = PROBE_TIMEOUT_SECONDS,
) -> dict[str, Any]:
    base: dict[str, Any] = {
        "id": identifier,
        "required": True,
        "status": "missing",
        "executable": str(executable) if executable else None,
        "version": None,
        "requirement": requirement,
        "diagnostic": "required executable was not found",
    }
    if executable is None:
        return base
    probe = _run_probe(
        executable, arguments, cwd=cwd, timeout_seconds=timeout_seconds
    )
    if not probe["ok"]:
        return {
            **base,
            "status": "probe-failed",
            "diagnostic": probe["diagnostic"],
        }
    version_match = VERSION.search(probe["output"])
    version = version_match.group(0) if version_match else None
    if version is None:
        return {
            **base,
            "status": "probe-failed",
            "diagnostic": "version probe returned no parseable version",
        }
    try:
        compatible = version_satisfies(version, requirement)
    except ValueError as error:
        return {
            **base,
            "version": version,
            "status": "invalid-configuration",
            "diagnostic": str(error),
        }
    return {
        **base,
        "version": version,
        "status": "ready" if compatible else "incompatible",
        "diagnostic": "" if compatible else f"found {version}; requires {requirement}",
    }

def _windows_file_version(executable: Path) -> str | None:
    if platform.system() != "Windows":
        return None
    try:
        import ctypes

        size = ctypes.windll.version.GetFileVersionInfoSizeW(str(executable), None)
        if not size:
            return None
        buffer = ctypes.create_string_buffer(size)
        if not ctypes.windll.version.GetFileVersionInfoW(
            str(executable), 0, size, buffer
        ):
            return None
        pointer = ctypes.c_void_p()
        length = ctypes.c_uint()
        if not ctypes.windll.version.VerQueryValueW(
            buffer, "\\", ctypes.byref(pointer), ctypes.byref(length)
        ):
            return None

        class FixedFileInfo(ctypes.Structure):
            _fields_ = [
                ("signature", ctypes.c_uint32),
                ("structure_version", ctypes.c_uint32),
                ("file_version_ms", ctypes.c_uint32),
                ("file_version_ls", ctypes.c_uint32),
            ]

        value = ctypes.cast(pointer, ctypes.POINTER(FixedFileInfo)).contents
        return ".".join(
            map(
                str,
                (
                    value.file_version_ms >> 16,
                    value.file_version_ms & 0xFFFF,
                    value.file_version_ls >> 16,
                    value.file_version_ls & 0xFFFF,
                ),
            )
        )
    except (AttributeError, OSError, ValueError):
        return None


def _browser_result(executable: Path | None, *, cwd: Path) -> dict[str, Any]:
    if executable is not None:
        version = _windows_file_version(executable)
        if version:
            return {
                "id": "browser",
                "required": True,
                "status": "ready",
                "executable": str(executable),
                "version": version,
                "requirement": None,
                "diagnostic": "",
            }
    return _tool_result("browser", executable, None, cwd=cwd)

def _read_extension_contract(
    extension_root: Path | None,
) -> tuple[dict[str, Any] | None, dict[str, Any] | None, list[str]]:
    if extension_root is None:
        return None, None, ["extension root was not supplied"]
    errors: list[str] = []
    package: dict[str, Any] | None = None
    lock: dict[str, Any] | None = None
    documents = (("package.json", "package"), ("package-lock.json", "lock"))
    for filename, destination in documents:
        path = extension_root / filename
        try:
            value = json.loads(path.read_text(encoding="utf-8"))
            if not isinstance(value, dict):
                raise ValueError("document must be a JSON object")
            if destination == "package":
                package = value
            else:
                lock = value
        except (OSError, ValueError, json.JSONDecodeError) as error:
            errors.append(f"{filename}: {error}")
    return package, lock, errors


def _node_requirements(
    lock: Mapping[str, Any] | None,
) -> tuple[list[str], str | None]:
    if lock is None:
        return [], "package-lock.json is unavailable"
    packages = lock.get("packages")
    if not isinstance(packages, Mapping):
        return [], "package-lock.json does not contain a packages map"
    requirements = sorted(
        {
            str(engines["node"]).strip()
            for value in packages.values()
            if isinstance(value, Mapping)
            and isinstance((engines := value.get("engines")), Mapping)
            and engines.get("node")
        }
    )
    if not requirements:
        return [], "locked packages do not declare a Node requirement"
    return requirements, None


def _node_result(
    executable: Path | None,
    requirements: Sequence[str],
    configuration_error: str | None,
    *,
    cwd: Path,
) -> dict[str, Any]:
    rendered = " AND ".join(f"({item})" for item in requirements) or None
    base: dict[str, Any] = {
        "id": "node",
        "required": True,
        "status": "missing",
        "executable": str(executable) if executable else None,
        "version": None,
        "requirement": rendered,
        "diagnostic": configuration_error or "required executable was not found",
    }
    if configuration_error:
        return {**base, "status": "invalid-configuration"}
    if executable is None:
        return base
    probe = _run_probe(executable, ("--version",), cwd=cwd)
    if not probe["ok"]:
        return {**base, "status": "probe-failed", "diagnostic": probe["diagnostic"]}
    version_match = VERSION.search(probe["output"])
    version = version_match.group(0) if version_match else None
    if version is None:
        return {**base, "status": "probe-failed", "diagnostic": "version probe returned no parseable version"}
    try:
        incompatible = [
            requirement
            for requirement in requirements
            if not version_satisfies(version, requirement)
        ]
    except ValueError as error:
        return {**base, "version": version, "status": "invalid-configuration", "diagnostic": str(error)}
    return {
        **base,
        "version": version,
        "status": "ready" if not incompatible else "incompatible",
        "diagnostic": "" if not incompatible else f"found {version}; incompatible with: {', '.join(incompatible)}",
    }


def _lock_result(
    package: Mapping[str, Any] | None,
    lock: Mapping[str, Any] | None,
    read_errors: Sequence[str],
    extension_root: Path | None,
) -> dict[str, Any]:
    errors = list(read_errors)
    if package is not None and lock is not None:
        if lock.get("lockfileVersion") != 3:
            errors.append("package-lock.json must use lockfileVersion 3")
        packages = lock.get("packages")
        root = packages.get("") if isinstance(packages, Mapping) else None
        if not isinstance(root, Mapping):
            errors.append("package-lock.json is missing the root package record")
        else:
            for field in ("name", "version", "dependencies", "devDependencies"):
                if package.get(field, {}) != root.get(field, {}):
                    errors.append(
                        f"package-lock root {field} differs from package.json"
                    )
        for group in ("dependencies", "devDependencies"):
            declared = package.get(group, {})
            if not isinstance(declared, Mapping):
                errors.append(f"package.json {group} must be an object")
                continue
            floating = [
                name
                for name, value in declared.items()
                if not re.fullmatch(
                    r"\d+(?:\.\d+){2}(?:[-+][A-Za-z0-9.-]+)?", str(value)
                )
            ]
            if floating:
                errors.append(
                    f"package.json {group} is not exact-pinned: "
                    f"{', '.join(sorted(floating))}"
                )
            if extension_root is not None:
                for name, expected in sorted(declared.items()):
                    installed_path = (
                        extension_root / "node_modules" / name / "package.json"
                    )
                    try:
                        installed = json.loads(
                            installed_path.read_text(encoding="utf-8")
                        )
                        actual = installed.get("version")
                    except (OSError, json.JSONDecodeError, AttributeError) as error:
                        errors.append(
                            f"installed dependency {name} is unavailable: {error}"
                        )
                        continue
                    if actual != expected:
                        errors.append(
                            f"installed dependency {name} is {actual}; "
                            f"expected {expected}"
                        )
    return {
        "id": "node-package-lock",
        "required": True,
        "status": "ready" if not errors else "invalid-configuration",
        "executable": None,
        "version": str(lock.get("lockfileVersion")) if lock else None,
        "requirement": (
            "lockfileVersion 3; exact direct pins; installed direct dependency parity"
        ),
        "diagnostic": "; ".join(errors),
    }

def _version_tuple(value: str) -> tuple[int, int, int] | None:
    match = VERSION.search(value)
    if not match:
        return None
    return tuple(int(part or 0) for part in match.groups())


def _satisfies_clause(version: tuple[int, int, int], clause: str) -> bool:
    match = COMPARATOR.fullmatch(clause.strip())
    if not match:
        raise ValueError(f"unsupported version constraint: {clause}")
    operator, raw_expected = match.groups()
    expected = _version_tuple(raw_expected)
    if expected is None:  # guarded by COMPARATOR; retained as a fail-closed check
        raise ValueError(f"invalid version constraint: {clause}")
    if operator == ">=":
        return version >= expected
    if operator == "<=":
        return version <= expected
    if operator == ">":
        return version > expected
    if operator == "<":
        return version < expected
    if operator == "^":
        ceiling = (expected[0] + 1, 0, 0)
        return expected <= version < ceiling
    if operator == "~":
        ceiling = (expected[0], expected[1] + 1, 0)
        return expected <= version < ceiling
    return version == expected


def version_satisfies(version: str, requirement: str | None) -> bool:
    """Evaluate the bounded semver subset used by the PX lock and manifests."""

    if not requirement:
        return True
    parsed = _version_tuple(version)
    if parsed is None:
        return False
    normalized = re.sub(r"(>=|<=|==|>|<|=|\^|~)\s+(?=\d)", r"\1", requirement)
    alternatives = [item.strip() for item in normalized.split("||") if item.strip()]
    if not alternatives:
        raise ValueError("version requirement is empty")
    for alternative in alternatives:
        clauses = [item for item in re.split(r"\s+", alternative) if item]
        if all(_satisfies_clause(parsed, clause) for clause in clauses):
            return True
    return False


def _resolve_executable(
    requested: str | None,
    names: Sequence[str],
    absolute_candidates: Iterable[Path] = (),
) -> Path | None:
    if requested:
        candidate = Path(requested).expanduser()
        if candidate.is_absolute() or candidate.parent != Path("."):
            return candidate.resolve() if candidate.is_file() else None
        resolved = shutil.which(requested)
        return Path(resolved).resolve() if resolved else None
    for name in names:
        resolved = shutil.which(name)
        if resolved:
            return Path(resolved).resolve()
    for candidate in absolute_candidates:
        if candidate.is_file():
            return candidate.resolve()
    return None


def _batch_command(executable: Path, arguments: Sequence[str]) -> list[str]:
    if platform.system() != "Windows" or executable.suffix.casefold() not in {
        ".cmd",
        ".bat",
    }:
        return [str(executable), *arguments]
    command_processor = os.environ.get("COMSPEC") or shutil.which("cmd.exe")
    if not command_processor:
        raise OSError("Windows command processor is unavailable")
    return [command_processor, "/d", "/c", str(executable), *arguments]


def _run_probe(
    executable: Path,
    arguments: Sequence[str],
    *,
    cwd: Path,
    timeout_seconds: float = PROBE_TIMEOUT_SECONDS,
) -> dict[str, Any]:
    try:
        completed = subprocess.run(
            _batch_command(executable, arguments),
            cwd=cwd,
            env=scrub_release_environment(),
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=timeout_seconds,
            check=False,
        )
    except (OSError, subprocess.TimeoutExpired) as error:
        return {
            "ok": False,
            "exit_code": None,
            "output": "",
            "diagnostic": f"{type(error).__name__}: {error}",
        }
    output = "\n".join(
        item.strip() for item in (completed.stdout, completed.stderr) if item.strip()
    )[:4096]
    return {
        "ok": completed.returncode == 0,
        "exit_code": completed.returncode,
        "output": output,
        "diagnostic": "" if completed.returncode == 0 else output or "probe failed",
    }


def _tool_result(
    identifier: str,
    executable: Path | None,
    requirement: str | None,
    *,
    cwd: Path,
    arguments: Sequence[str] = ("--version",),
    timeout_seconds: float = PROBE_TIMEOUT_SECONDS,
) -> dict[str, Any]:
    base: dict[str, Any] = {
        "id": identifier,
        "required": True,
        "status": "missing",
        "executable": str(executable) if executable else None,
        "version": None,
        "requirement": requirement,
        "diagnostic": "required executable was not found",
    }
    if executable is None:
        return base
    probe = _run_probe(
        executable, arguments, cwd=cwd, timeout_seconds=timeout_seconds
    )
    if not probe["ok"]:
        return {
            **base,
            "status": "probe-failed",
            "diagnostic": probe["diagnostic"],
        }
    version_match = VERSION.search(probe["output"])
    version = version_match.group(0) if version_match else None
    if version is None:
        return {
            **base,
            "status": "probe-failed",
            "diagnostic": "version probe returned no parseable version",
        }
    try:
        compatible = version_satisfies(version, requirement)
    except ValueError as error:
        return {
            **base,
            "version": version,
            "status": "invalid-configuration",
            "diagnostic": str(error),
        }
    return {
        **base,
        "version": version,
        "status": "ready" if compatible else "incompatible",
        "diagnostic": "" if compatible else f"found {version}; requires {requirement}",
    }


def _windows_file_version(executable: Path) -> str | None:
    if platform.system() != "Windows":
        return None
    try:
        import ctypes

        size = ctypes.windll.version.GetFileVersionInfoSizeW(str(executable), None)
        if not size:
            return None
        buffer = ctypes.create_string_buffer(size)
        if not ctypes.windll.version.GetFileVersionInfoW(
            str(executable), 0, size, buffer
        ):
            return None
        pointer = ctypes.c_void_p()
        length = ctypes.c_uint()
        if not ctypes.windll.version.VerQueryValueW(
            buffer, "\\", ctypes.byref(pointer), ctypes.byref(length)
        ):
            return None

        class FixedFileInfo(ctypes.Structure):
            _fields_ = [
                ("signature", ctypes.c_uint32),
                ("structure_version", ctypes.c_uint32),
                ("file_version_ms", ctypes.c_uint32),
                ("file_version_ls", ctypes.c_uint32),
            ]

        value = ctypes.cast(pointer, ctypes.POINTER(FixedFileInfo)).contents
        return ".".join(
            map(
                str,
                (
                    value.file_version_ms >> 16,
                    value.file_version_ms & 0xFFFF,
                    value.file_version_ls >> 16,
                    value.file_version_ls & 0xFFFF,
                ),
            )
        )
    except (AttributeError, OSError, ValueError):
        return None


def _browser_result(executable: Path | None, *, cwd: Path) -> dict[str, Any]:
    if executable is not None:
        version = _windows_file_version(executable)
        if version:
            return {
                "id": "browser",
                "required": True,
                "status": "ready",
                "executable": str(executable),
                "version": version,
                "requirement": None,
                "diagnostic": "",
            }
    return _tool_result("browser", executable, None, cwd=cwd)


def _python_requirement(engine_root: Path) -> tuple[str | None, str | None]:
    try:
        document = tomllib.loads(
            (engine_root / "pyproject.toml").read_text(encoding="utf-8")
        )
    except (OSError, tomllib.TOMLDecodeError) as error:
        return None, f"cannot read engine pyproject.toml: {error}"
    requirement = document.get("project", {}).get("requires-python")
    if not isinstance(requirement, str) or not requirement.strip():
        return None, "engine pyproject.toml does not declare requires-python"
    return requirement.replace(",", " "), None


def _build_requirement(engine_root: Path) -> tuple[str | None, str | None]:
    try:
        document = tomllib.loads(
            (engine_root / "pyproject.toml").read_text(encoding="utf-8")
        )
    except (OSError, tomllib.TOMLDecodeError) as error:
        return None, f"cannot read engine pyproject.toml: {error}"
    groups = document.get("project", {}).get("optional-dependencies", {})
    requirements = [
        str(item)
        for group in ("build", "release")
        for item in groups.get(group, ())
        if str(item).casefold().startswith("build==")
    ]
    if not requirements:
        return None, "engine does not exact-pin the Python build package"
    versions = sorted({item.split("==", 1)[1] for item in requirements})
    if len(versions) != 1:
        return None, "engine declares conflicting Python build package versions"
    return f"=={versions[0]}", None


def _python_build_result(
    python_executable: Path | None,
    requirement: str | None,
    configuration_error: str | None,
    *,
    cwd: Path,
) -> dict[str, Any]:
    base = {
        "id": "python-build",
        "required": True,
        "status": "missing",
        "executable": str(python_executable) if python_executable else None,
        "version": None,
        "requirement": requirement,
        "diagnostic": configuration_error or "Python executable is unavailable",
    }
    if configuration_error:
        return {**base, "status": "invalid-configuration"}
    if python_executable is None:
        return base
    probe = _run_probe(
        python_executable,
        (
            "-c",
            "import importlib.metadata as m; print(m.version('build'))",
        ),
        cwd=cwd,
    )
    if not probe["ok"]:
        return {
            **base,
            "diagnostic": "Python build package is missing or cannot be queried",
        }
    version_match = VERSION.search(probe["output"])
    version = version_match.group(0) if version_match else None
    compatible = bool(version and version_satisfies(version, requirement))
    return {
        **base,
        "version": version,
        "status": "ready" if compatible else "incompatible",
        "diagnostic": "" if compatible else f"found {version}; requires {requirement}",
    }

def _version_tuple(value: str) -> tuple[int, int, int] | None:
    match = VERSION.search(value)
    if not match:
        return None
    return tuple(int(part or 0) for part in match.groups())


def _satisfies_clause(version: tuple[int, int, int], clause: str) -> bool:
    match = COMPARATOR.fullmatch(clause.strip())
    if not match:
        raise ValueError(f"unsupported version constraint: {clause}")
    operator, raw_expected = match.groups()
    expected = _version_tuple(raw_expected)
    if expected is None:  # guarded by COMPARATOR; retained as a fail-closed check
        raise ValueError(f"invalid version constraint: {clause}")
    if operator == ">=":
        return version >= expected
    if operator == "<=":
        return version <= expected
    if operator == ">":
        return version > expected
    if operator == "<":
        return version < expected
    if operator == "^":
        ceiling = (expected[0] + 1, 0, 0)
        return expected <= version < ceiling
    if operator == "~":
        ceiling = (expected[0], expected[1] + 1, 0)
        return expected <= version < ceiling
    return version == expected


def version_satisfies(version: str, requirement: str | None) -> bool:
    """Evaluate the bounded semver subset used by the PX lock and manifests."""

    if not requirement:
        return True
    parsed = _version_tuple(version)
    if parsed is None:
        return False
    normalized = re.sub(r"(>=|<=|==|>|<|=|\^|~)\s+(?=\d)", r"\1", requirement)
    alternatives = [item.strip() for item in normalized.split("||") if item.strip()]
    if not alternatives:
        raise ValueError("version requirement is empty")
    for alternative in alternatives:
        clauses = [item for item in re.split(r"\s+", alternative) if item]
        if all(_satisfies_clause(parsed, clause) for clause in clauses):
            return True
    return False

def _lock_result(
    package: Mapping[str, Any] | None,
    lock: Mapping[str, Any] | None,
    read_errors: Sequence[str],
    extension_root: Path | None,
) -> dict[str, Any]:
    errors = list(read_errors)
    if package is not None and lock is not None:
        if lock.get("lockfileVersion") != 3:
            errors.append("package-lock.json must use lockfileVersion 3")
        packages = lock.get("packages")
        root = packages.get("") if isinstance(packages, Mapping) else None
        if not isinstance(root, Mapping):
            errors.append("package-lock.json is missing the root package record")
        else:
            for field in ("name", "version", "dependencies", "devDependencies"):
                if package.get(field, {}) != root.get(field, {}):
                    errors.append(
                        f"package-lock root {field} differs from package.json"
                    )
        for group in ("dependencies", "devDependencies"):
            declared = package.get(group, {})
            if not isinstance(declared, Mapping):
                errors.append(f"package.json {group} must be an object")
                continue
            floating = [
                name
                for name, value in declared.items()
                if not re.fullmatch(
                    r"\d+(?:\.\d+){2}(?:[-+][A-Za-z0-9.-]+)?", str(value)
                )
            ]
            if floating:
                errors.append(
                    f"package.json {group} is not exact-pinned: "
                    f"{', '.join(sorted(floating))}"
                )
            if extension_root is not None:
                for name, expected in sorted(declared.items()):
                    installed_path = (
                        extension_root / "node_modules" / name / "package.json"
                    )
                    try:
                        installed = json.loads(
                            installed_path.read_text(encoding="utf-8")
                        )
                        actual = installed.get("version")
                    except (OSError, json.JSONDecodeError, AttributeError) as error:
                        errors.append(
                            f"installed dependency {name} is unavailable: {error}"
                        )
                        continue
                    if actual != expected:
                        errors.append(
                            f"installed dependency {name} is {actual}; "
                            f"expected {expected}"
                        )
    return {
        "id": "node-package-lock",
        "required": True,
        "status": "ready" if not errors else "invalid-configuration",
        "executable": None,
        "version": str(lock.get("lockfileVersion")) if lock else None,
        "requirement": (
            "lockfileVersion 3; exact direct pins; installed direct dependency parity"
        ),
        "diagnostic": "; ".join(errors),
    }

