            if owner:
                edges.add((leaf_key, _record_key("skill", owner), "owned_by"))
            for dependency in _strings(item.get("dependencies")):
                edges.add((leaf_key, f"unresolved:{dependency}", "depends_on"))
            for extended in _strings(item.get("extends")):
                edges.add((leaf_key, f"unresolved:{extended}", "extends"))
            for formula_id in _strings(item.get("formula_refs")):
                edges.add(
                    (leaf_key, _record_key("formula", formula_id), "uses_formula")
                )

    # Target-owned capability registries are first-class map inputs. The source
    # pack omitted project_stream_capabilities.json, which made reviewed
    # workflow steps appear dangling even though their canonical declarations
    # were already present in the target.
    for capability_path in (
        root / "registry" / "project_stream_capabilities.json",
        root / "registry" / "metacognitive_capabilities.json",
    ):
        if not capability_path.is_file():
            continue
        payload = _json(capability_path)
        for item in payload.get("capabilities", ()):
            if not isinstance(item, Mapping) or not item.get("id"):
                continue
            identifier = str(item["id"])
            target_owners = _strings(item.get("target_owners"))
            implementation_level = str(item.get("implementation_level", ""))
            integration_state = str(item.get("integration_state", ""))
            if integration_state == "mapped_tested_owner" or not integration_state:
                status = "admitted"
            else:
                status = "mapped_deferred"
            risk_name = str(item.get("risk", item.get("risk_default", "R1")))
            risk = {"low": "R1", "medium": "R2", "high": "R3", "critical": "R4"}.get(
                risk_name, risk_name
            )
            _add(
                records,
                {
                    "id": identifier,
                    "kind": "capability",
                    "title": item.get("title", identifier.replace("-", " ")),
                    "summary": _first_text(item.get("purpose"), item.get("summary")),
                    "owner": _first_text(
                        *target_owners, item.get("owner"), "capability-registry"
                    ),
                    "status": status,
                    "domain": _first_text(
                        item.get("category"), item.get("domain"), "capability"
                    ),
                    "aliases": [identifier.replace("-", " "), item.get("title", "")],
                    "triggers": item.get("triggers", ()),
                    "concepts": [
                        item.get("invariant", ""),
                        implementation_level,
                        integration_state,
                    ],
                    "inputs": item.get("inputs", ()),
                    "outputs": item.get("outputs", ()),
                    "dependencies": item.get("dependencies", ()),
                    "formula_refs": item.get("formula_refs", ()),
                    "relations": target_owners,
                    "path": capability_path.relative_to(root).as_posix(),
                    "implementation_path": target_owners[0] if target_owners else "",
                    "source_sha256": hashlib.sha256(
                        capability_path.read_bytes()
                    ).hexdigest(),
                    "risk": risk,
                },
            )

    # Exact aliases point to a leaf when one exists; otherwise to the governed owner.
    for item in aliases:
        alias, owner = str(item.get("alias", "")), str(item.get("owner", ""))
        leaf_key = nested_by_normalized_id.get(normalize_text(alias))
        target = leaf_key if leaf_key in records else _record_key("skill", owner)
        if target in records and alias.strip():
            records[target]["aliases"] = sorted(
                set(records[target]["aliases"]) | {alias.strip()}
            )

    for formula_path in (
        root / "registry" / "metacognitive_formulas.json",
        root / "registry" / "declared_suite_formulas.json",
        root / "registry" / "brain_formulas.json",
    ):
        if not formula_path.is_file():
            continue
        payload = _json(formula_path)
        for item in _rows(payload):
            identifier = str(item.get("id", "")).strip()
            if not identifier:
                continue
            _add(
                records,
                {
                    "id": identifier,
                    "kind": "formula",
                    "title": item.get("title", identifier.replace("-", " ")),
                    "summary": _first_text(
                        item.get("use_when"), item.get("purpose"), item.get("summary")
                    ),
                    "owner": "formula-registry",
                    "status": item.get("status", "reference_only"),
                    "domain": _first_text(item.get("domain"), "formula"),
                    "aliases": [
                        identifier.replace("-", " "),
                        item.get("equation", ""),
                        item.get("expression", ""),
                    ],
                    "triggers": [item.get("use_when", "")],
                    "concepts": [
                        *_strings(item.get("caveats")),
                        *_strings(item.get("assumptions")),
                    ],
                    "inputs": item.get("variables", ()),
                    "path": formula_path.relative_to(root).as_posix(),
                    "source_sha256": hashlib.sha256(
                        formula_path.read_bytes()
                    ).hexdigest(),
                },
            )

    # Existing orchestration registries may include workflows not represented by leaf indexes.
    for workflow_path in (
        root / "registry" / "skill_orchestrations.json",
        root / "registry" / "project_stream_orchestrations.json",
    ):
        payload = _read_jsonish(workflow_path)
        if payload is None:
            continue
        for item in _rows(payload):
            identifier = _first_text(item.get("id"), item.get("orchestration_id"))
            if not identifier:
                continue
            member_ids: list[str] = []
            for step in (
                item.get("steps", ()) if isinstance(item.get("steps", ()), list) else ()
            ):
                if isinstance(step, Mapping):
                    member = _first_text(
                        step.get("skill_id"),
                        step.get("skill"),
                        step.get("capability"),
                        step.get("script"),
                    )
                    if member:
                        member_ids.append(member)
            member_ids.extend(_strings(item.get("skills")))
            _add(
                records,
                {
                    "id": identifier,
                    "kind": "workflow",
                    "title": identifier.replace("-", " "),
                    "summary": _first_text(
                        item.get("trigger"),
                        item.get("purpose"),
                        item.get("description"),
                    ),
                    "owner": item.get("canonical_owner", "workflow-registry"),
                    "status": item.get("status", "active"),
                    "domain": "orchestration",
                    "aliases": [identifier.replace("-", " ")],
                    "triggers": [item.get("trigger", "")],
                    "relations": member_ids,
                    "path": workflow_path.relative_to(root).as_posix(),
                    "source_sha256": hashlib.sha256(
                        workflow_path.read_bytes()
                    ).hexdigest(),
                },
            )
            for order, member in enumerate(member_ids):
                if member:
                    edges.add(
                        (
                            _record_key("workflow", identifier),
                            f"unresolved:{member}",
                            f"step:{order}",
                        )
                    )

    knowledge_path = root / "registry" / "knowledge_sources.json"
    if knowledge_path.is_file():
        knowledge_payload = _json(knowledge_path)
        for item in knowledge_payload.get(
            "knowledge_sources", knowledge_payload.get("sources", ())
        ):
            identifier = str(item.get("id", "")).strip()
            if not identifier:
                continue
            _add(
                records,
                {
                    "id": identifier,
                    "kind": "knowledge",
                    "title": identifier.replace("-", " "),
                    "summary": _first_text(item.get("summary"), item.get("kind")),
                    "owner": "knowledge-registry",
                    "status": item.get("status", "active"),
                    "domain": "knowledge",
                    "aliases": [identifier.replace("-", " ")],
                    "relations": item.get("uses", ()),
                    "path": item.get("location", ""),
                },
            )

    # Resolve declared identifiers only through reviewed mappings or one
    # unambiguous exact/normalized identity.
    resolution_path = root / "registry" / "cognitive_dependency_resolutions.json"
    explicit_resolutions: dict[str, str] = {}
    if resolution_path.is_file():
        resolution_payload = _json(resolution_path)
        rows = resolution_payload.get("records", ())
        if resolution_payload.get("count") != len(rows):
            raise ValueError("cognitive dependency resolution count mismatch")
        for item in rows:
            identifier = str(item.get("identifier", ""))
            target_key = str(item.get("target_key", ""))
            if not identifier or not target_key or item.get("status") != "reviewed":
                raise ValueError(
                    "cognitive dependency resolutions must be reviewed and complete"
                )
            if identifier in explicit_resolutions:
                raise ValueError(
                    f"duplicate cognitive dependency resolution: {identifier}"
                )
            explicit_resolutions[identifier] = target_key

    known_ids: dict[str, list[str]] = {}
    normalized_ids: dict[str, list[str]] = {}
    for key, record in records.items():
        known_ids.setdefault(str(record["id"]), []).append(key)
        for identity in (
            record.get("id", ""),
            record.get("title", ""),
            *record.get("aliases", ()),
        ):
            normalized = normalize_text(str(identity))
            if normalized:
                normalized_ids.setdefault(normalized, []).append(key)
    resolved_edges: set[tuple[str, str, str]] = set()
    for source, target, relation in edges:
        if target.startswith("unresolved:"):
            identifier = target.split(":", 1)[1]
            explicit = explicit_resolutions.get(identifier)
            if explicit is not None:
                if explicit not in records:
                    raise ValueError(
                        f"cognitive dependency resolution target is absent: {identifier} -> {explicit}"
                    )
                target = explicit
            else:
                candidates = known_ids.get(identifier, ())
                if not candidates:
                    candidates = tuple(
                        sorted(set(normalized_ids.get(normalize_text(identifier), ())))
                    )
                target = candidates[0] if len(candidates) == 1 else target
        resolved_edges.add((source, target, relation))

    ordered_records = sorted(
        records.values(), key=lambda item: (item["kind"], item["id"])
    )
    ordered_edges = [
        {"source": source, "target": target, "relation": relation}
        for source, target, relation in sorted(resolved_edges)
    ]
    revision = stable_hash({"records": ordered_records, "edges": ordered_edges})
    counts: dict[str, int] = {}
    for record in ordered_records:
        counts[record["kind"]] = counts.get(record["kind"], 0) + 1
    return {
        "schema_version": "1.1",
        "loading_rule": "metadata_only_global_map_then_hydrate_selected_records",
        "revision": revision,
        "record_count": len(ordered_records),
        "edge_count": len(ordered_edges),
        "kind_counts": dict(sorted(counts.items())),
        "records": ordered_records,
        "edges": ordered_edges,
    }

def validate_cognitive_index(
    root: Path, actual: dict[str, Any] | None = None
) -> dict[str, Any]:
    expected = build_cognitive_index(root)
    errors: list[str] = []
    if actual is not None and actual != expected:
        errors.append("cognitive index is stale or non-deterministic")
    keys = [item["key"] for item in expected["records"]]
    if len(keys) != len(set(keys)):
        errors.append("cognitive index contains duplicate keys")
    known = set(keys)
    unresolved = [
        edge for edge in expected["edges"] if edge["target"].startswith("unresolved:")
    ]
    dangling = [
        edge
        for edge in expected["edges"]
        if not edge["target"].startswith("unresolved:") and edge["target"] not in known
    ]
    if dangling:
        errors.append(f"cognitive index has dangling edges: {len(dangling)}")
    return {
        "valid": not errors,
        "record_count": expected["record_count"],
        "edge_count": expected["edge_count"],
        "kind_counts": expected["kind_counts"],
        "unresolved_external_dependencies": len(unresolved),
        "revision": expected["revision"],
        "errors": errors,
    }

"""Scoped belief ledger and bounded truth-maintenance projection."""

from __future__ import annotations

from collections import defaultdict
from collections.abc import Mapping, Sequence
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Any

from .common import clamp, stable_hash


def _parse_time(raw: object, field: str) -> datetime | None:
    if raw is None or raw == "":
        return None
    value = datetime.fromisoformat(str(raw).replace("Z", "+00:00"))
    if value.tzinfo is None or value.utcoffset() is None:
        raise ValueError(f"{field} must include an explicit timezone")
    return value.astimezone(timezone.utc)


@dataclass(frozen=True, slots=True)
class Belief:
    belief_id: str
    subject: str
    predicate: str
    value: Any
    scope: str
    valid_from: datetime | None
    valid_to: datetime | None
    confidence: float
    supports: tuple[str, ...]
    attacks: tuple[str, ...]
    dependencies: tuple[str, ...]
    status: str = "candidate"

    @classmethod
    def from_mapping(cls, value: Mapping[str, Any]) -> "Belief":
        belief_id = str(value.get("id", "")).strip()
        subject = str(value.get("subject", "")).strip()
        predicate = str(value.get("predicate", "")).strip()
        if not belief_id or not subject or not predicate:
            raise ValueError("belief id, subject, and predicate are required")
        confidence = float(value.get("confidence", 0.5))
        if not 0.0 <= confidence <= 1.0:
            raise ValueError(f"belief {belief_id}: confidence must be in [0, 1]")
        valid_from = _parse_time(
            value.get("valid_from"), f"belief {belief_id} valid_from"
        )
        valid_to = _parse_time(value.get("valid_to"), f"belief {belief_id} valid_to")
        if valid_from and valid_to and valid_to < valid_from:
            raise ValueError(f"belief {belief_id}: valid_to precedes valid_from")
        return cls(
            belief_id,
            subject,
            predicate,
            value.get("value"),
            str(value.get("scope", "global")),
            valid_from,
            valid_to,
            confidence,
            tuple(map(str, value.get("supports", ()))),
            tuple(map(str, value.get("attacks", ()))),
            tuple(map(str, value.get("dependencies", ()))),
            str(value.get("status", "candidate")),
        )


def _overlap(left: Belief, right: Belief) -> bool:
    start = max(filter(None, (left.valid_from, right.valid_from)), default=None)
    end = min(filter(None, (left.valid_to, right.valid_to)), default=None)
    return not (start and end and end < start)


class BeliefLedger:
    def __init__(self, beliefs: Sequence[Belief]) -> None:
        ids = [belief.belief_id for belief in beliefs]
        if len(ids) != len(set(ids)):
            raise ValueError("belief IDs must be unique")
        self.beliefs = {belief.belief_id: belief for belief in beliefs}
        for belief in beliefs:
            unknown = (
                set(belief.supports) | set(belief.attacks) | set(belief.dependencies)
            ) - set(ids)
            if unknown:
                raise ValueError(
                    f"belief {belief.belief_id}: unknown links {sorted(unknown)}"
                )
            if belief.belief_id in set(belief.supports) | set(belief.attacks) | set(
                belief.dependencies
            ):
                raise ValueError(f"belief {belief.belief_id}: self-links are forbidden")

    def project(
        self, *, as_of: datetime | None = None, scope: str | None = None
    ) -> dict[str, Any]:
        now = as_of or datetime.now(timezone.utc)
        if now.tzinfo is None or now.utcoffset() is None:
            raise ValueError("as_of must include an explicit timezone")
        now = now.astimezone(timezone.utc)
        active = {
            key: belief
            for key, belief in self.beliefs.items()
            if (scope is None or belief.scope == scope)
            and (belief.valid_from is None or belief.valid_from <= now)
            and (belief.valid_to is None or now <= belief.valid_to)
            and belief.status not in {"revoked", "superseded"}
        }
        scores = {key: belief.confidence for key, belief in active.items()}
        converged = True
        iterations = 0
        # Bounded fixed-point influence. An isolated belief retains its base confidence.
        for iteration in range(1, 51):
            iterations = iteration
            updated = dict(scores)
            for key, belief in active.items():
                support = (
                    sum(scores.get(item, 0.0) for item in belief.supports)
                    / len(belief.supports)
                    if belief.supports
                    else 0.0
                )
                attack = (
                    sum(scores.get(item, 0.0) for item in belief.attacks)
                    / len(belief.attacks)
                    if belief.attacks
                    else 0.0
                )
                dependency = min(
                    (scores.get(item, 0.0) for item in belief.dependencies), default=1.0
                )
                strengthened = belief.confidence + 0.25 * support * (
                    1.0 - belief.confidence
                )
                weakened = strengthened - 0.35 * attack * strengthened
                updated[key] = clamp(weakened * dependency)
            delta = max(
                (abs(updated[key] - scores[key]) for key in scores), default=0.0
            )
            scores = updated
            if delta < 1e-9:
                break
        else:
            converged = False

        grouped: dict[tuple[str, str, str], list[Belief]] = defaultdict(list)
        for belief in active.values():
            grouped[(belief.subject, belief.predicate, belief.scope)].append(belief)
        contradictions = []
        for key, group in grouped.items():
            for index, left in enumerate(group):
                for right in group[index + 1 :]:
                    if left.value != right.value and _overlap(left, right):
                        contradictions.append(
                            {
                                "subject": key[0],
                                "predicate": key[1],
                                "scope": key[2],
                                "left": left.belief_id,
                                "right": right.belief_id,
                                "left_effective_confidence": scores[left.belief_id],
                                "right_effective_confidence": scores[right.belief_id],
                                "resolution": "preserve_conflict_until_scope_time_or_evidence_resolves",
                            }
                        )
        records = [
            {
                "id": belief.belief_id,
                "subject": belief.subject,
                "predicate": belief.predicate,
                "value": belief.value,
                "scope": belief.scope,
                "status": belief.status,
                "base_confidence": belief.confidence,
                "effective_confidence": scores[belief.belief_id],
                "supports": list(belief.supports),
                "attacks": list(belief.attacks),
                "dependencies": list(belief.dependencies),
            }
            for belief in sorted(active.values(), key=lambda item: item.belief_id)
        ]
        result = {
            "valid": converged,
            "as_of": now.isoformat(),
            "scope": scope,
            "beliefs": records,
            "contradictions": contradictions,
            "fixed_point_converged": converged,
            "iterations": iterations,
            "warning": "Confidence influence is a bounded policy heuristic; it is not a substitute for calibrated probability or source-specific likelihood models.",
        }
        return {**result, "result_sha256": stable_hash(result)}


def project(payload: Mapping[str, Any]) -> dict[str, Any]:
    beliefs = tuple(Belief.from_mapping(item) for item in payload.get("beliefs", ()))
    as_of = _parse_time(payload.get("as_of"), "as_of")
    return BeliefLedger(beliefs).project(
        as_of=as_of, scope=str(payload["scope"]) if payload.get("scope") else None
    )

