def choose_runtime(
    profiles: Sequence[Mapping[str, object]],
    *,
    project_id: str,
    required_capabilities: Iterable[str],
    minimum_trust: int,
    locality: str | None = None,
) -> dict[str, object]:
    """Choose a runtime only after hard trust, health, scope, and quota filters."""
    required = set(map(str, required_capabilities))
    eligible = []
    rejected: dict[str, tuple[str, ...]] = {}
    for profile in profiles:
        profile_id = str(profile.get("id", ""))
        reasons = []
        if profile.get("healthy") is not True:
            reasons.append("unhealthy")
        if int(profile.get("trust", 0)) < minimum_trust:
            reasons.append("trust")
        if not required <= set(map(str, profile.get("capabilities", ()))):
            reasons.append("capability")
        scopes = set(map(str, profile.get("project_scopes", ())))
        if scopes and project_id not in scopes:
            reasons.append("project_scope")
        if locality and profile.get("locality") != locality:
            reasons.append("locality")
        if float(profile.get("available_quota", 0)) <= 0:
            reasons.append("quota")
        if reasons:
            rejected[profile_id] = tuple(reasons)
        else:
            eligible.append(profile)
    selected = min(
        eligible,
        key=lambda row: (float(row.get("cost", 0)), str(row.get("id", ""))),
        default=None,
    )
    payload = {
        "project_id": project_id,
        "selected_runtime": str(selected.get("id")) if selected else None,
        "rejected": tuple(sorted(rejected.items())),
        "valid": selected is not None,
    }
    return {**payload, "placement_sha256": stable_hash(payload)}

def evaluate_offline_skill_candidate(
    *,
    baseline: Sequence[Mapping[str, object]],
    candidate: Sequence[Mapping[str, object]],
    heldout_case_ids: Iterable[str],
    actor_id: str,
    optimizer_id: str,
    judge_id: str,
    max_regressions: int = 0,
) -> dict[str, object]:
    """Evaluate a quarantined skill candidate without permitting self-promotion."""
    if len({actor_id, optimizer_id, judge_id}) < 3:
        raise ValueError("actor, optimizer, and judge must be distinct")
    base = {str(row["case_id"]): float(row["score"]) for row in baseline}
    proposed = {str(row["case_id"]): float(row["score"]) for row in candidate}
    heldout = set(map(str, heldout_case_ids))
    if heldout - base.keys() or heldout - proposed.keys():
        raise ValueError("held-out cases must exist in both matched rollouts")
    regressions = tuple(sorted(case for case in heldout if proposed[case] < base[case]))
    improvements = tuple(
        sorted(case for case in heldout if proposed[case] > base[case])
    )
    payload = {
        "decision": "proposal_ready"
        if len(regressions) <= max_regressions and improvements
        else "reject",
        "activation": "quarantined_candidate",
        "heldout_cases": tuple(sorted(heldout)),
        "improvements": improvements,
        "regressions": regressions,
        "requires_independent_promotion": True,
    }
    return {**payload, "experiment_sha256": stable_hash(payload)}

def fingerprint_repository(files: Sequence[Mapping[str, object]]) -> dict[str, object]:
    """Fingerprint mechanisms and structure without treating a repository as canon."""
    normalized = tuple(
        sorted(
            (
                str(item.get("path", "")).replace("\\", "/"),
                int(item.get("bytes", 0)),
                str(item.get("sha256", "")),
            )
            for item in files
        )
    )
    suffixes: dict[str, int] = defaultdict(int)
    for path, _size, _digest in normalized:
        suffix = path.rsplit(".", 1)[-1].casefold() if "." in path else "none"
        suffixes[suffix] += 1
    payload = {
        "file_count": len(normalized),
        "total_bytes": sum(item[1] for item in normalized),
        "suffix_counts": dict(sorted(suffixes.items())),
        "tree_sha256": stable_hash(normalized),
    }
    return {**payload, "fingerprint_sha256": stable_hash(payload)}

def invalidate_dependents(
    changed_fact_ids: Iterable[str], dependencies: Mapping[str, Iterable[str]]
) -> dict[str, object]:
    """Compute bounded transitive invalidation without mutating source facts."""
    changed = set(map(str, changed_fact_ids))
    invalidated = set(changed)
    progressed = True
    while progressed:
        progressed = False
        for dependent, sources in sorted(dependencies.items()):
            if dependent not in invalidated and invalidated & set(map(str, sources)):
                invalidated.add(dependent)
                progressed = True
    payload = {
        "changed": tuple(sorted(changed)),
        "invalidated": tuple(sorted(invalidated - changed)),
    }
    return {**payload, "invalidation_sha256": stable_hash(payload)}

def optimize_candidate_package(
    candidates: Sequence[Mapping[str, object]],
    *,
    required_capabilities: Iterable[str] = (),
    required_kinds: Iterable[str] = (),
    max_cost: float,
    max_items: int = 15,
    family_floor: float = 0.35,
) -> dict[str, object]:
    """Select a dependency-closed package by deterministic marginal utility."""
    if max_cost < 0 or max_items < 1 or not 0 <= family_floor <= 1:
        raise ValueError("invalid package budget")
    records = {str(item["id"]): dict(item) for item in candidates}
    required_caps = set(map(str, required_capabilities))
    required_kind_set = set(map(str, required_kinds))
    selected: list[str] = []
    covered: set[str] = set()
    families: dict[str, int] = defaultdict(int)
    spent = 0.0
    rejected: dict[str, str] = {}

    def adjusted(item: Mapping[str, object]) -> tuple[float, str]:
        family = str(item.get("family", item.get("provider", "default")))
        attenuation = max(family_floor, 1.0 / (families[family] + 1))
        capabilities = set(map(str, item.get("capabilities", ())))
        marginal = len((required_caps - covered) & capabilities)
        score = float(item.get("intrinsic_score", 0.0)) * attenuation + 25 * marginal
        return score, str(item["id"])

    while len(selected) < max_items:
        eligible = []
        for item in records.values():
            candidate_id = str(item["id"])
            if candidate_id in selected or candidate_id in rejected:
                continue
            if item.get("admitted") is not True:
                rejected[candidate_id] = "not_admitted"
                continue
            cost = float(item.get("cost", 0.0))
            if spent + cost > max_cost:
                rejected[candidate_id] = "cost_budget"
                continue
            eligible.append(item)
        if not eligible:
            break
        item = min(eligible, key=lambda row: (-adjusted(row)[0], adjusted(row)[1]))
        candidate_id = str(item["id"])
        score, _ = adjusted(item)
        if score <= 0 and required_caps <= covered:
            rejected[candidate_id] = "no_marginal_utility"
            continue
        selected.append(candidate_id)
        spent += float(item.get("cost", 0.0))
        covered.update(map(str, item.get("capabilities", ())))
        families[str(item.get("family", item.get("provider", "default")))] += 1
        if required_caps <= covered and required_kind_set <= {
            str(records[value].get("kind", "")) for value in selected
        }:
            break

    cursor = 0
    errors: list[str] = []
    while cursor < len(selected):
        current_id = selected[cursor]
        cursor += 1
        for dependency in map(str, records[current_id].get("dependencies", ())):
            if dependency in selected:
                continue
            target = records.get(dependency)
            if target is None or target.get("admitted") is not True:
                errors.append(f"unresolved_dependency:{current_id}:{dependency}")
                continue
            cost = float(target.get("cost", 0.0))
            if len(selected) >= max_items or spent + cost > max_cost:
                errors.append(f"dependency_budget:{current_id}:{dependency}")
                continue
            selected.append(dependency)
            spent += cost

    selected_set = set(selected)
    for candidate_id in sorted(records):
        if candidate_id not in selected_set and candidate_id not in rejected:
            rejected[candidate_id] = "not_needed_after_coverage"
    missing_caps = sorted(required_caps - covered)
    present_kinds = {str(records[value].get("kind", "")) for value in selected}
    missing_kinds = sorted(required_kind_set - present_kinds)
    if missing_caps:
        errors.append("missing_capabilities:" + ",".join(missing_caps))
    if missing_kinds:
        errors.append("missing_kinds:" + ",".join(missing_kinds))
    payload = {
        "selected": tuple(selected),
        "spent": round(spent, 6),
        "covered_capabilities": tuple(sorted(covered)),
        "rejected": tuple(sorted(rejected.items())),
        "complete": not errors and bool(selected),
        "errors": tuple(sorted(set(errors))),
    }
    return {**payload, "package_sha256": stable_hash(payload)}

def query_bitemporal_facts(
    facts: Sequence[Mapping[str, object]],
    *,
    valid_at: str,
    known_at: str,
    project_id: str,
) -> tuple[Mapping[str, object], ...]:
    """Return facts valid in the world and known to the system at separate times."""
    valid_point = datetime.fromisoformat(valid_at.replace("Z", "+00:00"))
    known_point = datetime.fromisoformat(known_at.replace("Z", "+00:00"))

    def point(value: object, fallback: datetime) -> datetime:
        if value in {None, ""}:
            return fallback
        return datetime.fromisoformat(str(value).replace("Z", "+00:00"))

    low = datetime.min.replace(tzinfo=timezone.utc)
    high = datetime.max.replace(tzinfo=timezone.utc)
    selected = []
    for fact in facts:
        if str(fact.get("project_id")) != project_id or fact.get("revoked") is True:
            continue
        valid = (
            point(fact.get("valid_from"), low)
            <= valid_point
            < point(fact.get("valid_to"), high)
        )
        known = (
            point(fact.get("known_from"), low)
            <= known_point
            < point(fact.get("known_to"), high)
        )
        if valid and known:
            selected.append(fact)
    return tuple(sorted(selected, key=lambda item: str(item.get("fact_id", ""))))

def reconcile_budget(
    reservation: Mapping[str, object], actual: Mapping[str, float]
) -> dict[str, object]:
    if reservation.get("state") != "active":
        raise ValueError("only active reservations can be reconciled")
    reserved = dict(reservation.get("reserved", {}))
    overages = tuple(
        sorted(
            name
            for name, value in actual.items()
            if float(value) > float(reserved.get(name, 0.0))
        )
    )
    payload = {
        "reservation_id": reservation.get("reservation_id"),
        "actual": {key: float(value) for key, value in sorted(actual.items())},
        "released": {
            key: max(0.0, float(value) - float(actual.get(key, 0.0)))
            for key, value in sorted(reserved.items())
        },
        "state": "reconciled_with_overage" if overages else "reconciled",
        "overages": overages,
    }
    return {**payload, "receipt_sha256": stable_hash(payload)}

def reserve_budget(
    *,
    project_id: str,
    work_id: str,
    requested: Mapping[str, float],
    limits: Mapping[str, float],
    active_reservations: Sequence[Mapping[str, object]] = (),
) -> dict[str, object]:
    """Reserve multiple resource dimensions atomically or deny all of them."""
    if not project_id or not work_id:
        raise ValueError("project_id and work_id are required")
    used: dict[str, float] = defaultdict(float)
    for reservation in active_reservations:
        if (
            reservation.get("project_id") != project_id
            or reservation.get("state") != "active"
        ):
            continue
        for name, value in dict(reservation.get("reserved", {})).items():
            used[str(name)] += float(value)
    blockers = []
    for name, value in sorted(requested.items()):
        if float(value) < 0:
            blockers.append(f"negative_request:{name}")
        elif used[name] + float(value) > float(limits.get(name, 0.0)):
            blockers.append(f"limit_exceeded:{name}")
    payload = {
        "project_id": project_id,
        "work_id": work_id,
        "reserved": {key: float(value) for key, value in sorted(requested.items())},
        "state": "denied" if blockers else "active",
        "blockers": tuple(blockers),
    }
    return {**payload, "reservation_id": "res_" + stable_hash(payload)[:20]}

def synthesize_mechanism_delta(
    mechanisms: Sequence[Mapping[str, object]],
    canonical_capability_ids: Iterable[str],
) -> dict[str, object]:
    """Classify mechanism-level novelty; never promote whole repositories."""
    canonical = set(map(str, canonical_capability_ids))
    records = []
    for item in sorted(mechanisms, key=lambda row: str(row.get("mechanism_id", ""))):
        mechanism_id = str(item.get("mechanism_id", ""))
        owner = str(item.get("canonical_owner", ""))
        if not mechanism_id or not item.get("evidence_ids"):
            disposition = "review"
        elif owner in canonical:
            disposition = "enrich"
        else:
            disposition = "novel_candidate"
        records.append((mechanism_id, disposition, owner or None))
    payload = {
        "records": tuple(records),
        "promotion_allowed": False,
        "next_boundary": "knowledge_refinery_admission",
    }
    return {**payload, "delta_sha256": stable_hash(payload)}

def transition_job(
    job: Mapping[str, object], target_state: str, *, evidence_ids: Iterable[str] = ()
) -> dict[str, object]:
    """Translate external agent/job states into a sticky canonical lifecycle."""
    allowed = {
        "queued": {"running", "cancelled"},
        "running": TERMINAL_JOB_STATES | {"paused"},
        "paused": {"running", "cancelled", "timed_out"},
    }
    current = str(job.get("state", "queued"))
    if current in TERMINAL_JOB_STATES and target_state != current:
        raise ValueError("terminal job state is sticky")
    if current not in TERMINAL_JOB_STATES and target_state not in allowed.get(
        current, set()
    ):
        raise ValueError(f"invalid transition: {current}->{target_state}")
    evidence = tuple(sorted(set(map(str, evidence_ids))))
    if target_state == "succeeded" and not evidence:
        raise ValueError("success requires outcome evidence")
    payload = {
        "job_id": str(job["job_id"]),
        "project_id": str(job["project_id"]),
        "state": target_state,
        "evidence_ids": evidence,
        "previous_state": current,
    }
    return {**payload, "transition_sha256": stable_hash(payload)}

def validate_candidate_stage_trace(
    trace: Sequence[Mapping[str, object]],
    *,
    required_components: Iterable[str] = (),
) -> dict[str, object]:
    """Validate stage order, membership authority, and explicit failures."""
    errors: list[str] = []
    stages = tuple(str(item.get("stage", "")) for item in trace)
    if stages != PIPELINE_STAGES:
        errors.append("pipeline stages are missing, duplicated, or out of order")
    required = set(required_components)
    observed_components: set[str] = set()
    previous_ids: tuple[str, ...] | None = None
    removals: set[str] = set()
    for item in trace:
        stage = str(item.get("stage", ""))
        component = str(item.get("component", ""))
        if component:
            observed_components.add(component)
        status = str(item.get("status", ""))
        required_component = bool(item.get("required", component in required))
        if status not in {"ok", "abstained", "failed"}:
            errors.append(f"{stage}: component status is not explicit")
        if required_component and status != "ok":
            errors.append(f"{stage}: required component did not succeed")
        if not required_component and status == "failed":
            errors.append(f"{stage}: optional failure must be recorded as abstained")
        input_ids = tuple(str(value) for value in item.get("input_ids", ()))
        output_ids = tuple(str(value) for value in item.get("output_ids", ()))
        if len(output_ids) != len(set(output_ids)):
            errors.append(f"{stage}: duplicate candidate identity")
        if stage in MEMBERSHIP_PRESERVING and input_ids != output_ids:
            errors.append(f"{stage}: membership or order changed outside a filter")
        if previous_ids is not None and input_ids != previous_ids:
            errors.append(f"{stage}: input does not equal prior stage output")
        if stage in {"hard_filtering", "post_selection_filtering"}:
            removed = set(input_ids) - set(output_ids)
            reasons = item.get("removal_reasons", {})
            if not isinstance(reasons, Mapping) or removed - set(map(str, reasons)):
                errors.append(f"{stage}: removed candidate lacks a reason")
            removals.update(removed)
        previous_ids = output_ids
    missing_components = sorted(required - observed_components)
    if missing_components:
        errors.append("required components absent: " + ", ".join(missing_components))
    payload = {
        "valid": not errors,
        "stages": stages,
        "removed_candidates": tuple(sorted(removals)),
        "errors": tuple(errors),
    }
    return {**payload, "trace_sha256": stable_hash(payload)}

def validate_completion_control_workflow(root: Path) -> dict[str, object]:
    """Validate that every consolidated late-intake control is executable."""
    path = root / "orchestration/workflows/completion-controls.yaml"
    errors: list[str] = []
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        return {"valid": False, "errors": [str(exc)]}
    expected = {
        "candidate-pipeline",
        "distributed-runtime",
        "epistemic-evolution",
        "deliverable-validation",
        "research-engine",
    }
    workflows = payload.get("workflows", ())
    ids = {str(item.get("id", "")) for item in workflows if isinstance(item, Mapping)}
    if ids != expected:
        errors.append("completion-control workflow set is incomplete or duplicated")
    for workflow in workflows:
        if not isinstance(workflow, Mapping):
            errors.append("workflow must be an object")
            continue
        steps = workflow.get("steps", ())
        step_ids = {
            str(step.get("id", "")) for step in steps if isinstance(step, Mapping)
        }
        if not steps or "verify" not in step_ids:
            errors.append(f"{workflow.get('id')}: executable verification is missing")
        for step in steps:
            if not isinstance(step, Mapping):
                continue
            unknown = set(map(str, step.get("depends_on", ()))) - step_ids
            if unknown:
                errors.append(
                    f"{workflow.get('id')}:{step.get('id')}: unknown dependencies"
                )
    return {"valid": not errors, "workflow_count": len(ids), "errors": errors}

def validate_delivery(
    *,
    expected: Mapping[str, object],
    observed: Mapping[str, object],
    domain: str,
) -> dict[str, object]:
    """Validate physical or media promises; generated output is never proof."""
    blockers: list[str] = []
    unknowns: list[str] = []
    for field, promised in sorted(expected.items()):
        if field not in observed:
            unknowns.append(str(field))
        elif observed[field] != promised:
            blockers.append(f"mismatch:{field}")
    if observed.get("provider_downgrade"):
        blockers.append("silent_provider_downgrade")
    if domain in {"cad", "manufacturing", "robotics"}:
        required_checks = {"dimensions", "topology", "interference"}
        if domain == "manufacturing":
            required_checks.add("manufacturability")
        if domain == "robotics":
            required_checks.update({"joint_limits", "frames"})
        passed = set(map(str, observed.get("independent_checks", ())))
        for check in sorted(required_checks - passed):
            blockers.append(f"missing_independent_check:{check}")
    payload = {
        "domain": domain,
        "valid": not blockers and not unknowns,
        "blockers": tuple(blockers),
        "unknowns": tuple(unknowns),
    }
    return {**payload, "validation_sha256": stable_hash(payload)}

def verify_batch_independent_scores(
    baseline: Mapping[str, Mapping[str, float]],
    expanded: Mapping[str, Mapping[str, float]],
) -> dict[str, object]:
    """Prove that unrelated batch additions cannot change intrinsic scores."""
    changed = []
    for candidate_id, components in sorted(baseline.items()):
        if candidate_id not in expanded or dict(components) != dict(
            expanded[candidate_id]
        ):
            changed.append(candidate_id)
    payload = {"valid": not changed, "changed_candidate_ids": tuple(changed)}
    return {**payload, "evidence_sha256": stable_hash(payload)}

def validate_contract_corpus(root: Path) -> dict[str, Any]:
    contract_root = root / "contracts"
    ownership = _load(root / "registry" / "contract_ownership.json")
    ownership_records = ownership.get("records", ())
    ownership_by_path = {
        str(item.get("path")): item
        for item in ownership_records
        if isinstance(item, dict)
    }
    paths = sorted(
        path.relative_to(root).as_posix() for path in contract_root.rglob("*.json")
    )
    errors: list[str] = []
    owned: dict[str, str] = {}
    contract_digests: dict[str, str] = {}
    for relative in paths:
        path = root / relative
        schema: dict[str, Any] = {}
        try:
            schema = _load(path)
            errors.extend(
                f"{relative}: {item}" for item in _schema_structure_errors(schema)
            )
            if schema.get("$schema") != SUPPORTED_DIALECT:
                errors.append(f"{relative}: missing Draft 2020-12 declaration")
            expected_id = f"urn:engineering-loop-bootstrap:contract:{relative.removeprefix('contracts/').removesuffix('.schema.json').replace('/', ':')}"
            if schema.get("$id") != expected_id:
                errors.append(f"{relative}: unstable or missing contract id")
            _admit_schema(schema, path, contract_root.resolve(strict=True))
            contract_digests[relative] = contract_digest(
                path, contract_root=contract_root
            )
            example = build_minimal_instance(path, contract_root=contract_root)
            example_errors = _errors(
                example, schema, schema, path, "$", contract_root.resolve(strict=True)
            )
            errors.extend(
                f"{relative}: generated valid fixture failed: {item}"
                for item in example_errors
            )
            if schema.get("required") and not _errors(
                {}, schema, schema, path, "$", contract_root.resolve(strict=True)
            ):
                errors.append(
                    f"{relative}: empty-object negative fixture unexpectedly passed"
                )

def validate_contract_corpus(root: Path) -> dict[str, Any]:
    contract_root = root / "contracts"
    ownership = _load(root / "registry" / "contract_ownership.json")
    ownership_records = ownership.get("records", ())
    ownership_by_path = {
        str(item.get("path")): item
        for item in ownership_records
        if isinstance(item, dict)
    }
    paths = sorted(
        path.relative_to(root).as_posix() for path in contract_root.rglob("*.json")
    )
    errors: list[str] = []
    owned: dict[str, str] = {}
    contract_digests: dict[str, str] = {}
    for relative in paths:
        path = root / relative
        schema: dict[str, Any] = {}
        try:
            schema = _load(path)
            errors.extend(
                f"{relative}: {item}" for item in _schema_structure_errors(schema)
            )
            if schema.get("$schema") != SUPPORTED_DIALECT:
                errors.append(f"{relative}: missing Draft 2020-12 declaration")
            expected_id = f"urn:engineering-loop-bootstrap:contract:{relative.removeprefix('contracts/').removesuffix('.schema.json').replace('/', ':')}"
            if schema.get("$id") != expected_id:
                errors.append(f"{relative}: unstable or missing contract id")
            _admit_schema(schema, path, contract_root.resolve(strict=True))
            contract_digests[relative] = contract_digest(
                path, contract_root=contract_root
            )
            example = build_minimal_instance(path, contract_root=contract_root)
            example_errors = _errors(
                example, schema, schema, path, "$", contract_root.resolve(strict=True)
            )
            errors.extend(
                f"{relative}: generated valid fixture failed: {item}"
                for item in example_errors
            )
            if schema.get("required") and not _errors(
                {}, schema, schema, path, "$", contract_root.resolve(strict=True)
            ):
                errors.append(
                    f"{relative}: empty-object negative fixture unexpectedly passed"
                )
        except (OSError, ValueError, KeyError, json.JSONDecodeError) as error:
            errors.append(f"{relative}: {error}")
        ownership_record = ownership_by_path.get(relative)
        if ownership_record is None:
            errors.append(f"{relative}: missing explicit ownership record")
        else:
            owner = str(ownership_record.get("owner", ""))
            if not owner or not declared_file_available(root, owner):
                errors.append(f"{relative}: missing runtime owner {owner}")
            owned[relative] = owner
            if ownership_record.get("packaged") is not True:
                errors.append(f"{relative}: shipped contract is not marked packaged")
            if not ownership_record.get("enforcement"):
                errors.append(f"{relative}: missing enforcement classification")
            if ownership_record.get("contract_id") != schema.get("$id"):
                errors.append(f"{relative}: ownership contract id mismatch")
            if ownership_record.get("contract_version") != "1.0.0":
                errors.append(
                    f"{relative}: ownership contract version is missing or invalid"
                )
            for producer in ownership_record.get("producers", ()):
                if not declared_file_available(root, str(producer)):
                    errors.append(f"{relative}: missing producer {producer}")
            for test in ownership_record.get("tests", ()):
                if not declared_file_available(root, str(test)):
                    errors.append(f"{relative}: missing ownership test {test}")
    extras = sorted(set(ownership_by_path) - set(paths))
    errors.extend(
        f"ownership record references missing contract: {relative}"
        for relative in extras
    )
    if ownership.get("contract_count") != len(paths):
        errors.append("contract ownership count does not match corpus")

def _admit_schema(
    schema: dict[str, Any], schema_path: Path, contract_root: Path
) -> set[Path]:
    dependencies = {schema_path.resolve(strict=True)}
    validated_documents: set[Path] = set()

    def validate_document(document: dict[str, Any], document_path: Path) -> None:
        if document_path in validated_documents:
            return
        document_errors = _schema_structure_errors(document)
        if document.get("$schema") != SUPPORTED_DIALECT:
            document_errors.append(f"$: schema dialect must be {SUPPORTED_DIALECT}")
        if document_errors:
            raise ValueError("schema admission failed: " + "; ".join(document_errors))
        validated_documents.add(document_path)

    def walk(
        rule: dict[str, Any],
        document: dict[str, Any],
        document_path: Path,
        ref_stack: tuple[str, ...],
    ) -> None:
        if "$ref" in rule:
            resolved, resolved_document, resolved_path, key = _resolve_ref(
                rule["$ref"], document, document_path, contract_root
            )
            if key in ref_stack:
                chain = " -> ".join((*ref_stack, key))
                raise ValueError(f"schema reference cycle detected: {chain}")
            if len(ref_stack) >= MAX_REF_DEPTH:
                raise ValueError(f"schema reference depth exceeds {MAX_REF_DEPTH}")
            dependencies.add(resolved_path)
            validate_document(resolved_document, resolved_path)
            walk(resolved, resolved_document, resolved_path, ref_stack + (key,))
        for child in _schema_children(rule):
            walk(child, document, document_path, ref_stack)

    schema_path = schema_path.resolve(strict=True)
    validate_document(schema, schema_path)
    walk(schema, schema, schema_path, ())
    return dependencies

def _errors(
    instance: Any,
    rule: dict[str, Any],
    root_schema: dict[str, Any],
    schema_path: Path,
    at: str,
    contract_root: Path,
    ref_stack: tuple[str, ...] = (),
) -> list[str]:
    errors: list[str] = []
    if "$ref" in rule:
        resolved, resolved_document, resolved_path, key = _resolve_ref(
            rule["$ref"], root_schema, schema_path, contract_root
        )
        if key in ref_stack:
            return [f"{at}: schema reference cycle detected at {key}"]
        if len(ref_stack) >= MAX_REF_DEPTH:
            return [f"{at}: schema reference depth exceeds {MAX_REF_DEPTH}"]
        errors.extend(
            _errors(
                instance,
                resolved,
                resolved_document,
                resolved_path,
                at,
                contract_root,
                ref_stack + (key,),
            )
        )
        siblings = {
            key_name: value for key_name, value in rule.items() if key_name != "$ref"
        }
        if siblings:
            errors.extend(
                _errors(
                    instance,
                    siblings,
                    root_schema,
                    schema_path,
                    at,
                    contract_root,
                    ref_stack,
                )
            )
        return errors
    expected = rule.get("type")
    if expected is not None:
        choices = [expected] if isinstance(expected, str) else expected
        if not isinstance(choices, list) or not all(
            isinstance(item, str) for item in choices
        ):
            return [f"{at}: schema type declaration is invalid"]
        if not any(_is_type(instance, item) for item in choices):
            return [f"{at}: expected {' or '.join(choices)}"]
    if "const" in rule and instance != rule["const"]:
        errors.append(f"{at}: value does not equal required constant")
    if "enum" in rule and instance not in rule["enum"]:
        errors.append(f"{at}: value is outside the allowed enumeration")
    if isinstance(instance, dict):
        required = rule.get("required", ())
        for key in required:
            if key not in instance:
                errors.append(f"{at}: missing required property {key}")
        properties = rule.get("properties", {})
        if not isinstance(properties, dict):
            errors.append(f"{at}: schema properties must be an object")
            properties = {}
        for key, value in instance.items():
            child = properties.get(key)
            if isinstance(child, dict):
                errors.extend(
                    _errors(
                        value,
                        child,
                        root_schema,
                        schema_path,
                        f"{at}/{key}",
                        contract_root,
                        ref_stack,
                    )
                )
            elif rule.get("additionalProperties") is False:
                errors.append(f"{at}: unexpected property {key}")
            elif isinstance(rule.get("additionalProperties"), dict):
                errors.extend(
                    _errors(
                        value,
                        rule["additionalProperties"],
                        root_schema,
                        schema_path,
                        f"{at}/{key}",
                        contract_root,
                        ref_stack,
                    )
                )
    if isinstance(instance, list):
        if len(instance) < int(rule.get("minItems", 0)):
            errors.append(f"{at}: too few items")
        if "maxItems" in rule and len(instance) > int(rule["maxItems"]):
            errors.append(f"{at}: too many items")
        if rule.get("uniqueItems") is True:
            encoded = [
                json.dumps(value, sort_keys=True, separators=(",", ":"))
                for value in instance
            ]
            if len(encoded) != len(set(encoded)):
                errors.append(f"{at}: items are not unique")
        if isinstance(rule.get("items"), dict):
            for index, value in enumerate(instance):
                errors.extend(
                    _errors(
                        value,
                        rule["items"],
                        root_schema,
                        schema_path,
                        f"{at}/{index}",
                        contract_root,
                        ref_stack,
                    )
                )
    if isinstance(instance, str):
        if len(instance) < int(rule.get("minLength", 0)):
            errors.append(f"{at}: string is too short")
        if "pattern" in rule and re.search(str(rule["pattern"]), instance) is None:
            errors.append(f"{at}: string does not match required pattern")
        if "format" in rule:
            declared_format = rule.get("format")
            valid = {
                "date-time": _valid_datetime,
                "date": _valid_date,
                "uri": _valid_uri,
            }.get(declared_format)
            if valid is None:
                errors.append(f"{at}: unsupported format {declared_format}")
            elif not valid(instance):
                errors.append(f"{at}: invalid {declared_format}")
    if isinstance(instance, float) and not math.isfinite(instance):
        errors.append(f"{at}: non-finite numbers are not valid JSON numbers")
    elif _finite_number(instance):
        if "minimum" in rule and instance < rule["minimum"]:
            errors.append(f"{at}: value is below minimum")
        if "maximum" in rule and instance > rule["maximum"]:
            errors.append(f"{at}: value is above maximum")
        if "multipleOf" in rule:
            try:
                if Decimal(str(instance)) % Decimal(str(rule["multipleOf"])) != 0:
                    errors.append(f"{at}: value is not a required multiple")
            except (InvalidOperation, ZeroDivisionError):
                errors.append(f"{at}: invalid multipleOf schema constraint")
    for child in rule.get("allOf", ()):
        errors.extend(
            _errors(
                instance, child, root_schema, schema_path, at, contract_root, ref_stack
            )
        )
    if "anyOf" in rule and not any(
        not _errors(
            instance, child, root_schema, schema_path, at, contract_root, ref_stack
        )
        for child in rule["anyOf"]
    ):
        errors.append(f"{at}: no anyOf branch matched")
    if "not" in rule and not _errors(
        instance, rule["not"], root_schema, schema_path, at, contract_root, ref_stack
    ):
        errors.append(f"{at}: prohibited schema matched")
    if (
        "if" in rule
        and not _errors(
            instance, rule["if"], root_schema, schema_path, at, contract_root, ref_stack
        )
        and "then" in rule
    ):
        errors.extend(
            _errors(
                instance,
                rule["then"],
                root_schema,
                schema_path,
                at,
                contract_root,
                ref_stack,
            )
        )
    return errors

def _is_type(value: Any, expected: str) -> bool:
    return {
        "object": isinstance(value, dict),
        "array": isinstance(value, list),
        "string": isinstance(value, str),
        "boolean": isinstance(value, bool),
        "integer": isinstance(value, int) and not isinstance(value, bool),
        "number": _finite_number(value),
        "null": value is None,
    }.get(expected, False)

def _minimal(
    rule: dict[str, Any],
    root_schema: dict[str, Any],
    schema_path: Path,
    contract_root: Path,
    ref_stack: tuple[str, ...] = (),
) -> Any:
    if "$ref" in rule:
        resolved, resolved_document, resolved_path, key = _resolve_ref(
            rule["$ref"], root_schema, schema_path, contract_root
        )
        if key in ref_stack:
            raise ValueError(f"schema reference cycle detected at {key}")
        if len(ref_stack) >= MAX_REF_DEPTH:
            raise ValueError(f"schema reference depth exceeds {MAX_REF_DEPTH}")
        candidate = _minimal(
            resolved,
            resolved_document,
            resolved_path,
            contract_root,
            ref_stack + (key,),
        )
        siblings = {
            key_name: value for key_name, value in rule.items() if key_name != "$ref"
        }
        if siblings and _errors(
            candidate, siblings, root_schema, schema_path, "$", contract_root, ref_stack
        ):
            sibling_candidate = _minimal(
                siblings, root_schema, schema_path, contract_root, ref_stack
            )
            if not _errors(
                sibling_candidate,
                resolved,
                resolved_document,
                resolved_path,
                "$",
                contract_root,
                ref_stack + (key,),
            ):
                candidate = sibling_candidate
        return candidate
    if "const" in rule:
        return rule["const"]
    if "enum" in rule and rule["enum"]:
        return rule["enum"][0]
    if "default" in rule:
        return rule["default"]
    if "anyOf" in rule:
        return _minimal(
            rule["anyOf"][0], root_schema, schema_path, contract_root, ref_stack
        )
    declared = rule.get("type")
    choices = [declared] if isinstance(declared, str) else list(declared or ())
    selected = next(
        (item for item in choices if item != "null"),
        choices[0] if choices else "object",
    )
    if selected == "object":
        value: dict[str, Any] = {}
        properties = rule.get("properties", {})
        for key in rule.get("required", ()):
            value[key] = _minimal(
                properties.get(key, {}),
                root_schema,
                schema_path,
                contract_root,
                ref_stack,
            )
        for child in rule.get("allOf", ()):
            if "if" in child:
                if (
                    not _errors(
                        value,
                        child["if"],
                        root_schema,
                        schema_path,
                        "$",
                        contract_root,
                        ref_stack,
                    )
                    and "then" in child
                ):
                    then = child["then"]
                    for key in then.get("required", ()):
                        value[key] = _minimal(
                            properties.get(key, {}),
                            root_schema,
                            schema_path,
                            contract_root,
                            ref_stack,
                        )
                continue
            addition = _minimal(
                child, root_schema, schema_path, contract_root, ref_stack
            )
            if isinstance(addition, dict):
                value.update(addition)
        if (
            "if" in rule
            and not _errors(
                value,
                rule["if"],
                root_schema,
                schema_path,
                "$",
                contract_root,
                ref_stack,
            )
            and "then" in rule
        ):
            addition = _minimal(
                rule["then"], root_schema, schema_path, contract_root, ref_stack
            )
            if isinstance(addition, dict):
                value.update(addition)
        return value
    if selected == "array":
        count = int(rule.get("minItems", 0))
        item_rule = rule.get("items", {})
        enum_values = item_rule.get("enum", ()) if isinstance(item_rule, dict) else ()
        if (
            rule.get("uniqueItems") is True
            and isinstance(enum_values, list)
            and count <= len(enum_values)
        ):
            return enum_values[:count]
        return [
            _minimal(
                item_rule,
                root_schema,
                schema_path,
                contract_root,
                ref_stack,
            )
            for _ in range(count)
        ]
    if selected == "string":
        if rule.get("format") == "date-time":
            return "2026-08-02T00:00:00Z"
        if rule.get("format") == "date":
            return "2026-08-02"
        if rule.get("format") == "uri":
            return "urn:example:value"
        result = (
            _pattern_example(str(rule["pattern"])) if "pattern" in rule else "value"
        )
        minimum = int(rule.get("minLength", 0))
        return (
            result if len(result) >= minimum else result + "x" * (minimum - len(result))
        )
    if selected == "integer":
        value = int(rule.get("minimum", 0))
        multiple = int(rule.get("multipleOf", 1))
        return ((value + multiple - 1) // multiple) * multiple
    if selected == "number":
        return float(rule.get("minimum", 0))
    if selected == "boolean":
        return False
    return None

def _resolve_ref(
    ref: str,
    schema: dict[str, Any],
    schema_path: Path,
    contract_root: Path,
) -> tuple[dict[str, Any], dict[str, Any], Path, str]:
    if not isinstance(ref, str) or not ref:
        raise ValueError(
            f"schema reference must be a non-empty string in {schema_path}"
        )
    parsed = urlsplit(ref)
    if parsed.scheme or parsed.netloc or parsed.query:
        raise ValueError(f"URI schema references are not allowed: {ref!r}")

    ref_path, marker, fragment = ref.partition("#")
    if not ref_path:
        target_path = schema_path.resolve(strict=True)
        target_document = schema
    else:
        target_path = _resolve_external_path(ref_path, schema_path, contract_root)
        target_document = _load(target_path)
    target = _resolve_pointer(
        target_document, fragment if marker else "", ref, schema_path
    )
    key = f"{target_path.as_posix()}#{fragment if marker else ''}"
    return target, target_document, target_path, key

def build_minimal_instance(
    schema_path: Path, *, contract_root: Path | None = None
) -> Any:
    """Build a deterministic contract smoke fixture; validation remains authoritative."""
    schema_path = schema_path.resolve(strict=True)
    resolved_contract_root = _contract_root_for(schema_path, contract_root)
    schema = _load(schema_path)
    _admit_schema(schema, schema_path, resolved_contract_root)
    return _minimal(schema, schema, schema_path, resolved_contract_root)

def contract_digest(schema_path: Path, *, contract_root: Path | None = None) -> str:
    """Digest a contract and every schema document reached through its references."""
    schema_path = schema_path.resolve(strict=True)
    resolved_contract_root = _contract_root_for(schema_path, contract_root)
    schema = _load(schema_path)
    dependencies = _admit_schema(schema, schema_path, resolved_contract_root)
    records = []
    for dependency in sorted(dependencies, key=lambda item: item.as_posix()):
        records.append(
            {
                "path": dependency.relative_to(resolved_contract_root).as_posix(),
                "sha256": hashlib.sha256(dependency.read_bytes()).hexdigest(),
            }
        )
    encoded = json.dumps(records, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()

def validate_contract_corpus(root: Path) -> dict[str, Any]:
    contract_root = root / "contracts"
    ownership = _load(root / "registry" / "contract_ownership.json")
    ownership_records = ownership.get("records", ())
    ownership_by_path = {
        str(item.get("path")): item
        for item in ownership_records
        if isinstance(item, dict)
    }
    paths = sorted(
        path.relative_to(root).as_posix() for path in contract_root.rglob("*.json")
    )
    errors: list[str] = []
    owned: dict[str, str] = {}
    contract_digests: dict[str, str] = {}
    for relative in paths:
        path = root / relative
        schema: dict[str, Any] = {}
        try:
            schema = _load(path)
            errors.extend(
                f"{relative}: {item}" for item in _schema_structure_errors(schema)
            )
            if schema.get("$schema") != SUPPORTED_DIALECT:
                errors.append(f"{relative}: missing Draft 2020-12 declaration")
            expected_id = f"urn:engineering-loop-bootstrap:contract:{relative.removeprefix('contracts/').removesuffix('.schema.json').replace('/', ':')}"
            if schema.get("$id") != expected_id:
                errors.append(f"{relative}: unstable or missing contract id")
            _admit_schema(schema, path, contract_root.resolve(strict=True))
            contract_digests[relative] = contract_digest(
                path, contract_root=contract_root
            )
            example = build_minimal_instance(path, contract_root=contract_root)
            example_errors = _errors(
                example, schema, schema, path, "$", contract_root.resolve(strict=True)
            )
            errors.extend(
                f"{relative}: generated valid fixture failed: {item}"
                for item in example_errors
            )
            if schema.get("required") and not _errors(
                {}, schema, schema, path, "$", contract_root.resolve(strict=True)
            ):
                errors.append(
                    f"{relative}: empty-object negative fixture unexpectedly passed"
                )
        except (OSError, ValueError, KeyError, json.JSONDecodeError) as error:
            errors.append(f"{relative}: {error}")
        ownership_record = ownership_by_path.get(relative)
        if ownership_record is None:
            errors.append(f"{relative}: missing explicit ownership record")
        else:
            owner = str(ownership_record.get("owner", ""))
            if not owner or not declared_file_available(root, owner):
                errors.append(f"{relative}: missing runtime owner {owner}")
            owned[relative] = owner
            if ownership_record.get("packaged") is not True:
                errors.append(f"{relative}: shipped contract is not marked packaged")
            if not ownership_record.get("enforcement"):
                errors.append(f"{relative}: missing enforcement classification")
            if ownership_record.get("contract_id") != schema.get("$id"):
                errors.append(f"{relative}: ownership contract id mismatch")
            if ownership_record.get("contract_version") != "1.0.0":
                errors.append(
                    f"{relative}: ownership contract version is missing or invalid"
                )
            for producer in ownership_record.get("producers", ()):
                if not declared_file_available(root, str(producer)):
                    errors.append(f"{relative}: missing producer {producer}")
            for test in ownership_record.get("tests", ()):
                if not declared_file_available(root, str(test)):
                    errors.append(f"{relative}: missing ownership test {test}")
    extras = sorted(set(ownership_by_path) - set(paths))
    errors.extend(
        f"ownership record references missing contract: {relative}"
        for relative in extras
    )
    if ownership.get("contract_count") != len(paths):
        errors.append("contract ownership count does not match corpus")
    enforcement_counts: dict[str, int] = {}
    for record in ownership_records:
        state = str(record.get("enforcement", "missing"))
        enforcement_counts[state] = enforcement_counts.get(state, 0) + 1
    corpus_bytes = json.dumps(
        contract_digests, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")
    return {
        "valid": not errors,
        "contract_count": len(paths),
        "owned_count": len(owned),
        "enforcement_counts": enforcement_counts,
        "contract_corpus_digest": hashlib.sha256(corpus_bytes).hexdigest(),
        "contract_digests": contract_digests,
        "errors": errors,
    }

def validate_instance(
    instance: Any, schema_path: Path, *, contract_root: Path | None = None
) -> None:
    schema_path = schema_path.resolve(strict=True)
    resolved_contract_root = _contract_root_for(schema_path, contract_root)
    schema = _load(schema_path)
    _admit_schema(schema, schema_path, resolved_contract_root)
    errors = _errors(instance, schema, schema, schema_path, "$", resolved_contract_root)
    if errors:
        raise ContractValidationError("; ".join(errors))

def _acceptance_command_errors(root: Path, identifier: str, command: str) -> list[str]:
    try:
        tokens = shlex.split(command, posix=False)
    except ValueError as error:
        return [f"{identifier}: malformed acceptance command: {error}"]
    if not tokens:
        return [f"{identifier}: empty acceptance command"]
    if tokens[0] == "engineering-bootstrap":
        if tuple(tokens[1:]) not in SUPPORTED_CLI_ACCEPTANCE_FORMS:
            return [
                f"{identifier}: acceptance command is not supported by the CLI: {command}"
            ]
        return []
    if tokens[:3] == ["python", "-m", "runtime.cli"]:
        if tuple(tokens[3:]) not in SUPPORTED_CLI_ACCEPTANCE_FORMS:
            return [
                f"{identifier}: runtime CLI acceptance command is unsupported: {command}"
            ]
        return []
    if tokens[:3] == ["python", "-m", "pytest"]:
        errors = []
        for token in tokens[3:]:
            candidate = token.split("::", 1)[0]
            if candidate.startswith("tests/") or candidate.startswith("tests\\"):
                if not (root / candidate).exists():
                    errors.append(
                        f"{identifier}: acceptance test target does not exist: {candidate}"
                    )
        return errors
    if tokens[0] == "python" and len(tokens) > 1 and tokens[1].endswith(".py"):
        return (
            []
            if (root / tokens[1]).is_file()
            else [f"{identifier}: acceptance script does not exist: {tokens[1]}"]
        )
    return [f"{identifier}: unsupported acceptance command form: {command}"]

def validate_corrective_ledger(
    root: Path,
    *,
    require_blocking_passed: bool = False,
    allow_finalizer_in_progress: bool = False,
) -> dict[str, Any]:
    root = root.resolve()
    errors: list[str] = []
    try:
        ledger = load_corrective_ledger(root)
    except (OSError, ValueError, json.JSONDecodeError) as error:
        return {
            "valid": False,
            "errors": [f"cannot load corrective ledger: {error}"],
            "cards": 0,
        }
    cards = ledger.get("cards")
    if not isinstance(cards, list):
        return {"valid": False, "errors": ["cards must be a list"], "cards": 0}
    identifiers = [str(card.get("id", "")) for card in cards if isinstance(card, dict)]
    if len(identifiers) != len(set(identifiers)):
        errors.append("corrective ledger contains duplicate card IDs")
    source_ids = set(identifiers) & SOURCE_CARD_IDS
    child_ids = set(identifiers) - SOURCE_CARD_IDS
    if source_ids != SOURCE_CARD_IDS:
        errors.append(
            f"source-card denominator mismatch: missing={sorted(SOURCE_CARD_IDS - source_ids)} extra={sorted(source_ids - SOURCE_CARD_IDS)}"
        )
    if ledger.get("source_card_count") != len(SOURCE_CARD_IDS):
        errors.append("source_card_count is not authoritative")
    if ledger.get("card_count") != len(cards):
        errors.append("card_count does not match cards")
    known = set(identifiers)
    for card in cards:
        if not isinstance(card, dict):
            errors.append("card record must be an object")
            continue
        identifier = str(card.get("id", ""))
        status = card.get("status")
        priority = card.get("priority")
        if status not in ALLOWED_STATUSES:
            errors.append(f"{identifier}: invalid status {status!r}")
        if priority not in {"P0", "P1", "P2", "P3"}:
            errors.append(f"{identifier}: invalid priority {priority!r}")
        dependencies = card.get("dependencies")
        if not isinstance(dependencies, list) or any(
            dep not in known for dep in dependencies
        ):
            errors.append(f"{identifier}: unknown or malformed dependency")
        if not isinstance(card.get("owning_paths"), list) or not card["owning_paths"]:
            errors.append(f"{identifier}: owning_paths must be nonempty")
        else:
            for relative in card["owning_paths"]:
                owner_path = (root / str(relative)).resolve()
                if root not in owner_path.parents and owner_path != root:
                    errors.append(
                        f"{identifier}: owning path escapes product root: {relative}"
                    )
                elif not owner_path.exists() and not (
                    str(relative).startswith("evidence/")
                    and status in {"open", "in_progress"}
                ):
                    errors.append(
                        f"{identifier}: owning path does not exist: {relative}"
                    )
        commands = card.get("acceptance_commands")
        if not isinstance(commands, list) or not commands:
            errors.append(f"{identifier}: acceptance_commands must be nonempty")
        else:
            for command in commands:
                if not isinstance(command, str):
                    errors.append(f"{identifier}: acceptance command must be text")
                else:
                    errors.extend(_acceptance_command_errors(root, identifier, command))
        receipts = card.get("receipts")
        if not isinstance(receipts, list):
            errors.append(f"{identifier}: receipts must be a list")
            receipts = []
        if status in {"passed", "rejected_with_evidence"} and not receipts:
            errors.append(f"{identifier}: closed status requires receipts")
        for relative in receipts:
            path = (root / str(relative)).resolve()
            if root not in path.parents and path != root:
                errors.append(f"{identifier}: receipt escapes product root: {relative}")
            elif not path.is_file():
                errors.append(f"{identifier}: missing receipt: {relative}")
        if status == "deferred_with_owner":
            if (
                not card.get("owner")
                or not card.get("risk")
                or not card.get("rationale")
            ):
                errors.append(
                    f"{identifier}: deferral requires owner, risk, and rationale"
                )
        parent = card.get("parent")
        if identifier in child_ids and (not parent or parent not in known):
            errors.append(f"{identifier}: child finding requires a known parent")
        if require_blocking_passed and priority in BLOCKING_PRIORITIES:
            permitted = {"passed"}
            if allow_finalizer_in_progress and identifier in {
                "REL-010-E",
                "REL-011-FULL-REPAIR",
            }:
                permitted.add("in_progress")
            if status not in permitted:
                errors.append(f"{identifier}: blocking card is {status}, not passed")
    return {
        "schema_version": "1.0",
        "valid": not errors,
        "release": ledger.get("release"),
        "cards": len(cards),
        "source_cards": len(source_ids),
        "children": len(child_ids),
        "blocking_open": sum(
            1
            for card in cards
            if card.get("priority") in BLOCKING_PRIORITIES
            and card.get("status") != "passed"
        ),
        "errors": errors,
    }

"""Validate executed branch coverage against safety-class thresholds."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path
from typing import Any


def validate_coverage_evidence(root: Path, coverage_json: Path) -> dict[str, Any]:
    root = root.resolve()
    coverage_json = coverage_json.resolve()
    policy = json.loads(
        (root / "policies/coverage-assurance.json").read_text(encoding="utf-8")
    )
    coverage = json.loads(coverage_json.read_text(encoding="utf-8"))
    errors: list[str] = []
    meta = coverage.get("meta", {})
    if (
        policy.get("branch_required") is True
        and meta.get("branch_coverage") is not True
    ):
        errors.append("coverage evidence does not include branch coverage")
    if policy.get("dynamic_context_required") is True and not meta.get("show_contexts"):
        errors.append("coverage evidence does not include dynamic test contexts")
    exemptions = policy.get("exemptions", [])
    if not isinstance(exemptions, list):
        errors.append("coverage exemptions must be a list")
        exemptions = []
    for exemption in exemptions:
        if (
            not isinstance(exemption, dict)
            or not all(
                str(exemption.get(field, "")).strip()
                for field in ("module", "owner", "reason")
            )
            or not exemption.get("branches")
        ):
            errors.append(
                "coverage exemption requires module, owner, reason, and branches"
            )
    files = {
        str(path).replace("\\", "/"): value
        for path, value in coverage.get("files", {}).items()
    }
    classes: dict[str, object] = {}
    for class_name, rule in policy.get("classes", {}).items():
        modules = rule.get("modules", [])
        minimum = float(rule.get("minimum_branch_percent", 0))
        results = []
        class_total = 0
        class_missing = 0
        for module in modules:
            candidates = [
                value
                for path, value in files.items()
                if path == module or path.endswith("/" + module)
            ]
            if len(candidates) != 1:
                errors.append(f"{class_name}: executed coverage missing for {module}")
                continue
            summary = candidates[0].get("summary", {})
            contexts = candidates[0].get("contexts", {})
            if policy.get("dynamic_context_required") is True and not isinstance(
                contexts, dict
            ):
                errors.append(
                    f"{class_name}: dynamic test contexts missing for {module}"
                )
            elif policy.get("dynamic_context_required") is True and not any(
                isinstance(names, list) and any(str(name).strip() for name in names)
                for names in contexts.values()
            ):
                errors.append(
                    f"{class_name}: dynamic test contexts are empty for {module}"
                )
            total = int(summary.get("num_branches", 0))
            missing = int(summary.get("missing_branches", 0))
            percent = (
                100.0 if total == 0 else round((total - missing) * 100.0 / total, 2)
            )
            results.append(
                {
                    "module": module,
                    "branches": total,
                    "missing": missing,
                    "branch_percent": percent,
                }
            )
            class_total += total
            class_missing += missing
        class_percent = (
            100.0
            if class_total == 0
            else round((class_total - class_missing) * 100.0 / class_total, 2)
        )
        class_valid = len(results) == len(modules) and class_percent >= minimum
        if len(results) == len(modules) and class_percent < minimum:
            errors.append(
                f"{class_name}: aggregate branch coverage {class_percent}% is below {minimum}%"
            )
        classes[class_name] = {
            "minimum_branch_percent": minimum,
            "branch_percent": class_percent,
            "branches": class_total,
            "missing": class_missing,
            "modules": results,
            "valid": class_valid,
        }
    return {
        "schema_version": "1.0",
        "valid": not errors,
        "coverage_sha256": hashlib.sha256(coverage_json.read_bytes()).hexdigest(),
        "policy_sha256": hashlib.sha256(
            (root / "policies/coverage-assurance.json").read_bytes()
        ).hexdigest(),
        "classes": classes,
        "exemption_count": len(exemptions),
        "errors": errors,
    }

def validate_coverage_evidence(root: Path, coverage_json: Path) -> dict[str, Any]:
    root = root.resolve()
    coverage_json = coverage_json.resolve()
    policy = json.loads(
        (root / "policies/coverage-assurance.json").read_text(encoding="utf-8")
    )
    coverage = json.loads(coverage_json.read_text(encoding="utf-8"))
    errors: list[str] = []
    meta = coverage.get("meta", {})
    if (
        policy.get("branch_required") is True
        and meta.get("branch_coverage") is not True
    ):
        errors.append("coverage evidence does not include branch coverage")
    if policy.get("dynamic_context_required") is True and not meta.get("show_contexts"):
        errors.append("coverage evidence does not include dynamic test contexts")
    exemptions = policy.get("exemptions", [])
    if not isinstance(exemptions, list):
        errors.append("coverage exemptions must be a list")
        exemptions = []
    for exemption in exemptions:
        if (
            not isinstance(exemption, dict)
            or not all(
                str(exemption.get(field, "")).strip()
                for field in ("module", "owner", "reason")
            )
            or not exemption.get("branches")
        ):
            errors.append(
                "coverage exemption requires module, owner, reason, and branches"
            )
    files = {
        str(path).replace("\\", "/"): value
        for path, value in coverage.get("files", {}).items()
    }
    classes: dict[str, object] = {}
    for class_name, rule in policy.get("classes", {}).items():
        modules = rule.get("modules", [])
        minimum = float(rule.get("minimum_branch_percent", 0))
        results = []
        class_total = 0
        class_missing = 0
        for module in modules:
            candidates = [
                value
                for path, value in files.items()
                if path == module or path.endswith("/" + module)
            ]
            if len(candidates) != 1:
                errors.append(f"{class_name}: executed coverage missing for {module}")
                continue
            summary = candidates[0].get("summary", {})
            contexts = candidates[0].get("contexts", {})
            if policy.get("dynamic_context_required") is True and not isinstance(
                contexts, dict
            ):
                errors.append(
                    f"{class_name}: dynamic test contexts missing for {module}"
                )
            elif policy.get("dynamic_context_required") is True and not any(
                isinstance(names, list) and any(str(name).strip() for name in names)
                for names in contexts.values()
            ):
                errors.append(
                    f"{class_name}: dynamic test contexts are empty for {module}"
                )
            total = int(summary.get("num_branches", 0))
            missing = int(summary.get("missing_branches", 0))
            percent = (
                100.0 if total == 0 else round((total - missing) * 100.0 / total, 2)
            )
            results.append(
                {
                    "module": module,
                    "branches": total,
                    "missing": missing,
                    "branch_percent": percent,
                }
            )
            class_total += total
            class_missing += missing
        class_percent = (
            100.0
            if class_total == 0
            else round((class_total - class_missing) * 100.0 / class_total, 2)
        )
        class_valid = len(results) == len(modules) and class_percent >= minimum
        if len(results) == len(modules) and class_percent < minimum:
            errors.append(
                f"{class_name}: aggregate branch coverage {class_percent}% is below {minimum}%"
            )
        classes[class_name] = {
            "minimum_branch_percent": minimum,
            "branch_percent": class_percent,
            "branches": class_total,
            "missing": class_missing,
            "modules": results,
            "valid": class_valid,
        }
    return {
        "schema_version": "1.0",
        "valid": not errors,
        "coverage_sha256": hashlib.sha256(coverage_json.read_bytes()).hexdigest(),
        "policy_sha256": hashlib.sha256(
            (root / "policies/coverage-assurance.json").read_bytes()
        ).hexdigest(),
        "classes": classes,
        "exemption_count": len(exemptions),
        "errors": errors,
    }

