def build_dependency_graph(
    root: Path,
    nodes: Iterable[Mapping[str, object]],
    edges: Iterable[Mapping[str, object]],
    *,
    authority: Mapping[str, object] | None = None,
) -> dict[str, object]:
    """Build a validated graph whose edges point dependency -> consumer."""
    root = root.resolve()
    policy = dict(authority) if authority is not None else load_dependency_authority(root)
    authority_report = validate_dependency_authority(root, policy)
    if not authority_report["valid"]:
        raise ValueError("invalid dependency authority: " + "; ".join(authority_report["errors"]))
    errors: list[str] = []
    normalized_nodes: dict[str, dict[str, str]] = {}
    for item in nodes:
        node_id = str(item.get("node_id") or "")
        kind = str(item.get("kind") or "")
        revision = str(item.get("revision") or "")
        if not node_id or node_id in normalized_nodes:
            errors.append(f"node ID must be non-empty and unique: {node_id!r}")
            continue
        if kind not in REQUIRED_KINDS:
            errors.append(f"{node_id}: unknown dependency kind {kind!r}")
        if not revision:
            errors.append(f"{node_id}: revision is required")
        normalized_nodes[node_id] = {"node_id": node_id, "kind": kind, "revision": revision}
    normalized_edges: set[tuple[str, str]] = set()
    for item in edges:
        dependency = str(item.get("dependency") or "")
        consumer = str(item.get("consumer") or "")
        if dependency not in normalized_nodes or consumer not in normalized_nodes:
            errors.append(f"unknown dependency edge: {dependency!r} -> {consumer!r}")
            continue
        normalized_edges.add((dependency, consumer))
    cycles = _cycles(set(normalized_nodes), normalized_edges)
    allowed = {
        tuple(sorted(map(str, component)))
        for component in policy.get("allowed_cycle_components", [])
    }
    undeclared = [cycle for cycle in cycles if tuple(cycle) not in allowed]
    if undeclared:
        errors.append(f"undeclared dependency cycles: {undeclared}")
    if errors:
        raise ValueError("; ".join(errors))
    return {
        "schema_version": GRAPH_SCHEMA,
        "nodes": [normalized_nodes[key] for key in sorted(normalized_nodes)],
        "edges": [
            {"dependency": dependency, "consumer": consumer}
            for dependency, consumer in sorted(normalized_edges)
        ],
        "cycle_components": cycles,
    }

def compute_invalidation_cone(
    graph: Mapping[str, object],
    current_revisions: Mapping[str, object],
    *,
    authority: Mapping[str, object],
) -> dict[str, object]:
    """Propagate revision drift while retaining all historical node records."""
    nodes = {
        str(item["node_id"]): item
        for item in graph.get("nodes", [])
        if isinstance(item, Mapping) and item.get("node_id")
    }
    adjacency: dict[str, set[str]] = defaultdict(set)
    for edge in graph.get("edges", []):
        if isinstance(edge, Mapping):
            adjacency[str(edge.get("dependency"))].add(str(edge.get("consumer")))
    unknown = sorted(set(map(str, current_revisions)) - set(nodes))
    if unknown:
        raise ValueError(f"current revisions contain unknown dependency nodes: {unknown}")
    seeds = sorted(
        node_id
        for node_id, revision in current_revisions.items()
        if str(revision) != str(nodes[str(node_id)].get("revision"))
    )
    depths = {node_id: 0 for node_id in seeds}
    queue = deque(seeds)
    while queue:
        node_id = queue.popleft()
        for consumer in sorted(adjacency.get(node_id, ())):
            if consumer not in depths:
                depths[consumer] = depths[node_id] + 1
                queue.append(consumer)
    gates = {
        str(record["kind"]): str(record["rebuild_gate"])
        for record in authority.get("node_kinds", [])
        if isinstance(record, Mapping)
    }
    stale = [
        {
            "node_id": node_id,
            "kind": str(nodes[node_id].get("kind")),
            "recorded_revision": str(nodes[node_id].get("revision")),
            "current_revision": (
                str(current_revisions[node_id]) if node_id in current_revisions else None
            ),
            "depth": depths[node_id],
            "reason": "revision_drift" if depths[node_id] == 0 else "dependency_invalidated",
            "required_rebuild_gate": gates.get(str(nodes[node_id].get("kind"))),
        }
        for node_id in sorted(depths, key=lambda value: (depths[value], value))
    ]
    return {
        "schema_version": "px.invalidation-cone/1.0",
        "valid": True,
        "seed_nodes": seeds,
        "direct_consumers": [item["node_id"] for item in stale if item["depth"] == 1],
        "transitive_consumers": [item["node_id"] for item in stale if item["depth"] > 1],
        "stale_nodes": stale,
        "historical_records_retained": True,
    }

def close_specification_lifecycle(
    artifacts: Sequence[Mapping[str, object]],
) -> dict[str, object]:
    """Verify stage continuity, task coverage, evidence, and acceptance."""
    by_id: dict[str, Mapping[str, object]] = {}
    stage_records = {stage: [] for stage in SPECIFICATION_STAGES}
    errors: list[str] = []
    for artifact in artifacts:
        artifact_id = str(artifact.get("id", "")).strip()
        stage = str(artifact.get("stage", "")).strip()
        if not artifact_id or artifact_id in by_id:
            raise ValueError("artifact IDs must be non-empty and unique")
        if stage not in stage_records:
            raise ValueError(f"unsupported specification stage: {stage}")
        by_id[artifact_id] = artifact
        stage_records[stage].append(artifact)

    missing_stages = [stage for stage, records in stage_records.items() if not records]
    if missing_stages:
        errors.append(f"missing stages: {missing_stages}")
    stage_index = {stage: index for index, stage in enumerate(SPECIFICATION_STAGES)}
    referenced: set[str] = set()
    for artifact_id, artifact in by_id.items():
        current_stage = str(artifact["stage"])
        dependencies = tuple(map(str, artifact.get("depends_on", ())))
        if current_stage != "principles" and not dependencies:
            errors.append(f"{artifact_id}: non-principle artifact is orphaned")
        for dependency in dependencies:
            referenced.add(dependency)
            target = by_id.get(dependency)
            if target is None:
                errors.append(f"{artifact_id}: unresolved dependency {dependency}")
            elif stage_index[str(target["stage"])] >= stage_index[current_stage]:
                errors.append(f"{artifact_id}: dependency is not from an earlier stage")
        if current_stage == "implementation_evidence" and not artifact.get(
            "evidence_sha256"
        ):
            errors.append(f"{artifact_id}: implementation evidence hash missing")
        if current_stage == "acceptance" and artifact.get("passed") is not True:
            errors.append(f"{artifact_id}: acceptance did not pass")
    task_ids = {
        identifier
        for identifier, artifact in by_id.items()
        if artifact["stage"] == "tasks"
    }
    evidenced_tasks = {
        dependency
        for artifact in stage_records["implementation_evidence"]
        for dependency in map(str, artifact.get("depends_on", ()))
    }
    orphan_tasks = sorted(task_ids - evidenced_tasks)
    if orphan_tasks:
        errors.append(f"tasks without implementation evidence: {orphan_tasks}")
    result = {
        "valid": not errors,
        "closed": not errors,
        "stage_counts": {
            stage: len(records) for stage, records in stage_records.items()
        },
        "missing_stages": missing_stages,
        "orphan_tasks": orphan_tasks,
        "errors": errors,
        "artifact_count": len(artifacts),
        "authority_granted": False,
    }
    result["closure_sha256"] = _stable(result)
    return result

def transition_durable_goal(
    state: Mapping[str, object],
    event: str,
    *,
    project_id: str,
    session_id: str,
    evidence_ids: Sequence[str] = (),
    acceptance_results: Mapping[str, bool] | None = None,
    blocker: str | None = None,
    continuation_cost: int = 0,
) -> dict[str, object]:
    """Apply one deterministic goal transition with strict completion semantics."""
    current = str(state.get("status", "planned"))
    if current not in GOAL_STATES:
        raise ValueError("unknown goal state")
    if state.get("project_id") not in {None, project_id}:
        raise ValueError("goal transition crosses project boundary")
    if continuation_cost < 0:
        raise ValueError("continuation cost cannot be negative")
    budget = int(state.get("continuation_budget", 0))
    remaining = budget - continuation_cost
    errors: list[str] = []
    target = current
    history = [
        dict(item) for item in state.get("history", ()) if isinstance(item, Mapping)
    ]
    acceptance = dict(acceptance_results or {})
    evidence = tuple(sorted(set(map(str, evidence_ids))))

    if event == "start":
        if current not in {"planned", "paused", "blocked"}:
            errors.append("goal cannot start from current state")
        elif current == "paused" and state.get("paused_session_id") not in {
            None,
            session_id,
        }:
            errors.append("paused goal belongs to another session")
        else:
            target = "in_progress"
    elif event == "pause":
        if current != "in_progress":
            errors.append("only an in-progress goal may pause")
        else:
            target = "paused"
    elif event == "block":
        blocker_text = str(blocker or "").strip()
        repeated = 1
        for item in reversed(history):
            if item.get("event") == "block" and item.get("blocker") == blocker_text:
                repeated += 1
            else:
                break
        if not blocker_text:
            errors.append("blocked transition requires a blocker")
        elif repeated < 3:
            errors.append(
                "blocked semantics require three consecutive matching observations"
            )
        else:
            target = "blocked"
    elif event == "complete":
        if not acceptance or not all(acceptance.values()):
            errors.append("all acceptance criteria must pass")
        if not evidence:
            errors.append("completion evidence is required")
        if not errors:
            target = "complete"
    elif event == "continue":
        if current != "in_progress":
            errors.append("only an in-progress goal may continue")
        if continuation_cost < 1:
            errors.append("continuation must spend a positive bounded unit")
        if remaining < 0:
            errors.append("continuation budget exhausted")
    else:
        raise ValueError("unsupported goal event")

    applied = not errors
    if applied:
        history.append(
            {
                "event": event,
                "from": current,
                "to": target,
                "session_id": session_id,
                "blocker": blocker,
                "evidence_ids": list(evidence),
                "acceptance": acceptance,
            }
        )
    result = {
        "schema_version": "1.0",
        "goal_id": str(state.get("goal_id", "")),
        "project_id": project_id,
        "status": target if applied else current,
        "continuation_budget": remaining if applied else budget,
        "paused_session_id": session_id
        if applied and event == "pause"
        else state.get("paused_session_id"),
        "history": history,
        "event_applied": applied,
        "errors": errors,
        "authority_granted": False,
    }
    result["state_sha256"] = _stable(result)
    return result

def validate_effect_grant(
    grant: dict[str, Any],
    *,
    signature_path: Path,
    trust_policy_path: Path,
    capability_id: str,
    requested_effects: Iterable[str],
    adapter: str,
    environment: str,
    project_id: str,
    session_id: str,
    writable_targets: Iterable[Path] = (),
    network_hosts: Iterable[str] = (),
    secret_refs: Iterable[str] = (),
    destructive: bool = False,
    now: datetime | None = None,
    idempotency_key: str | None = None,
) -> dict[str, Any]:
    errors: list[str] = []
    if set(grant) != REQUIRED:
        errors.append("effect grant fields are not exact")
    if grant.get("schema_version") != "1.0" or grant.get("content_sha256") != _digest(
        grant
    ):
        errors.append("effect grant content digest mismatch")
    try:
        policy = json.loads(trust_policy_path.read_text(encoding="utf-8"))
        signature = grant["signature"]
        trusted = {
            item["fingerprint"]: item for item in policy.get("trusted_signers", [])
        }
        signer = trusted.get(signature.get("key_fingerprint"))
        if signer is None or signature.get("key_fingerprint") in policy.get(
            "revoked_fingerprints", []
        ):
            errors.append("effect grant signer is not trusted")
        elif (
            signature.get("namespace") != NAMESPACE
            or signature.get("algorithm") != "ssh-ed25519"
            or signature.get("identity") != signer.get("identity")
            or signature.get("publisher") != signer.get("publisher")
        ):
            errors.append("effect grant signer metadata mismatch")
        elif not signature_path.is_file():
            errors.append("effect grant detached signature is missing")
        else:
            with tempfile.TemporaryDirectory() as directory:
                allowed = Path(directory) / "allowed_signers"
                allowed.write_text(
                    f'{signer["identity"]} namespaces="{NAMESPACE}" {signer["public_key"]}\n',
                    encoding="utf-8",
                )
                verification = subprocess.run(
                    [
                        "ssh-keygen",
                        "-Y",
                        "verify",
                        "-f",
                        str(allowed),
                        "-I",
                        signer["identity"],
                        "-n",
                        NAMESPACE,
                        "-s",
                        str(signature_path),
                    ],
                    input=canonical_bytes(grant),
                    capture_output=True,
                    timeout=30,
                    check=False,
                )
                if verification.returncode:
                    errors.append("effect grant signature verification failed")
    except (
        OSError,
        KeyError,
        TypeError,
        ValueError,
        json.JSONDecodeError,
        subprocess.SubprocessError,
    ) as error:
        errors.append(
            f"effect grant trust validation failed: {type(error).__name__}: {error}"
        )
    requested = set(map(str, requested_effects))
    declared = set(map(str, grant.get("declared_effects", ())))
    if grant.get("capability_id") != capability_id or not requested <= declared:
        errors.append("effect grant does not cover capability or requested effects")
    if (
        grant.get("approved_adapter") != adapter
        or grant.get("approved_environment") != environment
    ):
        errors.append("effect grant adapter or environment binding mismatch")
    if grant.get("project_id") != project_id or grant.get("session_id") != session_id:
        errors.append("effect grant project or session binding mismatch")
    try:
        issued = datetime.fromisoformat(str(grant["issued_utc"]))
        expiry = datetime.fromisoformat(str(grant["expires_utc"]))
        current = now or datetime.now(timezone.utc)
        if (
            issued.tzinfo is None
            or expiry.tzinfo is None
            or expiry <= issued
            or current >= expiry
        ):
            errors.append("effect grant is expired or has invalid time bounds")
    except (KeyError, TypeError, ValueError):
        errors.append("effect grant time bounds are invalid")
    if not all(
        str(grant.get(field, "")).strip()
        for field in ("grant_id", "approval_identity", "nonce", "idempotency_key")
    ):
        errors.append("effect grant identity, nonce, or idempotency key is missing")
    if idempotency_key is not None and grant.get("idempotency_key") != idempotency_key:
        errors.append("effect grant idempotency key mismatch")
    roots = [Path(value).resolve() for value in grant.get("writable_roots", ())]
    for target in writable_targets:
        resolved = target.resolve()
        if not any(resolved == root or root in resolved.parents for root in roots):
            errors.append(f"write target is outside effect grant roots: {target}")
    network = grant.get("network_policy", {})
    allowed_hosts = (
        set(map(str, network.get("allow_hosts", ())))
        if isinstance(network, dict)
        else set()
    )
    if network_hosts and (
        not isinstance(network, dict)
        or network.get("mode") != "allowlist"
        or not set(map(str, network_hosts)) <= allowed_hosts
    ):
        errors.append("network effect exceeds grant policy")
    secret_policy = grant.get("secret_access_policy", {})
    if secret_refs and (
        not isinstance(secret_policy, dict)
        or secret_policy.get("mode") != "allowlist"
        or not set(map(str, secret_refs))
        <= set(map(str, secret_policy.get("allow_refs", ())))
    ):
        errors.append("secret access exceeds grant policy")
    destructive_policy = grant.get("destructive_operation_policy", {})
    if destructive and (
        not isinstance(destructive_policy, dict)
        or destructive_policy.get("approved") is not True
        or not destructive_policy.get("approval_id")
    ):
        errors.append("destructive effect lacks explicit approval")
    return {
        "schema_version": "1.0",
        "valid": not errors,
        "grant_id": grant.get("grant_id"),
        "errors": errors,
    }

def _call_name(node: ast.Call) -> str:
    value: ast.AST = node.func
    parts: list[str] = []
    while isinstance(value, ast.Attribute):
        parts.append(value.attr)
        value = value.value
    if isinstance(value, ast.Name):
        parts.append(value.id)
    return ".".join(reversed(parts))

def _popen_communication_timeout(tree: ast.AST, popen: ast.Call) -> str | None:
    """Return the timeout used to reap a Popen handle in the same function."""
    scope = next(
        (
            item
            for item in ast.walk(tree)
            if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef))
            and item.lineno <= popen.lineno <= getattr(item, "end_lineno", item.lineno)
        ),
        tree,
    )
    handle = None
    for item in ast.walk(scope):
        if isinstance(item, (ast.Assign, ast.AnnAssign)) and item.value is popen:
            targets = item.targets if isinstance(item, ast.Assign) else [item.target]
            if len(targets) == 1 and isinstance(targets[0], ast.Name):
                handle = targets[0].id
                break
    if handle is None:
        return None
    for item in ast.walk(scope):
        if not isinstance(item, ast.Call) or not isinstance(item.func, ast.Attribute):
            continue
        if (
            item.func.attr not in {"communicate", "wait"}
            or not isinstance(item.func.value, ast.Name)
            or item.func.value.id != handle
        ):
            continue
        timeout = next(
            (keyword.value for keyword in item.keywords if keyword.arg == "timeout"),
            None,
        )
        if timeout is not None:
            return f"{item.func.attr}(timeout={ast.unparse(timeout)})"
    return None

def validate_effect_surfaces(root: Path) -> dict[str, Any]:
    root = root.resolve()
    actual = discover_effect_surfaces(root)
    registry_path = root / "registry/effect_surface_ownership.json"
    registry = json.loads(registry_path.read_text(encoding="utf-8"))
    errors = []
    if registry.get("records") != actual or registry.get("record_count") != len(actual):
        errors.append("effect-surface ownership registry is stale")
    for record in actual:
        if not (root / record["policy"]).is_file():
            errors.append(f"{record['id']}: missing effect policy")
        if record["effect"] == "process":
            if record["call"] == "os.system" or record["shell"] == "True":
                errors.append(
                    f"{record['path']}:{record['line']}: unsafe shell execution"
                )
            if record["timeout"] is None:
                errors.append(
                    f"{record['path']}:{record['line']}: process call lacks timeout"
                )
        if (
            record["destructive"]
            and record["path"] != RESOURCE_LIFECYCLE_OWNER
            and record["path"] not in RECOVERABLE_RECLAMATION_OWNERS
        ):
            errors.append(
                f"{record['path']}:{record['line']}: hard-delete surface is prohibited"
            )
    counts: dict[str, int] = {}
    for record in actual:
        counts[record["effect"]] = counts.get(record["effect"], 0) + 1
    return {
        "schema_version": "1.0",
        "valid": not errors,
        "record_count": len(actual),
        "counts": dict(sorted(counts.items())),
        "errors": errors,
        "records": actual,
    }

def validate_engine_identity(root: Path) -> dict[str, Any]:
    root = root.resolve(strict=True)
    path = root / "registry/engine_identity.json"
    try:
        stored = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        stored = None
    current = build_engine_identity(root)
    return {
        "schema_version": "px.engine-identity-validation/1.0",
        "valid": stored == current,
        "manifest_path": "registry/engine_identity.json",
        "manifest_sha256": (
            hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() else None
        ),
        "tree_sha256": current["tree_sha256"],
        "file_total": current["file_total"],
    }

def _stable(value: object) -> str:
    return hashlib.sha256(
        json.dumps(value, sort_keys=True, separators=(",", ":"), default=str).encode()
    ).hexdigest()

def architecture_drift(
    baseline: Mapping[str, Iterable[str]], current: Mapping[str, Iterable[str]]
) -> dict[str, object]:
    old = {str(node): set(map(str, edges)) for node, edges in baseline.items()}
    new = {str(node): set(map(str, edges)) for node, edges in current.items()}
    added_nodes = sorted(set(new) - set(old))
    removed_nodes = sorted(set(old) - set(new))
    added_edges = sorted(
        (node, edge) for node in new for edge in new[node] - old.get(node, set())
    )
    removed_edges = sorted(
        (node, edge) for node in old for edge in old[node] - new.get(node, set())
    )
    denominator = max(1, len(old) + sum(map(len, old.values())))
    score = min(
        1.0,
        (len(added_nodes) + len(removed_nodes) + len(added_edges) + len(removed_edges))
        / denominator,
    )
    payload = {
        "added_nodes": added_nodes,
        "removed_nodes": removed_nodes,
        "added_edges": added_edges,
        "removed_edges": removed_edges,
    }
    return {
        **payload,
        "drift_score": round(score, 6),
        "baseline_sha256": _stable(old),
        "current_sha256": _stable(new),
    }

def benchmark_lab(
    runs: Iterable[Mapping[str, object]], *, baseline_version: str | None = None
) -> dict[str, object]:
    values = tuple(runs)
    groups: dict[str, list[Mapping[str, object]]] = {}
    errors = []
    for run in values:
        for field in (
            "candidate_id",
            "version",
            "fixture_version",
            "quality",
            "latency",
            "cost",
            "resource",
        ):
            if field not in run:
                errors.append(f"field_missing:{field}")
        if not errors or all(field in run for field in ("candidate_id", "version")):
            groups.setdefault(
                f"{run.get('candidate_id')}@{run.get('version')}", []
            ).append(run)
    reports = []
    for identity, items in sorted(groups.items()):
        metrics = {}
        for metric in ("quality", "latency", "cost", "resource"):
            samples = [float(item[metric]) for item in items if metric in item]
            if samples:
                metrics[metric] = {
                    "mean": round(sum(samples) / len(samples), 6),
                    "min": min(samples),
                    "max": max(samples),
                    "samples": len(samples),
                }
        reports.append(
            {
                "candidate": identity,
                "metrics": metrics,
                "fixture_versions": tuple(
                    sorted({str(item.get("fixture_version")) for item in items})
                ),
            }
        )
    return {
        "reports": tuple(reports),
        "errors": tuple(sorted(set(errors))),
        "baseline_version": baseline_version,
        "uncertainty_reported": True,
        "regression_gate": "blocked" if errors or not reports else "evaluable",
        "single_run_certifies": False,
    }

def code_genome(sources: Mapping[str, str]) -> dict[str, object]:
    files = []
    errors = []
    for path, source in sorted(sources.items()):
        try:
            tree = ast.parse(source, filename=path)
        except SyntaxError as error:
            errors.append({"path": path, "line": error.lineno, "kind": "syntax_error"})
            continue
        symbols = sorted(
            f"{type(node).__name__}:{node.name}:{len(node.args.args) if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) else 0}"
            for node in ast.walk(tree)
            if isinstance(node, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef))
        )
        imports = sorted(
            alias.name
            for node in ast.walk(tree)
            if isinstance(node, (ast.Import, ast.ImportFrom))
            for alias in node.names
        )
        files.append(
            {
                "path": path,
                "symbols": symbols,
                "imports": imports,
                "sha256": hashlib.sha256(source.encode()).hexdigest(),
            }
        )
    return {
        "files": tuple(files),
        "parse_errors": tuple(errors),
        "genome_sha256": _stable(files),
        "executes_source": False,
    }

def dependency_shockwave(
    graph: Mapping[str, Iterable[str]],
    changed: Iterable[str],
    *,
    max_depth: int = 8,
    max_nodes: int = 10_000,
) -> dict[str, object]:
    if max_depth < 1 or max_nodes < 1:
        raise ValueError("shockwave bounds must be positive")
    reverse: dict[str, set[str]] = {}
    for consumer, dependencies in graph.items():
        for dependency in dependencies:
            reverse.setdefault(str(dependency), set()).add(str(consumer))
    queue = deque((str(node), 0) for node in sorted(set(changed)))
    distance: dict[str, int] = {}
    while queue and len(distance) < max_nodes:
        node, depth = queue.popleft()
        if depth >= max_depth:
            continue
        for consumer in sorted(reverse.get(node, ())):
            next_depth = depth + 1
            if consumer not in distance or next_depth < distance[consumer]:
                distance[consumer] = next_depth
                queue.append((consumer, next_depth))
    truncated = bool(queue)
    ranked = tuple(
        sorted(
            (
                {"component": node, "distance": depth, "risk": round(1 / depth, 6)}
                for node, depth in distance.items()
            ),
            key=lambda item: (item["distance"], item["component"]),
        )
    )
    return {
        "affected": ranked,
        "truncated": truncated,
        "max_depth": max_depth,
        "max_nodes": max_nodes,
    }

def engineering_health(dimensions: Mapping[str, object]) -> dict[str, object]:
    scores = {}
    unknown = []
    for name in (
        "architecture",
        "dependencies",
        "contracts",
        "tests",
        "security",
        "operations",
        "knowledge",
    ):
        value = dimensions.get(name)
        if (
            not isinstance(value, (int, float))
            or isinstance(value, bool)
            or not 0 <= float(value) <= 1
        ):
            unknown.append(name)
        else:
            scores[name] = float(value)
    coverage = len(scores) / 7
    score = sum(scores.values()) / max(1, len(scores))
    return {
        "score": round(score, 6),
        "coverage": round(coverage, 6),
        "dimensions": scores,
        "unknown": unknown,
        "certifying": not unknown,
    }

def framework_dna(
    project_topology: Mapping[str, Iterable[str]],
    decision_graph: Iterable[Mapping[str, object]],
    validated_patterns: Iterable[Mapping[str, object]],
    *,
    exclusions: Iterable[str] = (),
) -> dict[str, object]:
    patterns = tuple(
        item
        for item in validated_patterns
        if item.get("validated") is True and item.get("id")
    )
    principles = tuple(
        sorted(
            {str(item.get("principle")) for item in patterns if item.get("principle")}
        )
    )
    modules = tuple(
        {"pattern_id": str(item["id"]), "state": "candidate_bootstrap_module"}
        for item in patterns
    )
    profile = {
        "topology_sha256": _stable(
            {key: sorted(map(str, value)) for key, value in project_topology.items()}
        ),
        "decision_sha256": _stable(tuple(decision_graph)),
        "principles": principles,
        "bootstrap_modules": modules,
        "project_specific_exclusions": tuple(sorted(set(map(str, exclusions)))),
        "blind_copy": False,
        "auto_activate": False,
    }
    return {**profile, "dna_sha256": _stable(profile)}

def opportunity_backlog(metrics: Iterable[Mapping[str, object]]) -> dict[str, object]:
    candidates = []
    for item in metrics:
        repetitions = max(0, int(item.get("repetitions", 0)))
        minutes = max(0.0, float(item.get("minutes_each", 0)))
        error_rate = min(1.0, max(0.0, float(item.get("error_rate", 0))))
        risk = min(1.0, max(0.0, float(item.get("automation_risk", 1))))
        value = (repetitions * minutes) * (1 + error_rate) * (1 - risk)
        if value <= 0:
            continue
        candidates.append(
            {
                "activity": str(item.get("activity", "unknown")),
                "value_score": round(value, 6),
                "automation_hypothesis": str(
                    item.get("hypothesis", "measure a bounded automation experiment")
                ),
                "risk": risk,
                "state": "candidate",
            }
        )
    candidates.sort(key=lambda item: (-item["value_score"], item["activity"]))
    return {
        "opportunities": tuple(candidates),
        "measured": True,
        "novelty_ranked": False,
        "auto_activate": False,
    }

def pattern_candidates(
    records: Iterable[Mapping[str, object]], *, minimum_support: int = 2
) -> dict[str, object]:
    if minimum_support < 2:
        raise ValueError("pattern support must require repetition")
    groups: dict[str, list[Mapping[str, object]]] = {}
    for record in records:
        signature = str(record.get("signature", "")).strip()
        if signature:
            groups.setdefault(signature, []).append(record)
    patterns = []
    for signature, items in sorted(groups.items()):
        if len(items) < minimum_support:
            continue
        patterns.append(
            {
                "signature": signature,
                "support": len(items),
                "examples": tuple(
                    sorted(
                        str(item.get("example", ""))
                        for item in items
                        if item.get("example")
                    )
                ),
                "generalization_proposal": str(
                    items[0].get("generalization", "review recurring structure")
                ),
                "validated": False,
            }
        )
    return {"patterns": tuple(patterns), "repetition_is_proof": False}

def refactoring_plan(*analyses: Mapping[str, object]) -> dict[str, object]:
    actions = []
    for analysis in analyses:
        for finding in analysis.get("findings", ()):
            actions.append(
                {
                    "finding": finding,
                    "action": "investigate_then_patch",
                    "approval_required": True,
                }
            )
        for node in analysis.get("removed_nodes", ()):
            actions.append(
                {
                    "finding": {"removed_node": node},
                    "action": "verify_dependents_and_contracts",
                    "approval_required": True,
                }
            )
    return {
        "actions": tuple(actions),
        "auto_apply": False,
        "plan_sha256": _stable(actions),
    }

def regression_hypotheses(
    changes: Iterable[Mapping[str, object]],
    failures: Iterable[Mapping[str, object]],
    dependency_graph: Mapping[str, Iterable[str]],
) -> dict[str, object]:
    """Rank evidence-backed regression hypotheses without asserting causality."""
    failed_components = {
        str(item.get("component", "")) for item in failures if item.get("component")
    }
    hypotheses = []
    for change in changes:
        component = str(change.get("component", ""))
        if not component:
            continue
        shockwave = dependency_shockwave(dependency_graph, [component])
        affected = {item["component"] for item in shockwave["affected"]} | {component}
        overlap = sorted(affected & failed_components)
        evidence = tuple(sorted(set(map(str, change.get("evidence", ())))))
        score = min(
            1.0,
            0.2 * len(overlap)
            + (0.2 if evidence else 0.0)
            + (0.2 if change.get("temporal_precedence") is True else 0.0),
        )
        if overlap:
            hypotheses.append(
                {
                    "change_id": str(change.get("change_id", "unknown")),
                    "component": component,
                    "affected_failures": overlap,
                    "evidence": evidence,
                    "score": round(score, 6),
                    "causality_proven": False,
                }
            )
    hypotheses.sort(key=lambda item: (-item["score"], item["change_id"]))
    return {
        "hypotheses": tuple(hypotheses),
        "causality_proven": False,
        "next": "isolate_and_reproduce",
    }

def repository_digital_twin(
    inventory: Iterable[str],
    manifests: Mapping[str, Iterable[str]],
    static_edges: Iterable[tuple[str, str]],
    runtime_edges: Iterable[tuple[str, str]],
) -> dict[str, object]:
    nodes = set(map(str, inventory)) | set(map(str, manifests))
    edges = {
        tuple(map(str, edge)) for edge in (*tuple(static_edges), *tuple(runtime_edges))
    }
    for source, target in edges:
        nodes.update((source, target))
    alerts = tuple(
        sorted(
            {
                f"manifest_target_missing:{source}->{target}"
                for source, targets in manifests.items()
                for target in targets
                if str(target) not in nodes
            }
        )
    )
    graph = {"nodes": tuple(sorted(nodes)), "edges": tuple(sorted(edges))}
    return {
        "graph": graph,
        "version": _stable(graph),
        "inconsistency_alerts": alerts,
        "simulation_interface": (
            "dependency_shockwave",
            "architecture_drift",
            "resilience_digital_twin",
        ),
        "source_of_truth": False,
    }

"""Auditable stage routing for the evidence-first engineering lifecycle."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from .project_management import validate_project_management
from .registry import validate_registry


def lifecycle_status(framework_root: Path, project: Path) -> dict[str, Any]:
    graph = json.loads(
        (framework_root / "registry" / "engineering_lifecycle.json").read_text(
            encoding="utf-8"
        )
    )
    project = project.resolve()
    registry = validate_registry(framework_root)
    checks: list[dict[str, Any]] = []
    checks.append(
        {
            "stage": "environment-discovery",
            "complete": registry["valid"],
            "blockers": registry["errors"],
        }
    )
    state_path = (
        project / ".engineering-bootstrap" / "project-management" / "state.json"
    )
    state: dict[str, Any] = {}
    if state_path.is_file():
        try:
            state = json.loads(state_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as error:
            state = {"_error": str(error)}
    pm_errors = (
        validate_project_management(project)
        if project.is_dir()
        else ["project root does not exist"]
    )
    checks.append(
        {
            "stage": "project-commissioning",
            "complete": not pm_errors,
            "blockers": pm_errors,
        }
    )
    tool_records = (
        state.get("evidence", {}).get("tool_intake_records", []) if state else []
    )
    checks.append(
        {
            "stage": "tool-and-package-admission",
            "complete": bool(tool_records),
            "blockers": []
            if tool_records
            else [
                "no project-scoped tool/package admission record; stage may be skipped only by an explicit no-tools decision"
            ],
        }
    )
    work = state.get("work", {}) if state else {}
    governance = state.get("governance", {}) if state else {}
    planned = (
        bool(work.get("objective"))
        and bool(work.get("milestones") or work.get("backlog"))
        and not governance.get("pending_approvals")
    )
    checks.append(
        {
            "stage": "architecture-and-planning",
            "complete": planned,
            "blockers": []
            if planned
            else [
                "objective, bounded work plan, and approval disposition are not complete"
            ],
        }
    )
    checkpoint = state.get("checkpoint", {}) if state else {}
    implementation = bool(checkpoint.get("changed_file_sha256"))
    checks.append(
        {
            "stage": "bounded-implementation",
            "complete": implementation,
            "blockers": []
            if implementation
            else ["no checkpointed implementation change set"],
        }
    )
    validation = checkpoint.get("validation", {}) if checkpoint else {}
    verified = validation.get("tests") not in (None, "not_run") and validation.get(
        "verifier"
    ) not in (None, "not_run", "incomplete")
    checks.append(
        {
            "stage": "verification-and-repair",
            "complete": verified,
            "blockers": []
            if verified
            else ["current test and independent-verifier evidence are required"],
        }
    )
    evidence = state.get("evidence", {}) if state else {}
    ready = bool(evidence.get("validation_receipt")) and verified
    checks.append(
        {
            "stage": "deployment-readiness",
            "complete": ready,
            "blockers": []
            if ready
            else [
                "installed-artifact, package, sanitation, rollback, and acceptance receipt is missing"
            ],
        }
    )
    process_records = evidence.get("process_records", []) if evidence else []
    checks.append(
        {
            "stage": "process-capture-and-skill-candidate",
            "complete": bool(process_records),
            "blockers": []
            if process_records
            else ["no verified engineering process record and candidate disposition"],
        }
    )
    stage_by_id = {item["id"]: item for item in graph["stages"]}
    next_stage = next((item["stage"] for item in checks if not item["complete"]), None)
    return {
        "valid": registry["valid"] and not state.get("_error"),
        "lifecycle": graph["id"],
        "complete": next_stage is None,
        "next_stage": next_stage,
        "next_stage_contract": stage_by_id.get(next_stage),
        "checks": checks,
        "invariants": graph["invariants"],
        "metadata_only": True,
    }

