def _negative_cases(f: dict[str, str], temp: Path) -> dict[str, ToolCase]:
    cases = {
        "permission-guard": ToolCase(
            (f["permission.json"], "--network", "example.com"), (3,)
        ),
        "prompt-injection-scanner": ToolCase((f["hostile.txt"],), (2,)),
        "secret-scanner": ToolCase((f["secret-dir"],), (2,)),
        "tool-policy-enforcer": ToolCase(
            (f["tool-policy.json"], f["denied-tool-request.json"]), (3,)
        ),
        "memory-write-gate": ToolCase((f["bad-memory-candidate.json"],), (3,)),
        "canary-compare": ToolCase((f["baseline.json"], f["bad-candidate.json"]), (4,)),
        "protocol-validator": ToolCase(
            (f["invalid-protocol.json"], "--kind", "openapi"), (2,)
        ),
        "archive-verifier": ToolCase((f["bad.zip"],), (1,)),
        "certification-aggregator": ToolCase(
            (f["fail-report.json"], "--out", str(temp / "failed-aggregate.json")),
            (1,),
            output_files=("failed-aggregate.json",),
        ),
        "completion-cutline": ToolCase((f["incomplete-status.json"],), (2,)),
        "ingestion-validator": ToolCase((str(temp / "empty.txt"),), (2,)),
    }
    for identifier in _positive_cases(f, temp):
        cases.setdefault(
            identifier,
            ToolCase(
                ("--pacify-x-invalid-boundary",),
                (1, 2, 3, 4),
                json_output=False,
            ),
        )
    return {
        identifier: ToolCase(
            case.args,
            case.expected_exit_codes,
            case.json_output,
            case.output_files,
            ("malformed_input", "wrong_type", "boundary_denial"),
        )
        for identifier, case in cases.items()
    }

def _tree_snapshot(root: Path) -> dict[str, str]:
    return {
        path.relative_to(root).as_posix(): _digest(path)
        for path in sorted(root.rglob("*"))
        if path.is_file() and "__pycache__" not in path.parts
    }

def _redact_fixture_roots(value: str, root_aliases: tuple[str, ...]) -> str:
    normalized = value.replace("\\", "/")
    for alias in sorted(set(root_aliases), key=len, reverse=True):
        candidate = alias.replace("\\", "/").rstrip("/")
        if candidate:
            normalized = re.sub(
                re.escape(candidate), "<fixture-root>", normalized, flags=re.IGNORECASE
            )
    return normalized


def _normalized(value: object, root_aliases: tuple[str, ...] = ()) -> object:
    if isinstance(value, dict):
        volatile_keys = {
            "at",
            "disk_free_bytes",
            "expires_at",
            "startedOn",
            "finishedOn",
            "requested_at",
            "verified_at",
        }
        return {
            key: _normalized(item, root_aliases)
            for key, item in sorted(value.items())
            if key not in volatile_keys
            and not any(
                token in key.casefold()
                for token in ("time", "created", "updated", "duration", "timestamp")
            )
        }
    if isinstance(value, list):
        return [_normalized(item, root_aliases) for item in value]
    if isinstance(value, str) and root_aliases:
        return _redact_fixture_roots(value, root_aliases)
    return value


def _normalized_digest(content: bytes, root: Path | None = None) -> str:
    aliases = (
        ()
        if root is None
        else tuple(
            {
                str(root),
                str(root.resolve()),
                os.path.abspath(str(root)),
                os.path.realpath(str(root)),
            }
        )
    )
    try:
        value = json.loads(content.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError):
        try:
            normalized = _redact_fixture_roots(content.decode("utf-8"), aliases).encode(
                "utf-8"
            )
        except UnicodeError:
            normalized = content
        return hashlib.sha256(normalized).hexdigest()
    return hashlib.sha256(
        json.dumps(
            _normalized(value, aliases), sort_keys=True, separators=(",", ":")
        ).encode()
    ).hexdigest()

def _seal(value: dict[str, Any]) -> dict[str, Any]:
    unsigned = dict(value)
    unsigned.pop("receipt_sha256", None)
    digest = hashlib.sha256(
        json.dumps(unsigned, sort_keys=True, separators=(",", ":")).encode()
    ).hexdigest()
    return {**unsigned, "receipt_sha256": digest}


def _sealed(value: dict[str, Any]) -> bool:
    expected = value.get("receipt_sha256")
    return isinstance(expected, str) and _seal(value)["receipt_sha256"] == expected

