def search_external_candidates(
    root: Path,
    query: str,
    *,
    limit: int = 8,
    kinds: Iterable[str] = (),
) -> dict[str, object]:
    if not query.strip() or not 1 <= limit <= 100:
        raise ValueError("nonblank query and limit between 1 and 100 are required")
    catalog = load_external_catalog(root)
    selected_kinds = set(map(str, kinds))
    records = [
        item
        for item in catalog["records"]
        if not selected_kinds or str(item.get("kind")) in selected_kinds
    ]
    query_terms = _terms(query)
    query_counts = Counter(query_terms)
    documents = [
        _terms(
            " ".join(
                [
                    str(item.get("id", "")),
                    str(item.get("title", "")),
                    str(item.get("summary", "")),
                    " ".join(map(str, item.get("keywords", ()) or ())),
                    " ".join(map(str, item.get("aliases", ()) or ())),
                    str(item.get("category", "")),
                    str(item.get("owner", "")),
                ]
            )
        )
        for item in records
    ]
    frequency: Counter[str] = Counter()
    for terms in documents:
        frequency.update(set(terms))
    average = max(1.0, sum(map(len, documents)) / max(1, len(documents)))
    phrase = query.strip().casefold()
    hits = []
    for record, terms in zip(records, documents):
        counts = Counter(terms)
        score = 0.0
        for term, weight in query_counts.items():
            tf = counts.get(term, 0)
            if not tf:
                continue
            df = frequency.get(term, 0)
            inverse = math.log(1 + (len(records) - df + 0.5) / (df + 0.5))
            score += (
                inverse
                * (tf * 2.5)
                / (tf + 1.5 * (1 - 0.72 + 0.72 * len(terms) / average))
                * weight
            )
        identifier = str(record.get("id", "")).casefold()
        title = str(record.get("title", "")).casefold()
        aliases = {str(value).casefold() for value in record.get("aliases", ()) or ()}
        if phrase in {identifier, title}:
            score += 16
        elif phrase in identifier or phrase in title:
            score += 7
        if phrase in aliases:
            score += 12
        if score <= 0:
            continue
        hits.append(
            {
                "id": record["id"],
                "kind": record.get("kind"),
                "title": record.get("title"),
                "summary": record.get("summary"),
                "owner": record.get("owner"),
                "status": record.get("status", "reference_only"),
                "score": round(score, 6),
                "matched_terms": sorted(set(query_terms) & set(terms)),
                "admission_required": True,
                "authority": "none",
                "metadata_only": True,
            }
        )
    hits.sort(key=lambda item: (-float(item["score"]), str(item["id"])))
    return {
        "valid": True,
        "query": query,
        "results": hits[:limit],
        "canonical": False,
        "active_registry_mutation": False,
    }


def hydrate_external_metadata(
    root: Path,
    candidate_ids: Iterable[str],
    *,
    max_records: int = 3,
    max_bytes: int = 32768,
) -> dict[str, object]:
    """Hydrate bounded registry metadata only; never read imported source bodies."""
    if max_records < 1 or max_bytes < 1:
        raise ValueError("positive hydration bounds are required")
    catalog = load_external_catalog(root)
    by_id = {str(item["id"]): item for item in catalog["records"]}
    selected = []
    used = 0
    missing = []
    for identifier in tuple(dict.fromkeys(map(str, candidate_ids)))[:max_records]:
        record = by_id.get(identifier)
        if record is None:
            missing.append(identifier)
            continue
        sanitized = {
            key: value
            for key, value in record.items()
            if key not in {"body", "content", "raw_source"}
        }
        size = len(json.dumps(sanitized, ensure_ascii=False).encode("utf-8"))
        if used + size > max_bytes:
            break
        selected.append(sanitized)
        used += size
    return {
        "valid": not missing,
        "records": selected,
        "missing": missing,
        "used_bytes": used,
        "max_bytes": max_bytes,
        "metadata_only": True,
        "source_bodies_loaded": 0,
        "authority_granted": False,
    }

def validate_external_capability_orchestration(root: Path) -> dict[str, object]:
    path = root / "orchestration/workflows/external-capability-intake.yaml"
    if not path.is_file():
        return {"valid": False, "errors": ["workflow missing"]}
    text = path.read_text(encoding="utf-8")
    required = (
        "inventory",
        "license",
        "search-metadata",
        "overlap",
        "plan-stage",
        "admission",
        "certify",
    )
    missing = [item for item in required if f'"{item}"' not in text]
    try:
        status = external_catalog_status(root)
    except (OSError, ValueError, json.JSONDecodeError) as error:
        return {"valid": False, "errors": [f"catalog invalid: {type(error).__name__}"]}
    return {
        "valid": not missing and status["valid"],
        "errors": [f"missing step: {item}" for item in missing],
        "catalog": status,
        "effects": ["read_local", "write_project_staging"],
    }

def apply_selective_stage(
    project: Path,
    plan: SelectiveStagePlan,
    *,
    approval_evidence: Iterable[str],
    apply: bool = False,
) -> dict[str, object]:
    """Persist a project binding receipt; active registries and skill bodies remain untouched."""
    project = project.resolve(strict=True)
    evidence = tuple(sorted(set(filter(None, map(str, approval_evidence)))))
    errors = []
    if plan.collisions:
        errors.append("project skill collision")
    if plan.unresolved_dependencies:
        errors.append("candidate dependency remains unresolved")
    if not evidence:
        errors.append("review evidence is required")
    result = {
        "valid": not errors,
        "applied": False,
        "plan": asdict(plan),
        "errors": errors,
        "hard_delete": False,
        "active_registry_mutation": False,
    }
    if not apply or errors:
        return result
    directory = project / ".engineering-bootstrap/external-capabilities/staged"
    target = directory / f"{plan.plan_id}.json"
    receipt = {
        "schema_version": "1.0",
        "plan": asdict(plan),
        "approval_evidence": list(evidence),
        "state": "staged_candidate",
        "created_utc": datetime.now(timezone.utc).isoformat(),
        "active_registry_mutation": False,
        "authority_granted": False,
    }
    rendered = json.dumps(receipt, indent=2, ensure_ascii=False) + "\n"
    target.parent.mkdir(parents=True, exist_ok=True)
    if target.exists() and target.read_text(encoding="utf-8") != rendered:
        existing = load_json_object(target)
        comparable = {
            key: value for key, value in existing.items() if key != "created_utc"
        }
        planned = {key: value for key, value in receipt.items() if key != "created_utc"}
        if comparable != planned:
            raise ValueError("selective stage receipt drift")
    elif not target.exists():
        with target.open("x", encoding="utf-8", newline="\n") as stream:
            stream.write(rendered)
    return {
        **result,
        "valid": True,
        "applied": True,
        "receipt": target.relative_to(project).as_posix(),
        "errors": [],
    }

def plan_selective_stage(
    root: Path, project: Path, *, project_id: str, bundle_ids: Iterable[str]
) -> SelectiveStagePlan:
    root = root.resolve(strict=True)
    project = project.resolve(strict=True)
    if not (project / ".engineering-bootstrap/project-management/state.json").is_file():
        raise ValueError("target project is not commissioned")
    catalog = load_external_catalog(root)
    bundles = {str(item["id"]): item for item in catalog["bundles"]}
    selected_ids = tuple(sorted(set(map(str, bundle_ids))))
    if not selected_ids:
        raise ValueError("at least one external bundle is required")
    missing = sorted(set(selected_ids) - set(bundles))
    if missing:
        raise ValueError("unknown external bundles: " + ", ".join(missing))
    hashes: dict[str, str] = {}
    collisions = []
    dependencies = []
    candidate_ids = {str(item["id"]) for item in catalog["candidates"]}
    selected_capability_ids = {
        str(capability_id)
        for identifier in selected_ids
        for capability_id in bundles[identifier].get("candidate_capabilities", ())
    }
    for identifier in selected_ids:
        bundle = bundles[identifier]
        body = root / str(bundle["body"])
        if not body.is_file() or not _inside(body, root):
            raise ValueError(f"external bundle body is unavailable: {identifier}")
        hashes[identifier] = hashlib.sha256(body.read_bytes()).hexdigest()
        if (project / ".px/skills" / identifier).exists():
            collisions.append(identifier)
        for capability_id in bundle.get("candidate_capabilities", ()):
            capability = next(
                (
                    item
                    for item in catalog["candidates"]
                    if item.get("id") == capability_id
                ),
                None,
            )
            if capability is None:
                dependencies.append(str(capability_id))
                continue
            for dependency in capability.get("dependencies", ()):
                if (
                    dependency in candidate_ids
                    and dependency not in selected_capability_ids
                ):
                    dependencies.append(str(dependency))
    payload = {
        "project_id": project_id,
        "bundle_ids": selected_ids,
        "body_sha256": hashes,
        "collisions": sorted(collisions),
        "unresolved_dependencies": sorted(set(dependencies)),
    }
    return SelectiveStagePlan(
        "xcp_" + _stable(payload)[:24],
        project_id,
        selected_ids,
        hashes,
        tuple(sorted(collisions)),
        tuple(sorted(set(dependencies))),
    )

def validate_external_evidence(
    root: Path, *, strict: bool = False, evidence_root: Path | None = None
) -> dict[str, Any]:
    root = root.resolve()
    index_path = root / "evidence/externalized-payload-index.json"
    if not index_path.is_file():
        errors = ["externalized payload index is missing"] if strict else []
        return {
            "schema_version": "1.0",
            "valid": not errors,
            "references": 0,
            "verified": 0,
            "strict": strict,
            "errors": errors,
        }
    try:
        index = json.loads(index_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        return {
            "schema_version": "1.0",
            "valid": False,
            "references": 0,
            "verified": 0,
            "strict": strict,
            "errors": [
                f"externalized payload index is unreadable: {type(error).__name__}"
            ],
        }
    errors = []
    verified = 0
    schema = root / "contracts/evidence-reference.schema.json"
    for record in index.get("records", []):
        try:
            validate_instance(record, schema)
        except (ValueError, OSError) as error:
            errors.append(f"{record.get('reference_id')}: invalid reference: {error}")
            continue
        relative = Path(str(record["manifest"]))
        if relative.is_absolute() or ".." in relative.parts:
            errors.append(
                f"{record['reference_id']}: manifest path must be product-relative and traversal-free"
            )
            continue
        base = evidence_root.resolve() if evidence_root else root
        manifest_path = (base / relative).resolve()
        if base not in manifest_path.parents:
            errors.append(f"{record['reference_id']}: manifest escapes evidence root")
            continue
        if not manifest_path.is_file():
            if strict or record["availability"].startswith("bundled"):
                errors.append(f"{record['reference_id']}: required manifest is missing")
            continue
        actual = hashlib.sha256(manifest_path.read_bytes()).hexdigest()
        if actual != record["sha256"]:
            errors.append(f"{record['reference_id']}: manifest hash mismatch")
            continue
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        inventory_path = manifest_path.parent / str(manifest["inventory"])
        if (
            not inventory_path.is_file()
            or hashlib.sha256(inventory_path.read_bytes()).hexdigest()
            != manifest["inventory_sha256"]
        ):
            errors.append(
                f"{record['reference_id']}: bundled inventory is missing or mismatched"
            )
            continue
        if record["bundle_id"] != f"sha256:{manifest['inventory_sha256']}":
            errors.append(
                f"{record['reference_id']}: bundle ID does not bind the inventory"
            )
            continue
        verified += 1
    return {
        "schema_version": "1.0",
        "valid": not errors,
        "references": len(index.get("records", [])),
        "verified": verified,
        "strict": strict,
        "errors": errors,
    }

class FileLock:
    """Acquire an exclusive byte lock and maintain its process-bound lease.

    The operating-system byte lock remains authoritative. The JSON lease adds a
    unique token, PID-generation fingerprint, heartbeat, and immutable recovery
    evidence. A free byte lock is not taken over when its retained lease still
    identifies a live process; this conservative check prevents lock theft when
    a filesystem or platform supplies weaker advisory-lock semantics.
    """

    def __init__(
        self,
        path: Path,
        *,
        timeout_seconds: float = 5.0,
        minimum_sleep_seconds: float = 0.005,
        maximum_sleep_seconds: float = 0.1,
        heartbeat_interval_seconds: float = DEFAULT_HEARTBEAT_INTERVAL_SECONDS,
    ) -> None:
        if (
            timeout_seconds <= 0
            or minimum_sleep_seconds <= 0
            or maximum_sleep_seconds < minimum_sleep_seconds
            or heartbeat_interval_seconds <= 0
        ):
            raise ValueError("file-lock timing values must be positive and ordered")
        self.path = path
        self.timeout_seconds = timeout_seconds
        self.minimum_sleep_seconds = minimum_sleep_seconds
        self.maximum_sleep_seconds = maximum_sleep_seconds
        self.heartbeat_interval_seconds = heartbeat_interval_seconds
        self._stream = None
        self._token: str | None = None
        self._lease: dict[str, object] | None = None
        self._heartbeat_stop: threading.Event | None = None
        self._heartbeat_thread: threading.Thread | None = None
        self._heartbeat_error: OSError | None = None
        self._metadata_guard = threading.Lock()
        self.recovery_receipt_path: Path | None = None
        self.attempts = 0
        self.slept_seconds = 0.0

    @staticmethod
    def _decode_record(raw: bytes) -> dict[str, object] | None:
        payload = raw[1:].strip(b"\x00\r\n ") if raw else b""
        if not payload:
            return None
        try:
            value = json.loads(payload.decode("utf-8"))
        except (UnicodeError, json.JSONDecodeError):
            return {
                "state": "unparseable",
                "raw_sha256": hashlib.sha256(payload).hexdigest(),
            }
        return dict(value) if isinstance(value, Mapping) else {"state": "unparseable"}

    def _read_record(self) -> dict[str, object] | None:
        try:
            # Byte zero is the advisory lock region. Starting at byte one lets
            # observers inspect lease health even while Windows denies reads of
            # the locked byte itself.
            with self.path.open("rb") as stream:
                stream.seek(1)
                return self._decode_record(b"0" + stream.read())
        except OSError:
            return None

    def _owner_diagnostic(self) -> str:
        record = self._read_record()
        if record is None:
            return "owner unavailable"
        if record.get("state") == "unparseable":
            return f"owner metadata unparseable sha256={record.get('raw_sha256', 'unknown')}"
        return (
            f"owner pid={record.get('pid', 'unknown')} "
            f"token={record.get('token', 'unknown')} "
            f"heartbeat_utc={record.get('heartbeat_utc', 'unknown')}"
        )

    @staticmethod
    def _owner_is_live(record: Mapping[str, object]) -> bool:
        if record.get("state") != "held":
            return False
        try:
            pid = int(record["pid"])
        except (KeyError, TypeError, ValueError):
            # Malformed held metadata is not sufficient evidence of a live owner.
            return False
        if not _process_exists(pid):
            return False
        expected = record.get("process_start_fingerprint")
        actual = _process_start_fingerprint(pid)
        if not isinstance(expected, str) or not expected:
            # A live PID with legacy/incomplete identity is conservatively held.
            return True
        if actual is None:
            # Inspection can be unavailable across users; do not steal in doubt.
            return True
        return secrets.compare_digest(expected, actual)

    def _write_record(self, record: Mapping[str, object]) -> None:
        if self._stream is None:
            raise OSError("cannot write lease metadata without an acquired stream")
        payload = json.dumps(
            dict(record), sort_keys=True, separators=(",", ":"), ensure_ascii=True
        ).encode("ascii")
        with self._metadata_guard:
            self._stream.seek(1)
            self._stream.truncate()
            self._stream.write(payload)
            self._stream.flush()
            os.fsync(self._stream.fileno())

    def _record_recovery(self, previous: Mapping[str, object]) -> Path:
        if self._token is None:
            raise OSError("recovery requires an allocated lease token")
        receipt_dir = self.path.parent / ".lock-recovery-receipts" / self.path.name
        receipt_dir.mkdir(parents=True, exist_ok=True)
        recovered_ns = time.time_ns()
        receipt: dict[str, object] = {
            "schema_version": LEASE_SCHEMA_VERSION,
            "receipt_type": "dead_file_lock_owner_recovery",
            # The receipt is stored below the lock's own parent, so the sibling
            # name is an exact portable locator. Never freeze a workstation-
            # absolute checkout path into retained project evidence.
            "lock_path": self.path.name,
            "lock_path_basis": "receipt_parent",
            "recovered_utc": datetime.fromtimestamp(
                recovered_ns / 1_000_000_000, timezone.utc
            ).isoformat(),
            "recovered_unix_ns": recovered_ns,
            "reason": (
                "unparseable_owner_metadata"
                if previous.get("state") == "unparseable"
                else "recorded_owner_not_live"
            ),
            "previous_lease": dict(previous),
            "recovered_by": {
                "token": self._token,
                "pid": os.getpid(),
                "process_start_fingerprint": _process_start_fingerprint(os.getpid()),
            },
        }
        canonical = json.dumps(
            receipt, sort_keys=True, separators=(",", ":"), ensure_ascii=True
        ).encode("ascii")
        receipt["receipt_sha256"] = hashlib.sha256(canonical).hexdigest()
        target = receipt_dir / f"{recovered_ns}-{self._token}.json"
        with target.open("x", encoding="utf-8", newline="\n") as stream:
            json.dump(receipt, stream, indent=2, sort_keys=True)
            stream.write("\n")
            stream.flush()
            os.fsync(stream.fileno())
        return target

    def _lock_stream(self) -> None:
        assert self._stream is not None
        self._stream.seek(0)
        if os.name == "nt":
            import msvcrt

            msvcrt.locking(self._stream.fileno(), msvcrt.LK_NBLCK, 1)
        else:
            import fcntl

            fcntl.flock(self._stream.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)

    def _unlock_stream(self) -> None:
        if self._stream is None:
            return
        self._stream.seek(0)
        if os.name == "nt":
            import msvcrt

            msvcrt.locking(self._stream.fileno(), msvcrt.LK_UNLCK, 1)
        else:
            import fcntl

            fcntl.flock(self._stream.fileno(), fcntl.LOCK_UN)

    def _abandon_attempt(self) -> None:
        if self._stream is None:
            return
        try:
            self._unlock_stream()
        except OSError:
            pass
        self._stream.close()
        self._stream = None

    def _acquire_once(self) -> None:
        if self._stream is None:
            self._stream = self.path.open("r+b")
        self._lock_stream()
        try:
            previous = self._decode_record(self._stream.read())
            if previous is not None and self._owner_is_live(previous):
                raise BlockingIOError("retained lease identifies a live process owner")
            self._token = secrets.token_hex(16)
            if previous is not None and previous.get("state") != "released":
                self.recovery_receipt_path = self._record_recovery(previous)
            acquired_ns = time.time_ns()
            fingerprint = _process_start_fingerprint(os.getpid())
            if fingerprint is None:
                raise OSError("current process start fingerprint is unavailable")
            self._lease = {
                "schema_version": LEASE_SCHEMA_VERSION,
                "state": "held",
                "token": self._token,
                "pid": os.getpid(),
                "hostname": socket.gethostname(),
                "process_start_fingerprint": fingerprint,
                "acquired_utc": datetime.fromtimestamp(
                    acquired_ns / 1_000_000_000, timezone.utc
                ).isoformat(),
                "acquired_unix_ns": acquired_ns,
                "heartbeat_utc": datetime.fromtimestamp(
                    acquired_ns / 1_000_000_000, timezone.utc
                ).isoformat(),
                "heartbeat_unix_ns": acquired_ns,
            }
            self._write_record(self._lease)
        except BaseException:
            self._abandon_attempt()
            raise

    def _heartbeat_once(self) -> None:
        if self._lease is None or self._stream is None:
            return
        heartbeat_ns = time.time_ns()
        self._lease["heartbeat_utc"] = datetime.fromtimestamp(
            heartbeat_ns / 1_000_000_000, timezone.utc
        ).isoformat()
        self._lease["heartbeat_unix_ns"] = heartbeat_ns
        self._write_record(self._lease)

    def _heartbeat_loop(self) -> None:
        assert self._heartbeat_stop is not None
        while not self._heartbeat_stop.wait(self.heartbeat_interval_seconds):
            try:
                self._heartbeat_once()
            except OSError as error:
                self._heartbeat_error = error
                return

    def _start_heartbeat(self) -> None:
        self._heartbeat_stop = threading.Event()
        self._heartbeat_thread = threading.Thread(
            target=self._heartbeat_loop,
            name=f"file-lock-heartbeat-{self.path.name}",
            daemon=True,
        )
        self._heartbeat_thread.start()

    def __enter__(self) -> "FileLock":
        self.path.parent.mkdir(parents=True, exist_ok=True)
        # Initialize exactly once. Writing through every contender races with
        # an already-held Windows byte-range lock and can raise PermissionError.
        try:
            with self.path.open("xb") as initializer:
                initializer.write(b"0")
                initializer.flush()
                os.fsync(initializer.fileno())
        except (FileExistsError, PermissionError):
            self._stream = None
        deadline = time.monotonic() + self.timeout_seconds
        delay = self.minimum_sleep_seconds
        while True:
            self.attempts += 1
            try:
                self._acquire_once()
                break
            except OSError as error:
                now = time.monotonic()
                if now >= deadline:
                    owner = self._owner_diagnostic()
                    self._abandon_attempt()
                    raise FileLockTimeout(
                        f"control state is locked by another process: {self.path}; {owner}; attempts={self.attempts}"
                    ) from error
                remaining = deadline - now
                sleep_for = min(remaining, delay * random.uniform(0.8, 1.2))
                time.sleep(sleep_for)
                self.slept_seconds += sleep_for
                delay = min(self.maximum_sleep_seconds, delay * 2)
        self._start_heartbeat()
        return self

    def __exit__(self, exc_type, exc, traceback) -> None:
        if self._stream is None:
            return
        if self._heartbeat_stop is not None:
            self._heartbeat_stop.set()
        if self._heartbeat_thread is not None:
            self._heartbeat_thread.join(timeout=1.0)
        release_error: OSError | None = self._heartbeat_error
        if self._lease is not None:
            released_ns = time.time_ns()
            self._lease["state"] = "released"
            self._lease["released_utc"] = datetime.fromtimestamp(
                released_ns / 1_000_000_000, timezone.utc
            ).isoformat()
            self._lease["released_unix_ns"] = released_ns
            try:
                self._write_record(self._lease)
            except OSError as error:
                release_error = release_error or error
        try:
            self._unlock_stream()
        finally:
            self._stream.close()
            self._stream = None
        if release_error is not None and exc_type is None:
            raise release_error

def __exit__(self, exc_type, exc, traceback) -> None:
    if self._stream is None:
        return
    if self._heartbeat_stop is not None:
        self._heartbeat_stop.set()
    if self._heartbeat_thread is not None:
        self._heartbeat_thread.join(timeout=1.0)
    release_error: OSError | None = self._heartbeat_error
    if self._lease is not None:
        released_ns = time.time_ns()
        self._lease["state"] = "released"
        self._lease["released_utc"] = datetime.fromtimestamp(
            released_ns / 1_000_000_000, timezone.utc
        ).isoformat()
        self._lease["released_unix_ns"] = released_ns
        try:
            self._write_record(self._lease)
        except OSError as error:
            release_error = release_error or error
    try:
        self._unlock_stream()
    finally:
        self._stream.close()
        self._stream = None
    if release_error is not None and exc_type is None:
        raise release_error

def _acquire_once(self) -> None:
    if self._stream is None:
        self._stream = self.path.open("r+b")
    self._lock_stream()
    try:
        previous = self._decode_record(self._stream.read())
        if previous is not None and self._owner_is_live(previous):
            raise BlockingIOError("retained lease identifies a live process owner")
        self._token = secrets.token_hex(16)
        if previous is not None and previous.get("state") != "released":
            self.recovery_receipt_path = self._record_recovery(previous)
        acquired_ns = time.time_ns()
        fingerprint = _process_start_fingerprint(os.getpid())
        if fingerprint is None:
            raise OSError("current process start fingerprint is unavailable")
        self._lease = {
            "schema_version": LEASE_SCHEMA_VERSION,
            "state": "held",
            "token": self._token,
            "pid": os.getpid(),
            "hostname": socket.gethostname(),
            "process_start_fingerprint": fingerprint,
            "acquired_utc": datetime.fromtimestamp(
                acquired_ns / 1_000_000_000, timezone.utc
            ).isoformat(),
            "acquired_unix_ns": acquired_ns,
            "heartbeat_utc": datetime.fromtimestamp(
                acquired_ns / 1_000_000_000, timezone.utc
            ).isoformat(),
            "heartbeat_unix_ns": acquired_ns,
        }
        self._write_record(self._lease)
    except BaseException:
        self._abandon_attempt()
        raise

def _heartbeat_loop(self) -> None:
    assert self._heartbeat_stop is not None
    while not self._heartbeat_stop.wait(self.heartbeat_interval_seconds):
        try:
            self._heartbeat_once()
        except OSError as error:
            self._heartbeat_error = error
            return

def _owner_is_live(record: Mapping[str, object]) -> bool:
    if record.get("state") != "held":
        return False
    try:
        pid = int(record["pid"])
    except (KeyError, TypeError, ValueError):
        # Malformed held metadata is not sufficient evidence of a live owner.
        return False
    if not _process_exists(pid):
        return False
    expected = record.get("process_start_fingerprint")
    actual = _process_start_fingerprint(pid)
    if not isinstance(expected, str) or not expected:
        # A live PID with legacy/incomplete identity is conservatively held.
        return True
    if actual is None:
        # Inspection can be unavailable across users; do not steal in doubt.
        return True
    return secrets.compare_digest(expected, actual)

"""Clean-room contracts derived from behavior requirements, never source code.

Every function is deterministic and read-only.  The module compares supplied
metadata; it does not import external implementations, contact services, load
models, mutate datasets, or activate a runtime.
"""

from __future__ import annotations

from dataclasses import asdict, dataclass
import hashlib
import json
import math
import re
from typing import Iterable, Mapping, Sequence


SHA256 = re.compile(r"^[0-9a-f]{64}$")
KNOWN_SPLITS = {"train", "validation", "test"}
KNOWN_SURFACE_CHECKS = {
    "config",
    "static",
    "unit",
    "integration",
    "contract",
    "build",
    "health",
    "logs",
    "route",
    "interaction",
    "accessibility",
    "rollback",
}


def _stable(value: object) -> str:
    return hashlib.sha256(
        json.dumps(value, sort_keys=True, separators=(",", ":"), default=str).encode()
    ).hexdigest()


@dataclass(frozen=True, slots=True)
class ContractSurface:
    contract_id: str
    owner: str
    method: str
    route: str
    fields: Mapping[str, str]
    required_fields: tuple[str, ...]
    authorization_scopes: tuple[str, ...] = ()
    version: str = "1"


def compare_contract_surfaces(
    providers: Iterable[ContractSurface],
    consumers: Iterable[ContractSurface],
) -> dict[str, object]:
    """Compare provider/consumer shapes, ownership, routes, and permissions."""
    provider_values = tuple(providers)
    consumer_values = tuple(consumers)
    provider_ids = [item.contract_id for item in provider_values]
    consumer_ids = [item.contract_id for item in consumer_values]
    if len(provider_ids) != len(set(provider_ids)) or len(consumer_ids) != len(
        set(consumer_ids)
    ):
        raise ValueError("contract IDs must be unique within each side")
    provider_map = {item.contract_id: item for item in provider_values}
    findings: list[dict[str, object]] = []
    for consumer in consumer_values:
        provider = provider_map.get(consumer.contract_id)
        if provider is None:
            findings.append(
                {
                    "contract_id": consumer.contract_id,
                    "kind": "provider_missing",
                    "severity": "high",
                }
            )
            continue
        if not provider.owner.strip():
            findings.append(
                {
                    "contract_id": consumer.contract_id,
                    "kind": "canonical_owner_missing",
                    "severity": "high",
                }
            )
        for field, left, right in (
            ("method", provider.method.upper(), consumer.method.upper()),
            ("route", provider.route, consumer.route),
            ("version", provider.version, consumer.version),
        ):
            if left != right:
                findings.append(
                    {
                        "contract_id": consumer.contract_id,
                        "kind": f"{field}_mismatch",
                        "severity": "high",
                        "provider": left,
                        "consumer": right,
                    }
                )
        missing = sorted(set(consumer.required_fields) - set(provider.fields))
        for field in missing:
            findings.append(
                {
                    "contract_id": consumer.contract_id,
                    "kind": "required_field_missing",
                    "field": field,
                    "severity": "high",
                }
            )
        for field in sorted(set(consumer.required_fields) & set(provider.fields)):
            expected = consumer.fields.get(field)
            actual = provider.fields.get(field)
            if expected and actual != expected:
                findings.append(
                    {
                        "contract_id": consumer.contract_id,
                        "kind": "field_type_mismatch",
                        "field": field,
                        "provider": actual,
                        "consumer": expected,
                        "severity": "high",
                    }
                )
        provider_scopes = set(provider.authorization_scopes)
        consumer_scopes = set(consumer.authorization_scopes)
        for scope in sorted(consumer_scopes - provider_scopes):
            findings.append(
                {
                    "contract_id": consumer.contract_id,
                    "kind": "provider_scope_missing",
                    "scope": scope,
                    "severity": "high",
                }
            )
        for scope in sorted(provider_scopes - consumer_scopes):
            findings.append(
                {
                    "contract_id": consumer.contract_id,
                    "kind": "consumer_scope_unmodeled",
                    "scope": scope,
                    "severity": "medium",
                }
            )
    unconsumed = tuple(sorted(set(provider_ids) - set(consumer_ids)))
    return {
        "decision": "compatible" if not findings else "incompatible",
        "findings": tuple(findings),
        "unconsumed_provider_contracts": unconsumed,
        "provider_sha256": _stable([asdict(item) for item in provider_values]),
        "consumer_sha256": _stable([asdict(item) for item in consumer_values]),
        "source_code_executed": False,
    }


@dataclass(frozen=True, slots=True)
class RetrievalCase:
    case_id: str
    relevant_ids: tuple[str, ...]
    forbidden_ids: tuple[str, ...] = ()


def evaluate_retrieval_readiness(
    cases: Iterable[RetrievalCase],
    ranked_results: Mapping[str, Sequence[str]],
    *,
    k: int = 5,
    minimum_recall: float = 0.8,
    minimum_mrr: float = 0.7,
    minimum_coverage: float = 1.0,
) -> dict[str, object]:
    """Evaluate synthetic/approved retrieval cases and fail closed on leakage."""
    if k < 1 or not all(
        0 <= value <= 1 for value in (minimum_recall, minimum_mrr, minimum_coverage)
    ):
        raise ValueError("retrieval bounds are invalid")
    values = tuple(cases)
    if not values or len({case.case_id for case in values}) != len(values):
        raise ValueError("retrieval cases must be non-empty with unique IDs")
    rows = []
    reasons = []
    recalls = []
    reciprocal_ranks = []
    covered = 0
    forbidden_exposures = []
    for case in values:
        relevant = set(case.relevant_ids)
        if not relevant:
            reasons.append(f"relevance_judgment_missing:{case.case_id}")
        result = tuple(map(str, ranked_results.get(case.case_id, ())))[:k]
        if result:
            covered += 1
        if len(result) != len(set(result)):
            reasons.append(f"duplicate_result_ids:{case.case_id}")
        hits = [index for index, item in enumerate(result, 1) if item in relevant]
        recall = len(set(result) & relevant) / max(1, len(relevant))
        reciprocal_rank = 1 / hits[0] if hits else 0.0
        exposed = tuple(sorted(set(result) & set(case.forbidden_ids)))
        if exposed:
            forbidden_exposures.append({"case_id": case.case_id, "ids": exposed})
        recalls.append(recall)
        reciprocal_ranks.append(reciprocal_rank)
        rows.append(
            {
                "case_id": case.case_id,
                "returned": len(result),
                "recall_at_k": round(recall, 6),
                "reciprocal_rank": round(reciprocal_rank, 6),
                "forbidden_exposure": exposed,
            }
        )
    metrics = {
        "cases": len(values),
        "k": k,
        "coverage": round(covered / len(values), 6),
        "mean_recall_at_k": round(sum(recalls) / len(recalls), 6),
        "mean_reciprocal_rank": round(sum(reciprocal_ranks) / len(reciprocal_ranks), 6),
        "forbidden_exposure_count": sum(
            len(item["ids"]) for item in forbidden_exposures
        ),
    }
    if metrics["coverage"] < minimum_coverage:
        reasons.append("coverage_below_threshold")
    if metrics["mean_recall_at_k"] < minimum_recall:
        reasons.append("recall_below_threshold")
    if metrics["mean_reciprocal_rank"] < minimum_mrr:
        reasons.append("mrr_below_threshold")
    if forbidden_exposures:
        reasons.append("forbidden_result_exposed")
    reasons = sorted(set(reasons))
    return {
        "decision": "ready" if not reasons else "blocked",
        "activation_allowed": not reasons,
        "reasons": tuple(reasons),
        "metrics": metrics,
        "cases": tuple(rows),
        "forbidden_exposures": tuple(forbidden_exposures),
        "evaluation_sha256": _stable({"cases": rows, "metrics": metrics}),
    }


@dataclass(frozen=True, slots=True)
class TrainingRecord:
    record_id: str
    content_sha256: str
    source_id: str
    license: str
    consent: str
    label: str
    split: str
    subject_id: str | None = None
    contains_sensitive_data: bool = False
    approved_sensitive_use: bool = False


def gate_model_dataset(
    records: Iterable[TrainingRecord],
    *,
    allowed_licenses: Iterable[str],
    minimum_records: int = 2,
) -> dict[str, object]:
    """Gate model metadata for provenance, rights, split leakage, and privacy."""
    values = tuple(records)
    allowed = {item.casefold().strip() for item in allowed_licenses if item.strip()}
    reasons = []
    if len(values) < minimum_records:
        reasons.append("minimum_record_count_not_met")
    ids = [item.record_id for item in values]
    if len(ids) != len(set(ids)):
        reasons.append("record_id_duplicate")
    content_splits: dict[str, set[str]] = {}
    subject_splits: dict[str, set[str]] = {}
    label_splits: dict[str, set[str]] = {}
    for item in values:
        if not item.record_id or not item.source_id:
            reasons.append("record_identity_missing")
        if not SHA256.fullmatch(item.content_sha256):
            reasons.append(f"content_hash_invalid:{item.record_id}")
        if item.license.casefold().strip() not in allowed:
            reasons.append(f"license_not_allowed:{item.record_id}")
        if not item.consent.strip():
            reasons.append(f"consent_or_authority_missing:{item.record_id}")
        if not item.label.strip():
            reasons.append(f"label_missing:{item.record_id}")
        if item.split not in KNOWN_SPLITS:
            reasons.append(f"split_invalid:{item.record_id}")
        if item.contains_sensitive_data and not item.approved_sensitive_use:
            reasons.append(f"sensitive_use_not_approved:{item.record_id}")
        content_splits.setdefault(item.content_sha256, set()).add(item.split)
        if item.subject_id:
            subject_splits.setdefault(item.subject_id, set()).add(item.split)
        label_splits.setdefault(item.label, set()).add(item.split)
    for digest, splits in sorted(content_splits.items()):
        if len(splits) > 1:
            reasons.append(f"content_split_leakage:{digest[:12]}")
    for subject, splits in sorted(subject_splits.items()):
        if len(splits) > 1:
            reasons.append(f"subject_split_leakage:{subject}")
    reasons = sorted(set(reasons))
    split_counts = {
        split: sum(item.split == split for item in values)
        for split in sorted(KNOWN_SPLITS)
    }
    return {
        "decision": "admitted_metadata" if not reasons else "blocked",
        "training_or_model_load_performed": False,
        "reasons": tuple(reasons),
        "record_count": len(values),
        "split_counts": split_counts,
        "label_split_coverage": {
            label: tuple(sorted(splits))
            for label, splits in sorted(label_splits.items())
        },
        "dataset_sha256": _stable([asdict(item) for item in values]),
    }


def evaluate_numeric_shift(
    baseline: Sequence[float],
    observed: Sequence[float],
    *,
    threshold: float = 0.25,
) -> dict[str, object]:
    """Robustly assess mean shift, including empty, constant, and non-finite data."""
    if threshold < 0:
        raise ValueError("shift threshold cannot be negative")
    left = tuple(map(float, baseline))
    right = tuple(map(float, observed))
    errors = []
    if not left or not right:
        errors.append("series_empty")
    if any(not math.isfinite(value) for value in (*left, *right)):
        errors.append("non_finite_value")
    score = 1.0
    if not errors:
        left_mean = sum(left) / len(left)
        right_mean = sum(right) / len(right)
        variance = sum((value - left_mean) ** 2 for value in left) / len(left)
        if variance == 0:
            score = (
                0.0
                if right_mean == left_mean
                and all(value == left_mean for value in right)
                else 1.0
            )
        else:
            score = abs(right_mean - left_mean) / math.sqrt(variance)
    drifted = bool(errors) or score > threshold
    return {
        "decision": "drifted" if drifted else "within_threshold",
        "score": round(score, 6),
        "threshold": threshold,
        "errors": tuple(errors),
    }


def validate_dimension_steps(
    steps: Iterable[Mapping[str, object]],
) -> dict[str, object]:
    """Check declared dimensional algebra without evaluating an expression."""
    findings = []
    normalized = []
    for index, raw in enumerate(steps):
        operation = str(raw.get("operation", ""))
        left = {
            str(key): int(value)
            for key, value in dict(raw.get("left", {})).items()
            if int(value)
        }
        right = {
            str(key): int(value)
            for key, value in dict(raw.get("right", {})).items()
            if int(value)
        }
        result = {
            str(key): int(value)
            for key, value in dict(raw.get("result", {})).items()
            if int(value)
        }
        if operation in {"add", "subtract"}:
            valid = left == right == result
        elif operation in {"multiply", "divide"}:
            sign = 1 if operation == "multiply" else -1
            expected = {
                dimension: left.get(dimension, 0) + sign * right.get(dimension, 0)
                for dimension in set(left) | set(right)
            }
            expected = {key: value for key, value in expected.items() if value}
            valid = expected == result
        else:
            valid = False
        normalized.append(
            {"operation": operation, "left": left, "right": right, "result": result}
        )
        if not valid:
            findings.append(
                {"step": index, "kind": "dimension_mismatch_or_unknown_operation"}
            )
    return {
        "decision": "valid" if normalized and not findings else "invalid",
        "findings": tuple(findings),
        "steps_sha256": _stable(normalized),
    }


def plan_runtime_surface_validation(
    surfaces: Iterable[Mapping[str, object]],
) -> dict[str, object]:
    """Order static-to-live validation and expose every approval boundary."""
    phases = (
        "config",
        "static",
        "unit",
        "integration",
        "contract",
        "build",
        "health",
        "logs",
        "route",
        "interaction",
        "accessibility",
        "rollback",
    )
    values = tuple(surfaces)
    errors = []
    planned = []
    for surface in values:
        surface_id = str(surface.get("id", "")).strip()
        owner = str(surface.get("owner", "")).strip()
        checks = tuple(dict.fromkeys(map(str, surface.get("checks", ()))))
        unknown = sorted(set(checks) - KNOWN_SURFACE_CHECKS)
        if not surface_id or not owner:
            errors.append(
                f"surface_identity_or_owner_missing:{surface_id or 'unknown'}"
            )
        if unknown:
            errors.append(f"unknown_checks:{surface_id}:{','.join(unknown)}")
        ordered = tuple(phase for phase in phases if phase in checks)
        planned.append(
            {
                "id": surface_id,
                "owner": owner,
                "checks": ordered,
                "live_runtime_required": bool(
                    set(ordered)
                    & {"health", "logs", "route", "interaction", "accessibility"}
                ),
                "approval_required": bool(surface.get("mutating"))
                or "build" in ordered,
            }
        )
    return {
        "decision": "planned" if values and not errors else "blocked",
        "errors": tuple(sorted(errors)),
        "surfaces": tuple(planned),
        "execution_performed": False,
        "plan_sha256": _stable(planned),
    }

def compare_contract_surfaces(
    providers: Iterable[ContractSurface],
    consumers: Iterable[ContractSurface],
) -> dict[str, object]:
    """Compare provider/consumer shapes, ownership, routes, and permissions."""
    provider_values = tuple(providers)
    consumer_values = tuple(consumers)
    provider_ids = [item.contract_id for item in provider_values]
    consumer_ids = [item.contract_id for item in consumer_values]
    if len(provider_ids) != len(set(provider_ids)) or len(consumer_ids) != len(
        set(consumer_ids)
    ):
        raise ValueError("contract IDs must be unique within each side")
    provider_map = {item.contract_id: item for item in provider_values}
    findings: list[dict[str, object]] = []
    for consumer in consumer_values:
        provider = provider_map.get(consumer.contract_id)
        if provider is None:
            findings.append(
                {
                    "contract_id": consumer.contract_id,
                    "kind": "provider_missing",
                    "severity": "high",
                }
            )
            continue
        if not provider.owner.strip():
            findings.append(
                {
                    "contract_id": consumer.contract_id,
                    "kind": "canonical_owner_missing",
                    "severity": "high",
                }
            )
        for field, left, right in (
            ("method", provider.method.upper(), consumer.method.upper()),
            ("route", provider.route, consumer.route),
            ("version", provider.version, consumer.version),
        ):
            if left != right:
                findings.append(
                    {
                        "contract_id": consumer.contract_id,
                        "kind": f"{field}_mismatch",
                        "severity": "high",
                        "provider": left,
                        "consumer": right,
                    }
                )
        missing = sorted(set(consumer.required_fields) - set(provider.fields))
        for field in missing:
            findings.append(
                {
                    "contract_id": consumer.contract_id,
                    "kind": "required_field_missing",
                    "field": field,
                    "severity": "high",
                }
            )
        for field in sorted(set(consumer.required_fields) & set(provider.fields)):
            expected = consumer.fields.get(field)
            actual = provider.fields.get(field)
            if expected and actual != expected:
                findings.append(
                    {
                        "contract_id": consumer.contract_id,
                        "kind": "field_type_mismatch",
                        "field": field,
                        "provider": actual,
                        "consumer": expected,
                        "severity": "high",
                    }
                )
        provider_scopes = set(provider.authorization_scopes)
        consumer_scopes = set(consumer.authorization_scopes)
        for scope in sorted(consumer_scopes - provider_scopes):
            findings.append(
                {
                    "contract_id": consumer.contract_id,
                    "kind": "provider_scope_missing",
                    "scope": scope,
                    "severity": "high",
                }
            )
        for scope in sorted(provider_scopes - consumer_scopes):
            findings.append(
                {
                    "contract_id": consumer.contract_id,
                    "kind": "consumer_scope_unmodeled",
                    "scope": scope,
                    "severity": "medium",
                }
            )
    unconsumed = tuple(sorted(set(provider_ids) - set(consumer_ids)))
    return {
        "decision": "compatible" if not findings else "incompatible",
        "findings": tuple(findings),
        "unconsumed_provider_contracts": unconsumed,
        "provider_sha256": _stable([asdict(item) for item in provider_values]),
        "consumer_sha256": _stable([asdict(item) for item in consumer_values]),
        "source_code_executed": False,
    }

def gate_model_dataset(
    records: Iterable[TrainingRecord],
    *,
    allowed_licenses: Iterable[str],
    minimum_records: int = 2,
) -> dict[str, object]:
    """Gate model metadata for provenance, rights, split leakage, and privacy."""
    values = tuple(records)
    allowed = {item.casefold().strip() for item in allowed_licenses if item.strip()}
    reasons = []
    if len(values) < minimum_records:
        reasons.append("minimum_record_count_not_met")
    ids = [item.record_id for item in values]
    if len(ids) != len(set(ids)):
        reasons.append("record_id_duplicate")
    content_splits: dict[str, set[str]] = {}
    subject_splits: dict[str, set[str]] = {}
    label_splits: dict[str, set[str]] = {}
    for item in values:
        if not item.record_id or not item.source_id:
            reasons.append("record_identity_missing")
        if not SHA256.fullmatch(item.content_sha256):
            reasons.append(f"content_hash_invalid:{item.record_id}")
        if item.license.casefold().strip() not in allowed:
            reasons.append(f"license_not_allowed:{item.record_id}")
        if not item.consent.strip():
            reasons.append(f"consent_or_authority_missing:{item.record_id}")
        if not item.label.strip():
            reasons.append(f"label_missing:{item.record_id}")
        if item.split not in KNOWN_SPLITS:
            reasons.append(f"split_invalid:{item.record_id}")
        if item.contains_sensitive_data and not item.approved_sensitive_use:
            reasons.append(f"sensitive_use_not_approved:{item.record_id}")
        content_splits.setdefault(item.content_sha256, set()).add(item.split)
        if item.subject_id:
            subject_splits.setdefault(item.subject_id, set()).add(item.split)
        label_splits.setdefault(item.label, set()).add(item.split)
    for digest, splits in sorted(content_splits.items()):
        if len(splits) > 1:
            reasons.append(f"content_split_leakage:{digest[:12]}")
    for subject, splits in sorted(subject_splits.items()):
        if len(splits) > 1:
            reasons.append(f"subject_split_leakage:{subject}")
    reasons = sorted(set(reasons))
    split_counts = {
        split: sum(item.split == split for item in values)
        for split in sorted(KNOWN_SPLITS)
    }
    return {
        "decision": "admitted_metadata" if not reasons else "blocked",
        "training_or_model_load_performed": False,
        "reasons": tuple(reasons),
        "record_count": len(values),
        "split_counts": split_counts,
        "label_split_coverage": {
            label: tuple(sorted(splits))
            for label, splits in sorted(label_splits.items())
        },
        "dataset_sha256": _stable([asdict(item) for item in values]),
    }

def validate_dimension_steps(
    steps: Iterable[Mapping[str, object]],
) -> dict[str, object]:
    """Check declared dimensional algebra without evaluating an expression."""
    findings = []
    normalized = []
    for index, raw in enumerate(steps):
        operation = str(raw.get("operation", ""))
        left = {
            str(key): int(value)
            for key, value in dict(raw.get("left", {})).items()
            if int(value)
        }
        right = {
            str(key): int(value)
            for key, value in dict(raw.get("right", {})).items()
            if int(value)
        }
        result = {
            str(key): int(value)
            for key, value in dict(raw.get("result", {})).items()
            if int(value)
        }
        if operation in {"add", "subtract"}:
            valid = left == right == result
        elif operation in {"multiply", "divide"}:
            sign = 1 if operation == "multiply" else -1
            expected = {
                dimension: left.get(dimension, 0) + sign * right.get(dimension, 0)
                for dimension in set(left) | set(right)
            }
            expected = {key: value for key, value in expected.items() if value}
            valid = expected == result
        else:
            valid = False
        normalized.append(
            {"operation": operation, "left": left, "right": right, "result": result}
        )
        if not valid:
            findings.append(
                {"step": index, "kind": "dimension_mismatch_or_unknown_operation"}
            )
    return {
        "decision": "valid" if normalized and not findings else "invalid",
        "findings": tuple(findings),
        "steps_sha256": _stable(normalized),
    }

def export_foundry_candidate(
    bundle: FoundryBundle, skill_id: str
) -> FoundryCandidateSkill:
    certification = certify_foundry_bundle(bundle)
    if certification["decision"] != "certified_candidate":
        raise ValueError("only a certified Foundry candidate may enter Studio intake")
    matches = [skill for skill in bundle.skills if skill.skill_id == skill_id]
    if len(matches) != 1:
        raise ValueError("exactly one Foundry skill must match the requested identity")
    skill: CandidateSkill = matches[0]
    by_id = {str(source.get("source_id")): source for source in bundle.sources}
    lineage = tuple(by_id[reference] for reference in skill.references if reference in by_id)
    formulas = tuple(
        {
            "calculation_id": item.calculation_id,
            "expression": item.expression,
            "normalized_dimension": dict(item.normalized_dimension),
            "formula_engine_revision": item.formula_engine_revision,
        }
        for item in bundle.calculations
    )
    unsigned = FoundryCandidateSkill(
        SCHEMA_VERSION,
        bundle.bundle_id,
        skill.skill_id,
        skill.purpose,
        lineage,
        tuple(skill.dependencies) or ("source-derived-procedure",),
        formulas,
        {
            "confidence": skill.confidence,
            "failure_cases": skill.failure_cases,
        },
        {
            "inputs": skill.inputs,
            "outputs": skill.outputs,
            "triggers": skill.triggers,
            "examples": skill.examples,
        },
        (),
        skill.tests,
        ("runtime_effects_not_declared",),
        (),
        "",
        {},
    )
    candidate_sha256 = _digest(_candidate_payload(unsigned))
    signature = {
        "algorithm": "sha256-domain-v1",
        "signed_by": "runtime.knowledge_foundry",
        "value": hashlib.sha256(
            b"px.foundry-candidate/1.0\0" + candidate_sha256.encode("ascii")
        ).hexdigest(),
    }
    result = FoundryCandidateSkill(
        **{
            **asdict(unsigned),
            "candidate_sha256": candidate_sha256,
            "lineage_signature": signature,
        }
    )
    validate_foundry_candidate(result)
    return result

def validate_foundry_candidate(candidate: FoundryCandidateSkill) -> None:
    if candidate.schema_version != SCHEMA_VERSION:
        raise ValueError("unsupported Foundry candidate schema")
    if candidate.authority_state != "foundry_candidate_only":
        raise PermissionError("Foundry candidate cannot grant canonical authority")
    if not candidate.skill_id or not candidate.tests or not candidate.source_lineage:
        raise ValueError("Foundry candidate contract is incomplete")
    for source in candidate.source_lineage:
        if not SHA256.fullmatch(str(source.get("sha256", ""))):
            raise ValueError("Foundry candidate source hash is missing or invalid")
        citation = source.get("citation")
        if not isinstance(citation, str) or not citation.strip():
            raise ValueError("Foundry candidate source citation is required")
    expected = _digest(_candidate_payload(candidate))
    if candidate.candidate_sha256 != expected:
        raise PermissionError("Foundry candidate hash mismatch")
    signature = candidate.lineage_signature
    if (
        signature.get("algorithm") != "sha256-domain-v1"
        or signature.get("signed_by") != "runtime.knowledge_foundry"
        or signature.get("value")
        != hashlib.sha256(
            b"px.foundry-candidate/1.0\0" + expected.encode("ascii")
        ).hexdigest()
    ):
        raise PermissionError("Foundry candidate lineage signature mismatch")

def validate_full_repair_ledger(
    root: Path,
    *,
    require_all_passed: bool = False,
    allowed_pending: frozenset[str] = frozenset(),
) -> dict[str, Any]:
    root = root.resolve()
    path = root / "registry/full_repair_ledger.json"
    errors: list[str] = []
    try:
        ledger = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError, json.JSONDecodeError) as error:
        return {"valid": False, "errors": [f"cannot load full-repair ledger: {error}"]}
    cards = ledger.get("cards")
    if not isinstance(cards, list):
        return {"valid": False, "errors": ["full-repair cards must be a list"]}
    identifiers = [str(item.get("id", "")) for item in cards if isinstance(item, dict)]
    if set(identifiers) != EXPECTED_IDS or len(identifiers) != len(EXPECTED_IDS):
        errors.append(
            "full-repair card denominator must be exactly PC-001 through PC-042"
        )
    if ledger.get("card_count") != len(cards):
        errors.append("full-repair card_count does not match cards")
    known = set(identifiers)
    allowed = set(map(str, ledger.get("allowed_statuses", ())))
    for card in cards:
        if not isinstance(card, dict):
            errors.append("full-repair card is not an object")
            continue
        identifier = str(card.get("id", ""))
        status = str(card.get("status", ""))
        if status not in allowed:
            errors.append(f"{identifier}: invalid status {status}")
        if (
            require_all_passed
            and status != "passed"
            and identifier not in allowed_pending
        ):
            errors.append(f"{identifier}: remains {status}")
        dependencies = card.get("dependencies")
        if not isinstance(dependencies, list) or any(
            item not in known or item == identifier for item in dependencies
        ):
            errors.append(f"{identifier}: malformed dependency set")
        for field in ("owners", "tests"):
            values = card.get(field)
            if not isinstance(values, list) or not values:
                errors.append(f"{identifier}: {field} must be nonempty")
                continue
            for relative in values:
                candidate = (root / str(relative)).resolve()
                if candidate != root and root not in candidate.parents:
                    errors.append(
                        f"{identifier}: {field} path escapes root: {relative}"
                    )
                elif not candidate.exists():
                    errors.append(f"{identifier}: {field} path is missing: {relative}")
        if status == "passed":
            receipts = card.get("receipts")
            if not isinstance(receipts, list) or not receipts:
                errors.append(f"{identifier}: passed card requires executed receipts")
    return {
        "schema_version": "1.0",
        "valid": not errors,
        "card_count": len(cards),
        "passed": sum(
            item.get("status") == "passed" for item in cards if isinstance(item, dict)
        ),
        "in_progress": sum(
            item.get("status") == "in_progress"
            for item in cards
            if isinstance(item, dict)
        ),
        "open": sum(
            item.get("status") == "open" for item in cards if isinstance(item, dict)
        ),
        "allowed_pending": sorted(allowed_pending),
        "errors": errors,
    }

