def find_io_paths(
    records: Iterable[Mapping[str, object]],
    source_type: str,
    target_type: str,
    *,
    limit: int = 3,
) -> tuple[tuple[str, ...], ...]:
    """Return deterministic, shortest capability paths from one type to another."""
    if not source_type or not target_type or limit < 1:
        raise ValueError("source_type, target_type, and positive limit are required")
    contracts = _contracts(records)
    available: dict[str, set[str]] = {source_type: {"$input"}}
    queue: deque[tuple[str, tuple[str, ...]]] = deque([(source_type, ())])
    paths: list[tuple[str, ...]] = []
    while queue and len(paths) < limit:
        current, path = queue.popleft()
        if current == target_type and path:
            paths.append(path)
            continue
        for capability_id, contract in sorted(contracts.items()):
            consumes = set(
                value
                for value in contract.get("consumes", ())
                if isinstance(value, str)
            )
            provides = sorted(
                value
                for value in contract.get("provides", ())
                if isinstance(value, str)
            )
            if current not in consumes or capability_id in path:
                continue
            for produced in provides:
                candidate = path + (capability_id,)
                known = available.setdefault(produced, set())
                signature = "|".join(candidate)
                if signature in known:
                    continue
                known.add(signature)
                queue.append((produced, candidate))
    return tuple(sorted(paths, key=lambda path: (len(path), path)))

def validate_orchestration(
    spec: Mapping[str, object], contracts: Iterable[Mapping[str, object]]
) -> tuple[str, ...]:
    """Validate a declarative DAG before it can be admitted to a workflow registry."""
    known = _contracts(contracts)
    errors: list[str] = []
    for field in (
        "id",
        "version",
        "status",
        "inputs",
        "outputs",
        "steps",
        "parallelism",
        "stop_conditions",
    ):
        if field not in spec:
            errors.append(f"missing orchestration field: {field}")
    steps = spec.get("steps", ())
    if not isinstance(steps, list):
        return tuple(errors + ["steps must be a list"])
    ids: set[str] = set()
    by_id: dict[str, Mapping[str, object]] = {}
    for step in steps:
        if not isinstance(step, Mapping):
            errors.append("step must be an object")
            continue
        step_id = step.get("id")
        capability = step.get("capability")
        if not isinstance(step_id, str) or not step_id:
            errors.append("step id must be a non-empty string")
            continue
        if step_id in ids:
            errors.append(f"duplicate step id: {step_id}")
            continue
        ids.add(step_id)
        by_id[step_id] = step
        if not isinstance(capability, str) or capability not in known:
            errors.append(f"{step_id}: unknown capability {capability}")
            continue
        declared = set(known[capability].get("effects", ()))
        requested = set(step.get("effects", declared))
        unknown = requested - KNOWN_EFFECTS
        if unknown:
            errors.append(f"{step_id}: unknown effects: {', '.join(sorted(unknown))}")
        if not requested <= declared:
            errors.append(f"{step_id}: effects exceed capability declaration")
    for step_id, step in sorted(by_id.items()):
        for dependency in step.get("depends_on", ()):
            if dependency not in ids:
                errors.append(f"{step_id}: unknown dependency step {dependency}")
        for dependency in step.get("optional_depends_on", ()):
            if dependency in ids and dependency == step_id:
                errors.append(f"{step_id}: optional dependency cannot reference itself")
    # Detect cycles with a deterministic depth-first traversal.
    visiting: set[str] = set()
    visited: set[str] = set()

    def visit(step_id: str) -> None:
        if step_id in visiting:
            errors.append(f"orchestration cycle includes {step_id}")
            return
        if step_id in visited:
            return
        visiting.add(step_id)
        dependencies = list(by_id[step_id].get("depends_on", ())) + [
            value
            for value in by_id[step_id].get("optional_depends_on", ())
            if value in by_id
        ]
        for dependency in sorted(dependencies):
            if dependency in by_id:
                visit(dependency)
        visiting.remove(step_id)
        visited.add(step_id)

    for step_id in sorted(by_id):
        visit(step_id)
    selected = {
        str(step.get("capability"))
        for step in by_id.values()
        if isinstance(step.get("capability"), str)
    }
    for capability_id in sorted(selected):
        for conflict in known.get(capability_id, {}).get("conflicts", ()):
            if conflict in selected:
                errors.append(
                    f"effect conflict: {capability_id} conflicts with {conflict}"
                )
    parallelism = spec.get("parallelism", {})
    if (
        not isinstance(parallelism, Mapping)
        or not isinstance(parallelism.get("max_agents"), int)
        or parallelism["max_agents"] < 1
    ):
        errors.append("parallelism.max_agents must be a positive integer")
    resource = spec.get("resource_budget", {})
    if resource and (
        not isinstance(resource, Mapping)
        or not isinstance(resource.get("max_tool_calls"), int)
        or resource["max_tool_calls"] < 0
    ):
        errors.append("resource_budget.max_tool_calls must be a non-negative integer")
    if isinstance(parallelism, Mapping) and parallelism.get("max_agents", 1) > 1:
        serial_steps = [
            step_id
            for step_id, step in by_id.items()
            if set(step.get("effects", ())) & SERIAL_EFFECTS
        ]
        if len(serial_steps) > 1:
            errors.append(
                "effect conflict: serial effects require an explicit serial dependency chain"
            )
    return tuple(sorted(set(errors)))

def _benchmark_is_current(
    benchmark: BenchmarkEvidence, workload: WorkloadProfile, policy: RoutingPolicy
) -> bool:
    try:
        measured = datetime.fromisoformat(benchmark.measured_at.replace("Z", "+00:00"))
        if measured.tzinfo is None:
            return False
        age = datetime.now(timezone.utc) - measured.astimezone(timezone.utc)
    except (TypeError, ValueError):
        return False
    if age < timedelta(0) or age > timedelta(seconds=policy.maximum_benchmark_age_seconds):
        return False
    if policy.require_workload_fingerprint:
        return benchmark.workload_fingerprint == workload.fingerprint
    return benchmark.workload_fingerprint in {None, workload.fingerprint}

def _probe_psutil_telemetry(
    sampled_at: str,
) -> tuple[list[dict[str, object]], dict[str, object]]:
    provider = {"id": "psutil", "available": False, "error": None}
    try:
        psutil = importlib.import_module("psutil")
    except Exception as error:
        provider["error"] = f"psutil unavailable: {type(error).__name__}"
        return [], provider
    temperatures = getattr(psutil, "sensors_temperatures", None)
    if not callable(temperatures):
        provider["error"] = "temperature API unavailable on this host"
        return [], provider
    try:
        groups = temperatures(fahrenheit=False) or {}
    except Exception as error:
        provider["error"] = f"temperature probe failed: {type(error).__name__}: {error}"
        return [], provider
    sensors: list[dict[str, object]] = []
    for group, entries in sorted(groups.items()):
        kind = "cpu" if any(token in group.casefold() for token in ("cpu", "coretemp", "k10temp")) else "thermal"
        for index, entry in enumerate(entries):
            current = getattr(entry, "current", None)
            value = float(current) if isinstance(current, (int, float)) else None
            label = str(getattr(entry, "label", "") or f"{group} {index + 1}")
            sensors.append(
                _sensor(
                    sensor_id=f"{kind}:{group}:{index}:temperature",
                    kind=kind,
                    device=group,
                    label=label,
                    metric="temperature",
                    value=value,
                    unit="celsius",
                    source="psutil",
                    sampled_at=sampled_at,
                    available=value is not None,
                    error=None if value is not None else "metric unavailable",
                )
            )
    provider["available"] = bool(sensors)
    if not sensors:
        provider["error"] = "no temperature sensors exposed by the operating system"
    return sensors, provider

def route_workload(
    workload: WorkloadProfile,
    hardware: HardwareProfile,
    *,
    policy: RoutingPolicy = RoutingPolicy(),
    benchmark: BenchmarkEvidence | None = None,
    requested_device: Literal["auto", "cpu", "cuda"] = "auto",
) -> RoutingDecision:
    policy.validate()
    checks = ["workload_classified", "fallback_declared"]
    if workload.item_count < 0 or workload.total_bytes < 0:
        raise ValueError("workload sizes cannot be negative")
    if requested_device not in {"auto", "cpu", "cuda"}:
        raise ValueError("requested device must be auto, cpu, or cuda")
    if workload.kind in CPU_AUTHORITATIVE:
        return RoutingDecision(
            Device.CPU,
            f"{workload.kind.value} is CPU/operating-system authoritative",
            required_checks=tuple(checks),
            deterministic_required=workload.deterministic_required,
        )
    if requested_device == "cpu":
        return RoutingDecision(
            Device.CPU,
            "CPU execution was explicitly requested",
            required_checks=tuple(checks),
            deterministic_required=workload.deterministic_required,
        )
    checks.append("cuda_available")
    if not hardware.cuda_available:
        return RoutingDecision(
            Device.CPU,
            "CUDA is unavailable; using declared CPU fallback",
            required_checks=tuple(checks),
            deterministic_required=workload.deterministic_required,
        )
    checks.append("cuda_executor_available")
    if not hardware.cuda_executor_available:
        return RoutingDecision(
            Device.CPU,
            "CUDA hardware is visible, but no compatible CUDA execution backend is ready",
            required_checks=tuple(checks),
            deterministic_required=workload.deterministic_required,
        )
    if hardware.free_vram_bytes < policy.minimum_free_vram_bytes:
        return RoutingDecision(
            Device.CPU,
            "free VRAM is below the configured reserve",
            required_checks=tuple(checks + ["free_vram_sufficient"]),
            deterministic_required=workload.deterministic_required,
        )
    estimated = workload.estimated_device_bytes or workload.total_bytes
    vram_limit = int(hardware.free_vram_bytes * policy.max_fraction_of_free_vram)
    checks.append("free_vram_sufficient")
    if estimated > vram_limit:
        return RoutingDecision(
            Device.CPU,
            "estimated device memory exceeds the configured free-VRAM fraction",
            required_checks=tuple(checks),
            deterministic_required=workload.deterministic_required,
        )
    if not workload.batchable:
        return RoutingDecision(
            Device.CPU,
            "workload is not batchable enough to amortize device overhead",
            required_checks=tuple(checks),
            deterministic_required=workload.deterministic_required,
        )
    if workload.item_count < policy.minimum_gpu_items and workload.total_bytes < policy.minimum_gpu_bytes:
        return RoutingDecision(
            Device.CPU,
            "workload is below configured GPU size thresholds",
            required_checks=tuple(checks),
            deterministic_required=workload.deterministic_required,
        )
    if workload.kind not in GPU_SUITABLE | CONDITIONAL:
        return RoutingDecision(
            Device.CPU,
            "no compatible GPU implementation is declared for this workload",
            required_checks=tuple(checks),
            deterministic_required=workload.deterministic_required,
        )
    checks.extend(("benchmark_current", "correctness_validated"))
    benchmark_valid = bool(
        benchmark
        and benchmark.operation_id == workload.operation_id
        and benchmark.hardware_fingerprint == hardware.fingerprint
        and _benchmark_is_current(benchmark, workload, policy)
        and benchmark.correctness_passed
        and benchmark.peak_vram_bytes <= vram_limit
        and benchmark.speedup >= policy.minimum_gpu_speedup
    )
    if policy.require_benchmark and requested_device == "auto" and not benchmark_valid:
        return RoutingDecision(
            Device.CPU,
            "current end-to-end benchmark and correctness evidence do not justify GPU routing",
            required_checks=tuple(checks),
            benchmark_speedup=benchmark.speedup if benchmark else None,
            deterministic_required=workload.deterministic_required,
        )
    reason = (
        "validated end-to-end benchmark exceeds the GPU speedup threshold"
        if benchmark_valid
        else "CUDA was explicitly requested and compatibility/resource checks passed"
    )
    return RoutingDecision(
        Device.CUDA,
        reason,
        batch_size=policy.default_batch_size,
        fallback_device=Device.CPU,
        required_checks=tuple(checks),
        benchmark_speedup=benchmark.speedup if benchmark else None,
        deterministic_required=workload.deterministic_required,
        executor_backend=next(
            (name for name in hardware.available_execution_backends if name != "onnx-directml"),
            None,
        ),
        device_index=hardware.selected_cuda_device_index,
        process_parallelism=hardware.gpu_process_parallelism,
    )

def _derive_state(
    lifecycle: Mapping[str, bool],
    *,
    stale: bool,
    last_success: str | None,
    last_failure: Mapping[str, str] | None,
    degradation: Sequence[str],
    blockers: Sequence[str],
) -> str:
    if blockers:
        return "blocked"
    if stale:
        return "stale"
    unresolved_failure = bool(
        last_failure
        and (
            last_success is None
            or _parse_datetime(last_failure["at"], "last_failure.at")
            > _parse_datetime(last_success, "last_success")
        )
    )
    if degradation or unresolved_failure:
        return "degraded"
    if lifecycle["ready"]:
        return "healthy"
    if any(lifecycle.values()) or last_success is not None or last_failure is not None:
        return "degraded"
    return "unknown"

def _validate_lifecycle(value: object) -> dict[str, bool]:
    if not isinstance(value, Mapping) or set(value) != set(LIFECYCLE_DIMENSIONS):
        raise HealthModelError(
            "lifecycle must contain exactly configured, detected, connected, "
            "authoritative, and ready"
        )
    lifecycle = dict(value)
    if any(type(lifecycle[field]) is not bool for field in LIFECYCLE_DIMENSIONS):
        raise HealthModelError("lifecycle values must be booleans")
    if lifecycle["connected"] and not lifecycle["detected"]:
        raise HealthModelError("connected health requires detected=true")
    if lifecycle["authoritative"] and not lifecycle["connected"]:
        raise HealthModelError("authoritative health requires connected=true")
    if lifecycle["ready"] and not all(
        lifecycle[field] for field in LIFECYCLE_DIMENSIONS[:-1]
    ):
        raise HealthModelError("ready health requires every prior lifecycle fact")
    return lifecycle

def project_health_for_extension(
    root: Path, report: Mapping[str, object]
) -> dict[str, Any]:
    """Create the read-only extension input; consumers cannot strengthen claims."""
    required = {
        "schema_version",
        "valid",
        "evaluated_at",
        "overall_state",
        "summary",
        "records",
    }
    if (
        set(report) != required
        or report.get("schema_version") != "px.health-report/1.0"
    ):
        raise HealthModelError(
            "extension projection requires a canonical health report"
        )
    validation = validate_health_report(root, report)
    if not validation["valid"]:
        raise HealthModelError(
            f"extension projection rejected health report: {validation['errors']}"
        )
    return {
        "schema_version": "px.extension-health-input/1.0",
        "source_schema_version": report["schema_version"],
        "read_only": True,
        "evaluated_at": report["evaluated_at"],
        "overall_state": report["overall_state"],
        "summary": dict(report["summary"]),
        "records": deepcopy(report["records"]),
    }

def validate_health_report(root: Path, report: Mapping[str, object]) -> dict[str, Any]:
    """Re-derive report semantics so a consumer cannot strengthen health claims."""
    root = root.resolve()
    errors: list[str] = []
    try:
        validate_instance(dict(report), root / REPORT_SCHEMA)
        registry = _load_registry(root)
    except (ContractValidationError, HealthModelError, OSError, ValueError) as error:
        return {
            "schema_version": "px.health-report-validation/1.0",
            "valid": False,
            "errors": [str(error)],
        }
    evaluation = _parse_datetime(report["evaluated_at"], "evaluated_at")
    records = report["records"]
    assert isinstance(records, list)
    by_surface = {item["surface_id"]: item for item in registry["surfaces"]}
    identifiers = [record["surface_id"] for record in records]
    if len(identifiers) != len(set(identifiers)):
        errors.append("report contains duplicate health surfaces")
    if set(identifiers) != set(by_surface):
        errors.append("report does not cover the canonical health surface set")
    counts: Counter[str] = Counter()
    for record in records:
        surface = by_surface.get(record["surface_id"])
        if surface is None:
            continue
        for field in ("domain", "authority", "remediation"):
            if record[field] != surface[field]:
                errors.append(f"{record['surface_id']}: canonical {field} mismatch")
        freshness = record["freshness"]
        if freshness["ttl_seconds"] != surface["ttl_seconds"]:
            errors.append(f"{record['surface_id']}: canonical TTL mismatch")
        if freshness["evaluated_at"] != _format_datetime(evaluation):
            errors.append(f"{record['surface_id']}: evaluation time mismatch")
        raw_observed = freshness["observed_at"]
        observed = (
            None
            if raw_observed is None
            else _parse_datetime(raw_observed, "freshness.observed_at")
        )
        if observed is not None and observed > evaluation:
            errors.append(f"{record['surface_id']}: observation is in the future")
        try:
            _validate_lifecycle(record["lifecycle"])
            _nullable_event_time(
                record["last_success"], "last_success", evaluation, observed
            )
            _last_failure(record["last_failure"], evaluation, observed)
        except HealthModelError as error:
            errors.append(f"{record['surface_id']}: {error}")
        has_facts = any(record["lifecycle"].values()) or bool(
            record["degradation"]
            or record["blockers"]
            or record["last_success"]
            or record["last_failure"]
        )
        if observed is None and has_facts:
            errors.append(f"{record['surface_id']}: facts require an observation")
        expected_age = (
            None
            if observed is None
            else round(max(0.0, (evaluation - observed).total_seconds()), 6)
        )
        expected_stale = (
            expected_age is not None and expected_age > surface["ttl_seconds"]
        )
        if freshness["age_seconds"] != expected_age:
            errors.append(f"{record['surface_id']}: age does not match timestamps")
        if freshness["stale"] is not expected_stale:
            errors.append(f"{record['surface_id']}: stale flag conflicts with TTL")
        expected_state = _derive_state(
            record["lifecycle"],
            stale=expected_stale,
            last_success=record["last_success"],
            last_failure=record["last_failure"],
            degradation=record["degradation"],
            blockers=record["blockers"],
        )
        if record["state"] != expected_state:
            errors.append(f"{record['surface_id']}: state conflicts with facts")
        counts[record["state"]] += 1
    expected_summary = {state: counts[state] for state in STATES}
    if report["summary"] != expected_summary:
        errors.append("report summary conflicts with records")
    expected_overall = next(
        (state for state in STATE_PRECEDENCE if counts[state]), "unknown"
    )
    if report["overall_state"] != expected_overall:
        errors.append("overall state conflicts with records")
    return {
        "schema_version": "px.health-report-validation/1.0",
        "valid": not errors,
        "errors": errors,
    }

def _latest_substantive_session(logs_root: Path) -> tuple[Path, Path, Path] | None:
    if not logs_root.is_dir():
        return None
    for session in sorted(
        (path for path in logs_root.iterdir() if path.is_dir()),
        key=lambda path: path.name,
        reverse=True,
    )[:64]:
        candidates = sorted(
            session.glob("window*/exthost/openai.chatgpt/Codex.log"),
            key=lambda path: path.stat().st_mtime_ns,
            reverse=True,
        )
        for codex in candidates:
            exthost = codex.parents[1] / "exthost.log"
            if exthost.is_file():
                return session, exthost, codex
    return None

