def skill_index_integrity(root: Path) -> dict[str, Any]:
    """Compare all current native skill projections from the same record set."""
    root = root.resolve()
    index = json.loads((root / ".px" / "skill-index.json").read_text(encoding="utf-8"))
    validation = validate_skill_index(index, require_derived=True)
    native_ids = {
        str(row["id"])
        for row in index["records"]
        if row.get("domain") == "px-standard" and row.get("native")
    }
    catalog = tomllib.loads(
        (root / "registry" / "skill_catalog.toml").read_text(encoding="utf-8")
    )
    catalog_ids = {str(row["id"]) for row in catalog.get("skills", ())}
    directory_ids = {
        path.name for path in (root / ".px" / "skills").iterdir() if path.is_dir()
    }
    projection_ids = {
        path.stem for path in (root / "registry" / "skill_packages").glob("*.json")
    }
    equal = native_ids == catalog_ids == directory_ids == projection_ids
    return {
        "schema_version": "px.skill-index-integrity/1.0",
        "valid": bool(validation.get("valid")) and equal,
        "revision": validation["revision"],
        "declared_record_count": index.get("record_count"),
        "derived_domain_counts": validation["counts"],
        "projections": {
            "native_index": len(native_ids),
            "catalog": len(catalog_ids),
            "package_directories": len(directory_ids),
            "package_records": len(projection_ids),
        },
        "differences": {
            "catalog_only": sorted(catalog_ids - native_ids),
            "index_only": sorted(native_ids - catalog_ids),
            "directory_only": sorted(directory_ids - native_ids),
            "package_record_only": sorted(projection_ids - native_ids),
        },
        "publication_rule": "records, counts, revision, catalog, package directories, and package records must agree before publication",
    }

def startup_log_revision(logs_root: Path | None = None) -> dict[str, object]:
    """Return compact metadata that invalidates cached attribution on log change."""
    resolved_logs = logs_root
    if resolved_logs is None:
        appdata = os.environ.get("APPDATA")
        if not appdata:
            return {"available": False, "reason": "APPDATA unavailable"}
        resolved_logs = Path(appdata) / "Code" / "logs"
    selected = _latest_substantive_session(resolved_logs.resolve())
    if selected is None:
        return {"available": False, "reason": "no substantive session"}
    session, exthost, codex = selected
    return {
        "available": True,
        "session": session.name,
        "exthost": {"size": exthost.stat().st_size, "mtime_ns": exthost.stat().st_mtime_ns},
        "codex": {"size": codex.stat().st_size, "mtime_ns": codex.stat().st_mtime_ns},
    }

def instrument_operation(
    root: Path, base: Mapping[str, object], emit: Emitter
) -> Iterator[None]:
    """Emit started then completed/failed without capturing exception content."""
    emit(lifecycle_event(root, base, lifecycle="started", result="pending"))
    try:
        yield
    except BaseException:
        emit(lifecycle_event(root, base, lifecycle="failed", result="failure"))
        raise
    else:
        emit(lifecycle_event(root, base, lifecycle="completed", result="success"))

def inspect_existing_project(
    project: Path,
    *,
    max_files: int = 10000,
    max_depth: int = 64,
    max_bytes: int = 256 * 1024 * 1024,
) -> dict[str, object]:
    root = project.resolve()
    if not root.is_dir():
        raise ValueError("existing project must be a directory")
    if max_files < 1:
        raise ValueError("max_files must be positive")
    # One extra accepted entry makes the public truncation state unambiguous.
    walk = bounded_walk(
        root,
        limits=WalkLimits(
            max_files=max_files + 1, max_depth=max_depth, max_bytes=max_bytes
        ),
        symlink_policy="reject",
        exclude=lambda relative: any(
            part.casefold() in EXCLUDES for part in Path(relative).parts
        ),
    )
    entries = list(walk.files)
    truncated = len(entries) > max_files
    entries = entries[:max_files]
    paths = [entry.path for entry in entries]
    relatives = [path.relative_to(root).as_posix() for path in paths]
    names = {path.name.casefold() for path in paths}
    languages = Counter(
        LANGUAGES[path.suffix.casefold()]
        for path in paths
        if path.suffix.casefold() in LANGUAGES
    )
    frameworks = sorted(
        {value for name, value in FRAMEWORK_FILES.items() if name in names}
    )
    tests = [
        relative for relative in relatives if "test" in Path(relative).name.casefold()
    ]
    security = [
        relative
        for relative in relatives
        if any(
            term in relative.casefold()
            for term in ("security", "auth", "policy", "threat")
        )
    ]
    ci = [
        relative
        for relative in relatives
        if relative.startswith((".github/workflows/", ".gitlab-ci"))
        or Path(relative).name.casefold() in {"jenkinsfile", "azure-pipelines.yml"}
    ]
    owners = [
        relative
        for relative in relatives
        if Path(relative).name.casefold()
        in {
            "agents.md",
            "codeowners",
            "architecture.md",
            "package.json",
            "pyproject.toml",
        }
    ]
    inventory_records = [
        {
            "path": entry.relative,
            "size_bytes": entry.size,
            "sha256": hashlib.sha256(entry.path.read_bytes()).hexdigest(),
            "file_type": "regular",
        }
        for entry in entries
    ]
    digest = hashlib.sha256(
        json.dumps(inventory_records, sort_keys=True, separators=(",", ":")).encode()
    ).hexdigest()
    gaps = []
    if not tests:
        gaps.append("test discovery produced no candidates")
    if not security:
        gaps.append("security-policy discovery produced no candidates")
    if not ci:
        gaps.append("CI discovery produced no candidates")
    return {
        "schema_version": "1.0",
        "mode": "read_only",
        "root_name": root.name,
        "file_count": len(paths),
        "truncated": truncated,
        "inventory_sha256": digest,
        "inventory_records": inventory_records,
        "languages": dict(sorted(languages.items())),
        "frameworks": frameworks,
        "tests": tests,
        "security_assets": security,
        "ci_assets": ci,
        "canonical_owner_candidates": owners,
        "gap_matrix": gaps,
        "proposed_integrations": [
            "project-scoped metadata registry",
            "bounded validation profile",
        ],
        "minimal_patch_path": [
            "add .engineering-bootstrap metadata",
            "preserve existing owners",
            "install no tools",
        ],
    }

def _append_event(
    state_dir: Path, event: str, payload: Mapping[str, object]
) -> dict[str, object]:
    state_dir.mkdir(parents=True, exist_ok=True)
    for _ in range(8):
        sequence = len(load_events(state_dir)) + 1
        record = {
            "schema_version": "1.0",
            "sequence": sequence,
            "event": event,
            "created_utc": _timestamp(_utc_now()),
            **dict(payload),
        }
        path = state_dir / f"{sequence:06d}-{event}.json"
        try:
            with path.open("x", encoding="utf-8", newline="\n") as stream:
                json.dump(record, stream, indent=2)
                stream.write("\n")
            return record
        except FileExistsError:
            continue
    raise RuntimeError("intake event ledger is receiving concurrent writes")

def close_intake(
    source: Path,
    state_dir: Path,
    *,
    source_alias: str,
    approved_by: str,
    minimum_stability_seconds: float = 30.0,
) -> dict[str, object]:
    if not approved_by.strip():
        raise ValueError("explicit closure approver is required")
    if minimum_stability_seconds < 0:
        raise ValueError("minimum stability window cannot be negative")
    status = intake_status(state_dir)
    if status["status"] != "open" or status["source_alias"] != source_alias:
        raise ValueError("matching source intake is not open")
    snapshots = [
        event for event in load_events(state_dir) if event["event"] == "snapshot"
    ]
    if len(snapshots) < 2:
        raise ValueError("two recorded snapshots are required before closure")
    first, second = snapshots[-2:]
    left = first["snapshot"]
    right = second["snapshot"]
    elapsed = (
        datetime.fromisoformat(str(second["created_utc"]))
        - datetime.fromisoformat(str(first["created_utc"]))
    ).total_seconds()
    if (
        left["tree_sha256"] != right["tree_sha256"]
        or left["records"] != right["records"]
    ):
        raise ValueError("the two latest source snapshots are not identical")
    if elapsed < minimum_stability_seconds:
        raise ValueError("source snapshots do not satisfy the stability window")
    current = snapshot_tree(source, source_alias=source_alias)
    if (
        current["tree_sha256"] != right["tree_sha256"]
        or current["records"] != right["records"]
    ):
        raise ValueError("source changed after the accepted snapshot")
    return _append_event(
        state_dir,
        "close",
        {
            "source_alias": source_alias,
            "approved_by": approved_by,
            "minimum_stability_seconds": minimum_stability_seconds,
            "accepted_snapshot": current,
        },
    )

def load_events(state_dir: Path) -> tuple[dict[str, object], ...]:
    if not state_dir.exists():
        return ()
    if not state_dir.is_dir():
        raise ValueError("intake state path must be a directory")
    events = []
    for path in sorted(state_dir.glob("*.json")):
        event = json.loads(path.read_text(encoding="utf-8"))
        if (
            not isinstance(event, dict)
            or "event" not in event
            or "sequence" not in event
        ):
            raise ValueError(f"invalid intake event: {path.name}")
        events.append(event)
    expected = list(range(1, len(events) + 1))
    if [int(event["sequence"]) for event in events] != expected:
        raise ValueError("intake event sequence is incomplete or reordered")
    return tuple(events)

def require_closed_stable(
    source: Path, state_dir: Path, *, source_alias: str
) -> dict[str, object]:
    events = load_events(state_dir)
    status = intake_status(state_dir)
    if status["status"] != "closed" or status["source_alias"] != source_alias:
        raise ValueError("source intake is not explicitly closed")
    closure = next(event for event in reversed(events) if event["event"] == "close")
    accepted = closure["accepted_snapshot"]
    current = snapshot_tree(source, source_alias=source_alias)
    if (
        current["tree_sha256"] != accepted["tree_sha256"]
        or current["records"] != accepted["records"]
    ):
        raise ValueError(
            "closed source intake has drifted; reopen it before processing"
        )
    return current

def snapshot_tree(root: Path, *, source_alias: str) -> dict[str, object]:
    resolved = root.resolve()
    if not resolved.is_dir():
        raise ValueError("source intake root must be a directory")
    records: list[dict[str, object]] = []
    for path in sorted(
        resolved.rglob("*"), key=lambda item: item.as_posix().casefold()
    ):
        if not path.is_file():
            continue
        stat = path.stat()
        digest = hashlib.sha256(path.read_bytes()).hexdigest()
        records.append(
            {
                "path": path.relative_to(resolved).as_posix(),
                "sha256": digest,
                "bytes": stat.st_size,
                "mtime_ns": stat.st_mtime_ns,
            }
        )
    canonical = "\n".join(
        f"{item['path']}\0{item['sha256']}\0{item['bytes']}\0{item['mtime_ns']}"
        for item in records
    )
    return {
        "source_alias": source_alias,
        "captured_utc": _timestamp(_utc_now()),
        "file_count": len(records),
        "byte_count": sum(int(item["bytes"]) for item in records),
        "tree_sha256": hashlib.sha256(canonical.encode("utf-8")).hexdigest(),
        "records": records,
    }

def _overlay_target(parts: tuple[str, ...]) -> str | None:
    for index, part in enumerate(parts):
        if part.casefold() in OVERLAY_MARKERS and index + 1 < len(parts):
            return "/".join(parts[index + 1 :])
    return None


