def compare_revisions(
    *, incumbent: Mapping[str, Any], challenger: Mapping[str, Any], trials: Sequence[Mapping[str, Any]], minimum_trials: int = 6
) -> dict[str, Any]:
    for revision in (incumbent, challenger):
        if revision.get("record_type") != "frozen_revision" or not _valid_hash(revision.get("revision_sha256")):
            raise ValueError("A/B comparison requires frozen revisions")
    wins = losses = ties = 0
    evidence = []
    for trial in trials:
        if not _valid_hash(trial.get("evidence_sha256")):
            raise ValueError("every A/B trial requires hashed evidence")
        winner = str(trial.get("winner"))
        if winner == "challenger":
            wins += 1
        elif winner == "incumbent":
            losses += 1
        elif winner == "tie":
            ties += 1
        else:
            raise ValueError("trial winner must be challenger, incumbent, or tie")
        evidence.append(str(trial["evidence_sha256"]))
    gate = confidence_gate(wins=wins, losses=losses, ties=ties, minimum_trials=minimum_trials)
    return _record(
        "ab_comparison",
        {
            "incumbent_revision_sha256": incumbent["revision_sha256"],
            "challenger_revision_sha256": challenger["revision_sha256"],
            "trial_evidence_sha256": sorted(evidence),
            "gate": gate,
            "passed": gate["passed"],
            "loser_retention_required": True,
        },
    )

def validate_licensing(root: Path) -> dict[str, Any]:
    root = root.resolve()
    errors: list[str] = []
    required = sorted(REQUIRED_ROOT_FILES)
    for name in required:
        if not (root / name).is_file():
            errors.append(f"missing publication file: {name}")

    license_path = root / "LICENSE"
    if license_path.is_file():
        text = license_path.read_text(encoding="utf-8").replace("\r\n", "\n")
        markers = (
            "Apache License\n                           Version 2.0, January 2004",
            "TERMS AND CONDITIONS FOR USE, REPRODUCTION, AND DISTRIBUTION",
            "1. Definitions.",
            "9. Accepting Warranty or Additional Liability.",
            "END OF TERMS AND CONDITIONS",
            "APPENDIX: How to apply the Apache License to your work.",
        )
        if len(text) < 11_000 or any(marker not in text for marker in markers):
            errors.append(
                "LICENSE is not the complete standard Apache License 2.0 text"
            )
        if _sha256(license_path) != OFFICIAL_APACHE_2_SHA256:
            errors.append(
                "LICENSE does not byte-match the official Apache License 2.0 text"
            )

    notice_path = root / "NOTICE"
    if notice_path.is_file():
        notice = notice_path.read_text(encoding="utf-8").replace("\r\n", "\n")
        if not notice.startswith(NOTICE_TEXT):
            errors.append(
                "NOTICE attribution does not match the governed publication identity"
            )
        for relative, marker in THIRD_PARTY_LICENSES.items():
            if not (root / relative).is_file():
                errors.append(f"missing third-party license: {relative}")
            elif marker not in notice:
                errors.append(f"NOTICE is missing third-party attribution: {marker}")

    pyproject_path = root / "pyproject.toml"
    try:
        project = tomllib.loads(pyproject_path.read_text(encoding="utf-8"))["project"]
        if project.get("license") != LICENSE_ID:
            errors.append(f"pyproject project.license must be {LICENSE_ID}")
        if AUTHOR not in {str(item.get("name")) for item in project.get("authors", ())}:
            errors.append(f"pyproject authors must include {AUTHOR}")
        urls = project.get("urls", {})
        if urls.get("Repository") != REPOSITORY or urls.get("Homepage") != REPOSITORY:
            errors.append("pyproject repository ownership metadata is inconsistent")
        if set(project.get("license-files", ())) != {"LICENSE", "NOTICE"}:
            errors.append("pyproject license-files must include LICENSE and NOTICE")
    except (OSError, KeyError, tomllib.TOMLDecodeError) as error:
        errors.append(f"invalid pyproject licensing metadata: {error}")

    owned_contracts = sorted((root / "registry" / "skills").glob("*.json"))
    for path in owned_contracts:
        try:
            if (
                json.loads(path.read_text(encoding="utf-8")).get("license")
                != LICENSE_ID
            ):
                errors.append(
                    f"owned skill contract license mismatch: {path.relative_to(root).as_posix()}"
                )
        except (OSError, json.JSONDecodeError) as error:
            errors.append(
                f"invalid owned skill contract: {path.relative_to(root).as_posix()}: {error}"
            )

    readme_path = root / "README.md"
    if readme_path.is_file():
        readme = readme_path.read_text(encoding="utf-8")
        for marker in (
            "## License",
            AUTHOR,
            "doing business as Mountain-Nomad-BC",
            "Apache License, Version 2.0",
        ):
            if marker not in readme:
                errors.append(f"README licensing attribution missing: {marker}")

    conflict_files = [pyproject_path, *owned_contracts]
    for path in conflict_files:
        if not path.is_file():
            continue
        text = path.read_text(encoding="utf-8")
        for token in CONFLICTING_PROJECT_LICENSES:
            if token in text:
                errors.append(
                    f"conflicting project license token in {path.relative_to(root).as_posix()}: {token}"
                )

    policy_path = root / "policies" / "release-artifact-policy.json"
    try:
        roots = set(
            json.loads(policy_path.read_text(encoding="utf-8"))["product_root_files"]
        )
        missing_from_policy = sorted(REQUIRED_ROOT_FILES - roots)
        if missing_from_policy:
            errors.append(
                f"publication files absent from release artifact policy: {missing_from_policy}"
            )
    except (OSError, KeyError, json.JSONDecodeError) as error:
        errors.append(f"invalid release artifact policy: {error}")

    files = [
        path
        for path in (
            license_path,
            notice_path,
            pyproject_path,
            readme_path,
            policy_path,
        )
        if path.is_file()
    ]
    files.extend(path for path in owned_contracts if path.is_file())
    files.extend(
        root / relative
        for relative in THIRD_PARTY_LICENSES
        if (root / relative).is_file()
    )
    return {
        "schema_version": "1.0",
        "valid": not errors,
        "license": LICENSE_ID,
        "author": AUTHOR,
        "publisher": PUBLISHER,
        "repository": REPOSITORY,
        "checked_file_count": len(files),
        "files": [
            {"path": path.relative_to(root).as_posix(), "sha256": _sha256(path)}
            for path in sorted(files)
        ],
        "errors": errors,
    }

"""Deterministic checkpoints and evidence-gated retry decisions."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timezone
import hashlib
from typing import Iterable, Protocol


@dataclass(frozen=True, slots=True)
class Checkpoint:
    task_id: str
    sequence: int
    stage: str
    status: str
    capability_id: str | None
    evidence_ids: tuple[str, ...]
    created_at: datetime


class CheckpointSink(Protocol):
    def append(self, checkpoint: Checkpoint) -> None: ...


class MemoryCheckpointSink:
    """In-memory default: checkpoints do not silently create filesystem effects."""

    def __init__(self) -> None:
        self.records: list[Checkpoint] = []

    def append(self, checkpoint: Checkpoint) -> None:
        self.records.append(checkpoint)


@dataclass(frozen=True, slots=True)
class FailureRecord:
    task_id: str
    capability_id: str | None
    fingerprint: str
    attempt: int
    evidence_ids: tuple[str, ...]
    message: str


@dataclass(frozen=True, slots=True)
class RetryDecision:
    allowed: bool
    reason: str


def failure_fingerprint(
    capability_id: str | None, error_type: str, message: str
) -> str:
    normalized = "|".join(
        (capability_id or "none", error_type.strip(), " ".join(message.split()))
    )
    return hashlib.sha256(normalized.encode("utf-8")).hexdigest()[:16]


def decide_retry(
    previous: FailureRecord,
    *,
    candidate_attempt: int,
    evidence_ids: Iterable[str],
    max_retries: int,
    require_new_evidence: bool,
) -> RetryDecision:
    if candidate_attempt != previous.attempt + 1:
        return RetryDecision(False, "retry attempt is not sequential")
    if candidate_attempt > max_retries + 1:
        return RetryDecision(False, "retry budget exhausted")
    new_evidence = set(evidence_ids) - set(previous.evidence_ids)
    if require_new_evidence and not new_evidence:
        return RetryDecision(False, "retry requires new evidence")
    return RetryDecision(True, "retry admitted")


def make_checkpoint(
    task_id: str,
    sequence: int,
    stage: str,
    status: str,
    capability_id: str | None,
    evidence_ids: Iterable[str] = (),
) -> Checkpoint:
    return Checkpoint(
        task_id=task_id,
        sequence=sequence,
        stage=stage,
        status=status,
        capability_id=capability_id,
        evidence_ids=tuple(sorted(set(evidence_ids))),
        created_at=datetime.now(timezone.utc),
    )

def decide_retry(
    previous: FailureRecord,
    *,
    candidate_attempt: int,
    evidence_ids: Iterable[str],
    max_retries: int,
    require_new_evidence: bool,
) -> RetryDecision:
    if candidate_attempt != previous.attempt + 1:
        return RetryDecision(False, "retry attempt is not sequential")
    if candidate_attempt > max_retries + 1:
        return RetryDecision(False, "retry budget exhausted")
    new_evidence = set(evidence_ids) - set(previous.evidence_ids)
    if require_new_evidence and not new_evidence:
        return RetryDecision(False, "retry requires new evidence")
    return RetryDecision(True, "retry admitted")

"""Governed, data-free lifecycle owner for local GGUF llama.cpp servers.

Canonical model bytes remain user-owned.  Pacify-X records only stable filesystem
identity, SHA-256, bounded GGUF metadata, an immutable launch plan, and owned
process/session receipts.
"""

from __future__ import annotations

from dataclasses import asdict, dataclass
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path
import struct
import subprocess
import time
from typing import Callable, Iterable, Mapping, Sequence
from urllib.request import ProxyHandler, Request, build_opener
from uuid import uuid4

from runtime.file_lock import FileLock
from runtime.process_supervisor import ProcessSupervisor
from runtime.resource_lifecycle import ResourceManager, RunState


MAX_GGUF_METADATA_BYTES = 1_048_576
MAX_GGUF_METADATA_ITEMS = 4_096
MAX_MODEL_BYTES = 1024**4
SUPPORTED_GGUF_VERSIONS = frozenset({2, 3})
DEFAULT_ARCHITECTURES = frozenset(
    {"llama", "mistral", "qwen2", "qwen3", "gemma", "gemma2", "phi2", "phi3"}
)


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _canonical(value: object) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")


def _sha(value: object) -> str:
    return hashlib.sha256(_canonical(value)).hexdigest()


def _inside(path: Path, roots: Sequence[Path]) -> bool:
    candidate = os.path.normcase(str(path))
    for root in roots:
        try:
            if os.path.commonpath((candidate, os.path.normcase(str(root)))) == os.path.normcase(str(root)):
                return True
        except ValueError:
            continue
    return False


def _linked(path: Path, stop: Path) -> bool:
    current = path
    while True:
        try:
            stat = current.lstat()
        except OSError:
            return True
        if current.is_symlink() or bool(getattr(stat, "st_file_attributes", 0) & 0x400):
            return True
        if current == stop:
            return False
        if current.parent == current:
            return True
        current = current.parent


class _Reader:
    def __init__(self, raw: bytes) -> None:
        self.raw = raw
        self.offset = 0

    def take(self, size: int) -> bytes:
        if size < 0 or self.offset + size > len(self.raw):
            raise ValueError("GGUF metadata is truncated or exceeds the inspection bound")
        result = self.raw[self.offset : self.offset + size]
        self.offset += size
        return result

    def unpack(self, code: str) -> object:
        size = struct.calcsize("<" + code)
        return struct.unpack("<" + code, self.take(size))[0]

    def string(self) -> str:
        size = int(self.unpack("Q"))
        if size > MAX_GGUF_METADATA_BYTES:
            raise ValueError("GGUF string exceeds the inspection bound")
        try:
            return self.take(size).decode("utf-8")
        except UnicodeDecodeError as error:
            raise ValueError("GGUF metadata is not valid UTF-8") from error


_SCALARS = {0: "B", 1: "b", 2: "H", 3: "h", 4: "I", 5: "i", 6: "f", 7: "?", 10: "Q", 11: "q", 12: "d"}


def _value(reader: _Reader, kind: int, *, depth: int = 0) -> object:
    if depth > 2:
        raise ValueError("GGUF metadata nesting exceeds the inspection bound")
    if kind in _SCALARS:
        return reader.unpack(_SCALARS[kind])
    if kind == 8:
        return reader.string()
    if kind == 9:
        element_kind = int(reader.unpack("I"))
        count = int(reader.unpack("Q"))
        if count > MAX_GGUF_METADATA_ITEMS:
            raise ValueError("GGUF metadata array exceeds the inspection bound")
        return [_value(reader, element_kind, depth=depth + 1) for _ in range(count)]
    raise ValueError(f"unsupported GGUF metadata value type {kind}")


def parse_gguf_metadata(raw: bytes) -> dict[str, object]:
    """Parse only the bounded GGUF header/metadata area; tensor bytes are untouched."""
    if len(raw) > MAX_GGUF_METADATA_BYTES:
        raise ValueError("GGUF metadata inspection buffer is over budget")
    reader = _Reader(raw)
    if reader.take(4) != b"GGUF":
        raise ValueError("model does not have a GGUF header")
    version = int(reader.unpack("I"))
    tensor_count = int(reader.unpack("Q"))
    metadata_count = int(reader.unpack("Q"))
    if version not in SUPPORTED_GGUF_VERSIONS:
        raise ValueError("GGUF version is not supported")
    if tensor_count <= 0:
        raise ValueError("GGUF model declares no tensors")
    if metadata_count <= 0 or metadata_count > MAX_GGUF_METADATA_ITEMS:
        raise ValueError("GGUF metadata count is invalid")
    metadata: dict[str, object] = {}
    for _ in range(metadata_count):
        key = reader.string()
        if not key or len(key) > 256 or key in metadata:
            raise ValueError("GGUF metadata key is invalid or duplicated")
        metadata[key] = _value(reader, int(reader.unpack("I")))
    architecture = metadata.get("general.architecture")
    if not isinstance(architecture, str) or not architecture:
        raise ValueError("GGUF architecture metadata is missing")
    return {
        "version": version,
        "tensor_count": tensor_count,
        "metadata_count": metadata_count,
        "architecture": architecture,
        "name": metadata.get("general.name"),
        "file_type": metadata.get("general.file_type"),
        "context_length": metadata.get(f"{architecture}.context_length"),
        "embedding_length": metadata.get(f"{architecture}.embedding_length"),
    }


@dataclass(frozen=True, slots=True)
class ModelAdmission:
    schema_version: str
    model_path: str
    model_sha256: str
    size_bytes: int
    device: int
    inode: int
    mtime_ns: int
    metadata: dict[str, object]
    compatible: bool
    compatibility_reasons: tuple[str, ...]
    admitted_at: str


@dataclass(frozen=True, slots=True)
class ServerPlan:
    schema_version: str
    plan_id: str
    model: dict[str, object]
    executable_path: str
    executable_sha256: str
    host: str
