            tuple(sorted((record.memory_id, conflict)))
            for record in eligible
            for conflict in record.conflicts_with
            if conflict in selected_ids
        }
    )
    if conflicts:
        violations.extend(f"memory_conflict:{left}:{right}" for left, right in conflicts)
    bindings = resolve_loadout(caller, eligible, max_assets=plan.max_items)
    selected = [by_id[binding.memory_id] for binding in bindings]
    items = [
        {
            "memory_id": record.memory_id,
            "title": record.title,
            "summary": record.summary,
            "layer": record.layer,
            "memory_type": record.memory_type,
            "source_sha256": record.source_sha256,
            "evidence_locator": record.evidence_locator,
            "revision": record.revision,
        }
        for record in selected
    ]
    byte_count = len(json.dumps(items, sort_keys=True).encode("utf-8"))
    token_count = math.ceil(byte_count / 4)
    if len(selected) < len(eligible):
        violations.append("memory_item_budget_exceeded")
    if byte_count > plan.max_bytes:
        violations.append("memory_byte_budget_exceeded")
    if token_count > plan.max_tokens:
        violations.append("memory_token_budget_exceeded")
    if violations:
        items = []
        byte_count = 0
        token_count = 0
    body = {
        "schema_version": "px.memory-materialization/1.0",
        "plan_id": plan.plan_id,
        "plan_sha256": plan.plan_sha256,
        "binding_ids": list(plan.binding_ids),
        "project_id": plan.project_id,
        "subject_id": plan.subject_id,
        "eligible": not violations,
        "items": items,
        "item_count": len(items),
        "byte_count": byte_count,
        "token_count": token_count,
        "quarantined": sorted(set(violations)),
        "writeback_policy": plan.writeback_policy,
    }
    return {**body, "receipt_sha256": _hash(body)}

def materialize_memory_context(
    plan: MemoryQueryPlan,
    records: Iterable[MemoryRecord],
    *,
    now_utc: datetime | None = None,
) -> dict[str, object]:
    """Materialize an immutable context receipt or fail closed with quarantines."""
    report = validate_memory_query_plan(plan)
    if not report["valid"]:
        raise ValueError("invalid memory query plan: " + "; ".join(report["errors"]))
    now = now_utc or datetime.now(timezone.utc)
    caller = MemoryCaller(plan.project_id, plan.actor_id, plan.agent_id, task_id=plan.subject_id)
    supplied = tuple(records)
    by_id = {record.memory_id: record for record in supplied}
    violations: list[str] = []
    eligible: list[MemoryRecord] = []
    for memory_id in plan.binding_ids:
        record = by_id.get(memory_id)
        if record is None:
            violations.append(f"missing_memory:{memory_id}")
            continue
        if record.project_id != plan.project_id or not can_access(caller, record):
            violations.append(f"foreign_or_unauthorized_memory:{memory_id}")
        elif record.memory_type not in plan.memory_classes or record.layer not in plan.tiers:
            violations.append(f"memory_class_or_tier_mismatch:{memory_id}")
        elif (
            record.confidence < plan.trust_floor
            or record.certification_status not in {"certified", "trusted"}
            or not record.retrieval_enabled
        ):
            violations.append(f"memory_below_trust_floor:{memory_id}")
        elif record.expires_at and record.expires_at <= now:
            violations.append(f"memory_stale:{memory_id}")
        elif (now - record.effective_at).total_seconds() > plan.max_age_seconds:
            violations.append(f"memory_stale:{memory_id}")
        elif plan.provenance_required and (
            not _SHA.fullmatch(record.source_sha256) or not record.evidence_locator
        ):
            violations.append(f"memory_provenance_missing:{memory_id}")
        else:
            eligible.append(record)
    selected_ids = {record.memory_id for record in eligible}
    conflicts = sorted(
        {
            tuple(sorted((record.memory_id, conflict)))
            for record in eligible
            for conflict in record.conflicts_with
            if conflict in selected_ids
        }
    )
    if conflicts:
        violations.extend(f"memory_conflict:{left}:{right}" for left, right in conflicts)
    bindings = resolve_loadout(caller, eligible, max_assets=plan.max_items)
    selected = [by_id[binding.memory_id] for binding in bindings]
    items = [
        {
            "memory_id": record.memory_id,
            "title": record.title,
            "summary": record.summary,
            "layer": record.layer,
            "memory_type": record.memory_type,
            "source_sha256": record.source_sha256,
            "evidence_locator": record.evidence_locator,
            "revision": record.revision,
        }
        for record in selected
    ]
    byte_count = len(json.dumps(items, sort_keys=True).encode("utf-8"))
    token_count = math.ceil(byte_count / 4)
    if len(selected) < len(eligible):
        violations.append("memory_item_budget_exceeded")
    if byte_count > plan.max_bytes:
        violations.append("memory_byte_budget_exceeded")
    if token_count > plan.max_tokens:
        violations.append("memory_token_budget_exceeded")
    if violations:
        items = []
        byte_count = 0
        token_count = 0
    body = {
        "schema_version": "px.memory-materialization/1.0",
        "plan_id": plan.plan_id,
        "plan_sha256": plan.plan_sha256,
        "binding_ids": list(plan.binding_ids),
        "project_id": plan.project_id,
        "subject_id": plan.subject_id,
        "eligible": not violations,
        "items": items,
        "item_count": len(items),
        "byte_count": byte_count,
        "token_count": token_count,
        "quarantined": sorted(set(violations)),
        "writeback_policy": plan.writeback_policy,
    }
    return {**body, "receipt_sha256": _hash(body)}

def validation_errors(self) -> tuple[str, ...]:
    errors = []
    mandatory = {
        "memory_id": self.memory_id,
        "workspace_id": self.workspace_id,
        "project_id": self.project_id,
        "owner_id": self.owner_id,
        "session_id": self.session_id,
        "lease_id": self.lease_id,
        "title": self.title,
        "summary": self.summary,
        "source_artifact": self.source_artifact,
        "source_sha256": self.source_sha256,
        "evidence_locator": self.evidence_locator,
        "confidence_method": self.confidence_method,
        "classification": self.classification,
    }
    errors.extend(
        f"missing_{name}"
        for name, value in mandatory.items()
        if not str(value).strip()
    )
    if self.memory_type not in MEMORY_TYPES:
        errors.append("invalid_memory_type")
    if self.epistemic_status not in {"observation", "inference", "proposal"}:
        errors.append("invalid_epistemic_status")
    if not 0.0 <= self.confidence <= 1.0:
        errors.append("confidence_out_of_range")
    if not re.fullmatch(r"[0-9a-f]{64}", self.source_sha256.casefold()):
        errors.append("invalid_source_sha256")
    if not self.acl:
        errors.append("acl_missing")
    if self.revision < 1:
        errors.append("invalid_revision")
    if self.certification_status not in CERTIFICATION_STATES:
        errors.append("invalid_certification_status")
    if self.layer not in MEMORY_LAYERS:
        errors.append("invalid_memory_layer")
    if self.visibility not in VISIBILITY_STATES:
        errors.append("invalid_visibility")
    if not 0 <= self.priority <= 100:
        errors.append("priority_out_of_range")
    if not 0.0 <= self.usage_success_rate <= 1.0:
        errors.append("usage_success_rate_out_of_range")
    if self.layer == "L0" and self.memory_type != "evidence":
        errors.append("l0_must_be_evidence")
    if self.layer == "L2" and self.memory_type != "scenario":
        errors.append("l2_must_be_scenario")
    if self.layer == "L3" and self.memory_type not in {
        "project_doctrine",
        "team_model",
        "user_core",
        "agent_profile",
    }:
        errors.append("l3_scope_model_required")
    if self.retrieval_enabled and self.certification_status not in {
        "certified",
        "trusted",
    }:
        errors.append("uncertified_retrieval_enabled")
    if self.expires_at and self.expires_at <= self.effective_at:
        errors.append("expiry_not_after_effective")
    if self.semantic is not None:
        errors.extend(self.semantic.validation_errors(project_id=self.project_id))
    return tuple(sorted(set(errors)))

def candidate_memories(
    query: str,
    records: Iterable[MemoryRecord],
    *,
    project_id: str,
    actor_id: str,
    max_hamming: int = 18,
    now: datetime | None = None,
) -> tuple[str, ...]:
    """Generate hard-filtered candidates with exact semantics before locality."""
    query_hash = simhash64(query)
    current = now or datetime.now(timezone.utc)
    values = tuple(records)
    superseded = {memory_id for record in values for memory_id in record.supersedes}
    query_terms = set(TOKEN.findall(query.casefold()))
    candidates = []
    for record in values:
        allowed = actor_id in record.acl or project_id in record.acl
        expired = record.expires_at is not None and record.expires_at <= current
        if (
            record.project_id != project_id
            or record.validation_errors()
            or not allowed
            or expired
            or record.memory_id in superseded
            or record.certification_status not in {"certified", "trusted"}
            or not record.retrieval_enabled
        ):
            continue
        if any(
            set(TOKEN.findall(pattern.casefold())) <= query_terms
            for pattern in record.negative_matches
        ):
            continue
        exact_priority, semantic_score = semantic_query_signals(query, record.semantic)
        distance = (
            query_hash ^ simhash64(record.title + " " + record.summary)
        ).bit_count()
        if exact_priority == 0 or semantic_score > 0 or distance <= max_hamming:
            candidates.append(
                (exact_priority, -semantic_score, distance, record.memory_id)
            )
    return tuple(memory_id for *_, memory_id in sorted(candidates))

def admit_memory(
    record: MemoryRecord, *, active_project_id: str, actor_id: str
) -> MemoryDecision:
    reasons = list(record.validation_errors())
    if record.project_id != active_project_id:
        reasons.append("foreign_project_memory")
    if record.owner_id != actor_id:
        reasons.append("actor_attribution_mismatch")
    if record.epistemic_status == "proposal" and record.confidence >= 1.0:
        reasons.append("proposal_cannot_be_certain")
    return MemoryDecision(
        "candidate" if not reasons else "quarantine",
        tuple(sorted(set(reasons))),
        record.memory_id,
    )

