            "semantic": max(
                0.0, min(1.0, float(semantic_scores.get(record.memory_id, 0.0)))
            )
            * 0.15,
            "graph": max(0.0, min(1.0, float(graph_scores.get(record.memory_id, 0.0))))
            * 0.10,
            "scope": 0.10,
            "binding": (0.08 if caller.agent_id in record.fixed_agent_ids else 0.0),
