def build_graph_clusters(
    nodes: Iterable[GraphNode],
    edges: Iterable[tuple[str, str]],
    *,
    max_initial_nodes: int = 1000,
    max_cluster_size: int = 64,
) -> ClusterResult:
    if min(max_initial_nodes, max_cluster_size) < 1:
        raise ValueError("graph bounds must be positive")
    supplied = tuple(nodes)
    selected = supplied[:max_initial_nodes]
    lookup = {node.node_id: node for node in selected}
    adjacency = {node_id: set() for node_id in lookup}
    missing = set()
    for left, right in edges:
        if left not in lookup or right not in lookup:
            if left not in lookup:
                missing.add(left)
            if right not in lookup:
                missing.add(right)
            continue
        adjacency[left].add(right)
        adjacency[right].add(left)
    assigned = set()
    clusters = []
    for seed in sorted(lookup):
        if seed in assigned:
            continue
        queue = [seed]
        members = []
        while queue and len(members) < max_cluster_size:
            node_id = queue.pop(0)
            if node_id in assigned or node_id not in lookup:
                continue
            assigned.add(node_id)
            members.append(node_id)
            queue.extend(sorted(adjacency[node_id] - assigned))
        terms = []
        seen_terms = set()
        provenance = set()
        for node_id in members:
            node = lookup[node_id]
            provenance.update(node.provenance)
            for term in WORD.findall(node.text.casefold()):
                if term not in seen_terms:
                    terms.append(term)
                    seen_terms.add(term)
        clusters.append(
            GraphCluster(
                f"cluster-{len(clusters) + 1:04d}",
                tuple(members),
                tuple(terms[:32]),
                tuple(sorted(provenance)),
                not any(adjacency[node_id] for node_id in members),
            )
        )
    return ClusterResult(
        tuple(clusters),
        len(selected),
        len(supplied) > len(selected),
        tuple(sorted(missing)),
    )

def plan_memory_graph_remediation(
    project_id: str,
    nodes: Sequence[Mapping[str, object]],
    dependencies: Sequence[Sequence[str]],
    *,
    mutation_approved: bool = False,
    spend_cap: float = 0.0,
) -> dict[str, object]:
    """Detect graph defects and order bounded repairs without applying them."""
    if not project_id.strip() or spend_cap < 0:
        raise ValueError("a project identity and non-negative spend cap are required")
    by_id: dict[str, Mapping[str, object]] = {}
    findings: list[dict[str, object]] = []
    for node in nodes:
        node_id = str(node.get("id", "")).strip()
        if not node_id or node_id in by_id:
            raise ValueError("memory node IDs must be non-empty and unique")
        by_id[node_id] = node
        if node.get("project_id") != project_id:
            findings.append(
                {"code": "cross_project_node", "node_id": node_id, "cost": 1.0}
            )
        citations = tuple(map(str, node.get("citations", ())))
        if not citations:
            findings.append(
                {"code": "citation_missing", "node_id": node_id, "cost": 0.5}
            )
        temporal = node.get("temporal_claims", ())
        for claim in temporal if isinstance(temporal, Sequence) else ():
            if (
                not isinstance(claim, Mapping)
                or claim.get("type") not in TEMPORAL_TYPES
                or not claim.get("value")
            ):
                findings.append(
                    {"code": "invalid_temporal_claim", "node_id": node_id, "cost": 0.5}
                )

    adjacency = {node_id: set() for node_id in by_id}
    indegree = {node_id: 0 for node_id in by_id}
    for edge in dependencies:
        if len(edge) != 2:
            raise ValueError("dependencies must contain pairs")
        dependency, consumer = map(str, edge)
        if dependency not in by_id or consumer not in by_id:
            findings.append(
                {"code": "dangling_dependency", "node_id": consumer, "cost": 0.25}
            )
            continue
        if consumer not in adjacency[dependency]:
            adjacency[dependency].add(consumer)
            indegree[consumer] += 1
    queue = sorted(node_id for node_id, count in indegree.items() if count == 0)
    ordered: list[str] = []
    while queue:
        node_id = queue.pop(0)
        ordered.append(node_id)
        for consumer in sorted(adjacency[node_id]):
            indegree[consumer] -= 1
            if indegree[consumer] == 0:
                queue.append(consumer)
                queue.sort()
    cyclic = sorted(set(by_id) - set(ordered))
    for node_id in cyclic:
        findings.append({"code": "dependency_cycle", "node_id": node_id, "cost": 1.0})

    finding_rank = {
        "dependency_cycle": 0,
        "dangling_dependency": 1,
        "cross_project_node": 2,
        "invalid_temporal_claim": 3,
        "citation_missing": 4,
    }
    findings.sort(
        key=lambda item: (finding_rank[str(item["code"])], str(item["node_id"]))
    )
    steps = []
    spent = 0.0
    for index, finding in enumerate(findings, 1):
        cost = float(finding["cost"])
        within_budget = spent + cost <= spend_cap
        if within_budget:
            spent += cost
        steps.append(
            {
                "order": index,
                "finding": finding,
                "within_spend_cap": within_budget,
                "mutation_approved": mutation_approved,
                "apply": within_budget and mutation_approved,
                "post_step_verification": "recompute graph health and evidence hashes",
            }
        )
    result = {
        "valid": not findings,
        "project_id": project_id,
        "node_count": len(by_id),
        "findings": findings,
        "dependency_order": ordered,
        "steps": steps,
        "spend_cap": spend_cap,
        "planned_spend": spent,
        "mutation_approved": mutation_approved,
        "mutated": False,
        "authority_granted": False,
    }
    result["plan_sha256"] = _stable(result)
    return result

def _all_record_paths(self) -> tuple[Path, ...]:
    return (
        tuple(sorted(self.knowledge_root.rglob("record-*.json")))
        if self.knowledge_root.is_dir()
        else ()
    )

def records(self) -> tuple[MemoryRecord, ...]:
    values: list[MemoryRecord] = []
    previous_by_id: dict[str, str] = {}
    revision_by_id: dict[str, int] = {}
    lifecycle_hashes: dict[str, set[str]] = {}
    for path in self._all_record_paths():
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError) as error:
            raise ValueError(
                f"memory record integrity failure: {path.name}: {type(error).__name__}"
            ) from error
        if not isinstance(payload, dict):
            raise ValueError(
                f"memory record integrity failure: {path.name}: record is not an object"
            )
        required_seals = {
            "previous_record_sha256",
            "record_sha256",
            "lifecycle_event_head_sha256",
        }
        if not required_seals.issubset(payload):
            raise ValueError(
                f"memory record integrity failure: {path.name}: seal fields missing"
            )
        memory_id = str(payload.get("memory_id", ""))
        revision = payload.get("revision")
        if (
            not isinstance(revision, int)
            or isinstance(revision, bool)
            or revision != revision_by_id.get(memory_id, 0) + 1
        ):
            raise ValueError(
                f"memory record integrity failure: {path.name}: revision chain invalid"
            )
        if payload["previous_record_sha256"] != previous_by_id.get(
            memory_id, "0" * 64
        ):
            raise ValueError(
                f"memory record integrity failure: {path.name}: previous-record link mismatch"
            )
        if payload["record_sha256"] != _hash_without(payload, "record_sha256"):
            raise ValueError(
                f"memory record integrity failure: {path.name}: record digest mismatch"
            )
        if memory_id not in lifecycle_hashes:
            lifecycle_hashes[memory_id] = {
                str(item["event_sha256"])
                for item in self._validate_lifecycle(memory_id)
            }
        if (
            payload["lifecycle_event_head_sha256"]
            not in lifecycle_hashes[memory_id]
        ):
            raise ValueError(
                f"memory record integrity failure: {path.name}: lifecycle binding mismatch"
            )
        record = _record_from_payload(payload)
        errors = record.validation_errors()
        if errors:
            raise ValueError(
                f"memory record integrity failure: {path.name}: {', '.join(errors)}"
            )
        values.append(record)
        previous_by_id[memory_id] = str(payload["record_sha256"])
        revision_by_id[memory_id] = revision
    return tuple(values)

