    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        return {
            "valid": False,
            "generation": generation,
            "reasons": (f"generation_unreadable:{type(error).__name__}",),
        }
    if not isinstance(manifest, dict) or not isinstance(entries, list):
        reasons.append("generation_shape_invalid")
    else:
        if manifest.get("schema_version") != "px.memory-index-generation/2.0":
            reasons.append("generation_schema_invalid")
        if manifest.get("generation") != generation:
            reasons.append("generation_identity_invalid")
        if manifest.get("status") != "candidate":
            reasons.append("generation_status_invalid")
        if manifest.get("record_count") != len(entries):
            reasons.append("generation_count_invalid")
        if manifest.get("entries_sha256") != hashlib.sha256(entries_path.read_bytes()).hexdigest():
            reasons.append("generation_entries_hash_invalid")
        if manifest.get("source_tree_sha256") != _stable(entries):
            reasons.append("generation_source_hash_invalid")

        records = {
            (record.memory_id, record.revision): record for record in self.records()
        }
        for entry in entries:
            if not isinstance(entry, dict):
                reasons.append("generation_entry_invalid")
                continue
            key = (str(entry.get("memory_id", "")), entry.get("revision"))
            record = records.get(key)
            if record is None:
                reasons.append("generation_record_missing")
                continue
            if entry.get("record_sha256") != _stable(_record_payload(record)):
                reasons.append("generation_record_hash_stale")
            if entry.get("semantic") != semantic_index_projection(record.semantic):
                reasons.append("generation_semantic_projection_stale")
    return {
        "valid": not reasons,
        "generation": generation,
        "reasons": tuple(sorted(set(reasons))),
        "manifest_sha256": (
            hashlib.sha256(manifest_path.read_bytes()).hexdigest()
            if manifest_path.is_file()
            else None
        ),
    }

def compose_team(
    request: dict[str, Any], agents: list[dict[str, Any]], max_agents: int = 3
) -> dict[str, Any]:
    primary = route(request, agents)
    eligible_ids = [
        x["agent_id"] for x in primary["ranked_candidates"] if x["eligible"]
    ]
    selected: list[str] = []
    covered_failures: set[str] = set()
    for agent_id in eligible_ids:
        agent = next(a for a in agents if a.get("id") == agent_id)
        failures = set(map(str, agent.get("known_failure_modes", [])))
        if not selected or not failures.issubset(covered_failures):
            selected.append(agent_id)
            covered_failures |= failures
        if len(selected) >= max_agents:
            break
    return {
        "request_id": request.get("id"),
        "team": selected,
        "primary": selected[0] if selected else None,
        "coordination_required": len(selected) > 1,
        "max_agents": max_agents,
        "note": "Profiles describe measured task behavior, not human personality or protected traits.",
    }

def route(request: dict[str, Any], agents: list[dict[str, Any]]) -> dict[str, Any]:
    requirements = request.get("requirements", {})
    weights = dict(DEFAULT_WEIGHTS)
    weights.update(request.get("weights", {}))
    required_domains = set(map(str, request.get("domains", [])))
    max_risk = float(request.get("max_risk", 1.0))
    max_cost = float(request.get("max_cost", float("inf")))
    ranked = []
    for agent in agents:
        exclusions = []
        if float(agent.get("risk", 0.5)) > max_risk:
            exclusions.append("risk_budget")
        if float(agent.get("estimated_cost", 0.0)) > max_cost:
            exclusions.append("cost_budget")
        agent_domains = set(map(str, agent.get("domains", [])))
        domain_fit = (
            1.0
            if not required_domains
            else len(agent_domains & required_domains) / len(required_domains)
        )
        components = {}
        total = 0.0
        for dimension, weight in weights.items():
            if dimension == "domain_fit":
                value = domain_fit
            elif dimension in {"latency", "cost"}:
                value = 1.0 - _normalized(agent, dimension)
            else:
                value = _normalized(agent, dimension)
            minimum = requirements.get(dimension)
            if minimum is not None and value < float(minimum):
                exclusions.append(f"minimum_{dimension}")
            components[dimension] = round(value, 6)
            total += float(weight) * value
        calibration_penalty = float(agent.get("calibration_error", 0.0))
        failure_penalty = min(0.5, 0.05 * len(agent.get("known_failure_modes", [])))
        score = total - calibration_penalty - failure_penalty
        ranked.append(
            {
                "agent_id": agent.get("id"),
                "eligible": not exclusions,
                "score": round(score, 6),
                "components": components,
                "exclusions": sorted(set(exclusions)),
                "known_failure_modes": agent.get("known_failure_modes", []),
            }
        )
    ranked.sort(key=lambda x: (not x["eligible"], -x["score"], str(x["agent_id"])))
    selected = next((item for item in ranked if item["eligible"]), None)
    return {
        "request_id": request.get("id"),
        "selected_agent": selected["agent_id"] if selected else None,
        "ranked_candidates": ranked,
        "abstained": selected is None,
        "reason": None if selected else "no candidate satisfies hard constraints",
    }

from __future__ import annotations
from collections import defaultdict, deque
from typing import Any
from ..common.mathx import weighted_jaccard

RELATION_TYPES = {
    "depends_on",
    "requires",
    "produces",
    "improves",
    "conflicts_with",
    "extends",
    "replaces",
    "supersedes",
    "duplicates",
    "composes_with",
}


def _token_weights(capability: dict[str, Any]) -> dict[str, float]:
    tokens: dict[str, float] = {}
    for field, weight in (
        ("tags", 1.0),
        ("inputs", 0.8),
        ("outputs", 0.9),
        ("mechanisms", 1.2),
    ):
        for value in capability.get(field, []):
            tokens[str(value).lower()] = max(
                tokens.get(str(value).lower(), 0.0), weight
            )
    return tokens


def build(
    capabilities: list[dict[str, Any]], relations: list[dict[str, Any]] | None = None
) -> dict[str, Any]:
    relations = list(relations or [])
    ids = {str(c["id"]) for c in capabilities}
    errors: list[str] = []
    for relation in relations:
        if relation.get("type") not in RELATION_TYPES:
            errors.append(f"unknown relation type: {relation.get('type')}")
        if relation.get("source") not in ids or relation.get("target") not in ids:
            errors.append(f"relation references unknown node: {relation}")
    duplicates = []
    for i, left in enumerate(capabilities):
        for right in capabilities[i + 1 :]:
            similarity = weighted_jaccard(_token_weights(left), _token_weights(right))
            if similarity >= 0.72:
                duplicates.append(
                    {
                        "left": left["id"],
                        "right": right["id"],
                        "similarity": round(similarity, 6),
                        "disposition": "review_for_merge_or_alias",
                    }
                )
    indegree = defaultdict(int)
    outdegree = defaultdict(int)
    for relation in relations:
        indegree[relation["target"]] += 1
        outdegree[relation["source"]] += 1
    nodes = []
    for capability in capabilities:
        cid = str(capability["id"])
        nodes.append(
            {
                **capability,
                "incoming_relations": indegree[cid],
                "outgoing_relations": outdegree[cid],
                "orphan": indegree[cid] == 0 and outdegree[cid] == 0,
            }
        )
    return {
        "valid": not errors,
        "errors": errors,
        "nodes": nodes,
        "relations": relations,
        "duplicate_candidates": duplicates,
        "metrics": {
            "node_count": len(nodes),
            "relation_count": len(relations),
            "orphan_count": sum(1 for n in nodes if n["orphan"]),
            "duplicate_candidate_count": len(duplicates),
        },
    }


def dependency_health(genome: dict[str, Any]) -> dict[str, Any]:
    nodes = {n["id"]: n for n in genome.get("nodes", [])}
    graph = defaultdict(list)
    indegree = {node_id: 0 for node_id in nodes}
    missing = []
    for rel in genome.get("relations", []):
        if rel.get("type") not in {"depends_on", "requires"}:
            continue
        source, target = rel.get("source"), rel.get("target")
        if source not in nodes or target not in nodes:
            missing.append(rel)
            continue
        graph[target].append(source)
        indegree[source] += 1
    queue = deque(sorted([n for n, degree in indegree.items() if degree == 0]))
    visited = []
    while queue:
        node = queue.popleft()
        visited.append(node)
        for dependent in graph[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                queue.append(dependent)
    cycles = sorted([n for n, degree in indegree.items() if degree > 0])
    critical = sorted(
        (
            {
                "id": node_id,
                "dependent_count": len(graph[node_id]),
                "certification": nodes[node_id].get("certification", "unknown"),
            }
            for node_id in nodes
            if graph[node_id]
        ),
        key=lambda x: (-x["dependent_count"], x["id"]),
    )
    return {
        "healthy": not missing and not cycles,
        "missing_dependency_relations": missing,
        "cycle_nodes": cycles,
        "topological_order": visited if not cycles else [],
        "critical_dependencies": critical,
    }


def mutation_plan(genome: dict[str, Any], desired_outputs: list[str]) -> dict[str, Any]:
    available = {str(x) for n in genome.get("nodes", []) for x in n.get("outputs", [])}
    missing = sorted(set(map(str, desired_outputs)) - available)
    proposals = [
        {
            "gap": gap,
            "proposal_id": f"capability-for-{gap.replace(' ', '-').lower()}",
            "status": "proposal_only",
            "required_validation": [
                "unit",
                "integration",
                "held_out_outcome",
