from __future__ import annotations
from collections import defaultdict
from typing import Any
from ..common.mathx import clamp, entropy


def decayed_trust(
    initial: float,
    age_days: float,
    half_life_days: float,
    validation_boost: float = 0.0,
) -> float:
    if half_life_days <= 0:
        raise ValueError("half_life_days must be positive")
    decay = 0.5 ** (max(0.0, age_days) / half_life_days)
    return clamp(initial * decay + validation_boost)


def contradiction_pressure(claims: list[dict[str, Any]]) -> float:
    if len(claims) < 2:
        return 0.0
    weighted_disagreement = 0.0
    total_weight = 0.0
    for i, left in enumerate(claims):
        for right in claims[i + 1 :]:
            weight = float(left.get("trust", 0.5)) * float(right.get("trust", 0.5))
            total_weight += weight
            if left.get("value") != right.get("value"):
                weighted_disagreement += weight
    return 0.0 if total_weight == 0 else weighted_disagreement / total_weight


def simulate(state: dict[str, Any]) -> dict[str, Any]:
    now_day = float(state.get("now_day", 0))
    records = []
    for record in state.get("records", []):
        age = max(0.0, now_day - float(record.get("validated_day", now_day)))
        trust = decayed_trust(
            float(record.get("trust", 0.5)),
            age,
            float(record.get("half_life_days", 90)),
            float(record.get("validation_boost", 0.0)),
        )
        records.append({**record, "age_days": age, "effective_trust": trust})
    by_subject = defaultdict(list)
    for record in records:
        by_subject[str(record.get("subject", ""))].append(record)
    subjects = []
    for subject, group in sorted(by_subject.items()):
        weights = [r["effective_trust"] for r in group]
        probabilities = [w / sum(weights) for w in weights] if sum(weights) else []
        pressure = contradiction_pressure(group)
        volatility = sum(abs(float(r.get("recent_delta", 0.0))) for r in group) / max(
            1, len(group)
        )
        validation_age = max((r["age_days"] for r in group), default=0.0)
        stability = clamp(
            1.0
            - 0.55 * pressure
            - 0.25 * volatility
            - 0.20 * min(1.0, validation_age / 365.0)
        )
        subjects.append(
            {
                "subject": subject,
                "record_count": len(group),
                "trust_entropy_bits": entropy(probabilities),
                "contradiction_pressure": pressure,
                "volatility": volatility,
                "stability": stability,
                "revalidation_priority": clamp(
                    0.45 * pressure
                    + 0.25 * volatility
                    + 0.20 * (1 - stability)
                    + 0.10 * min(1.0, validation_age / 365)
                ),
            }
        )
    relations = state.get("relations", [])
    coexecution = defaultdict(float)
    for relation in relations:
        if relation.get("type") == "coexecuted":
            pair = tuple(
                sorted([str(relation.get("source")), str(relation.get("target"))])
            )
            coexecution[pair] += float(relation.get("weight", 1.0))
    attractors = [
        {"members": list(pair), "strength": strength}
        for pair, strength in sorted(coexecution.items(), key=lambda x: (-x[1], x[0]))
        if strength >= float(state.get("attractor_threshold", 2.0))
    ]
    return {
        "subjects": subjects,
        "attractors": attractors,
        "highest_revalidation_priorities": sorted(
            subjects, key=lambda x: (-x["revalidation_priority"], x["subject"])
        )[:10],
        "model_note": (
            "Knowledge physics is an explicit operational metaphor. Every output is decomposed "
            "into trust, age, contradictions, volatility, connectivity, and validation evidence."
        ),
    }

from __future__ import annotations
import re


def normalize(text: str) -> str:
    return re.sub(r"\s+", " ", text.strip().lower())


def detect(claims: list[dict]) -> list[dict]:
    findings = []
    by_subject: dict[str, list[dict]] = {}
    for claim in claims:
        by_subject.setdefault(claim.get("subject", ""), []).append(claim)
    for subject, group in by_subject.items():
        for index, left in enumerate(group):
            for right in group[index + 1 :]:
                conflict, reason = False, ""
                if (
                    left.get("value") is not None
                    and right.get("value") is not None
                    and left.get("value") != right.get("value")
                ):
                    conflict, reason = True, "different values"
                ls, rs = (
                    normalize(left.get("statement", "")),
                    normalize(right.get("statement", "")),
                )
                if ls == "not " + rs or rs == "not " + ls:
                    conflict, reason = True, "explicit negation"
                if conflict:
                    findings.append(
                        {
                            "subject": subject,
                            "claim_a": left.get("id"),
                            "claim_b": right.get("id"),
                            "reason": reason,
                            "resolution": "unresolved",
                        }
                    )
    return findings

def detect(claims: list[dict]) -> list[dict]:
    findings = []
    by_subject: dict[str, list[dict]] = {}
    for claim in claims:
        by_subject.setdefault(claim.get("subject", ""), []).append(claim)
    for subject, group in by_subject.items():
        for index, left in enumerate(group):
            for right in group[index + 1 :]:
                conflict, reason = False, ""
                if (
                    left.get("value") is not None
                    and right.get("value") is not None
                    and left.get("value") != right.get("value")
                ):
                    conflict, reason = True, "different values"
                ls, rs = (
                    normalize(left.get("statement", "")),
                    normalize(right.get("statement", "")),
                )
                if ls == "not " + rs or rs == "not " + ls:
                    conflict, reason = True, "explicit negation"
                if conflict:
                    findings.append(
                        {
                            "subject": subject,
                            "claim_a": left.get("id"),
                            "claim_b": right.get("id"),
                            "reason": reason,
                            "resolution": "unresolved",
                        }
                    )
    return findings

from __future__ import annotations
from ..common.mathx import clamp, entropy


def bayes_update(
    prior: float, likelihood_if_true: float, likelihood_if_false: float
) -> float:
    prior = clamp(prior)
    lt = clamp(likelihood_if_true)
    lf = clamp(likelihood_if_false)
    denominator = lt * prior + lf * (1 - prior)
    return prior if denominator == 0 else clamp((lt * prior) / denominator)


def brier(predictions, outcomes) -> float:
    ps, ys = list(map(float, predictions)), list(map(float, outcomes))
    if len(ps) != len(ys) or not ps:
        raise ValueError("equal non-empty arrays required")
    return sum((p - y) ** 2 for p, y in zip(ps, ys)) / len(ps)


def expected_calibration_error(predictions, outcomes, bins: int = 10) -> float:
    ps, ys = list(map(float, predictions)), list(map(float, outcomes))
    if len(ps) != len(ys) or not ps:
        raise ValueError("equal non-empty arrays required")
    total, result = len(ps), 0.0
    for b in range(bins):
        lo, hi = b / bins, (b + 1) / bins
        idx = [
            i for i, p in enumerate(ps) if lo <= p < hi or (b == bins - 1 and p == 1.0)
        ]
        if idx:
            confidence = sum(ps[i] for i in idx) / len(idx)
            accuracy = sum(ys[i] for i in idx) / len(idx)
            result += len(idx) / total * abs(accuracy - confidence)
    return result


def build_state(case: dict) -> dict:
    hypotheses = [dict(h) for h in case.get("hypotheses", [])]
    for hypothesis in hypotheses:
        posterior = float(hypothesis.get("prior", 0.5))
        for evidence in hypothesis.get("evidence", []):
            posterior = bayes_update(
                posterior,
                float(evidence["likelihood_if_true"]),
                float(evidence["likelihood_if_false"]),
            )
        hypothesis["posterior"] = posterior
    probabilities = [h.get("posterior", h.get("prior", 0.5)) for h in hypotheses]
    return {
        "id": case.get("id", "case"),
        "hypotheses": hypotheses,
        "entropy_bits": entropy(probabilities),
        "unknowns": case.get("unknowns", []),
        "assumptions": case.get("assumptions", []),
    }

from __future__ import annotations
from typing import Any


def dominates(
    left: dict[str, float], right: dict[str, float], directions: dict[str, str]
) -> bool:
    no_worse = True
    strictly_better = False
    for metric, direction in directions.items():
        lv, rv = float(left[metric]), float(right[metric])
        if direction == "maximize":
            no_worse &= lv >= rv
            strictly_better |= lv > rv
        else:
            no_worse &= lv <= rv
            strictly_better |= lv < rv
    return bool(no_worse and strictly_better)


def pareto_front(
    candidates: list[dict[str, Any]], directions: dict[str, str]
) -> list[dict[str, Any]]:
    front = []
    for candidate in candidates:
        if not any(
            dominates(other["metrics"], candidate["metrics"], directions)
            for other in candidates
            if other is not candidate
        ):
            front.append(candidate)
    return sorted(front, key=lambda x: str(x.get("id")))


def evaluate(experiment: dict[str, Any]) -> dict[str, Any]:
    baseline = experiment["baseline"]
    candidates = experiment.get("candidates", [])
    directions = experiment.get("directions", {})
    thresholds = experiment.get("hard_thresholds", {})
    results = []
    for candidate in candidates:
        failures = []
        for metric, threshold in thresholds.items():
            value = float(candidate["metrics"][metric])
            direction = directions.get(metric, "maximize")
            if direction == "maximize" and value < float(threshold):
                failures.append(metric)
            if direction == "minimize" and value > float(threshold):
                failures.append(metric)
        regressions = []
        for metric, direction in directions.items():
            cv = float(candidate["metrics"][metric])
            bv = float(baseline["metrics"][metric])
            tolerance = float(
                experiment.get("regression_tolerance", {}).get(metric, 0.0)
            )
            if direction == "maximize" and cv + tolerance < bv:
                regressions.append(metric)
            elif direction == "minimize" and cv - tolerance > bv:
                regressions.append(metric)
        utility = 0.0
        for metric, weight in experiment.get("utility_weights", {}).items():
            cv = float(candidate["metrics"][metric])
            utility += float(weight) * (
                cv if directions.get(metric) == "maximize" else -cv
            )
        results.append(
            {
                "id": candidate["id"],
                "metrics": candidate["metrics"],
                "threshold_failures": failures,
                "regressions": regressions,
                "eligible": not failures and not regressions,
                "utility": round(utility, 8),
            }
        )
    eligible = [r for r in results if r["eligible"]]
    pareto = pareto_front(eligible, directions) if eligible else []
    selected = max(pareto, key=lambda x: x["utility"], default=None)
    return {
        "experiment_id": experiment.get("id"),
        "baseline": baseline,
        "candidate_results": results,
        "pareto_front": [x["id"] for x in pareto],
        "selected": selected["id"] if selected else None,
        "disposition": "promote_candidate" if selected else "retain_baseline",
        "rollback_required_on_failure": True,
        "promotion_requires_independent_validation": True,
    }

from __future__ import annotations
from typing import Any

REQUIRED = {
    "capability_id": str,
    "reads": list,
    "writes": list,
    "epistemic_effects": list,
    "evidence_required": list,
    "rollback": dict,
}

SENSITIVE_PREFIXES = (
    "memory.",
    "registry.",
    "permissions.",
    "external.",
    "runtime.",
    "filesystem.",
    "network.",
    "secrets.",
    "model.",
)


def lint(contract: dict[str, Any]) -> dict[str, Any]:
    errors: list[str] = []
    warnings: list[str] = []
    for name, expected in REQUIRED.items():
        if name not in contract:
            errors.append(f"missing required field: {name}")
        elif not isinstance(contract[name], expected):
            errors.append(f"{name} must be {expected.__name__}")

    reads = (
        set(contract.get("reads", []))
        if isinstance(contract.get("reads"), list)
        else set()
    )
    writes = (
        set(contract.get("writes", []))
        if isinstance(contract.get("writes"), list)
        else set()
    )
    prohibited = (
        set(contract.get("prohibited_effects", []))
        if isinstance(contract.get("prohibited_effects"), list)
        else set()
    )
    evidence = (
        contract.get("evidence_required", [])
        if isinstance(contract.get("evidence_required"), list)
        else []
    )
    rollback = (
        contract.get("rollback", {})
        if isinstance(contract.get("rollback"), dict)
        else {}
    )

    overlap = writes & prohibited
    if overlap:
        errors.append(
            "declared writes conflict with prohibited effects: "
            + ", ".join(sorted(overlap))
        )
    undeclared_sensitive = [
        effect
        for effect in contract.get("observed_effects", [])
        if effect.startswith(SENSITIVE_PREFIXES) and effect not in writes
    ]
    if undeclared_sensitive:
        errors.append(
            "observed sensitive effects were not declared: "
            + ", ".join(sorted(undeclared_sensitive))
        )
    if writes and not rollback.get("required", False):
        warnings.append("writes are declared but rollback.required is false")
    if writes and not rollback.get("method"):
        errors.append("writes require a concrete rollback.method")
    if contract.get("external_effects") and not evidence:
        warnings.append("external effects declared without evidence requirements")
    if not contract.get("epistemic_effects"):
        warnings.append("no epistemic effects declared")
    if reads & writes:
        warnings.append(
            "same resources appear in reads and writes; verify mutation intent"
        )
    return {
        "capability_id": contract.get("capability_id"),
        "valid": not errors,
        "errors": errors,
        "warnings": warnings,
        "declared_read_count": len(reads),
        "declared_write_count": len(writes),
    }

