    if payload.get("card_id") != card_id or payload.get("status") != "accepted":
        problems.append({"code": "acceptance_not_accepted", "detail": card_id})
    artifacts = payload.get("artifacts")
    if not isinstance(artifacts, list) or not artifacts:
        problems.append({"code": "acceptance_artifacts_missing", "detail": card_id})
        return problems
    seen: set[str] = set()
    for artifact in artifacts:
        if not isinstance(artifact, Mapping):
            problems.append({"code": "acceptance_artifact_invalid", "detail": card_id})
            continue
        raw_path = artifact.get("path")
        expected = artifact.get("sha256")
        if not isinstance(expected, str) or not HEX_SHA256.fullmatch(expected):
            problems.append({"code": "acceptance_receipt_invalid", "detail": card_id})
            continue
        try:
            path = _resolve_below(root, raw_path)
        except ValueError:
            problems.append({"code": "acceptance_receipt_invalid", "detail": card_id})
            continue
        key = path.as_posix()
        if key in seen:
            problems.append({"code": "acceptance_artifact_duplicate", "detail": card_id})
            continue
        seen.add(key)
        try:
            actual = _file_sha256(path)
        except OSError:
            problems.append({"code": "acceptance_artifact_missing", "detail": f"{card_id}:{raw_path}"})
            continue
        if actual != expected:
            problems.append({"code": "acceptance_receipt_mismatch", "detail": f"{card_id}:{raw_path}"})
    return problems

def reconcile_operation_coverage(
    root: Path,
    *,
    health_snapshot: Mapping[str, object] | Path | None = None,
    evidence_dir: Path = DEFAULT_EVIDENCE_DIR,
    now: datetime | None = None,
    max_age_seconds: int = 300,
) -> dict[str, Any]:
    """Reconcile static claims, current health, and hash-bound acceptance proof."""
    root = root.resolve()
    if not 1 <= max_age_seconds <= 86_400:
        raise ValueError("max_age_seconds must be between 1 and 86400")
    clock = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    registry_report = validate_route_registry(root)
    blockers: list[dict[str, str]] = []
    errors: list[str] = list(registry_report.get("errors", ()))
    if not registry_report.get("valid"):
        blockers.append({"code": "registry_invalid", "detail": "route registry failed structural or tier honesty validation"})
    try:
        loaded_registry = _load_json(root / ROUTE_REGISTRY)
    except ValueError as error:
        loaded_registry = {"routes": []}
        errors.append(str(error))
    routes = loaded_registry.get("routes", []) if isinstance(loaded_registry, Mapping) else []
    route_by_id = {
        str(route.get("route_id")): route
        for route in routes
        if isinstance(route, Mapping) and isinstance(route.get("route_id"), str)
    }

    evidence, evidence_problems = _load_acceptance_evidence(root, evidence_dir)
    blockers.extend(evidence_problems)
    states, health_problems, health_sha256 = _load_health_snapshot(health_snapshot)
    blockers.extend(health_problems)
    state_by_route: dict[str, Mapping[str, object]] = {}
    for state in states:
        route_id = state.get("route_id")
        if not isinstance(route_id, str) or not route_id:
            blockers.append({"code": "health_state_invalid", "detail": "route_id is missing"})
            continue
        if route_id not in route_by_id:
            blockers.append({"code": "unknown_route_state", "detail": route_id})
            continue
        if route_id in state_by_route:
            blockers.append({"code": "duplicate_route_state", "detail": route_id})
            continue
        state_by_route[route_id] = state

    validated_cards: dict[str, list[dict[str, str]]] = {}
    route_reports: list[dict[str, object]] = []
    blind_spots: list[dict[str, str]] = []
    cutoff = clock - timedelta(seconds=max_age_seconds)
    future_limit = clock + timedelta(seconds=60)
    for route_id, route in route_by_id.items():
        route_blockers: list[dict[str, str]] = []
        tier = str(route.get("coverage_tier"))
        instrumentation = route.get("instrumentation")
        instrumentation = instrumentation if isinstance(instrumentation, Mapping) else {}
        mechanism = str(instrumentation.get("kind", ""))
        active = route.get("advertised") is True
        planned_inactive = not active and route.get("status") == "planned"
        expected_mechanism = TIER_MECHANISMS.get(tier)
        if expected_mechanism and mechanism != expected_mechanism:
            route_blockers.append({"code": "dishonest_tier", "detail": f"Tier {tier} requires {expected_mechanism}"})
        required_cards: list[str] = []
        for requirement in route.get("acceptance_evidence", []):
            card = _card_id(requirement)
            if card is None:
                route_blockers.append({"code": "acceptance_reference_invalid", "detail": route_id})
                continue
            if card not in required_cards:
                required_cards.append(card)
        for card in required_cards:
            if planned_inactive:
                continue
            record = evidence.get(card)
            if record is None:
                route_blockers.append({"code": "acceptance_evidence_missing", "detail": card})
                continue
            if card not in validated_cards:
                validated_cards[card] = _validate_acceptance_record(root, card, record)
            route_blockers.extend(validated_cards[card])

        owner = route.get("owner")
        owner_evidence: dict[str, str] | None = None
        try:
            owner_path = _resolve_below(root, owner)
            if not owner_path.is_file():
                raise ValueError("owner missing")
            owner_evidence = {
                "mode": "local_file",
                "owner": owner_path.relative_to(root).as_posix(),
                "owner_sha256": _file_sha256(owner_path),
            }
        except (OSError, ValueError):
            if route.get("surface") in {"extension", "mcp"}:
                owner_evidence = _external_owner_receipt(
                    root, owner, required_cards, evidence, validated_cards
                )
            if owner_evidence is None:
                route_blockers.append({"code": "route_owner_missing", "detail": route_id})

        if tier == "D":
            blind = str(route.get("blind_spot_state", "unobserved"))
            blind_spots.append({"route_id": route_id, "state": blind})
            if route.get("advertised") is True:
                route_blockers.append({"code": "declared_blind_spot", "detail": blind})
            if mechanism != "none":
                route_blockers.append({"code": "dishonest_tier", "detail": "Tier D requires no instrumentation claim"})
        else:
            if active and instrumentation.get("health") != "healthy":
                route_blockers.append({"code": "declared_instrumentation_unhealthy", "detail": str(instrumentation.get("health"))})
            state = state_by_route.get(route_id)
            if tier in {"A", "B"} and active:
                if state is None:
                    route_blockers.append({"code": "required_health_state_missing", "detail": route_id})
                else:
                    kind = state.get("kind")
                    allowed_kinds = {"mediator"} if tier == "A" else {"observer", "sensor"}
                    if kind not in allowed_kinds or kind not in HEALTH_KINDS:
                        route_blockers.append({"code": "health_kind_mismatch", "detail": str(kind)})
                    health = state.get("health")
                    if health not in HEALTH_VALUES or health != "healthy":
                        route_blockers.append({"code": "route_health_unhealthy", "detail": str(health)})
                    try:
                        observed_at = _parse_time(state.get("observed_at"))
                        if observed_at < cutoff or observed_at > future_limit:
                            route_blockers.append({"code": "route_health_stale", "detail": route_id})
                    except ValueError:
                        route_blockers.append({"code": "route_health_time_invalid", "detail": route_id})
                    expected_sha = state.get("receipt_sha256")
                    if not isinstance(expected_sha, str) or not HEX_SHA256.fullmatch(expected_sha):
                        route_blockers.append({"code": "health_receipt_invalid", "detail": route_id})
                    else:
                        try:
                            receipt = _resolve_below(root, state.get("receipt_path"))
                            actual_sha = _file_sha256(receipt)
                        except (OSError, ValueError):
                            route_blockers.append({"code": "health_receipt_missing", "detail": route_id})
                        else:
                            if actual_sha != expected_sha:
                                route_blockers.append({"code": "health_receipt_mismatch", "detail": route_id})
        for blocker in route_blockers:
            blockers.append({**blocker, "route_id": route_id})
        route_reports.append(
            {
                "route_id": route_id,
                "tier": tier,
                "declared": True,
                "advertised": route.get("advertised") is True,
                "certifiable": not route_blockers,
                "required_acceptance_cards": required_cards,
                "owner_evidence": owner_evidence,
                "health_state_present": route_id in state_by_route,
                "blockers": route_blockers,
            }
        )

    input_invalid_codes = {
        "registry_invalid",
        "evidence_directory_unreadable",
        "evidence_limit_exceeded",
        "evidence_unreadable",
        "evidence_invalid",
        "duplicate_acceptance_evidence",
        "health_snapshot_unreadable",
        "health_snapshot_invalid",
        "health_state_invalid",
        "unknown_route_state",
        "duplicate_route_state",
    }
    input_valid = not errors and not any(item["code"] in input_invalid_codes for item in blockers)
    return {
        "schema_version": "px.operation-coverage-report/1.0",
        "valid": input_valid,
        "certifiable": input_valid and not blockers,
        "route_registry_sha256": _file_sha256(root / ROUTE_REGISTRY) if (root / ROUTE_REGISTRY).is_file() else None,
        "health_snapshot_sha256": health_sha256,
        "route_count": len(route_by_id),
        "classified_route_count": sum(1 for route in routes if isinstance(route, Mapping) and route.get("coverage_tier") in {"A", "B", "C", "D"}),
        "tiers": registry_report.get("tiers", {tier: 0 for tier in "ABCD"}),
        "acceptance_cards_loaded": sorted(evidence),
        "blind_spots": blind_spots,
        "routes": route_reports,
        "blockers": blockers,
        "errors": errors,
    }

def assess_loop(skill_id: str, payload: Mapping[str, object]) -> ControlResult:
    states = tuple(map(str, payload.get("state_fingerprints", ())))
    evidence_counts = tuple(int(value) for value in payload.get("evidence_counts", ()))
    repeated = len(states) != len(set(states))
    no_progress = len(evidence_counts) > 1 and evidence_counts[-1] <= evidence_counts[0]
    failures = int(payload.get("failure_count", 0))
    cost = float(payload.get("next_step_cost", 0.0))
    gain = float(payload.get("expected_information_gain", 0.0))
    risk = float(payload.get("trajectory_risk", 0.0))
    reasons = []
    if repeated:
        reasons.append("repeated_state")
    if no_progress:
        reasons.append("no_evidence_progress")
    if failures >= int(payload.get("failure_limit", 2)):
        reasons.append("failure_budget_exhausted")
    if risk >= float(payload.get("risk_limit", 0.8)):
        reasons.append("trajectory_risk_high")
    if gain <= cost:
        reasons.append("marginal_utility_nonpositive")
    decision = (
        "continue"
        if not reasons
        else ("escalate" if "trajectory_risk_high" in reasons else "stop")
    )
    return ControlResult(
        skill_id,
        decision,
        tuple(reasons),
        {
            "expected_gain": gain,
            "next_step_cost": cost,
            "trajectory_risk": risk,
            "remaining_failure_budget": max(
                0, int(payload.get("failure_limit", 2)) - failures
            ),
        },
    )

def assess_supply_chain(skill_id: str, payload: Mapping[str, object]) -> ControlResult:
    declared_permissions = set(map(str, payload.get("declared_permissions", ())))
    prior_permissions = set(map(str, payload.get("prior_permissions", ())))
    observed_effects = set(map(str, payload.get("observed_effects", ())))
    declared_effects = set(map(str, payload.get("declared_effects", ())))
    additions = declared_permissions - prior_permissions
    undeclared = observed_effects - declared_effects
    checks = {
        "hash_matches": payload.get("hash_matches") is True,
        "signature_valid": payload.get("signature_valid") is True,
        "owner_resolved": bool(payload.get("owner")),
        "build_chain_resolved": bool(payload.get("build_chain")),
    }
    reasons = []
    if additions:
        reasons.append("permission_expansion")
    if undeclared:
        reasons.append("observed_undeclared_effect")
    if not all(checks.values()):
        reasons.append("provenance_or_signature_failure")
    if skill_id == "dynamic-skill-detonator" and not payload.get("sandbox_adapter"):
        reasons.append("sandbox_adapter_missing")
    decision = (
        "admit"
        if not reasons
        else (
            "sandbox_required"
            if reasons == ["sandbox_adapter_missing"]
            else "quarantine"
        )
    )
    return ControlResult(
        skill_id,
        decision,
        tuple(reasons),
        {
            "permission_additions": tuple(sorted(additions)),
            "undeclared_effects": tuple(sorted(undeclared)),
            "verification_checks": checks,
            "synthetic_secrets_only": skill_id == "dynamic-skill-detonator",
        },
    )

def compile_candidate(skill_id: str, payload: Mapping[str, object]) -> ControlResult:
    records = [dict(item) for item in payload.get("records", ())]
    accepted = tuple(
        sorted(
            str(item.get("id"))
            for item in records
            if item.get("verified") is True and item.get("evidence")
        )
    )
    rejected = tuple(
        sorted(
            str(item.get("id"))
            for item in records
            if str(item.get("id")) not in accepted
        )
    )
    return ControlResult(
        skill_id,
        "candidate_compiled" if accepted else "insufficient_evidence",
        (() if accepted else ("no_verified_records",)),
        {
            "accepted_records": accepted,
            "rejected_records": rejected,
            "activation": "candidate",
            "compilation_hash": _stable(accepted),
        },
    )

def evaluate_memory(skill_id: str, payload: Mapping[str, object]) -> ControlResult:
    item = str(payload.get("retrieved_item", payload.get("memory", "")))
    original_goal = str(payload.get("original_goal", ""))
    requested = set(map(str, payload.get("requested_effects", ())))
    allowed = set(map(str, payload.get("allowed_effects", ())))
    provenance = str(payload.get("provenance", "unknown"))
    instruction_markers = (
        "ignore previous",
        "override policy",
        "reveal secret",
        "expand permission",
        "system message",
    )
    findings: list[str] = []
    if any(marker in item.casefold() for marker in instruction_markers):
        findings.append("embedded_instruction")
    if requested - allowed:
        findings.append("permission_expansion")
    if not provenance or provenance == "unknown":
        findings.append("unresolved_provenance")
    if (
        original_goal
        and item
        and not set(original_goal.casefold().split()) & set(item.casefold().split())
    ):
        findings.append("intent_divergence")

    current = dict(payload.get("current_variables", {}))
    prior = dict(payload.get("memory_variables", {}))
    mismatches = tuple(
        sorted(
            key
            for key in set(current) | set(prior)
            if current.get(key) != prior.get(key)
        )
    )
    if mismatches:
        findings.append("material_context_mismatch")

    promotion_checks = {
        "current_evidence": payload.get("evidence_status") == "current",
        "postconditions": payload.get("postconditions_passed") is True,
        "approved_scope": bool(payload.get("approved_scope")),
        "no_contradiction": not payload.get("contradictions"),
    }
    if skill_id in {"candidate-memory-promoter", "procedural-memory-compiler"}:
        decision = (
            "promote"
            if all(promotion_checks.values()) and not findings
            else "candidate_only"
        )
    elif findings:
        decision = "quarantine"
    else:
        decision = "allow_principles_only"
    return ControlResult(
        skill_id,
        decision,
        tuple(sorted(findings)),
        {
            "mismatches": mismatches,
            "promotion_checks": promotion_checks,
            "prohibited_replay": bool(mismatches or findings),
        },
        _tuple(payload.get("evidence", ())),
    )

def resolve_bundle(skill_id: str, payload: Mapping[str, object]) -> ControlResult:
    requirements = set(map(str, payload.get("requirements", ())))
    candidates = [dict(item) for item in payload.get("candidates", ())]
    limit = max(1, min(int(payload.get("max_assets", 8)), 8))
    selected: list[dict[str, object]] = []
    unresolved = set(requirements)
    conflicts: set[str] = set()
    while unresolved and len(selected) < limit:
        eligible = []
        selected_ids = {str(item["id"]) for item in selected}
        for item in candidates:
            item_id = str(item.get("id", ""))
            if not item_id or item_id in selected_ids:
                continue
            item_conflicts = set(map(str, item.get("conflicts", ())))
            if item_conflicts & selected_ids:
                conflicts.add(item_id)
                continue
            coverage = unresolved & set(map(str, item.get("provides", ())))
            if coverage:
                score = (
                    len(coverage) * 100
                    - float(item.get("cost", 1)) * 5
                    - float(item.get("risk", 1))
                )
                eligible.append((score, item_id, item, coverage))
        if not eligible:
            break
        _, _, winner, coverage = max(eligible, key=lambda entry: (entry[0], entry[1]))
        selected.append(winner)
        unresolved -= coverage
    decision = "resolved" if not unresolved else "incomplete"
    return ControlResult(
        skill_id,
        decision,
        (() if decision == "resolved" else ("requirements_unresolved",)),
        {
            "selected": tuple(str(item["id"]) for item in selected),
            "unresolved": tuple(sorted(unresolved)),
            "excluded_conflicts": tuple(sorted(conflicts)),
            "selection_hash": _stable([item.get("id") for item in selected]),
        },
    )

def run_control(skill_id: str, payload: Mapping[str, object]) -> ControlResult:
    if skill_id in DELEGATED_HANDLERS:
        return ControlResult(
            skill_id,
            "delegate",
            (),
            {"handler": DELEGATED_HANDLERS[skill_id], "payload_hash": _stable(payload)},
        )
    family = SKILL_FAMILIES.get(skill_id)
    if family == "memory":
        return evaluate_memory(skill_id, payload)
    if family == "bundle":
        return resolve_bundle(skill_id, payload)
    if family == "supply_chain":
        return assess_supply_chain(skill_id, payload)
    if family == "loop":
        return assess_loop(skill_id, payload)
    if family == "impact":
        return trace_impact(skill_id, payload)
    if family == "evaluation":
        return select_evaluation(skill_id, payload)
    if family == "research":
        return process_research(skill_id, payload)
    if family == "progress":
        return track_progress(skill_id, payload)
    if family == "compile":
        return compile_candidate(skill_id, payload)
    if family == "topology":
        return select_topology(skill_id, payload)
    raise KeyError(f"unknown operational skill: {skill_id}")

def select_topology(skill_id: str, payload: Mapping[str, object]) -> ControlResult:
    approved = [dict(item) for item in payload.get("approved_templates", ())]
    risk = float(payload.get("risk", 0))
    complexity = float(payload.get("complexity", 0))
    eligible = [
        item
        for item in approved
        if float(item.get("max_risk", 1)) >= risk
        and float(item.get("max_complexity", 1)) >= complexity
    ]
    eligible.sort(
        key=lambda item: (float(item.get("cost", 0)), str(item.get("id", "")))
    )
    selected = str(eligible[0].get("id")) if eligible else None
    if skill_id == "read-only-speculation-controller":
        read_only = bool(payload.get("read_only"))
        return ControlResult(
            skill_id,
            "proposal_only" if read_only else "denied",
            (() if read_only else ("non_read_speculation_forbidden",)),
            {
                "selected_template": selected,
                "cache_state": "quarantined",
                "executed": False,
            },
        )
    return ControlResult(
        skill_id,
        "selected" if selected else "no_approved_topology",
        (() if selected else ("approved_template_missing",)),
        {"selected_template": selected},
    )

def track_progress(skill_id: str, payload: Mapping[str, object]) -> ControlResult:
    milestones = [dict(item) for item in payload.get("milestones", ())]
    states = []
    for item in milestones:
        if item.get("postcondition") is True and item.get("evidence"):
            state = "complete"
        elif item.get("blocked"):
            state = "blocked"
        else:
            state = "partial"
        states.append((str(item.get("id", "")), state))
    unresolved = tuple(item_id for item_id, state in states if state != "complete")
    handoff_required = ("goal", "constraints", "decisions", "evidence", "next_actions")
    missing_handoff = tuple(
        field for field in handoff_required if not payload.get(field)
    )
    decision = "complete" if states and not unresolved else "resumable"
    return ControlResult(
        skill_id,
        decision,
        (() if not missing_handoff else ("handoff_fields_missing",)),
        {
            "milestones": tuple(states),
            "unresolved": unresolved,
            "missing_handoff_fields": missing_handoff,
        },
    )

def _route_tier(self, route_id: str) -> str:
    path = self.engine_root / "registry/operation_route_registry.json"
    stat = path.stat()
    identity = (stat.st_size, stat.st_mtime_ns, stat.st_ctime_ns)
    if identity != self._route_registry_identity:
        report = validate_route_registry(self.engine_root)
        if not report["valid"]:
            raise ValueError("operation route registry is invalid")
        registry = json.loads(path.read_text(encoding="utf-8"))
        self._route_tiers = {
            str(route["route_id"]): str(route["coverage_tier"])
            for route in registry["routes"]
        }
        self._route_registry_identity = identity
    if route_id in self._route_tiers:
        return self._route_tiers[route_id]
    raise ValueError(f"operation route is not admitted: {route_id}")

def publish_batch(
    self, events: list[Mapping[str, object]], *, link_current_head: bool = False
) -> list[dict[str, object]]:
    """Publish a bounded ingress batch while linking each event under the lock."""
    if len(events) > 1_000:
        raise ValueError("operational event batch exceeds 1000 events")
    return [
        self.publish(event, link_current_head=link_current_head) for event in events
    ]

def replay(self, *, after_revision: int = 0, limit: int = 1000) -> dict[str, Any]:
    """Replay a bounded verified suffix while preserving degraded ancestry."""
    if after_revision < 0 or not 0 <= limit <= 10_000:
        raise ValueError("invalid replay boundary")
    self.root.mkdir(parents=True, exist_ok=True)
    self.wal.recover()
    records: list[dict[str, object]] = []
    errors: list[str] = []
    previous = ZERO_SHA256
    paths = sorted((self.root / "events").glob("*.json")) if (self.root / "events").is_dir() else []
    for expected, path in enumerate(paths, start=1):
        try:
            envelope = json.loads(path.read_text(encoding="utf-8"))
            if set(envelope) != {"schema_version", "revision", "event_sha256", "event"}:
                raise ValueError("envelope fields are not exact")
            event = envelope["event"]
            expected_previous = None if expected == 1 else previous
            if (
                envelope["schema_version"] != "px.operation-envelope/1.0"
                or envelope["revision"] != expected
                or path.name != f"{expected:08d}.json"
                or envelope["event_sha256"] != _sha(event)
                or event["integrity"]["previous_event_sha256"] != expected_previous
            ):
                raise ValueError("event ancestry or digest mismatch")
            validation = validate_operation_event(self.engine_root, event)
            if not validation["valid"]:
                raise ValueError("event contract invalid")
        except (OSError, UnicodeError, json.JSONDecodeError, KeyError, TypeError, ValueError) as error:
            errors.append(f"{path.name}: {error}")
            break
        previous = str(envelope["event_sha256"])
        records.append(envelope)
    state = self._state()
    if not errors and records:
        expected_head = {
            "schema_version": "px.operation-bus-head/1.0",
            "revision": len(records),
            "event_sha256": previous,
        }
        try:
            head = json.loads(self._head_path.read_text(encoding="utf-8"))
            anchor = self.root / ".authority" / "anchors" / f"{len(records):08d}-{previous}.json"
            if head != expected_head or json.loads(anchor.read_text(encoding="utf-8")) != expected_head:
                raise ValueError("protected head or anchor mismatch")
            if state["revision"] != len(records) or state["head_sha256"] != previous:
                raise ValueError("bus state differs from event ancestry")
        except (OSError, UnicodeError, json.JSONDecodeError, ValueError) as error:
            errors.append(str(error))
    selected = [record for record in records if int(record["revision"]) > after_revision]
    if limit:
        selected = selected[-limit:]
    else:
        selected = []
    return {
        "schema_version": "px.operation-replay/1.0",
        "valid": not errors,
        "revision": state["revision"],
        "valid_prefix_count": len(records),
        "events": selected,
        "errors": errors,
    }

def wait_for_revision(self, after_revision: int, timeout_seconds: float) -> dict[str, Any]:
    """Wait without polling the backend and then return a verified replay delta."""
    if timeout_seconds <= 0 or timeout_seconds > 300:
        raise ValueError("subscription timeout must be between zero and 300 seconds")
    deadline = time.monotonic() + timeout_seconds
    with self._condition:
        while int(self._state()["revision"]) <= after_revision:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                break
            self._condition.wait(remaining)
    return self.replay(after_revision=after_revision)

previous_controls_sha256 = str(payload.get("previous_controls_sha256") or "").lower()
current_controls = list(map(str, current["known_controls"]))
previous_control_records = dict(current.get("control_records", {}))
if previous_controls_sha256 != _controls_sha256(current_controls):
    raise ValueError("surface inventory revision does not bind its predecessor")
controls, records = _validate_control_records(payload.get("controls"))
removed_controls = set(current_controls) - set(controls)
restored_controls = set(controls) - set(current_controls)
for control_id in sorted(restored_controls & set(current["retired_controls"])):
    prior_retirement = current["retired_controls"].pop(control_id)
    current["retired_control_history"].append({
        **prior_retirement,
        "restored_at": event["timestamp"],
        "restored_by": event["actor"],
    })
    current["retired_control_history_count"] += 1
declared_retirement_schema = "retired_controls" in payload
retirement_rows = payload.get("retired_controls", [])
if not isinstance(retirement_rows, list) or any(
    not isinstance(item, Mapping) for item in retirement_rows
):
    raise ValueError("retired_controls must be an array of objects")
retirement_ids = [str(item.get("control_id") or "") for item in retirement_rows]
if declared_retirement_schema and (
    len(retirement_ids) != len(set(retirement_ids))
    or set(retirement_ids) != removed_controls
):
    raise ValueError("retired_controls must match the exact removed control set")
if not declared_retirement_schema:
    retirement_rows = [
        {
            "control_id": control_id,
            "reason": "Legacy pre-retirement-schema inventory revision.",
            "replacement_control_ids": [],
        }
        for control_id in sorted(removed_controls)
    ]
normalized_retirements: dict[str, dict[str, object]] = {}
for item in retirement_rows:
    control_id = str(item.get("control_id") or "")
    reason = str(item.get("reason") or "").strip()
    replacements = item.get("replacement_control_ids", [])
    _nonempty(reason, "retired control reason")
    if (
        not isinstance(replacements, list)
        or len(replacements) != len(set(map(str, replacements)))
        or any(str(replacement) not in controls for replacement in replacements)
    ):
        raise ValueError("retired control replacements must reference unique current controls")
    if control_id in current["retired_controls"]:
        raise ValueError("control was already retired")
    normalized_retirements[control_id] = {
        "reason": reason,
        "replacement_control_ids": sorted(map(str, replacements)),
    }
