            store, root / "policies/effect-grant-trust.json"
        )
        scope = EvidenceScope(
            str(request["project_id"]),
            str(request["outcome_id"]),
            str(request["task_id"]),
            str(request["execution_id"]),
            session_id=str(request.get("session_id", "")),
        )
        accepted = set(map(str, request["accepted_producers"]))
        max_age = int(request.get("max_age_seconds", 86400))
    except (OSError, KeyError, TypeError, ValueError, json.JSONDecodeError) as error:
        return _result(
            "invalid_request",
            reasons=[f"request_resolution_failed:{type(error).__name__}"],
        )

    policy = resolver.resolve(
        str(request["policy_decision_ref"]),
        scope=scope,
        accepted_producers=accepted,
        max_age_seconds=max_age,
        required_type="policy_decision",
    )
    if not policy.verified:
        reasons.extend(policy.reasons)
    elif policy.record.get("result", {}).get("allowed") is not True:
        reasons.append("policy_denied")

    refs = request.get("evidence_refs")
    if not isinstance(refs, list) or not refs:
        reasons.append("evidence_missing")
        refs = []
    resolved = []
    observed_checks: dict[str, bool] = {}
    for item in refs:
        if not isinstance(item, dict) or "ref" not in item:
            reasons.append("invalid_evidence_reference")
            continue
        value = resolver.resolve(
            str(item["ref"]),
            scope=scope,
            accepted_producers=accepted,
            max_age_seconds=max_age,
            expected_sha256=item.get("sha256"),
            required_type="postcondition",
        )
        resolved.append(value)
        reasons.extend(value.reasons)
        if value.verified:
            checks = value.record.get("result", {}).get("postconditions", {})
            if isinstance(checks, dict):
                for name, passed in checks.items():
                    observed_checks[str(name)] = passed is True
    failed = sorted(
        name for name in required_checks if observed_checks.get(name) is not True
    )
    if failed:
        reasons.extend(f"postcondition_failed:{name}" for name in failed)
    integrity_failure = any(
        "integrity" in reason or "hash_mismatch" in reason for reason in reasons
    )
    decision = (
        "evidence_integrity_failure"
        if integrity_failure
        else "insufficient_trusted_evidence"
        if reasons
        and any(
            reason
            in {
                "evidence_missing",
                "evidence_stale",
                "evidence_scope_mismatch",
                "evidence_producer_unapproved",
                "evidence_signature_missing",
                "evidence_signer_untrusted",
            }
            for reason in reasons
        )
        else "verification_failed"
        if reasons
        else "verified"
    )
    return _result(
        decision,
        reasons=reasons,
        policy={
            "resolved": policy.resolved,
            "authentic": policy.signature_valid,
            "applicable": policy.scope_valid
            and policy.record is not None
            and policy.record.get("result", {}).get("allowed") is True,
        },
        evidence={
            "requested": len(refs),
            "resolved": sum(item.resolved for item in resolved),
            "integrity_valid": sum(item.integrity_valid for item in resolved),
            "fresh": sum(item.fresh for item in resolved),
            "scope_valid": sum(item.scope_valid for item in resolved),
            "verified_ids": [
                str(item.record.get("evidence_id"))
                for item in resolved
                if item.verified
            ],
        },
        postconditions={
            "contract_resolved": True,
            "required": list(required_checks),
            "observed": observed_checks,
            "passed": not failed,
        },
    )

"""Locate framework assets in a source checkout or installed distribution."""

from __future__ import annotations

from pathlib import Path
import sysconfig


SOURCE_ONLY_ROOTS = {"extension", "tests", "scripts"}


def framework_root() -> Path:
    source = Path(__file__).resolve().parents[1]
    if (source / "bootstrap" / "startup.toml").is_file():
        return source
    installed = Path(sysconfig.get_path("data")) / "share" / "engineering-bootstrap"
    if (installed / "bootstrap" / "startup.toml").is_file():
        return installed
    raise FileNotFoundError("engineering bootstrap framework assets are not installed")


def is_source_checkout(root: Path) -> bool:
    root = root.resolve()
    return (root / "pyproject.toml").is_file() and (root / "runtime").is_dir()


def resolve_declared_path(root: Path, relative: str | Path) -> Path | None:
    """Resolve a source declaration against source or lean installed layouts.

    Tests and release-build scripts are deliberate sdist-only declarations and
    therefore have no normal runtime-wheel path.
    """
    root = root.resolve()
    value = Path(relative)
    if value.is_absolute() or ".." in value.parts:
        raise ValueError(f"declared framework path must be relative: {relative}")
    if is_source_checkout(root):
        return root / value
    parts = value.parts
    if not parts:
        return root
    package_root = Path(__file__).resolve().parent
    if parts[0] == "runtime":
        return package_root.joinpath(*parts[1:])
    if parts[0] == "builders":
        return package_root.joinpath("builders", *parts[1:])
    if parts[0] in SOURCE_ONLY_ROOTS:
        return None
    return root / value


def declared_file_available(root: Path, relative: str | Path) -> bool:
    resolved = resolve_declared_path(root, relative)
    return resolved is None or resolved.is_file()


def resolve_repository_relative(root: Path, relative: object) -> Path | None:
    """Resolve one repository-relative path without permitting an escape."""
    if not isinstance(relative, str) or not relative or "\\" in relative:
        return None
    resolved_root = root.resolve()
    path = (resolved_root / relative).resolve()
    try:
        path.relative_to(resolved_root)
    except ValueError:
        return None
    return path

def declared_file_available(root: Path, relative: str | Path) -> bool:
    resolved = resolve_declared_path(root, relative)
    return resolved is None or resolved.is_file()

def resolve_declared_path(root: Path, relative: str | Path) -> Path | None:
    """Resolve a source declaration against source or lean installed layouts.

    Tests and release-build scripts are deliberate sdist-only declarations and
    therefore have no normal runtime-wheel path.
    """
    root = root.resolve()
    value = Path(relative)
    if value.is_absolute() or ".." in value.parts:
        raise ValueError(f"declared framework path must be relative: {relative}")
    if is_source_checkout(root):
        return root / value
    parts = value.parts
    if not parts:
        return root
    package_root = Path(__file__).resolve().parent
    if parts[0] == "runtime":
        return package_root.joinpath(*parts[1:])
    if parts[0] == "builders":
        return package_root.joinpath("builders", *parts[1:])
    if parts[0] in SOURCE_ONLY_ROOTS:
        return None
    return root / value

"""Frozen, resumable work-package planning with explicit requirement coverage."""

from __future__ import annotations

from dataclasses import asdict, dataclass
import hashlib
import json
from pathlib import Path
from typing import Iterable, Mapping


@dataclass(frozen=True, slots=True)
class Requirement:
    requirement_id: str
    text: str
    capability_id: str | None
    state: str = "missing"


@dataclass(frozen=True, slots=True)
class WorkNode:
    node_id: str
    requirement_id: str
    capability_id: str | None
    dependencies: tuple[str, ...]
    tests: tuple[str, ...]
    evidence: tuple[str, ...]
    status: str


@dataclass(frozen=True, slots=True)
class WorkPackage:
    package_id: str
    goal: str
    requirements_hash: str
    nodes: tuple[WorkNode, ...]
    blocked_requirements: tuple[str, ...]
    deferred_discoveries: tuple[str, ...]
    frozen: bool = True


def _fingerprint(requirements: Iterable[Requirement]) -> str:
    payload = json.dumps(
        [asdict(item) for item in requirements], sort_keys=True, separators=(",", ":")
    )
    return hashlib.sha256(payload.encode()).hexdigest()


def build_work_package(
    goal: str,
    requirements: Iterable[Requirement],
    *,
    dependency_map: Mapping[str, tuple[str, ...]] | None = None,
    deferred: Iterable[str] = (),
) -> WorkPackage:
    requirements = tuple(sorted(requirements, key=lambda item: item.requirement_id))
    if not goal.strip() or not requirements:
        raise ValueError("goal and at least one requirement are required")
    if any(
        item.state not in {"existing", "partial", "missing", "blocked"}
        for item in requirements
    ):
        raise ValueError("unknown requirement state")
    dependencies = dependency_map or {}
    nodes = tuple(
        WorkNode(
            "work-" + item.requirement_id,
            item.requirement_id,
            item.capability_id,
            tuple(sorted(dependencies.get(item.requirement_id, ()))),
            ("positive", "negative", "effect-boundary"),
            ("deterministic-summary",),
            "complete"
            if item.state == "existing"
            else (
                "blocked"
                if item.capability_id is None or item.state == "blocked"
                else "pending"
            ),
        )
        for item in requirements
    )
    blocked = tuple(
        item.requirement_id
        for item in requirements
        if item.capability_id is None or item.state == "blocked"
    )
    digest = _fingerprint(requirements)
    return WorkPackage(
        digest[:16], goal, digest, nodes, blocked, tuple(sorted(set(deferred)))
    )


def save_work_package(package: WorkPackage, path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("x", encoding="utf-8", newline="\n") as stream:
        stream.write(json.dumps(asdict(package), indent=2) + "\n")


def load_work_package(path: Path) -> WorkPackage:
    payload = json.loads(path.read_text(encoding="utf-8"))
    return WorkPackage(
        payload["package_id"],
        payload["goal"],
        payload["requirements_hash"],
        tuple(
            WorkNode(
                **{
                    **item,
                    "dependencies": tuple(item["dependencies"]),
                    "tests": tuple(item["tests"]),
                    "evidence": tuple(item["evidence"]),
                }
            )
            for item in payload["nodes"]
        ),
        tuple(payload["blocked_requirements"]),
        tuple(payload["deferred_discoveries"]),
        payload["frozen"],
    )


def detect_scope_drift(
    package: WorkPackage, requirements: Iterable[Requirement]
) -> bool:
    return package.requirements_hash != _fingerprint(
        tuple(sorted(requirements, key=lambda item: item.requirement_id))
    )

