"""Conservative static lint for duplicate canonical primitive definitions."""

from __future__ import annotations

import ast
from datetime import datetime, timezone
from pathlib import Path
from typing import Iterable, Mapping

from .primitive_authority import (
    load_primitive_authority,
    validate_primitive_authority,
)


def _time(value: object) -> datetime | None:
    try:
        parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except ValueError:
        return None
    return parsed if parsed.tzinfo is not None else None


def validate_primitive_exceptions(
    registry: Mapping[str, object], *, now_utc: datetime | None = None
) -> dict[str, object]:
    """Require every duplicate-authority exception to be exact and unexpired."""
    now = now_utc or datetime.now(timezone.utc)
    errors: list[str] = []
    count = 0
    for record in registry.get("primitives", []):
        if not isinstance(record, Mapping):
            continue
        primitive = str(record.get("primitive") or "")
        for exception in record.get("bypass_exceptions", []):
            count += 1
            if not isinstance(exception, Mapping):
                errors.append(f"{primitive}: exception must be an object")
                continue
            owner = exception.get("owner")
            if not isinstance(owner, Mapping):
                errors.append(f"{primitive}: exception owner is required")
                continue
            path = str(owner.get("path") or "")
            symbol = str(owner.get("symbol") or "")
            if not path or not symbol or any(marker in path + symbol for marker in ("*", "?", "[")):
                errors.append(f"{primitive}: broad or incomplete exception owner")
            expiry = _time(exception.get("expires_utc"))
            if expiry is None or expiry <= now:
                errors.append(f"{primitive}: exception is invalid or expired")
    return {"valid": not errors, "exception_count": count, "errors": errors}


def _definitions(tree: ast.AST) -> Iterable[tuple[str, ast.AST]]:
    def walk(body: list[ast.stmt], prefix: str = ""):
        for node in body:
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                qualified = f"{prefix}.{node.name}" if prefix else node.name
                if not isinstance(node, ast.ClassDef):
                    yield qualified, node
                else:
                    yield from walk(node.body, qualified)

    yield from walk(tree.body)  # type: ignore[attr-defined]


def scan_duplicate_primitives(
    root: Path,
    *,
    registry: Mapping[str, object] | None = None,
    candidate_paths: Iterable[Path] | None = None,
) -> dict[str, object]:
    """Flag exact-name duplicate definitions and unresolved dynamic lookups."""
    root = root.resolve()
    authority = dict(registry) if registry is not None else load_primitive_authority(root)
    authority_report = validate_primitive_authority(root, authority)
    exception_report = validate_primitive_exceptions(authority)
    if not authority_report["valid"] or not exception_report["valid"]:
        return {
            "schema_version": "px.primitive-lint/1.0",
            "valid": False,
            "findings": [],
            "aliases": [],
            "errors": [*authority_report["errors"], *exception_report["errors"]],
        }
    primitives: dict[str, tuple[str, str, str]] = {}
    exceptions: set[tuple[str, str, str]] = set()
    for record in authority["primitives"]:
        owner = record["canonical_owner"]
        primitive = str(record["primitive"])
        primitives[str(owner["symbol"]).rsplit(".", 1)[-1]] = (
            primitive,
            str(owner["path"]),
            str(owner["symbol"]),
        )
        for exception in record.get("bypass_exceptions", []):
            exception_owner = exception["owner"]
            exceptions.add(
                (primitive, str(exception_owner["path"]), str(exception_owner["symbol"]))
            )
    paths = (
        sorted(path.resolve() for path in candidate_paths)
        if candidate_paths is not None
        else sorted(
            path.resolve()
            for directory in (root / "runtime", root / "scripts")
            if directory.is_dir()
            for path in directory.rglob("*.py")
            if "__pycache__" not in path.parts
        )
    )
    findings: list[dict[str, object]] = []
    aliases: list[dict[str, object]] = []
    for path in paths:
        try:
            relative = path.relative_to(root).as_posix()
        except ValueError:
            relative = f"<external>/{path.name}"
        try:
            tree = ast.parse(path.read_text(encoding="utf-8-sig"), filename=relative)
        except (OSError, SyntaxError, UnicodeError) as error:
            findings.append(
                {"kind": "ambiguity", "path": relative, "reason": f"uninspectable:{error}"}
            )
            continue
        for qualified, node in _definitions(tree):
            leaf = qualified.rsplit(".", 1)[-1]
            if leaf not in primitives:
                continue
            primitive, owner_path, owner_symbol = primitives[leaf]
            if (relative, qualified) == (owner_path, owner_symbol):
                continue
            if (primitive, relative, qualified) in exceptions:
                continue
            findings.append(
                {
                    "kind": "duplicate_definition",
                    "primitive": primitive,
                    "path": relative,
                    "symbol": qualified,
                    "line": getattr(node, "lineno", None),
                    "canonical_owner": f"{owner_path}:{owner_symbol}",
                }
            )
        for node in ast.walk(tree):
            if isinstance(node, (ast.Assign, ast.AnnAssign)):
                value = node.value
                if isinstance(value, ast.Name) and value.id in primitives:
                    aliases.append(
                        {"path": relative, "target": value.id, "line": node.lineno}
                    )
            if (
                isinstance(node, ast.Call)
                and isinstance(node.func, ast.Name)
                and node.func.id == "getattr"
                and len(node.args) >= 2
                and isinstance(node.args[1], ast.Constant)
                and node.args[1].value in primitives
            ):
                findings.append(
                    {
                        "kind": "dynamic_ambiguity",
                        "primitive": primitives[str(node.args[1].value)][0],
                        "path": relative,
                        "line": node.lineno,
                    }
                )
    findings.sort(key=lambda item: (str(item.get("path")), int(item.get("line") or 0)))
    aliases.sort(key=lambda item: (str(item["path"]), int(item["line"])))
    return {
        "schema_version": "px.primitive-lint/1.0",
        "valid": not findings,
        "finding_count": len(findings),
        "findings": findings,
        "aliases": aliases,
        "errors": [],
    }

def _definitions(tree: ast.AST) -> Iterable[tuple[str, ast.AST]]:
    def walk(body: list[ast.stmt], prefix: str = ""):
        for node in body:
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                qualified = f"{prefix}.{node.name}" if prefix else node.name
                if not isinstance(node, ast.ClassDef):
                    yield qualified, node
                else:
                    yield from walk(node.body, qualified)

    yield from walk(tree.body)  # type: ignore[attr-defined]

def scan_duplicate_primitives(
    root: Path,
    *,
    registry: Mapping[str, object] | None = None,
    candidate_paths: Iterable[Path] | None = None,
) -> dict[str, object]:
    """Flag exact-name duplicate definitions and unresolved dynamic lookups."""
    root = root.resolve()
    authority = dict(registry) if registry is not None else load_primitive_authority(root)
    authority_report = validate_primitive_authority(root, authority)
    exception_report = validate_primitive_exceptions(authority)
    if not authority_report["valid"] or not exception_report["valid"]:
        return {
            "schema_version": "px.primitive-lint/1.0",
            "valid": False,
            "findings": [],
            "aliases": [],
            "errors": [*authority_report["errors"], *exception_report["errors"]],
        }
    primitives: dict[str, tuple[str, str, str]] = {}
    exceptions: set[tuple[str, str, str]] = set()
    for record in authority["primitives"]:
        owner = record["canonical_owner"]
        primitive = str(record["primitive"])
        primitives[str(owner["symbol"]).rsplit(".", 1)[-1]] = (
            primitive,
            str(owner["path"]),
            str(owner["symbol"]),
        )
        for exception in record.get("bypass_exceptions", []):
            exception_owner = exception["owner"]
            exceptions.add(
                (primitive, str(exception_owner["path"]), str(exception_owner["symbol"]))
            )
    paths = (
        sorted(path.resolve() for path in candidate_paths)
        if candidate_paths is not None
        else sorted(
            path.resolve()
            for directory in (root / "runtime", root / "scripts")
            if directory.is_dir()
            for path in directory.rglob("*.py")
            if "__pycache__" not in path.parts
        )
    )
    findings: list[dict[str, object]] = []
    aliases: list[dict[str, object]] = []
    for path in paths:
        try:
            relative = path.relative_to(root).as_posix()
        except ValueError:
            relative = f"<external>/{path.name}"
        try:
            tree = ast.parse(path.read_text(encoding="utf-8-sig"), filename=relative)
        except (OSError, SyntaxError, UnicodeError) as error:
            findings.append(
                {"kind": "ambiguity", "path": relative, "reason": f"uninspectable:{error}"}
            )
            continue
        for qualified, node in _definitions(tree):
            leaf = qualified.rsplit(".", 1)[-1]
            if leaf not in primitives:
                continue
            primitive, owner_path, owner_symbol = primitives[leaf]
            if (relative, qualified) == (owner_path, owner_symbol):
                continue
            if (primitive, relative, qualified) in exceptions:
                continue
            findings.append(
                {
                    "kind": "duplicate_definition",
                    "primitive": primitive,
                    "path": relative,
                    "symbol": qualified,
                    "line": getattr(node, "lineno", None),
                    "canonical_owner": f"{owner_path}:{owner_symbol}",
                }
            )
        for node in ast.walk(tree):
            if isinstance(node, (ast.Assign, ast.AnnAssign)):
                value = node.value
                if isinstance(value, ast.Name) and value.id in primitives:
                    aliases.append(
                        {"path": relative, "target": value.id, "line": node.lineno}
                    )
            if (
                isinstance(node, ast.Call)
                and isinstance(node.func, ast.Name)
                and node.func.id == "getattr"
                and len(node.args) >= 2
                and isinstance(node.args[1], ast.Constant)
                and node.args[1].value in primitives
            ):
                findings.append(
                    {
                        "kind": "dynamic_ambiguity",
                        "primitive": primitives[str(node.args[1].value)][0],
                        "path": relative,
                        "line": node.lineno,
                    }
                )
    findings.sort(key=lambda item: (str(item.get("path")), int(item.get("line") or 0)))
    aliases.sort(key=lambda item: (str(item["path"]), int(item["line"])))
    return {
        "schema_version": "px.primitive-lint/1.0",
        "valid": not findings,
        "finding_count": len(findings),
        "findings": findings,
        "aliases": aliases,
        "errors": [],
    }

def validate_primitive_exceptions(
    registry: Mapping[str, object], *, now_utc: datetime | None = None
) -> dict[str, object]:
    """Require every duplicate-authority exception to be exact and unexpired."""
    now = now_utc or datetime.now(timezone.utc)
    errors: list[str] = []
    count = 0
    for record in registry.get("primitives", []):
        if not isinstance(record, Mapping):
            continue
        primitive = str(record.get("primitive") or "")
        for exception in record.get("bypass_exceptions", []):
            count += 1
            if not isinstance(exception, Mapping):
                errors.append(f"{primitive}: exception must be an object")
                continue
            owner = exception.get("owner")
            if not isinstance(owner, Mapping):
                errors.append(f"{primitive}: exception owner is required")
                continue
            path = str(owner.get("path") or "")
            symbol = str(owner.get("symbol") or "")
            if not path or not symbol or any(marker in path + symbol for marker in ("*", "?", "[")):
                errors.append(f"{primitive}: broad or incomplete exception owner")
            expiry = _time(exception.get("expires_utc"))
            if expiry is None or expiry <= now:
                errors.append(f"{primitive}: exception is invalid or expired")
    return {"valid": not errors, "exception_count": count, "errors": errors}

def compile_process_candidate(root: Path, record: dict[str, Any]) -> dict[str, Any]:
    validate_instance(record, root / "contracts/engineering-process-record.schema.json")
    if record["verification"]["outcome_met"] is not True:
        return {
            "valid": False,
            "decision": "reject_unverified",
            "errors": ["outcome is not verified"],
            "activation": "blocked",
        }
    if any(item["verified"] is not True for item in record["failures"]):
        return {
            "valid": False,
            "decision": "reject_unverified_recovery",
            "errors": ["a failure recovery is unverified"],
            "activation": "blocked",
        }
    canonical = json.dumps(
        record, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")
    process_hash = hashlib.sha256(canonical).hexdigest()
    catalog = tomllib.loads(
        (root / "registry/skill_catalog.toml").read_text(encoding="utf-8")
    )
    process_terms = _terms(
        " ".join(
            [
                record["goal"],
                record["outcome"],
                record["reusable_pattern"],
                *record["steps"],
            ]
        )
    )
    matches: list[tuple[float, str]] = []
    for skill in catalog.get("skills", ()):
        skill_terms = _terms(
            " ".join([str(skill.get("id", "")), *map(str, skill.get("tags", ()))])
        )
        union = process_terms | skill_terms
        score = len(process_terms & skill_terms) / len(union) if union else 0.0
        matches.append((score, str(skill["id"])))
    score, existing = max(
        matches, default=(0.0, ""), key=lambda item: (item[0], item[1])
    )
    decision = "improve_existing" if score >= 0.20 else "create_candidate"
    candidate_id = (
        existing
        if decision == "improve_existing"
        else _slug(record["reusable_pattern"])
    )
    decisions = [
        {
            "order": index,
            "decision": item["decision"],
            "reason": item["reason"],
            "alternatives": item["alternatives"],
        }
        for index, item in enumerate(record["decisions"])
    ]
    tools = [{"order": index, **item} for index, item in enumerate(record["tools"])]
    execution = [
        {"order": index, "step": step, "depends_on": [] if index == 0 else [index - 1]}
        for index, step in enumerate(record["steps"])
    ]
    return {
        "valid": True,
        "decision": decision,
        "candidate": {
            "id": candidate_id,
            "status": "candidate",
            "auto_activate": False,
            "source_process_sha256": process_hash,
            "goal": record["goal"],
            "procedure": record["steps"],
            "verification": record["verification"],
            "failure_recovery": record["failures"],
            "evidence": record["evidence"],
            "similarity": {
                "existing_skill": existing or None,
                "score": round(score, 6),
            },
        },
        "decision_graph": decisions,
        "tool_graph": tools,
        "execution_graph": execution,
        "activation": "requires_skill_admission_controller",
        "errors": [],
    }

def record_process_candidate(
    root: Path, project: Path, record: dict[str, Any], *, apply: bool = False
) -> dict[str, Any]:
    project = project.resolve()
    state_path = project / ".engineering-bootstrap/project-management/state.json"
    if not state_path.is_file():
        raise ValueError("project is not commissioned")
    result = compile_process_candidate(root, record)
    result = {**result, "apply": apply, "project": project.as_posix()}
    if not result["valid"] or not apply:
        return result
    digest = result["candidate"]["source_process_sha256"]
    relative = (
        Path(".engineering-bootstrap/project-management/process") / f"{digest}.json"
    )
    target = project / relative
    target.parent.mkdir(parents=True, exist_ok=True)
    payload = {"schema_version": "1.0", "process": record, "compilation": result}
    rendered = json.dumps(payload, indent=2, ensure_ascii=False) + "\n"
    if target.exists() and target.read_text(encoding="utf-8") != rendered:
        raise ValueError("process receipt hash collision or drift")
    target.write_text(rendered, encoding="utf-8")
    state = json.loads(state_path.read_text(encoding="utf-8"))
    records = state.setdefault("evidence", {}).setdefault("process_records", [])
    path_text = relative.as_posix()
    if path_text not in records:
        records.append(path_text)
        records.sort()
    validate_instance(state, root / "contracts/project-management.schema.json")
    state_path.write_text(
        json.dumps(state, indent=2, ensure_ascii=False) + "\n", encoding="utf-8"
    )
    return {**result, "receipt": path_text}

def validate(self) -> None:
    timeouts = (
        self.startup_timeout_seconds,
        self.idle_timeout_seconds,
        self.total_timeout_seconds,
        self.graceful_shutdown_seconds,
        self.force_shutdown_seconds,
        self.poll_interval_seconds,
    )
    if any(value <= 0 or value > MAX_TIMEOUT_SECONDS for value in timeouts):
        raise ValueError("process timeout budget is outside hard bounds")
    if self.startup_timeout_seconds > self.total_timeout_seconds:
        raise ValueError("startup timeout exceeds total timeout")
    if self.idle_timeout_seconds > self.total_timeout_seconds:
        raise ValueError("idle timeout exceeds total timeout")
    if not 1 <= self.stdout_limit_bytes <= MAX_CAPTURE_BYTES:
        raise ValueError("stdout byte budget is outside hard bounds")
    if not 1 <= self.stderr_limit_bytes <= MAX_CAPTURE_BYTES:
        raise ValueError("stderr byte budget is outside hard bounds")
    if not 1 <= self.disk_consumption_limit_bytes <= MAX_DISK_CONSUMPTION_LIMIT_BYTES:
        raise ValueError("disk-consumption byte budget is outside hard bounds")

class ProcessSupervisor:
    """Execute one pre-authorized action inside a bounded owned process tree."""

    def __init__(self, manager: ResourceManager) -> None:
        self.manager = manager

    @staticmethod
    def command_plan(
        command: Sequence[str], *, platform: str | None = None
    ) -> dict[str, object]:
        active = platform or ("windows" if os.name == "nt" else "posix")
        if active not in {"windows", "posix"}:
            raise ValueError("unsupported process platform")
        if not command or any(
            not isinstance(item, str) or not item or "\0" in item for item in command
        ):
            raise ValueError("command must be a non-empty argv sequence")
        return {
            "platform": active,
            "argv_count": len(command),
            "shell": False,
            "tree_boundary": "job_object"
            if active == "windows"
            else "new_session_process_group",
        }

    def _authorize(
        self, action: Mapping[str, object], cwd: Path
    ) -> tuple[ProcessBudgets, str, tuple[Path, ...]]:
        if (
            not isinstance(action.get("action_id"), str)
            or not str(action["action_id"]).strip()
        ):
            raise ValueError("typed action_id is required")
        decision = supervise_action(action)
        if decision.decision != "allow":
            raise PermissionError(
                f"contained execution {decision.decision}: {','.join(decision.reasons)}"
            )
        effects = set(map(str, action.get("effects", ())))
        if "process" not in effects:
            raise PermissionError("process effect was not declared")
        if action.get("approval") is not True:
            raise PermissionError("explicit supplied process authority is required")
        owned = tuple(
            Path(str(item)).resolve(strict=True)
            for item in action.get("owned_paths", ())
        )
        resolved_cwd = cwd.resolve(strict=True)
        if not resolved_cwd.is_dir() or not any(
            _inside(resolved_cwd, root) for root in owned
        ):
            raise PermissionError("process cwd is outside supplied owned paths")
        for target in action.get("target_paths", ()):
            resolved_target = Path(str(target)).resolve(strict=False)
            if not any(_inside(resolved_target, root) for root in owned):
                raise PermissionError("process target is outside supplied owned paths")
        raw_disk_paths = action.get("disk_consumption_paths", ())
        if not isinstance(raw_disk_paths, (list, tuple)) or len(raw_disk_paths) > 32:
            raise ValueError("disk-consumption paths must be a bounded sequence")
        disk_paths = tuple(
            Path(str(item)).resolve(strict=False) for item in raw_disk_paths
        )
        if any(not any(_inside(path, root) for root in owned) for path in disk_paths):
            raise PermissionError(
                "disk-consumption accounting path is outside supplied owned paths"
            )
        budget = ProcessBudgets.from_mapping(dict(action.get("budget", {})))
        limits = ProcessBudgets.from_mapping(dict(action.get("limits", {})))
        for field in ProcessBudgets.__dataclass_fields__:
            if getattr(budget, field) > getattr(limits, field):
                raise PermissionError(f"process budget exceeds limit: {field}")
        return budget, str(decision.outputs["audit_record_hash"]), disk_paths

    def _receipt(self, result: ProcessResult) -> str:
        receipt_id = f"process-{uuid4().hex}"
        path = self.manager.receipt_dir / f"{receipt_id}.json"
        path.parent.mkdir(parents=True, exist_ok=True)
        payload = {
            "schema_version": "px.process-supervision-receipt/1.0",
            "receipt_id": receipt_id,
            "action_id": result.action_id,
            "resource_id": result.resource_id,
            "status": result.status,
            "exit_code": result.exit_code,
            "started_at": result.started_at,
            "ended_at": result.ended_at,
            "duration_seconds": result.duration_seconds,
            "stdout": {
                key: value
                for key, value in asdict(result.stdout).items()
                if key != "text"
            },
            "stderr": {
                key: value
                for key, value in asdict(result.stderr).items()
                if key != "text"
            },
            "shutdown_mode": result.shutdown_mode,
            "tree_closed": result.tree_closed,
            "failure_type": result.failure_type,
            "audit_record_hash": result.audit_record_hash,
        }
        temporary = path.with_suffix(f".{uuid4().hex}.tmp")
        with temporary.open("x", encoding="utf-8", newline="\n") as stream:
            json.dump(payload, stream, sort_keys=True, indent=2)
            stream.write("\n")
            stream.flush()
            os.fsync(stream.fileno())
        # A failed atomic promotion deliberately retains the uniquely named
        # prepared record for normal resource-lifecycle reconciliation.
        os.replace(temporary, path)
        return str(path)

    @staticmethod
    def _discover_posix_descendants(root_pid: int) -> dict[int, str]:
        if os.name == "nt" or not Path("/proc").is_dir():
            return {}
        parents: dict[int, int] = {}
        for entry in Path("/proc").iterdir():
            if not entry.name.isdigit():
                continue
            try:
                stat = (entry / "stat").read_text(encoding="ascii")
                close = stat.rfind(")")
                fields = stat[close + 2 :].split()
                parents[int(entry.name)] = int(fields[1])
            except (OSError, UnicodeError, ValueError, IndexError):
                continue
        found: set[int] = {root_pid}
        changed = True
        while changed:
            changed = False
            for pid, parent in parents.items():
                if parent in found and pid not in found:
                    found.add(pid)
                    changed = True
        return {
            pid: fingerprint
            for pid in found
            if (fingerprint := _process_start_fingerprint(pid)) is not None
        }

    @staticmethod
    def _signal_proven_posix(tracked: Mapping[int, str], sig: int) -> None:
        for pid, expected in sorted(tracked.items(), reverse=True):
            if _process_start_fingerprint(pid) != expected:
                continue
            try:
                os.kill(pid, sig)
            except ProcessLookupError:
                pass

    def _shutdown(
        self,
        process: subprocess.Popen[object],
        fingerprint: str,
        tracked: dict[int, str],
        job: _WindowsJob | None,
        budget: ProcessBudgets,
    ) -> tuple[str, bool]:
        if (
            process.poll() is None
            and _process_start_fingerprint(process.pid) == fingerprint
        ):
            try:
                if os.name == "nt":
                    process.send_signal(signal.CTRL_BREAK_EVENT)
                else:
                    os.killpg(process.pid, signal.SIGTERM)
                    self._signal_proven_posix(tracked, signal.SIGTERM)
            except OSError:
                pass
        try:
            process.wait(timeout=budget.graceful_shutdown_seconds)
            mode = "graceful"
        except subprocess.TimeoutExpired:
            mode = "forced"
        if os.name != "nt":
            tracked.update(self._discover_posix_descendants(process.pid))
            survivors = {
                pid: value
                for pid, value in tracked.items()
                if pid != process.pid and _process_start_fingerprint(pid) == value
            }
        else:
            survivors = {}
            if mode != "forced" and job is not None and job.active_processes() > 0:
                job.terminate()
                if not job.wait_closed(
                    budget.force_shutdown_seconds, budget.poll_interval_seconds
                ):
                    return "forced_failed", False
        if mode == "forced" or survivors:
            mode = "forced"
            try:
                if job is not None:
                    try:
                        job.terminate()
                    except OSError:
                        # TerminateJobObject can be denied by a containing host
                        # policy even though this supervisor still owns the
                        # exact Popen process handle.  Kill that root through
                        # the retained handle; its nested kill-on-close jobs
                        # then close their own descendants.
                        if (
                            process.poll() is None
                            and _process_start_fingerprint(process.pid) == fingerprint
                        ):
                            process.kill()
                        else:
                            raise
                elif (
                    os.name == "nt"
                    and _process_start_fingerprint(process.pid) == fingerprint
                ):
                    subprocess.run(
                        ["taskkill", "/PID", str(process.pid), "/T", "/F"],
                        stdout=subprocess.DEVNULL,
                        stderr=subprocess.DEVNULL,
                        timeout=budget.force_shutdown_seconds,
                        check=False,
                        shell=False,
                    )
                else:
                    try:
                        os.killpg(process.pid, signal.SIGKILL)
                    except OSError:
                        pass
                    self._signal_proven_posix(tracked, signal.SIGKILL)
                process.wait(timeout=budget.force_shutdown_seconds)
                if job is not None and not job.wait_closed(
                    budget.force_shutdown_seconds, budget.poll_interval_seconds
                ):
                    return "forced_failed", False
            except (OSError, subprocess.SubprocessError):
                return "forced_failed", False
        if os.name != "nt":
            deadline = time.monotonic() + budget.force_shutdown_seconds
            while time.monotonic() < deadline:
                live = [
                    pid
                    for pid, value in tracked.items()
                    if pid != process.pid and _process_start_fingerprint(pid) == value
                ]
                if not live:
                    break
                time.sleep(min(0.02, budget.poll_interval_seconds))
            else:
                return "forced_failed", False
        return mode, process.poll() is not None

    def run(
        self,
        command: Sequence[str],
        *,
        cwd: Path,
        action: Mapping[str, object],
        project_id: str,
        run_id: str,
        lane_id: str,
        creator: str,
        environment: Mapping[str, str] | None = None,
        cancel_event: threading.Event | None = None,
    ) -> ProcessResult:
        self.command_plan(command)
        budget, audit_hash, disk_paths = self._authorize(action, cwd)
        # ``run`` executes in the process that owns and supervises the child.
        # Its own PID is the custody identity.  Using getppid() binds the child
        # to the supervisor's launcher, which is intentionally short-lived for
        # durable Studio workers and therefore creates false owner-loss kills.
        owner_pid = os.getpid()
        owner_fingerprint = _process_start_fingerprint(owner_pid)
        owner_liveness = _open_owner_liveness(owner_pid)
        if owner_fingerprint is None and owner_liveness is None:
            raise RuntimeError("supervising process identity cannot be proven")
        disk_root = Path(cwd.resolve(strict=True).anchor or cwd.resolve(strict=True))
        initial_disk_free = shutil.disk_usage(disk_root).free
        initial_owned_consumption = (
            _disk_consumption_bytes(disk_paths) if disk_paths else None
        )
        action_id = str(action["action_id"])
        started_at = _now()
        started = time.monotonic()
        empty = CaptureResult("", 0, 0, 0, 0, False)
        try:
            record, process = self.manager.spawn_owned_process(
                command,
                cwd=cwd.resolve(strict=True),
                project_id=project_id,
                run_id=run_id,
                lane_id=lane_id,
                creator=creator,
                environment=environment,
                text=False,
                start_suspended=os.name == "nt",
            )
        except (OSError, subprocess.SubprocessError) as error:
            if owner_liveness is not None:
                owner_liveness.close()
            preliminary = ProcessResult(
                action_id,
                None,
                "spawn_failed",
                None,
                started_at,
                _now(),
                time.monotonic() - started,
                empty,
                empty,
                "not_started",
                True,
                type(error).__name__,
                audit_hash,
                None,
            )
            receipt = self._receipt(preliminary)
            return ProcessResult(
                **{
                    **asdict(preliminary),
                    "stdout": preliminary.stdout,
                    "stderr": preliminary.stderr,
                    "receipt_path": receipt,
                }
            )

        fingerprint = _process_start_fingerprint(process.pid)
        if fingerprint is None:
            # The live Popen handle remains exact in this process. Persist a
            # deliberately non-replayable identity so restart reconciliation
            # retains rather than killing an unproven PID.
            process_identity = f"owned-handle:{uuid4().hex}"
        else:
            process_identity = f"process-start:{fingerprint}"
        self.manager.update(record.resource_id, process_identity=process_identity)
        job: _WindowsJob | None = None
        try:
            if os.name == "nt":
                job = _WindowsJob(process)
                job.resume_process(process.pid)
        except OSError as error:
            if job is not None:
                try:
                    job.terminate()
                finally:
                    job.close()
            else:
                self.manager.terminate_owned_process(record.resource_id)
            if owner_liveness is not None:
                owner_liveness.close()
            raise RuntimeError(
                f"process containment setup failed ({type(error).__name__})"
            ) from None

        activity_lock = threading.Lock()
        supervision_started = time.monotonic()
        last_activity = [supervision_started]
        observed = [False]

        def activity() -> None:
            with activity_lock:
                observed[0] = True
                last_activity[0] = time.monotonic()

        stdout_capture = _BoundedCapture(budget.stdout_limit_bytes, activity)
        stderr_capture = _BoundedCapture(budget.stderr_limit_bytes, activity)
        threads = [
            threading.Thread(
                target=_drain, args=(process.stdout, stdout_capture), daemon=True
            ),
            threading.Thread(
                target=_drain, args=(process.stderr, stderr_capture), daemon=True
            ),
        ]
        for thread in threads:
            thread.start()

        status = "exited"
        shutdown_mode = "natural"
        tree_closed = True
        tracked = {process.pid: fingerprint}
        next_safety_check = supervision_started
        next_disk_check = supervision_started

        def terminal_safety_status(*, check_disk: bool) -> str | None:
            if owner_liveness is not None:
                owner_alive = owner_liveness.alive()
            elif owner_fingerprint is not None:
                owner_alive = (
                    _process_start_fingerprint(owner_pid) == owner_fingerprint
                )
            else:
                owner_alive = False
            if not owner_alive:
                return "owner_lost"
            if not check_disk:
                return None
            if initial_owned_consumption is not None:
                current_owned_consumption = _disk_consumption_bytes(disk_paths)
                if (
                    current_owned_consumption - initial_owned_consumption
                    > budget.disk_consumption_limit_bytes
                ):
                    return "disk_budget_exceeded"
            else:
                current_disk_free = shutil.disk_usage(disk_root).free
                if (
                    initial_disk_free - current_disk_free
                    > budget.disk_consumption_limit_bytes
                ):
                    return "disk_budget_exceeded"
            return None

        try:
            while process.poll() is None:
                now = time.monotonic()
                if os.name != "nt":
                    tracked.update(self._discover_posix_descendants(process.pid))
                with activity_lock:
                    has_activity, last = observed[0], last_activity[0]
                if cancel_event is not None and cancel_event.is_set():
                    status = "cancelled"
                    break
                if now >= next_safety_check:
                    next_safety_check = now + max(
                        0.25, budget.poll_interval_seconds
                    )
                    check_disk = now >= next_disk_check
                    if check_disk:
                        next_disk_check = now + max(
                            MIN_DISK_ACCOUNTING_INTERVAL_SECONDS,
                            budget.poll_interval_seconds,
                        )
                    safety_status = terminal_safety_status(check_disk=check_disk)
                    if safety_status is not None:
                        status = safety_status
                        break
                if now - supervision_started >= budget.total_timeout_seconds:
                    status = "total_timeout"
                    break
                if (
                    not has_activity
                    and now - supervision_started >= budget.startup_timeout_seconds
                ):
                    status = "startup_timeout"
                    break
                if has_activity and now - last >= budget.idle_timeout_seconds:
                    status = "idle_timeout"
                    break
                time.sleep(budget.poll_interval_seconds)
            # The child can exit while this supervisor thread is descheduled.
            # Reconcile hard terminal controls after poll() observes that exit;
            # otherwise an over-budget or cancelled process can be published as
            # a successful natural exit under host contention.
            if status == "exited":
                # A final unconditional disk measurement preserves the hard
                # ceiling for fast-exit commands while avoiding a recursive
                # full-tree walk on every 20 ms supervision poll.
                safety_status = terminal_safety_status(check_disk=True)
                if safety_status is not None:
                    status = safety_status
                elif cancel_event is not None and cancel_event.is_set():
                    status = "cancelled"
                elif (
                    time.monotonic() - supervision_started
                    >= budget.total_timeout_seconds
                ):
                    status = "total_timeout"
            if status != "exited":
                shutdown_mode, tree_closed = self._shutdown(
                    process, fingerprint, tracked, job, budget
                )
            elif os.name == "nt" and job is not None:
                # Closing a kill-on-close Job ensures descendants cannot outlive a
                # successfully exited root process.
                try:
                    job.terminate()
                    tree_closed = job.wait_closed(
                        budget.force_shutdown_seconds, budget.poll_interval_seconds
                    )
                except OSError:
                    tree_closed = False
            elif os.name != "nt":
                tracked.update(self._discover_posix_descendants(process.pid))
                survivors = {
                    pid: value for pid, value in tracked.items() if pid != process.pid
                }
                if survivors:
                    shutdown_mode, tree_closed = self._shutdown(
                        process, fingerprint, tracked, job, budget
                    )
        finally:
            if job is not None:
                job.close()
            if owner_liveness is not None:
                owner_liveness.close()
            for thread in threads:
                thread.join(timeout=budget.force_shutdown_seconds)

        failure_type = None if tree_closed else "ProcessTreeClosureError"
        if not tree_closed:
            status = "shutdown_failed"
            self.manager.update(
                record.resource_id,
                active=True,
                status=ResourceStatus.CLEANUP_FAILED.value,
                cleanup_result="process_tree_not_verified",
                retained_reason="process tree closure could not be proven",
            )
        else:
            self.manager.complete_process(record.resource_id)
            if status == "exited" and process.returncode not in {0, None}:
                self.manager.update(
                    record.resource_id,
                    run_state=RunState.FAILED.value,
                    cleanup_result=f"exit_{process.returncode}",
                )
            elif status != "exited":
                self.manager.update(
                    record.resource_id,
                    run_state=RunState.CANCELLED.value,
                    cleanup_result=f"{status}_{shutdown_mode}",
                )
        preliminary = ProcessResult(
            action_id=action_id,
            resource_id=record.resource_id,
            status=status,
            exit_code=process.returncode,
            started_at=started_at,
            ended_at=_now(),
            duration_seconds=time.monotonic() - started,
            stdout=stdout_capture.result(),
            stderr=stderr_capture.result(),
            shutdown_mode=shutdown_mode,
            tree_closed=tree_closed,
            failure_type=failure_type,
            audit_record_hash=audit_hash,
            receipt_path=None,
        )
        receipt = self._receipt(preliminary)
        return ProcessResult(
            **{
                **asdict(preliminary),
                "stdout": preliminary.stdout,
                "stderr": preliminary.stderr,
                "receipt_path": receipt,
            }
        )

    def reconcile_persisted(
        self,
        resource_id: str,
        *,
        supplied_authority: bool,
        timeout_seconds: float = 5.0,
    ) -> dict[str, object]:
        """Reap only a persisted PID whose start identity is still provable."""
        if supplied_authority is not True:
            raise PermissionError(
                "explicit supplied reconciliation authority is required"
            )
        record = self.manager.ledger.get(resource_id)
        if record.resource_type != "process" or not record.pid or not record.active:
            raise ValueError("resource is not an active persisted process")
        prefix = "process-start:"
        if not record.process_identity or not record.process_identity.startswith(
            prefix
        ):
            return {
                "status": "retained_unproven",
                "resource_id": resource_id,
                "tree_closed": False,
            }
        expected = record.process_identity[len(prefix) :]
        if not _process_exists(record.pid):
            self.manager.update(
                resource_id,
                active=False,
                run_state=RunState.ABANDONED.value,
                status=ResourceStatus.RECLAIMED.value,
                cleanup_result="persisted_process_already_absent",
            )
            return {
                "status": "already_absent",
                "resource_id": resource_id,
                "tree_closed": True,
            }
        if _process_start_fingerprint(record.pid) != expected:
            return {
                "status": "retained_unproven",
                "resource_id": resource_id,
                "tree_closed": False,
            }
        try:
            if os.name == "nt":
                completed = subprocess.run(
                    ["taskkill", "/PID", str(record.pid), "/T", "/F"],
                    text=True,
                    capture_output=True,
                    timeout=timeout_seconds,
                    check=False,
                    shell=False,
                )
                if completed.returncode not in {0, 128}:
                    diagnostic = (completed.stderr or completed.stdout).strip()
                    raise OSError(
                        f"taskkill exit {completed.returncode}: {diagnostic[:160]}"
                    )
            else:
                if os.getpgid(record.pid) != record.pid:
                    return {
                        "status": "retained_unproven",
                        "resource_id": resource_id,
                        "tree_closed": False,
                    }
                os.killpg(record.pid, signal.SIGKILL)
            deadline = time.monotonic() + timeout_seconds
            while _process_exists(record.pid) and time.monotonic() < deadline:
                time.sleep(0.02)
            if _process_exists(record.pid):
                raise OSError("verified process identity remains active")
        except (OSError, subprocess.SubprocessError) as error:
            self.manager.update(
                resource_id,
                status=ResourceStatus.CLEANUP_FAILED.value,
                retained_reason=f"reconciliation failed ({type(error).__name__})",
            )
            return {
                "status": "reconcile_failed",
                "resource_id": resource_id,
                "tree_closed": False,
                "failure_type": type(error).__name__,
                "failure_detail": str(error)[:256],
            }
        self.manager.update(
            resource_id,
            active=False,
            run_state=RunState.ABANDONED.value,
            status=ResourceStatus.RECLAIMED.value,
            cleanup_result="persisted_verified_process_tree_terminated",
        )
        return {"status": "reaped", "resource_id": resource_id, "tree_closed": True}

def _authorize(
    self, action: Mapping[str, object], cwd: Path
) -> tuple[ProcessBudgets, str, tuple[Path, ...]]:
    if (
        not isinstance(action.get("action_id"), str)
        or not str(action["action_id"]).strip()
    ):
        raise ValueError("typed action_id is required")
    decision = supervise_action(action)
    if decision.decision != "allow":
        raise PermissionError(
            f"contained execution {decision.decision}: {','.join(decision.reasons)}"
        )
    effects = set(map(str, action.get("effects", ())))
    if "process" not in effects:
        raise PermissionError("process effect was not declared")
    if action.get("approval") is not True:
        raise PermissionError("explicit supplied process authority is required")
    owned = tuple(
        Path(str(item)).resolve(strict=True)
        for item in action.get("owned_paths", ())
    )
    resolved_cwd = cwd.resolve(strict=True)
    if not resolved_cwd.is_dir() or not any(
        _inside(resolved_cwd, root) for root in owned
    ):
        raise PermissionError("process cwd is outside supplied owned paths")
    for target in action.get("target_paths", ()):
        resolved_target = Path(str(target)).resolve(strict=False)
        if not any(_inside(resolved_target, root) for root in owned):
            raise PermissionError("process target is outside supplied owned paths")
    raw_disk_paths = action.get("disk_consumption_paths", ())
    if not isinstance(raw_disk_paths, (list, tuple)) or len(raw_disk_paths) > 32:
        raise ValueError("disk-consumption paths must be a bounded sequence")
    disk_paths = tuple(
        Path(str(item)).resolve(strict=False) for item in raw_disk_paths
    )
    if any(not any(_inside(path, root) for root in owned) for path in disk_paths):
        raise PermissionError(
            "disk-consumption accounting path is outside supplied owned paths"
        )
    budget = ProcessBudgets.from_mapping(dict(action.get("budget", {})))
    limits = ProcessBudgets.from_mapping(dict(action.get("limits", {})))
    for field in ProcessBudgets.__dataclass_fields__:
        if getattr(budget, field) > getattr(limits, field):
            raise PermissionError(f"process budget exceeds limit: {field}")
    return budget, str(decision.outputs["audit_record_hash"]), disk_paths

def _shutdown(
    self,
    process: subprocess.Popen[object],
    fingerprint: str,
    tracked: dict[int, str],
    job: _WindowsJob | None,
    budget: ProcessBudgets,
) -> tuple[str, bool]:
    if (
        process.poll() is None
        and _process_start_fingerprint(process.pid) == fingerprint
    ):
        try:
            if os.name == "nt":
                process.send_signal(signal.CTRL_BREAK_EVENT)
            else:
                os.killpg(process.pid, signal.SIGTERM)
                self._signal_proven_posix(tracked, signal.SIGTERM)
        except OSError:
            pass
    try:
        process.wait(timeout=budget.graceful_shutdown_seconds)
        mode = "graceful"
    except subprocess.TimeoutExpired:
        mode = "forced"
    if os.name != "nt":
        tracked.update(self._discover_posix_descendants(process.pid))
        survivors = {
            pid: value
            for pid, value in tracked.items()
            if pid != process.pid and _process_start_fingerprint(pid) == value
        }
    else:
        survivors = {}
        if mode != "forced" and job is not None and job.active_processes() > 0:
            job.terminate()
            if not job.wait_closed(
                budget.force_shutdown_seconds, budget.poll_interval_seconds
            ):
                return "forced_failed", False
    if mode == "forced" or survivors:
        mode = "forced"
        try:
            if job is not None:
                try:
                    job.terminate()
                except OSError:
                    # TerminateJobObject can be denied by a containing host
                    # policy even though this supervisor still owns the
                    # exact Popen process handle.  Kill that root through
                    # the retained handle; its nested kill-on-close jobs
                    # then close their own descendants.
                    if (
                        process.poll() is None
                        and _process_start_fingerprint(process.pid) == fingerprint
                    ):
                        process.kill()
                    else:
                        raise
            elif (
                os.name == "nt"
                and _process_start_fingerprint(process.pid) == fingerprint
            ):
                subprocess.run(
                    ["taskkill", "/PID", str(process.pid), "/T", "/F"],
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    timeout=budget.force_shutdown_seconds,
                    check=False,
                    shell=False,
                )
            else:
                try:
                    os.killpg(process.pid, signal.SIGKILL)
                except OSError:
                    pass
                self._signal_proven_posix(tracked, signal.SIGKILL)
            process.wait(timeout=budget.force_shutdown_seconds)
            if job is not None and not job.wait_closed(
                budget.force_shutdown_seconds, budget.poll_interval_seconds
            ):
                return "forced_failed", False
        except (OSError, subprocess.SubprocessError):
            return "forced_failed", False
    if os.name != "nt":
        deadline = time.monotonic() + budget.force_shutdown_seconds
        while time.monotonic() < deadline:
            live = [
                pid
                for pid, value in tracked.items()
                if pid != process.pid and _process_start_fingerprint(pid) == value
            ]
            if not live:
                break
            time.sleep(min(0.02, budget.poll_interval_seconds))
        else:
            return "forced_failed", False
    return mode, process.poll() is not None

def reconcile_persisted(
    self,
    resource_id: str,
    *,
    supplied_authority: bool,
    timeout_seconds: float = 5.0,
) -> dict[str, object]:
    """Reap only a persisted PID whose start identity is still provable."""
    if supplied_authority is not True:
        raise PermissionError(
            "explicit supplied reconciliation authority is required"
        )
    record = self.manager.ledger.get(resource_id)
    if record.resource_type != "process" or not record.pid or not record.active:
        raise ValueError("resource is not an active persisted process")
    prefix = "process-start:"
    if not record.process_identity or not record.process_identity.startswith(
        prefix
    ):
        return {
            "status": "retained_unproven",
            "resource_id": resource_id,
            "tree_closed": False,
        }
    expected = record.process_identity[len(prefix) :]
    if not _process_exists(record.pid):
        self.manager.update(
            resource_id,
            active=False,
            run_state=RunState.ABANDONED.value,
            status=ResourceStatus.RECLAIMED.value,
            cleanup_result="persisted_process_already_absent",
        )
        return {
            "status": "already_absent",
            "resource_id": resource_id,
            "tree_closed": True,
        }
    if _process_start_fingerprint(record.pid) != expected:
        return {
            "status": "retained_unproven",
            "resource_id": resource_id,
            "tree_closed": False,
        }
    try:
        if os.name == "nt":
            completed = subprocess.run(
                ["taskkill", "/PID", str(record.pid), "/T", "/F"],
                text=True,
                capture_output=True,
                timeout=timeout_seconds,
                check=False,
                shell=False,
            )
            if completed.returncode not in {0, 128}:
                diagnostic = (completed.stderr or completed.stdout).strip()
                raise OSError(
                    f"taskkill exit {completed.returncode}: {diagnostic[:160]}"
                )
        else:
            if os.getpgid(record.pid) != record.pid:
                return {
                    "status": "retained_unproven",
                    "resource_id": resource_id,
                    "tree_closed": False,
                }
            os.killpg(record.pid, signal.SIGKILL)
        deadline = time.monotonic() + timeout_seconds
        while _process_exists(record.pid) and time.monotonic() < deadline:
            time.sleep(0.02)
        if _process_exists(record.pid):
            raise OSError("verified process identity remains active")
    except (OSError, subprocess.SubprocessError) as error:
        self.manager.update(
            resource_id,
            status=ResourceStatus.CLEANUP_FAILED.value,
            retained_reason=f"reconciliation failed ({type(error).__name__})",
        )
        return {
            "status": "reconcile_failed",
            "resource_id": resource_id,
            "tree_closed": False,
            "failure_type": type(error).__name__,
            "failure_detail": str(error)[:256],
        }
    self.manager.update(
        resource_id,
        active=False,
        run_state=RunState.ABANDONED.value,
        status=ResourceStatus.RECLAIMED.value,
        cleanup_result="persisted_verified_process_tree_terminated",
    )
    return {"status": "reaped", "resource_id": resource_id, "tree_closed": True}

def run(
    self,
    command: Sequence[str],
    *,
    cwd: Path,
    action: Mapping[str, object],
    project_id: str,
    run_id: str,
    lane_id: str,
    creator: str,
    environment: Mapping[str, str] | None = None,
    cancel_event: threading.Event | None = None,
) -> ProcessResult:
    self.command_plan(command)
    budget, audit_hash, disk_paths = self._authorize(action, cwd)
    # ``run`` executes in the process that owns and supervises the child.
    # Its own PID is the custody identity.  Using getppid() binds the child
    # to the supervisor's launcher, which is intentionally short-lived for
    # durable Studio workers and therefore creates false owner-loss kills.
    owner_pid = os.getpid()
    owner_fingerprint = _process_start_fingerprint(owner_pid)
    owner_liveness = _open_owner_liveness(owner_pid)
    if owner_fingerprint is None and owner_liveness is None:
        raise RuntimeError("supervising process identity cannot be proven")
    disk_root = Path(cwd.resolve(strict=True).anchor or cwd.resolve(strict=True))
    initial_disk_free = shutil.disk_usage(disk_root).free
    initial_owned_consumption = (
        _disk_consumption_bytes(disk_paths) if disk_paths else None
    )
    action_id = str(action["action_id"])
    started_at = _now()
    started = time.monotonic()
    empty = CaptureResult("", 0, 0, 0, 0, False)
    try:
        record, process = self.manager.spawn_owned_process(
            command,
            cwd=cwd.resolve(strict=True),
            project_id=project_id,
            run_id=run_id,
            lane_id=lane_id,
            creator=creator,
            environment=environment,
            text=False,
            start_suspended=os.name == "nt",
        )
    except (OSError, subprocess.SubprocessError) as error:
        if owner_liveness is not None:
            owner_liveness.close()
        preliminary = ProcessResult(
            action_id,
            None,
            "spawn_failed",
            None,
            started_at,
            _now(),
            time.monotonic() - started,
            empty,
            empty,
            "not_started",
            True,
            type(error).__name__,
            audit_hash,
            None,
        )
        receipt = self._receipt(preliminary)
        return ProcessResult(
            **{
                **asdict(preliminary),
                "stdout": preliminary.stdout,
                "stderr": preliminary.stderr,
                "receipt_path": receipt,
            }
        )

    fingerprint = _process_start_fingerprint(process.pid)
    if fingerprint is None:
        # The live Popen handle remains exact in this process. Persist a
        # deliberately non-replayable identity so restart reconciliation
        # retains rather than killing an unproven PID.
        process_identity = f"owned-handle:{uuid4().hex}"
    else:
        process_identity = f"process-start:{fingerprint}"
    self.manager.update(record.resource_id, process_identity=process_identity)
    job: _WindowsJob | None = None
    try:
        if os.name == "nt":
            job = _WindowsJob(process)
            job.resume_process(process.pid)
    except OSError as error:
        if job is not None:
            try:
                job.terminate()
            finally:
                job.close()
        else:
            self.manager.terminate_owned_process(record.resource_id)
        if owner_liveness is not None:
            owner_liveness.close()
        raise RuntimeError(
            f"process containment setup failed ({type(error).__name__})"
        ) from None

    activity_lock = threading.Lock()
    supervision_started = time.monotonic()
    last_activity = [supervision_started]
    observed = [False]

    def activity() -> None:
        with activity_lock:
            observed[0] = True
            last_activity[0] = time.monotonic()

    stdout_capture = _BoundedCapture(budget.stdout_limit_bytes, activity)
    stderr_capture = _BoundedCapture(budget.stderr_limit_bytes, activity)
    threads = [
        threading.Thread(
            target=_drain, args=(process.stdout, stdout_capture), daemon=True
        ),
        threading.Thread(
            target=_drain, args=(process.stderr, stderr_capture), daemon=True
        ),
    ]
    for thread in threads:
        thread.start()

    status = "exited"
    shutdown_mode = "natural"
    tree_closed = True
    tracked = {process.pid: fingerprint}
    next_safety_check = supervision_started
    next_disk_check = supervision_started

    def terminal_safety_status(*, check_disk: bool) -> str | None:
        if owner_liveness is not None:
            owner_alive = owner_liveness.alive()
        elif owner_fingerprint is not None:
            owner_alive = (
                _process_start_fingerprint(owner_pid) == owner_fingerprint
            )
        else:
            owner_alive = False
        if not owner_alive:
            return "owner_lost"
        if not check_disk:
            return None
        if initial_owned_consumption is not None:
            current_owned_consumption = _disk_consumption_bytes(disk_paths)
            if (
                current_owned_consumption - initial_owned_consumption
                > budget.disk_consumption_limit_bytes
            ):
                return "disk_budget_exceeded"
        else:
            current_disk_free = shutil.disk_usage(disk_root).free
            if (
                initial_disk_free - current_disk_free
                > budget.disk_consumption_limit_bytes
            ):
                return "disk_budget_exceeded"
        return None

    try:
        while process.poll() is None:
            now = time.monotonic()
            if os.name != "nt":
                tracked.update(self._discover_posix_descendants(process.pid))
            with activity_lock:
                has_activity, last = observed[0], last_activity[0]
            if cancel_event is not None and cancel_event.is_set():
                status = "cancelled"
                break
            if now >= next_safety_check:
                next_safety_check = now + max(
                    0.25, budget.poll_interval_seconds
                )
                check_disk = now >= next_disk_check
                if check_disk:
                    next_disk_check = now + max(
                        MIN_DISK_ACCOUNTING_INTERVAL_SECONDS,
                        budget.poll_interval_seconds,
                    )
                safety_status = terminal_safety_status(check_disk=check_disk)
                if safety_status is not None:
                    status = safety_status
                    break
            if now - supervision_started >= budget.total_timeout_seconds:
                status = "total_timeout"
                break
            if (
                not has_activity
                and now - supervision_started >= budget.startup_timeout_seconds
            ):
                status = "startup_timeout"
                break
            if has_activity and now - last >= budget.idle_timeout_seconds:
                status = "idle_timeout"
                break
            time.sleep(budget.poll_interval_seconds)
        # The child can exit while this supervisor thread is descheduled.
        # Reconcile hard terminal controls after poll() observes that exit;
        # otherwise an over-budget or cancelled process can be published as
        # a successful natural exit under host contention.
        if status == "exited":
            # A final unconditional disk measurement preserves the hard
            # ceiling for fast-exit commands while avoiding a recursive
            # full-tree walk on every 20 ms supervision poll.
            safety_status = terminal_safety_status(check_disk=True)
            if safety_status is not None:
                status = safety_status
            elif cancel_event is not None and cancel_event.is_set():
                status = "cancelled"
            elif (
                time.monotonic() - supervision_started
                >= budget.total_timeout_seconds
            ):
                status = "total_timeout"
        if status != "exited":
            shutdown_mode, tree_closed = self._shutdown(
                process, fingerprint, tracked, job, budget
            )
        elif os.name == "nt" and job is not None:
            # Closing a kill-on-close Job ensures descendants cannot outlive a
            # successfully exited root process.
            try:
                job.terminate()
                tree_closed = job.wait_closed(
                    budget.force_shutdown_seconds, budget.poll_interval_seconds
                )
            except OSError:
                tree_closed = False
        elif os.name != "nt":
            tracked.update(self._discover_posix_descendants(process.pid))
            survivors = {
                pid: value for pid, value in tracked.items() if pid != process.pid
            }
            if survivors:
                shutdown_mode, tree_closed = self._shutdown(
                    process, fingerprint, tracked, job, budget
                )
    finally:
        if job is not None:
            job.close()
        if owner_liveness is not None:
            owner_liveness.close()
        for thread in threads:
            thread.join(timeout=budget.force_shutdown_seconds)

    failure_type = None if tree_closed else "ProcessTreeClosureError"
    if not tree_closed:
        status = "shutdown_failed"
        self.manager.update(
            record.resource_id,
            active=True,
            status=ResourceStatus.CLEANUP_FAILED.value,
            cleanup_result="process_tree_not_verified",
            retained_reason="process tree closure could not be proven",
        )
    else:
        self.manager.complete_process(record.resource_id)
        if status == "exited" and process.returncode not in {0, None}:
            self.manager.update(
                record.resource_id,
                run_state=RunState.FAILED.value,
                cleanup_result=f"exit_{process.returncode}",
            )
        elif status != "exited":
            self.manager.update(
                record.resource_id,
                run_state=RunState.CANCELLED.value,
                cleanup_result=f"{status}_{shutdown_mode}",
            )
    preliminary = ProcessResult(
        action_id=action_id,
        resource_id=record.resource_id,
        status=status,
        exit_code=process.returncode,
        started_at=started_at,
        ended_at=_now(),
        duration_seconds=time.monotonic() - started,
        stdout=stdout_capture.result(),
        stderr=stderr_capture.result(),
        shutdown_mode=shutdown_mode,
        tree_closed=tree_closed,
        failure_type=failure_type,
        audit_record_hash=audit_hash,
        receipt_path=None,
    )
    receipt = self._receipt(preliminary)
    return ProcessResult(
        **{
            **asdict(preliminary),
            "stdout": preliminary.stdout,
            "stderr": preliminary.stderr,
            "receipt_path": receipt,
        }
    )

"""Validation for portable bootstrap resource and model-routing profiles."""

from __future__ import annotations

from pathlib import Path
import tomllib


PROFILE_IDS = frozenset(
    {"default", "constrained", "large-workstation", "local-model", "cloud-restricted"}
)


def validate_profile(path: Path) -> dict[str, object]:
    payload = tomllib.loads(path.read_text(encoding="utf-8"))
    errors: list[str] = []
    if payload.get("schema_version") != "1.0":
        errors.append("unsupported schema_version")
    if payload.get("id") not in PROFILE_IDS:
        errors.append("unknown profile id")
    resources = payload.get("resources", {})
    for key in ("max_agents", "max_heavy_lanes", "max_context_bytes"):
        value = resources.get(key)
        if not isinstance(value, int) or isinstance(value, bool) or value < 1:
            errors.append(f"resources.{key} must be positive")
    if resources.get("max_heavy_lanes") != 1:
        errors.append("profiles must serialize heavy work")
    routing = payload.get("routing", {})
    if set(routing) != {"local_models", "cloud_models", "sensitive_data"}:
        errors.append("routing keys are incomplete")
    serialized = path.read_text(encoding="utf-8")
    if ":\\" in serialized or "/Users/" in serialized or "\\Users\\" in serialized:
        errors.append("profile contains a machine-specific path")
    return {
        "valid": not errors,
        "id": payload.get("id"),
        "errors": errors,
        "profile": payload,
    }


def validate_profile_set(root: Path) -> dict[str, object]:
    results = [validate_profile(path) for path in sorted(root.glob("*.toml"))]
    ids = {item["id"] for item in results}
    errors = [error for item in results for error in item["errors"]]
    errors.extend(f"missing profile: {name}" for name in sorted(PROFILE_IDS - ids))
    return {
        "valid": not errors,
        "profile_count": len(results),
        "errors": errors,
        "profiles": results,
    }

