            {
                "work_id": work_id,
                "worker_id": worker_id,
                "lane": lane,
                "owned_paths": owned_paths,
            }
        )
    return {"assignments": assignments, "blocked": blocked, "bounded": True}

def evaluate_resilience(
    experiments: Iterable[Mapping[str, object]],
) -> dict[str, object]:
    """Evaluate bounded digital-twin experiments; never inject faults into live systems."""
    allowed_faults = {
        "unavailable",
        "latency",
        "corrupt_response",
        "resource_pressure",
        "dependency_failure",
    }
    results = []
    for experiment in experiments:
        reasons = []
        if str(experiment.get("fault", "")) not in allowed_faults:
            reasons.append("fault_not_allowed")
        if experiment.get("digital_twin") is not True:
            reasons.append("not_a_digital_twin")
        if experiment.get("approved") is not True:
            reasons.append("experiment_not_approved")
        if not experiment.get("baseline_evidence") or not experiment.get(
            "observed_evidence"
        ):
            reasons.append("experiment_evidence_incomplete")
        if experiment.get("rollback_verified") is not True:
            reasons.append("rollback_not_verified")
        results.append(
            {
                "experiment_id": str(experiment.get("experiment_id", "unknown")),
                "status": "passed"
                if not reasons and experiment.get("outcome_met") is True
                else "failed",
                "reasons": reasons
                + (
                    [] if experiment.get("outcome_met") is True else ["outcome_not_met"]
                ),
            }
        )
    return {
        "mode": "digital_twin_only",
        "experiments": results,
        "passed": bool(results) and all(item["status"] == "passed" for item in results),
        "live_fault_injection": False,
    }

def guarded_change(
    active_root: Path,
    staged_file: Path,
    destination: Path,
    quarantine_root: Path,
    ledger: Path,
    evidence: Mapping[str, object],
    *,
    staging_root: Path | None = None,
    expected_source_sha256: str | None = None,
    allowed_suffixes: Iterable[str] = (".json", ".md", ".py", ".toml", ".yaml", ".yml"),
    collision_policy: str = "reject",
) -> dict[str, object]:
    root = active_root.resolve()
    staged = staged_file.resolve()
    destination = destination.resolve()
    reasons = []
    if not root.is_dir() or not _inside(destination, root):
        reasons.append("change_paths_invalid")
    owned_staging = staging_root.resolve() if staging_root is not None else None
    if owned_staging is None or expected_source_sha256 is None:
        reasons.append("owned_staging_contract_missing")
    else:
        reasons.extend(
            _allowed_source(
                staged, owned_staging, expected_source_sha256, allowed_suffixes
            )
        )
    if collision_policy not in {"reject"}:
        reasons.append("unsupported_destination_collision_policy")
    if destination.exists() and collision_policy == "reject":
        reasons.append("destination_collision")
    for field in (
        "intent",
        "tests",
        "outcome_contract",
        "rollback",
        "approval_id",
        "idempotency_key",
    ):
        if not evidence.get(field):
            reasons.append(f"{field}_missing")
    if (
        evidence.get("tests_passed") is not True
        or evidence.get("outcome_passed") is not True
    ):
        reasons.append("validation_not_passed")
    if reasons:
        event = append_event(
            ledger,
            "change-rejected",
            {
                "source_sha256": _sha(staged) if staged.is_file() else None,
                "source_mutated": False,
                "reasons": reasons,
                "hard_delete": False,
            },
        )
        return {
            "decision": "rejected",
            "reasons": tuple(sorted(set(reasons))),
            "event": event.as_posix(),
            "source_mutated": False,
            "hard_delete": False,
        }
    if _sha(staged) != expected_source_sha256:
        return {
            "decision": "rejected",
            "reasons": ("source_digest_changed_before_commit",),
            "source_mutated": False,
            "hard_delete": False,
        }
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(staged, destination)
    if _sha(destination) != expected_source_sha256:
        raise RuntimeError("guarded change hash mismatch")
    event = append_event(
        ledger,
        "change-accepted",
        {
            "destination": destination.relative_to(root).as_posix(),
            "sha256": _sha(destination),
            "evidence": dict(evidence),
        },
    )
    return {
        "decision": "accepted",
        "destination": destination.as_posix(),
        "sha256": _sha(destination),
        "event": event.as_posix(),
    }

def import_transfer(
    workspace_root: Path,
    source: Path,
    destination: Path,
    package: TransferPackage,
    ledger: Path,
    evidence_references: TransferEvidenceReferences,
    evidence_resolver: TrustedEvidenceResolver,
) -> dict[str, object]:
    root = workspace_root.resolve()
    source = source.resolve()
    destination = destination.resolve()
    decision = authorize_transfer(package, evidence_references, evidence_resolver)
    reasons = list(decision.reasons)
    if (
        not root.is_dir()
        or not source.is_file()
        or not _inside(source, root)
        or not _inside(destination, root)
    ):
        reasons.append("transfer_path_outside_workspace_or_missing")
    if destination.exists():
        reasons.append("destination_collision")
    if reasons:
        return {
            "decision": "rejected",
            "reasons": tuple(sorted(set(reasons))),
            "receipt_hash": decision.receipt_hash,
        }
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source, destination)
    if _sha(source) != _sha(destination):
        raise RuntimeError("transfer copy hash mismatch")
    event = append_event(
        ledger,
        "transfer-imported",
        {
            "package": asdict(package),
            "source": source.relative_to(root).as_posix(),
            "destination": destination.relative_to(root).as_posix(),
            "sha256": _sha(destination),
        },
    )
    return {
        "decision": "imported",
        "path": destination.as_posix(),
        "sha256": _sha(destination),
        "event": event.as_posix(),
    }

def project_health(metrics: Mapping[str, object]) -> dict[str, object]:
    required = ("tests", "security", "evidence", "dependencies", "memory", "operations")
    scores: dict[str, float] = {}
    unknown = []
    for name in required:
        value = metrics.get(name)
        if (
            not isinstance(value, (int, float))
            or isinstance(value, bool)
            or not 0 <= float(value) <= 1
        ):
            unknown.append(name)
        else:
            scores[name] = round(float(value), 4)
    overall = round(sum(scores.values()) / len(scores), 4) if scores else 0.0
    return {
        "overall": overall,
        "dimensions": scores,
        "unknown": unknown,
        "certifying": not unknown,
    }

def promote_capability(
    candidate: Path,
    shared_root: Path,
    ledger: Path,
    evidence: Mapping[str, object],
    *,
    staging_root: Path | None = None,
    expected_source_sha256: str | None = None,
    allowed_suffixes: Iterable[str] = (".json", ".md", ".py", ".toml", ".yaml", ".yml"),
) -> dict[str, object]:
    candidate = candidate.resolve()
    target_root = shared_root.resolve()
    reasons = []
    owned_staging = staging_root.resolve() if staging_root is not None else None
    if owned_staging is None or expected_source_sha256 is None:
        reasons.append("owned_staging_contract_missing")
    else:
        reasons.extend(
            _allowed_source(
                candidate, owned_staging, expected_source_sha256, allowed_suffixes
            )
        )
    for field in (
        "provenance",
        "license",
        "tests",
        "benchmark",
        "approval_id",
        "version",
    ):
        if not evidence.get(field):
            reasons.append(f"{field}_missing")
    if (
        evidence.get("tests_passed") is not True
        or evidence.get("benchmark_passed") is not True
    ):
        reasons.append("validation_not_passed")
    target = (
        target_root
        / str(evidence.get("capability_id", candidate.stem))
        / str(evidence.get("version", "candidate"))
        / candidate.name
    )
    if target.exists():
        reasons.append("release_collision")
    if reasons:
        return {
            "decision": "rejected",
            "reasons": tuple(sorted(set(reasons))),
            "automatic_activation": False,
        }
    target.parent.mkdir(parents=True, exist_ok=True)
    if _sha(candidate) != expected_source_sha256:
        return {
            "decision": "rejected",
            "reasons": ("source_digest_changed_before_commit",),
            "automatic_activation": False,
        }
    shutil.copy2(candidate, target)
    if _sha(target) != expected_source_sha256:
        raise RuntimeError("capability promotion hash mismatch")
    event = append_event(
        ledger,
        "capability-promoted",
        {
            "target": target.as_posix(),
            "sha256": _sha(target),
            "evidence": dict(evidence),
        },
    )
    return {
        "decision": "released",
        "target": target.as_posix(),
        "sha256": _sha(target),
        "event": event.as_posix(),
        "automatic_activation": False,
    }

def quarantine_candidates(
    active_root: Path,
    candidates: Iterable[Path],
    quarantine_root: Path,
    ledger: Path,
    *,
    transaction_root: Path | None = None,
    expected_sha256: Mapping[str, str] | None = None,
    fault_injector: Callable[[str], None] | None = None,
) -> dict[str, object]:
    root = active_root.resolve()
    quarantine = quarantine_root.resolve()
    supplied = tuple(path.resolve() for path in candidates)
    paths = tuple(sorted(supplied, key=lambda item: item.as_posix().casefold()))
    reasons = []
    if not root.is_dir() or not supplied:
        reasons.append("active_root_or_candidates_invalid")
    if len(set(supplied)) != len(supplied):
        reasons.append("duplicate_candidate")
    if (
        not _inside(quarantine, root.parent)
        or quarantine == root
        or _inside(quarantine, root)
    ):
        reasons.append("quarantine_must_be_sibling_bounded_tree")
    replay_requested = (
        bool(paths)
        and quarantine.is_dir()
        and all(
            _inside(path, root)
            and path != root
            and not path.exists()
            and (quarantine / path.relative_to(root)).exists()
            for path in paths
        )
    )
    for path in paths:
        if (
            path == root
            or not _inside(path, root)
            or (not path.exists() and not replay_requested)
        ):
            reasons.append(f"invalid_candidate:{path}")
        if any(path != other and _inside(path, other) for other in paths):
            reasons.append(f"overlapping_candidate:{path}")
    inventory: list[dict[str, object]] = []
    if not reasons:
        for path in paths:
            if replay_requested:
                replay_target = quarantine / path.relative_to(root)
                files = (
                    (replay_target,)
                    if replay_target.is_file()
                    else tuple(
                        item
                        for item in sorted(replay_target.rglob("*"))
                        if item.is_file()
                    )
                )
                inventory.extend(
                    {
                        "path": item.relative_to(quarantine).as_posix(),
                        "sha256": _sha(item),
                        "size": item.stat().st_size,
                    }
                    for item in files
                )
            else:
                files = (
                    (path,)
                    if path.is_file()
                    else tuple(
                        item for item in sorted(path.rglob("*")) if item.is_file()
                    )
                )
                inventory.extend(
                    {
                        "path": item.relative_to(root).as_posix(),
                        "sha256": _sha(item),
                        "size": item.stat().st_size,
                    }
                    for item in files
                )
    operation_id = _stable(
        {
            "root": root.as_posix(),
            "quarantine": quarantine.as_posix(),
            "inventory": inventory,
        }
    )
    transactions = (
        transaction_root or (ledger.parent / "transactions" / "quarantine")
    ).resolve()
    if (
        not _inside(transactions, root.parent)
        or transactions == root
        or _inside(transactions, root)
    ):
        reasons.append("transaction_root_must_be_sibling_bounded_tree")
    transaction = transactions / operation_id
    committed = transaction / "0003-committed.json"
    if quarantine.exists():
        if committed.is_file() and all(
            (quarantine / str(item["path"])).is_file()
            and _sha(quarantine / str(item["path"])) == item["sha256"]
            for item in inventory
        ):
            return {
                "decision": "quarantined",
                "count": len(inventory),
                "inventory": inventory,
                "event": None,
                "hard_delete": False,
                "idempotent_replay": True,
            }
        reasons.append("quarantine_destination_exists")
    planned = expected_sha256 or {}
    for item in inventory:
        relative = str(item["path"])
        if relative in planned and planned[relative] != item["sha256"]:
            reasons.append(f"source_digest_mismatch:{relative}")
        if (quarantine / relative).exists():
            reasons.append(f"destination_collision:{relative}")
    if reasons:
        return {
            "decision": "rejected",
            "reasons": tuple(sorted(set(reasons))),
            "hard_delete": False,
        }
    transactions.mkdir(parents=True, exist_ok=True)
    _write_journal_record(
        transaction,
        1,
        "intent",
        {
            "active_root": root.as_posix(),
            "quarantine_root": quarantine.as_posix(),
            "inventory": inventory,
        },
    )
    quarantine.mkdir(parents=True, exist_ok=False)
    moved: list[tuple[Path, Path]] = []
    try:
        for index, path in enumerate(paths, start=1):
            if fault_injector:
                fault_injector(f"before_move_{index}")
            # Revalidate every source immediately before mutation.
            for item in inventory:
                item_path = root / str(item["path"])
                if _inside(item_path, path) and (
                    not item_path.is_file() or _sha(item_path) != item["sha256"]
                ):
                    raise RuntimeError(
                        f"source changed before quarantine commit: {item['path']}"
                    )
            target = quarantine / path.relative_to(root)
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.move(str(path), str(target))
            moved.append((path, target))
        for item in inventory:
            target = quarantine / str(item["path"])
            if not target.is_file() or _sha(target) != item["sha256"]:
                raise RuntimeError("quarantine reconciliation failed")
        _write_journal_record(
            transaction,
            2,
            "moved",
            {"moved": [target.as_posix() for _, target in moved]},
        )
    except BaseException as error:
        rollback_errors = []
        for source, target in reversed(moved):
            try:
                source.parent.mkdir(parents=True, exist_ok=True)
                shutil.move(str(target), str(source))
            except OSError as rollback_error:
                rollback_errors.append(str(rollback_error))
        _write_journal_record(
            transaction,
            2,
            "rolled-back",
            {
                "error": f"{type(error).__name__}: {error}",
                "rollback_errors": rollback_errors,
            },
        )
        if rollback_errors:
            raise RuntimeError(
                f"quarantine failed and rollback was incomplete: {rollback_errors}"
            ) from error
        raise
    event = append_event(
        ledger,
        "artifacts-quarantined",
        {
            "active_root": root.as_posix(),
            "quarantine_root": quarantine.as_posix(),
            "inventory": inventory,
            "hard_delete": False,
            "transaction_id": operation_id,
        },
    )
    _write_journal_record(
        transaction,
        3,
        "committed",
        {"event": event.as_posix(), "inventory_sha256": _stable(inventory)},
    )
    return {
        "decision": "quarantined",
        "count": len(inventory),
        "inventory": inventory,
        "event": event.as_posix(),
        "hard_delete": False,
        "transaction_id": operation_id,
    }

def switch_project(
    ledger: Path, old: ScopeEnvelope, new: ScopeEnvelope, evidence: SwitchEvidence
) -> dict[str, object]:
    decision = validate_project_switch(old, new, evidence)
    if decision.decision != "allow":
        return {
            "decision": "rejected",
            "reasons": decision.reasons,
            "receipt_hash": decision.receipt_hash,
        }
    event = append_event(
        ledger,
        "project-switch",
        {"old": asdict(old), "new": asdict(new), "evidence": asdict(evidence)},
    )
    return {
        "decision": "active",
        "project_id": new.project_id,
        "event": event.as_posix(),
        "receipt_hash": decision.receipt_hash,
    }

def _walk(
    starts: Iterable[str],
    adjacency: Mapping[str, set[str]],
    *,
    max_depth: int,
    max_nodes: int,
) -> tuple[dict[str, int], bool]:
    depths = {str(node): 0 for node in starts}
    queue = deque(sorted(depths))
    truncated = False
    while queue:
        source = queue.popleft()
        depth = depths[source]
        if depth >= max_depth:
            continue
        for target in sorted(adjacency.get(source, ())):
            if target in depths:
                continue
            if len(depths) >= max_nodes:
                truncated = True
                return depths, truncated
            depths[target] = depth + 1
            queue.append(target)
    return depths, truncated

def analyze_project_impact(
    project_or_map: Path,
    target: str,
    *,
    direction: str = "upstream",
    max_depth: int = 4,
    max_nodes: int = 500,
    require_fresh: bool = True,
) -> dict[str, object]:
    """Return bounded callers, importing files, routes, contracts, tests, and services."""
    if direction not in {"upstream", "downstream", "both"}:
        raise ValueError("direction must be upstream, downstream, or both")
    if max_depth < 1 or max_depth > 12:
        raise ValueError("max_depth must be between 1 and 12")
    if max_nodes < 1 or max_nodes > 10_000:
        raise ValueError("max_nodes must be between 1 and 10000")

    validation = validate_project_map(project_or_map, check_freshness=require_fresh)
    if not validation.get("valid"):
        return {
            "schema_version": "1.0",
            "valid": False,
            "target": target,
            "errors": validation.get("errors", []),
            "warnings": validation.get("warnings", []),
            "repair": "Build or refresh the project map before impact analysis.",
        }

    map_dir = _map_dir(project_or_map)
    manifest = _load_json(map_dir / "project-manifest.json")
    symbols = _load_jsonl(map_dir / "symbol-index.jsonl")
    inventory = _load_jsonl(map_dir / "file-inventory.jsonl")
    inventory_paths = {str(record["path"]) for record in inventory}
    target_id, candidates, resolution_error = _resolve_target(
        target, symbols, inventory_paths
    )
    if target_id is None:
        return {
            "schema_version": "1.0",
            "valid": False,
            "target": target,
            "map_revision": manifest.get("map_revision"),
            "error": resolution_error,
            "candidates": candidates,
        }

    call_graph = _load_json(map_dir / "call-graph.json")
    dependency_graph = _load_json(map_dir / "dependency-graph.json")
    traceability = _load_json(map_dir / "traceability-map.json")
    runtime = _load_json(map_dir / "runtime-topology.json")

    call_edges = list(call_graph.get("edges", ()))
    dependency_edges = [
        edge
        for edge in dependency_graph.get("edges", ())
        if edge.get("kind") in {"imports", "service_depends_on"}
    ]
    if direction == "both":
        call_adj = _adjacency(call_edges, reverse=False)
        dep_adj = _adjacency(dependency_edges, reverse=False)
        for node, neighbors in _adjacency(call_edges, reverse=True).items():
            call_adj[node].update(neighbors)
        for node, neighbors in _adjacency(dependency_edges, reverse=True).items():
            dep_adj[node].update(neighbors)
    else:
        reverse = direction == "upstream"
        call_adj = _adjacency(call_edges, reverse=reverse)
        dep_adj = _adjacency(dependency_edges, reverse=reverse)

    target_is_file = target_id.startswith("file:")
    target_path = (
        target_id.removeprefix("file:")
        if target_is_file
        else target_id.removeprefix("symbol:").rsplit(":", 1)[0]
    )
    symbol_starts = (
        [
            _symbol_id(record)
            for record in symbols
            if str(record.get("path")) == target_path
        ]
        if target_is_file
        else [target_id]
    )
    call_depths, call_truncated = _walk(
        symbol_starts, call_adj, max_depth=max_depth, max_nodes=max_nodes
    )
    impacted_symbol_ids = set(call_depths)
    symbol_by_id = {_symbol_id(record): record for record in symbols}
    symbol_files = {
        str(symbol_by_id[symbol_id]["path"])
        for symbol_id in impacted_symbol_ids
        if symbol_id in symbol_by_id
    }
    file_starts = {f"file:{target_path}", *(f"file:{path}" for path in symbol_files)}
    file_depths, dependency_truncated = _walk(
        file_starts, dep_adj, max_depth=max_depth, max_nodes=max_nodes
    )
    impacted_files = sorted(
        {
            node.removeprefix("file:")
            for node in file_depths
            if node.startswith("file:")
        }
        | symbol_files
        | {target_path}
    )

    trace_by_file = {
        str(record.get("implementation")): record
        for record in traceability.get("records", ())
    }
    tests: set[str] = set()
    contracts: set[str] = set()
    routes: set[str] = set()
    for path in impacted_files:
        record = trace_by_file.get(path, {})
        tests.update(str(item) for item in record.get("tests", ()))
        contracts.update(str(item) for item in record.get("contracts", ()) if item)
        routes.update(str(item) for item in record.get("routes", ()) if item)
    services = sorted(
        {
            str(service.get("name") or service.get("id"))
            for service in runtime.get("services", ())
            if str(service.get("source", "")) in impacted_files
        }
    )

    direct_nodes = {
        node for node, depth in call_depths.items() if depth == 1
    } | {node for node, depth in file_depths.items() if depth == 1}
    all_nodes = set(call_depths) | set(file_depths)
    truncated = call_truncated or dependency_truncated
    score, level = _risk(
        direct=len(direct_nodes),
        transitive=max(0, len(all_nodes) - len(symbol_starts) - len(file_starts)),
        files=len(impacted_files),
        routes=len(routes),
        contracts=len(contracts),
        services=len(services),
        tests=len(tests),
        truncated=truncated,
    )
    impacted_symbols = [
        {
            **_symbol_candidate(symbol_by_id[node]),
            "depth": call_depths[node],
        }
        for node in sorted(impacted_symbol_ids, key=lambda item: (call_depths[item], item))
        if node in symbol_by_id and node not in symbol_starts
    ]
    file_records = [
        {
            "path": path,
            "depth": file_depths.get(f"file:{path}", 0),
            "basis": "call_or_import_graph",
        }
        for path in sorted(
            impacted_files,
            key=lambda item: (file_depths.get(f"file:{item}", 0), item),
        )
    ]
    return {
        "schema_version": "1.0",
        "valid": True,
        "target": target,
        "resolved_target": target_id,
        "target_path": target_path,
        "direction": direction,
        "map_dir": map_dir.as_posix(),
        "map_revision": manifest.get("map_revision"),
        "source_inventory_sha256": manifest.get("source_inventory_sha256"),
        "freshness_checked": require_fresh,
        "risk": {
            "level": level,
            "score": score,
            "direct_affected_nodes": len(direct_nodes),
            "transitive_affected_nodes": max(
                0, len(all_nodes) - len(symbol_starts) - len(file_starts)
            ),
            "truncated": truncated,
        },
        "affected_symbols": impacted_symbols,
        "affected_files": file_records,
        "affected_routes": sorted(routes),
        "affected_contracts": sorted(contracts),
        "affected_tests": sorted(tests),
        "affected_services": services,
        "limits": {"max_depth": max_depth, "max_nodes": max_nodes},
        "evidence": [
            "project-manifest.json",
            "symbol-index.jsonl",
            "call-graph.json",
            "dependency-graph.json",
            "traceability-map.json",
            "runtime-topology.json",
        ],
        "limitations": [
            "Static call resolution is incomplete for dynamic dispatch, reflection, generated code, and runtime dependency injection.",
            "A high/critical result requires user warning before edits; a low result does not remove the need for tests.",
        ],
    }

def as_invalidation_inputs(
    impact: Mapping[str, object],
    *,
    revision_bindings: Mapping[str, object],
) -> tuple[list[dict[str, str]], list[dict[str, str]]]:
    """Adapt one valid impact receipt to universal invalidation graph inputs."""
    if impact.get("valid") is not True:
        raise ValueError("a valid project-impact receipt is required")
    target = str(impact.get("resolved_target") or "")
    if not target:
        raise ValueError("project-impact receipt has no resolved target")
    typed: dict[str, str] = {target: "source"}
    for record in impact.get("affected_files", []):
        if isinstance(record, Mapping) and record.get("path"):
            typed[f"file:{record['path']}"] = "source"
    for path in impact.get("affected_tests", []):
        typed[f"test:{path}"] = "test"
    nodes = [
        {
            "node_id": node_id,
            "kind": typed[node_id],
            "revision": str(revision_bindings.get(node_id) or ""),
        }
        for node_id in sorted(typed)
    ]
    edges = [
        {"dependency": target, "consumer": node_id}
        for node_id in sorted(typed)
        if node_id != target
    ]
    return nodes, edges

def validate_project_change_intelligence_orchestration(
    root: Path,
) -> dict[str, object]:
    """Validate the native mapping/impact workflow and its executable owners."""
    path = root.resolve() / "orchestration/workflows/project-change-intelligence.yaml"
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        return {"valid": False, "errors": [str(error)]}
    expected = (
        ("map", "map-project-intelligence", ()),
        ("retrieve", "query-project-map", ("map",)),
        ("impact", "query-project-map", ("map", "retrieve")),
        ("verify", "verify-outcome", ("impact",)),
    )
    actual = tuple(
        (
            str(step.get("id", "")),
            str(step.get("skill", "")),
            tuple(map(str, step.get("depends_on", ()))),
        )
        for step in payload.get("steps", ())
        if isinstance(step, Mapping)
    )
    errors: list[str] = []
    if payload.get("id") != "project-change-intelligence":
        errors.append("project change intelligence workflow id is invalid")
    if actual != expected:
        errors.append("project change intelligence steps are incomplete, duplicated, or out of order")
    if not str(payload.get("failure_policy", "")).strip():
        errors.append("project change intelligence failure policy is missing")
    if not (root / "contracts/project-impact.schema.json").is_file():
        errors.append("project impact receipt contract is missing")
    return {
        "valid": not errors,
        "workflow_id": payload.get("id"),
        "step_count": len(actual),
        "errors": errors,
    }

class _PythonScanner(ast.NodeVisitor):
    def __init__(self, relative: str) -> None:
        self.relative = relative
        self.scope: list[str] = []
        self.symbols: list[dict[str, object]] = []
        self.imports: list[dict[str, object]] = []
        self.calls: list[dict[str, object]] = []
        self.routes: list[dict[str, object]] = []
        self.config_refs: list[dict[str, object]] = []
        self.data_flows: list[dict[str, object]] = []
        self.contracts: list[dict[str, object]] = []
        self.tests: list[dict[str, object]] = []

    def _qualname(self, name: str) -> str:
        return ".".join((*self.scope, name))

    def _decorators(
        self, node: ast.FunctionDef | ast.AsyncFunctionDef | ast.ClassDef
    ) -> list[str]:
        return [
            _attribute_name(item.func if isinstance(item, ast.Call) else item)
            for item in node.decorator_list
        ]

    def visit_ClassDef(self, node: ast.ClassDef) -> None:
        bases = [_attribute_name(base) for base in node.bases]
        decorators = self._decorators(node)
        symbol = {
            "name": node.name,
            "qualname": self._qualname(node.name),
            "kind": "class",
            "line_start": node.lineno,
            "line_end": getattr(node, "end_lineno", node.lineno),
            "bases": [value for value in bases if value],
            "decorators": [value for value in decorators if value],
        }
        self.symbols.append(symbol)
        if any(
            base.endswith(("BaseModel", "TypedDict", "Enum")) for base in bases
        ) or any(item.endswith("dataclass") for item in decorators):
            self.contracts.append(
                {
                    "id": f"python:{self.relative}:{symbol['qualname']}",
                    "kind": "python_model",
                    "name": node.name,
                    "path": self.relative,
                    "line": node.lineno,
                    "evidence": {"bases": bases, "decorators": decorators},
                }
            )
        self.scope.append(node.name)
        self.generic_visit(node)
        self.scope.pop()

    def _visit_function(self, node: ast.FunctionDef | ast.AsyncFunctionDef) -> None:
        kind = (
            "async_function" if isinstance(node, ast.AsyncFunctionDef) else "function"
        )
        if self.scope:
            kind = (
                "async_method" if isinstance(node, ast.AsyncFunctionDef) else "method"
            )
        decorators = self._decorators(node)
        symbol = {
            "name": node.name,
            "qualname": self._qualname(node.name),
            "kind": kind,
            "line_start": node.lineno,
            "line_end": getattr(node, "end_lineno", node.lineno),
            "decorators": [value for value in decorators if value],
        }
        self.symbols.append(symbol)
        if node.name.startswith("test_"):
            self.tests.append(
                {
                    "name": symbol["qualname"],
                    "path": self.relative,
                    "line": node.lineno,
                    "kind": "test_function",
                }
            )
        for decorator in node.decorator_list:
            target = decorator.func if isinstance(decorator, ast.Call) else decorator
            name = _attribute_name(target)
            method = name.rsplit(".", 1)[-1].casefold()
            if method in ROUTE_METHODS or method == "api_route":
                route_path = (
                    _literal_string(decorator.args[0])
                    if isinstance(decorator, ast.Call) and decorator.args
                    else None
                )
                # HTTP route decorators require an explicit absolute path.  A
                # name-only match is insufficient: unittest.mock.patch and
                # similar decorators otherwise become false HTTP PATCH routes.
                if route_path is None or not route_path.startswith("/"):
                    continue
                methods = [method.upper()] if method != "api_route" else []
                if isinstance(decorator, ast.Call):
                    for keyword in decorator.keywords:
                        if keyword.arg == "methods" and isinstance(
                            keyword.value, (ast.List, ast.Tuple)
                        ):
                            methods = [
                                str(value.value).upper()
                                for value in keyword.value.elts
                                if isinstance(value, ast.Constant)
                            ]
                self.routes.append(
                    {
                        "id": f"route:{self.relative}:{node.lineno}:{route_path or '?'}",
                        "path": route_path,
                        "methods": methods or ["UNKNOWN"],
                        "handler": symbol["qualname"],
                        "file": self.relative,
                        "line": node.lineno,
                        "framework_hint": name.rsplit(".", 1)[0] or "decorator",
                    }
                )
        self.scope.append(node.name)
        self.generic_visit(node)
        self.scope.pop()

    def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
        self._visit_function(node)

    def visit_AsyncFunctionDef(self, node: ast.AsyncFunctionDef) -> None:
        self._visit_function(node)

    def visit_Import(self, node: ast.Import) -> None:
        for alias in node.names:
            self.imports.append(
                {
                    "module": alias.name,
                    "name": None,
                    "alias": alias.asname,
                    "level": 0,
                    "line": node.lineno,
                }
            )

    def visit_ImportFrom(self, node: ast.ImportFrom) -> None:
        for alias in node.names:
            self.imports.append(
                {
                    "module": node.module or "",
                    "name": alias.name,
                    "alias": alias.asname,
                    "level": node.level,
                    "line": node.lineno,
                }
            )

    def visit_Call(self, node: ast.Call) -> None:
        callee = _attribute_name(node.func)
        caller = ".".join(self.scope) or "<module>"
        self.calls.append({"callee": callee, "caller": caller, "line": node.lineno})
        source, sink, confidence = _classify_call(callee)
        if source or sink:
            self.data_flows.append(
                {
                    "file": self.relative,
                    "line": node.lineno,
                    "caller": caller,
                    "operation": callee,
                    "source": source,
                    "sink": sink,
                    "confidence": confidence,
                    "basis": "static_call_pattern",
                }
            )
        if callee in {"os.getenv", "os.environ.get"} and node.args:
            key = _literal_string(node.args[0])
            if key:
                self.config_refs.append(
                    {
                        "key": key,
                        "path": self.relative,
                        "line": node.lineno,
                        "access": callee,
                        "sensitive": bool(SENSITIVE_KEY.search(key)),
                    }
                )
        self.generic_visit(node)

    def visit_Subscript(self, node: ast.Subscript) -> None:
        target = _attribute_name(node.value)
        if target == "os.environ":
            key = _literal_string(node.slice)
            if key:
                self.config_refs.append(
                    {
                        "key": key,
                        "path": self.relative,
                        "line": node.lineno,
                        "access": "os.environ[]",
                        "sensitive": bool(SENSITIVE_KEY.search(key)),
                    }
                )
        self.generic_visit(node)

def _architecture_graph(
    facts: Sequence[Mapping[str, object]],
    dependency_graph: Mapping[str, object],
    runtime: Mapping[str, object],
    contract_map: Mapping[str, object],
    integration_map: Mapping[str, object],
    routes: Sequence[Mapping[str, object]],
    ownership: Mapping[str, object],
) -> dict[str, object]:
    nodes: dict[str, dict[str, object]] = {
        "project": {"id": "project", "kind": "project", "name": "project"}
    }
    edges: list[dict[str, object]] = []
    owners_by_path = {
        str(item.get("path")): [str(owner) for owner in item.get("owners", ())]
        for item in ownership.get("assignments", ())
        if isinstance(item, Mapping)
    }
    for fact in facts:
        node_id = f"file:{fact['path']}"
        nodes[node_id] = {
            "id": node_id,
            "kind": "file",
            "path": fact["path"],
            "language": fact["language"],
            "role": fact["role"],
            "sha256": fact.get("sha256"),
            "owner": owners_by_path.get(str(fact["path"]), []),
            "provenance": {
                "class": "DERIVED",
                "source": "project-map/file-facts.jsonl",
                "source_path": fact["path"],
                "source_sha256": fact.get("sha256"),
                "owner_basis": "codeowners" if str(fact["path"]) in owners_by_path else "unassigned",
            },
        }
        edges.append({"from": "project", "to": node_id, "kind": "contains"})
    for edge in dependency_graph.get("edges", ()):
        nodes.setdefault(
            str(edge["to"]),
            next(
                (
                    node
                    for node in dependency_graph.get("nodes", ())
                    if node.get("id") == edge["to"]
                ),
                {"id": edge["to"], "kind": "unknown"},
            ),
        )
        edges.append({"from": edge["from"], "to": edge["to"], "kind": edge["kind"]})
    for service in runtime.get("services", ()):
        node_id = str(service["id"])
        nodes[node_id] = {
            "id": node_id,
            "kind": "service",
            "name": service.get("name"),
            "image": service.get("image"),
        }
        edges.append({"from": "project", "to": node_id, "kind": "runs"})
    for route in routes:
        node_id = str(route["id"])
        nodes[node_id] = {
            "id": node_id,
            "kind": "route",
            "path": route.get("path"),
            "methods": route.get("methods"),
        }
        edges.append(
            {"from": f"file:{route['file']}", "to": node_id, "kind": "declares_route"}
        )
    for contract in contract_map.get("contracts", ()):
        node_id = f"contract:{contract['id']}"
        nodes[node_id] = {
            "id": node_id,
            "kind": "contract",
            "name": contract.get("name"),
            "contract_kind": contract.get("kind"),
        }
        edges.append(
            {
                "from": f"file:{contract['path']}",
                "to": node_id,
                "kind": "defines_contract",
            }
        )
    for package in integration_map.get("packages", ()):
        node_id = f"integration:{package['ecosystem']}:{package['name']}"
        nodes[node_id] = {
            "id": node_id,
            "kind": "integration",
            "name": package["name"],
            "category": package.get("category"),
        }
        for source in package.get("sources", ()):
            edges.append(
                {"from": f"file:{source}", "to": node_id, "kind": "uses_integration"}
            )
    return {
        "schema_version": SCHEMA_VERSION,
        "nodes": sorted(nodes.values(), key=lambda item: str(item["id"])),
        "edges": sorted(
            edges,
            key=lambda item: (str(item["from"]), str(item["to"]), str(item["kind"])),
        ),
    }

def _call_graph(
    facts: Sequence[Mapping[str, object]],
    dependency_graph: Mapping[str, object] | None = None,
) -> dict[str, object]:
    nodes: dict[str, dict[str, object]] = {}
    by_file_name: dict[str, dict[str, str]] = defaultdict(dict)
    for fact in facts:
        path = str(fact["path"])
        for symbol in fact.get("symbols", ()):  # type: ignore[union-attr]
            node_id = f"symbol:{path}:{symbol.get('qualname')}"
            nodes[node_id] = {
                "id": node_id,
                "kind": symbol.get("kind"),
                "name": symbol.get("qualname"),
                "path": path,
                "line": symbol.get("line_start"),
            }
            by_file_name[path][str(symbol.get("name"))] = node_id
    edges: list[dict[str, object]] = []
    external_calls: Counter[str] = Counter()
    imported_targets: dict[tuple[str, str], str] = {}
    dependency_edges = list((dependency_graph or {}).get("edges", ()))
    for fact in facts:
        path = str(fact["path"])
        for imported in fact.get("imports", ()):  # type: ignore[union-attr]
            imported_name = str(imported.get("alias") or imported.get("name") or "")
            if not imported_name or imported_name == "*":
                continue
            specifier = str(imported.get("module") or imported.get("specifier") or "")
            target_file = None
            for edge in dependency_edges:
                if (
                    edge.get("from") == f"file:{path}"
                    and edge.get("kind") == "imports"
                    and (
                        edge.get("line") == imported.get("line")
                        or edge.get("specifier") == specifier
                    )
                ):
                    target_file = str(edge.get("to", "")).removeprefix("file:")
                    break
            target_symbol = by_file_name.get(target_file or "", {}).get(
                str(imported.get("name") or imported_name)
            )
            if target_symbol:
                imported_targets[(path, imported_name)] = target_symbol
    for fact in facts:
        path = str(fact["path"])
        for call in fact.get("calls", ()):  # type: ignore[union-attr]
            callee = str(call.get("callee", ""))
            leaf = callee.rsplit(".", 1)[-1]
            target = by_file_name[path].get(leaf) or imported_targets.get((path, leaf))
            caller_name = str(call.get("caller", "<module>"))
            caller = (
                f"symbol:{path}:{caller_name}"
                if f"symbol:{path}:{caller_name}" in nodes
                else f"file:{path}"
            )
            if target:
                edges.append(
                    {
                        "from": caller,
                        "to": target,
                        "kind": "calls",
                        "line": call.get("line"),
                        "resolved": True,
                    }
                )
            elif callee and ("." in callee or callee in {"open", "fetch"}):
                external_calls[callee] += 1
    edges.sort(
        key=lambda item: (
            str(item["from"]),
            str(item["to"]),
            int(item.get("line") or 0),
        )
    )
    return {
        "schema_version": SCHEMA_VERSION,
        "nodes": sorted(nodes.values(), key=lambda item: str(item["id"])),
        "edges": edges,
        "external_call_summary": [
            {"callee": key, "count": value}
            for key, value in external_calls.most_common(200)
        ],
    }

def _dependency_graph(facts: Sequence[Mapping[str, object]]) -> dict[str, object]:
    files = {str(fact["path"]) for fact in facts}
    python_modules: dict[str, str] = {}
    for path in files:
        module = _python_module(path)
        if module is not None:
            python_modules[module] = path
    nodes: dict[str, dict[str, object]] = {
        f"file:{path}": {"id": f"file:{path}", "kind": "file", "path": path}
        for path in files
    }
    edges: list[dict[str, object]] = []
    unresolved: list[dict[str, object]] = []
    external: set[tuple[str, str]] = set()
    for fact in facts:
        source = str(fact["path"])
        language = str(fact["language"])
        for item in fact.get("imports", ()):  # type: ignore[union-attr]
            target: str | None = None
            specifier = str(item.get("module") or item.get("specifier") or "")
            if language == "python":
                level = int(item.get("level") or 0)
                module = specifier
                if level:
                    current = _python_module(source) or ""
                    package = current.split(".")[:-1]
                    keep = max(0, len(package) - level + 1)
                    module = ".".join(
                        (*package[:keep], *([specifier] if specifier else []))
                    ).strip(".")
                candidates = (
                    [
                        module,
                        *[
                            ".".join(module.split(".")[:index])
                            for index in range(len(module.split(".")) - 1, 0, -1)
                        ],
                    ]
                    if module
                    else []
                )
                target = next(
                    (
                        python_modules[value]
                        for value in candidates
                        if value in python_modules
                    ),
                    None,
                )
            elif language in {"javascript", "typescript"}:
                target = _resolve_relative_js(source, specifier, files)
            if target:
                edges.append(
                    {
                        "from": f"file:{source}",
                        "to": f"file:{target}",
                        "kind": "imports",
                        "line": item.get("line"),
                        "specifier": specifier,
                        "resolved": True,
                    }
                )
            elif specifier:
                package = (
                    specifier.split("/", 1)[0]
                    if not specifier.startswith("@")
                    else "/".join(specifier.split("/")[:2])
                )
                external.add((language, package))
                node_id = f"external:{language}:{package}"
                nodes.setdefault(
                    node_id,
                    {
                        "id": node_id,
                        "kind": "external_package",
                        "name": package,
                        "ecosystem_hint": language,
                    },
                )
                edges.append(
                    {
                        "from": f"file:{source}",
                        "to": node_id,
                        "kind": "imports_external",
                        "line": item.get("line"),
                        "specifier": specifier,
                        "resolved": False,
                    }
                )
                if specifier.startswith(".") or (
                    language == "python"
                    and specifier.split(".", 1)[0]
                    not in {
                        "os",
                        "sys",
                        "json",
                        "pathlib",
                        "typing",
                        "collections",
                        "datetime",
                        "re",
                        "math",
                        "hashlib",
                        "argparse",
                        "subprocess",
                        "tempfile",
                        "shutil",
                        "itertools",
                        "functools",
                        "dataclasses",
                        "enum",
                        "logging",
                        "asyncio",
                        "unittest",
                    }
                ):
                    unresolved.append(
                        {
                            "source": source,
                            "specifier": specifier,
                            "line": item.get("line"),
                            "language": language,
                        }
                    )
        for dep in fact.get("dependencies", ()):  # type: ignore[union-attr]
            name = str(dep.get("name", ""))
            ecosystem = str(dep.get("ecosystem", "unknown"))
            if not name:
                continue
            node_id = f"external:{ecosystem}:{name}"
            nodes.setdefault(
                node_id,
                {
                    "id": node_id,
                    "kind": "external_package",
                    "name": name,
                    "ecosystem_hint": ecosystem,
                },
            )
            edges.append(
                {
                    "from": f"file:{source}",
                    "to": node_id,
                    "kind": "declares_dependency",
                    "scope": dep.get("scope"),
                    "resolved": True,
                }
            )
        for service in fact.get("services", ()):  # type: ignore[union-attr]
            node_id = str(service.get("id"))
            nodes[node_id] = {
                "id": node_id,
                "kind": "service",
                "name": service.get("name"),
                "source": source,
            }
            edges.append(
                {
                    "from": f"file:{source}",
                    "to": node_id,
                    "kind": "declares_service",
                    "resolved": True,
                }
            )
    for fact in facts:
        for service in fact.get("services", ()):  # type: ignore[union-attr]
            source_id = str(service.get("id"))
            for dependency in service.get("depends_on", ()):  # type: ignore[union-attr]
                target_id = f"service:{dependency}"
                if target_id in nodes:
                    edges.append(
                        {
                            "from": source_id,
                            "to": target_id,
                            "kind": "service_depends_on",
                            "resolved": True,
                        }
                    )
                else:
                    unresolved.append(
                        {
                            "source": source_id,
                            "specifier": dependency,
                            "language": "compose",
                            "line": service.get("line"),
                        }
                    )
    edges.sort(
        key=lambda item: (
            str(item["from"]),
            str(item["to"]),
            str(item["kind"]),
            int(item.get("line") or 0),
        )
    )
    return {
        "schema_version": SCHEMA_VERSION,
        "nodes": sorted(nodes.values(), key=lambda item: str(item["id"])),
        "edges": edges,
        "unresolved": sorted(
            unresolved, key=lambda item: (str(item["source"]), str(item["specifier"]))
        ),
    }

def _git_visible_paths(root: Path, *, max_files: int) -> tuple[set[str] | None, dict[str, object]]:
    """Return Git's tracked + untracked, non-ignored source set when available.

    ``git ls-files --exclude-standard`` is the canonical interpreter for root
    and nested gitignore files.  The mapper never approximates wildmatch
    semantics itself.  A bounded failure falls back to the explicit PX default
    exclusions and is recorded in the map manifest.
    """
    command = [
        "git", "-C", str(root), "-c", "core.quotepath=false", "ls-files",
        "-z", "--cached", "--others", "--exclude-standard",
    ]
    try:
        result = subprocess.run(
            command,
            check=True,
            capture_output=True,
            timeout=30,
        )
        # Keep the discovery stage bounded before decoding attacker-controlled
        # path data.  The file-count limit remains the authoritative walk bound.
        output_limit = min(128 * 1024 * 1024, max(1024 * 1024, max_files * 4096))
        if len(result.stdout) > output_limit:
            raise ValueError("git visible-source inventory exceeded its byte bound")
        records = {
            value.decode("utf-8", errors="surrogateescape").replace("\\", "/").strip("/")
            for value in result.stdout.split(b"\0")
            if value
        }
        if len(records) > max_files:
            raise ValueError("git visible-source inventory exceeded max_files")
        directories = {
            parent.as_posix()
            for record in records
            for parent in Path(record).parents
            if parent.as_posix() != "."
        }
        return records | directories, {
            "mode": "git-exclude-standard",
            "available": True,
            "record_count": len(records),
            "command": "git ls-files --cached --others --exclude-standard",
        }
    except (OSError, subprocess.SubprocessError, ValueError) as error:
        return None, {
            "mode": "px-default-excludes-only",
            "available": False,
            "reason": f"{type(error).__name__}: {error}",
        }

def _parse_compose(text: str, relative: str) -> list[dict[str, object]]:
    try:
        import yaml  # type: ignore

        data = yaml.safe_load(text) or {}
        services = []
        for name, spec in sorted((data.get("services") or {}).items()):
            spec = spec or {}
            environment = spec.get("environment") or {}
            if isinstance(environment, list):
                env_keys = sorted(str(item).split("=", 1)[0] for item in environment)
            else:
                env_keys = sorted(map(str, environment.keys()))
            depends = spec.get("depends_on") or []
            if isinstance(depends, Mapping):
                depends = list(depends)
            services.append(
                {
                    "id": f"service:{name}",
                    "name": str(name),
                    "source": relative,
                    "image": str(spec.get("image", "")) or None,
                    "build": str(spec.get("build", ""))
                    if not isinstance(spec.get("build"), Mapping)
                    else str(spec.get("build", {}).get("context", "")),
                    "depends_on": sorted(map(str, depends)),
                    "ports": [str(item) for item in spec.get("ports", ())],
                    "environment_keys": env_keys,
                    "command_declared": "command" in spec,
                }
            )
        return services
    except Exception:
        services: list[dict[str, object]] = []
        lines = text.splitlines()
        in_services = False
        current: dict[str, object] | None = None
        base_indent = 0
        for number, line in enumerate(lines, 1):
            if re.match(r"^services:\s*$", line):
                in_services = True
                base_indent = len(line) - len(line.lstrip())
                continue
            if not in_services:
                continue
            indent = len(line) - len(line.lstrip())
            match = re.match(r"^\s+([A-Za-z0-9_.-]+):\s*$", line)
            if (
                match
                and indent > base_indent
                and (current is None or indent <= int(current.get("indent", indent)))
            ):
                if current:
                    current.pop("indent", None)
                    services.append(current)
                current = {
                    "id": f"service:{match.group(1)}",
                    "name": match.group(1),
                    "source": relative,
                    "line": number,
                    "depends_on": [],
                    "ports": [],
                    "environment_keys": [],
                    "indent": indent,
                }
                continue
            if current:
                scalar = re.match(r"^\s+(image|build|command):\s*(.+)$", line)
                if scalar:
                    key = scalar.group(1)
                    value = scalar.group(2).strip().strip("'\"")
                    current["command_declared" if key == "command" else key] = (
                        True if key == "command" else value
                    )
        if current:
            current.pop("indent", None)
            services.append(current)
        return services

def _resolve_relative_js(source: str, specifier: str, files: set[str]) -> str | None:
    if not specifier.startswith("."):
        return None
    base = (Path(source).parent / specifier).as_posix()
    candidates = [
        base,
        *[
            base + suffix
            for suffix in (".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs", ".json")
        ],
        *[
            (Path(base) / f"index{suffix}").as_posix()
            for suffix in (".ts", ".tsx", ".js", ".jsx")
        ],
    ]
    normalized = {Path(item).as_posix(): item for item in files}
    for candidate in candidates:
        clean = Path(candidate).as_posix()
        if clean in normalized:
            return normalized[clean]
    return None

def _scan_js(text: str, relative: str, language: str) -> dict[str, object]:
    imports = [
        {"specifier": match.group(1), "line": _line_number(text, match.start())}
        for match in JS_IMPORT_RE.finditer(text)
    ]
    symbols: list[dict[str, object]] = []
    for match in JS_SYMBOL_RE.finditer(text):
        kind = match.group(2) or "arrow_function"
        name = match.group(3) or match.group(4)
        symbols.append(
            {
                "name": name,
                "qualname": name,
                "kind": f"{language}_{kind}",
                "line_start": _line_number(text, match.start()),
                "line_end": _line_number(text, match.end()),
            }
        )
    routes = [
        {
            "id": f"route:{relative}:{_line_number(text, m.start())}:{m.group(2)}",
            "path": m.group(2),
            "methods": [m.group(1).upper()],
            "handler": None,
            "file": relative,
            "line": _line_number(text, m.start()),
            "framework_hint": "express_like",
        }
        for m in JS_ROUTE_RE.finditer(text)
    ]
    config_refs = []
    for match in JS_ENV_RE.finditer(text):
        key = match.group(1) or match.group(2)
        config_refs.append(
            {
                "key": key,
                "path": relative,
                "line": _line_number(text, match.start()),
                "access": "process.env",
                "sensitive": bool(SENSITIVE_KEY.search(key)),
            }
        )
    calls = []
    data_flows = []
    for match in JS_CALL_RE.finditer(text):
        callee = match.group(1)
        line = _line_number(text, match.start())
        calls.append({"callee": callee, "caller": "<unknown>", "line": line})
        source, sink, confidence = _classify_call(callee)
        if source or sink:
            data_flows.append(
                {
                    "file": relative,
                    "line": line,
                    "caller": "<unknown>",
                    "operation": callee,
                    "source": source,
                    "sink": sink,
                    "confidence": confidence,
                    "basis": "static_call_pattern",
                }
            )
    contracts = []
    for symbol in symbols:
        if any(term in str(symbol["kind"]) for term in ("interface", "type", "enum")):
            contracts.append(
                {
                    "id": f"{language}:{relative}:{symbol['name']}",
                    "kind": f"{language}_type",
                    "name": symbol["name"],
                    "path": relative,
                    "line": symbol["line_start"],
                }
            )
    tests = [
        {
            "name": symbol["name"],
            "path": relative,
            "line": symbol["line_start"],
            "kind": "test_symbol",
        }
        for symbol in symbols
        if str(symbol["name"]).casefold().startswith(("test", "should"))
    ]
    return {
        "symbols": symbols,
        "imports": imports,
        "calls": calls,
        "routes": routes,
        "config_refs": config_refs,
        "data_flows": data_flows,
        "contracts": contracts,
        "tests": tests,
    }

def _scan_known_config(text: str, relative: str, language: str) -> dict[str, object]:
    name = Path(relative).name.casefold()
    config_keys: list[dict[str, object]] = []
    dependencies: list[dict[str, object]] = []
    entrypoints: list[dict[str, object]] = []
    services: list[dict[str, object]] = []
    contracts: list[dict[str, object]] = []
    ci: list[dict[str, object]] = []
    ownership: list[dict[str, object]] = []
    parse_errors: list[dict[str, object]] = []

    if name == "package.json":
        try:
            data = json.loads(text)
            for section, scope in (
                ("dependencies", "runtime"),
                ("devDependencies", "development"),
                ("peerDependencies", "peer"),
                ("optionalDependencies", "optional"),
            ):
                for package in sorted((data.get(section) or {}).keys()):
                    dependencies.append(
                        {
                            "name": package,
                            "scope": scope,
                            "source": relative,
                            "ecosystem": "npm",
                        }
                    )
            for script in sorted((data.get("scripts") or {}).keys()):
                entrypoints.append(
                    {"kind": "npm_script", "name": script, "source": relative}
                )
            for key in _flatten_keys(data):
                config_keys.append(
                    {
                        "key": key,
                        "path": relative,
                        "line": None,
                        "access": "json_key",
                        "sensitive": bool(SENSITIVE_KEY.search(key)),
                    }
                )
        except json.JSONDecodeError as error:
            parse_errors.append(
                {"code": "json_parse_error", "line": error.lineno, "message": error.msg}
            )
    elif name == "pyproject.toml":
        try:
            data = tomllib.loads(text)
            project = data.get("project", {})
            for raw in project.get("dependencies", ()):
                dependencies.append(
                    {
                        "name": _dependency_name(str(raw)),
                        "scope": "runtime",
                        "source": relative,
                        "ecosystem": "python",
                    }
                )
            for group, values in (
                project.get("optional-dependencies", {}) or {}
            ).items():
                for raw in values:
                    dependencies.append(
                        {
                            "name": _dependency_name(str(raw)),
                            "scope": f"optional:{group}",
                            "source": relative,
                            "ecosystem": "python",
                        }
                    )
            for script, target in (project.get("scripts", {}) or {}).items():
                entrypoints.append(
                    {
                        "kind": "python_console_script",
                        "name": script,
                        "target": str(target),
                        "source": relative,
                    }
                )
            for key in _flatten_keys(data):
                config_keys.append(
                    {
                        "key": key,
                        "path": relative,
                        "line": None,
                        "access": "toml_key",
                        "sensitive": bool(SENSITIVE_KEY.search(key)),
                    }
                )
        except tomllib.TOMLDecodeError as error:
            parse_errors.append(
                {"code": "toml_parse_error", "line": None, "message": str(error)}
            )
    elif name == "cargo.toml":
        try:
            data = tomllib.loads(text)
            for section, scope in (
                ("dependencies", "runtime"),
                ("dev-dependencies", "development"),
                ("build-dependencies", "build"),
            ):
                for package in sorted((data.get(section) or {}).keys()):
                    dependencies.append(
                        {
                            "name": package,
                            "scope": scope,
                            "source": relative,
                            "ecosystem": "cargo",
                        }
                    )
        except tomllib.TOMLDecodeError as error:
            parse_errors.append(
                {"code": "toml_parse_error", "line": None, "message": str(error)}
            )
    elif name == "go.mod":
        for match in re.finditer(r"(?m)^\s*([A-Za-z0-9_.~/-]+)\s+v[0-9]", text):
            dependencies.append(
                {
                    "name": match.group(1),
                    "scope": "runtime",
                    "source": relative,
                    "ecosystem": "go",
                }
            )
    elif name.startswith("requirements") and name.endswith(".txt"):
        for line_number, line in enumerate(text.splitlines(), 1):
            clean = line.split("#", 1)[0].strip()
            if clean and not clean.startswith(("-", "git+", "http:")):
                dependencies.append(
                    {
                        "name": _dependency_name(clean),
                        "scope": "runtime",
                        "source": relative,
                        "ecosystem": "python",
                        "line": line_number,
                    }
                )
    elif name in {
        "docker-compose.yml",
        "docker-compose.yaml",
        "compose.yml",
        "compose.yaml",
    }:
        services.extend(_parse_compose(text, relative))
    elif name == "dockerfile" or name.endswith(".dockerfile"):
        for line_number, line in enumerate(text.splitlines(), 1):
            match = re.match(
                r"\s*(FROM|ENTRYPOINT|CMD|EXPOSE|HEALTHCHECK)\s+(.+)",
                line,
                re.IGNORECASE,
            )
            if match:
                entrypoints.append(
                    {
                        "kind": f"docker_{match.group(1).casefold()}",
                        "name": match.group(2).strip()[:200],
                        "source": relative,
                        "line": line_number,
                    }
                )
    elif name in {"codeowners", "owners"} or relative.casefold().endswith(
        "/.github/codeowners"
    ):
        for line_number, line in enumerate(text.splitlines(), 1):
            clean = line.strip()
            if not clean or clean.startswith("#"):
                continue
            parts = clean.split()
            if len(parts) >= 2:
                ownership.append(
                    {
                        "pattern": parts[0],
                        "owners": parts[1:],
                        "source": relative,
                        "line": line_number,
                    }
                )
    elif relative.casefold().startswith((".github/workflows/", ".gitlab/")) or name in {
        "azure-pipelines.yml",
        "jenkinsfile",
        ".gitlab-ci.yml",
    }:
        jobs = []
        for line_number, line in enumerate(text.splitlines(), 1):
            match = re.match(r"\s{2,}([A-Za-z0-9_.-]+):\s*(?:#.*)?$", line)
            if match and match.group(1) not in {
                "steps",
                "env",
                "with",
                "permissions",
                "on",
            }:
                jobs.append({"name": match.group(1), "line": line_number})
        uses = sorted(set(re.findall(r"\buses:\s*([^\s#]+)", text)))
        ci.append({"source": relative, "jobs": jobs[:100], "external_actions": uses})
    elif language == "json":
        try:
            data = json.loads(text)
            for key in _flatten_keys(data):
                config_keys.append(
                    {
                        "key": key,
                        "path": relative,
                        "line": None,
                        "access": "json_key",
                        "sensitive": bool(SENSITIVE_KEY.search(key)),
                    }
                )
            if isinstance(data, Mapping) and any(
                term in name for term in ("openapi", "swagger")
            ):
                for route, methods in (data.get("paths") or {}).items():
                    for method in methods:
                        if method.casefold() in ROUTE_METHODS:
                            contracts.append(
                                {
                                    "id": f"openapi:{relative}:{method}:{route}",
                                    "kind": "openapi_operation",
                                    "name": f"{method.upper()} {route}",
                                    "path": relative,
                                    "line": None,
                                }
                            )
        except json.JSONDecodeError as error:
            parse_errors.append(
                {"code": "json_parse_error", "line": error.lineno, "message": error.msg}
            )
    elif name.startswith(".env") or language in {"toml", "yaml"}:
        for line_number, line in enumerate(text.splitlines(), 1):
            match = re.match(r"\s*([A-Za-z_][A-Za-z0-9_.-]*)\s*[:=]", line)
            if match:
                key = match.group(1)
                config_keys.append(
                    {
                        "key": key,
                        "path": relative,
                        "line": line_number,
                        "access": "config_declaration",
                        "sensitive": bool(SENSITIVE_KEY.search(key)),
                    }
                )
    if language == "protobuf":
        for match in re.finditer(
            r"(?m)^\s*(message|service|enum)\s+([A-Za-z_][A-Za-z0-9_]*)", text
        ):
            contracts.append(
                {
                    "id": f"proto:{relative}:{match.group(2)}",
                    "kind": f"proto_{match.group(1)}",
                    "name": match.group(2),
                    "path": relative,
                    "line": _line_number(text, match.start()),
                }
            )
    elif language == "graphql":
        for match in re.finditer(
            r"(?m)^\s*(type|input|interface|enum|union|scalar)\s+([A-Za-z_][A-Za-z0-9_]*)",
            text,
        ):
            contracts.append(
                {
                    "id": f"graphql:{relative}:{match.group(2)}",
                    "kind": f"graphql_{match.group(1)}",
                    "name": match.group(2),
                    "path": relative,
                    "line": _line_number(text, match.start()),
                }
            )
    elif language == "sql":
        for match in re.finditer(
            r"(?i)\bCREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?[\"`\[]?([A-Za-z_][A-Za-z0-9_.]*)",
            text,
        ):
            contracts.append(
                {
                    "id": f"sql:{relative}:{match.group(1)}",
                    "kind": "database_table",
                    "name": match.group(1),
                    "path": relative,
                    "line": _line_number(text, match.start()),
                }
            )
    return {
        "config_refs": config_keys,
        "dependencies": dependencies,
        "entrypoints": entrypoints,
        "services": services,
        "contracts": contracts,
        "ci": ci,
        "ownership": ownership,
        "parse_errors": parse_errors,
    }

def _scan_python(text: str, relative: str) -> dict[str, object]:
    scanner = _PythonScanner(relative)
    try:
        tree = ast.parse(text, filename=relative)
    except SyntaxError as error:
        return {
            "parse_errors": [
                {
                    "code": "python_syntax_error",
                    "line": error.lineno,
                    "message": error.msg,
                }
            ]
        }
    scanner.visit(tree)
    return {
        "symbols": scanner.symbols,
        "imports": scanner.imports,
        "calls": scanner.calls,
        "routes": scanner.routes,
        "config_refs": scanner.config_refs,
        "data_flows": scanner.data_flows,
        "contracts": scanner.contracts,
        "tests": scanner.tests,
    }

def _scan_regex_language(text: str, relative: str, language: str) -> dict[str, object]:
    symbols: list[dict[str, object]] = []
    imports: list[dict[str, object]] = []
    routes: list[dict[str, object]] = []
    config_refs: list[dict[str, object]] = []
    contracts: list[dict[str, object]] = []
    if language == "go":
        for match in GO_IMPORT_RE.finditer(text):
            imports.append(
                {
                    "specifier": match.group(1) or match.group(2),
                    "line": _line_number(text, match.start()),
                }
            )
        for match in GO_SYMBOL_RE.finditer(text):
            name = match.group(1) or match.group(2)
            kind = "function" if match.group(1) else match.group(3)
            symbols.append(
                {
                    "name": name,
                    "qualname": name,
                    "kind": f"go_{kind}",
                    "line_start": _line_number(text, match.start()),
                    "line_end": _line_number(text, match.end()),
                }
            )
            if kind in {"struct", "interface"}:
                contracts.append(
                    {
                        "id": f"go:{relative}:{name}",
                        "kind": f"go_{kind}",
                        "name": name,
                        "path": relative,
                        "line": _line_number(text, match.start()),
                    }
                )
        for match in GO_ENV_RE.finditer(text):
            key = match.group(1)
            config_refs.append(
                {
                    "key": key,
                    "path": relative,
                    "line": _line_number(text, match.start()),
                    "access": "os.Getenv",
                    "sensitive": bool(SENSITIVE_KEY.search(key)),
                }
            )
        for match in GO_ROUTE_RE.finditer(text):
            routes.append(
                {
                    "id": f"route:{relative}:{_line_number(text, match.start())}:{match.group(1)}",
                    "path": match.group(1),
                    "methods": ["UNKNOWN"],
                    "handler": None,
                    "file": relative,
                    "line": _line_number(text, match.start()),
                    "framework_hint": "net/http",
                }
            )
    elif language == "rust":
        imports = [
            {"specifier": m.group(1).strip(), "line": _line_number(text, m.start())}
            for m in RUST_IMPORT_RE.finditer(text)
        ]
        for match in RUST_SYMBOL_RE.finditer(text):
            kind, name = match.group(1), match.group(2)
            symbols.append(
                {
                    "name": name,
                    "qualname": name,
                    "kind": f"rust_{kind}",
                    "line_start": _line_number(text, match.start()),
                    "line_end": _line_number(text, match.end()),
                }
            )
            if kind in {"struct", "enum", "trait", "type"}:
                contracts.append(
                    {
                        "id": f"rust:{relative}:{name}",
                        "kind": f"rust_{kind}",
                        "name": name,
                        "path": relative,
                        "line": _line_number(text, match.start()),
                    }
                )
        for match in RUST_ENV_RE.finditer(text):
            key = match.group(1)
            config_refs.append(
                {
                    "key": key,
                    "path": relative,
                    "line": _line_number(text, match.start()),
                    "access": "env::var",
                    "sensitive": bool(SENSITIVE_KEY.search(key)),
                }
            )
    elif language in {"java", "kotlin", "csharp"}:
        import_re = CS_USING_RE if language == "csharp" else JVM_IMPORT_RE
        imports = [
            {"specifier": m.group(1), "line": _line_number(text, m.start())}
            for m in import_re.finditer(text)
        ]
        for match in JVM_SYMBOL_RE.finditer(text):
            kind, name = match.group(1), match.group(2)
            symbols.append(
                {
                    "name": name,
                    "qualname": name,
                    "kind": f"{language}_{kind}",
                    "line_start": _line_number(text, match.start()),
                    "line_end": _line_number(text, match.end()),
                }
            )
            if kind in {"interface", "enum", "record"}:
                contracts.append(
                    {
                        "id": f"{language}:{relative}:{name}",
                        "kind": f"{language}_{kind}",
                        "name": name,
                        "path": relative,
                        "line": _line_number(text, match.start()),
                    }
                )
        route_re = CS_ROUTE_RE if language == "csharp" else SPRING_ROUTE_RE
        for match in route_re.finditer(text):
            method = (
                match.group(1).replace("Http", "").replace("Mapping", "").upper()
                or "UNKNOWN"
            )
            route = match.group(2) or ""
            routes.append(
                {
                    "id": f"route:{relative}:{_line_number(text, match.start())}:{route}",
                    "path": route,
                    "methods": [method],
                    "handler": None,
                    "file": relative,
                    "line": _line_number(text, match.start()),
                    "framework_hint": "annotation_route",
                }
            )
    elif language == "ruby":
        imports = [
            {"specifier": m.group(1), "line": _line_number(text, m.start())}
            for m in RUBY_REQUIRE_RE.finditer(text)
        ]
        for match in RUBY_SYMBOL_RE.finditer(text):
            symbols.append(
                {
                    "name": match.group(2),
                    "qualname": match.group(2),
                    "kind": f"ruby_{match.group(1)}",
                    "line_start": _line_number(text, match.start()),
                    "line_end": _line_number(text, match.end()),
                }
            )
    elif language == "php":
        imports = [
            {"specifier": m.group(1).strip(), "line": _line_number(text, m.start())}
            for m in PHP_USE_RE.finditer(text)
        ]
        for match in PHP_SYMBOL_RE.finditer(text):
            kind, name = match.group(1), match.group(2)
            symbols.append(
                {
                    "name": name,
                    "qualname": name,
                    "kind": f"php_{kind}",
                    "line_start": _line_number(text, match.start()),
                    "line_end": _line_number(text, match.end()),
                }
            )
            if kind in {"interface", "trait"}:
                contracts.append(
                    {
                        "id": f"php:{relative}:{name}",
                        "kind": f"php_{kind}",
                        "name": name,
                        "path": relative,
                        "line": _line_number(text, match.start()),
                    }
                )
    return {
        "symbols": symbols,
        "imports": imports,
        "routes": routes,
        "config_refs": config_refs,
        "contracts": contracts,
    }

def _test_coverage_map(
    facts: Sequence[Mapping[str, object]], dependency_graph: Mapping[str, object]
) -> dict[str, object]:
    test_files = {str(fact["path"]) for fact in facts if fact.get("role") == "test"}
    source_files = {
        str(fact["path"])
        for fact in facts
        if fact.get("role") == "source" and not fact.get("generated")
    }
    links: set[tuple[str, str, str]] = set()
    for edge in dependency_graph.get("edges", ()):
        source = str(edge.get("from", "")).removeprefix("file:")
        target = str(edge.get("to", "")).removeprefix("file:")
        if (
            source in test_files
            and target in source_files
            and edge.get("kind") == "imports"
        ):
            links.add((source, target, "test_import"))
    sources_by_stem: dict[str, list[str]] = defaultdict(list)
    for source in source_files:
        sources_by_stem[Path(source).stem.casefold()].append(source)
    for test in test_files:
        stem = (
            Path(test)
            .stem.casefold()
            .removeprefix("test_")
            .removesuffix("_test")
            .removesuffix(".test")
            .removesuffix(".spec")
        )
        if len(stem) < 3:
            continue
        candidates = sources_by_stem.get(stem, [])
        if len(candidates) == 1:
            links.add((test, candidates[0], "exact_basename"))
            continue
        test_parts = Path(test).parent.parts
        scored: list[tuple[int, str]] = []
        for source in candidates:
            source_parts = Path(source).parent.parts
            common = 0
            for left, right in zip(test_parts, source_parts):
                if left.casefold() != right.casefold():
                    break
                common += 1
            scored.append((common, source))
        best = max((score for score, _source in scored), default=0)
        if best > 0:
            for _score, source in scored:
                if _score == best:
                    links.add((test, source, "exact_basename_directory_affinity"))
    linked_sources = {source for _, source, _ in links}
    linked_tests = {test for test, _, _ in links}
    return {
        "schema_version": SCHEMA_VERSION,
        "coverage_kind": "static_traceability_not_execution_coverage",
        "test_files": sorted(test_files),
        "source_files": sorted(source_files),
        "links": [
            {"test": test, "source": source, "basis": basis}
            for test, source, basis in sorted(links)
        ],
        "untested_source_candidates": sorted(source_files - linked_sources),
        "unmapped_test_files": sorted(test_files - linked_tests),
    }

def project_map_status(
    project: Path, *, verify_integrity: bool = True
) -> dict[str, object]:
    try:
        map_dir = _map_dir(project)
    except ValueError as error:
        return {
            "valid": False,
            "available": False,
            "stale": None,
            "errors": [str(error)],
        }
    if verify_integrity:
        validation = validate_project_map(map_dir, check_freshness=False)
        manifest = (
            _load_json(map_dir / "project-manifest.json")
            if validation["valid"]
            else {}
        )
        validation_scope = "full-byte-integrity"
    else:
        errors: list[str] = []
        try:
            manifest = _load_json(map_dir / "project-manifest.json")
            receipt = _load_json(map_dir / "map-receipt.json")
            expected_receipt_hash = receipt.get("receipt_sha256")
            receipt_payload = dict(receipt)
            receipt_payload.pop("receipt_sha256", None)
            if expected_receipt_hash != _stable_hash(receipt_payload):
                errors.append("map receipt hash mismatch")
            if receipt.get("map_revision") != manifest.get("map_revision"):
                errors.append("receipt map revision does not match manifest")
            if receipt.get("source_inventory_sha256") != manifest.get(
                "source_inventory_sha256"
            ):
                errors.append("receipt source inventory does not match manifest")
            recorded_files = receipt.get("file_sha256", {})
            if not isinstance(recorded_files, dict):
                errors.append("map receipt file inventory is invalid")
                recorded_files = {}
            for name in REQUIRED_MAP_FILES:
                if not (map_dir / name).is_file():
                    errors.append(f"missing map file: {name}")
                elif name != "map-receipt.json" and name not in recorded_files:
                    errors.append(f"map file is absent from receipt: {name}")
        except (OSError, ValueError, json.JSONDecodeError) as error:
            manifest = {}
            errors.append(f"map projection parse failure: {error}")
        validation = {"valid": not errors, "errors": errors}
        validation_scope = "sealed-projection-metadata"
    return {
        "valid": validation["valid"],
        "available": True,
        "map_dir": map_dir.as_posix(),
        "map_revision": manifest.get("map_revision"),
        "source_inventory_sha256": manifest.get("source_inventory_sha256"),
        "counts": manifest.get("counts", {}),
        "errors": validation.get("errors", []),
        "freshness": "not_checked",
        "validation_scope": validation_scope,
        "content_hashes_verified": verify_integrity,
    }

def validate_project_map(
    project_or_map: Path, *, check_freshness: bool = False
) -> dict[str, object]:
    errors: list[str] = []
    warnings: list[str] = []
    try:
        map_dir = _map_dir(project_or_map)
    except ValueError as error:
        return {"valid": False, "errors": [str(error)], "warnings": []}
    for name in REQUIRED_MAP_FILES:
        if not (map_dir / name).is_file():
            errors.append(f"missing map file: {name}")
    if errors:
        return {
            "valid": False,
            "map_dir": map_dir.as_posix(),
            "errors": errors,
            "warnings": warnings,
        }
    try:
        manifest = _load_json(map_dir / "project-manifest.json")
        receipt = _load_json(map_dir / "map-receipt.json")
        inventory = _load_jsonl(map_dir / "file-inventory.jsonl")
        facts = _load_jsonl(map_dir / "file-facts.jsonl")
        symbols = _load_jsonl(map_dir / "symbol-index.jsonl")
        retrieval = _load_json(map_dir / "retrieval-index.json")
        configuration = _load_json(map_dir / "configuration-map.json")
    except (OSError, ValueError, json.JSONDecodeError) as error:
        return {
            "valid": False,
            "map_dir": map_dir.as_posix(),
            "errors": [f"map parse failure: {error}"],
            "warnings": warnings,
        }
    for name, expected in receipt.get("file_sha256", {}).items():
        path = map_dir / name
        if not path.is_file() or _sha_file(path) != expected:
            errors.append(f"map file hash mismatch: {name}")
    inventory_sha = _inventory_digest(inventory)
    if inventory_sha != manifest.get("source_inventory_sha256"):
        errors.append("source inventory digest does not match manifest")
    if receipt.get("map_revision") != manifest.get("map_revision"):
        errors.append("receipt map revision does not match manifest")
    if len(inventory) != manifest.get("counts", {}).get("files"):
        errors.append("file count does not match manifest")
    if len(symbols) != manifest.get("counts", {}).get("symbols"):
        errors.append("symbol count does not match manifest")
    fact_paths = {str(item.get("path")) for item in facts}
    inventory_paths = {str(item.get("path")) for item in inventory}
    if fact_paths != inventory_paths:
        errors.append("file facts and inventory path sets differ")
    forbidden_inventory = sorted(path for path in inventory_paths if _excluded_source(path))
    caller_exclude_prefixes = _normalize_exclude_prefixes(
        manifest.get("caller_exclude_prefixes", ())
    )
    forbidden_inventory.extend(
        sorted(
            path
            for path in inventory_paths
            if _matches_exclude_prefix(path, caller_exclude_prefixes)
        )
    )
    if forbidden_inventory:
        errors.append(
            "sensitive/excluded source paths entered inventory: "
            + ", ".join(forbidden_inventory[:10])
        )
    documents = retrieval.get("documents", [])
    if len(documents) != retrieval.get("document_count"):
        errors.append("retrieval document count is inconsistent")
    identifiers = [str(item.get("id")) for item in documents]
    if len(identifiers) != len(set(identifiers)):
        errors.append("retrieval document identifiers are not unique")
    forbidden_documents = sorted(
        {
            str(item.get("path"))
            for item in documents
            if item.get("path")
            and (
                _excluded_source(str(item.get("path")))
                or _matches_exclude_prefix(
                    str(item.get("path")), caller_exclude_prefixes
                )
            )
        }
    )
    if forbidden_documents:
        errors.append(
            "sensitive/excluded source paths entered retrieval: "
            + ", ".join(forbidden_documents[:10])
        )
    document_count = len(documents)
    for token, postings in retrieval.get("postings", {}).items():
        for posting in postings:
            if (
                not isinstance(posting, list)
                or len(posting) != 2
                or not isinstance(posting[0], int)
                or posting[0] < 0
                or posting[0] >= document_count
            ):
                errors.append(f"invalid retrieval posting for token {token}")
                break
    forbidden_fields = {
        "value",
        "secret",
        "password",
        "token",
        "credential",
        "connection_string",
    }
    for key in configuration.get("keys", ()):
        if forbidden_fields.intersection(key):
            errors.append(
                f"configuration map contains prohibited value field for {key.get('key')}"
            )
    if check_freshness:
        project_root = Path(str(manifest.get("project_root", "")))
        if not project_root.is_dir():
            warnings.append(
                "freshness check skipped because recorded project root is unavailable"
            )
        else:
            try:
                git_policy = manifest.get("gitignore_policy", {})
                git_visible_paths = None
                if isinstance(git_policy, Mapping) and git_policy.get("mode") == "git-exclude-standard":
                    git_visible_paths, current_git_policy = _git_visible_paths(
                        project_root, max_files=int(manifest["limits"]["max_files"])
                    )
                    if git_visible_paths is None:
                        raise ValueError(
                            "freshness cannot reproduce recorded gitignore policy: "
                            + str(current_git_policy.get("reason") or "unavailable")
                        )

                def exclude_current_source(relative: str) -> bool:
                    return (
                        _excluded_source(relative)
                        or _matches_exclude_prefix(relative, caller_exclude_prefixes)
                        or (git_visible_paths is not None and relative not in git_visible_paths)
                    )

                walk = bounded_walk(
                    project_root,
                    limits=WalkLimits(
                        max_files=int(manifest["limits"]["max_files"]),
                        max_depth=int(manifest["limits"]["max_depth"]),
                        max_bytes=int(manifest["limits"]["max_bytes"]),
                    ),
                    symlink_policy="reject",
                    exclude=exclude_current_source,
                )
                current = [
                    {
                        "path": entry.relative,
                        "size_bytes": entry.size or 0,
                        "sha256": _sha_file(entry.path),
                    }
                    for entry in walk.files
                ]
                current.sort(key=lambda item: str(item["path"]))
                if _stable_hash(current) != manifest.get("source_inventory_sha256"):
                    errors.append(
                        "project map is stale relative to the current source tree"
                    )
            except (OSError, FilesystemWalkError, ValueError) as error:
                errors.append(f"freshness walk failed: {error}")
    return {
        "valid": not errors,
        "map_dir": map_dir.as_posix(),
        "map_revision": manifest.get("map_revision"),
        "source_inventory_sha256": manifest.get("source_inventory_sha256"),
        "errors": errors,
        "warnings": warnings,
        "counts": manifest.get("counts", {}),
    }

def validate_project_management(project: Path) -> list[str]:
    root = project.resolve()
    errors: list[str] = []
    if not (root / "PROJECT_MANAGEMENT.md").is_file():
        errors.append("missing PROJECT_MANAGEMENT.md")
    for name in CONTROL_FILES:
        if not (root / CONTROL_DIR / name).is_file():
            errors.append(f"missing {(CONTROL_DIR / name).as_posix()}")
    for name in COMPACT_OUTPUT_FILES:
        if not (root / name).is_file():
            errors.append(f"missing {name}")
    state_path = root / CONTROL_DIR / "state.json"
    if not state_path.is_file():
        errors.append(f"missing {(CONTROL_DIR / 'state.json').as_posix()}")
        return errors
    try:
        state = json.loads(state_path.read_text(encoding="utf-8"))
        validate_instance(
            state, framework_root() / "contracts" / "project-management.schema.json"
        )
        if state.get("schema_version") != "1.0":
            errors.append("invalid project-management schema version")
        if state.get("project", {}).get("mode") not in {"new", "existing"}:
            errors.append("invalid project-management mode")
        if state.get("controls", {}).get("maximum_selected_skills") != 3:
            errors.append("invalid project-management skill budget")
        if state.get("controls", {}).get("quarantine_only_cleanup") is not True:
            errors.append("project management does not enforce quarantine-only cleanup")
        checkpoint = state.get("checkpoint", {})
        if (
            not isinstance(checkpoint.get("revision"), int)
            or checkpoint["revision"] < 1
            or checkpoint.get("next_safe_action")
            != state.get("lifecycle", {}).get("next_action")
        ):
            errors.append(
                "project-management checkpoint is incomplete or unsynchronized"
            )
    except (OSError, ValueError, json.JSONDecodeError) as error:
        errors.append(f"invalid project-management state: {error}")
    return errors

def _load_json_cached(
    path_text: str, modified_ns: int, size_bytes: int
) -> dict[str, Any]:
    """Load immutable promoted-map JSON once per observed file revision."""
    del modified_ns, size_bytes
    return json.loads(Path(path_text).read_text(encoding="utf-8"))

def _load_map_json(path: Path) -> dict[str, Any]:
    stat = path.stat()
    return _load_json_cached(path.as_posix(), stat.st_mtime_ns, stat.st_size)

def decision_frontier(document: Mapping[str, object]) -> dict[str, object]:
    tickets = _ticket_map(document)
    cycles = find_cycles(document)
    if cycles:
        return {
            "valid": False,
            "frontier": [],
            "cycles": [list(item) for item in cycles],
            "errors": ["decision graph contains a cycle"],
        }
    closed = {
        identifier
        for identifier, row in tickets.items()
        if str(row.get("status", "open")) in CLOSED_STATES
    }
    ready = []
    for identifier, row in tickets.items():
        if identifier in closed or row.get("claimed_by"):
            continue
        blockers = tuple(map(str, row.get("blocked_by", ())))
        if all(blocker in closed for blocker in blockers):
            ready.append(dict(row))
    ready.sort(
        key=lambda row: (
            -float(row.get("impact", 0.0)),
            -float(row.get("irreversibility", 0.0)),
            -float(row.get("uncertainty", 0.0)),
            float(row.get("answer_cost", 1.0)),
            str(row["id"]),
        )
    )
    canonical = json.dumps(
        ready, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    )
    return {
        "valid": True,
        "frontier": ready,
        "cycles": [],
        "closed_count": len(closed),
        "ticket_count": len(tickets),
        "frontier_sha256": hashlib.sha256(canonical.encode("utf-8")).hexdigest(),
        "errors": [],
    }

def find_cycles(document: Mapping[str, object]) -> tuple[tuple[str, ...], ...]:
    tickets = _ticket_map(document)
    graph = {
        identifier: tuple(sorted(set(map(str, row.get("blocked_by", ())))))
        for identifier, row in tickets.items()
    }
    visited: set[str] = set()
    active: list[str] = []
    cycles: set[tuple[str, ...]] = set()

    def visit(identifier: str) -> None:
        if identifier in active:
            cycle = active[active.index(identifier) :] + [identifier]
            core = cycle[:-1]
            rotations = [
                tuple(core[index:] + core[:index]) for index in range(len(core))
            ]
            canonical = min(rotations)
            cycles.add((*canonical, canonical[0]))
            return
        if identifier in visited:
            return
        active.append(identifier)
        for blocker in graph[identifier]:
            visit(blocker)
        active.pop()
        visited.add(identifier)

    for identifier in sorted(graph):
        visit(identifier)
    return tuple(sorted(cycles))

def audit_glossary(
    glossary: Mapping[str, object],
    paths: Iterable[Path],
    *,
    project_root: Path,
    max_file_bytes: int = 1_000_000,
) -> dict[str, object]:
    root = project_root.resolve(strict=True)
    terms = glossary.get("terms", ())
    if not isinstance(terms, Sequence) or isinstance(terms, (str, bytes)):
        raise ValueError("glossary terms must be an array")
    aliases: list[tuple[str, str]] = []
    canonical_seen: set[str] = set()
    for item in terms:
        if not isinstance(item, Mapping):
            raise ValueError("glossary term must be an object")
        canonical = str(item.get("canonical", "")).strip()
        if not canonical or canonical.casefold() in canonical_seen:
            raise ValueError("canonical terms must be nonempty and unique")
        canonical_seen.add(canonical.casefold())
        for alias in item.get("aliases", ()):
            value = str(alias).strip()
            if value and value.casefold() != canonical.casefold():
                aliases.append((value, canonical))
    selected_paths = tuple(sorted({item.resolve(strict=True) for item in paths}))
    issues = []
    skipped = []
    for path in selected_paths:
        try:
            relative = path.relative_to(root).as_posix()
        except ValueError as error:
            raise ValueError(f"glossary audit path escapes project: {path}") from error
        if not path.is_file() or path.stat().st_size > max_file_bytes:
            skipped.append(relative)
            continue
        text = path.read_text(encoding="utf-8", errors="replace")
        for alias, canonical in aliases:
            pattern = re.compile(r"(?i)(?<!\w)" + re.escape(alias) + r"(?!\w)")
            for match in pattern.finditer(text):
                issues.append(
                    {
                        "path": relative,
                        "line": text.count("\n", 0, match.start()) + 1,
                        "alias": match.group(0),
                        "canonical": canonical,
                    }
                )
    issues.sort(key=lambda item: (item["path"], item["line"], item["alias"].casefold()))
    return {
        "valid": not issues,
        "issue_count": len(issues),
        "issues": issues,
        "skipped": sorted(skipped),
        "files_checked": len(selected_paths) - len(skipped),
    }

"""Fail-closed project, session, lease, and transfer boundary controls.

These controls are deliberately side-effect free. They validate or produce plans;
callers must use separately authorized adapters to mutate repositories or state.
"""

from __future__ import annotations

from dataclasses import asdict, dataclass
from datetime import datetime, timezone
import hashlib
import json
import re
from typing import Iterable, Mapping

from .trusted_evidence import EvidenceScope, ResolvedEvidence, TrustedEvidenceResolver


ID_PATTERN = re.compile(r"^[a-z][a-z0-9_-]{2,127}$")
PRIVATE_KINDS = frozenset(
    {"memory", "embedding", "prompt", "log", "source", "agent_state"}
)
GLOBAL_ALLOWED_KINDS = frozenset({"constitution", "policy", "sanitized_capability"})


def _stable(value: object) -> str:
    return hashlib.sha256(
        json.dumps(value, sort_keys=True, separators=(",", ":"), default=str).encode(
            "utf-8"
        )
    ).hexdigest()


@dataclass(frozen=True, slots=True)
class ScopeEnvelope:
    workspace_id: str
    project_id: str
    agent_id: str
    session_id: str
    workstream_id: str
    lease_id: str
    intent_id: str
    correlation_id: str

    def errors(self) -> tuple[str, ...]:
        missing = []
        for name, value in asdict(self).items():
            if not value or not ID_PATTERN.fullmatch(value):
                missing.append(f"invalid_{name}")
        return tuple(missing)


@dataclass(frozen=True, slots=True)
class ContextObject:
    source_id: str
    namespace_type: str
    project_id: str | None
    kind: str
    classification: str
    provenance: str
    transfer_id: str | None = None


@dataclass(frozen=True, slots=True)
class BoundaryDecision:
    decision: str
    reasons: tuple[str, ...]
    allowed_source_ids: tuple[str, ...]
    denied_source_ids: tuple[str, ...]
    receipt_hash: str


def authorize_context(
    scope: ScopeEnvelope,
    objects: Iterable[ContextObject],
    *,
    approved_transfer_ids: Iterable[str] = (),
) -> BoundaryDecision:
    """Authorize minimum context for exactly one project namespace."""
    scope_errors = scope.errors()
    if scope_errors:
        return BoundaryDecision("deny", scope_errors, (), (), _stable(scope_errors))
    approved = set(approved_transfer_ids)
    allowed: list[str] = []
    denied: list[str] = []
    reasons: set[str] = set()
    for item in objects:
        if not item.source_id or not item.provenance or not item.classification:
            denied.append(item.source_id or "untagged")
            reasons.add("untagged_or_unprovenanced_context")
        elif item.namespace_type == "project" and item.project_id == scope.project_id:
            allowed.append(item.source_id)
        elif item.namespace_type == "global" and item.kind in GLOBAL_ALLOWED_KINDS:
            allowed.append(item.source_id)
        elif (
            item.namespace_type == "transfer"
            and item.transfer_id
            and item.transfer_id in approved
            and item.project_id == scope.project_id
        ):
            allowed.append(item.source_id)
        else:
            denied.append(item.source_id)
            reasons.add("foreign_or_unapproved_context")
        if item.namespace_type == "global" and item.kind in PRIVATE_KINDS:
            if item.source_id in allowed:
                allowed.remove(item.source_id)
            if item.source_id not in denied:
                denied.append(item.source_id)
            reasons.add("private_payload_in_global_namespace")
    decision = "allow" if not denied else "deny"
    payload = {
        "scope": asdict(scope),
        "allowed": sorted(allowed),
        "denied": sorted(denied),
        "reasons": sorted(reasons),
    }
    return BoundaryDecision(
        decision,
        tuple(sorted(reasons)),
        tuple(sorted(allowed)),
        tuple(sorted(denied)),
        _stable(payload),
    )


@dataclass(frozen=True, slots=True)
class LeaseRequest:
    scope: ScopeEnvelope
    writable: bool
    expires_at: datetime
    tools: tuple[str, ...]
    roots: tuple[str, ...]
    side_effect_budget: Mapping[str, int]


@dataclass(frozen=True, slots=True)
class LeaseDecision:
    decision: str
    reasons: tuple[str, ...]
    lease_fingerprint: str


def authorize_lease(
    request: LeaseRequest, existing: Iterable[LeaseRequest] = ()
) -> LeaseDecision:
    reasons = list(request.scope.errors())
    now = datetime.now(timezone.utc)
    expiry = request.expires_at
    if expiry.tzinfo is None or expiry <= now:
        reasons.append("lease_not_future_expiring")
    if not request.tools or not request.roots:
        reasons.append("lease_scope_incomplete")
    if any(
        not isinstance(value, int) or isinstance(value, bool) or value < 0
        for value in request.side_effect_budget.values()
    ):
        reasons.append("invalid_side_effect_budget")
    for lease in existing:
        if (
            request.writable
            and lease.writable
            and lease.scope.session_id == request.scope.session_id
            and lease.scope.project_id != request.scope.project_id
            and lease.expires_at > now
        ):
            reasons.append("session_has_foreign_writable_lease")
    fingerprint = _stable(
        {
            "scope": asdict(request.scope),
            "writable": request.writable,
            "expires_at": request.expires_at.isoformat(),
            "tools": sorted(request.tools),
            "roots": sorted(request.roots),
            "budget": dict(request.side_effect_budget),
        }
    )
    return LeaseDecision(
        "allow" if not reasons else "deny", tuple(sorted(set(reasons))), fingerprint
    )


