def execute_project_stream(
    root: Path,
    context: ProjectStreamContext,
    *,
    checkpoint_root: Path,
    handlers: Mapping[str, Handler] | None = None,
) -> ProjectStreamResult:
    registry = _load(root / "registry" / "project_stream_orchestrations.json")
    workflows = {
        str(item["orchestration_id"]): item for item in registry["orchestrations"]
    }
    workflow = workflows.get(context.workflow_id)
    if workflow is None:
        return ProjectStreamResult(
            context.workflow_id, "blocked", ("unknown_workflow",), {}, (), None
        )
    checkpoints = []
    required_values = (
        context.workspace_id,
        context.agent_id,
        context.session_id,
        context.intent_id,
        context.correlation_id,
    )
    if not all(value.strip() for value in required_values):
        return ProjectStreamResult(
            context.workflow_id, "blocked", ("required_context_missing",), {}, (), None
        )
    if context.workflow_id != "workspace_bootstrap" and not context.project_id.strip():
        return ProjectStreamResult(
            context.workflow_id, "blocked", ("project_binding_missing",), {}, (), None
        )
    if context.timeout_seconds < 1 or context.timeout_seconds > 3600:
        return ProjectStreamResult(
            context.workflow_id,
            "blocked",
            ("workflow_timeout_outside_budget",),
            {},
            (),
            None,
        )
    if _authorization_expired(context):
        return ProjectStreamResult(
            context.workflow_id, "blocked", ("project_lease_expired",), {}, (), None
        )
    missing_preflight = tuple(
        name
        for name in workflow["preflight"]
        if context.preflight.get(name) is not True
    )
    if missing_preflight:
        return ProjectStreamResult(
            context.workflow_id,
            "blocked",
            tuple(f"preflight_failed:{name}" for name in missing_preflight),
            {},
            (),
            None,
        )
    checkpoints.append(
        _append_checkpoint(
            checkpoint_root, context, "preflight", "passed", context.preflight
        )
    )
    registry_handlers = _load(root / "registry" / "project_stream_handlers.json")
    binding = next(
        item
        for item in registry_handlers["workflows"]
        if item["orchestration_id"] == context.workflow_id
    )
    if binding["status"] != "executable":
        checkpoints.append(
            _append_checkpoint(
                checkpoint_root, context, "activation", "blocked", binding
            )
        )
        return ProjectStreamResult(
            context.workflow_id,
            "plan_only",
            ("workflow_implementation_not_admitted",),
            {
                "skills": tuple(workflow["skills"]),
                "outcomes": tuple(workflow["outcomes"]),
            },
            tuple(checkpoints),
            None,
        )
    effects = set(map(str, binding["effects"]))
    if not effects <= set(context.approved_effects):
        return ProjectStreamResult(
            context.workflow_id,
            "blocked",
            ("effects_not_approved",),
            {},
            tuple(checkpoints),
            str(binding["handler"]),
        )
    if effects - {"read_local"} and not context.approval:
        return ProjectStreamResult(
            context.workflow_id,
            "blocked",
            ("explicit_approval_missing",),
            {},
            tuple(checkpoints),
            str(binding["handler"]),
        )
    active_handlers = dict(BUILTIN_HANDLERS if handlers is None else handlers)
    handler = active_handlers.get(context.workflow_id)
    if handler is None:
        return ProjectStreamResult(
            context.workflow_id,
            "blocked",
            ("runtime_handler_missing",),
            {},
            tuple(checkpoints),
            str(binding["handler"]),
        )
    if _authorization_expired(context):
        checkpoints.append(
            _append_checkpoint(
                checkpoint_root,
                context,
                "authorization",
                "blocked",
                {"reason": "project_lease_expired"},
            )
        )
        return ProjectStreamResult(
            context.workflow_id,
            "blocked",
            ("project_lease_expired",),
            {},
            tuple(checkpoints),
            str(binding["handler"]),
        )
    started = datetime.now(timezone.utc)
    try:
        outputs = dict(handler(context))
    except Exception as error:
        checkpoints.append(
            _append_checkpoint(
                checkpoint_root,
                context,
                "execution",
                "failed",
                {"error": type(error).__name__},
            )
        )
        return ProjectStreamResult(
            context.workflow_id,
            "failed",
            (f"{type(error).__name__}:{error}",),
            {},
            tuple(checkpoints),
            str(binding["handler"]),
        )
    elapsed = (datetime.now(timezone.utc) - started).total_seconds()
    if _authorization_expired(context) or elapsed > context.timeout_seconds:
        reason = (
            "project_lease_expired"
            if _authorization_expired(context)
            else "workflow_timeout_exceeded"
        )
        checkpoints.append(
            _append_checkpoint(
                checkpoint_root,
                context,
                "verification",
                "failed",
                {"reason": reason, "elapsed_seconds": elapsed},
            )
        )
        return ProjectStreamResult(
            context.workflow_id,
            "failed",
            (reason,),
            {},
            tuple(checkpoints),
            str(binding["handler"]),
        )
    missing_outcomes = tuple(
        name for name in workflow["outcomes"] if name not in outputs
    )
    status = "completed" if not missing_outcomes else "incomplete"
    checkpoints.append(
        _append_checkpoint(checkpoint_root, context, "verification", status, outputs)
    )
    return ProjectStreamResult(
        context.workflow_id,
        status,
        tuple(f"outcome_missing:{name}" for name in missing_outcomes),
        outputs,
        tuple(checkpoints),
        str(binding["handler"]),
    )

def memory_maintenance(context: ProjectStreamContext) -> Mapping[str, object]:
    vault = context.payload.get("vault")
    if not isinstance(vault, MemoryVault):
        raise ValueError("memory maintenance requires a MemoryVault")
    before = vault.reconcile_indexes()
    if before["orphan_generations"]:
        return {
            "memory_health_report": "review_required",
            "index": before,
            "action": "quarantine_orphans_after_human_review",
            "hard_delete": False,
        }
    generation = vault.build_index()
    validation = vault.validate_index_generation(generation.generation)
    if validation["valid"] is not True:
        raise ValueError("memory index candidate failed deterministic validation")
    activation = vault.promote_index(generation.generation, approved=context.approval)
    return {
        "memory_health_report": "index_published",
        "generation": asdict(generation),
        "validation": validation,
        "activation": activation,
        "authoritative_generation": f"{generation.generation:06d}",
        "previous_generations_preserved": True,
        "hard_delete": False,
    }

