def _assert_known_projection_current(
    root: Path, projection_id: str, output: str
) -> None:
    """Refuse to record fresh revisions for known stale projection bytes."""
    known = {
        "semantic-capability-index",
        "cognitive-map-index",
        "agency-agent-graph",
        "registry-envelope-inventory",
    }
    if projection_id not in known:
        return
    path = root / output
    try:
        actual = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        raise ValueError(f"{projection_id}: projection output is unreadable") from error
    if projection_id == "semantic-capability-index":
        from .semantic_index import build_semantic_index

        expected = build_semantic_index(root)
    elif projection_id == "cognitive-map-index":
        from .cognitive_core.index_builder import build_cognitive_index

        expected = build_cognitive_index(root)
    elif projection_id == "agency-agent-graph":
        from .agent_provider import build_agent_graph

        expected = build_agent_graph(root)
    elif projection_id == "registry-envelope-inventory":
        from scripts.build_registry_envelope_inventory import build_inventory

        expected = build_inventory()
    if actual != expected:
        raise ValueError(
            f"{projection_id}: registered builder output is stale; rebuild before revision reconciliation"
        )

def _validate(root: Path, payload: Mapping[str, object]) -> None:
    if payload.get("schema_version") != SCHEMA_VERSION:
        raise ValueError("unsupported projection dependency schema")
    rows = payload.get("projections")
    if not isinstance(rows, list) or not rows:
        raise ValueError("projection registry must contain projections")
    ids: set[str] = set()
    outputs: set[str] = set()
    adjacency: dict[str, set[str]] = defaultdict(set)
    indegree: dict[str, int] = {}
    for row in rows:
        if not isinstance(row, Mapping):
            raise ValueError("projection record must be an object")
        projection_id = str(row.get("projection_id", ""))
        output = str(row.get("output", ""))
        builder = str(row.get("builder", ""))
        if not projection_id or projection_id in ids:
            raise ValueError("projection IDs must be non-empty and unique")
        if not output or output in outputs:
            raise ValueError("projection outputs must be non-empty and unique")
        ids.add(projection_id)
        outputs.add(output)
        indegree[output] = 0
        if not (root / builder).is_file():
            raise ValueError(f"unknown projection builder: {builder}")
        if row.get("cost") not in COSTS or row.get("rebuild_gate") not in GATES:
            raise ValueError(f"{projection_id}: invalid cost or rebuild gate")
        if (
            row.get("cost") == "expensive"
            and row.get("rebuild_gate") != "block_until_rebuilt"
        ):
            raise ValueError(f"{projection_id}: expensive projection must fail closed")
        if not SHA256.fullmatch(str(row.get("output_revision", ""))):
            raise ValueError(f"{projection_id}: output revision is required")
        dependencies = row.get("dependencies")
        if not isinstance(dependencies, list) or not dependencies:
            raise ValueError(f"{projection_id}: dependencies are required")
        for dependency in dependencies:
            if not isinstance(dependency, Mapping):
                raise ValueError(f"{projection_id}: dependency must be an object")
            path = str(dependency.get("path", ""))
            if not path or not SHA256.fullmatch(str(dependency.get("revision", ""))):
                raise ValueError(f"{projection_id}: dependency revision is required")
            if not (root / path).exists():
                raise ValueError(f"{projection_id}: dependency does not exist: {path}")
    by_output = {str(row["output"]): row for row in rows}
    for row in rows:
        output = str(row["output"])
        for dependency in row["dependencies"]:
            source = str(dependency["path"])
            if source in by_output:
                adjacency[source].add(output)
                indegree[output] += 1
    queue = deque(sorted(path for path, count in indegree.items() if count == 0))
    visited = 0
    while queue:
        current = queue.popleft()
        visited += 1
        for consumer in sorted(adjacency[current]):
            indegree[consumer] -= 1
            if indegree[consumer] == 0:
                queue.append(consumer)
    if visited != len(indegree):
        raise ValueError("projection dependency cycle")

def build_projection_staleness(
    registry: Mapping[str, object],
) -> dict[str, object]:
    """Project one reconciled registry into a bounded all-current status."""
    rows = registry.get("projections")
    if not isinstance(rows, list):
        raise ValueError("projection dependency registry is invalid")
    projections = []
    for row in rows:
        if not isinstance(row, Mapping):
            raise ValueError("projection dependency row is invalid")
        projections.append(
            {
                "output": str(row.get("output") or ""),
                "output_revision": str(row.get("output_revision") or ""),
                "projection_id": str(row.get("projection_id") or ""),
                "stale": False,
            }
        )
    return {
        "consumer_policy": "block_until_governed_rebuild",
        "projections": projections,
        "schema_version": "px.projection-staleness/1.0",
    }

def invalidate_projections(
    root: Path, registry: Mapping[str, object] | None = None
) -> dict[str, object]:
    resolved = root.resolve()
    payload = dict(registry) if registry is not None else load_projection_dependencies(resolved)
    _validate(resolved, payload)
    rows = {str(row["output"]): row for row in payload["projections"]}
    stale: dict[str, dict[str, object]] = {}
    for output, row in sorted(rows.items()):
        changed = []
        for dependency in row["dependencies"]:
            path = str(dependency["path"])
            current = revision_for_path(resolved, path)
            if current != dependency["revision"]:
                changed.append(path)
        if not (resolved / output).is_file() or revision_for_path(resolved, output) != row["output_revision"]:
            changed.append(output)
        if changed:
            stale[output] = {
                "projection_id": row["projection_id"],
                "output": output,
                "reasons": tuple(sorted(set(changed))),
                "cost": row["cost"],
                "rebuild_gate": row["rebuild_gate"],
            }
    changed = True
    while changed:
        changed = False
        for output, row in sorted(rows.items()):
            if output in stale:
                continue
            upstream = sorted(
                str(item["path"])
                for item in row["dependencies"]
                if str(item["path"]) in stale
            )
            if upstream:
                stale[output] = {
                    "projection_id": row["projection_id"],
                    "output": output,
                    "reasons": tuple(upstream),
                    "cost": row["cost"],
                    "rebuild_gate": row["rebuild_gate"],
                }
                changed = True
    return {
        "schema_version": "px.projection-invalidation/1.0",
        "valid": True,
        "stale": tuple(stale[key] for key in sorted(stale)),
        "fresh_outputs": tuple(sorted(set(rows) - set(stale))),
    }

def reconcile_graph_authority_manifest(root: Path) -> dict[str, object]:
    """Refresh only declared graph and source revisions after graph builders run."""
    resolved = root.resolve(strict=True)
    path = resolved / "registry/graph_authority_manifest.json"
    payload = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(payload, Mapping) or not isinstance(payload.get("graphs"), list):
        raise ValueError("graph authority manifest is invalid")
    graphs = []
    for row in payload["graphs"]:
        if not isinstance(row, Mapping) or not isinstance(row.get("source_revisions"), list):
            raise ValueError("graph authority row is invalid")
        graphs.append(
            {
                **dict(row),
                "graph_revision": revision_for_path(resolved, str(row.get("path") or "")),
                "source_revisions": [
                    {**dict(item), "revision": revision_for_path(resolved, str(item.get("path") or ""))}
                    for item in row["source_revisions"]
                    if isinstance(item, Mapping)
                ],
            }
        )
    current = {**dict(payload), "graphs": graphs}
    report = validate_graph_authority_manifest(resolved, current)
    if not report["valid"]:
        raise ValueError("reconciled graph authority is invalid: " + "; ".join(report["errors"]))
    prepared = path.with_name(f".{path.name}.{uuid4().hex}.prepared")
    prepared.write_text(json.dumps(current, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    os.replace(prepared, path)
    return current

def reconcile_projection_dependencies(root: Path) -> dict[str, object]:
    """Publish exact current output/dependency revisions after registered builders run."""
    resolved = root.resolve(strict=True)
    path = resolved / "registry/projection_dependencies.json"
    payload = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(payload, Mapping) or not isinstance(payload.get("projections"), list):
        raise ValueError("projection dependency registry is invalid")
    projections = []
    for row in payload["projections"]:
        if not isinstance(row, Mapping):
            raise ValueError("projection dependency row is invalid")
        output = str(row.get("output") or "")
        projection_id = str(row.get("projection_id") or "")
        dependencies = row.get("dependencies")
        if not isinstance(dependencies, list):
            raise ValueError("projection dependency list is invalid")
        _assert_known_projection_current(resolved, projection_id, output)
        projections.append(
            {
                **dict(row),
                "output_revision": revision_for_path(resolved, output),
                "dependencies": [
                    {**dict(item), "revision": revision_for_path(resolved, str(item.get("path") or ""))}
                    for item in dependencies
                    if isinstance(item, Mapping)
                ],
            }
        )
    current = {**dict(payload), "projections": projections}
    _validate(resolved, current)
    encoded = json.dumps(current, indent=2, sort_keys=True).encode("utf-8") + b"\n"
    prepared = path.with_name(f".{path.name}.{uuid4().hex}.prepared")
    prepared.write_bytes(encoded)
    os.replace(prepared, path)
    return current

def revision_for_path(root: Path, relative: str) -> str:
    target = (root.resolve() / relative).resolve()
    try:
        target.relative_to(root.resolve())
    except ValueError as error:
        raise ValueError(f"projection path escapes repository: {relative}") from error
    if target.is_file():
        return hashlib.sha256(target.read_bytes()).hexdigest()
    if not target.is_dir():
        raise ValueError(f"projection dependency does not exist: {relative}")
    digest = hashlib.sha256(b"px.projection-tree/1.0\0")
    for path in sorted(item for item in target.rglob("*") if item.is_file()):
        if {"__pycache__", ".pytest_cache", ".ruff_cache"} & set(path.parts):
            continue
        name = path.relative_to(target).as_posix().encode("utf-8")
        data = path.read_bytes()
        digest.update(len(name).to_bytes(8, "big"))
        digest.update(name)
        digest.update(len(data).to_bytes(8, "big"))
        digest.update(data)
    return digest.hexdigest()

def validate_graph_authority_manifest(
    root: Path, manifest: Mapping[str, object] | None = None
) -> dict[str, object]:
    """Require one purpose-specific authority contract for every major graph."""
    resolved = root.resolve()
    try:
        payload = (
            dict(manifest)
            if manifest is not None
            else json.loads(
                (resolved / "registry/graph_authority_manifest.json").read_text(
                    encoding="utf-8"
                )
            )
        )
    except (OSError, ValueError, json.JSONDecodeError) as error:
        return {"valid": False, "errors": (str(error),)}
    errors: list[str] = []
    if payload.get("schema_version") != "px.graph-authority-manifest/1.0":
        errors.append("graph authority schema mismatch")
    rows = payload.get("graphs")
    if not isinstance(rows, list):
        rows = []
        errors.append("graphs must be a list")
    ids: set[str] = set()
    paths: set[str] = set()
    purposes: set[str] = set()
    for row in rows:
        if not isinstance(row, Mapping):
            errors.append("graph record must be an object")
            continue
        graph_id = str(row.get("graph_id", ""))
        path = str(row.get("path", ""))
        purpose = str(row.get("purpose", ""))
        authority = row.get("authority")
        if not graph_id or graph_id in ids or not path or path in paths:
            errors.append("graph IDs and paths must be non-empty and unique")
        ids.add(graph_id)
        paths.add(path)
        if not purpose or purpose in purposes:
            errors.append(f"{graph_id}: graph purpose must be distinct")
        purposes.add(purpose)
        if not isinstance(authority, str) or not authority.strip():
            errors.append(f"{graph_id}: exactly one authority owner is required")
        builder = str(row.get("builder", ""))
        if not (resolved / builder).is_file():
            errors.append(f"{graph_id}: builder is missing")
        if not row.get("consumers") or not row.get("invalidation_rule") or not row.get("rebuild_gate"):
            errors.append(f"{graph_id}: consumer/invalidation/gate contract is incomplete")
        revisions = row.get("source_revisions")
        if not isinstance(revisions, list) or not revisions or any(
            not isinstance(item, Mapping)
            or not str(item.get("path", ""))
            or not SHA256.fullmatch(str(item.get("revision", "")))
            for item in revisions
        ):
            errors.append(f"{graph_id}: source revisions are incomplete")
        expected = str(row.get("graph_revision", ""))
        target = resolved / path
        if not target.is_file() or not SHA256.fullmatch(expected):
            errors.append(f"{graph_id}: graph artifact/revision is missing")
        elif revision_for_path(resolved, path) != expected:
            errors.append(f"{graph_id}: consumer graph is stale")
    inventory = {
        path.relative_to(resolved).as_posix()
        for base in (resolved / "registry", resolved / "registry/graphs")
        for path in base.glob("*graph*.json")
        if path.name not in {"graph_authority_manifest.json", "graph_manifest.json"}
    }
    if paths != inventory:
        errors.append(
            f"graph inventory mismatch: missing={sorted(inventory - paths)}, extra={sorted(paths - inventory)}"
        )
    return {
        "schema_version": "px.graph-authority-validation/1.0",
        "valid": not errors,
        "graph_count": len(rows),
        "errors": tuple(errors),
    }

if outcome == "success":
    if usage is None:
        raise ValueError("successful provider settlement requires usage")
    input_tokens, output_tokens, charge = self._usage_values(usage)
    if usage.billing_state != record["billing_state"]:
        raise BudgetIntegrityError(
            "provider usage billing state differs from its reservation"
        )
    policy_overrun = (
        input_tokens > reserved_input or output_tokens > reserved_output
    )
    if usage.billing_state == "local_non_billable":
        settled_charge = 0
        basis = "local_non_billable"
    elif usage.billing_state in {"actual", "estimated"}:
        assert charge is not None
        settled_charge = charge
        basis = usage.billing_state
        policy_overrun = policy_overrun or charge > reserved_charge
    else:
        settled_charge = reserved_charge
        basis = "unknown_conservative_burn"
    settled_input = input_tokens
    settled_output = output_tokens
    if policy_overrun:
        basis = f"{basis}_overrun"

receipt_path = self.root / "receipts" / f"{invocation_id}.settled.json"
result = self.wal.commit(
    (
        JsonArtifact("state", self.state_path, updated),
        JsonArtifact("receipt", receipt_path, receipt),
    ),
    transaction_id=f"provider-settle-{invocation_id}",
)
return {**receipt, "wal_transaction_id": result["transaction_id"]}

def _probe(name: str, function: Callable[[], bool]) -> ProbeResult:
    execution_id = _stable(
        {"name": name, "started": datetime.now(timezone.utc).isoformat()}
    )[:24]
    try:
        passed = function() is True
        observed = {"name": name, "passed": passed}
        return ProbeResult(
            name,
            passed,
            execution_id,
            _stable(observed),
            None if passed else "AssertionFailed",
        )
    except Exception as error:
        observed = {"name": name, "passed": False, "error": type(error).__name__}
        return ProbeResult(
            name, False, execution_id, _stable(observed), type(error).__name__
        )

def provider_execution_policy_report(
    policy: Mapping[str, object], request: Mapping[str, object]
) -> dict[str, object]:
    """Language-neutral fail-closed policy semantics and stable violation IDs."""
    violations: list[str] = []
    if policy.get("schema_version") != "px.provider-execution-policy/1.0":
        violations.append(PROVIDER_POLICY_VIOLATION_IDS[0])
    unsigned = {key: value for key, value in policy.items() if key != "policy_sha256"}
    if policy.get("policy_sha256") != _digest(unsigned, limit=MAX_REQUEST_BYTES):
        violations.append(PROVIDER_POLICY_VIOLATION_IDS[1])
    if (
        not _sha(policy.get("task_plan_sha256"))
        or policy.get("task_plan_sha256") != request.get("task_plan_sha256")
    ):
        violations.append(PROVIDER_POLICY_VIOLATION_IDS[2])
    model = policy.get("model")
    if not isinstance(model, Mapping) or any(
        (
            not str(model.get(field, "")).strip()
            if field in {"provider_id", "adapter_id", "model_id", "model_revision"}
            else not _sha(model.get(field))
        )
        for field in (
            "provider_id",
            "adapter_id",
            "model_id",
            "model_revision",
            "attachment_sha256",
        )
    ) or any(
        model.get(field) != request.get(request_field)
        for field, request_field in (
            ("adapter_id", "adapter_id"),
            ("model_id", "model_id"),
            ("model_revision", "model_revision"),
            ("attachment_sha256", "model_attachment_sha256"),
        )
    ):
        violations.append(PROVIDER_POLICY_VIOLATION_IDS[3])
    authority = policy.get("authority")
    if (
        not isinstance(authority, Mapping)
        or not _sha(authority.get("revision"))
        or authority.get("revision") != request.get("authority_revision")
        or authority.get("provider_effect") is not True
    ):
        violations.append(PROVIDER_POLICY_VIOLATION_IDS[4])
    egress = policy.get("egress")
    egress_valid = False
    if isinstance(egress, Mapping):
        mode = egress.get("mode")
        requested = request.get("requested_egress")
        destinations = egress.get("allowed_destinations", ())
        egress_valid = bool(
            (mode == "deny" and requested == "deny")
            or (mode == "loopback_only" and requested == "loopback")
            or (
                mode == "allowlist"
                and isinstance(destinations, Sequence)
                and not isinstance(destinations, (str, bytes))
                and requested in destinations
            )
        )
    if not egress_valid:
        violations.append(PROVIDER_POLICY_VIOLATION_IDS[5])
    cost = policy.get("cost")
    if (
        not isinstance(cost, Mapping)
        or cost.get("budget_id") != request.get("budget_id")
        or not isinstance(cost.get("max_charge_microunits"), int)
        or int(cost.get("max_charge_microunits", -1)) < 0
        or int(request.get("expected_charge_microunits", -1))
        > int(cost.get("max_charge_microunits", -1))
    ):
        violations.append(PROVIDER_POLICY_VIOLATION_IDS[6])
    privacy = {"policy_gated": 0, "isolated": 1, "local": 2}
    authority_levels = {"contained": 0, "installed_host": 1, "external_authority": 2}
    fallback_valid = isinstance(model, Mapping)
    for fallback in policy.get("fallbacks", ()):
        if not isinstance(fallback, Mapping) or any(
            not str(fallback.get(field, "")).strip()
            for field in ("provider_id", "adapter_id", "model_id", "model_revision")
        ) or not _sha(fallback.get("artifact_sha256")):
            fallback_valid = False
            continue
        if (
            privacy.get(str(fallback.get("privacy")), -1)
            < privacy.get(str(model.get("privacy")), -1)
            or authority_levels.get(str(fallback.get("authority_class")), -1)
            < authority_levels.get(str(model.get("authority_class")), -1)
        ):
            fallback_valid = False
    if not fallback_valid:
        violations.append(PROVIDER_POLICY_VIOLATION_IDS[7])
    if policy.get("exact_receipt_required") is not True:
        violations.append(PROVIDER_POLICY_VIOLATION_IDS[8])
    ordered = [item for item in PROVIDER_POLICY_VIOLATION_IDS if item in violations]
    return {
        "schema_version": "px.provider-execution-policy-conformance/1.0",
        "valid": not ordered,
        "violation_ids": ordered,
    }

privacy = {"policy_gated": 0, "isolated": 1, "local": 2}
authority_levels = {"contained": 0, "installed_host": 1, "external_authority": 2}
fallback_valid = isinstance(model, Mapping)
for fallback in policy.get("fallbacks", ()):
    if not isinstance(fallback, Mapping) or any(
        not str(fallback.get(field, "")).strip()
        for field in ("provider_id", "adapter_id", "model_id", "model_revision")
    ) or not _sha(fallback.get("artifact_sha256")):
        fallback_valid = False
        continue
    if (
        privacy.get(str(fallback.get("privacy")), -1)
        < privacy.get(str(model.get("privacy")), -1)
        or authority_levels.get(str(fallback.get("authority_class")), -1)
        < authority_levels.get(str(model.get("authority_class")), -1)
    ):
        fallback_valid = False
if not fallback_valid:
    violations.append(PROVIDER_POLICY_VIOLATION_IDS[7])

class OllamaHttpAdapter:
    """Bounded loopback-only Ollama adapter for the governed gateway."""

    adapter_id = "ollama-http"

    def __init__(
        self,
        base_url: str = "http://127.0.0.1:11434",
        *,
        timeout_seconds: float = 120.0,
        opener: object | None = None,
    ) -> None:
        parsed = urlsplit(base_url)
        if (
            parsed.scheme != "http"
            or parsed.hostname not in {"127.0.0.1", "::1"}
            or parsed.username is not None
            or parsed.password is not None
            or parsed.query
            or parsed.fragment
            or parsed.path not in {"", "/"}
        ):
            raise ValueError("Ollama adapter requires a literal loopback HTTP origin")
        if not 1 <= timeout_seconds <= 300:
            raise ValueError("Ollama timeout must be between 1 and 300 seconds")
        self.base_url = base_url.rstrip("/")
        self.timeout_seconds = float(timeout_seconds)
        # Ignore ambient proxy configuration so a local model request cannot be
        # redirected through a network proxy.
        self._opener = opener or build_opener(ProxyHandler({}))

    def invoke(
        self, model_id: str, payload: Mapping[str, object]
    ) -> ProviderResponse:
        model = model_id.strip()
        if not model or len(model) > 160 or any(character.isspace() for character in model):
            raise ValueError("Ollama model identity is invalid")
        if "model" in payload or "stream" in payload:
            raise ValueError("Ollama model and stream mode are gateway-owned")
        has_messages = isinstance(payload.get("messages"), list)
        has_prompt = isinstance(payload.get("prompt"), str)
        if has_messages == has_prompt:
            raise ValueError("Ollama payload requires exactly one prompt or messages input")
        request_payload = dict(payload)
        request_payload.update({"model": model, "stream": False})
        encoded = _canonical(request_payload, limit=MAX_REQUEST_BYTES)
        endpoint = "/api/chat" if has_messages else "/api/generate"
        request = Request(
            f"{self.base_url}{endpoint}",
            data=encoded,
            headers={"Content-Type": "application/json", "Accept": "application/json"},
            method="POST",
        )
        with self._opener.open(request, timeout=self.timeout_seconds) as response:
            raw = response.read(MAX_RESPONSE_BYTES + 1)
        if len(raw) > MAX_RESPONSE_BYTES:
            raise ValueError("Ollama response exceeds the configured byte bound")
        try:
            result = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise ValueError("Ollama returned invalid JSON") from error
        if not isinstance(result, dict) or result.get("error"):
            raise ValueError("Ollama returned an invalid terminal response")
        value = (
            result.get("message", {}).get("content")
            if has_messages and isinstance(result.get("message"), dict)
            else result.get("response")
        )
        if not isinstance(value, str):
            raise ValueError("Ollama terminal response omitted model output")
        input_tokens = result.get("prompt_eval_count", 0)
        output_tokens = result.get("eval_count", 0)
        if (
            not isinstance(input_tokens, int)
            or isinstance(input_tokens, bool)
            or input_tokens < 0
            or not isinstance(output_tokens, int)
            or isinstance(output_tokens, bool)
            or output_tokens < 0
        ):
            raise ValueError("Ollama terminal response has invalid usage metadata")
        return ProviderResponse(
            value=value,
            usage=ProviderUsage(
                billing_state="local_non_billable",
                input_tokens=input_tokens,
                output_tokens=output_tokens,
                charge_microunits=0,
            ),
        )


class LlamaCppHttpAdapter:
    """Bounded loopback-only adapter for an owned llama.cpp server session."""

    adapter_id = "llama-cpp-http"

    def __init__(
        self,
        base_url: str,
        *,
        session_id: str,
        model_sha256: str,
        timeout_seconds: float = 120.0,
        opener: object | None = None,
    ) -> None:
        parsed = urlsplit(base_url)
        if (
            parsed.scheme != "http"
            or parsed.hostname not in {"127.0.0.1", "::1"}
            or parsed.username is not None
            or parsed.password is not None
            or parsed.query
            or parsed.fragment
            or parsed.path not in {"", "/"}
        ):
            raise ValueError("llama.cpp adapter requires a literal loopback HTTP origin")
        if not session_id.startswith("local-model-session-"):
            raise ValueError("llama.cpp session identity is invalid")
        if len(model_sha256) != 64 or any(character not in "0123456789abcdef" for character in model_sha256):
            raise ValueError("llama.cpp model digest is invalid")
        if not 1 <= timeout_seconds <= 300:
            raise ValueError("llama.cpp timeout must be between 1 and 300 seconds")
        self.base_url = base_url.rstrip("/")
        self.session_id = session_id
        self.model_sha256 = model_sha256
        self.timeout_seconds = float(timeout_seconds)
        self._opener = opener or build_opener(ProxyHandler({}))

    def invoke(self, model_id: str, payload: Mapping[str, object]) -> ProviderResponse:
        if model_id != self.model_sha256:
            raise ValueError("llama.cpp request model does not match the admitted digest")
        if "model" in payload or "stream" in payload:
            raise ValueError("llama.cpp model and stream mode are gateway-owned")
        messages = payload.get("messages")
        if not isinstance(messages, list) or not messages:
            raise ValueError("llama.cpp payload requires non-empty messages")
        request_payload = dict(payload)
        request_payload.update({"model": self.model_sha256, "stream": False})
        raw_request = _canonical(request_payload, limit=MAX_REQUEST_BYTES)
        request = Request(
            f"{self.base_url}/v1/chat/completions",
            data=raw_request,
            headers={
                "Content-Type": "application/json",
                "Accept": "application/json",
                "X-Pacify-Local-Session": self.session_id,
            },
            method="POST",
        )
        with self._opener.open(request, timeout=self.timeout_seconds) as response:
            raw = response.read(MAX_RESPONSE_BYTES + 1)
        if len(raw) > MAX_RESPONSE_BYTES:
            raise ValueError("llama.cpp response exceeds the configured byte bound")
        try:
            result = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise ValueError("llama.cpp returned invalid JSON") from error
        try:
            value = result["choices"][0]["message"]["content"]
            usage = result.get("usage", {})
            input_tokens = usage.get("prompt_tokens", 0)
            output_tokens = usage.get("completion_tokens", 0)
        except (KeyError, IndexError, TypeError, AttributeError) as error:
            raise ValueError("llama.cpp returned an invalid terminal response") from error
        if not isinstance(value, str) or any(
            not isinstance(count, int) or isinstance(count, bool) or count < 0
            for count in (input_tokens, output_tokens)
        ):
            raise ValueError("llama.cpp terminal response has invalid output or usage")
        return ProviderResponse(
            value=value,
            usage=ProviderUsage("local_non_billable", input_tokens, output_tokens, 0),
        )

def load_provider_registry(root: Path) -> dict[str, object]:
    """Load the adapter allow-list as hostile data and enforce semantic rules."""
    try:
        value = json.loads((root / REGISTRY_PATH).read_text(encoding="utf-8"))
        validate_instance(value, root / REGISTRY_SCHEMA)
    except (
        OSError,
        UnicodeError,
        json.JSONDecodeError,
        ContractValidationError,
    ) as error:
        raise ValueError("provider adapter registry is invalid") from error
    seen: set[str] = set()
    for row in value["adapters"]:
        adapter_id = str(row["adapter_id"])
        if adapter_id in seen:
            raise ValueError(f"duplicate provider adapter: {adapter_id}")
        seen.add(adapter_id)
        if row["admitted"] is True and row["status"] != "ready":
            raise ValueError(f"admitted provider adapter is not ready: {adapter_id}")
        if row["mode"] == "local" and row["billing_state"] != "local_non_billable":
            raise ValueError(f"local adapter billing state is invalid: {adapter_id}")
    return value


def _attribute_name(node: ast.AST) -> str:
    parts: list[str] = []
    current = node
    while isinstance(current, ast.Attribute):
        parts.append(current.attr)
        current = current.value
    if isinstance(current, ast.Name):
        parts.append(current.id)
    return ".".join(reversed(parts))


def _scan_provider_file(path: Path, relative: str) -> list[dict[str, object]]:
    violations: list[dict[str, object]] = []
    try:
        tree = ast.parse(path.read_text(encoding="utf-8"), filename=relative)
    except (OSError, UnicodeError, SyntaxError) as error:
        return [{"path": relative, "line": None, "kind": "unscannable", "detail": type(error).__name__}]
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                if any(alias.name == name or alias.name.startswith(name + ".") for name in _DIRECT_PROVIDER_IMPORTS):
                    violations.append({"path": relative, "line": node.lineno, "kind": "provider_import", "detail": alias.name})
        elif isinstance(node, ast.ImportFrom) and node.module:
            if any(node.module == name or node.module.startswith(name + ".") for name in _DIRECT_PROVIDER_IMPORTS):
                violations.append({"path": relative, "line": node.lineno, "kind": "provider_import", "detail": node.module})
        elif isinstance(node, ast.Call):
            name = _attribute_name(node.func)
            if any(name == suffix or name.endswith("." + suffix) for suffix in _DIRECT_CALL_SUFFIXES):
                violations.append({"path": relative, "line": node.lineno, "kind": "provider_call", "detail": name})
    return violations


def _file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def _provider_source_paths(root: Path) -> list[Path]:
    return sorted(
        (path for base in (root / "runtime", root / "scripts") if base.is_dir() for path in base.rglob("*.py") if "__pycache__" not in path.parts),
        key=lambda item: item.as_posix(),
    )


def _scan_direct_provider_routes(root: Path) -> dict[str, object]:
    """Find obvious model-client bypasses without importing repository code."""
    violations: list[dict[str, object]] = []
    for path in _provider_source_paths(root):
        relative = path.relative_to(root).as_posix()
        if relative != "runtime/provider_gateway.py":
            violations.extend(_scan_provider_file(path, relative))
    return {
        "schema_version": "px.provider-reachability/1.0",
        "valid": not violations,
        "scanned_roots": ["runtime", "scripts"],
        "allowed_gateway": "runtime/provider_gateway.py",
        "violation_count": len(violations),
        "violations": violations,
    }


def build_provider_route_index(root: Path) -> dict[str, object]:
    root = root.resolve()
    index_path = root / "registry/provider_route_scan.json"
    try:
        previous = json.loads(index_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        previous = {}
    prior = {str(item.get("path")): item for item in previous.get("records", ()) if isinstance(item, dict)}
    records = []
    violations: list[dict[str, object]] = []
    for path in _provider_source_paths(root):
        relative = path.relative_to(root).as_posix()
        stat = path.stat()
        content_sha256 = _file_sha256(path)
        old = prior.get(relative, {})
        unchanged = (
            old.get("bytes") == stat.st_size
            and old.get("sha256") == content_sha256
            and isinstance(old.get("violations"), list)
        )
        if unchanged:
            file_violations = list(old["violations"])
        else:
            file_violations = [] if relative == "runtime/provider_gateway.py" else _scan_provider_file(path, relative)
        violations.extend(file_violations)
        records.append({
            "path": relative,
            "bytes": stat.st_size,
            "sha256": content_sha256,
            "scan_state": "verified",
            "violations": file_violations,
        })
    report = {
        "schema_version": "px.provider-reachability/1.0",
        "valid": not violations,
        "scanned_roots": ["runtime", "scripts"],
        "allowed_gateway": "runtime/provider_gateway.py",
        "violation_count": len(violations),
        "violations": violations,
    }
    return {
        "schema_version": "px.provider-route-index/1.3",
        "records": records,
        "report": report,
        "verified_file_count": len(records),
    }


def scan_direct_provider_routes(root: Path) -> dict[str, object]:
    """Use the native source index when current; never silently rediscover it."""
    root = root.resolve()
    index_path = root / "registry/provider_route_scan.json"
    if (root / "pyproject.toml").is_file() and index_path.is_file():
        try:
            index = json.loads(index_path.read_text(encoding="utf-8"))
            expected = {str(item["path"]): item for item in index.get("records", ())}
            current: dict[str, dict[str, object]] = {}
            for path in _provider_source_paths(root):
                stat = path.stat()
                current[path.relative_to(root).as_posix()] = {
                    "bytes": stat.st_size,
                    "sha256": _file_sha256(path),
                }
            fresh = set(current) == set(expected) and all(
                current[path]["bytes"] == int(record["bytes"])
                and current[path]["sha256"] == str(record["sha256"])
                for path, record in expected.items()
            )
            if fresh:
                return {**dict(index["report"]), "index_used": True, "index_current": True}
            return {
                "schema_version": "1.0",
                "valid": False,
                "violation_count": 1,
                "violations": [{"path": "registry/provider_route_scan.json", "line": None, "kind": "index_stale", "detail": "run python scripts/build_provider_route_index.py"}],
                "index_used": True,
                "index_current": False,
            }
        except (OSError, ValueError, KeyError, TypeError, json.JSONDecodeError):
            return {
                "schema_version": "1.0",
                "valid": False,
                "violation_count": 1,
                "violations": [{"path": "registry/provider_route_scan.json", "line": None, "kind": "index_invalid", "detail": "run python scripts/build_provider_route_index.py"}],
                "index_used": True,
                "index_current": False,
            }
    return {**_scan_direct_provider_routes(root), "index_used": False, "index_current": False}

