        ]
        level = "direct-isolated-behavior"

def _installed_record_hashes() -> dict[Path, str]:
    distribution = importlib.metadata.distribution("engineering-loop-bootstrap")
    text = distribution.read_text("RECORD")
    if text is None:
        raise ValueError("installed wheel RECORD is missing")
    records: dict[Path, str] = {}
    for relative, encoded, _ in csv.reader(io.StringIO(text)):
        if not encoded.startswith("sha256="):
            continue
        digest = base64.urlsafe_b64decode(encoded.removeprefix("sha256=") + "==").hex()
        records[Path(distribution.locate_file(relative)).resolve()] = digest
    return records

def _role(relative: str) -> tuple[str, str, bool]:
    parts = relative.split("/")
    if relative == "sitecustomize.py":
        return "source-build-control", "project-release-control", False
    if relative == "conftest.py":
        return "release-test-harness", "release-verification", False
    if parts[:2] == ["extension", "tests"]:
        return "extension-release-test", "vscode-extension-verification", False
    if parts[:2] == ["extension", "scripts"]:
        return "extension-source-control", "vscode-extension", False
    if parts[0] == "tests":
        return "release-test", "release-verification", True
    if parts[0] == "runtime":
        return "installed-runtime", "engineering_bootstrap", True
    if parts[0] == "builders":
        return "installed-builder", "engineering_bootstrap.builders", True
    if parts[0] == "templates" and len(parts) >= 2 and parts[1] == "generated":
        return "installed-generator-template", "generated-artifact-reconciliation", True
    if (
        parts[:2] == [".px", "skills"]
        and len(parts) >= 5
        and "scripts" in parts
    ):
        return "installed-skill-tool", parts[2], True
    if parts[0] == "scripts":
        return "source-build-control", "project-release-control", False
    if parts[0] == "examples":
        return "source-example", "public-demonstration", False
    return "unknown", "unowned", False

def certify_python_surfaces(
    root: Path,
    exact_tool_certification: dict[str, Any],
    *,
    require_map_current: bool = True,
) -> dict[str, Any]:
    root = root.resolve()
    source_checkout = (root / "pyproject.toml").is_file() and (root / "tests").is_dir()
    if not source_checkout:
        ownership_path = root / "registry" / "python_surface_ownership.json"
        if not ownership_path.is_file():
            return {
                "schema_version": "1.0",
                "valid": False,
                "python_file_count": 0,
                "syntax_valid_count": 0,
                "errors": ["installed Python surface ownership map is missing"],
                "records": [],
            }
        ownership = json.loads(ownership_path.read_text(encoding="utf-8"))
        package_root = Path(__file__).resolve().parent
        try:
            record_hashes = _installed_record_hashes()
        except (importlib.metadata.PackageNotFoundError, OSError, ValueError) as error:
            return {
                "schema_version": "1.0",
                "valid": False,
                "python_file_count": 0,
                "syntax_valid_count": 0,
                "errors": [str(error)],
                "records": [],
            }
        expected: dict[str, tuple[Path, dict[str, Any]]] = {}
        for record in ownership.get("records", ()):
            source_path = str(record.get("path", ""))
            role = str(record.get("role", ""))
            if role == "installed-runtime" and source_path.startswith("runtime/"):
                installed = package_root / source_path.removeprefix("runtime/")
                key = "engineering_bootstrap/" + source_path.removeprefix("runtime/")
            elif role == "installed-builder" and source_path.startswith("builders/"):
                installed = (
                    package_root / "builders" / source_path.removeprefix("builders/")
                )
                key = "engineering_bootstrap/builders/" + source_path.removeprefix(
                    "builders/"
                )
            elif role in {
                "installed-skill-tool",
                "installed-generator-template",
            } and record.get("packaged"):
                installed = root / source_path
                key = "share/engineering-bootstrap/" + source_path
            else:
                continue
            expected[key] = (installed, record)

        records: list[dict[str, Any]] = []
        errors: list[str] = []
        observed: set[str] = set()
        candidates = [
            *(
                path
                for path in package_root.rglob("*.py")
                if "__pycache__" not in path.parts
            ),
            *(path for path in root.rglob("*.py") if "__pycache__" not in path.parts),
        ]
        for path in sorted(candidates, key=lambda item: item.as_posix().casefold()):
            if path.is_relative_to(package_root):
                relative = (
                    "engineering_bootstrap/" + path.relative_to(package_root).as_posix()
                )
            else:
                relative = (
                    "share/engineering-bootstrap/" + path.relative_to(root).as_posix()
                )
            projection = expected.get(relative)
            if projection is None:
                if (
                    path.is_relative_to(package_root)
                    and path.resolve() in record_hashes
                ):
                    package_relative = path.relative_to(package_root).as_posix()
                    is_builder = package_relative.startswith("builders/")
                    record = {
                        "path": (
                            "builders/" + package_relative.removeprefix("builders/")
                        )
                        if is_builder
                        else "runtime/" + package_relative,
                        "role": "installed-builder"
                        if is_builder
                        else "installed-runtime",
                        "owner": "engineering_bootstrap.builders"
                        if is_builder
                        else "engineering_bootstrap",
                        "packaged": True,
                        "validation_level": "wheel-record-and-artifact-manifest",
                        "evidence": ["wheel RECORD", "canonical artifact manifest"],
                        "syntax_valid": True,
                    }
                else:
                    errors.append(
                        f"{relative}: installed Python file is absent from ownership map"
                    )
                    continue
            else:
                _, record = projection
                observed.add(relative)
            actual_digest = _digest(path)
            recorded_digest = record_hashes.get(path.resolve())
            if recorded_digest is None:
                errors.append(
                    f"{relative}: installed Python file is absent from wheel RECORD"
                )
            elif actual_digest != recorded_digest:
                errors.append(
                    f"{relative}: installed Python file differs from wheel RECORD"
                )
            try:
                ast.parse(path.read_text(encoding="utf-8-sig"), filename=relative)
            except (OSError, SyntaxError, UnicodeError) as error:
                errors.append(f"{relative}: {type(error).__name__}: {error}")
            records.append(
                {
                    **record,
                    "installed_path": relative,
                    "installed_sha256": actual_digest,
                }
            )
        missing = sorted(set(expected) - observed)
        errors.extend(
            f"{path}: mapped packaged Python file is missing from installation"
            for path in missing
        )
        mirrored = [
            name for name in ("runtime", "builders", "tests") if (root / name).exists()
        ]
        errors.extend(
            f"lean runtime installation contains forbidden shared {name} tree"
            for name in mirrored
        )
        return {
            "schema_version": "1.0",
            "valid": not errors,
            "python_file_count": len(records),
            "syntax_valid_count": len(records)
            - sum(
                1
                for error in errors
                if "SyntaxError" in error or "UnicodeError" in error
            ),
            "source_python_file_count": ownership.get("python_file_count"),
            "packaged_file_count": len(expected),
            "distribution_model": "lean-runtime-wheel-complete-sdist",
            "mirrored_runtime_source_count": len(mirrored),
            "errors": errors,
            "records": records,
        }
    tests = sorted((root / "tests").glob("test_*.py"))
    test_text = {
        path.relative_to(root).as_posix(): path.read_text(
            encoding="utf-8", errors="replace"
        )
        for path in tests
    }
    direct_paths = {
        record["target"]
        for record in exact_tool_certification.get("results", ())
        if record["positive_behavior"]["passed"]
    }
    direct_paths.update(
        record["target"]
        for record in exact_tool_certification.get("wrapper_results", ())
        if record["behavior"]["passed"]
    )
    records: list[dict[str, Any]] = []
    errors: list[str] = []
    for path in sorted(root.rglob("*.py"), key=lambda item: item.as_posix().casefold()):
        if not _source_python_candidate(path, root):
            continue
        relative = path.relative_to(root).as_posix()
        role, owner, packaged = _role(relative)
        syntax_error = None
        try:
            ast.parse(path.read_text(encoding="utf-8-sig"), filename=relative)
        except (OSError, SyntaxError, UnicodeError) as error:
            syntax_error = f"{type(error).__name__}: {error}"
            errors.append(f"{relative}: {syntax_error}")
        references = sorted(
            name
            for name, text in test_text.items()
            if path.name in text or relative in text
        )
        if role in {"release-test", "release-test-harness"}:
            evidence = [relative]
            level = "executable-test"
        elif relative in direct_paths:
            evidence = [
                "runtime/exact_tool_certification.py",
                "tests/test_exact_tool_certification.py",
            ]
            level = "direct-isolated-behavior"
        elif references:
            evidence = references
            level = "evidence-association"
        elif role in {"installed-runtime", "installed-builder"}:
            evidence = ["tests", "tests/test_installed_wheel_e2e.py"]
            level = "full-suite-and-installed-integration"
        elif role == "source-build-control":
            evidence = [
                "structural AST validation",
                "project-management release boundary",
            ]
            level = "source-only-structural"
        else:
            evidence = []
            level = "unvalidated"
        if role == "unknown":
            errors.append(f"{relative}: unknown Python surface")
        if (
            packaged
            and role == "installed-skill-tool"
            and level not in {"direct-isolated-behavior", "evidence-association"}
        ):
            errors.append(
                f"{relative}: packaged skill tool lacks direct behavioral evidence"
            )
        records.append(
            {
                "path": relative,
                "sha256": _digest(path),
                "bytes": path.stat().st_size,
                "role": role,
                "owner": owner,
                "packaged": packaged,
                "validation_level": level,
                "evidence": evidence,
                "syntax_valid": syntax_error is None,
            }
        )
    role_counts: dict[str, int] = {}
    validation_counts: dict[str, int] = {}
    for record in records:
        role_counts[record["role"]] = role_counts.get(record["role"], 0) + 1
        validation_counts[record["validation_level"]] = (
            validation_counts.get(record["validation_level"], 0) + 1
        )
    ownership_path = root / "registry" / "python_surface_ownership.json"
    map_current = False
    if ownership_path.is_file():
        stored = json.loads(ownership_path.read_text(encoding="utf-8"))
        map_current = stored.get("records") == records
    if require_map_current and not map_current:
        errors.append("Python surface ownership map is stale or missing")
    return {
        "schema_version": "1.0",
        "valid": not errors,
        "python_file_count": len(records),
        "syntax_valid_count": sum(1 for record in records if record["syntax_valid"]),
        "packaged_file_count": sum(1 for record in records if record["packaged"]),
        "direct_behavior_count": validation_counts.get("direct-isolated-behavior", 0),
        "evidence_association_count": validation_counts.get("evidence-association", 0),
        "source_only_structural_count": validation_counts.get(
            "source-only-structural", 0
        ),
        "map_current": map_current,
        "role_counts": dict(sorted(role_counts.items())),
        "validation_counts": dict(sorted(validation_counts.items())),
        "errors": errors,
        "records": records,
    }

def compact_communication(
    messages: Iterable[Mapping[str, object]],
    *,
    max_items: int,
    mandatory_categories: Iterable[str] = MANDATORY_COMMUNICATION_CATEGORIES,
) -> dict[str, object]:
    """Compress repeat messages while preserving mandatory safety information."""
    if max_items < 1:
        raise ValueError("max_items must be positive")
    required = frozenset(map(str, mandatory_categories))
    rows: list[dict[str, object]] = []
    seen_ids: set[str] = set()
    for message in messages:
        identifier = str(message.get("id", "")).strip()
        category = str(message.get("category", "")).strip()
        text = str(message.get("text", "")).strip()
        if not identifier or identifier in seen_ids or not category or not text:
            raise ValueError("messages require unique IDs, category, and text")
        seen_ids.add(identifier)
        rows.append(
            {
                "id": identifier,
                "category": category,
                "text": text,
                "evidence_ids": sorted(set(map(str, message.get("evidence_ids", ())))),
                "repeat_key": str(message.get("repeat_key", text)).strip().casefold(),
            }
        )

    mandatory = [row for row in rows if row["category"] in required]
    if len(mandatory) > max_items:
        return {
            "valid": False,
            "decision": "budget_insufficient",
            "items": mandatory,
            "mandatory_count": len(mandatory),
            "max_items": max_items,
            "dropped": [],
            "errors": ["communication budget cannot contain all mandatory records"],
        }

    selected = list(mandatory)
    selected_ids = {str(row["id"]) for row in selected}
    optional = [row for row in rows if row["id"] not in selected_ids]
    groups: dict[tuple[str, str], list[dict[str, object]]] = {}
    for row in optional:
        groups.setdefault((str(row["category"]), str(row["repeat_key"])), []).append(
            row
        )
    summaries: list[dict[str, object]] = []
    for (category, repeat_key), group in sorted(groups.items()):
        first = group[0]
        summaries.append(
            {
                "id": str(first["id"]),
                "category": category,
                "text": str(first["text"]),
                "evidence_ids": sorted(
                    {item for row in group for item in row["evidence_ids"]}
                ),
                "repeat_key": repeat_key,
                "repeat_count": len(group),
                "source_ids": [str(row["id"]) for row in group],
            }
        )
    selected.extend(summaries[: max_items - len(selected)])
    retained_source_ids = {
        source for row in selected for source in row.get("source_ids", [str(row["id"])])
    }
    dropped = [str(row["id"]) for row in rows if row["id"] not in retained_source_ids]
    return {
        "valid": True,
        "decision": "compacted",
        "items": selected,
        "original_count": len(rows),
        "retained_count": len(selected),
        "mandatory_count": len(mandatory),
        "max_items": max_items,
        "dropped": dropped,
        "compression_sha256": _stable(selected),
        "authority_granted": False,
    }

def run_independent_hypothesis_panel(
    branches: Sequence[Mapping[str, object]],
    *,
    convergence_threshold: float = 0.75,
    max_rounds: int = 3,
) -> dict[str, object]:
    """Critique isolated hypotheses and converge only when evidence supports it.

    The function consumes observable branch artifacts. It neither requests nor
    records private reasoning traces.
    """
    if not 2 <= len(branches) <= 12:
        raise ValueError("an independent panel requires two through twelve branches")
    if not 0.5 <= convergence_threshold <= 1.0:
        raise ValueError("convergence_threshold must be between 0.5 and 1.0")
    if not 1 <= max_rounds <= 10:
        raise ValueError("max_rounds must be between one and ten")

    normalized: list[dict[str, object]] = []
    branch_ids: set[str] = set()
    evidence_owners: dict[str, set[str]] = {}
    errors: list[str] = []
    for branch in branches:
        branch_id = str(branch.get("branch_id", "")).strip()
        conclusion = str(branch.get("conclusion", "")).strip()
        evidence = tuple(sorted(set(map(str, branch.get("evidence_ids", ())))))
        confidence = float(branch.get("confidence", 0.0))
        if not branch_id or branch_id in branch_ids:
            raise ValueError("branch IDs must be non-empty and unique")
        branch_ids.add(branch_id)
        if branch.get("isolated") is not True:
            errors.append(f"{branch_id}: branch was not independently isolated")
        if not conclusion:
            errors.append(f"{branch_id}: conclusion missing")
        if not 0.0 <= confidence <= 1.0:
            raise ValueError("branch confidence must be between zero and one")
        if not evidence:
            errors.append(f"{branch_id}: evidence missing")
        for evidence_id in evidence:
            evidence_owners.setdefault(evidence_id, set()).add(branch_id)
        normalized.append(
            {
                "branch_id": branch_id,
                "conclusion": conclusion,
                "confidence": confidence,
                "evidence_ids": evidence,
                "artifact_sha256": str(branch.get("artifact_sha256", "")),
            }
        )

    correlated = sorted(
        evidence_id
        for evidence_id, owners in evidence_owners.items()
        if len(owners) == len(branches)
    )
    if correlated:
        errors.append(
            "all branches rely on the same evidence; independence is not established"
        )

    totals: Counter[str] = Counter()
    for branch in normalized:
        totals[str(branch["conclusion"])] += max(float(branch["confidence"]), 0.01)
    total_weight = sum(totals.values())
    ranked = sorted(totals.items(), key=lambda item: (-item[1], item[0]))
    leading, leading_weight = ranked[0]
    support = leading_weight / total_weight if total_weight else 0.0
    converged = not errors and support >= convergence_threshold
    dissent = [
        {
            "branch_id": branch["branch_id"],
            "conclusion": branch["conclusion"],
            "confidence": branch["confidence"],
            "evidence_ids": list(branch["evidence_ids"]),
        }
        for branch in normalized
        if branch["conclusion"] != leading
    ]
    critic = {
        "independent": True,
        "method": "observable-artifact-consistency-and-evidence-separation",
        "private_reasoning_requested": False,
        "findings": errors,
        "shared_evidence_ids": correlated,
    }
    return {
        "valid": not errors,
        "converged": converged,
        "selected_conclusion": leading if converged else None,
        "leading_support": round(support, 6),
        "threshold": convergence_threshold,
        "rounds_used": 1,
        "max_rounds": max_rounds,
        "branches": normalized,
        "dissent": dissent,
        "critic": critic,
        "panel_sha256": _stable({"branches": normalized, "critic": critic}),
        "authority_granted": False,
    }

def reconcile(self, *, apply: bool = False) -> dict[str, object]:
    """Run a deterministic reconciliation pass over configured authorities."""
    from .state_invariants import validate_coordination_startup

    components: list[dict[str, object]] = []
    for index, (journal_root, allowed_root) in enumerate(
        self.configuration.wal_targets
    ):
        try:
            wal = JsonWal(journal_root, allowed_root)
            detail = wal.recover() if apply else wal.inspect()
            requires_recovery = bool(detail.get("requires_recovery"))
            components.append(
                self._component(
                    f"wal[{index}]",
                    "degraded" if requires_recovery else "healthy",
                    detail=detail,
                )
            )
        except (OSError, ValueError, RuntimeError) as error:
            components.append(
                self._component(f"wal[{index}]", "blocked", error=error)
            )

    for index, state_path in enumerate(self.configuration.durable_state_paths):
        try:
            try:
                state = load_state(state_path)
                detail: dict[str, object] = {
                    "schema_version": CURRENT_STATE_SCHEMA_VERSION,
                    "package_id": state.package_id,
                    "migrated": False,
                }
            except DurableStateVersionError:
                if not apply:
                    components.append(
                        self._component(
                            f"durable_state[{index}]",
                            "degraded",
                            detail={
                                "migration_required": True,
                                "path": str(state_path),
                            },
                        )
                    )
                    continue
                receipt = migrate_state(state_path)
                state = load_state(state_path)
                detail = {
                    "schema_version": CURRENT_STATE_SCHEMA_VERSION,
                    "package_id": state.package_id,
                    "migrated": bool(receipt.get("migrated")),
                    "receipt": receipt,
                }
            components.append(
                self._component(f"durable_state[{index}]", "healthy", detail=detail)
            )
        except (OSError, ValueError, RuntimeError) as error:
            components.append(
                self._component(f"durable_state[{index}]", "blocked", error=error)
            )

    try:
        invariant = validate_coordination_startup(self.configuration.project_root)
        components.append(
            self._component(
                "coordination_invariants",
                "healthy" if invariant.get("valid") else "blocked",
                configured=bool(invariant.get("configured")),
                detail=invariant,
            )
        )
    except (OSError, ValueError, RuntimeError) as error:
        components.append(
            self._component("coordination_invariants", "blocked", error=error)
        )

    callback_groups = (
        ("event_bus", self.configuration.event_bus_reconcilers),
        ("agent_sessions", self.configuration.agent_session_reconcilers),
    )
    for label, callbacks in callback_groups:
        if not callbacks:
            components.append(self._component(label, "healthy", configured=False))
        for index, callback in enumerate(callbacks):
            try:
                detail = dict(callback(apply))
                status = "healthy" if detail.get("valid", True) else "blocked"
                components.append(
                    self._component(f"{label}[{index}]", status, detail=detail)
                )
            except (OSError, ValueError, RuntimeError) as error:
                components.append(
                    self._component(f"{label}[{index}]", "blocked", error=error)
                )

    if not self.configuration.resource_reconcilers:
        components.append(self._component("resources", "healthy", configured=False))
    for index, callback in enumerate(self.configuration.resource_reconcilers):
        try:
            detail = dict(callback(apply))
            status = "healthy" if detail.get("valid", True) else "degraded"
            if int(detail.get("cleanup_failures", 0)):
                status = "blocked"
            components.append(
                self._component(f"resources[{index}]", status, detail=detail)
            )
        except (OSError, ValueError, RuntimeError) as error:
            components.append(
                self._component(f"resources[{index}]", "blocked", error=error)
            )

    statuses = {str(item["status"]) for item in components}
    status = (
        "blocked"
        if "blocked" in statuses
        else "degraded"
        if "degraded" in statuses
        else "healthy"
    )
    report = {
        "schema_version": RECOVERY_REPORT_SCHEMA_VERSION,
        "valid": status == "healthy",
        "status": status,
        "mode": "apply" if apply else "dry_run",
        "forensic_state": "retained",
        "components": components,
    }
    report["human_summary"] = (
        f"Recovery doctor: {status}; {len(components)} component checks; "
        f"mode={report['mode']}."
    )
    return report

def _validate_payload(
    payload: Mapping[str, object], version: str, *, historical_unversioned: bool = False
) -> None:
    expected = _V1_FIELDS if version == "1.0" else _V2_FIELDS
    if historical_unversioned:
        allowed = {_V1_FIELDS - {"schema_version"}, _V2_FIELDS - {"schema_version"}}
        if frozenset(payload) not in allowed:
            raise DurableStateIntegrityError(
                "historical durable state fields are not exact"
            )
    elif frozenset(payload) != expected:
        raise DurableStateIntegrityError(
            f"durable state {version} fields are not exact"
        )
    package_id = payload.get("package_id")
    if not isinstance(package_id, str) or not package_id.strip():
        raise DurableStateIntegrityError("package_id must be a non-empty string")
    for field in (
        "completed_steps",
        "pending_approvals",
        "evidence_refs",
        "idempotency_keys",
    ):
        _require_string_sequence(payload, field)
    if version == CURRENT_STATE_SCHEMA_VERSION or "interrupted_steps" in payload:
        _require_string_sequence(payload, "interrupted_steps")
    selected = payload.get("selected_skills")
    if not isinstance(selected, list) or any(
        not isinstance(item, list)
        or len(item) != 2
        or any(not isinstance(part, str) for part in item)
        for item in selected
    ):
        raise DurableStateIntegrityError(
            "selected_skills must be an array of two-string arrays"
        )

def load_state(path: Path) -> DurableState:
    """Load only the current schema; callers must request migrations explicitly."""
    payload, _, version, historical = _decode(path)
    if historical or version != CURRENT_STATE_SCHEMA_VERSION:
        raise DurableStateVersionError(
            f"durable state {version} requires explicit migration to "
            f"{CURRENT_STATE_SCHEMA_VERSION}"
        )
    return _to_state(payload)

def reconcile_resume(
    state: DurableState,
    *,
    actual_evidence: Iterable[str],
    requested_idempotency_key: str | None = None,
) -> tuple[bool, tuple[str, ...]]:
    reasons: list[str] = []
    if set(state.evidence_refs) - set(actual_evidence):
        reasons.append("recorded evidence is missing from runtime")
    if state.interrupted_steps:
        reasons.append("interrupted steps are non-certifying")
    if (
        requested_idempotency_key
