"""Classify release artifacts and compute deterministic product/harness digests."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path, PurePosixPath
import shutil
import tomllib
from typing import Any, Iterable

from .bounded_walk import FilesystemWalkError, WalkLimits, bounded_walk
from .repository_scope import is_external_environment_relative


def _load_policy(root: Path) -> dict[str, Any]:
    return json.loads(
        (root / "policies/release-artifact-policy.json").read_text(encoding="utf-8")
    )


def _canonical_digest(records: list[dict[str, Any]]) -> str:
    payload = b"".join(
        (json.dumps(record, sort_keys=True, separators=(",", ":")) + "\n").encode()
        for record in records
    )
    return hashlib.sha256(payload).hexdigest()


def _is_release_walk_excluded(relative: str | Path) -> bool:
    """Prune external custody without hiding policy-governed evidence.

    The repository source boundary intentionally excludes evidence from normal
    source discovery.  Release classification has a different obligation: it
    must see evidence payloads so executable or unapproved files cannot hide in
    that namespace.  Evidence remains non-product and its content is not hashed.
    """
    path = Path(relative)
    if any(part.casefold() == "evidence" for part in path.parts):
        return False
    return is_external_environment_relative(path)


def classify_tree(root: Path) -> dict[str, Any]:
    root = root.resolve()
    policy = _load_policy(root)
    product_roots = {item.casefold() for item in policy["product_roots"]}
    product_files = {item.casefold() for item in policy["product_root_files"]}
    evidence_roots = {item.casefold() for item in policy["evidence_roots"]}
    audit_roots = {item.casefold() for item in policy.get("audit_roots", [])}
    audit_root_files = {item.casefold() for item in policy.get("audit_root_files", [])}
    audit_suffixes = {item.casefold() for item in policy.get("audit_allowed_suffixes", [])}
    intermediate_names = {item.casefold() for item in policy["intermediate_names"]}
    intermediate_name_suffixes = {
        item.casefold() for item in policy.get("intermediate_name_suffixes", [])
    }
    intermediate_suffixes = {
        item.casefold() for item in policy["intermediate_suffixes"]
    }
    control_outputs = {item.casefold() for item in policy["control_output_paths"]}
    control_output_prefixes = tuple(
        item.casefold() for item in policy.get("control_output_prefixes", [])
    )
    evidence_suffixes = {
        item.casefold() for item in policy["evidence_allowed_suffixes"]
    }
    evidence_names = {
        item.casefold() for item in policy.get("evidence_allowed_names", [])
    }
    records: list[dict[str, Any]] = []
    errors: list[str] = []
    product_errors: list[str] = []
    normalized_seen: dict[str, str] = {}
    try:
        walk = bounded_walk(
            root,
            limits=WalkLimits(
                max_files=250_000,
                max_depth=128,
                max_bytes=64 * 1024 * 1024 * 1024,
            ),
            symlink_policy="reject",
            exclude=_is_release_walk_excluded,
        )
    except FilesystemWalkError as error:
        return {
            "schema_version": "1.0",
            "valid": False,
            "product_valid": False,
            "policy_version": policy["policy_version"],
            "policy_sha256": hashlib.sha256(
                (root / "policies/release-artifact-policy.json").read_bytes()
            ).hexdigest(),
            "file_count": 0,
            "counts": {},
            "product_digest": _canonical_digest([]),
            "harness_digest": _canonical_digest([]),
            "product_records": [],
            "records": [],
            "errors": [f"bounded filesystem walk failed: {error.code}"],
        }
    for entry in walk.entries:
        relative = entry.relative
        normalized = relative.casefold()
        prior = normalized_seen.get(normalized)
        if prior is not None and prior != relative:
            collision = f"case-fold path collision: {prior} vs {relative}"
            errors.append(collision)
            product_errors.append(collision)
        normalized_seen[normalized] = relative
        if entry.kind == "file":
            path = entry.path
            parts = relative.split("/")
            folded_parts = [item.casefold() for item in parts]
            folded = relative.casefold()
            suffix = path.suffix.casefold()
            if (
                any(item in intermediate_names for item in folded_parts)
                or any(
                    item.endswith(ending)
                    for item in folded_parts
                    for ending in intermediate_name_suffixes
                )
                or suffix in intermediate_suffixes
            ):
                classification = "generated_intermediate"
                reason = "narrow generated-artifact exclusion"
            elif folded in control_outputs or any(
                folded.startswith(prefix) for prefix in control_output_prefixes
            ):
                classification = "control_output"
                reason = "mutable release transaction, governance, or receipt control"
            elif any(part in evidence_roots for part in folded_parts):
                classification = "evidence_output"
                reason = "non-executable evidence namespace"
                if suffix not in evidence_suffixes and path.name.casefold() not in evidence_names:
                    errors.append(
                        f"executable or unapproved evidence payload: {relative}"
                    )
            elif folded_parts[0] in audit_roots or (len(parts) == 1 and folded in audit_root_files):
                classification = "audit_artifact"
                reason = "bounded final audit handoff surface"
                if suffix not in audit_suffixes:
                    errors.append(f"unapproved audit artifact payload: {relative}")
            elif folded_parts[0] in product_roots or (
                len(parts) == 1 and folded in product_files
            ):
                classification = "product_input"
                reason = "declared product surface"
            else:
                classification = "unclassified"
                reason = "no release policy rule"
                errors.append(f"unclassified release artifact: {relative}")
            if path.is_file():
                if classification in {"control_output", "evidence_output"}:
                    content_sha256 = None
                else:
                    try:
                        content_sha256 = hashlib.sha256(path.read_bytes()).hexdigest()
                    except OSError as error:
                        content_sha256 = None
                        unreadable = (
                            f"unreadable release artifact: {relative}: "
                            f"{type(error).__name__}"
                        )
                        errors.append(unreadable)
                        if classification == "product_input":
                            product_errors.append(unreadable)
                records.append(
                    {
                        "path": relative,
                        "classification": classification,
                        "reason": reason,
                        "size": entry.size,
                        "sha256": content_sha256,
                    }
                )
    records.sort(key=lambda item: item["path"].casefold())
    product_records = [
        {key: item[key] for key in ("path", "size", "sha256")}
        for item in records
        if item["classification"] == "product_input"
    ]
    harness_paths = {
        "runtime/release_artifacts.py",
        "runtime/release_certification.py",
        "runtime/release_audit.py",
        "runtime/structural_integrity.py",
        "runtime/exact_tool_certification.py",
        "policies/release-artifact-policy.json",
        "registry/test_profiles.json",
    }
    harness_records = [
        item
        for item in product_records
        if item["path"] in harness_paths
        or item["path"].startswith("tests/test_release")
        or item["path"].startswith("tests/test_structural")
    ]
    counts: dict[str, int] = {}
    for item in records:
        counts[item["classification"]] = counts.get(item["classification"], 0) + 1
    return {
        "schema_version": "1.0",
        "valid": not errors,
        "product_valid": not product_errors,
        "policy_version": policy["policy_version"],
        "policy_sha256": hashlib.sha256(
            (root / "policies/release-artifact-policy.json").read_bytes()
        ).hexdigest(),
        "file_count": len(records),
        "counts": dict(sorted(counts.items())),
        "product_digest": _canonical_digest(product_records),
        "harness_digest": _canonical_digest(harness_records),
        "product_records": product_records,
        "records": records,
        "errors": errors,
    }


def verify_frozen_product(root: Path, frozen: dict[str, Any]) -> dict[str, Any]:
    current = classify_tree(root)
    errors = list(current["errors"])
    if current["product_digest"] != frozen.get("product_digest"):
        errors.append("product input digest changed after freeze")
    if current["harness_digest"] != frozen.get("harness_digest"):
        errors.append("certification harness digest changed after freeze")
    return {
        "valid": not errors,
        "product_digest": current["product_digest"],
        "harness_digest": current["harness_digest"],
        "errors": errors,
    }


def _safe_fixture_relative(value: str) -> PurePosixPath:
    relative = PurePosixPath(value)
    if relative.is_absolute() or not relative.parts or ".." in relative.parts:
        raise ValueError(f"unsafe release fixture path: {value}")
    return relative


def _declared_evidence_files(root: Path) -> set[str]:
    configuration = tomllib.loads((root / "pyproject.toml").read_text(encoding="utf-8"))
    data_files = (
        configuration.get("tool", {})
        .get("setuptools", {})
        .get("data-files", {})
    )
    declared: set[str] = set()
    for patterns in data_files.values():
        for pattern in patterns:
            relative_pattern = _safe_fixture_relative(str(pattern)).as_posix()
            if not relative_pattern.startswith("evidence/"):
                continue
            for candidate in root.glob(relative_pattern):
                if candidate.is_file():
                    declared.add(candidate.relative_to(root).as_posix())
    return declared


def materialize_release_source(
    source_root: Path,
    destination: Path,
    *,
    extra_paths: Iterable[str] = (),
) -> dict[str, object]:
    """Materialize product inputs and declared packaged evidence for release tests."""

    root = source_root.resolve(strict=True)
    target = destination.resolve(strict=False)
    if target.exists():
        raise FileExistsError(f"release fixture destination already exists: {target}")
    try:
        target.relative_to(root)
    except ValueError:
        pass
    else:
        raise ValueError("release fixture destination must be outside the source root")

    classification = classify_tree(root)
    if not classification["valid"] or not classification["product_valid"]:
        raise ValueError(f"release source is not classifiable: {classification['errors']}")

    product_paths = {record["path"] for record in classification["product_records"]}
    declared_evidence = _declared_evidence_files(root)
    extras = {_safe_fixture_relative(str(path)).as_posix() for path in extra_paths}
    selected = sorted(product_paths | declared_evidence | extras)

    copied_bytes = 0
    for relative in selected:
        source = (root / Path(relative)).resolve(strict=True)
        try:
            source.relative_to(root)
        except ValueError as error:
            raise ValueError(f"release fixture path escapes source root: {relative}") from error
        if not source.is_file():
            raise ValueError(f"release fixture input is not a file: {relative}")
        output = target / Path(relative)
        output.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, output)
        copied_bytes += source.stat().st_size

    return {
        "schema_version": "px.test-release-source-fixture/1.0",
        "valid": True,
        "file_count": len(selected),
        "copied_bytes": copied_bytes,
        "product_file_count": len(product_paths),
        "declared_evidence_file_count": len(declared_evidence),
        "extra_file_count": len(extras),
        "product_digest": classification["product_digest"],
        "harness_digest": classification["harness_digest"],
    }

    item.casefold() for item in policy["evidence_allowed_suffixes"]
}
evidence_names = {
    item.casefold() for item in policy.get("evidence_allowed_names", [])
}
records: list[dict[str, Any]] = []
errors: list[str] = []
product_errors: list[str] = []
normalized_seen: dict[str, str] = {}
try:
    walk = bounded_walk(
        root,
        limits=WalkLimits(
            max_files=250_000,
            max_depth=128,
            max_bytes=64 * 1024 * 1024 * 1024,
        ),
        symlink_policy="reject",
        exclude=_is_release_walk_excluded,
    )
except FilesystemWalkError as error:
    return {
        "schema_version": "1.0",
        "valid": False,
        "product_valid": False,
        "policy_version": policy["policy_version"],
        "policy_sha256": hashlib.sha256(
            (root / "policies/release-artifact-policy.json").read_bytes()
        ).hexdigest(),

def classify_tree(root: Path) -> dict[str, Any]:
    root = root.resolve()
    policy = _load_policy(root)
    product_roots = {item.casefold() for item in policy["product_roots"]}
    product_files = {item.casefold() for item in policy["product_root_files"]}
    evidence_roots = {item.casefold() for item in policy["evidence_roots"]}
    audit_roots = {item.casefold() for item in policy.get("audit_roots", [])}
    audit_root_files = {item.casefold() for item in policy.get("audit_root_files", [])}
    audit_suffixes = {item.casefold() for item in policy.get("audit_allowed_suffixes", [])}
    intermediate_names = {item.casefold() for item in policy["intermediate_names"]}
    intermediate_name_suffixes = {
        item.casefold() for item in policy.get("intermediate_name_suffixes", [])
    }
    intermediate_suffixes = {
        item.casefold() for item in policy["intermediate_suffixes"]
    }
    control_outputs = {item.casefold() for item in policy["control_output_paths"]}
    control_output_prefixes = tuple(
        item.casefold() for item in policy.get("control_output_prefixes", [])
    )
    evidence_suffixes = {
        item.casefold() for item in policy["evidence_allowed_suffixes"]
    }
    evidence_names = {
        item.casefold() for item in policy.get("evidence_allowed_names", [])
    }
    records: list[dict[str, Any]] = []
    errors: list[str] = []
    product_errors: list[str] = []
    normalized_seen: dict[str, str] = {}
    try:
        walk = bounded_walk(
            root,
            limits=WalkLimits(
                max_files=250_000,
                max_depth=128,
                max_bytes=64 * 1024 * 1024 * 1024,
            ),
            symlink_policy="reject",
            exclude=_is_release_walk_excluded,
        )
    except FilesystemWalkError as error:
        return {
            "schema_version": "1.0",
            "valid": False,
            "product_valid": False,
            "policy_version": policy["policy_version"],
            "policy_sha256": hashlib.sha256(
                (root / "policies/release-artifact-policy.json").read_bytes()
            ).hexdigest(),
            "file_count": 0,
            "counts": {},
            "product_digest": _canonical_digest([]),
            "harness_digest": _canonical_digest([]),
            "product_records": [],
            "records": [],
            "errors": [f"bounded filesystem walk failed: {error.code}"],
        }
    for entry in walk.entries:
        relative = entry.relative
        normalized = relative.casefold()
        prior = normalized_seen.get(normalized)
        if prior is not None and prior != relative:
            collision = f"case-fold path collision: {prior} vs {relative}"
            errors.append(collision)
            product_errors.append(collision)
        normalized_seen[normalized] = relative
        if entry.kind == "file":
            path = entry.path
            parts = relative.split("/")
            folded_parts = [item.casefold() for item in parts]
            folded = relative.casefold()
            suffix = path.suffix.casefold()
            if (
                any(item in intermediate_names for item in folded_parts)
                or any(
                    item.endswith(ending)
                    for item in folded_parts
                    for ending in intermediate_name_suffixes
                )
                or suffix in intermediate_suffixes
            ):
                classification = "generated_intermediate"
                reason = "narrow generated-artifact exclusion"
            elif folded in control_outputs or any(
                folded.startswith(prefix) for prefix in control_output_prefixes
            ):
                classification = "control_output"
                reason = "mutable release transaction, governance, or receipt control"
            elif any(part in evidence_roots for part in folded_parts):
                classification = "evidence_output"
                reason = "non-executable evidence namespace"
                if suffix not in evidence_suffixes and path.name.casefold() not in evidence_names:
                    errors.append(
                        f"executable or unapproved evidence payload: {relative}"
                    )
            elif folded_parts[0] in audit_roots or (len(parts) == 1 and folded in audit_root_files):
                classification = "audit_artifact"
                reason = "bounded final audit handoff surface"
                if suffix not in audit_suffixes:
                    errors.append(f"unapproved audit artifact payload: {relative}")
            elif folded_parts[0] in product_roots or (
                len(parts) == 1 and folded in product_files
            ):
                classification = "product_input"
                reason = "declared product surface"
            else:
                classification = "unclassified"
                reason = "no release policy rule"
                errors.append(f"unclassified release artifact: {relative}")
            if path.is_file():
                if classification in {"control_output", "evidence_output"}:
                    content_sha256 = None
                else:
                    try:
                        content_sha256 = hashlib.sha256(path.read_bytes()).hexdigest()
                    except OSError as error:
                        content_sha256 = None
                        unreadable = (
                            f"unreadable release artifact: {relative}: "
                            f"{type(error).__name__}"
                        )
                        errors.append(unreadable)
                        if classification == "product_input":
                            product_errors.append(unreadable)
                records.append(
                    {
                        "path": relative,
                        "classification": classification,
                        "reason": reason,
                        "size": entry.size,
                        "sha256": content_sha256,
                    }
                )
    records.sort(key=lambda item: item["path"].casefold())
    product_records = [
        {key: item[key] for key in ("path", "size", "sha256")}
        for item in records
        if item["classification"] == "product_input"
    ]
    harness_paths = {
        "runtime/release_artifacts.py",
        "runtime/release_certification.py",
        "runtime/release_audit.py",
        "runtime/structural_integrity.py",
        "runtime/exact_tool_certification.py",
        "policies/release-artifact-policy.json",
        "registry/test_profiles.json",
    }
    harness_records = [
        item
        for item in product_records
        if item["path"] in harness_paths
        or item["path"].startswith("tests/test_release")
        or item["path"].startswith("tests/test_structural")
    ]
    counts: dict[str, int] = {}
    for item in records:
        counts[item["classification"]] = counts.get(item["classification"], 0) + 1
    return {
        "schema_version": "1.0",
        "valid": not errors,
        "product_valid": not product_errors,
        "policy_version": policy["policy_version"],
        "policy_sha256": hashlib.sha256(
            (root / "policies/release-artifact-policy.json").read_bytes()
        ).hexdigest(),
        "file_count": len(records),
        "counts": dict(sorted(counts.items())),
        "product_digest": _canonical_digest(product_records),
        "harness_digest": _canonical_digest(harness_records),
        "product_records": product_records,
        "records": records,
        "errors": errors,
    }

def materialize_release_source(
    source_root: Path,
    destination: Path,
    *,
    extra_paths: Iterable[str] = (),
) -> dict[str, object]:
    """Materialize product inputs and declared packaged evidence for release tests."""

    root = source_root.resolve(strict=True)
    target = destination.resolve(strict=False)
    if target.exists():
        raise FileExistsError(f"release fixture destination already exists: {target}")
    try:
        target.relative_to(root)
    except ValueError:
        pass
    else:
        raise ValueError("release fixture destination must be outside the source root")

    classification = classify_tree(root)
    if not classification["valid"] or not classification["product_valid"]:
        raise ValueError(f"release source is not classifiable: {classification['errors']}")

    product_paths = {record["path"] for record in classification["product_records"]}
    declared_evidence = _declared_evidence_files(root)
    extras = {_safe_fixture_relative(str(path)).as_posix() for path in extra_paths}
    selected = sorted(product_paths | declared_evidence | extras)

    copied_bytes = 0
    for relative in selected:
        source = (root / Path(relative)).resolve(strict=True)
        try:
            source.relative_to(root)
        except ValueError as error:
            raise ValueError(f"release fixture path escapes source root: {relative}") from error
        if not source.is_file():
            raise ValueError(f"release fixture input is not a file: {relative}")
        output = target / Path(relative)
        output.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, output)
        copied_bytes += source.stat().st_size

    return {
        "schema_version": "px.test-release-source-fixture/1.0",
        "valid": True,
        "file_count": len(selected),
        "copied_bytes": copied_bytes,
        "product_file_count": len(product_paths),
        "declared_evidence_file_count": len(declared_evidence),
        "extra_file_count": len(extras),
        "product_digest": classification["product_digest"],
        "harness_digest": classification["harness_digest"],
    }

def _audit_check(
    identifier: str, passed: bool, detail: str, evidence: list[str] | None = None
) -> dict[str, Any]:
    return {
        "id": identifier,
        "passed": bool(passed),
        "detail": detail,
        "evidence": evidence or [],
    }

def _release_audit_walk(root: Path):
    def exclude_audit_path(relative: str | Path) -> bool:
        path = Path(relative)
        parts = path.parts
        if parts and parts[0].casefold() == ".pytest_cache":
            return True
        if parts[:2] == _QUARANTINE_PREFIX:
            return True
        if (
            any(part in _GENERATED_DIRECTORY_NAMES for part in parts)
            or path.name.endswith(".egg-info")
            or path.suffix.casefold() in {".pyc", ".pyo"}
        ):
            return False
        return is_external_environment_relative(relative)

    return bounded_walk(
        root,
        limits=WalkLimits(max_files=100_000, max_depth=128, max_bytes=4 * 1024**3),
        symlink_policy="skip",
        exclude=exclude_audit_path,
    )

def audit_generated_artifact_hygiene(
    root: Path, *, audit_walk=None
) -> dict[str, Any]:
    root = root.resolve()
    audit_walk = audit_walk or _release_audit_walk(root)
    generated = sorted(
        entry.relative
        for entry in audit_walk.entries
        for path in (entry.path,)
        if (
            any(
                part in _GENERATED_DIRECTORY_NAMES
                for part in path.relative_to(root).parts
            )
            or path.name.endswith(".egg-info")
            or path.suffix.casefold() in {".pyc", ".pyo"}
        )
    )
    generated = [
        relative for relative in generated if not relative.startswith("extension/dist")
    ]
    generated_evidence: list[str] = []
    for marker in sorted(_GENERATED_DIRECTORY_NAMES):
        witness = next(
            (
                relative
                for relative in generated
                if marker in Path(relative).parts
            ),
            None,
        )
        if witness is not None and witness not in generated_evidence:
            generated_evidence.append(witness)
    for predicate in (
        lambda path: path.name.endswith(".egg-info"),
        lambda path: path.suffix.casefold() in {".pyc", ".pyo"},
    ):
        witness = next(
            (relative for relative in generated if predicate(Path(relative))), None
        )
        if witness is not None and witness not in generated_evidence:
            generated_evidence.append(witness)
    generated_evidence.extend(
        relative for relative in generated if relative not in generated_evidence
    )
    return _audit_check(
        "generated-artifact-hygiene",
        not generated,
        f"active generated artifacts={len(generated)}",
        generated_evidence[:20],
    )

def audit_python_surface_ownership(
    root: Path, *, audit_walk=None
) -> dict[str, Any]:
    root = root.resolve()
    audit_walk = audit_walk or _release_audit_walk(root)
    ownership_path = root / "registry/python_surface_ownership.json"
    ownership_errors: list[str] = []
    mapped_count = 0
    if ownership_path.is_file():
        ownership = _json(ownership_path)
        mapped = {
            str(record.get("path")): record for record in ownership.get("records", ())
        }
        python_paths = {
            entry.relative: entry.path
            for entry in audit_walk.files
            for path in (entry.path,)
            if path.suffix.casefold() == ".py"
            and is_project_source(path, root)
            and "__pycache__" not in path.parts
            and path.relative_to(root).parts[:2] != _QUARANTINE_PREFIX
        }
        mapped_count = len(mapped)
        for relative, path in python_paths.items():
            record = mapped.get(relative)
            if record is None:
                ownership_errors.append(f"unmapped: {relative}")
            elif hashlib.sha256(path.read_bytes()).hexdigest() != record.get("sha256"):
                ownership_errors.append(f"hash mismatch: {relative}")
        ownership_errors.extend(
            f"missing: {relative}"
            for relative in sorted(set(mapped) - set(python_paths))
        )
    else:
        ownership_errors.append("missing registry/python_surface_ownership.json")
    return _audit_check(
        "python-surface-ownership",
        not ownership_errors,
        f"mapped={mapped_count}; errors={len(ownership_errors)}",
        ["registry/python_surface_ownership.json", *ownership_errors[:20]],
    )

def _valid_pre_identity_failure(value: object, campaign_id: str) -> bool:
    return (
        isinstance(value, dict)
        and value.get("schema_version") == PRE_IDENTITY_FAILURE_SCHEMA
        and value.get("campaign_id") == campaign_id
        and value.get("owner") in {"archive_clear", "reconcile", "identity"}
        and value.get("status") == "failed"
        and value.get("attempt_count") == 1
        and bool(str(value.get("error") or "").strip())
        and bool(str(value.get("recorded_at") or "").strip())
    )

def _validate(value: object) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ReleaseCampaignBlocked("release campaign state must be an object")
    stages = value.get("stages")
    if (
        value.get("schema_version") != "px.release-campaign/1.0"
        or not str(value.get("campaign_id") or "")
        or not str(value.get("repair_campaign_id") or "")
        or value.get("state") not in {"cleared", "active", "failed", "certified"}
        or not isinstance(value.get("apply_count"), int)
        or value["apply_count"] not in {0, 1}
        or not isinstance(stages, dict)
        or set(stages) != set(STAGES)
        or any(
            not isinstance(stages[name], dict)
            or stages[name].get("status")
            not in {"pending", "claimed", "passed", "failed"}
            for name in STAGES
        )
    ):
        raise ReleaseCampaignBlocked("release campaign state is malformed")
    identity = value.get("identity")
    pre_identity_failure = value.get("pre_identity_failure")
    if pre_identity_failure is not None and not _valid_pre_identity_failure(
        pre_identity_failure, str(value["campaign_id"])
    ):
        raise ReleaseCampaignBlocked("pre-identity failure marker is malformed")
    if value["state"] == "cleared":
        if (
            value["apply_count"] != 0
            or identity is not None
            or value.get("active_claim") is not None
            or any(stages[name]["status"] != "pending" for name in STAGES)
        ):
            raise ReleaseCampaignBlocked("cleared release campaign retains identity state")
    elif (
        value["apply_count"] != 1
        or not isinstance(identity, dict)
        or identity.get("schema_version") != "px.release-identity-kernel/2.0"
        or identity.get("campaign_id") != value["campaign_id"]
        or identity.get("repair_campaign_id") != value["repair_campaign_id"]
        or not SHA256_PATTERN.fullmatch(
            str(identity.get("release_identity_sha256") or "")
        )
        or _sha(
            {
                key: item
                for key, item in identity.items()
                if key != "release_identity_sha256"
            }
        )
        != identity.get("release_identity_sha256")
    ):
        raise ReleaseCampaignBlocked("active release campaign identity is malformed")
    if value["state"] != "cleared":
        statuses = [stages[name]["status"] for name in STAGES]
        claimed = [index for index, status in enumerate(statuses) if status == "claimed"]
        failed = [index for index, status in enumerate(statuses) if status == "failed"]
        active_claim = value.get("active_claim")
        if value["state"] == "active":
            if failed or len(claimed) > 1:
                raise ReleaseCampaignBlocked("active release campaign stage state is malformed")
            if not claimed and "pending" not in statuses:
                raise ReleaseCampaignBlocked("active release campaign has no pending stage")
            boundary = claimed[0] if claimed else statuses.index("pending") if "pending" in statuses else len(STAGES)
            if any(status != "passed" for status in statuses[:boundary]) or any(
                status != "pending" for status in statuses[boundary + bool(claimed) :]
            ):
                raise ReleaseCampaignBlocked("active release campaign stages are out of order")
            if claimed:
                stage = STAGES[claimed[0]]
                if (
                    not isinstance(active_claim, dict)
                    or active_claim.get("stage") != stage
                    or active_claim.get("claim_id") != stages[stage].get("claim_id")
                ):
                    raise ReleaseCampaignBlocked("active release stage claim is malformed")
            elif active_claim is not None:
                raise ReleaseCampaignBlocked("release campaign has an unbound active claim")
        elif value["state"] == "failed":
            if len(failed) != 1 or claimed or active_claim is not None:
                raise ReleaseCampaignBlocked("failed release campaign stage state is malformed")
            boundary = failed[0]
            if any(status != "passed" for status in statuses[:boundary]) or any(
                status != "pending" for status in statuses[boundary + 1 :]
            ):
                raise ReleaseCampaignBlocked("failed release campaign stages are out of order")
        elif (
            value["state"] != "certified"
            or any(status != "passed" for status in statuses)
            or active_claim is not None
        ):
            raise ReleaseCampaignBlocked("certified release campaign stage state is malformed")
    return value

def apply_release_identity(root: Path) -> dict[str, Any]:
    """Apply exactly one source identity to the already-cleared campaign."""

    root = root.resolve(strict=True)
    repair = _repair_campaign(root)
    if (
        repair.get("phase") != "revision_reconciled"
        or repair.get("intake_open") is not False
        or repair.get("unresolved") != []
    ):
        raise ReleaseCampaignBlocked(
            "release identity apply requires one reconciled, zero-unresolved revision"
        )
    path = root / STATE_PATH
    value = _validate(json.loads(path.read_text(encoding="utf-8")))
    if value.get("repair_campaign_id") != repair["campaign_id"]:
        raise ReleaseCampaignBlocked("cleared identity belongs to another repair campaign")
    if value["state"] != "cleared" or value["apply_count"] != 0:
        raise ReleaseCampaignBlocked("release identity was already applied")
    classification = classify_tree(root)
    if not classification["valid"] or not classification["product_valid"]:
        raise ReleaseCampaignBlocked(
            "release source classification failed: "
            + "; ".join(classification["errors"][:8])
        )
    extension = json.loads(
        (root / "extension/package.json").read_text(encoding="utf-8")
    )
    source_manifest = classification["product_records"]
    kernel = {
        "schema_version": "px.release-identity-kernel/2.0",
        "campaign_id": value["campaign_id"],
        "repair_campaign_id": repair["campaign_id"],
        "release_version": authoritative_version(root),
        "extension_version": str(extension.get("version") or ""),
        "source_product_digest": classification["product_digest"],
        "source_harness_digest": classification["harness_digest"],
        "source_manifest_sha256": _sha(source_manifest),
        "source_file_count": len(source_manifest),
        "release_policy_sha256": classification["policy_sha256"],
    }
    value.update(
        {
            "state": "active",
            "applied_at": _now(),
            "apply_count": 1,
            "identity": {
                **kernel,
                "release_identity_sha256": _sha(kernel),
            },
        }
    )
    _write(path, value)
    return release_campaign_status(root, verify_source=True)

def claim_release_stage(root: Path, stage: str) -> dict[str, Any]:
    root = root.resolve(strict=True)
    if stage not in STAGES:
        raise ReleaseCampaignBlocked(f"unknown release stage: {stage}")
    path = root / STATE_PATH
    value = _validate(json.loads(path.read_text(encoding="utf-8")))
    repair = _repair_campaign(root)
    if (
        value.get("repair_campaign_id") != repair.get("campaign_id")
        or repair.get("phase") != STAGE_PHASES[stage]
        or repair.get("intake_open") is not False
        or repair.get("unresolved") != []
    ):
        raise ReleaseCampaignBlocked(
            f"release stage {stage} requires zero unresolved work at phase "
            f"{STAGE_PHASES[stage]}"
        )
    if value["state"] != "active" or value.get("active_claim") is not None:
        raise ReleaseCampaignBlocked("release campaign is not available for a stage claim")
    status = release_campaign_status(root, verify_source=True)
    if not status["valid"]:
        raise ReleaseCampaignBlocked("release source changed after identity apply")
    index = STAGES.index(stage)
    predecessors = STAGES[:index]
    if any(value["stages"][name]["status"] != "passed" for name in predecessors):
        raise ReleaseCampaignBlocked(
            f"release stage {stage} has an incomplete predecessor"
        )
    if value["stages"][stage]["status"] != "pending":
        raise ReleaseCampaignBlocked(f"release stage {stage} cannot be replayed")
    claim_id = f"release-stage:{value['campaign_id']}:{stage}:{uuid4().hex}"
    claim = {"stage": stage, "claim_id": claim_id, "claimed_at": _now()}
    value["active_claim"] = claim
    value["stages"][stage] = {
        "status": "claimed",
        "claim_id": claim_id,
        "claimed_at": claim["claimed_at"],
    }
    _write(path, value)
    return {**claim, "release_identity_sha256": value["identity"]["release_identity_sha256"]}

def clear_release_identity(root: Path, *, campaign_id: str) -> dict[str, Any]:
    """Create one empty campaign; never erase/reuse an already-applied campaign."""

    root = root.resolve(strict=True)
    if not campaign_id.strip():
        raise ReleaseCampaignBlocked("release campaign ID is required")
    repair = _repair_campaign(root)
    if repair.get("phase") not in {"repair", "repair_frozen"}:
        raise ReleaseCampaignBlocked(
            "release identity may be cleared only during repair or repair freeze"
        )
    path = root / STATE_PATH
    if path.is_file():
        previous = _validate(json.loads(path.read_text(encoding="utf-8")))
        same_repair = previous.get("repair_campaign_id") == repair["campaign_id"]
        if same_repair and previous.get("campaign_id") != campaign_id:
            raise ReleaseCampaignBlocked(
                "the current repair campaign already owns a release campaign"
            )
        if previous.get("campaign_id") == campaign_id:
            if previous["state"] == "cleared":
                return release_campaign_status(root)
            raise ReleaseCampaignBlocked(
                "an applied release campaign cannot be cleared and reused"
            )
    value = {
        "schema_version": "px.release-campaign/1.0",
        "campaign_id": campaign_id,
        "repair_campaign_id": repair["campaign_id"],
        "state": "cleared",
        "cleared_at": _now(),
        "applied_at": None,
        "apply_count": 0,
        "identity": None,
        "active_claim": None,
        "stages": {name: {"status": "pending", "claim_id": None} for name in STAGES},
    }
    _write(path, value)
    return release_campaign_status(root)

def finish_release_stage(
    root: Path, *, stage: str, claim_id: str, passed: bool
) -> dict[str, Any]:
    root = root.resolve(strict=True)
    path = root / STATE_PATH
    value = _validate(json.loads(path.read_text(encoding="utf-8")))
    claim = value.get("active_claim")
    if (
        not isinstance(claim, dict)
        or claim.get("stage") != stage
        or claim.get("claim_id") != claim_id
        or value["stages"].get(stage, {}).get("status") != "claimed"
    ):
        raise ReleaseCampaignBlocked("release stage completion does not bind its claim")
    if passed and not release_campaign_status(root, verify_source=True)["valid"]:
        passed = False
    final = "passed" if passed else "failed"
    value["stages"][stage] = {
        **value["stages"][stage],
        "status": final,
        "finished_at": _now(),
    }
    value["active_claim"] = None
    if not passed:
        value["state"] = "failed"
