def admission_experiment(
    candidate: dict[str, object],
    *,
    local_tests: Iterable[str],
    negative_tests: Iterable[str],
) -> dict[str, object]:
    positive = tuple(sorted(set(map(str, local_tests))))
    negative = tuple(sorted(set(map(str, negative_tests))))
    reasons = []
    if candidate.get("state") != "candidate_experiment":
        reasons.append("candidate_state_invalid")
    if not positive:
        reasons.append("local_reproduction_tests_missing")
    if not negative:
        reasons.append("negative_boundary_tests_missing")
    return {
        "decision": "ready_for_local_experiment" if not reasons else "blocked",
        "reasons": tuple(reasons),
        "positive_tests": positive,
        "negative_tests": negative,
        "activation": "candidate_only",
        "auto_activate": False,
    }

def canonicalize_research(mechanisms: Iterable[ResearchMechanism]) -> dict[str, object]:
    values = tuple(mechanisms)
    if not values:
        raise ValueError("research assimilation requires at least one mechanism")
    errors = []
    for item in values:
        if not item.source_id or len(item.source_sha256) != 64:
            errors.append(f"invalid_source_identity:{item.source_id or 'unknown'}")
        if not item.citation.strip():
            errors.append(f"citation_missing:{item.source_id}")
        if not all(
            (
                item.claim.strip(),
                item.mechanism.strip(),
                item.evaluation_context.strip(),
            )
        ):
            errors.append(f"mechanism_incomplete:{item.source_id}")
        if (
            not item.assumptions
            or not item.limitations
            or not item.reproduction_requirements
        ):
            errors.append(f"boundary_evidence_incomplete:{item.source_id}")
    groups: dict[str, list[ResearchMechanism]] = {}
    for item in values:
        groups.setdefault(item.capability_id, []).append(item)
    candidates = []
    for capability_id, items in sorted(groups.items()):
        independent_sources = len({item.citation.casefold().strip() for item in items})
        mechanism_tokens = [
            set(WORD.findall(item.mechanism.casefold())) for item in items
        ]
        shared = set.intersection(*mechanism_tokens) if mechanism_tokens else set()
        candidates.append(
            {
                "capability_id": capability_id,
                "source_ids": tuple(sorted(item.source_id for item in items)),
                "independent_source_count": independent_sources,
                "recurring_mechanism_terms": tuple(sorted(shared)),
                "convergence": "multi_source"
                if independent_sources >= 2
                else "single_source",
                "assumptions": tuple(
                    sorted({value for item in items for value in item.assumptions})
                ),
                "limitations": tuple(
                    sorted({value for item in items for value in item.limitations})
                ),
                "reproduction_requirements": tuple(
                    sorted(
                        {
                            value
                            for item in items
                            for value in item.reproduction_requirements
                        }
                    )
                ),
                "state": "candidate_experiment",
                "production_proof": False,
                "auto_activate": False,
            }
        )
    return {
        "state": "blocked" if errors else "candidate",
        "errors": tuple(sorted(set(errors))),
        "sources": tuple(asdict(item) for item in values),
        "candidates": tuple(candidates),
        "bundle_sha256": _stable([asdict(item) for item in values]),
        "production_proof": False,
        "auto_activate": False,
    }

def storage_status(
    self, path: Path, budget: StorageBudget = StorageBudget()
) -> dict[str, object]:
    usage = shutil.disk_usage(path)
    free_fraction = usage.free / usage.total if usage.total else 0.0
    records = self.ledger.load()
    owned = [
        item
        for item in records
        if item.classification == ResourceClassification.EPHEMERAL.value
        and item.status != ResourceStatus.RECLAIMED.value
    ]
    owned_bytes = sum(item.bytes for item in owned)
    if (
        usage.free < budget.minimum_free_bytes
        or free_fraction <= budget.critical_free_fraction
    ):
        pressure = StoragePressure.CRITICAL
    elif free_fraction <= budget.high_free_fraction:
        pressure = StoragePressure.HIGH
    elif free_fraction <= budget.warning_free_fraction:
        pressure = StoragePressure.WARNING
    else:
        pressure = StoragePressure.NORMAL
    alerts: list[str] = []
    if (
        budget.max_owned_ephemeral_bytes is not None
        and owned_bytes > budget.max_owned_ephemeral_bytes
    ):
        alerts.append("owned ephemeral byte budget exceeded")
    if (
        budget.max_workspace_count is not None
        and len(owned) > budget.max_workspace_count
    ):
        alerts.append("workspace count budget exceeded")
    if (
        budget.max_file_count is not None
        and sum(item.files for item in owned) > budget.max_file_count
    ):
        alerts.append("owned ephemeral file budget exceeded")
    return {
        "valid": not alerts,
        "pressure": pressure.value,
        "host_total_bytes": usage.total,
        "host_free_bytes": usage.free,
        "host_free_fraction": free_fraction,
        "owned_ephemeral_bytes": owned_bytes,
        "owned_ephemeral_resources": len(owned),
        "quarantine_bytes": sum(
            item.bytes
            for item in records
            if item.classification == ResourceClassification.QUARANTINE.value
        ),
        "alerts": alerts,
    }

