def emit(
    self,
    operation_name: str,
    lifecycle: str,
    result: str,
    *,
    declared_effects: tuple[str, ...] = (),
    observed_effects: tuple[str, ...] = (),
    input_sha256: str | None = None,
    output_sha256: str | None = None,
) -> dict[str, object]:
    event = build_operation_event(
        self.engine_root,
        {
            "sdk_version": SDK_VERSION,
            "schema_version": "px.operation-event/1",
            "event_id": f"evt-{uuid.uuid4().hex}",
            "correlation_id": self.correlation_id,
            "parent_correlation_id": None,
            "actor": {
                "actor_id": self.actor_id,
                "actor_kind": "runtime",
                "session_id": self.session_id,
                "harness": "pacify-x-runtime",
                "accountable_owner": self.actor_id,
            },
            "work": {
                "project_id": self.project_id,
                "task_id": self.task_id,
                "claim_id": None,
                "orchestration_id": self.orchestration_id,
            },
            "source": {
                "route_id": "runtime.project-control-plane",
                "component": "runtime.runtime_lifecycle",
                "host_id": None,
                "coverage_tier": "C",
            },
            "operation": {
                "name": operation_name,
                "lifecycle": lifecycle,
                "result": result,
            },
            "effects": {
                "declared": list(declared_effects),
                "observed": list(observed_effects),
                "scope_refs": [f"project:{self.project_id}"],
            },
            "provider": None,
            "time": {
                "observed_at": datetime.now(timezone.utc).isoformat(),
                "started_at": None,
                "duration_ms": None,
                "freshness": "live",
            },
            "integrity": {
                "input_sha256": input_sha256,
                "output_sha256": output_sha256,
                "previous_event_sha256": self._previous,
            },
            "capture": {
                "classification": "metadata_only",
                "payload_included": False,
            },
        },
    )
    receipt = self.bus.publish(event)
    self._previous = str(receipt["event_sha256"])
    return receipt

class ResourceScheduler:
    def __init__(self, policy: ResourcePolicy = ResourcePolicy()) -> None:
        if (
            min(
                policy.max_agents,
                policy.max_light_lanes,
                policy.max_heavy_lanes,
                policy.lost_worker_seconds,
            )
            < 1
        ):
            raise ValueError("resource limits must be positive")
        self.policy = policy
        self._lanes: dict[str, str] = {}
        self._workers: dict[str, datetime] = {}
        self._ownership: dict[str, frozenset[str]] = {}
        self._assignments: dict[str, str] = {}

    def admit(
        self,
        work_id: str,
        lane: str,
        snapshot: Mapping[str, float | int],
        *,
        owned_paths: tuple[str, ...] = (),
    ) -> Admission:
        if lane not in {"light", "heavy"}:
            return Admission(False, "unknown lane")
        if work_id in self._lanes:
            return Admission(False, "work is already admitted")
        if float(snapshot.get("memory_percent", 0)) >= self.policy.max_memory_percent:
            return Admission(False, "memory pressure threshold reached")
        if float(snapshot.get("gpu_percent", 0)) >= self.policy.max_gpu_percent:
            return Admission(False, "GPU pressure threshold reached")
        if (
            float(snapshot.get("wsl_memory_percent", 0))
            >= self.policy.max_wsl_memory_percent
        ):
            return Admission(False, "WSL memory pressure threshold reached")
        if (
            float(snapshot.get("docker_memory_percent", 0))
            >= self.policy.max_docker_memory_percent
        ):
            return Admission(False, "Docker memory pressure threshold reached")
        normalized_paths = frozenset(
            path.replace("\\", "/").casefold().rstrip("/") for path in owned_paths
        )
        for owner, existing in self._ownership.items():
            if any(
                left == right
                or left.startswith(right + "/")
                or right.startswith(left + "/")
                for left in normalized_paths
                for right in existing
            ):
                return Admission(False, f"file ownership overlaps {owner}")
        limit = (
            self.policy.max_heavy_lanes
            if lane == "heavy"
            else self.policy.max_light_lanes
        )
        if sum(value == lane for value in self._lanes.values()) >= limit:
            return Admission(False, f"{lane} lane is serialized")
        if int(snapshot.get("agents", len(self._workers))) >= self.policy.max_agents:
            return Admission(False, "agent budget reached")
        self._lanes[work_id] = lane
        self._ownership[work_id] = normalized_paths
        return Admission(True, "resource policy admitted work")

    def release(self, work_id: str) -> bool:
        self._ownership.pop(work_id, None)
        for worker, assigned in tuple(self._assignments.items()):
            if assigned == work_id:
                self._assignments.pop(worker, None)
        return self._lanes.pop(work_id, None) is not None

    def heartbeat(self, worker_id: str, at: datetime | None = None) -> None:
        self._workers[worker_id] = at or datetime.now(timezone.utc)

    def assign_worker(self, worker_id: str, work_id: str) -> None:
        if work_id not in self._lanes:
            raise ValueError("work must be admitted before worker assignment")
        if (
            len(self._assignments) >= self.policy.max_agents
            and worker_id not in self._assignments
        ):
            raise ValueError("agent budget reached")
        self._assignments[worker_id] = work_id
        self.heartbeat(worker_id)

    def lost_workers(self, now: datetime | None = None) -> tuple[str, ...]:
        reference = now or datetime.now(timezone.utc)
        threshold = timedelta(seconds=self.policy.lost_worker_seconds)
        return tuple(
            sorted(
                worker
                for worker, last_seen in self._workers.items()
                if reference - last_seen > threshold
            )
        )

    def recover_lost(self, now: datetime | None = None) -> tuple[str, ...]:
        recovered: list[str] = []
        for worker in self.lost_workers(now):
            work_id = self._assignments.pop(worker, None)
            self._workers.pop(worker, None)
            if work_id is not None:
                self.release(work_id)
                recovered.append(work_id)
        return tuple(sorted(recovered))

    def snapshot(self, now: datetime | None = None) -> dict[str, object]:
        """Expose current admission facts without probing or starting work."""
        lost = self.lost_workers(now)
        return {
            "schema_version": "px.resource-scheduler-snapshot/1.0",
            "limits": {
                "agents": self.policy.max_agents,
                "light_lanes": self.policy.max_light_lanes,
                "heavy_lanes": self.policy.max_heavy_lanes,
            },
            "active": {
                work_id: {
                    "lane": lane,
                    "owned_paths": sorted(self._ownership.get(work_id, ())),
                    "workers": sorted(
                        worker
                        for worker, assigned in self._assignments.items()
                        if assigned == work_id
                    ),
                }
                for work_id, lane in sorted(self._lanes.items())
            },
            "active_count": len(self._lanes),
            "workers": len(self._workers),
            "lost_workers": list(lost),
            "cpu_authoritative": True,
        }

def admit(
    self,
    work_id: str,
    lane: str,
    snapshot: Mapping[str, float | int],
    *,
    owned_paths: tuple[str, ...] = (),
) -> Admission:
    if lane not in {"light", "heavy"}:
        return Admission(False, "unknown lane")
    if work_id in self._lanes:
        return Admission(False, "work is already admitted")
    if float(snapshot.get("memory_percent", 0)) >= self.policy.max_memory_percent:
        return Admission(False, "memory pressure threshold reached")
    if float(snapshot.get("gpu_percent", 0)) >= self.policy.max_gpu_percent:
        return Admission(False, "GPU pressure threshold reached")
    if (
        float(snapshot.get("wsl_memory_percent", 0))
        >= self.policy.max_wsl_memory_percent
    ):
        return Admission(False, "WSL memory pressure threshold reached")
    if (
        float(snapshot.get("docker_memory_percent", 0))
        >= self.policy.max_docker_memory_percent
    ):
        return Admission(False, "Docker memory pressure threshold reached")
    normalized_paths = frozenset(
        path.replace("\\", "/").casefold().rstrip("/") for path in owned_paths
    )
    for owner, existing in self._ownership.items():
        if any(
            left == right
            or left.startswith(right + "/")
            or right.startswith(left + "/")
            for left in normalized_paths
            for right in existing
        ):
            return Admission(False, f"file ownership overlaps {owner}")
    limit = (
        self.policy.max_heavy_lanes
        if lane == "heavy"
        else self.policy.max_light_lanes
    )
    if sum(value == lane for value in self._lanes.values()) >= limit:
        return Admission(False, f"{lane} lane is serialized")
    if int(snapshot.get("agents", len(self._workers))) >= self.policy.max_agents:
        return Admission(False, "agent budget reached")
    self._lanes[work_id] = lane
    self._ownership[work_id] = normalized_paths
    return Admission(True, "resource policy admitted work")

def assign_worker(self, worker_id: str, work_id: str) -> None:
    if work_id not in self._lanes:
        raise ValueError("work must be admitted before worker assignment")
    if (
        len(self._assignments) >= self.policy.max_agents
        and worker_id not in self._assignments
    ):
        raise ValueError("agent budget reached")
    self._assignments[worker_id] = work_id
    self.heartbeat(worker_id)

def recover_lost(self, now: datetime | None = None) -> tuple[str, ...]:
    recovered: list[str] = []
    for worker in self.lost_workers(now):
        work_id = self._assignments.pop(worker, None)
        self._workers.pop(worker, None)
        if work_id is not None:
            self.release(work_id)
            recovered.append(work_id)
    return tuple(sorted(recovered))

def release(self, work_id: str) -> bool:
    self._ownership.pop(work_id, None)
    for worker, assigned in tuple(self._assignments.items()):
        if assigned == work_id:
            self._assignments.pop(worker, None)
    return self._lanes.pop(work_id, None) is not None

def scan_secret_shapes(
    root: Path, *, review_registry: Path | None = None
) -> dict[str, object]:
    resolved = root.resolve(strict=True)
    if not resolved.is_dir() or resolved == Path(resolved.anchor):
        raise ValueError("root must be an explicit non-filesystem-root directory")
    findings: list[dict[str, object]] = []
    files_scanned = 0
    errors: list[dict[str, str]] = []
    source_files: list[Path] = []
    for directory, names, files in os.walk(resolved, topdown=True, followlinks=False):
        relative_directory = Path(directory).relative_to(resolved)
        names[:] = sorted(
            name for name in names
            if name not in SKIP_DIRECTORIES
            and not name.startswith(".venv")
            and not is_external_environment_relative(relative_directory / name)
        )
        source_files.extend(Path(directory) / name for name in sorted(files))
    for path in source_files:
        if path.is_symlink() or not path.is_file():
            continue
        try:
            sample = path.read_bytes()
            if b"\x00" in sample[:65536]:
                continue
            text = sample.decode("utf-8", errors="ignore")
        except OSError as error:
            errors.append(
                {
                    "file": path.relative_to(resolved).as_posix(),
                    "error": type(error).__name__,
                }
            )
            continue
        files_scanned += 1
        findings.extend(_scan_text(path, resolved, text))
    registry_path = review_registry or (
        resolved / "registry/secret_finding_reviews.json"
    )
    reviews: dict[str, dict[str, object]] = {}
    if registry_path.is_file():
        try:
            payload = json.loads(registry_path.read_text(encoding="utf-8"))
            reviews = {str(item["id"]): item for item in payload.get("records", ())}
        except (OSError, ValueError, KeyError, json.JSONDecodeError) as error:
            errors.append({"file": str(registry_path), "error": type(error).__name__})
    finding_ids = {str(item["id"]) for item in findings}
    for item in findings:
        review = reviews.get(str(item["id"]))
        if review and all(
            review.get(key) == item.get(key) for key in ("file", "kind", "line_sha256")
        ):
            item["classification"] = str(
                review.get("classification", "reviewed_fixture")
            )
            item["review_owner"] = str(review.get("owner", "unknown"))
        else:
            item["classification"] = "unreviewed"
    stale_reviews = sorted(set(reviews) - finding_ids)
    if stale_reviews:
        errors.append({"file": str(registry_path), "error": "stale_reviews"})
    unreviewed = [item for item in findings if item["classification"] == "unreviewed"]
    return {
        "schema_version": "1.1",
        "scan_scope": "active-source-tree; generated custody, caches, environments, build outputs, and dependency stores excluded",
        "valid": not unreviewed and not errors,
        "files_scanned": files_scanned,
        "finding_count": len(findings),
        "reviewed_count": len(findings) - len(unreviewed),
        "unreviewed_count": len(unreviewed),
        "findings": findings,
        "error_count": len(errors),
        "errors": errors,
    }

"""Build and validate a compact semantic index without runtime skill hydration."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path
import re
import tomllib

from .capability_semantics import (
    build_capability_semantic_profile,
    validate_capability_semantic_profile,
)


DESCRIPTION = re.compile(r"(?m)^description:\s*[\"']?(.*?)[\"']?\s*$")


def _load_json(path: Path) -> dict:
    return json.loads(path.read_text(encoding="utf-8"))


def _description_text(text: str) -> str:
    match = DESCRIPTION.search(text)
    return match.group(1).strip() if match else ""


def build_semantic_index(
    root: Path, *, overlays: dict[str, bytes] | None = None
) -> dict[str, object]:
    root = root.resolve()
    overlay_bytes = dict(overlays or {})

    def read_bytes(path: Path) -> bytes | None:
        relative = path.relative_to(root).as_posix()
        if relative in overlay_bytes:
            return overlay_bytes[relative]
        return path.read_bytes() if path.is_file() else None

    def read_json(path: Path) -> dict:
        data = read_bytes(path)
        return json.loads(data.decode("utf-8")) if data is not None else {}

    catalog_data = read_bytes(root / "registry" / "skill_catalog.toml")
    if catalog_data is None:
        raise FileNotFoundError("skill catalog is unavailable")
    catalog = tomllib.loads(catalog_data.decode("utf-8"))
    workflow_path = root / "registry" / "skill_orchestrations.json"
    workflow_membership: dict[str, set[str]] = {}
    alias_path = root / "registry" / "capability_aliases.json"
    aliases_by_owner: dict[str, set[str]] = {}
    if alias_path.is_file():
        for alias in _load_json(alias_path).get("records", ()):
            aliases_by_owner.setdefault(str(alias.get("owner", "")), set()).add(
                str(alias.get("alias", ""))
            )
    if workflow_path.is_file():
        for workflow in _load_json(workflow_path).get("workflows", ()):
            workflow_id = str(workflow.get("id", ""))
            for step in workflow.get("steps", ()):
                workflow_membership.setdefault(str(step.get("skill", "")), set()).add(
                    workflow_id
                )
    records: list[dict[str, object]] = []
    for item in catalog.get("skills", ()):
        skill_id = str(item["id"])
        body = root / str(item["body"])
        contract_path = root / str(item["contract"])
        contract = read_json(contract_path)
        body_data = read_bytes(body)
        contract_data = read_bytes(contract_path)
        tags = sorted({str(value) for value in item.get("tags", ())})
        resources = [str(value) for value in contract.get("resources", ())]
        profile = build_capability_semantic_profile(
            {
                **item,
                "aliases": sorted(aliases_by_owner.get(skill_id, set())),
                "triggers": contract.get("triggers", ()),
            },
            contract,
            maturity=None,
        )
        semantic_profile = profile.as_dict()
        profile_revision = hashlib.sha256(
            json.dumps(
                semantic_profile, sort_keys=True, separators=(",", ":")
            ).encode("utf-8")
        ).hexdigest()
        records.append(
            {
                "id": skill_id,
                "kind": "skill",
                "status": str(item.get("status", "candidate")),
                "description": _description_text(body_data.decode("utf-8"))
                if body_data is not None
                else "",
                "domains": list(profile.domains),
                "intents": list(profile.positive_intents),
                "negative_intents": list(profile.negative_intents),
                "concepts": sorted(
                    set((*tags, *skill_id.split("-"), *profile.domains))
                ),
                "synonyms": list(profile.synonyms),
                "tools": sorted({Path(value).stem for value in resources if value}),
                "relations": sorted(workflow_membership.get(skill_id, ())),
                "semantic_profile": semantic_profile,
                "profile_revision": profile_revision,
                "contract_revision": hashlib.sha256(contract_data).hexdigest()
                if contract_data is not None
                else "",
                "body_sha256": hashlib.sha256(body_data).hexdigest()
                if body_data is not None
                else "",
            }
        )
    records.sort(key=lambda value: str(value["id"]))
    revision = hashlib.sha256(
        json.dumps(records, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    return {
        "schema_version": "1.0",
        "loading_rule": "metadata_only",
        "revision": revision,
        "record_count": len(records),
        "records": records,
    }


def load_semantic_index(root: Path) -> dict[str, object]:
    return _load_json(root.resolve() / "registry" / "semantic_capability_index.json")


def validate_semantic_index(root: Path) -> dict[str, object]:
    expected = build_semantic_index(root)
    try:
        actual = load_semantic_index(root)
    except (OSError, json.JSONDecodeError) as error:
        return {"valid": False, "errors": [f"semantic index unavailable: {error}"]}
    errors: list[str] = []
    alias_path = root.resolve() / "registry" / "capability_aliases.json"
    if alias_path.is_file():
        aliases = _load_json(alias_path).get("records", ())
        owners = {str(record["id"]) for record in expected["records"]}
        seen_aliases: dict[str, str] = {}
        for record in aliases:
            alias = str(record.get("alias", "")).strip()
            owner = str(record.get("owner", ""))
            if not alias:
                errors.append("capability alias must be nonempty")
            if owner not in owners:
                errors.append(f"capability alias {alias}: unknown owner {owner}")
            if alias in seen_aliases and seen_aliases[alias] != owner:
                errors.append(f"capability alias {alias}: conflicting owners")
            seen_aliases[alias] = owner
    if actual != expected:
        errors.append("semantic capability index is stale or non-deterministic")
    seen: set[str] = set()
    for record in expected["records"]:
        capability_id = str(record.get("id") or "")
        if capability_id in seen:
            errors.append(f"duplicate semantic identity: {capability_id}")
        seen.add(capability_id)
        profile = record.get("semantic_profile")
        report = (
            validate_capability_semantic_profile(profile)
            if isinstance(profile, dict)
            else {"valid": False, "errors": ["profile missing"]}
        )
        if not report["valid"]:
            errors.append(f"{capability_id}: invalid semantic profile: {report['errors']}")
        if record.get("status") == "active" and not record.get("intents"):
            errors.append(f"{capability_id}: active routable skill has empty positive intent")
        calculated = hashlib.sha256(
            json.dumps(profile, sort_keys=True, separators=(",", ":")).encode("utf-8")
        ).hexdigest()
        if record.get("profile_revision") != calculated:
            errors.append(f"{capability_id}: stale semantic profile revision")
    return {
        "valid": not errors,
        "record_count": expected["record_count"],
        "revision": expected["revision"],
        "errors": errors,
    }

