def resolve_test_groups(root: Path) -> list[dict[str, Any]]:
    """Read compact native group metadata; never rediscover during status."""
    root = root.resolve()
    config = json.loads(
        (root / "registry/test_profiles.json").read_text(encoding="utf-8")
    )
    path = root / "registry/test_group_index.json"
    try:
        index = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        raise ValueError(
            "test group index missing or corrupt; run python scripts/build_test_group_index.py"
        ) from error
    if index.get("topology_sha256") != _group_topology_sha256(config):
        raise ValueError(
            "test group topology is stale; run python scripts/build_test_group_index.py"
        )
    current_tests = sorted(
        path.relative_to(root).as_posix() for path in (root / "tests").glob("test_*.py")
    )
    indexed_tests = sorted(
        member
        for group in index.get("groups", ())
        for member in group.get("members", ())
    )
    if current_tests != indexed_tests:
        raise ValueError(
            "test group membership is stale; run python scripts/build_test_group_index.py"
        )
    environment = dict(config.get("environment", {}))
    groups = []
    for stored in index.get("groups", ()):
        group_name = str(stored.get("group", ""))
        stored_scan_inputs = list(map(str, stored.get("scan_inputs", ())))
        base_inputs = list(
            map(str, stored.get("base_inputs", stored.get("inputs", ())))
        )
        current_scan_inputs = (
            _structural_scan_files(root)
            if group_name == "structural-adversarial"
            else []
        )
        inputs = sorted({*base_inputs, *current_scan_inputs})
        try:
            current_sha256 = _fingerprint(root, inputs)
        except OSError:
            current_sha256 = ""
        inventory_current = current_scan_inputs == stored_scan_inputs
        index_current = (
            inventory_current and current_sha256 == stored.get("input_sha256")
        )
        groups.append(
            {
                "schema_version": "px.test-group/1.0",
                "valid": index_current,
                **stored,
                "index_current": index_current,
                "scan_inventory_current": inventory_current,
                "input_sha256": current_sha256,
                "indexed_input_sha256": stored.get("input_sha256"),
                "environment": environment,
                "command": [
                    sys.executable,
                    "-m",
                    "pytest",
                    "-q",
                    "--durations=20",
                    "-p",
                    "no:cacheprovider",
                    *stored["members"],
                ],
            }
        )
    return groups

def section_status(root: Path) -> dict[str, Any]:
    root = root.resolve()
    config = json.loads(
        (root / "registry/test_profiles.json").read_text(encoding="utf-8")
    )
    receipt_root = root / ".engineering-bootstrap/test-evidence/sections"
    rows = []
    for name in sorted(config.get("sections", {})):
        current = resolve_test_section(root, name)
        path = receipt_root / f"{name}.json"
        try:
            receipt = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            receipt = {}
        passed = receipt.get("passed") is True
        fresh = receipt.get("input_sha256") == current["input_sha256"]
        rows.append(
            {
                "section": name,
                "dependencies": current["dependencies"],
                "passed": passed,
                "fresh": fresh,
                "dependencies_current": False,
                "current": False,
                "input_sha256": current["input_sha256"],
                "receipt": path.as_posix(),
            }
        )
    by_name = {row["section"]: row for row in rows}

    def current(name: str, visiting: frozenset[str] = frozenset()) -> bool:
        if name in visiting or name not in by_name:
            return False
        row = by_name[name]
        dependencies_current = all(
            current(dependency, visiting | {name}) for dependency in row["dependencies"]
        )
        row["dependencies_current"] = dependencies_current
        row["current"] = row["passed"] and row["fresh"] and dependencies_current
        return bool(row["current"])

    for name in by_name:
        current(name)
    required = list(
        map(str, config.get("certification", {}).get("required_sections", ()))
    )
    return {
        "schema_version": "px.test-section-status/1.0",
        "valid": all(by_name.get(name, {}).get("current") is True for name in required),
        "required_sections": required,
        "sections": rows,
    }

if _is_pytest_command(effective_command):
    if not _has_pytest_rootdir(effective_command):
        effective_command.append(f"--rootdir={cwd.resolve(strict=True)}")
    if not _disables_pytest_cache(effective_command):
        effective_command.extend(("-p", "no:cacheprovider"))
    if not _loads_pytest_lifecycle_guards(effective_command):
        # Explicit loading also covers governed tests whose files are
        # outside the repository conftest discovery tree.
        effective_command.extend(("-p", "tests.pytest_guards"))

def _is_pytest_command(command: Sequence[str]) -> bool:
    """Recognize direct and coverage-wrapped pytest invocations."""

    return any(
        Path(str(value)).name.lower() in {"pytest", "pytest.exe"} for value in command
    )

def _corpus_digest(project: Path) -> str:
    records = []
    for path in sorted(project.rglob("*"), key=lambda item: item.as_posix().casefold()):
        if path.is_file() and not path.is_symlink() and _inside(path, project):
            records.append(
                (path.relative_to(project).as_posix(), path.stat().st_size, _sha(path))
            )
    return hashlib.sha256(
        json.dumps(records, separators=(",", ":")).encode()
    ).hexdigest()

def _recipes(ecosystems: set[str], project: Path) -> list[tuple[str, list[str]]]:
    recipes: list[tuple[str, list[str]]] = []
    if "node" in ecosystems and (project / "package-lock.json").is_file():
        recipes.append(("npm-audit", ["npm", "audit", "--json", "--ignore-scripts"]))
    if "python" in ecosystems and shutil.which("pip-audit"):
        recipes.append(("pip-audit", ["pip-audit", "--format", "json", "--local"]))
    if "rust" in ecosystems and shutil.which("cargo-audit"):
        recipes.append(("cargo-audit", ["cargo", "audit", "--json"]))
    if shutil.which("trivy"):
        recipes.append(
            (
                "trivy",
                [
                    "trivy",
                    "fs",
                    "--format",
                    "json",
                    "--scanners",
                    "vuln,secret,misconfig",
                    ".",
                ],
            )
        )
    if shutil.which("syft"):
        recipes.append(("syft-sbom-license", ["syft", ".", "-o", "json"]))
    if shutil.which("clamscan"):
        recipes.append(("clamav", ["clamscan", "--recursive", "--infected", "."]))
    return recipes

def execute_scanner(
    command: list[str],
    *,
    project: Path,
    approved_executable: Path,
    corpus_digest: str,
    network_allowed: bool | None = None,
    network_isolation_enforced: bool = False,
    timeout_seconds: int = 300,
    runner: Runner = subprocess.run,
) -> dict[str, Any]:
    """Run a pre-authorized scanner with a minimal environment and bound result."""
    if timeout_seconds < 1:
        raise ValueError("scanner timeout must be positive")
    if not re.fullmatch(r"[0-9a-f]{64}", corpus_digest):
        raise ValueError("scanner corpus digest must be a lowercase SHA-256")
    if network_allowed is None:
        raise PermissionError("scanner network policy must be explicit")
    if network_allowed is False and not network_isolation_enforced:
        raise PermissionError(
            "network-denied scanner requires an enforced isolation adapter"
        )
    executable = approved_executable.resolve(strict=True)
    if not executable.is_file() or not os.path.isabs(str(approved_executable)):
        raise PermissionError("scanner executable must be an absolute regular file")
    if not command or not Path(command[0]).is_absolute():
        raise PermissionError("scanner path shadowing or identity mismatch")
    try:
        command_executable = Path(command[0]).resolve(strict=True)
    except OSError as error:
        raise PermissionError("scanner path shadowing or identity mismatch") from error
    if command_executable != executable:
        raise PermissionError("scanner path shadowing or identity mismatch")
    environment = {
        "PATH": str(executable.parent),
        "NO_COLOR": "1",
        "PYTHONNOUSERSITE": "1",
    }
    for name in ("SYSTEMROOT", "WINDIR", "COMSPEC"):
        if os.environ.get(name):
            environment[name] = os.environ[name]
    environment["ENGINEERING_BOOTSTRAP_NETWORK"] = (
        "allow" if network_allowed else "deny"
    )
    try:
        version_result = runner(
            [str(executable), "--version"],
            cwd=project.resolve(),
            capture_output=True,
            text=True,
            timeout=min(timeout_seconds, 15),
            shell=False,
            env=environment,
        )
        if version_result.returncode:
            return {
                "status": "failure",
                "failure_stage": "scanner_identity",
                "scanner": {
                    "path": executable.as_posix(),
                    "sha256": _sha(executable),
                    "version": None,
                },
                "input_corpus_sha256": corpus_digest,
                "network_allowed": network_allowed,
                "network_isolation_enforced": network_isolation_enforced,
            }
        version = (
            (version_result.stdout or version_result.stderr or "").strip().splitlines()
            or [""]
        )[0][:500]
        if not version:
            return {
                "status": "failure",
                "failure_stage": "scanner_identity",
                "scanner": {
                    "path": executable.as_posix(),
                    "sha256": _sha(executable),
                    "version": None,
                },
                "input_corpus_sha256": corpus_digest,
                "network_allowed": network_allowed,
                "network_isolation_enforced": network_isolation_enforced,
            }
        completed = runner(
            command,
            cwd=project.resolve(),
            capture_output=True,
            text=True,
            timeout=timeout_seconds,
            shell=False,
            env=environment,
        )
    except subprocess.TimeoutExpired:
        return {
            "status": "timeout",
            "scanner": {
                "path": executable.as_posix(),
                "sha256": _sha(executable),
                "version": None,
            },
            "input_corpus_sha256": corpus_digest,
            "network_allowed": network_allowed,
            "network_isolation_enforced": network_isolation_enforced,
        }
    output = (completed.stdout or "") + (completed.stderr or "")
    parse_error = None
    try:
        structured = json.loads(completed.stdout or "")
    except json.JSONDecodeError as error:
        structured = None
        parse_error = f"{type(error).__name__}: scanner stdout is not structured JSON"
    status = "pass" if completed.returncode == 0 and parse_error is None else "failure"
    return {
        "status": status,
        "failure_stage": "structured_output"
        if parse_error
        else ("scanner_execution" if completed.returncode else None),
        "returncode": completed.returncode,
        "output_sha256": hashlib.sha256(output.encode()).hexdigest(),
        "output_bytes": len(output.encode()),
        "structured_output_type": type(structured).__name__
        if structured is not None
        else None,
        "parse_error": parse_error,
        "scanner": {
            "path": executable.as_posix(),
            "sha256": _sha(executable),
            "version": version,
        },
        "network_allowed": network_allowed,
        "network_isolation_enforced": network_isolation_enforced,
        "input_corpus_sha256": corpus_digest,
    }

def scan_project_tooling(
    project: Path,
    framework_root: Path,
    *,
    execute_scanners: bool = False,
    scanner_approval: bool = False,
    scanner_network_allowed: bool | None = None,
    scanner_network_isolation_enforced: bool = False,
    component_approval: bool = False,
    allowed_licenses: Iterable[str] = (),
    runner: Runner = subprocess.run,
) -> dict[str, Any]:
    project = project.resolve()
    if not project.is_dir():
        raise ValueError("project root does not exist")
    components = _inventory(project)
    allowed = {value.casefold() for value in allowed_licenses}
    recipes = _recipes({item["ecosystem"] for item in components}, project)
    scanners: list[dict[str, Any]] = []
    if execute_scanners and not scanner_approval:
        raise PermissionError(
            "external scanner execution requires explicit scanner approval"
        )
    if execute_scanners and scanner_network_allowed is None:
        raise PermissionError(
            "external scanner execution requires an explicit network policy"
        )
    if execute_scanners:
        corpus_digest = _corpus_digest(project)
        for scanner_id, command in recipes:
            executable = shutil.which(command[0])
            if not executable:
                scanners.append(
                    {"id": scanner_id, "status": "unavailable", "command": command}
                )
                continue
            try:
                result = execute_scanner(
                    [str(Path(executable).resolve()), *command[1:]],
                    project=project,
                    approved_executable=Path(executable),
                    corpus_digest=corpus_digest,
                    network_allowed=scanner_network_allowed,
                    network_isolation_enforced=scanner_network_isolation_enforced,
                    runner=runner,
                )
                scanners.append({"id": scanner_id, "command": command, **result})
            except (OSError, PermissionError) as error:
                scanners.append(
                    {
                        "id": scanner_id,
                        "status": "failure",
                        "command": command,
                        "error": type(error).__name__,
                    }
                )
    else:
        scanners = [
            {"id": name, "status": "available_not_run", "command": command}
            for name, command in recipes
        ]
    scanner_pass = bool(scanners) and all(item["status"] == "pass" for item in scanners)
    schema = framework_root / "contracts" / "external-tool-intake.schema.json"
    for item in components:
        item["approval"] = component_approval
        item["policy_compatible"] = (
            component_approval
            and scanner_pass
            and not item["malicious_indicators"]
            and item["license"].casefold() in allowed
        )
        validate_instance(item, schema)
    decision = (
        "no_external_tooling"
        if not components
        else (
            "admit"
            if components and all(item["policy_compatible"] for item in components)
            else "quarantine"
        )
    )
    return {
        "schema_version": "1.0",
        "project": project.as_posix(),
        "decision": decision,
        "execution_allowed": decision == "admit",
        "components": components,
        "scanners": scanners,
        "scanner_execution": "approved_and_executed"
        if execute_scanners
        else "not_executed",
        "limitations": [
            "UNKNOWN licenses require a reviewed license decision before admission.",
            "Unavailable or unexecuted scanners never produce an admission decision.",
            "This control does not execute, install, import, or detonate candidate packages.",
        ],
        "created_utc": datetime.now(timezone.utc).isoformat(),
    }

"""Read-only, signal-based first-run tooling assessment."""

from __future__ import annotations

import json
import os
from pathlib import Path
import shutil
import subprocess
from typing import Callable


SKIP_DIRECTORIES = {
    ".git",
    ".hg",
    ".svn",
    ".venv",
    "venv",
    "node_modules",
    "build",
    "dist",
    "quarantine",
    "repo_quarantine",
}


def search_project_text(
    project: Path, needle: str, *, resolver: Callable[[str], str | None] = shutil.which
) -> tuple[str, ...]:
    """Search text deterministically; ripgrep is optional acceleration only."""
    project = project.resolve()
    executable = resolver("rg")
    if executable:
        try:
            completed = subprocess.run(
                [executable, "--files-with-matches", "--fixed-strings", needle, "."],
                cwd=project,
                capture_output=True,
                text=True,
                timeout=30,
                shell=False,
                env={"PATH": str(Path(executable).parent), "NO_COLOR": "1"},
            )
            if completed.returncode in {0, 1}:
                return tuple(
                    sorted(
                        (
                            line.removeprefix("./")
                            .removeprefix(".\\")
                            .replace("\\", "/")
                            for line in completed.stdout.splitlines()
                        ),
                        key=lambda value: (value.casefold(), value),
                    )
                )
        except (OSError, subprocess.TimeoutExpired):
            pass
    found = []
    for base, names, files in os.walk(project, followlinks=False):
        names[:] = sorted(name for name in names if name not in SKIP_DIRECTORIES)
        for name in sorted(files):
            path = Path(base) / name
            try:
                if needle in path.read_text(encoding="utf-8", errors="replace"):
                    found.append(path.relative_to(project).as_posix())
            except OSError:
                continue
    return tuple(sorted(found, key=lambda value: (value.casefold(), value)))


def optional_tool_status(
    resolver: Callable[[str], str | None] = shutil.which,
) -> dict[str, object]:
    path = resolver("rg")
    return {
        "name": "ripgrep",
        "available": bool(path),
        "path": path,
        "required": False,
        "disposition": "optional_performance_enhancement",
    }


def _inventory(project: Path, *, maximum_files: int) -> dict[str, object]:
    markdown = source = 0
    directories: set[str] = set()
    examined = 0
    truncated = False
    for base, names, files in os.walk(project, followlinks=False):
        names[:] = sorted(name for name in names if name not in SKIP_DIRECTORIES)
        relative_base = Path(base).relative_to(project)
        directories.update(
            path.as_posix() for name in names if (path := relative_base / name)
        )
        for name in sorted(files):
            examined += 1
            if examined > maximum_files:
                truncated = True
                break
            suffix = Path(name).suffix.casefold()
            markdown += suffix in {".md", ".mdx"}
            source += suffix in {
                ".py",
                ".js",
                ".jsx",
                ".ts",
                ".tsx",
                ".java",
                ".cs",
                ".go",
                ".rs",
                ".rb",
                ".php",
                ".cpp",
                ".c",
                ".h",
            }
        if truncated:
            break
    return {
        "examined_files": min(examined, maximum_files),
        "markdown_files": markdown,
        "source_files": source,
        "directories": directories,
        "truncated": truncated,
    }


def assess_project_tooling(
    root: Path,
    project: Path,
    *,
    resolver: Callable[[str], str | None] = shutil.which,
    maximum_files: int = 5_000,
) -> dict[str, object]:
    root = root.resolve()
    project = project.resolve()
    if not project.is_dir():
        return {
            "schema_version": "1.0",
            "valid": False,
            "project": project.as_posix(),
            "errors": ["project directory does not exist"],
        }
    if maximum_files < 1 or maximum_files > 20_000:
        raise ValueError("maximum_files must be between 1 and 20000")
    registry = json.loads(
        (root / "registry/initial_tool_recommendations.json").read_text(
            encoding="utf-8"
        )
    )
    inventory = _inventory(project, maximum_files=maximum_files)
    results: list[dict[str, object]] = []
    approvals: list[dict[str, object]] = []
    for record in registry["tools"]:
        locations: list[str] = []
        for candidate in record["candidates"]:
            try:
                location = resolver(str(candidate))
            except OSError:
                location = None
            if location:
                locations.append(str(location))
        rule = record["recommend_when"]
        relevant = (
            int(inventory["markdown_files"])
            >= int(rule.get("minimum_markdown_files", 10**9))
            or int(inventory["source_files"])
            >= int(rule.get("minimum_source_files", 10**9))
            or str(rule.get("or_directory", "missing")) in inventory["directories"]
        )
        detected = bool(locations)
        if detected:
            disposition = (
                "available_for_separately_approved_configuration"
                if relevant
                else "available_not_selected"
            )
        elif relevant:
            disposition = str(record["missing_disposition"])
        else:
            disposition = "not_relevant_to_current_project_signals"
        item = {
            "id": record["id"],
            "display_name": record["display_name"],
            "detected": detected,
            "locations": sorted(set(locations)),
            "relevant": relevant,
            "disposition": disposition,
            "built_in_alternatives": record.get("built_in_alternatives", []),
            "auto_install": False,
            "executed_changes": False,
        }
        results.append(item)
        if relevant and not detected and disposition == "offer_optional_installation":
            approvals.append(
                {
                    "id": f"install-{record['id']}",
                    "tool": record["id"],
                    "effect": record["install_effect"],
                    "approval_required": True,
                    "status": "not_requested",
                    "reason": "optional tool is relevant to observed project signals but is not available",
                }
            )
    return {
        "schema_version": "1.0",
        "valid": True,
        "project": project.as_posix(),
        "read_only": True,
        "executed_changes": False,
        "inventory": {
            key: value for key, value in inventory.items() if key != "directories"
        },
        "recommendations": results,
        "approval_requests": approvals,
        "installation_policy": "never_auto_install; submit a separate bounded proposal and obtain explicit approval",
        "errors": [],
    }

