            raise ValueError(
                f"record source provenance mismatch: {record['record_id']}"
            )
        if record["conversation_id"] != source["conversation_id"]:
            raise ValueError(
                f"record conversation identity mismatch: {record['record_id']}"
            )
        if record["queue_id"] != manifest["queue_id"]:
            raise ValueError(f"record queue boundary mismatch: {record['record_id']}")
    target = run_dir / "data" / "records.jsonl"
    if target.exists():
        raise FileExistsError(
            "canonical record file already exists; runs are append-free and immutable"
        )
    rendered = "".join(
        json.dumps(item, sort_keys=True, ensure_ascii=False) + "\n" for item in ordered
    )
    result = {
        "valid": True,
        "applied": apply,
        "record_count": len(ordered),
        "records_sha256": hashlib.sha256(rendered.encode("utf-8")).hexdigest(),
        "target": target.as_posix(),
    }
    if not apply:
        return result
    target.write_text(rendered, encoding="utf-8", newline="\n")
    manifest["records_sha256"] = result["records_sha256"]
    manifest["run_manifest_sha256"] = _stable(
        {key: value for key, value in manifest.items() if key != "run_manifest_sha256"}
    )
    manifest_path.write_text(
        json.dumps(manifest, indent=2, ensure_ascii=False) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    return result

class JsonWal:
    """Coordinate JSON state, event, receipt, handoff, and projection writes."""

    def __init__(
        self,
        journal_root: Path,
        allowed_root: Path,
        *,
        lock_timeout_seconds: float = 10.0,
        precommit_validator: PreCommitValidator | None = None,
    ) -> None:
        self.allowed_root = allowed_root.resolve()
        if not self.allowed_root.is_dir():
            raise ValueError("allowed root must be an existing directory")
        journal_nominal = (
            journal_root
            if journal_root.is_absolute()
            else self.allowed_root / journal_root
        )
        journal_nominal = Path(os.path.abspath(journal_nominal))
        _reject_nominal_link_chain(
            journal_nominal,
            self.allowed_root,
            label="journal root",
        )
        self.journal_root = journal_nominal.resolve()
        if not _inside(self.journal_root, self.allowed_root):
            raise ValueError("journal root must be inside the allowed root")
        self.lock_timeout_seconds = lock_timeout_seconds
        self.precommit_validator = precommit_validator

    @property
    def _lock_path(self) -> Path:
        return self.journal_root / ".wal.lock"

    @property
    def _transactions_root(self) -> Path:
        return self.journal_root / "transactions"

    @property
    def _rolled_back_root(self) -> Path:
        return self.journal_root / "rolled-back"

    @property
    def _committed_root(self) -> Path:
        return self.journal_root / "committed"

    def _normalize(
        self, artifacts: Iterable[Artifact]
    ) -> tuple[tuple[Artifact, Path, bytes], ...]:
        items = tuple(artifacts)
        if not 1 <= len(items) <= MAX_ARTIFACTS:
            raise ValueError(f"transaction must contain 1..{MAX_ARTIFACTS} artifacts")
        normalized: list[tuple[Artifact, Path, bytes]] = []
        targets: set[Path] = set()
        total = 0
        for artifact in items:
            if artifact.role not in ARTIFACT_ROLES:
                raise ValueError(f"unsupported JSON artifact role: {artifact.role}")
            target = self._safe_target(artifact.path, label="artifact")
            if _inside(target, self.journal_root):
                raise ValueError("transaction targets cannot be inside the WAL journal")
            if target in targets:
                raise ValueError(f"duplicate transaction target: {target}")
            targets.add(target)
            if isinstance(artifact, JsonArtifact):
                try:
                    rendered = _canonical(artifact.value)
                except (TypeError, ValueError) as error:
                    raise ValueError(f"artifact is not strict JSON: {target}") from error
            elif isinstance(artifact, JsonTextArtifact):
                if not isinstance(artifact.value, str):
                    raise ValueError(f"JSON text artifact is not a string: {target}")
                try:
                    _strict_json_loads(artifact.value)
                except ValueError as error:
                    raise ValueError(f"artifact is not strict JSON: {target}") from error
                rendered = artifact.value.encode("utf-8")
            elif isinstance(artifact, TextArtifact):
                if not isinstance(artifact.value, str):
                    raise ValueError(f"text artifact is not a string: {target}")
                rendered = artifact.value.encode("utf-8")
            elif isinstance(artifact, BytesArtifact):
                if not isinstance(artifact.value, bytes):
                    raise ValueError(f"byte artifact is not bytes: {target}")
                rendered = artifact.value
            else:
                raise TypeError(f"unsupported artifact type: {type(artifact).__name__}")
            total += len(rendered)
            if total > MAX_TRANSACTION_BYTES:
                raise ValueError("transaction payload exceeds the bounded byte limit")
            normalized.append((artifact, target, rendered))
        return tuple(normalized)

    def _safe_target(self, path: Path, *, label: str) -> Path:
        if ".." in path.parts:
            raise ValueError(f"{label} contains parent traversal: {path}")
        nominal = path if path.is_absolute() else self.allowed_root / path
        nominal = Path(os.path.abspath(nominal))
        _reject_nominal_link_chain(nominal, self.allowed_root, label=label)
        target = nominal.resolve(strict=False)
        if not _inside(target, self.allowed_root):
            raise ValueError(f"{label} escapes allowed root: {path}")
        return target

    def _read_existing(self, artifact: Artifact, path: Path) -> bytes | None:
        if not path.exists():
            return None
        if not path.is_file() or path.is_symlink():
            raise WalIntegrityError(f"target is not a regular file: {path}")
        raw = path.read_bytes()
        if isinstance(artifact, (JsonArtifact, JsonTextArtifact)):
            try:
                _strict_json_loads(raw.decode("utf-8"))
            except (UnicodeError, ValueError) as error:
                raise WalIntegrityError(
                    f"existing JSON target is invalid: {path}"
                ) from error
        elif isinstance(artifact, TextArtifact):
            try:
                raw.decode("utf-8")
            except UnicodeError as error:
                raise WalIntegrityError(
                    f"existing text target is not UTF-8: {path}"
                ) from error
        return raw

    @staticmethod
    def _transition_value(artifact: Artifact, payload: bytes) -> object | bytes | str:
        if isinstance(artifact, (JsonArtifact, JsonTextArtifact)):
            return _strict_json_loads(payload.decode("utf-8"))
        if isinstance(artifact, TextArtifact):
            return payload.decode("utf-8")
        return payload

    def _write_manifest(
        self,
        transaction: Path,
        manifest: Mapping[str, object],
        phase: str,
        fault_injector: FaultInjector | None,
    ) -> dict[str, object]:
        updated = _sealed_manifest({**manifest, "phase": phase})
        _atomic_replace(
            transaction / "manifest.json",
            _canonical(updated),
            label=f"manifest:{phase}",
            fault_injector=fault_injector,
        )
        return updated

    def _load_manifest(self, transaction: Path) -> dict[str, object] | None:
        path = transaction / "manifest.json"
        if not path.is_file():
            return None
        try:
            value = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError) as error:
            raise WalIntegrityError(
                f"{transaction.name}: manifest is unreadable"
            ) from error
        return _validate_manifest(value, transaction.name)

    def _artifact_paths(
        self, transaction: Path, record: Mapping[str, object]
    ) -> tuple[Path, Path, Path | None, str, str | None]:
        try:
            relative = Path(str(record["path"]))
            if relative.is_absolute():
                raise ValueError
            target = self._safe_target(relative, label="recovery target")
            after_record = record["after"]
            before_record = record["before"]
            if not isinstance(after_record, Mapping) or not isinstance(
                before_record, Mapping
            ):
                raise ValueError
            after_nominal = transaction / str(after_record["stage"])
            _reject_nominal_link_chain(
                after_nominal, transaction, label="staged after-image"
            )
            after = after_nominal.resolve()
            before_nominal = transaction / str(before_record["stage"])
            if before_record.get("exists") is True:
                _reject_nominal_link_chain(
                    before_nominal,
                    transaction,
                    label="staged before-image",
                )
                before = before_nominal.resolve()
            else:
                before = None
            after_sha = str(after_record["sha256"])
            before_sha = (
                str(before_record["sha256"])
                if before_record.get("exists") is True
                else None
            )
        except (KeyError, TypeError, ValueError) as error:
            raise WalIntegrityError(
                f"{transaction.name}: malformed artifact record"
            ) from error
        if (
            relative.is_absolute()
            or not _inside(target, self.allowed_root)
            or _inside(target, self.journal_root)
            or not _inside(after, transaction)
            or (before is not None and not _inside(before, transaction))
            or not after.is_file()
        ):
            raise WalIntegrityError(
                f"{transaction.name}: artifact path escapes custody"
            )
        if _sha_bytes(after.read_bytes()) != after_sha:
            raise WalIntegrityError(f"{transaction.name}: staged after-image mismatch")
        if before is not None and (
            not before.is_file() or _sha_bytes(before.read_bytes()) != before_sha
        ):
            raise WalIntegrityError(f"{transaction.name}: staged before-image mismatch")
        return target, after, before, after_sha, before_sha

    def _apply(
        self,
        transaction: Path,
        manifest: Mapping[str, object],
        fault_injector: FaultInjector | None = None,
    ) -> None:
        artifacts = manifest["artifacts"]
        assert isinstance(artifacts, list)
        seen: set[Path] = set()
        for index, raw_record in enumerate(artifacts):
            if not isinstance(raw_record, Mapping):
                raise WalIntegrityError(
                    f"{transaction.name}: artifact record is not an object"
                )
            target, after, _before, after_sha, before_sha = self._artifact_paths(
                transaction, raw_record
            )
            if target in seen:
                raise WalIntegrityError(f"{transaction.name}: duplicate target")
            seen.add(target)
            current = target.read_bytes() if target.is_file() else None
            current_sha = _sha_bytes(current) if current is not None else None
            if current_sha == after_sha:
                continue
            if current_sha != before_sha:
                raise WalIntegrityError(
                    f"{transaction.name}: target changed outside transaction: {target}"
                )
            _atomic_replace(
                target,
                after.read_bytes(),
                label=f"target:{index}",
                fault_injector=fault_injector,
                prepared_path=target.with_name(
                    f".{target.name}.wal-{transaction.name}-{index}.prepared"
                ),
            )

    def _inspect_artifacts(
        self,
        transaction: Path,
        manifest: Mapping[str, object],
        *,
        require_after_images: bool,
    ) -> dict[str, int]:
        """Validate staged images and targets without changing any path."""
        artifacts = manifest["artifacts"]
        assert isinstance(artifacts, list)
        seen: set[Path] = set()
        targets_before = 0
        targets_after = 0
        for raw_record in artifacts:
            if not isinstance(raw_record, Mapping):
                raise WalIntegrityError(
                    f"{transaction.name}: artifact record is not an object"
                )
            target, _after, _before, after_sha, before_sha = self._artifact_paths(
                transaction, raw_record
            )
            if target in seen:
                raise WalIntegrityError(f"{transaction.name}: duplicate target")
            seen.add(target)
            if target.exists() and not target.is_file():
                raise WalIntegrityError(
                    f"{transaction.name}: target is not a regular file: {target}"
                )
            current = target.read_bytes() if target.is_file() else None
            current_sha = _sha_bytes(current) if current is not None else None
            if current_sha == after_sha:
                targets_after += 1
            elif current_sha == before_sha and not require_after_images:
                targets_before += 1
            else:
                label = (
                    "committed target drift"
                    if require_after_images
                    else "target changed outside transaction"
                )
                raise WalIntegrityError(f"{transaction.name}: {label}: {target}")
        return {
            "artifact_count": len(artifacts),
            "targets_before": targets_before,
            "targets_after": targets_after,
        }

    def _inspect_transaction(self, transaction: Path) -> dict[str, object]:
        manifest = self._load_manifest(transaction)
        if manifest is None:
            return {
                "transaction_id": transaction.name,
                "phase": "unprepared",
                "required_action": "rollback",
                "artifact_count": 0,
                "targets_before": 0,
                "targets_after": 0,
            }
        phase = str(manifest["phase"])
        detail = self._inspect_artifacts(
            transaction,
            manifest,
            require_after_images=phase == "committed",
        )
        return {
            "transaction_id": transaction.name,
            "phase": phase,
            "required_action": "archive_committed"
            if phase == "committed"
            else "roll_forward",
            **detail,
        }

    def _pending_transactions(self) -> tuple[Path, ...]:
        if not self._transactions_root.exists():
            return ()
        if not self._transactions_root.is_dir():
            raise WalIntegrityError("WAL transactions authority is not a directory")
        transactions = tuple(
            sorted(self._transactions_root.iterdir(), key=lambda path: path.name)
        )
        if len(transactions) > MAX_PENDING_TRANSACTIONS:
            raise WalIntegrityError("pending WAL transaction bound exceeded")
        for transaction in transactions:
            if (
                not transaction.is_dir()
                or transaction.is_symlink()
                or not _IDENTIFIER.fullmatch(transaction.name)
            ):
                raise WalIntegrityError(
                    f"unexpected directory in WAL authority: {transaction.name}"
                )
        return transactions

    def _inspection_fingerprint(self) -> str:
        if not self._transactions_root.exists():
            return "absent"
        records: list[dict[str, object]] = []
        total_bytes = 0
        paths = sorted(
            self._transactions_root.rglob("*"),
            key=lambda path: path.relative_to(self._transactions_root).as_posix(),
        )
        if len(paths) > MAX_INSPECTION_FILES:
            raise WalIntegrityError("WAL inspection file bound exceeded")
        for path in paths:
            relative = path.relative_to(self._transactions_root).as_posix()
            if path.is_symlink():
                raise WalIntegrityError(f"symlink in WAL authority: {relative}")
            if path.is_dir():
                records.append({"path": relative, "kind": "directory"})
                continue
            if not path.is_file():
                raise WalIntegrityError(f"non-regular WAL entry: {relative}")
            payload = path.read_bytes()
            total_bytes += len(payload)
            if total_bytes > MAX_INSPECTION_BYTES:
                raise WalIntegrityError("WAL inspection byte bound exceeded")
            records.append(
                {
                    "path": relative,
                    "kind": "file",
                    "size": len(payload),
                    "sha256": _sha_bytes(payload),
                }
            )
        return _sha_bytes(_canonical(records))

    def _archive_unprepared(self, transaction: Path) -> Path:
        self._rolled_back_root.mkdir(parents=True, exist_ok=True)
        destination = self._rolled_back_root / transaction.name
        if destination.exists():
            raise WalIntegrityError(
                f"{transaction.name}: rolled-back transaction identity collision"
            )
        _replace_with_bounded_permission_retry(transaction, destination)
        _fsync_directory(self._transactions_root)
        _fsync_directory(self._rolled_back_root)
        return destination

    def _archive_committed(
        self,
        transaction: Path,
        fault_injector: FaultInjector | None = None,
    ) -> Path:
        self._committed_root.mkdir(parents=True, exist_ok=True)
        destination = self._committed_root / transaction.name
        if destination.exists():
            raise WalIntegrityError(
                f"{transaction.name}: committed transaction identity collision"
            )
        _replace_with_bounded_permission_retry(transaction, destination)
        _fsync_directory(self._transactions_root)
        _fsync_directory(self._committed_root)
        if fault_injector is not None:
            fault_injector("journal:committed:published")
        return destination

    def _recover_locked(self) -> dict[str, object]:
        self._transactions_root.mkdir(parents=True, exist_ok=True)
        completed: list[str] = []
        rolled_back: list[str] = []
        for transaction in self._pending_transactions():
            inspection = self._inspect_transaction(transaction)
            manifest = self._load_manifest(transaction)
            if manifest is None:
                self._archive_unprepared(transaction)
                rolled_back.append(transaction.name)
                continue
            if manifest["phase"] != "committed":
                self._apply(transaction, manifest)
                manifest = self._write_manifest(
                    transaction, manifest, "committed", None
                )
                self._inspect_artifacts(
                    transaction, manifest, require_after_images=True
                )
            elif inspection["required_action"] != "archive_committed":
                raise WalIntegrityError(
                    f"{transaction.name}: invalid committed recovery action"
                )
            self._archive_committed(transaction)
            completed.append(transaction.name)
        return {
            "schema_version": SCHEMA_VERSION,
            "completed": completed,
            "rolled_back": rolled_back,
            "valid": True,
        }

    def recover(self) -> dict[str, object]:
        """Recover every retained transaction under the process-bound WAL lock."""
        self.journal_root.mkdir(parents=True, exist_ok=True)
        with FileLock(self._lock_path, timeout_seconds=self.lock_timeout_seconds):
            return self._recover_locked()

    def inspect(self) -> dict[str, object]:
        """Inspect pending recovery without creating, locking, or changing paths."""
        before = self._inspection_fingerprint()
        transactions = [
            self._inspect_transaction(transaction)
            for transaction in self._pending_transactions()
        ]
        after = self._inspection_fingerprint()
        if before != after:
            raise WalIntegrityError("WAL changed during read-only inspection")
        would_complete = [
            str(item["transaction_id"])
            for item in transactions
            if item["required_action"] != "rollback"
        ]
        would_roll_back = [
            str(item["transaction_id"])
            for item in transactions
            if item["required_action"] == "rollback"
        ]
        return {
            "schema_version": SCHEMA_VERSION,
            "mode": "inspect",
            "valid": True,
            "requires_recovery": bool(transactions),
            "would_complete": would_complete,
            "would_roll_back": would_roll_back,
            "transactions": transactions,
            "inspection_sha256": after,
        }

    def commit(
        self,
        artifacts: Iterable[Artifact],
        *,
        transaction_id: str | None = None,
        fault_injector: FaultInjector | None = None,
    ) -> dict[str, object]:
        """Durably commit related JSON artifacts or leave a recoverable WAL."""
        items = self._normalize(artifacts)
        identifier = transaction_id or f"tx-{uuid.uuid4().hex}"
        if not _IDENTIFIER.fullmatch(identifier):
            raise ValueError("transaction_id must be a bounded identifier")
        self.journal_root.mkdir(parents=True, exist_ok=True)
        with FileLock(self._lock_path, timeout_seconds=self.lock_timeout_seconds):
            self._recover_locked()
            before_images = [
                self._read_existing(artifact, target)
                for artifact, target, _ in items
            ]
            if self.precommit_validator is not None:
                transitions = tuple(
                    JsonTransition(
                        artifact.role,
                        target,
                        self._transition_value(artifact, before)
                        if before is not None
                        else None,
                        self._transition_value(artifact, after),
                    )
                    for (artifact, target, after), before in zip(
                        items, before_images, strict=True
                    )
                )
                self.precommit_validator(transitions)
            transaction = self._transactions_root / identifier
            if (
                transaction.exists()
                or (self._rolled_back_root / identifier).exists()
                or (self._committed_root / identifier).exists()
            ):
                raise ValueError(f"transaction_id has already been used: {identifier}")
            transaction.mkdir(parents=False)
            _fsync_directory(self._transactions_root)
            records: list[dict[str, object]] = []
            intents: list[dict[str, str]] = []
            for index, ((artifact, target, after), before) in enumerate(
                zip(items, before_images, strict=True)
            ):
                suffix = (
                    ".json"
                    if isinstance(artifact, (JsonArtifact, JsonTextArtifact))
                    else ".txt"
                    if isinstance(artifact, TextArtifact)
                    else ".bin"
                )
                before_stage = f"before/{index:04d}{suffix}"
                after_stage = f"after/{index:04d}{suffix}"
                if before is not None:
                    _write_new(transaction / before_stage, before)
                    if fault_injector is not None:
                        fault_injector(f"journal:before:{index}")
                _write_new(transaction / after_stage, after)
                if fault_injector is not None:
                    fault_injector(f"journal:after:{index}")
                relative = target.relative_to(self.allowed_root).as_posix()
                after_sha = _sha_bytes(after)
                records.append(
                    {
                        "index": index,
                        "role": artifact.role,
                        "path": relative,
                        "before": {
                            "exists": before is not None,
                            "sha256": _sha_bytes(before)
                            if before is not None
                            else None,
                            "stage": before_stage if before is not None else None,
                        },
                        "after": {"sha256": after_sha, "stage": after_stage},
                    }
                )
                intents.append(
                    {"role": artifact.role, "path": relative, "sha256": after_sha}
                )
            manifest = self._write_manifest(
                transaction,
                {
                    "schema_version": SCHEMA_VERSION,
                    "transaction_id": identifier,
                    "recovery_policy": RECOVERY_POLICY,
                    "intent_sha256": _sha_bytes(_canonical(intents)),
                    "artifacts": records,
                },
                "prepared",
                fault_injector,
            )
            manifest = self._write_manifest(
                transaction, manifest, "applying", fault_injector
            )
            self._apply(transaction, manifest, fault_injector)
            manifest = self._write_manifest(
                transaction, manifest, "committed", fault_injector
            )
            committed = self._archive_committed(transaction, fault_injector)
            return {
                "schema_version": SCHEMA_VERSION,
                "transaction_id": identifier,
                "state": "committed",
                "artifact_count": len(records),
                "intent_sha256": manifest["intent_sha256"],
                "journal": committed.as_posix(),
            }

def _apply(
    self,
    transaction: Path,
    manifest: Mapping[str, object],
    fault_injector: FaultInjector | None = None,
) -> None:
    artifacts = manifest["artifacts"]
    assert isinstance(artifacts, list)
    seen: set[Path] = set()
    for index, raw_record in enumerate(artifacts):
        if not isinstance(raw_record, Mapping):
            raise WalIntegrityError(
                f"{transaction.name}: artifact record is not an object"
            )
        target, after, _before, after_sha, before_sha = self._artifact_paths(
            transaction, raw_record
        )
        if target in seen:
            raise WalIntegrityError(f"{transaction.name}: duplicate target")
        seen.add(target)
        current = target.read_bytes() if target.is_file() else None
        current_sha = _sha_bytes(current) if current is not None else None
        if current_sha == after_sha:
            continue
        if current_sha != before_sha:
            raise WalIntegrityError(
                f"{transaction.name}: target changed outside transaction: {target}"
            )
        _atomic_replace(
            target,
            after.read_bytes(),
            label=f"target:{index}",
            fault_injector=fault_injector,
            prepared_path=target.with_name(
                f".{target.name}.wal-{transaction.name}-{index}.prepared"
            ),
        )

def _inspection_fingerprint(self) -> str:
    if not self._transactions_root.exists():
        return "absent"
    records: list[dict[str, object]] = []
    total_bytes = 0
    paths = sorted(
        self._transactions_root.rglob("*"),
        key=lambda path: path.relative_to(self._transactions_root).as_posix(),
    )
    if len(paths) > MAX_INSPECTION_FILES:
        raise WalIntegrityError("WAL inspection file bound exceeded")
    for path in paths:
        relative = path.relative_to(self._transactions_root).as_posix()
        if path.is_symlink():
            raise WalIntegrityError(f"symlink in WAL authority: {relative}")
        if path.is_dir():
            records.append({"path": relative, "kind": "directory"})
            continue
        if not path.is_file():
            raise WalIntegrityError(f"non-regular WAL entry: {relative}")
        payload = path.read_bytes()
        total_bytes += len(payload)
        if total_bytes > MAX_INSPECTION_BYTES:
            raise WalIntegrityError("WAL inspection byte bound exceeded")
        records.append(
            {
                "path": relative,
                "kind": "file",
                "size": len(payload),
                "sha256": _sha_bytes(payload),
            }
        )
    return _sha_bytes(_canonical(records))

def _normalize(
    self, artifacts: Iterable[Artifact]
) -> tuple[tuple[Artifact, Path, bytes], ...]:
    items = tuple(artifacts)
    if not 1 <= len(items) <= MAX_ARTIFACTS:
        raise ValueError(f"transaction must contain 1..{MAX_ARTIFACTS} artifacts")
    normalized: list[tuple[Artifact, Path, bytes]] = []
    targets: set[Path] = set()
    total = 0
    for artifact in items:
        if artifact.role not in ARTIFACT_ROLES:
            raise ValueError(f"unsupported JSON artifact role: {artifact.role}")
        target = self._safe_target(artifact.path, label="artifact")
        if _inside(target, self.journal_root):
            raise ValueError("transaction targets cannot be inside the WAL journal")
        if target in targets:
            raise ValueError(f"duplicate transaction target: {target}")
        targets.add(target)
        if isinstance(artifact, JsonArtifact):
            try:
                rendered = _canonical(artifact.value)
            except (TypeError, ValueError) as error:
                raise ValueError(f"artifact is not strict JSON: {target}") from error
        elif isinstance(artifact, JsonTextArtifact):
            if not isinstance(artifact.value, str):
                raise ValueError(f"JSON text artifact is not a string: {target}")
            try:
                _strict_json_loads(artifact.value)
            except ValueError as error:
                raise ValueError(f"artifact is not strict JSON: {target}") from error
            rendered = artifact.value.encode("utf-8")
        elif isinstance(artifact, TextArtifact):
            if not isinstance(artifact.value, str):
                raise ValueError(f"text artifact is not a string: {target}")
            rendered = artifact.value.encode("utf-8")
        elif isinstance(artifact, BytesArtifact):
            if not isinstance(artifact.value, bytes):
                raise ValueError(f"byte artifact is not bytes: {target}")
            rendered = artifact.value
        else:
            raise TypeError(f"unsupported artifact type: {type(artifact).__name__}")
        total += len(rendered)
        if total > MAX_TRANSACTION_BYTES:
            raise ValueError("transaction payload exceeds the bounded byte limit")
        normalized.append((artifact, target, rendered))
    return tuple(normalized)

def _pending_transactions(self) -> tuple[Path, ...]:
    if not self._transactions_root.exists():
        return ()
    if not self._transactions_root.is_dir():
        raise WalIntegrityError("WAL transactions authority is not a directory")
    transactions = tuple(
        sorted(self._transactions_root.iterdir(), key=lambda path: path.name)
    )
    if len(transactions) > MAX_PENDING_TRANSACTIONS:
        raise WalIntegrityError("pending WAL transaction bound exceeded")
    for transaction in transactions:
        if (
            not transaction.is_dir()
            or transaction.is_symlink()
            or not _IDENTIFIER.fullmatch(transaction.name)
        ):
            raise WalIntegrityError(
                f"unexpected directory in WAL authority: {transaction.name}"
            )
    return transactions

def _read_existing(self, artifact: Artifact, path: Path) -> bytes | None:
    if not path.exists():
        return None
    if not path.is_file() or path.is_symlink():
        raise WalIntegrityError(f"target is not a regular file: {path}")
    raw = path.read_bytes()
    if isinstance(artifact, (JsonArtifact, JsonTextArtifact)):
        try:
            _strict_json_loads(raw.decode("utf-8"))
        except (UnicodeError, ValueError) as error:
            raise WalIntegrityError(
                f"existing JSON target is invalid: {path}"
            ) from error
    elif isinstance(artifact, TextArtifact):
        try:
            raw.decode("utf-8")
        except UnicodeError as error:
            raise WalIntegrityError(
                f"existing text target is not UTF-8: {path}"
            ) from error
    return raw

def _recover_locked(self) -> dict[str, object]:
    self._transactions_root.mkdir(parents=True, exist_ok=True)
    completed: list[str] = []
    rolled_back: list[str] = []
    for transaction in self._pending_transactions():
        inspection = self._inspect_transaction(transaction)
        manifest = self._load_manifest(transaction)
        if manifest is None:
            self._archive_unprepared(transaction)
            rolled_back.append(transaction.name)
            continue
        if manifest["phase"] != "committed":
            self._apply(transaction, manifest)
            manifest = self._write_manifest(
                transaction, manifest, "committed", None
            )
            self._inspect_artifacts(
                transaction, manifest, require_after_images=True
            )
        elif inspection["required_action"] != "archive_committed":
            raise WalIntegrityError(
                f"{transaction.name}: invalid committed recovery action"
            )
        self._archive_committed(transaction)
        completed.append(transaction.name)
    return {
        "schema_version": SCHEMA_VERSION,
        "completed": completed,
        "rolled_back": rolled_back,
        "valid": True,
    }

def commit(
    self,
    artifacts: Iterable[Artifact],
    *,
    transaction_id: str | None = None,
    fault_injector: FaultInjector | None = None,
) -> dict[str, object]:
    """Durably commit related JSON artifacts or leave a recoverable WAL."""
    items = self._normalize(artifacts)
    identifier = transaction_id or f"tx-{uuid.uuid4().hex}"
    if not _IDENTIFIER.fullmatch(identifier):
        raise ValueError("transaction_id must be a bounded identifier")
    self.journal_root.mkdir(parents=True, exist_ok=True)
    with FileLock(self._lock_path, timeout_seconds=self.lock_timeout_seconds):
        self._recover_locked()
        before_images = [
            self._read_existing(artifact, target)
            for artifact, target, _ in items
        ]
        if self.precommit_validator is not None:
            transitions = tuple(
                JsonTransition(
                    artifact.role,
                    target,
                    self._transition_value(artifact, before)
                    if before is not None
                    else None,
                    self._transition_value(artifact, after),
                )
                for (artifact, target, after), before in zip(
                    items, before_images, strict=True
                )
            )
            self.precommit_validator(transitions)
        transaction = self._transactions_root / identifier
        if (
            transaction.exists()
            or (self._rolled_back_root / identifier).exists()
            or (self._committed_root / identifier).exists()
        ):
            raise ValueError(f"transaction_id has already been used: {identifier}")
        transaction.mkdir(parents=False)
        _fsync_directory(self._transactions_root)
        records: list[dict[str, object]] = []
        intents: list[dict[str, str]] = []
        for index, ((artifact, target, after), before) in enumerate(
            zip(items, before_images, strict=True)
        ):
            suffix = (
                ".json"
                if isinstance(artifact, (JsonArtifact, JsonTextArtifact))
                else ".txt"
                if isinstance(artifact, TextArtifact)
                else ".bin"
            )
            before_stage = f"before/{index:04d}{suffix}"
            after_stage = f"after/{index:04d}{suffix}"
            if before is not None:
                _write_new(transaction / before_stage, before)
                if fault_injector is not None:
                    fault_injector(f"journal:before:{index}")
            _write_new(transaction / after_stage, after)
            if fault_injector is not None:
                fault_injector(f"journal:after:{index}")
            relative = target.relative_to(self.allowed_root).as_posix()
            after_sha = _sha_bytes(after)
            records.append(
                {
                    "index": index,
                    "role": artifact.role,
                    "path": relative,
                    "before": {
                        "exists": before is not None,
                        "sha256": _sha_bytes(before)
                        if before is not None
                        else None,
                        "stage": before_stage if before is not None else None,
                    },
                    "after": {"sha256": after_sha, "stage": after_stage},
                }
            )
            intents.append(
                {"role": artifact.role, "path": relative, "sha256": after_sha}
            )
        manifest = self._write_manifest(
            transaction,
            {
                "schema_version": SCHEMA_VERSION,
                "transaction_id": identifier,
                "recovery_policy": RECOVERY_POLICY,
                "intent_sha256": _sha_bytes(_canonical(intents)),
                "artifacts": records,
            },
            "prepared",
            fault_injector,
        )
        manifest = self._write_manifest(
            transaction, manifest, "applying", fault_injector
        )
        self._apply(transaction, manifest, fault_injector)
        manifest = self._write_manifest(
            transaction, manifest, "committed", fault_injector
        )
        committed = self._archive_committed(transaction, fault_injector)
        return {
            "schema_version": SCHEMA_VERSION,
            "transaction_id": identifier,
            "state": "committed",
            "artifact_count": len(records),
            "intent_sha256": manifest["intent_sha256"],
            "journal": committed.as_posix(),
        }

def _atomic_replace(
    path: Path,
    payload: bytes,
    *,
    label: str,
    fault_injector: FaultInjector | None,
    prepared_path: Path | None = None,
) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = prepared_path or path.with_name(
        f".{path.name}.{uuid.uuid4().hex}.prepared"
    )
    if temporary.exists():
        if not temporary.is_file() or temporary.read_bytes() != payload:
            raise WalIntegrityError(f"conflicting prepared image: {temporary}")
    else:
        _write_new(temporary, payload)
        if fault_injector is not None:
            fault_injector(f"{label}:staged")
    _replace_with_bounded_permission_retry(temporary, path)
    _fsync_directory(path.parent)
    if fault_injector is not None:
        fault_injector(f"{label}:published")

"""Persistent bounded admission and state-bus owner for expensive Python work.

The service has no timer, daemon, or background thread. Stable state is quiet:
work happens only for an explicit request, a changed input fingerprint, or an
expired informational cache. Cross-process lock directories provide bounded
single-flight and pool admission without stealing Codex host authority.
"""

from __future__ import annotations

from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path
import tempfile
import time
from typing import Any, Callable, Sequence, TypeVar
from uuid import uuid4


T = TypeVar("T")
SCHEMA = "px.runtime-work-plane/1.0"
POOL_LIMITS = {"interactive": 2, "light": 2, "heavy": 1, "validation": 1}
PRODUCER_CATALOG = (
    {"id": "dashboard.snapshot", "class": "dynamic-read", "admission": "runtime-work-plane"},
    {"id": "dashboard.hardware", "class": "sensor", "admission": "runtime-work-plane"},
    {"id": "dashboard.host-startup", "class": "host-log-sensor", "admission": "runtime-work-plane"},
    {"id": "execution-placement", "class": "decision", "admission": "runtime-work-plane"},
    {"id": "project-map.build", "class": "filesystem-heavy", "admission": "runtime-work-plane"},
    {"id": "test-index.build", "class": "filesystem-heavy", "admission": "runtime-work-plane"},
    {"id": "test-group.run", "class": "validation", "admission": "bounded-test-owner"},
    {"id": "hardware.cli", "class": "sensor", "admission": "runtime-work-plane"},
    {"id": "workspace.discovery", "class": "filesystem-heavy", "admission": "runtime-work-plane"},
)


class WorkAdmissionTimeout(RuntimeError):
    pass


def content_hash(value: object) -> str:
    return hashlib.sha256(
        json.dumps(
            value,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
            allow_nan=False,
        ).encode("utf-8")
    ).hexdigest()


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _atomic_json(path: Path, payload: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    prepared = path.with_name(f".{path.name}.{uuid4().hex}.prepared")
    prepared.write_text(
        json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )
    os.replace(prepared, path)


class RuntimeWorkPlane:
    def __init__(self, root: Path) -> None:
        self.root = root.resolve()
        owned_plane = os.environ.get("PX_OWNED_RUNTIME_WORK_PLANE_ROOT", "").strip()
        if owned_plane:
            if os.environ.get("PX_OWNED_VSCODE_HOST") != "1":
                raise ValueError(
                    "runtime work-plane override requires an owned VS Code host"
                )
            candidate = Path(owned_plane).resolve()
            temporary = Path(tempfile.gettempdir()).resolve()
            if not candidate.is_relative_to(temporary):
                raise ValueError(
                    "owned runtime work-plane override must remain under the OS temporary root"
                )
            self.plane = candidate
        else:
            self.plane = self.root / ".engineering-bootstrap" / "runtime-core"
        self.locks = self.plane / "locks"
        self.pools = self.plane / "pools"
        self.cache = self.plane / "cache"
        self.operations = self.plane / "operations"
        self.state_path = self.plane / "state.json"

    def _empty_state(self) -> dict[str, Any]:
        return {
            "schema_version": SCHEMA,
            "bus_revision": 0,
            "domain_revisions": {},
            "active": {},
            "counters": {
                "starts": 0,
                "joins": 0,
                "waits": 0,
                "failures": 0,
                "duplicate_executions_avoided": 0,
            },
            "last_delta": None,
            "operations": [],
        }

    def _read_state(self) -> dict[str, Any]:
        try:
            state = json.loads(self.state_path.read_text(encoding="utf-8"))
            return state if state.get("schema_version") == SCHEMA else self._empty_state()
        except (OSError, json.JSONDecodeError, AttributeError):
            return self._empty_state()

    @staticmethod
    def _read_cache(path: Path) -> dict[str, Any] | None:
        """Reject malformed or incomplete cache entries and let work rebuild them."""
        try:
            cached = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError, UnicodeError):
            return None
        if not isinstance(cached, dict) or "result" not in cached:
            return None
        try:
            float(cached.get("created_epoch", 0))
        except (TypeError, ValueError):
            return None
        return cached

    def _acquire_directory(self, path: Path, timeout_seconds: float) -> float:
        started = time.monotonic()
        path.parent.mkdir(parents=True, exist_ok=True)
        while True:
            if self._claim_directory(path):
                return time.monotonic() - started
            self._reconcile_orphan(path)
            if time.monotonic() - started >= timeout_seconds:
                raise WorkAdmissionTimeout(f"bounded admission timed out: {path.name}")
            time.sleep(0.025)

    def _claim_directory(self, path: Path) -> bool:
        try:
            path.mkdir()
            _atomic_json(
                path / "owner.json",
                {"pid": os.getpid(), "created_epoch": time.time(), "created_at": _now()},
            )
            return True
        except FileExistsError:
            return False

    @staticmethod
    def _pid_alive(pid: int) -> bool:
        if pid <= 0:
            return False
        if pid == os.getpid():
            return True
        if os.name == "nt":
            try:
                import ctypes

                process = ctypes.windll.kernel32.OpenProcess(0x1000, False, pid)
                if not process:
                    return False
                exit_code = ctypes.c_ulong()
                alive = bool(
                    ctypes.windll.kernel32.GetExitCodeProcess(
                        process, ctypes.byref(exit_code)
                    )
                    and exit_code.value == 259
                )
                ctypes.windll.kernel32.CloseHandle(process)
                return alive
            except (AttributeError, OSError):
                return False
        try:
            os.kill(pid, 0)
            return True
        except OSError:
            return False

    def _reconcile_orphan(self, path: Path) -> bool:
        try:
            owner = json.loads((path / "owner.json").read_text(encoding="utf-8"))
            pid = int(owner.get("pid", 0))
        except (OSError, ValueError, TypeError, json.JSONDecodeError):
            return False
        if self._pid_alive(pid):
            return False
        custody = self.plane / "orphaned-locks"
        custody.mkdir(parents=True, exist_ok=True)
        try:
            os.replace(path, custody / f"{path.name}-{uuid4().hex}")
            return True
        except OSError:
            return False

    @staticmethod
    def _release_directory(path: Path) -> None:
        owner = path / "owner.json"
        if owner.is_file():
            for _ in range(10):
                try:
                    owner.unlink()
                    break
                except PermissionError:
                    time.sleep(0.05)
            else:
                raise
        for _ in range(12):
            try:
                path.rmdir()
                return
            except PermissionError:
                time.sleep(0.05)
            except OSError:
                if not path.is_dir():
                    return
                # Keep retrying only when another process briefly blocks release.
        raise RuntimeError(f"unable to release directory lock: {path}")

    def _update_state(self, mutate: Callable[[dict[str, Any]], None]) -> None:
        lock = self.locks / "state"
        self._acquire_directory(lock, 2.0)
        try:
            state = self._read_state()
            mutate(state)
            _atomic_json(self.state_path, state)
        finally:
            self._release_directory(lock)

    def _pool_token(self, lane: str, timeout_seconds: float) -> tuple[Path, float]:
        if lane not in POOL_LIMITS:
            raise ValueError(f"unknown runtime work lane: {lane}")
        started = time.monotonic()
        contended = False
        directory = self.pools / lane
        directory.mkdir(parents=True, exist_ok=True)
        while True:
            for index in range(POOL_LIMITS[lane]):
                token = directory / str(index)
                if self._claim_directory(token):
                    return token, time.monotonic() - started if contended else 0.0
                self._reconcile_orphan(token)
            contended = True
            if time.monotonic() - started >= timeout_seconds:
                raise WorkAdmissionTimeout(f"{lane} pool is saturated")
            time.sleep(0.025)

    def execute(
        self,
        operation: str,
        producer: Callable[[], T],
        *,
        reason: str,
        input_fingerprint: object,
        domains: Sequence[str],
        lane: str = "light",
        cache_seconds: float = 0.0,
        timeout_seconds: float = 10.0,
        authoritative: bool = False,
    ) -> dict[str, Any]:
        if not operation.strip() or not reason.strip() or not domains:
            raise ValueError("operation, reason, and affected domains are required")
        if cache_seconds < 0 or timeout_seconds <= 0:
            raise ValueError("cache and timeout bounds are invalid")
        input_sha = content_hash(input_fingerprint)
        key = hashlib.sha256(operation.encode("utf-8")).hexdigest()[:24]
        cache_path = self.cache / f"{key}.json"
        if cache_seconds and not authoritative and cache_path.is_file():
            cached = self._read_cache(cache_path)
        else:
            cached = None
        if cached is not None:
            age = time.time() - float(cached.get("created_epoch", 0))
            if cached.get("input_sha256") == input_sha and 0 <= age < cache_seconds:
                return {
                    "result": cached["result"],
                    "admission": {
                        "decision": "cache_hit",
                        "operation": operation,
                        "reason": reason,
                        "input_sha256": input_sha,
                        "cache_age_seconds": round(age, 6),
                        "authority": "informational-cache-only",
                    },
                }

        operation_lock = self.locks / f"operation-{key}"
        acquired = False
        wait_started = time.monotonic()
        join_started_epoch = time.time()
        while not acquired:
            try:
                operation_lock.parent.mkdir(parents=True, exist_ok=True)
                acquired = self._claim_directory(operation_lock)
            except OSError:
                acquired = False
            if not acquired:
                self._reconcile_orphan(operation_lock)
                if cache_path.is_file():
                    cached = self._read_cache(cache_path)
                    if cached is not None and (
                        cached.get("input_sha256") == input_sha
                        and float(cached.get("created_epoch", 0)) >= join_started_epoch
                    ):
                        waited = time.monotonic() - wait_started
                        self._record_join(operation, reason, waited)
                        return {
                            "result": cached["result"],
                            "admission": {
                                "decision": "joined",
                                "operation": operation,
                                "reason": reason,
                                "input_sha256": input_sha,
                                "wait_seconds": round(waited, 6),
                            },
                        }
                if time.monotonic() - wait_started >= timeout_seconds:
                    raise WorkAdmissionTimeout(
                        f"single-flight wait timed out for {operation}"
                    )
                time.sleep(0.025)

        # The producer can publish its cache and release the operation lock
        # between this consumer's failed claim and its next claim attempt. In
        # that handoff window the consumer owns the lock, but it is still a
        # joiner for the just-published identical input. Recheck after
        # acquisition so lock handoff never becomes a duplicate execution.
        cached = self._read_cache(cache_path) if cache_path.is_file() else None
        if cached is not None and (
            cached.get("input_sha256") == input_sha
            and float(cached.get("created_epoch", 0)) >= join_started_epoch
        ):
            waited = time.monotonic() - wait_started
            try:
                self._record_join(operation, reason, waited)
            finally:
                if operation_lock.is_dir():
                    self._release_directory(operation_lock)
            return {
                "result": cached["result"],
                "admission": {
                    "decision": "joined",
                    "operation": operation,
                    "reason": reason,
                    "input_sha256": input_sha,
                    "wait_seconds": round(waited, 6),
                },
            }

        token: Path | None = None
        operation_id = f"{key}-{uuid4().hex}"
        started = time.perf_counter()
        try:
            token, pool_wait = self._pool_token(lane, timeout_seconds)
            self._record_start(
                operation_id,
                operation,
                reason,
                lane,
                input_sha,
                domains,
                pool_wait,
                authoritative,
            )
            result = producer()
            payload = {
                "schema_version": "px.runtime-work-result/1.0",
                "operation": operation,
                "operation_id": operation_id,
                "input_sha256": input_sha,
                "created_epoch": time.time(),
                "created_at": _now(),
                "result": result,
                "result_sha256": content_hash(result),
            }
            _atomic_json(cache_path, payload)
            duration = time.perf_counter() - started
            self._record_finish(
                operation_id, operation, reason, domains, duration, payload["result_sha256"]
            )
            return {
                "result": result,
                "admission": {
                    "decision": "ran",
                    "operation": operation,
                    "operation_id": operation_id,
                    "reason": reason,
                    "input_sha256": input_sha,
                    "duration_seconds": round(duration, 6),
                    "pool_wait_seconds": round(pool_wait, 6),
                    "lane": lane,
                    "authoritative": authoritative,
                },
            }
        except Exception as error:
            self._record_failure(operation_id, operation, reason, error)
            raise
        finally:
            if token is not None and token.is_dir():
                self._release_directory(token)
            if operation_lock.is_dir():
                self._release_directory(operation_lock)

    def _record_join(self, operation: str, reason: str, waited: float) -> None:
        def mutate(state: dict[str, Any]) -> None:
            counters = state["counters"]
            counters["joins"] += 1
            counters["waits"] += 1
            counters["duplicate_executions_avoided"] += 1
            state["operations"] = (
                state["operations"]
                + [{"operation": operation, "outcome": "joined", "reason": reason, "wait_seconds": round(waited, 6), "at": _now()}]
            )[-50:]

        self._update_state(mutate)

    def _record_start(
        self,
        operation_id: str,
        operation: str,
        reason: str,
        lane: str,
        input_sha: str,
        domains: Sequence[str],
        waited: float,
        authoritative: bool,
    ) -> None:
        def mutate(state: dict[str, Any]) -> None:
            state["active"] = {
                key: value
                for key, value in state["active"].items()
                if self._pid_alive(int(value.get("pid", 0)))
            }
            state["counters"]["starts"] += 1
            if waited >= 0.001:
                state["counters"]["waits"] += 1
            state["active"][operation_id] = {
                "operation": operation,
                "reason": reason,
                "lane": lane,
                "input_sha256": input_sha,
                "domains": sorted(set(domains)),
                "started_at": _now(),
                "authoritative": authoritative,
                "pid": os.getpid(),
            }

        self._update_state(mutate)

    def _record_finish(
        self,
        operation_id: str,
        operation: str,
        reason: str,
        domains: Sequence[str],
        duration: float,
        result_sha: str,
    ) -> None:
        def mutate(state: dict[str, Any]) -> None:
            state["active"].pop(operation_id, None)
            state["bus_revision"] += 1
            revisions = state["domain_revisions"]
            changed = {}
            for domain in sorted(set(domains)):
                revisions[domain] = int(revisions.get(domain, 0)) + 1
                changed[domain] = revisions[domain]
            event = {
                "operation": operation,
                "operation_id": operation_id,
                "outcome": "published",
                "reason": reason,
                "duration_seconds": round(duration, 6),
                "result_sha256": result_sha,
                "bus_revision": state["bus_revision"],
                "changed": changed,
                "at": _now(),
            }
            state["last_delta"] = event
            state["operations"] = (state["operations"] + [event])[-50:]

        self._update_state(mutate)

    def _record_failure(
        self, operation_id: str, operation: str, reason: str, error: Exception
    ) -> None:
        def mutate(state: dict[str, Any]) -> None:
            state["active"].pop(operation_id, None)
            state["counters"]["failures"] += 1
            state["operations"] = (
                state["operations"]
                + [{"operation": operation, "operation_id": operation_id, "outcome": "failed", "reason": reason, "error": type(error).__name__, "at": _now()}]
            )[-50:]

        self._update_state(mutate)

    def snapshot(self) -> dict[str, Any]:
        state = self._read_state()
        active = {
            key: value
            for key, value in state.get("active", {}).items()
            if self._pid_alive(int(value.get("pid", 0)))
        }
        orphaned_active = sorted(set(state.get("active", {})) - set(active))
        connected = sum(row["admission"] == "runtime-work-plane" for row in PRODUCER_CATALOG)
        separately_bounded = sum(
            row["admission"] == "bounded-test-owner" for row in PRODUCER_CATALOG
        )
        legacy_direct = sum(row["admission"] == "legacy-direct" for row in PRODUCER_CATALOG)
        return {
            **state,
            "active": active,
            "orphaned_active": orphaned_active,
            "quiet_model": "no timers or background workers; explicit demand only",
            "pool_limits": dict(POOL_LIMITS),
            "producer_trace": list(PRODUCER_CATALOG),
            "producer_trace_summary": {
                "total": len(PRODUCER_CATALOG),
                "runtime_work_plane": connected,
                "separately_bounded": separately_bounded,
                "legacy_direct": legacy_direct,
                "owned_total": connected + separately_bounded,
                "complete": legacy_direct == 0,
            },
            "observed_at": _now(),
        }

@staticmethod
def _read_cache(path: Path) -> dict[str, Any] | None:
    """Reject malformed or incomplete cache entries and let work rebuild them."""
    try:
        cached = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError, UnicodeError):
        return None
    if not isinstance(cached, dict) or "result" not in cached:
        return None
    try:
        float(cached.get("created_epoch", 0))
    except (TypeError, ValueError):
        return None
    return cached

def _acquire_directory(self, path: Path, timeout_seconds: float) -> float:
    started = time.monotonic()
    path.parent.mkdir(parents=True, exist_ok=True)
    while True:
        if self._claim_directory(path):
            return time.monotonic() - started
        self._reconcile_orphan(path)
        if time.monotonic() - started >= timeout_seconds:
            raise WorkAdmissionTimeout(f"bounded admission timed out: {path.name}")
        time.sleep(0.025)

def _pool_token(self, lane: str, timeout_seconds: float) -> tuple[Path, float]:
    if lane not in POOL_LIMITS:
        raise ValueError(f"unknown runtime work lane: {lane}")
    started = time.monotonic()
    contended = False
    directory = self.pools / lane
    directory.mkdir(parents=True, exist_ok=True)
    while True:
        for index in range(POOL_LIMITS[lane]):
            token = directory / str(index)
            if self._claim_directory(token):
                return token, time.monotonic() - started if contended else 0.0
            self._reconcile_orphan(token)
        contended = True
        if time.monotonic() - started >= timeout_seconds:
            raise WorkAdmissionTimeout(f"{lane} pool is saturated")
        time.sleep(0.025)

