def audit(
    root: Path,
    *,
    ignored: tuple[Path, ...] = (),
    excluded_names: frozenset[str] = frozenset(),
) -> dict[str, object]:
    resolved = root.resolve()
    ignored_paths = {path.resolve() for path in ignored}
    identifier_hits: list[dict[str, object]] = []
    legacy_placeholder_hits: list[dict[str, object]] = []
    host_home_hits: list[dict[str, object]] = []
    host_home_exemptions: list[dict[str, object]] = []
    zip_paths: list[str] = []
    files_scanned = 0
    bytes_scanned = 0
    errors: list[str] = []
    for path in sorted(
        resolved.rglob("*"), key=lambda item: item.as_posix().casefold()
    ):
        relative_path = path.relative_to(resolved)
        relative_name = relative_path.as_posix()
        if any(
            part in EXCLUDED_DIRECTORIES or part in excluded_names
            for part in relative_path.parts
        ) or (
            is_external_environment_relative(relative_path)
            and relative_name not in IMMUTABLE_PROVENANCE_PATHS
        ):
            continue
        if not path.is_file() or path.resolve() in ignored_paths:
            continue
        relative = relative_name
        files_scanned += 1
        if path.suffix.casefold() == ".zip":
            zip_paths.append(relative)
        path_match = PATTERN.search(relative.encode("utf-8", errors="replace"))
        if path_match:
            identifier_hits.append(
                {"path": relative, "location": "path", "offset": path_match.start()}
            )
        legacy_path_match = LEGACY_PATTERN.search(
            relative.encode("utf-8", errors="replace")
        )
        if legacy_path_match:
            legacy_placeholder_hits.append(
                {
                    "path": relative,
                    "location": "path",
                    "offset": legacy_path_match.start(),
                }
            )
        host_path_match = HOST_HOME_PATTERN.search(
            relative.encode("utf-8", errors="replace")
        )
        if host_path_match:
            host_home_hits.append(
                {"path": relative, "location": "path", "offset": host_path_match.start()}
            )
        try:
            if not _is_admitted_text(path):
                bytes_scanned += path.stat().st_size
                continue
            overlap = b""
            offset = 0
            with path.open("rb") as handle:
                chunk = handle.read(1024 * 1024)
                while chunk:
                    following = handle.read(1024 * 1024)
                    bytes_scanned += len(chunk)
                    buffer = overlap + chunk
                    safe_end = (
                        len(buffer) if not following else max(0, len(buffer) - 128)
                    )
                    buffer_start = offset - len(overlap)
                    for match in PATTERN.finditer(buffer):
                        absolute = buffer_start + match.start()
                        if match.start() < safe_end and absolute >= 0:
                            identifier_hits.append(
                                {
                                    "path": relative,
                                    "location": "content",
                                    "offset": absolute,
                                }
                            )
                    for match in LEGACY_PATTERN.finditer(buffer):
                        absolute = buffer_start + match.start()
                        if match.start() < safe_end and absolute >= 0:
                            legacy_placeholder_hits.append(
                                {
                                    "path": relative,
                                    "location": "content",
                                    "offset": absolute,
                                }
                            )
                    for match in HOST_HOME_PATTERN.finditer(buffer):
                        absolute = buffer_start + match.start()
                        if match.start() < safe_end and absolute >= 0:
                            classification = None
                            if relative in IMMUTABLE_PROVENANCE_PATHS:
                                classification = "immutable-append-only-provenance"
                            elif match.group(0) in TYPED_CONTAINER_HOME_PATHS.get(relative, set()):
                                classification = "declared-container-runtime-home"
                            target = (
                                host_home_exemptions
                                if classification is not None
                                else host_home_hits
                            )
                            record = {
                                "path": relative,
                                "location": "content",
                                "offset": absolute,
                            }
                            if classification is not None:
                                record["classification"] = classification
                            target.append(record)
                    overlap = buffer[safe_end:]
                    offset += len(chunk)
                    chunk = following
        except OSError as error:
            errors.append(f"{relative}: {type(error).__name__}: {error}")
    identifier_hits.sort(
        key=lambda item: (str(item["path"]), str(item["location"]), int(item["offset"]))
    )
    legacy_placeholder_hits.sort(
        key=lambda item: (str(item["path"]), str(item["location"]), int(item["offset"]))
    )
    host_home_hits.sort(
        key=lambda item: (str(item["path"]), str(item["location"]), int(item["offset"]))
    )
    host_home_exemptions.sort(
        key=lambda item: (str(item["path"]), str(item["location"]), int(item["offset"]))
    )

def _forbidden(relative: str) -> bool:
    parts = PurePosixPath(relative).parts
    if not parts:
        return False
    top = parts[0]
    return (
        top in {".tmp", ".VSCodeCounter", "evidence"}
        or top.startswith(".tmp_")
        or top.startswith("tmp_")
        or parts[:2]
        in {
            (".px", "global-skill-isolation"),
            (".px", "preserved-extension-installations"),
            (".px", "preserved-skills"),
        }
        or parts[:2] == (".engineering-bootstrap", "coordination")
    )


def _inspect_archive(
    archive_path: Path, *, revision: str, worktree_attributes: bool
) -> dict[str, Any]:
    members: list[str] = []
    forbidden: list[str] = []
    total_bytes = 0
    if archive_path.stat().st_size > MAX_SOURCE_ARCHIVE_BYTES:
        return {
            "schema_version": "px.source-archive-audit/1.0",
            "valid": False,
            "revision": revision,
            "errors": ["archive exceeds the 256 MiB physical source budget"],
        }
    try:
        with tarfile.open(archive_path, mode="r:") as archive:
            for member in archive:
                if not member.isfile():
                    continue
                members.append(member.name)
                total_bytes += member.size
                if _forbidden(member.name):
                    forbidden.append(member.name)
    except tarfile.TarError as error:
        return {
            "schema_version": "px.source-archive-audit/1.0",
            "valid": False,
            "revision": revision,
            "errors": [f"invalid Git archive: {type(error).__name__}"],
        }
    errors = []
    if forbidden:
        errors.append(f"archive contains {len(forbidden)} host/evidence custody members")
    if total_bytes > MAX_SOURCE_ARCHIVE_BYTES:
        errors.append("archive exceeds the 256 MiB uncompressed source budget")
    required = {
        "pyproject.toml",
        "runtime/cli.py",
        "registry/operational_gap_ledger.jsonl",
        ".engineering-bootstrap/project-registry.json",
    }
    missing = sorted(required - set(members))
    if missing:
        errors.append("archive is missing required bootstrap authority")
    return {
        "schema_version": "px.source-archive-audit/1.0",
        "valid": not errors,
        "revision": revision,
        "worktree_attributes": worktree_attributes,
        "file_count": len(members),
        "uncompressed_bytes": total_bytes,
        "maximum_uncompressed_bytes": MAX_SOURCE_ARCHIVE_BYTES,
        "forbidden_members": forbidden,
        "missing_required_members": missing,
        "errors": errors,
    }

