KINDS = ("certification", "task", "tool_contract")


def reconcile(root: Path, *, check: bool) -> dict[str, object]:
    root = root.resolve()
    owner_root = root / "templates/declared_suite/authoritative-pack"
    stale = []
    records = []
    for kind in KINDS:
        source = owner_root / f"{kind}.json"
        expected = source.read_bytes()
        digest = hashlib.sha256(expected).hexdigest()
        for pack in range(1, 8):
            target = root / "templates/declared_suite" / f"pack-{pack:02d}-{kind}.json"
            if not target.is_file() or target.read_bytes() != expected:
                stale.append(target.relative_to(root).as_posix())
                if not check:
                    target.write_bytes(expected)
        records.append(
            {
                "kind": kind,
                "owner": source.relative_to(root).as_posix(),
                "sha256": digest,
                "projections": 7,
            }
        )
    return {
        "schema_version": "1.0",
        "valid": not stale if check else True,
        "records": records,
        "projection_count": 21,
        "stale": stale,
        "check": check,
    }

