def _dashboard_navigation_surfaces(source: str) -> list[str]:
    surfaces: list[str] = []
    for declaration in ("visibleSurfaces", "advancedSurfaces"):
        match = re.search(rf"const\s+{declaration}\s*=\s*\[(.*?)\];", source, re.DOTALL)
        if match is None:
            raise ValueError(f"dashboard controller is missing {declaration}")
        surfaces.extend(re.findall(r"\[\s*['\"]([^'\"]+)['\"]\s*,", match.group(1)))
    if not surfaces or len(surfaces) != len(set(surfaces)):
        raise ValueError("dashboard navigation surface declarations are empty or duplicated")
    return surfaces

_SOURCE_TERMS = ("r" + "ie", "re" + "my", "rh" + "eem")
TERMS = re.compile(rf"(?i)(?<![A-Za-z])({'|'.join(_SOURCE_TERMS)})(?![A-Za-z])")


def redact(value: str) -> str:
    replacements = dict(
        zip(
            _SOURCE_TERMS,
            (
                "intelligent_integrations_and_engines",
                "governed_retrieval_system_with_deterministic_rails",
                "enterprise",
            ),
        )
    )
    return TERMS.sub(lambda match: replacements[match.group(1).lower()], value)


def classify(path: Path, relative: Path, size: int) -> tuple[str, str]:
    parts = {part.casefold() for part in relative.parts}
    name = path.name.casefold()
    if parts & EXCLUDED_SEGMENTS:
        return "generated_or_dependency", "exclude_from_runtime"
    if any(
        token in parts
        for token in {"security", "governance", "policy", "certification", "evidence"}
    ):
        return "governance_or_assurance", "review_for_pattern"
    if (
        any(token in parts for token in {"skill_staging", "skills", ".codex"})
        or "skill" in name
    ):
        return "skill_or_registry", "admission_required"
    if any(token in parts for token in {"tests", "test-results"}) or name.startswith(
        "test_"
    ):
        return "test_or_validation", "review_for_pattern"
    if any(token in parts for token in {"deploy", "infra", "monitoring", "ci"}):
        return "operations", "review_for_pattern"
    if any(
        token in parts
        for token in {"docs", "references", "temp_references", "knowledge", "research"}
    ):
        return "knowledge_or_reference", "reference_only"
    if path.suffix.casefold() in {
        ".zip",
        ".tar",
        ".gz",
        ".rar",
        ".7z",
        ".png",
        ".jpg",
        ".jpeg",
        ".pdf",
        ".db",
        ".sqlite",
        ".pyc",
    }:
        return "binary_or_archive", "exclude_from_runtime"
    if size > 5 * 1024 * 1024:
        return "large_artifact", "reference_only"
    return "implementation_or_misc", "triage_required"

def classify(item: dict, duplicate_ids: set[str]) -> tuple[str, float, str]:
    if item["id"] in duplicate_ids:
        return "duplicate", 1.0, "canonical_selection_required"
    path = item["path"].casefold()
    headings = " ".join(item.get("structure", {}).get("headings", [])).casefold()
    value = f"{path} {headings}"
    suffix = item.get("extension", "")
    if suffix in {".exe", ".dll", ".so", ".dylib", ".bin"}:
        return "unsafe_untrusted", 0.98, "quarantine"

