def _candidate_records(stage: Path) -> list[dict[str, object]]:
    records = []
    for path in sorted(
        stage.rglob("*"), key=lambda item: item.relative_to(stage).as_posix().casefold()
    ):
        if (
            not path.is_file()
            or path.is_symlink()
            or path.name == "AUDIT_EXPORT_MANIFEST.json"
        ):
            continue
        data = path.read_bytes()
        records.append(
            {
