def tree_hash(records: list[dict[str, object]]) -> str:
    payload = "\n".join(
        f"{item['path']}\0{item['sha256']}\0{item['bytes']}\0{item['mtime_ns']}"
        for item in records
    )
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


