def canonical_json(value: object) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def read_jsonl(path: Path) -> Iterator[dict]:
    with path.open(encoding="utf-8") as handle:
        for line_number, line in enumerate(handle, 1):
            if not line.strip():
                continue
            try:
                yield json.loads(line)
            except json.JSONDecodeError as error:
                raise ValueError(
                    f"{path}:{line_number}: invalid JSONL: {error}"
                ) from error


def write_jsonl(path: Path, records: Iterable[dict]) -> tuple[int, str]:
    path.parent.mkdir(parents=True, exist_ok=True)
    digest = hashlib.sha256()
    count = 0
    with path.open("w", encoding="utf-8", newline="\n") as handle:
        for record in records:
            line = canonical_json(record) + "\n"
            handle.write(line)
            digest.update(line.encode("utf-8"))
            count += 1
    return count, digest.hexdigest()

def simhash64(tokens: list[str]) -> str | None:
    if not tokens:
        return None
    weights = [0] * 64
    for token, count in Counter(tokens).items():
        value = int.from_bytes(
            hashlib.sha256(token.encode("utf-8")).digest()[:8], "big"
        )
        for bit in range(64):
            weights[bit] += count if value & (1 << bit) else -count
    result = sum(1 << bit for bit, weight in enumerate(weights) if weight >= 0)
    return f"{result:016x}"


def hamming_hex(left: str, right: str) -> int:
    return (int(left, 16) ^ int(right, 16)).bit_count()

def _entry_snapshot(root: Path) -> list[dict[str, Any]]:
    """Hash a tree without following links; retain empty directories."""
    if not _lexists(root):
        return []
    records: list[dict[str, Any]] = []

    def add(path: Path) -> None:
        relative = "." if path == root else path.relative_to(root).as_posix()
        if path.is_symlink():
            target = os.readlink(path)
            records.append(
                {
                    "path": relative,
                    "kind": "symlink",
                    "target": target,
                    "sha256": hashlib.sha256(target.encode("utf-8")).hexdigest(),
                }
            )
        elif path.is_file():
            records.append(
                {
                    "path": relative,
                    "kind": "file",
                    "bytes": path.stat().st_size,
                    "sha256": _sha256(path),
                }
            )
        elif path.is_dir():
            records.append({"path": relative, "kind": "directory"})
        else:
            records.append({"path": relative, "kind": "other"})

    add(root)
    if root.is_dir() and not root.is_symlink():
        for current, directories, files in os.walk(root, followlinks=False):
            current_path = Path(current)
            linked_directories: list[str] = []
            for name in directories:
                child = current_path / name
                if child.is_symlink():
                    add(child)
                    linked_directories.append(name)
                else:
                    add(child)
            directories[:] = [name for name in directories if name not in linked_directories]
            for name in files:
                add(current_path / name)
    return sorted(records, key=lambda item: (str(item["path"]).casefold(), item["kind"]))

def _is_preserved_evidence_reparse(root: Path, path: Path) -> bool:
    """Return true only for reparse points confined to declared evidence custody."""
    return any(_inside(path, root / relative) for relative in PRESERVED_REPARSE_ROOTS)

def _tree_evidence(root: Path) -> dict[str, Any]:
    entries = _entry_snapshot(root)
    encoded = json.dumps(entries, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return {
        "tree_sha256": hashlib.sha256(encoded).hexdigest(),
        "entry_count": len(entries),
        "file_count": sum(item["kind"] == "file" for item in entries),
        "directory_count": sum(item["kind"] == "directory" for item in entries),
        "reparse_point_count": sum(item["kind"] == "symlink" for item in entries),
        "total_file_bytes": sum(int(item.get("bytes", 0)) for item in entries),
        "reparse_points": [
            {"path": item["path"], "target": item["target"], "sha256": item["sha256"]}
            for item in entries
            if item["kind"] == "symlink"
        ],
    }

