def verify(self, step: str) -> None:
    if step in {"installed_operational", "card_reconcile", "preflight", "finalize"}:
        validate_installed_summary(self.config)
    release = _release(self.config)
    repair = _repair(self.config)
    phase = repair.get("phase")

    def phase_at_least(expected: str) -> bool:
        return (
            phase in PHASE_ORDER
            and PHASE_ORDER.index(str(phase)) >= PHASE_ORDER.index(expected)
        )

    if step == "archive_clear":
        valid = (
            release.get("campaign_id") == self.config.candidate_id
            and (
                (
                    release.get("state") == "cleared"
                    and
                    release.get("apply_count") == 0
                    and release.get("active_claim") is None
                    and all(
                        row.get("status") == "pending"
                        for row in release.get("stages", {}).values()
                        if isinstance(row, dict)
                    )
                )
                or (
                    release.get("state") in {"active", "certified"}
                    and release.get("apply_count") == 1
                )
            )
        )
    elif step == "reconcile":
        valid = (
            release.get("campaign_id") == self.config.candidate_id
            and release.get("state") in {"cleared", "active", "certified"}
            and phase_at_least("revision_reconciled")
        )
    elif step == "identity":
        valid = (
            release.get("campaign_id") == self.config.candidate_id
            and release.get("state") in {"active", "certified"}
            and release.get("apply_count") == 1
            and isinstance(release.get("identity"), dict)
        )
    elif step == "card_reconcile":
        from scripts.reconcile_unverified_operational_controls import (
            operational_reconciliation_status,
        )

        dag = _object(self.config.cohesion_dag)
        progress = dag.get("progress", {})
        operational = operational_reconciliation_status(
            self.config.root, self.config.installed_exhaustive_receipt
        )
        valid = (
            release.get("campaign_id") == self.config.candidate_id
            and release.get("state") in {"active", "certified"}
            and phase_at_least("installed_operational")
            and release.get("stages", {}).get("installed_operational", {}).get("status")
            == "passed"
            and progress.get("closed_source_or_proof_cards") == 37
            and progress.get("remaining_source_or_proof_cards") == 0
            and operational.get("valid") is True
        )
    elif step == "preflight":
        claim = release.get("active_claim")
        certify_status = release.get("stages", {}).get("certify", {}).get("status")
        valid = (
            certify_status == "passed"
            or (
                certify_status == "claimed"
                and isinstance(claim, dict)
                and claim.get("stage") == "certify"
            )
        )
    else:
        stage = STAGE_AFTER[step]
        valid = release.get("stages", {}).get(stage, {}).get("status") == "passed"
        if step in PHASE_AFTER:
            valid = valid and phase_at_least(PHASE_AFTER[step])
        if step == "finalize":
            valid = valid and release.get("state") == "certified"
    if not valid:
        raise AutomationBlocked(f"owner exited zero without its postcondition: {step}")

def _derived_count(receipt: object, key: str) -> int:
    values = _find_named(receipt, re.sub(r"[^a-z0-9]", "", key.lower()))
    if not values:
        raise AutomationBlocked(f"exhaustive receipt omits {key}")
    counts = [len(value) if isinstance(value, list) else int(value) for value in values]
    if len(set(counts)) != 1:
        raise AutomationBlocked(f"exhaustive receipt has conflicting {key} values")
    return counts[0]

def _find_named(value: object, wanted: str) -> list[object]:
    matches: list[object] = []
    if isinstance(value, dict):
        for key, child in value.items():
            if re.sub(r"[^a-z0-9]", "", str(key).lower()) == wanted:
                matches.append(child)
            matches.extend(_find_named(child, wanted))
    elif isinstance(value, list):
        for child in value:
            matches.extend(_find_named(child, wanted))
    return matches

def _iso_utc(value: object) -> None:
    text = str(value or "")
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError as exc:
        raise AutomationBlocked("installed summary finished_utc is invalid") from exc
    if parsed.tzinfo is None or parsed.utcoffset() != timezone.utc.utcoffset(parsed):
        raise AutomationBlocked("installed summary finished_utc must be UTC")

def execute_next(
    config: Config, owners: OwnerRunner, *, admission_event_id: str, gap_id: str
) -> dict[str, Any]:
    step = next_pending_step(config, owners)
    if step is None:
        raise AutomationBlocked("candidate already has every step passed")
    journal = Journal(config)
    journal.start(step, admission_event_id=admission_event_id, gap_id=gap_id)
    try:
        details = dict(owners.run(step, config.owners[step]))
        details.update(
            admission_event_id=admission_event_id,
            gap_id=gap_id,
            executed_step=step,
        )
        passed = details.get("valid") is True
    except Exception as exc:
        journal.finish(step, passed=False, details={
            "error": f"{type(exc).__name__}: {exc}",
            "admission_event_id": admission_event_id,
            "gap_id": gap_id,
            "executed_step": step,
        })
        raise
    journal.finish(step, passed=passed, details=details)
    if not passed:
        raise AutomationBlocked(f"owner failed and cannot be retried: {step}")
    return {
        "schema_version": "px.release-candidate-step-result/1.0",
        "candidate_id": config.candidate_id,
        "executed_step": step,
        "next_step": next_pending_step(config, owners),
        "admission_event_id": admission_event_id,
        "valid": True,
    }

def main(argv: list[str] | None = None) -> int:
    args = parser().parse_args(argv)
    try:
        config = Config.load(args.config.resolve(strict=True))
        if not args.check and not args.execute_next and not args.execute_all:
            print(json.dumps(plan(config), indent=2))
            return 0
        if args.check:
            report = readiness(config)
            if report["valid"]:
                report["next_step"] = next_pending_step(config, SubprocessOwners(config))
            print(json.dumps(report, indent=2))
            return 0 if report["valid"] else 1
        if args.confirm_candidate != config.candidate_id:
            raise AutomationBlocked(
                "execution requires --confirm-candidate equal to candidate_id"
            )
        if not str(args.gap_id or "").strip():
            raise AutomationBlocked("execution requires --gap-id")
        if args.execute_all:
            if args.admission_event_id:
                raise AutomationBlocked("--execute-all creates its own per-stage admissions")
            if args.campaign_report is None:
                raise AutomationBlocked("--execute-all requires --campaign-report")
            report = readiness(config)
            if report["valid"] is not True:
                print(json.dumps(report, indent=2))
                return 1
            outcome = execute_all(
                config,
                SubprocessOwners(config),
                gap_id=args.gap_id,
                report_path=args.campaign_report,
            )
            print(json.dumps(outcome, indent=2))
            return 0 if outcome["valid"] else 1
        if not str(args.admission_event_id or "").strip():
            raise AutomationBlocked("--execute-next requires --gap-id and --admission-event-id")
        report = readiness(config)
        if report["valid"] is not True:
            print(json.dumps(report, indent=2))
            return 1
        outcome = execute_next(
            config, SubprocessOwners(config), gap_id=args.gap_id,
            admission_event_id=args.admission_event_id,
        )
        print(json.dumps(outcome, indent=2))
        return 0
    except (AutomationBlocked, OSError, ValueError, json.JSONDecodeError) as exc:
        print(
            json.dumps(
                {"valid": False, "errors": [f"{type(exc).__name__}: {exc}"]},
                indent=2,
            )
        )
        return 1

def next_pending_step(config: Config, owners: OwnerRunner) -> str | None:
    """Return the sole step that may run, verifying all earlier postconditions."""

    if not config.automation_state.exists():
        return STEP_ORDER[0]
    value = _object(config.automation_state)
    if value.get("schema_version") != STATE_SCHEMA or value.get("candidate_id") != config.candidate_id:
        raise AutomationBlocked("automation state identity is invalid")
    steps = value.get("steps")
    if not isinstance(steps, dict):
        raise AutomationBlocked("automation state steps are invalid")
    for step in STEP_ORDER:
        record = steps.get(step)
        status = record.get("status") if isinstance(record, dict) else None
        if status == "passed":
            owners.verify(step)
            continue
        if status is not None:
            raise AutomationBlocked(
                f"owner {step} is {status}; no retry is allowed for this candidate"
            )
        later = STEP_ORDER[STEP_ORDER.index(step) + 1 :]
        if any(name in steps for name in later):
            raise AutomationBlocked("automation journal skips canonical order")
        return step
    return None

def readiness(config: Config) -> dict[str, Any]:
    from runtime.release_campaign import cleared_campaign_can_be_superseded

    errors: list[str] = []
    initial = not config.automation_state.exists()
    if not config.root.is_dir():
        errors.append("repository root is missing")
    if not config.artifact.is_file() or config.artifact.is_symlink():
        errors.append("immutable artifact is not an exact non-symlink file")
    else:
        info = config.artifact.stat()
        observed = (_sha256(config.artifact), info.st_size, info.st_mtime_ns)
        expected = (
            config.artifact_sha256,
            config.artifact_size,
            config.artifact_mtime_ns,
        )
        if observed != expected:
            errors.append("immutable artifact identity differs from configuration")
    if initial and any(path.exists() for path in config.fresh_paths):
        errors.append("one or more fresh output paths already exist before the first step")
    if initial:
        repair_phase: str | None = None
        try:
            _validate_pre_candidate_hygiene(config)
        except (OSError, ValueError, json.JSONDecodeError, RuntimeError) as exc:
            errors.append(f"pre-candidate hygiene gate failed: {exc}")
        try:
            repair = _repair(config)
            repair_phase = str(repair.get("phase") or "")
            if repair.get("campaign_id") != config.repair_campaign_id:
                errors.append("repair campaign ID differs from configuration")
            if (
                repair_phase not in {"repair_frozen", *RELEASE_STAGE_PHASES.values()}
                or repair.get("intake_open") is not False
                or repair.get("unresolved") != []
            ):
                errors.append("repair campaign is not frozen with an empty denominator")
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            errors.append(f"repair campaign is unreadable: {type(exc).__name__}")
        try:
            release = _release(config)
            if release.get("campaign_id") != config.predecessor_campaign_id:
                errors.append("predecessor campaign ID differs from configuration")
            predecessor_ready = False
            if release.get("state") == "failed":
                failed_stages = [
                    name
                    for name, record in release.get("stages", {}).items()
                    if isinstance(record, dict) and record.get("status") == "failed"
                ]
                predecessor_ready = (
                    len(failed_stages) == 1
                    and failed_stages[0] in RELEASE_STAGE_PHASES
                    and repair_phase
                    in {
                        "repair_frozen",
                        RELEASE_STAGE_PHASES[failed_stages[0]],
                    }
                )
            elif release.get("state") == "cleared":
                predecessor_ready = (
                    release.get("apply_count") == 0
                    and release.get("identity") is None
                    and repair_phase in {"repair_frozen", "revision_reconciled"}
                    and cleared_campaign_can_be_superseded(release)
                )
            active_kind = _invalid_active_predecessor_kind(config, release)
            if release.get("state") == "active":
                retained_passes = [
                    name
                    for name in RELEASE_STAGE_PHASES
                    if isinstance(release.get("stages", {}).get(name), dict)
                    and release["stages"][name].get("status") == "passed"
                ]
                predecessor_ready = (
                    active_kind == "unused_invalid_identity"
                    and repair_phase in {"repair_frozen", "revision_reconciled"}
                ) or (
                    active_kind == "invalid_active_with_retained_passes"
                    and bool(retained_passes)
                    and repair_phase
                    in {
                        "repair_frozen",
                        RELEASE_STAGE_PHASES[
                            tuple(RELEASE_STAGE_PHASES)[len(retained_passes)]
                        ],
                    }
                )
            if not predecessor_ready or release.get("active_claim") is not None:
                errors.append(
                    "predecessor is not terminal failed, unused cleared, or an "
                    "source-invalid active predecessor"
                )
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            errors.append(f"release campaign is unreadable: {type(exc).__name__}")
    else:
        try:
            state = _object(config.automation_state)
            if state.get("schema_version") != STATE_SCHEMA or state.get("candidate_id") != config.candidate_id:
                errors.append("automation state identity is invalid")
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            errors.append(f"automation state is unreadable: {type(exc).__name__}")
    return {
        "schema_version": "px.release-candidate-readiness/1.0",
        "candidate_id": config.candidate_id,
        "valid": not errors,
        "errors": errors,
    }

def validate_installed_summary(config: Config) -> dict[str, Any]:
    """Validate hash-bound installed evidence before downstream certification."""

    if not config.installed_summary.is_file() or config.installed_summary.is_symlink():
        raise AutomationBlocked("installed operational summary is missing")
    summary = _object(config.installed_summary)
    if summary.get("schema_version") != "px.installed-operational-run-summary/1.1":
        raise AutomationBlocked("installed operational summary schema must be 1.1")
    if summary.get("campaign_id") != config.candidate_id:
        raise AutomationBlocked("installed summary campaign differs from the candidate")
    release = _release(config)
    identity = release.get("identity")
    if not isinstance(identity, dict):
        raise AutomationBlocked("live release identity is missing")
    for key in (
        "release_identity_sha256", "source_product_digest", "source_harness_digest"
    ):
        expected = identity.get(key)
        if not isinstance(expected, str) or not SHA256_RE.fullmatch(expected):
            raise AutomationBlocked(f"live release identity {key} is invalid")
        if summary.get(key) != expected:
            raise AutomationBlocked(f"installed summary {key} differs from release identity")
    installed_claim = release.get("stages", {}).get("installed_operational", {}).get("claim_id")
    if (
        not isinstance(installed_claim, str)
        or summary.get("claim_id") != installed_claim
        or not installed_claim.startswith(
            f"release-stage:{config.candidate_id}:installed_operational:"
        )
    ):
        raise AutomationBlocked("installed summary claim is not candidate-bound")
    _iso_utc(summary.get("finished_utc"))
    for key, expected in {
        "all_passed": True,
        "retries": 0,
        "cross_platform_smokes_parallel": True,
        "windows_hosts_serialized": True,
    }.items():
        if summary.get(key) != expected:
            raise AutomationBlocked(f"installed summary {key} is not {expected!r}")
    artifact = summary.get("artifact")
    if not isinstance(artifact, dict):
        raise AutomationBlocked("installed summary artifact is invalid")
    artifact_path = _inside(config.root, _required(artifact, "path"), "artifact")
    if artifact_path != config.artifact or artifact.get("sha256") != config.artifact_sha256:
        raise AutomationBlocked("installed summary artifact identity differs")
    if artifact.get("size") != config.artifact_size:
        raise AutomationBlocked("installed summary artifact size differs")
    observed = config.artifact.stat()
    if (_sha256(config.artifact), observed.st_size, observed.st_mtime_ns) != (
        config.artifact_sha256, config.artifact_size, config.artifact_mtime_ns
    ):
        raise AutomationBlocked("immutable artifact changed during installed proof")
    stages = release.get("stages")
    if not isinstance(stages, dict):
        raise AutomationBlocked("live release stages are missing")
    package_claim = stages.get("package", {}).get("claim_id")
    install_claim = stages.get("install", {}).get("claim_id")
    if not isinstance(package_claim, str) or not isinstance(install_claim, str):
        raise AutomationBlocked("package/install release claims are missing")
    _validate_stage_receipt(
        config, summary.get("package_receipt"), label="package",
        identity=identity, expected_claim_id=package_claim,
    )
    _validate_stage_receipt(
        config, summary.get("install_receipt"), label="install",
        identity=identity, expected_claim_id=install_claim,
    )
    members = summary.get("members")
    expected_names = {
        "windows-exact-vsix-smoke",
        "ubuntu-exact-vsix-smoke",
        "exhaustive-installed-exact-vsix-host-walk",
    }
    if not isinstance(members, list) or len(members) != 3:
        raise AutomationBlocked("installed summary must contain exactly three members")
    by_name = {
        str(item.get("member")): item for item in members if isinstance(item, dict)
    }
    if set(by_name) != expected_names:
        raise AutomationBlocked("installed summary member set is incomplete")
    for name in expected_names:
        member = by_name[name]
        if member.get("exit_code") != 0 or member.get("artifact_unchanged") is not True:
            raise AutomationBlocked(f"installed member is not successful: {name}")
        if member.get("process_tree_closed_verified") is not True:
            raise AutomationBlocked(f"installed member process tree is not closed: {name}")
        _evidence_file(config, member.get("log"), f"{name}.log")
        _evidence_file(config, member.get("receipt"), f"{name}.receipt")
        if name != "exhaustive-installed-exact-vsix-host-walk":
            _evidence_file(
                config, member.get("process_lifecycle_receipt"),
                f"{name}.process_lifecycle_receipt",
            )
    exhaustive = by_name["exhaustive-installed-exact-vsix-host-walk"]
    for key, expected in {
        "terminal_state": "completed",
        "scope_complete": True,
        "operationally_complete": True,
        "issue_count": 0,
        "blocking_issue_count": 0,
        "host_error_count": 0,
        "profile_failure_count": 0,
        "workspace_reclaimed": True,
    }.items():
        if exhaustive.get(key) != expected:
            raise AutomationBlocked(f"exhaustive installed proof {key} is not {expected!r}")
    report_path = _evidence_file(config, exhaustive.get("report"), "exhaustive.report")
    receipt_path = _evidence_file(config, exhaustive.get("receipt"), "exhaustive.receipt")
    report = _object(report_path)
    receipt = _object(receipt_path)
    truth = report.get("status_truth", {})
    status = report.get("child_lifecycle", {}).get("operational_status", {})
    derived = {
        "terminal_state": truth.get("terminal_state"),
        "operationally_complete": truth.get("operationally_complete"),
        "issue_count": truth.get("summary", {}).get("issue_count"),
        "blocking_issue_count": truth.get("summary", {}).get("blocking_issue_count"),
        "scope_complete": status.get("scope_complete"),
        "process_tree_closed_verified": report.get("owner_lifecycle", {}).get(
            "process_tree_closed_verified"
        ),
        "workspace_reclaimed": report.get("cleanup", {}).get("reclaimed"),
        "artifact_unchanged": report.get("child_lifecycle", {}).get(
            "installed_artifact", {}
        ).get("unchanged_after_install"),
    }
    for key, value in derived.items():
        if exhaustive.get(key) != value:
            raise AutomationBlocked(f"exhaustive summary disagrees with report: {key}")
    if exhaustive.get("host_error_count") != _derived_count(receipt, "host_errors"):
        raise AutomationBlocked("exhaustive host error count disagrees with receipt")
    if exhaustive.get("profile_failure_count") != _derived_count(receipt, "profile_failures"):
        raise AutomationBlocked("exhaustive profile failure count disagrees with receipt")
    return summary

def _load(root: Path) -> dict[str, object]:
    path = root / "registry/release_fault_campaign.json"
    value = json.loads(path.read_text(encoding="utf-8"))
    if value.get("schema_version") != "px.release-fault-campaign/1.0":
        raise ValueError("unsupported fault-campaign schema")
    required = value.get("required_dimensions")
    lanes = value.get("lanes")
    if not isinstance(required, list) or not required or len(set(required)) != len(required):
        raise ValueError("fault-campaign dimensions are invalid")
    if not isinstance(lanes, list) or not lanes:
        raise ValueError("fault-campaign lanes are missing")
    covered: set[str] = set()
    for lane in lanes:
        if not isinstance(lane, dict) or set(lane) != {"id", "cwd", "command", "dimensions"}:
            raise ValueError("fault-campaign lane contract is invalid")
        command = lane["command"]
        if not isinstance(command, list) or not command or command[0] not in {"python", "node"}:
            raise ValueError("fault-campaign command is not admitted")
        cwd = (root / str(lane["cwd"])).resolve()
        cwd.relative_to(root)
        if not cwd.is_dir():
            raise ValueError("fault-campaign working directory is missing")
        for token in command:
            if not isinstance(token, str) or "\x00" in token:
                raise ValueError("fault-campaign command token is invalid")
        dimensions = lane["dimensions"]
        if not isinstance(dimensions, list) or not set(dimensions) <= set(required):
            raise ValueError("fault-campaign lane dimensions are invalid")
        covered.update(dimensions)
    if covered != set(required):
        raise ValueError("fault-campaign does not cover every required dimension")
    return value

def run(config: Config, step: str, effects: Effects) -> dict[str, Any]:
    readiness = check(config, step)
    if readiness["valid"] is not True:
        raise OwnerBlocked("; ".join(readiness["errors"]))
    evidence = dict(effects.execute(step, config))
    effects.verify(step, config)

def execute(self, step: str, config: Config) -> Mapping[str, Any]:
    from runtime.release_campaign import (
        claim_release_stage,
        finish_release_stage,
        supersede_consumed_cleared_release_campaign,
        supersede_failed_release_campaign,
        supersede_invalid_active_release_campaign,
        supersede_invalid_release_identity,
        rewind_failed_release_campaign_repair,
        rewind_consumed_cleared_release_campaign_repair,
        rewind_invalid_active_release_campaign_repair,
        rewind_invalid_release_identity_reconciliation,
    )

    stale: list[str] = []
    if step == "identity" and (
        not config.path_manifest.is_file() or config.path_manifest.is_symlink()
    ):
        raise OwnerBlocked("identity path manifest is not a regular file")
    if step == "sections":
        from runtime.test_profiles import (
            section_status,
            stale_section_execution_order,
        )

        stale = stale_section_execution_order(section_status(config.root))
    if step == "package" and self.package_audit(
        config, {"claim_id": "preclaim-audit"}
    ).get("valid") is not True:
        raise OwnerBlocked("package inputs fail the exact pre-claim audit")
    if step == "install" and self.install_audit(
        config, {"claim_id": "preclaim-audit"}
    ).get("valid") is not True:
        raise OwnerBlocked("install inputs fail the exact pre-claim audit")
    receipt_path = config.evidence_dir / f"{config.candidate_id}-{step}.json"
    outputs = [receipt_path]
    if step in {"full_profile", "validate", "package", "install"}:
        outputs.append(config.log_dir / f"{config.candidate_id}-{step}.log")
    if step == "sections":
        outputs.extend(
            config.log_dir / f"{config.candidate_id}-sections-{name}.log"
            for name in stale
        )
    for output in outputs:
        self.probe_output(output)
    atomic_json(
        receipt_path,
        {
            "schema_version": "px.release-stage-owner-terminal-marker/1.0",
            "candidate_id": config.candidate_id,
            "step": step,
            "status": "running",
            "valid": False,
        },
    )
    if step == "archive_clear":
        current = release(config)
        if current.get("state") == "failed":
            if repair(config).get("phase") != "repair_frozen":
                rewind_failed_release_campaign_repair(config.root)
            status = supersede_failed_release_campaign(
                config.root,
                campaign_id=config.candidate_id,
                reason=(
                    f"{config.predecessor_id} is terminal and repair12 is frozen; "
                    f"establish {config.candidate_id} once."
                ),
            )
        elif current.get("state") == "active":
            stages = current.get("stages", {})
            retained_passes = any(
                isinstance(stages.get(name), dict)
                and stages[name].get("status") == "passed"
                for name in STAGES
            )
            if retained_passes:
                if repair(config).get("phase") != "repair_frozen":
                    rewind_invalid_active_release_campaign_repair(config.root)
                status = supersede_invalid_active_release_campaign(
                    config.root,
                    campaign_id=config.candidate_id,
                    reason=(
                        f"{config.predecessor_id} is source-invalid with retained "
                        f"passed stages; establish {config.candidate_id} once."
                    ),
                )
            else:
                if repair(config).get("phase") == "revision_reconciled":
                    rewind_invalid_release_identity_reconciliation(config.root)
                status = supersede_invalid_release_identity(
                    config.root,
                    campaign_id=config.candidate_id,
                    reason=(
                        f"{config.predecessor_id} has one unused invalid identity; "
                        f"establish {config.candidate_id} once."
                    ),
                )
        else:
            if repair(config).get("phase") == "revision_reconciled":
                rewind_consumed_cleared_release_campaign_repair(config.root)
            status = supersede_consumed_cleared_release_campaign(
                config.root,
                campaign_id=config.candidate_id,
                reason=(
                    f"{config.predecessor_id} was consumed by a failed pre-identity "
                    f"owner postcondition; establish {config.candidate_id} once."
                ),
            )
        return self.receipt(
            config,
            step,
            {
                "schema_version": "px.release-successor-receipt/1.0",
                "candidate_id": config.candidate_id,
                "archive": status.get("superseded_archive"),
                "valid": status.get("valid") is True,
            },
        )
    if step == "reconcile":
        from runtime.generated_artifacts import validate_generated_artifacts
        from runtime.release_artifacts import classify_tree
        from scripts.clean_source_export import _rebuild_candidate_projections

        _rebuild_candidate_projections(config.root)
        generated = validate_generated_artifacts(config.root)
        classification = classify_tree(config.root)
        if (
            generated.get("valid") is not True
            or classification.get("valid") is not True
            or classification.get("product_valid") is not True
        ):
            raise OwnerBlocked("reconciliation post-audit failed")
        self.advance(config, *PHASES[step])
        return self.receipt(
            config,
            step,
            {
                "schema_version": "px.revision-reconciliation-receipt/1.0",
                "campaign_id": config.candidate_id,
                "product_digest": classification.get("product_digest"),
                "harness_digest": classification.get("harness_digest"),
                "generated_check_count": generated.get("check_count"),
                "valid": True,
            },
        )
    if step == "identity":
        return self.identity(config)
    if step == "sections":
        from runtime.test_profiles import section_status

        claim = claim_release_stage(config.root, "sections")
        finished = False
        try:
            logs = [
                self.command(
                    config,
                    f"sections-{name}",
                    [
                        sys.executable,
                        "-B",
                        "-m",
                        "runtime.cli",
                        "test-section",
                        "run",
                        name,
                    ],
                    timeout_seconds=900,
                )
                for name in stale
            ]
            passed = section_status(config.root).get("valid") is True
            finish_release_stage(
                config.root,
                stage="sections",
                claim_id=str(claim["claim_id"]),
                passed=passed,
            )
            finished = True
            if not passed:
                raise OwnerBlocked("not all six governed sections are current")
        except BaseException:
            if not finished:
                try:
                    finish_release_stage(
                        config.root,
                        stage="sections",
                        claim_id=str(claim["claim_id"]),
                        passed=False,
                    )
                except Exception:
                    pass
            raise
        self.advance(config, *PHASES[step])
        return self.receipt(
            config,
            step,
            {
                "schema_version": "px.governed-sections-complete-denominator/1.0",
                "campaign_id": config.candidate_id,
                "claim_id": claim["claim_id"],
                "stale_sections_before": stale,
                "owners": logs,
                "all_six_current": True,
                "valid": True,
            },
        )
    if step in {"full_profile", "validate"}:
        action = (
            ["test-profile", "run", "full"]
            if step == "full_profile"
            else ["validate"]
        )
        log = self.command(
            config,
            step,
            [sys.executable, "-B", "-m", "runtime.cli", *action],
            timeout_seconds=3000 if step == "full_profile" else 900,
        )
        current = release(config)
        kernel = current.get("identity", {})
        if current.get("stages", {}).get(step, {}).get(
            "status"
        ) != "passed" or not isinstance(kernel, dict):
            raise OwnerBlocked(f"canonical {step} CLI did not pass")
        self.advance(config, *PHASES[step])
        return self.receipt(
            config,
            step,
            {
                "schema_version": "px.full-profile-receipt/1.0"
                if step == "full_profile"
                else "px.validation-receipt/1.0",
                "campaign_id": config.candidate_id,
                "release_identity_sha256": kernel.get("release_identity_sha256"),
                "owner_invocations": 1,
                "owner_log": log,
                "stage_status": "passed",
                "valid": True,
            },
        )
    claim = claim_release_stage(config.root, step)
    finished = False
    try:
        payload = (
            self.package_audit(config, claim)
            if step == "package"
            else self.install_audit(config, claim)
        )
        audit_log = config.log_dir / f"{config.candidate_id}-{step}.log"
        atomic_json(audit_log, payload)
        payload.update(
            audit_log=config.relative(audit_log),
            audit_log_sha256=sha256(audit_log),
        )
        passed = payload.get("valid") is True
        finish_release_stage(
            config.root, stage=step, claim_id=str(claim["claim_id"]), passed=passed
        )
        finished = True
        receipt = self.receipt(config, step, payload)
        if not passed:
            raise OwnerBlocked(f"{step} audit failed")
    except BaseException:
        if not finished:
            try:
                finish_release_stage(
                    config.root,
                    stage=step,
                    claim_id=str(claim["claim_id"]),
                    passed=False,
                )
            except Exception:
                pass
        raise
    self.advance(config, *PHASES[step])
    return receipt

def identity(self, config: Config) -> Mapping[str, Any]:
    from runtime.release_campaign import apply_release_identity
    from runtime.release_identity import _release_dirty_state, authoritative_version

    manifest = load_object(config.path_manifest)
    paths = manifest.get("paths")
    mutable_paths = manifest.get("mutable_paths", [])
    if (
        not isinstance(paths, list)
        or not paths
        or paths != sorted(set(paths), key=str.casefold)
        or not isinstance(mutable_paths, list)
        or mutable_paths != sorted(set(mutable_paths), key=str.casefold)
        or set(paths) & set(mutable_paths)
        or any(
            not isinstance(path, str) or not path or ".." in Path(path).parts
            for path in [*paths, *mutable_paths]
        )
    ):
        raise OwnerBlocked(
            "identity manifest source/mutable paths must be sorted, disjoint, and safe"
        )
    dirty = _release_dirty_state(config.root)
    if dirty.get("classifier_errors"):
        raise OwnerBlocked("release source classification is invalid")
    if set(dirty.get("blocking_paths", ())) != set(paths):
        raise OwnerBlocked(
            "blocking source changes differ from the explicit identity manifest"
        )
    if set(dirty.get("mutable_control_paths", ())) != set(mutable_paths):
        raise OwnerBlocked(
            "mutable control changes differ from the explicit identity manifest"
        )
    self.git(config, "add", "--", *paths)
    cached = {
        path
        for path in self.git(
            config, "diff", "--cached", "--name-only", "-z", "--no-renames"
        ).split("\0")
        if path
    }
    if cached != set(paths):
        raise OwnerBlocked("Git cached set differs from explicit identity manifest")
    if config.release_tag != f"v{authoritative_version(config.root)}":
        raise OwnerBlocked("release tag differs from authoritative version")
    old_target = self.git(config, "rev-list", "-n", "1", config.release_tag)
    if (
        old_target != config.prior_tag_target
        or self.git(config, "cat-file", "-t", f"refs/tags/{config.release_tag}")
        != "tag"
    ):
        raise OwnerBlocked(
            "existing annotated tag is not at the admitted prior target"
        )
    self.git(config, "commit", "-m", config.commit_message)
    head = self.git(config, "rev-parse", "HEAD")
    post_commit = _release_dirty_state(config.root)
    if post_commit.get("blocking_paths") or post_commit.get("classifier_errors"):
        raise OwnerBlocked("source commit left blocking release-input drift")
    self.git(
        config,
        "tag",
        "-f",
        "-a",
        config.release_tag,
        "-m",
        f"{config.release_tag} {config.candidate_id}",
        head,
    )
    if self.git(config, "rev-list", "-n", "1", config.release_tag) != head:
        raise OwnerBlocked("authorized one-time retag did not bind HEAD")
    status = apply_release_identity(config.root)
    kernel = status.get("identity", {})
    if status.get("valid") is not True or not isinstance(kernel, dict):
        raise OwnerBlocked("release identity apply failed")
    return self.receipt(
        config,
        "identity",
        {
            "schema_version": "px.single-identity-transition-receipt/1.0",
            "campaign_id": config.candidate_id,
            "commit": head,
            "annotated_tag": config.release_tag,
            "tag_target": head,
            "release_identity_sha256": kernel.get("release_identity_sha256"),
            "source_product_digest": kernel.get("source_product_digest"),
            "source_harness_digest": kernel.get("source_harness_digest"),
            "artifact": {
                "path": config.relative(config.artifact),
                "sha256": config.artifact_sha256,
                "size": config.artifact_size,
            },
            "retag_count": 1,
            "valid": True,
        },
    )

def list_installed_extensions(
    self, config: Config
) -> subprocess.CompletedProcess[str]:
    """Query the exact extension root without inheriting an IDE host profile."""

    environment = {
        key: value
        for key, value in os.environ.items()
        if not key.upper().startswith("VSCODE_")
    }
    with tempfile.TemporaryDirectory(
        prefix="pacify-x-vscode-cli-audit-"
    ) as user_data_dir:
        return subprocess.run(
            [
                str(config.code_command),
                "--user-data-dir",
                user_data_dir,
                "--extensions-dir",
                str(config.installed_dir.parent),
                "--list-extensions",
                "--show-versions",
            ],
            cwd=config.root,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=60,
            check=False,
            env=environment,
        )

def receipt(
    self, config: Config, step: str, payload: Mapping[str, Any]
) -> dict[str, Any]:
    path = config.evidence_dir / f"{config.candidate_id}-{step}.json"
    atomic_json(path, dict(payload))
    return {
        "path": config.relative(path),
        "sha256": sha256(path),
        "size": path.stat().st_size,
        "valid": True,
    }

def tree(self, root: Path) -> tuple[dict[str, Path], list[str], str]:
    files: dict[str, Path] = {}
    links: list[str] = []
    for current, directories, names in os.walk(
        root, topdown=True, followlinks=False
    ):
        base = Path(current)
        retained: list[str] = []
        for name in sorted(directories):
            path = base / name
            flags = int(getattr(path.lstat(), "st_file_attributes", 0))
            if path.is_symlink() or flags & int(
                getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)
            ):
                links.append(path.relative_to(root).as_posix() + "/")
            else:
                retained.append(name)
        directories[:] = retained
        for name in sorted(names):
            path = base / name
            relative = path.relative_to(root).as_posix()
            flags = int(getattr(path.lstat(), "st_file_attributes", 0))
            if path.is_symlink() or flags & int(
                getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)
            ):
                links.append(relative)
            elif path.is_file():
                files[relative] = path
    digest = hashlib.sha256()
    for relative in sorted(files):
        payload = files[relative].read_bytes()
        for part in (
            relative.encode(),
            b"\0",
            str(len(payload)).encode(),
            b"\0",
            hashlib.sha256(payload).digest(),
        ):
            digest.update(part)
    return files, sorted(links), digest.hexdigest()

def verify(self, step: str, config: Config) -> None:
    current_release = release(config)
    current_repair = repair(config)
    if step == "archive_clear":
        valid = (
            current_release.get("campaign_id") == config.candidate_id
            and current_release.get("state") == "cleared"
            and current_release.get("apply_count") == 0
            and current_release.get("identity") is None
            and current_release.get("active_claim") is None
            and tuple(current_release.get("stages", {})) == STAGES
            and all(
                row.get("status") == "pending"
                for row in current_release["stages"].values()
            )
        )
    elif step == "reconcile":
        valid = (
            current_release.get("state") == "cleared"
            and current_repair.get("phase") == "revision_reconciled"
        )
    elif step == "identity":
        valid = (
            current_release.get("state") == "active"
            and current_release.get("apply_count") == 1
            and isinstance(current_release.get("identity"), dict)
        )
    else:
        valid = (
            current_release.get("stages", {}).get(step, {}).get("status")
            == "passed"
            and current_repair.get("phase") == PHASES[step][1]
        )
    receipt_path = config.evidence_dir / f"{config.candidate_id}-{step}.json"
    receipt = load_object(receipt_path) if receipt_path.is_file() else {}
    expected_schema = {
        "archive_clear": "px.release-successor-receipt/1.0",
        "reconcile": "px.revision-reconciliation-receipt/1.0",
        "identity": "px.single-identity-transition-receipt/1.0",
        "sections": "px.governed-sections-complete-denominator/1.0",
        "full_profile": "px.full-profile-receipt/1.0",
        "validate": "px.validation-receipt/1.0",
        "package": "px.release-stage-evidence/1.0",
        "install": "px.install-audit-denominator/1.0",
    }[step]
    receipt_campaign = receipt.get("candidate_id") if step == "archive_clear" else receipt.get("campaign_id")
    receipt_valid = (
        receipt.get("schema_version") == expected_schema
        and receipt_campaign == config.candidate_id
        and receipt.get("valid") is True
    )
    if step in {"sections", "package", "install"}:
        expected_claim = current_release.get("stages", {}).get(step, {}).get("claim_id")
        actual_claim = receipt.get("claim_id")
        if step == "install" and actual_claim is None:
            actual_claim = receipt.get("install_claim_id")
        receipt_valid = receipt_valid and actual_claim == expected_claim
    if step in {"identity", "package", "install"}:
        artifact = receipt.get("artifact")
        receipt_valid = receipt_valid and artifact == {
            "path": config.relative(config.artifact),
            "sha256": config.artifact_sha256,
            "size": config.artifact_size,
        }
    if step in {"full_profile", "validate", "package", "install"}:
        identity = current_release.get("identity", {})
        receipt_valid = (
            receipt_valid
            and isinstance(identity, dict)
            and receipt.get("release_identity_sha256")
            == identity.get("release_identity_sha256")
        )
        if step in {"package", "install"}:
            receipt_valid = receipt_valid and all(
                receipt.get(key) == identity.get(key)
                for key in ("source_product_digest", "source_harness_digest")
            )
    resources = resource_postcondition(config)
    clean = resources.get("valid") is True
    if (
        not valid
        or not clean
        or not receipt_path.is_file()
        or receipt_path.is_symlink()
        or not receipt_valid
    ):
        raise OwnerBlocked(f"{step} postcondition is not exact")

def check(config: Config, step: str) -> dict[str, Any]:
    from runtime.release_campaign import cleared_campaign_can_be_superseded

    errors: list[str] = []
    if step not in STEPS:
        errors.append("unsupported step")
    if not config.artifact.is_file() or config.artifact.is_symlink():
        errors.append("artifact is not a regular file")
    else:
        info = config.artifact.stat()
        if (sha256(config.artifact), info.st_size, info.st_mtime_ns) != (
            config.artifact_sha256,
            config.artifact_size,
            config.artifact_mtime_ns,
        ):
            errors.append("artifact identity differs from config")
    try:
        current_repair = repair(config)
        current_release = release(config)
        archive_recovery_phase = None
        active_kind = None
        if step == "archive_clear" and current_release.get("state") == "failed":
            failed_stages = [
                name
                for name, record in current_release.get("stages", {}).items()
                if isinstance(record, dict) and record.get("status") == "failed"
            ]
            if len(failed_stages) == 1 and failed_stages[0] in STAGE_PHASES:
                archive_recovery_phase = STAGE_PHASES[failed_stages[0]]
        elif step == "archive_clear" and current_release.get("state") == "active":
            active_kind = invalid_active_predecessor_kind(config, current_release)
            if active_kind == "unused_invalid_identity":
                archive_recovery_phase = "revision_reconciled"
            elif active_kind == "invalid_active_with_retained_passes":
                passed_stages = [
                    name
                    for name in STAGES
                    if current_release["stages"][name].get("status") == "passed"
                ]
                archive_recovery_phase = STAGE_PHASES[STAGES[len(passed_stages)]]
        elif step == "archive_clear" and current_release.get("state") == "cleared":
            if cleared_campaign_can_be_superseded(current_release):
                archive_recovery_phase = "revision_reconciled"
        repair_phase_valid = current_repair.get("phase") == PHASES.get(
            step, (None,)
        )[0] or current_repair.get("phase") == archive_recovery_phase
        if (
            current_repair.get("campaign_id")
            != "pacify-x-cohesion-closure-repair12-20260905"
            or not repair_phase_valid
            or current_repair.get("intake_open") is not False
            or current_repair.get("unresolved") != []
        ):
            errors.append(f"repair12 phase is not exact for {step}")
        if step == "archive_clear":
            if (
                current_release.get("campaign_id") != config.predecessor_id
                or current_release.get("active_claim") is not None
                or current_release.get("state") not in {"failed", "cleared", "active"}
                or (
                    current_release.get("state") == "cleared"
                    and (
                        current_release.get("apply_count") != 0
                        or current_release.get("identity") is not None
                        or not cleared_campaign_can_be_superseded(current_release)
                    )
                )
                or (
                    current_release.get("state") == "active"
                    and active_kind not in {
                        "unused_invalid_identity",
                        "invalid_active_with_retained_passes",
                    }
                )
            ):
                errors.append(
                    "archive_clear requires a terminal failed, unused cleared, "
                    "or source-invalid active predecessor"
                )
        elif step in {"reconcile", "identity"}:
            if (
                current_release.get("campaign_id") != config.candidate_id
                or current_release.get("state") != "cleared"
                or current_release.get("apply_count") != 0
                or current_release.get("identity") is not None
            ):
                errors.append(f"{step} requires cleared candidate")
        else:
            stages = current_release.get("stages", {})
            index = STAGES.index(step)
            if (
                current_release.get("campaign_id") != config.candidate_id
                or current_release.get("state") != "active"
                or current_release.get("apply_count") != 1
                or tuple(stages) != STAGES
                or current_release.get("active_claim") is not None
                or stages.get(step, {}).get("status") != "pending"
                or any(
                    stages[name].get("status") != "passed" for name in STAGES[:index]
                )
            ):
                errors.append(f"{step} release stage/predecessors are not exact")
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        errors.append(f"control plane unreadable: {type(exc).__name__}")
    if (config.evidence_dir / f"{config.candidate_id}-{step}.json").exists() or (
        config.log_dir / f"{config.candidate_id}-{step}.log"
    ).exists():
        errors.append("fresh owner receipt already exists")
    return {
        "schema_version": "px.release-stage-owner-check/1.0",
        "candidate_id": config.candidate_id,
        "step": step,
        "valid": not errors,
        "errors": errors,
    }

def inside(root: Path, raw: object, label: str) -> Path:
    source = Path(str(raw or ""))
    if not str(source) or ".." in source.parts:
        raise OwnerBlocked(f"unsafe {label} path")
    nominal = Path(os.path.abspath(source if source.is_absolute() else root / source))
    try:
        relative = nominal.relative_to(root)
    except ValueError as exc:
        raise OwnerBlocked(f"{label} escapes repository") from exc
    current = root
    for part in relative.parts:
        current /= part
        try:
            flags = int(getattr(current.lstat(), "st_file_attributes", 0))
        except FileNotFoundError:
            flags = 0
        if current.is_symlink() or flags & int(
            getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)
        ):
            raise OwnerBlocked(f"{label} traverses a symlink/reparse point: {current}")
    path = nominal.resolve()
    try:
        path.relative_to(root)
    except ValueError as exc:
        raise OwnerBlocked(f"{label} escapes repository") from exc
    return path

def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", type=Path, required=True)
    parser.add_argument("--step", choices=STEPS, required=True)
    modes = parser.add_mutually_exclusive_group()
    modes.add_argument("--check", action="store_true")
    modes.add_argument("--execute", action="store_true")
    args = parser.parse_args(argv)
    config: Config | None = None
    try:
        config = Config.load(args.config.resolve(strict=True))
        if not args.check and not args.execute:
            output = plan(config, args.step)
        elif args.check:
            output = check(config, args.step)
        else:
            output = run(config, args.step, ProductionEffects())
        print(json.dumps(output, indent=2))
        return 0 if output.get("valid") else 1
    except (OwnerBlocked, OSError, ValueError, json.JSONDecodeError) as exc:
        marker_error: Exception | None = None
        if args.execute and config is not None and args.step in {
            "archive_clear",
            "reconcile",
            "identity",
        }:
            try:
                current = release(config)
                if (
                    current.get("campaign_id") == config.candidate_id
                    and current.get("state") == "cleared"
                ):
                    from runtime.release_campaign import mark_pre_identity_owner_failure

                    mark_pre_identity_owner_failure(
                        config.root,
                        campaign_id=config.candidate_id,
                        owner=args.step,
                        error=f"{type(exc).__name__}: {exc}",
                    )
            except (OSError, ValueError, json.JSONDecodeError) as marker_exc:
                marker_error = marker_exc
        errors = [f"{type(exc).__name__}: {exc}"]
        if marker_error is not None:
            errors.append(
                "pre-identity failure marker could not be recorded: "
                f"{type(marker_error).__name__}: {marker_error}"
            )
        print(
            json.dumps({"valid": False, "errors": errors}, indent=2)
        )
        return 1

def sanitize_tree(
    root: Path,
    *,
    apply: bool = False,
    excluded_names: frozenset[str] = frozenset(),
    preservation_root: Path | None = None,
) -> dict[str, object]:
    resolved = root.resolve()
    if not resolved.is_dir() or resolved == Path(resolved.anchor):
        raise ValueError("root must be an explicit non-filesystem-root directory")
    preserved: list[dict[str, object]] = []
    preservation = preservation_root.resolve() if preservation_root else None
    if apply:
        if preservation is None:
            raise ValueError("apply requires a recoverable preservation root")
        preservation_is_nested = True
        try:
            preservation.relative_to(resolved)
        except ValueError:
            preservation_is_nested = False
        if preservation_is_nested:
            raise ValueError(
                "preservation root must be outside the active sanitization tree"
            )
        if preservation.exists() and any(preservation.iterdir()):
            raise ValueError("preservation root must not contain an earlier run")
        preservation.mkdir(parents=True, exist_ok=True)
    content_changes: list[str] = []
    path_changes: list[dict[str, str]] = []
    binary_hits: list[str] = []
    errors: list[str] = []
    paths = sorted(resolved.rglob("*"), key=lambda item: len(item.parts), reverse=True)
    if apply and preservation is not None:
        affected: set[Path] = set()
        preservation_errors: list[str] = []
        changed_nodes = [
            path for path in paths if _sanitized_component(path.name) != path.name
        ]
        for path in paths:
            relative_parts = path.relative_to(resolved).parts
            if any(
                part in SKIP_DIRECTORIES or part in excluded_names
                for part in relative_parts
            ):
                continue
            if path.is_file():
                try:
                    with path.open("rb") as handle:
                        sample = handle.read(65536)
                    if b"\x00" not in sample and _text_requires_change(path):
                        affected.add(path)
                except (OSError, UnicodeDecodeError) as error:
                    preservation_errors.append(
                        sanitize(
                            f"{path.relative_to(resolved).as_posix()}: {type(error).__name__}: {error}"
                        )
                    )
        if preservation_errors:
            raise SanitizationPreflightError(sorted(preservation_errors))
        for node in changed_nodes:
            if node.is_file():
                affected.add(node)
            elif node.is_dir():
                affected.update(path for path in node.rglob("*") if path.is_file())
        for path in sorted(affected, key=lambda item: item.as_posix().casefold()):
            relative = path.relative_to(resolved)
            target = preservation / relative
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(path, target)

