        } <= declared
    for facade in (ROOT / ".px/skills").iterdir():
        if not facade.is_dir():
            continue
        facade_files = {
            item.relative_to(ROOT).as_posix()
            for item in generator._owned_files(facade)
        }
        assert facade_files <= declared
