            (ROOT / "registry/skill_catalog.toml").read_text(encoding="utf-8")
        )
        mapped = json.loads(
            (ROOT / "registry/specialty_map.json").read_text(encoding="utf-8")
        )
        active_ids = {
            item["id"]
            for item in catalog["skills"]
            if item.get("status") in {"active", "admitted"}
        }
        mapped_active = {
            item["id"]
            for category in mapped["categories"]
            for item in category["specialties"]
            if item["state"] == "active"
        }
        candidate_ids = {
            item["id"]
            for category in mapped["categories"]
            for item in category["specialties"]
        }
        self.assertEqual(mapped_active, active_ids & candidate_ids)
        self.assertEqual(
            set(mapped["framework_only_active"]), active_ids - candidate_ids
        )
        self.assertEqual(mapped["candidate_count"], len(candidate_ids))
        self.assertEqual(mapped["active_candidate_count"], len(mapped_active))
        self.assertEqual(
            mapped["deferred_candidate_count"], len(candidate_ids - mapped_active)
        )


